export const dtbtSentences: Sentence[] = [
  {"id":"s_work_dtbt_1_1","chapterId":"ch_work_dtbt_1","text":"出版說明","sortOrder":1},
  {"id":"s_work_dtbt_1_2","chapterId":"ch_work_dtbt_1","text":"《容齋隨筆》，南宋洪邁(一一二三──一二０二)著，分《隨筆》、《續筆》、《三筆》、《四筆》、《五筆》，共五集七十四卷。","sortOrder":2},
  {"id":"s_work_dtbt_1_3","chapterId":"ch_work_dtbt_1","text":"洪邁字景盧，別號野處，鄱陽(今江西波陽)人。在地方作過知州，在朝廷歷任起居郎、中書舍人兼侍讀、直學士院等官職，監修過國史，最後官至端明殿學士。他一生涉獵書籍頗多，凡有所得，便隨筆記之，前後近四十年，乃成《容齋隨筆》五集。原計劃每集各分十六卷，但書未成即死，故《五筆》僅十卷。","sortOrder":3},
  {"id":"s_work_dtbt_1_4","chapterId":"ch_work_dtbt_1","text":"《容齋隨筆》是關於歷史、文學、哲學、藝術等方面的筆記。書中考證了宋以前的一些歷史史實、政治經濟製度；記述了不少詞章典故；對於宋代的典章製度記述尤詳；有較大的參考價值。對於某些歷史人物和歷史事件，也間加評論。但由於洪邁所處的時代和階級的局限，因而對歷史人物和歷史事件不可能作出恰當的評價，均有待於分析和批判。","sortOrder":4},
  {"id":"s_work_dtbt_1_5","chapterId":"ch_work_dtbt_1","text":"現據清光緒元年重校同治年間洪氏刊本標點出版，供讀者研究參考。","sortOrder":5},
  {"id":"s_work_dtbt_1_6","chapterId":"ch_work_dtbt_1","text":"本書是由上海師範大學古籍整理組校點整理的。","sortOrder":6},
  {"id":"s_work_dtbt_1_7","chapterId":"ch_work_dtbt_1","text":"上海古籍出版社　一九七八年一月","sortOrder":7},
  {"id":"s_work_dtbt_2_1","chapterId":"ch_work_dtbt_2","text":"容齋隨筆提要","sortOrder":1},
  {"id":"s_work_dtbt_2_2","chapterId":"ch_work_dtbt_2","text":"(紀昀)","sortOrder":2},
  {"id":"s_work_dtbt_2_3","chapterId":"ch_work_dtbt_2","text":"宋鄱陽洪邁撰。凡十六卷，續筆、三筆、四筆，卷數亦如此。五筆未脫稿而歿，故僅十卷。自序稱作一筆，首尾十八年。四筆不費一年，遲速何若是之懸殊也。書中自經史諸子百家，以及醫卜星算之屬，靡不引證詳洽。雖晚年撰夷堅志，於是書不甚措意，未免利鈍互形。然大致則辯析精審。於宋代掌故，尤為嫻熟，非徒事掎摭者比，昔人謂南宋說部，當以此為首屈。知言哉。（此則錄於中國世界語出版社1995年第1版－－發文者註）","sortOrder":3},
  {"id":"s_work_dtbt_2_4","chapterId":"ch_work_dtbt_2","text":"容齋隨筆總序","sortOrder":4},
  {"id":"s_work_dtbt_2_5","chapterId":"ch_work_dtbt_2","text":"知贛州寺簿洪公伋，以書來曰：「從祖文敏公由右史出守是邦，今四十餘年矣。伋何幸遠繼其後，官閑無事，取文敏隨筆紀錄，自一至四各十六卷，五則絕筆之書，僅有十卷，悉鋟木於郡齋，用以示邦人焉。想像抵掌風流，宛然如在，公其為我識之。」","sortOrder":5},
  {"id":"s_work_dtbt_2_6","chapterId":"ch_work_dtbt_2","text":"僕頃備數憲幕，留贛二年，至之日，文敏去才旬月，不及識也。而經行之地，筆墨飛動，人誦其書，家有其像，平易近民之政，悉能言之。有訴不平者，如訴之於其父，而謁其所欲者，如謁之於其母。後十五年，文敏為翰苑，出鎮浙東，僕適後至，濫叨朝列，相隔又旬月，竟不及識。而與其子太社木莘，其孫參軍偃，相從甚久，得其文愈多，而所謂隨筆者，僅見一二，今所有太半出於浙東歸休之後，宜其不盡見也。可以稽典故，可以廣聞見，可以證訛謬，可以膏筆端，實為儒生進學之地，何止慰贛人去後之思。僕又嘗於陳日華曄，盡得夷堅十志與支志、三志及四志之二，共三百二十卷，就摘其間詩詞、雜著、藥餌、符呪之屬，以類相從，編刻於湖陰之計臺，疏為十卷，覽者便之。僕因此搜索志中，欲取其不涉神怪，近於人事，資鑒戒而佐辯博，非夷堅所宜收者，別為一書，亦可得十卷。俟其成也，規以附刻於章貢可乎？","sortOrder":6},
  {"id":"s_work_dtbt_2_7","chapterId":"ch_work_dtbt_2","text":"寺簿方以課最就持憲節，威行溪洞，折其萌芽，民實陰受其賜。願少留於此，他日有餘力，則經紀文敏之家，子孫未振，家集大全，恐馴致散失，再為收拾實難。今盤洲、小隱二集，士夫珍藏墨本已久，獨野處未焉，寺簿推廣隨筆之用心，願有以亟圖之可也。嘉定壬申仲冬初吉，寶謨閣直學士、太中大夫、提舉隆興府玉隆萬壽宮臨川何異謹序。","sortOrder":7},
  {"id":"s_work_dtbt_2_8","chapterId":"ch_work_dtbt_2","text":"容齋隨筆舊序","sortOrder":8},
  {"id":"s_work_dtbt_2_9","chapterId":"ch_work_dtbt_2","text":"書必符乎名教，君子有所取，而讀者要非無益之言也。夫天下之事，萬有不齊，而可以憑藉者理之正，事不一而理有定在，猶百川萬折，必歸於海。否則涉於荒唐繆悠，絕類離索，以盲聵人之耳目者，在所不取。古今馳聲於墨札之場者，噓英吐華，爭相著作，浩渺連艫，策氏籍名，不可紀極，嗜博者亦必珍如拱璧，而把玩之不輟焉。","sortOrder":9},
  {"id":"s_work_dtbt_2_10","chapterId":"ch_work_dtbt_2","text":"文敏公洪景盧，博洽通儒，為宋學士。出鎮浙東，歸自越府，謝絕外事，聚天下之書而遍閱之。搜悉異聞，考核經史，捃拾典故，值言之最者必札之，遇事之奇者必摘之，雖詩詞、文翰、曆讖、卜醫，鉤纂不遺，從而評之。參訂品藻，論議雌黃，或加以辯證，或繫以讚繇，天下事為，寓以正理，殆將畢載。積廿餘年，率皆成書，名曰隨筆，謙言順筆錄之雲爾。加以續筆、三筆、四筆，絕於五筆，莫非隨之之意，總若幹萬言。比所作夷堅志、支志、盤洲集，踔有正趣。可勸可戒，可喜可愕，可以廣見聞，可以證訛謬，可以祛疑貳，其於世教未嘗無所裨補。","sortOrder":10},
  {"id":"s_work_dtbt_2_11","chapterId":"ch_work_dtbt_2","text":"予得而覽之，大豁襟抱，洞歸正理，如躋明堂，而胸中樓閣四通八達也。惜乎傳之未廣，不得人挾而家置。因命紋梓，播之方輿，以弘博雅之君子，而凡志於格物致知者，資之亦可以窮天下之理雲。弘治戊午冬十月既望，巡按河南監察御史沁水李瀚書。","sortOrder":11},
  {"id":"s_work_dtbt_2_12","chapterId":"ch_work_dtbt_2","text":"重刻容齋隨筆紀事一","sortOrder":12},
  {"id":"s_work_dtbt_2_13","chapterId":"ch_work_dtbt_2","text":"元調少時就童子試於松江，郡將堂邑許公，通經學古人也。一語意合，或旬日再三召，恆坐列肆中，以待門啟而入。有鬻容齋隨筆者，取閱一二，則喜其聞所未聞，千錢易之。然猶未悉容齋之為何等人，隨筆之為何等書也。歸以告本師子柔先生，先生曰：「此宋文敏洪公之所著書，其考據精確，議論高簡，讀書作文之法盡是矣。」又曰：「吾向從丘子成先生見此書而不全，汝亟取以來，吾將卒業焉。」又曰：「考據議論之書，莫備於兩宋，然北則三劉、沈括，南則文敏兄弟，歐、曾輩似不及也。」元調謹受教，日夕浸灌其中，行李往來，未嘗不挾與之俱。","sortOrder":13},
  {"id":"s_work_dtbt_2_14","chapterId":"ch_work_dtbt_2","text":"壬子秋，寓長幹報恩僧舍，得略識一時知名士，每集必數十人，論及古今成敗及文章得失，忿爭不決者，元調輒片言以解，此書之助為多。間以示玉繩周子，讀之盡卷，惘然曰：「古人學問如是，吾儕窮措大，縱欲留意，顧安所得書，又安所得暇日乎？雖然，吾來年將館丹陽荊氏，君遊蹤務相近，頗載所藏書借我。」已而周子入翰林為修撰，寄語：「子今不患無書可讀矣。」周子謝不敏，報書：「吾則未暇，留以待子。」蓋戲之也。自後讀隨筆漸熟，又推其意以漸讀他書，如執權度稱量萬物，爽者鮮矣。每逢同儕，必勸令讀是書，而傳本甚少，慨然欲重梓以公同好。","sortOrder":14},
  {"id":"s_work_dtbt_2_15","chapterId":"ch_work_dtbt_2","text":"去年春，明府勾章謝公刻子柔先生等集，工匠稿不應手，屢欲散去。元調實董較勘，始謀翻刻，以寓羈縻。而所蓄本未免舛訛，適丘子成先生家鬻舊書，得向不全本，考其序，乃弘治中沁水侍御李公瀚所刻。又從友人沈子誨借得殘落數卷，會之良合。然舛訛較所蓄本尤多，參伍是正，為改定千餘字，仍闕其疑，明府公遂為之序，復紀其重刻之故，以告我後人。","sortOrder":15},
  {"id":"s_work_dtbt_2_16","chapterId":"ch_work_dtbt_2","text":"嗟乎！二十年之間，曩時相與讀是書者，遭逢聖明，當古平章軍國之任，元調獨窮老不遇，啜粥飲水，優遊江海之濱，聊以整頓舊書為樂事，曾不得信其舌而奮其筆，何託落之甚也。上有稷、卨，下有巢、由，道並行而不相悖，均之為太平之象，亦各言其志也已矣。崇禎三年三月朔，嘉定馬元調書於僦居之紙窗竹屋。","sortOrder":16},
  {"id":"s_work_dtbt_2_17","chapterId":"ch_work_dtbt_2","text":"重刻容齋隨筆紀事二","sortOrder":17},
  {"id":"s_work_dtbt_2_18","chapterId":"ch_work_dtbt_2","text":"先文敏公容齋先生隨筆一書，與沈存中夢溪筆談、王伯厚困學紀聞等，後先並重於世。其書自經史典故、諸子百家之言，以及詩詞文翰、醫卜星曆之類，無不紀載，而多所辨證。昔人嘗稱其考據精確，議論高簡，如執權度而稱量萬物，不差累黍，歐、曾之徒所不及也。","sortOrder":18},
  {"id":"s_work_dtbt_2_19","chapterId":"ch_work_dtbt_2","text":"考公自浙東致政歸田里後，自謂老懶讀書不多，凡意有得，隨筆志之，初成十六卷，又續筆以至三筆、四筆、五筆共七十四卷。宋嘉定中，公從孫寺簿伋，鋟木於章貢郡齋。明宏治中，沁水御史李公瀚，又嘗序而梓之。其嘉惠來學，為讀書稽古之益者，豈為少哉！吾家舊有此書，乃嘉定婁先生子柔，俾其門人馬巽甫氏刻而行世者。又嘗補其殘缺，訂其舛訛，流傳於今，亦已七十餘年矣。從子天爵，自疁邑得此版而歸於璟，其有闕失者，一一補正完好，重為披讀，如獲重器焉，然愧學殖荒落，不能發明其萬一。而公之沾丐後人者，已歷五百年所，又世為家藏之舊，用以公諸天下博雅嗜古之儒，未必不如瑚璉、簠簋三代法物，登之宗廟，可以觀禮，與他玩好者殊異也。公父子兄弟，忠孝大節，炳在宋史，人皆知之。","sortOrder":19},
  {"id":"s_work_dtbt_2_20","chapterId":"ch_work_dtbt_2","text":"又公所著有文集、唐人萬首絕句、夷堅志等書，其題跋一種，今刻於津逮祕書中，又巽甫刻有夢溪筆談，與是書如合璧然，皆天下之公物也。璟喜是書之歸，而有光復舊物之意，因志其本末如此雲。康熙三十九年春三月，族孫璟謹書。","sortOrder":20},
  {"id":"s_work_dtbt_3_1","chapterId":"ch_work_dtbt_3","text":"卷第一(二十九則)","sortOrder":1},
  {"id":"s_work_dtbt_3_2","chapterId":"ch_work_dtbt_3","text":"予老去習懶，讀書不多，意之所之，隨即紀錄，因其後先，無復詮次，故目之曰隨筆。淳熙庚子，鄱陽洪邁景盧。","sortOrder":2},
  {"id":"s_work_dtbt_3_3","chapterId":"ch_work_dtbt_3","text":"歐率更帖","sortOrder":3},
  {"id":"s_work_dtbt_3_4","chapterId":"ch_work_dtbt_3","text":"臨川石刻雜法帖一卷，載歐陽率更一帖雲：「年二十餘，至鄱陽，地沃土平，飲食豐賤，衆士往往湊聚。每日賞華，恣口所須。其二張才華議論，一時俊傑；殷、薛二侯，故不可言；戴君國士，出言便是月旦；蕭中郎頗縱放誕，亦有雅致；彭君摛藻，特有自然，至如閣山神詩，先輩亦不能加。此數子遂無一在，殊使痛心。」茲蓋吾鄉故實也。","sortOrder":4},
  {"id":"s_work_dtbt_3_5","chapterId":"ch_work_dtbt_3","text":"羅處士志","sortOrder":5},
  {"id":"s_work_dtbt_3_6","chapterId":"ch_work_dtbt_3","text":"襄陽有隋處士羅君墓誌曰：「君諱靖，字禮，襄陽廣昌人。高祖長卿，齊饒州刺史。曾祖弘智，梁殿中將軍。祖養，父靖，學優不仕，有名當代。」碑字畫勁楷，類褚河南，然父子皆名靖，為不可曉。拓拔魏安同父名屈，同之長子亦名屈，祖孫同名，胡人無足言者，但羅君不應爾也。","sortOrder":6},
  {"id":"s_work_dtbt_3_7","chapterId":"ch_work_dtbt_3","text":"唐平蠻碑","sortOrder":7},
  {"id":"s_work_dtbt_3_8","chapterId":"ch_work_dtbt_3","text":"成都有唐平南蠻碑，開元十九年，劍南節度副大使張敬忠所立。時南蠻大酋長染浪州刺史楊盛顛為邊患，明皇遣內常侍高守信為南道招慰處置使以討之，拔其九城。此事新、舊唐書及野史皆不載。肅宗以魚朝恩為觀軍容處置使，憲宗用吐突承璀為招討使，議者譏其以中人主兵柄，不知明皇用守信蓋有以啟之也。裴光庭、蕭嵩時為相，無足責者。楊氏苗裔，至今猶連「晟」字雲。","sortOrder":8},
  {"id":"s_work_dtbt_3_9","chapterId":"ch_work_dtbt_3","text":"半擇迦","sortOrder":9},
  {"id":"s_work_dtbt_3_10","chapterId":"ch_work_dtbt_3","text":"大般若經雲：梵言「扇搋半擇迦」，唐言黃門，其類有五：一曰半擇迦，總名也，有男根用而不生子；二曰伊利沙半擇迦，此雲妬，謂他行欲即發，不見即無，亦具男根而不生子；三曰扇搋半擇迦，謂本來男根不滿，亦不能生子；四曰博義半擇迦，謂半月能男半月不能男；五曰留拏半擇迦，此雲割，謂被割刑者。此五種黃門，名為人中惡趣受身處。搋音丑皆反。(「博義」，館本作「搏義」。)","sortOrder":10},
  {"id":"s_work_dtbt_3_11","chapterId":"ch_work_dtbt_3","text":"六十四種惡口","sortOrder":11},
  {"id":"s_work_dtbt_3_12","chapterId":"ch_work_dtbt_3","text":"大集經載六十四種惡口之業，曰：麤語，軟語，非時語，妄語，漏語，大語，高語，輕語，破語，不了語，散語，低語，仰語，錯語，惡語，畏語，吃語，諍語，語，誑語，惱語，怯語，邪語，罪語，啞語，入語，燒語，地語，獄語，虛語，慢語，不愛語，說罪咎語，失語，別離語，利害語，兩舌語，無義語，無護語，喜語，狂語，殺語，害語，繫語，閑語，縛語，打語，歌語，非法語，自讚嘆語，說他過語，說三寶語。","sortOrder":12},
  {"id":"s_work_dtbt_3_13","chapterId":"ch_work_dtbt_3","text":"八月端午","sortOrder":13},
  {"id":"s_work_dtbt_3_14","chapterId":"ch_work_dtbt_3","text":"唐玄宗以八月五日生，以其日為千秋節。張說上大衍曆序雲：「謹以開元十六年八月端午赤光照室之夜獻之。」唐類表有宋璟請以八月五日為千秋節表雲：「月惟仲秋，日在端午。」然則凡月之五日皆可稱端午也。","sortOrder":14},
  {"id":"s_work_dtbt_3_15","chapterId":"ch_work_dtbt_3","text":"贊公少公","sortOrder":15},
  {"id":"s_work_dtbt_3_16","chapterId":"ch_work_dtbt_3","text":"唐人呼縣令為明府，丞為贊府，尉為少府。李太白集有餞陽曲王贊公賈少公石艾尹少公序。蓋陽曲丞、尉，石艾尉也，「贊公」、「少公」之語益奇。","sortOrder":16},
  {"id":"s_work_dtbt_3_17","chapterId":"ch_work_dtbt_3","text":"郭璞葬地","sortOrder":17},
  {"id":"s_work_dtbt_3_18","chapterId":"ch_work_dtbt_3","text":"世說：「郭景純過江，居於暨陽。墓去水不盈百步，時人以為近水，景純曰：『將當為陸。』今沙漲，去墓數十里皆為桑田。」此說蓋以郭為先知也。世傳錦囊葬經為郭所著，行山卜宅兆者印為元龜。然郭能知水之為陸，獨不能卜吉以免其非命乎？廁上銜刀之見淺矣。","sortOrder":18},
  {"id":"s_work_dtbt_3_19","chapterId":"ch_work_dtbt_3","text":"黃魯直詩","sortOrder":19},
  {"id":"s_work_dtbt_3_20","chapterId":"ch_work_dtbt_3","text":"徐陵鴛鴦賦雲：「山鷄映水那相得，孤鸞照鏡不成雙。天下真成長會合，無勝比翼兩鴛鴦。」黃魯直題畫睡鴨曰：「山鷄照影空自愛，孤鸞舞鏡不作雙。天下真成長會合，兩鳧相倚睡秋江。」全用徐語點化之，末句尤精工。又有黔南十絕，盡取白樂天語，其七篇全用之，其三篇頗有改易處。樂天寄行簡詩，凡八韻，後四韻雲：「相去六千里，地絕天邈然。十書九不達，何以開憂顏！渴人多夢飲，饑人多夢餐。春來夢何處？合眼到東川。」魯直翦為兩首，其一雲：「相望六千里，天地隔江山。十書九不到，何用一開顏？」其二雲：「病人多夢醫，囚人多夢赦。如何春來夢，合眼在鄉社！」樂天歲晚詩七韻，首句雲：「霜降水返壑，風落木歸山。冉冉歲將晏，物皆復本源。」魯直改後兩句七字，作「冉冉歲華晚，崑蟲皆閉關」。","sortOrder":20},
  {"id":"s_work_dtbt_3_21","chapterId":"ch_work_dtbt_3","text":"禹治水","sortOrder":21},
  {"id":"s_work_dtbt_3_22","chapterId":"ch_work_dtbt_3","text":"禹貢敍治水，以冀、兗、青、徐、揚、荊、豫、梁、雍為次。考地理言之，豫居九州中，與兗、徐接境，何為自徐之揚，顧以豫為後乎？蓋禹順五行而治之耳。冀為帝都，既在所先，而地居北方，實於五行為水，水生木，木東方也，故次之以兗、青、徐；木生火，火南方也，故次之以揚、荊；火生土，土中央也，故次之以豫；土生金，金西方也，故終於梁、雍。所謂彝倫攸敍者此也。與鯀之汨陳五行，相去遠矣。此說予得之魏幾道。","sortOrder":22},
  {"id":"s_work_dtbt_3_23","chapterId":"ch_work_dtbt_3","text":"敕勒歌","sortOrder":23},
  {"id":"s_work_dtbt_3_24","chapterId":"ch_work_dtbt_3","text":"魯直題陽關圖詩雲：「想得陽關更西路，北風低草見牛羊。」又集中有書韋深道諸帖雲：「斛律明月，胡兒也，不以文章顯，老胡以重兵困敕勒川，召明月作歌以排悶。倉卒之間，語奇壯如此，蓋率意道事實耳。」予按古樂府有敕勒歌，以為齊高歡攻周玉壁而敗，恚憤疾發，使斛律金唱敕勒，歡自和之。其歌本鮮卑語，詞曰：「敕勒川，陰山下，天似穹廬，籠罩四野。天蒼蒼，野茫茫，風吹草低見牛羊。」魯直所題及詩中所用，蓋此也。但誤以斛律金為明月，明月名光，金之子也。歡敗於玉壁，亦非困於敕勒川。","sortOrder":24},
  {"id":"s_work_dtbt_3_25","chapterId":"ch_work_dtbt_3","text":"淺妄書","sortOrder":25},
  {"id":"s_work_dtbt_3_26","chapterId":"ch_work_dtbt_3","text":"俗間所傳淺妄之書，如所謂雲仙散錄、老杜事實、開元天寶遺事之屬，皆絕可笑。然士大夫或信之，至以老杜事實為東坡所作者，今蜀本刻杜集，遂以入註。孔傳續六帖，采摭唐事殊有功，而悉載雲仙錄中事，自穢其書。開天遺事託雲王仁裕所著，仁裕五代時人，雖文章乏氣骨，恐不至此。姑析其數端以為笑。其一雲：「姚元崇開元初作翰林學士，有步輦之召。」按，元崇自武後時已為宰相，及開元初三入輔矣。其二雲：「郭元振少時美風姿，宰相張嘉貞欲納為婿，遂牽紅絲綫，得第三女，果隨夫貴達。」按，元振為睿宗宰相，明皇初年即貶死，後十年，嘉貞方作相。其三雲：「楊國忠盛時，朝之文武，爭附之以求富貴，惟張九齡未嘗及門。」按，九齡去相位十年，國忠方得官耳。其四雲：「張九齡覽蘇頲文卷，謂為文陣之雄師。」按，頲為相時，九齡元未達也。此皆顯顯可言者，固鄙淺不足攻，然頗能疑誤後生也。惟張彖指楊國忠為冰山事，資治通鑑亦取之，不知別有何據？近歲，興化軍學刊遺事，南劍州學刊散錄，皆可毀。","sortOrder":26},
  {"id":"s_work_dtbt_3_27","chapterId":"ch_work_dtbt_3","text":"五臣註文選","sortOrder":27},
  {"id":"s_work_dtbt_3_28","chapterId":"ch_work_dtbt_3","text":"東坡詆五臣註文選，以為荒陋。予觀選中謝玄暉和王融詩雲：「阽危賴宗袞，微管寄明牧。」正謂謝安、謝玄。安石於玄暉為遠祖，以其為相，故曰宗袞。而李周翰註雲：「宗袞謂王導，導與融同宗，言晉國臨危，賴王導而破苻堅。牧謂謝玄，亦同破堅者。」夫以宗袞為王導固可笑，然猶以和王融之故，微為有說，至以導為與謝玄同破苻堅，乃是全不知有史策，而狂妄註書，所謂小兒強解事也。唯李善註得之。","sortOrder":28},
  {"id":"s_work_dtbt_3_29","chapterId":"ch_work_dtbt_3","text":"文煩簡有當","sortOrder":29},
  {"id":"s_work_dtbt_3_30","chapterId":"ch_work_dtbt_3","text":"歐陽公進新唐書表曰：「其事則增於前，其文則省於舊。」夫文貴於達而已，繁與省各有當也。史記衞青傳：「校尉李朔、校尉趙不虞、校尉公孫戎奴，各三從大將軍獲王，以千三百戶封朔為涉軹侯，以千三百戶封不虞為隨成侯，以千三百戶封戎奴為從平侯。」前漢書但雲：「校尉李朔、趙不虞、公孫戎奴，各三從大將軍，封朔為涉軹侯、不虞為隨成侯、戎奴為從平侯。」比於史記五十八字中省二十三字，然不若史記為朴贍可喜。","sortOrder":30},
  {"id":"s_work_dtbt_3_31","chapterId":"ch_work_dtbt_3","text":"地險","sortOrder":31},
  {"id":"s_work_dtbt_3_32","chapterId":"ch_work_dtbt_3","text":"古今言地險者，以謂函秦宅關、河之勝，齊負海、岱，趙、魏據大河，晉表裏河山，蜀有劍門、瞿唐之阻，楚國方城以為城，漢水以為池，吳長江萬里，兼五湖之固，皆足以立國。唯宋、衞之郊，四通五達，無一險可恃。然東漢之末，袁紹跨有青、冀、幽、幷四州，韓遂、馬騰輩分據關中，劉璋擅蜀，劉表居荊州，呂布盜徐，袁術包南陽、壽春，孫策取江東，天下形勝盡矣。曹操晚得兗州，倔強其間，終之夷羣雄，覆漢祚。議者尚以為操挾天子以自重，故能成功。而唐僖、昭之時，方鎮擅地，王氏有趙百年，羅洪信在魏，劉仁恭在燕，李克用在河東，王重榮在蒲，朱宣、朱瑾在兗、鄆，時溥在徐，王敬武在淄、青，楊行密在淮南，王建在蜀，天子都長安，鳳翔、邠、華三鎮鼎立為梗，李茂貞、韓建皆嘗刧遷乘輿。而朱溫區區以汴、宋、亳、潁嶻然中居，及其得志，乃與操等。以在德不在險為言，則操、溫之德又可見矣。","sortOrder":32},
  {"id":"s_work_dtbt_3_33","chapterId":"ch_work_dtbt_3","text":"史記世次","sortOrder":33},
  {"id":"s_work_dtbt_3_34","chapterId":"ch_work_dtbt_3","text":"史記所紀帝王世次，最為不可考信，且以稷、契論之，二人皆帝嚳子，同仕於唐虞。契之後為商，自契至成湯凡十三世，歷五百餘年。稷之後為周，自稷至武王凡十五世，歷千一百餘年。王季蓋與湯為兄弟，而世之相去六百年，既已可疑。則周之先十五世，須每世皆在位七八十年，又皆暮年所生嗣君，乃合此數，則其所享壽皆當過百年乃可。其為漫誕不稽，無足疑者。國語所載太子晉之言曰：「自後稷之始基靖民，十五王而文始平之。」皆不然也。","sortOrder":34},
  {"id":"s_work_dtbt_3_35","chapterId":"ch_work_dtbt_3","text":"解釋經旨","sortOrder":35},
  {"id":"s_work_dtbt_3_36","chapterId":"ch_work_dtbt_3","text":"解釋經旨，貴於簡明，惟孟子獨然。其稱公劉之詩：「乃積乃倉，乃裹餱糧，於槖於囊，思戢用光，弓矢斯張，幹戈戚揚，爰方啟行。」而釋之之詞，但雲：「故居者有積倉，行者有裹糧也，然後可以爰方啟行。」其稱烝民之詩：「天生烝民，有物有則，民之秉夷，好是懿德。」而引孔子之語以釋之，但曰：「故有物必有則，民之秉夷也，故好是懿德。」用兩故字，一必字，一也字，而四句之義昭然。彼訓「曰若稽古」三萬言，真可覆醬瓿也。","sortOrder":36},
  {"id":"s_work_dtbt_3_37","chapterId":"ch_work_dtbt_3","text":"坤動也剛","sortOrder":37},
  {"id":"s_work_dtbt_3_38","chapterId":"ch_work_dtbt_3","text":"坤卦文言曰：「坤至柔而動也剛。」王弼雲：「動之方正，不為邪也。」程伊川雲：「坤道至柔，而其動則剛，動剛故應乾不違。」張橫渠雲：「柔亦有剛，靜亦有動，但舉一體，則有屈伸動靜終始。」又雲：「積大勢成而然。」東坡雲：「夫物非剛者能剛，惟柔者能剛爾。畜而不發，及其極也，發之必決。」張葆光但以訓六二之直。陳了翁雲：「至柔至靜，坤之至也。剛者道之動，方者靜之德，柔剛靜動，坤元之道之德也。」郭雍雲：「坤雖以柔靜為主，苟無方剛之德，不足以含洪光大。」諸家之說，率不外此。予頃見臨安退居庵僧曇瑩雲：「動者謂爻之變也，坤不動則已，動則陽剛見焉。在初為復，在二為師，在三為謙，自是以往皆剛也。」其說最為分明有理。","sortOrder":38},
  {"id":"s_work_dtbt_3_39","chapterId":"ch_work_dtbt_3","text":"樂天侍兒","sortOrder":39},
  {"id":"s_work_dtbt_3_40","chapterId":"ch_work_dtbt_3","text":"世言白樂天侍兒唯小蠻、樊素二人。予讀集中小庭亦有月一篇雲：「菱角執笙簧，穀兒抹琵琶，紅綃信手舞，紫綃隨意歌。」自註曰：「菱、穀、紫、紅皆小臧獲名。」若然，則紅、紫二綃亦女奴也。","sortOrder":40},
  {"id":"s_work_dtbt_3_41","chapterId":"ch_work_dtbt_3","text":"白公詠史","sortOrder":41},
  {"id":"s_work_dtbt_3_42","chapterId":"ch_work_dtbt_3","text":"東坡志林雲：「白樂天嘗為王涯所讒，貶江州司馬。甘露之禍，樂天有詩雲：『當君白首同歸日，是我青山獨往時。』不知者以樂天為幸之，樂天豈幸人之禍者哉？蓋悲之也。」予讀白集有詠史一篇，註雲：九年十一月作。其詞曰：「秦磨利刃斬李斯，齊燒沸鼎烹酈其，可憐黃綺入商洛，閒臥白雲歌紫芝，彼為葅醢機上盡，此作鸞凰天外飛，去者逍遙來者死，乃知禍福非天為。」正為甘露事而作，其悲之之意可見矣。","sortOrder":42},
  {"id":"s_work_dtbt_3_43","chapterId":"ch_work_dtbt_3","text":"十年為一秩","sortOrder":43},
  {"id":"s_work_dtbt_3_44","chapterId":"ch_work_dtbt_3","text":"白公詩雲：「已開第七秩，飽食仍安眠。」又雲：「年開第七秩，屈指幾多人。」是時年六十二，元日詩也。又一篇雲：「行開第八秩，可謂盡天年。」註曰：「時俗謂七十以上為開第八秩。」蓋以十年為一秩雲。司馬溫公作慶文潞公八十會致語雲「歲曆行開九帙新」，亦用此也。","sortOrder":44},
  {"id":"s_work_dtbt_3_45","chapterId":"ch_work_dtbt_3","text":"裴晉公禊事","sortOrder":45},
  {"id":"s_work_dtbt_3_46","chapterId":"ch_work_dtbt_3","text":"唐開成二年三月三日，河南尹李待價將禊於洛濱，前一日啟留守裴令公。公明日召太子少傅白居易，太子賓客蕭籍、李仍叔、劉禹錫，中書舍人鄭居中等十五人合宴於舟中，自晨及暮，前水嬉而後妓樂，左筆硯而右壺觴，望之若仙，觀者如堵。裴公首賦一章，四坐繼和，樂天為十二韻以獻，見於集中。今人賦上巳，鮮有用其事者。予按裴公傳，是年起節度河東，三年以病丐還東都。文宗上巳宴羣臣曲江，度不赴，帝賜以詩，使者及門而度薨。與前事相去正一年。然樂天又有一篇，題雲奉和裴令公三月上巳日遊太原龍泉憶去歲禊洛之作，是開成三年詩，則度以四年三月始薨。新史以為三年，誤也。宰相表却載其三年十二月為中書令，四年三月薨。而帝紀全失書，獨舊史紀、傳為是。","sortOrder":46},
  {"id":"s_work_dtbt_3_47","chapterId":"ch_work_dtbt_3","text":"司字作入聲","sortOrder":47},
  {"id":"s_work_dtbt_3_48","chapterId":"ch_work_dtbt_3","text":"白樂天詩，好以司字作入聲讀，如雲：「四十著緋軍司馬，男兒官職未蹉跎」，「一為州司馬，三見歲重陽」，是也。又以相字作入聲，如雲：「為問長安月，誰教不相離」，是也。相字之下自註雲：思必切。以十字作平聲讀，如雲：「在郡六百日，入山十二回」，「綠浪東西南北路，紅欄三百九十橋」，是也。以琵字作入聲讀，如雲：「四絃不似琵琶聲，亂寫真珠細撼鈴」，「忽聞水上琵琶聲」，是也。武元衡亦有句雲：「唯有白鬚張司馬，不言名利尚相從。」","sortOrder":48},
  {"id":"s_work_dtbt_3_49","chapterId":"ch_work_dtbt_3","text":"樂天新居詩","sortOrder":49},
  {"id":"s_work_dtbt_3_50","chapterId":"ch_work_dtbt_3","text":"白樂天自杭州刺史分司東都，有題新居呈王尹兼簡府中三掾詩雲：「弊宅須重葺，貧家乏羨財，橋憑州守造，樹倩府寮栽，朱板新猶濕，紅英暖漸開，仍期更攜酒，倚檻看花來。」乃知唐世風俗尚為可喜。今人居閒，而郡守為之造橋，府寮為之栽樹，必遭譏議，又肯形之篇詠哉！","sortOrder":50},
  {"id":"s_work_dtbt_3_51","chapterId":"ch_work_dtbt_3","text":"黃紙除書","sortOrder":51},
  {"id":"s_work_dtbt_3_52","chapterId":"ch_work_dtbt_3","text":"樂天好用「黃紙除書」字，如：「紅旗破賊非吾事，黃紙除書無我名」，「正聽山鳥向陽眠，黃紙除書落枕前」，「黃紙除書到，青宮詔命催」。","sortOrder":52},
  {"id":"s_work_dtbt_3_53","chapterId":"ch_work_dtbt_3","text":"白用杜句","sortOrder":53},
  {"id":"s_work_dtbt_3_54","chapterId":"ch_work_dtbt_3","text":"杜子美詩雲：「夜足霑沙雨，春多逆水風。」白樂天詩「巫山暮足霑花雨，隴水春多逆浪風」，全用之。","sortOrder":54},
  {"id":"s_work_dtbt_3_55","chapterId":"ch_work_dtbt_3","text":"唐人重服章","sortOrder":55},
  {"id":"s_work_dtbt_3_56","chapterId":"ch_work_dtbt_3","text":"唐人重服章，故杜子美有「銀章付老翁」，「朱紱負平生」，「扶病垂朱紱」之句。白樂天詩言銀緋處最多，七言如：「大抵著緋宜老大」，「一片緋衫何足道」，「暗淡緋衫稱我身」，「酒典緋花舊賜袍」，「假著緋袍君莫笑」，「腰間紅綬繫未穩」，「朱紱仙郎白雪歌」，「腰佩銀龜朱兩輪」，「便留朱紱還鈴閤」，「映我緋衫渾不見」，「白頭俱未著緋衫」，「緋袍著了好歸田」，「銀魚金帶繞腰光」，「銀章蹔假為專城」，「新授銅符未著緋」，「徒使花袍紅似火」，「似掛緋袍衣架上」。五言如：「未換銀青綬，唯添雪白鬚」，「笑我青袍故，饒君茜綬新」，「老逼教垂白，官科遣著緋」，「那知垂白日，始是著緋年」，「晚遇何足言，白髮映朱紱」。至於形容衣魚之句，如：「魚綴白金隨步躍，鵠銜紅綬繞身飛。」","sortOrder":56},
  {"id":"s_work_dtbt_3_57","chapterId":"ch_work_dtbt_3","text":"詩讖不然","sortOrder":57},
  {"id":"s_work_dtbt_3_58","chapterId":"ch_work_dtbt_3","text":"今人富貴中作不如意語，少壯時作衰病語，詩家往往以為讖。白公十八歲，病中作絕句雲：「久為勞生事，不學攝生道，少年已多病，此身豈堪老？」然白公壽七十五。","sortOrder":58},
  {"id":"s_work_dtbt_3_59","chapterId":"ch_work_dtbt_3","text":"青龍寺詩","sortOrder":59},
  {"id":"s_work_dtbt_3_60","chapterId":"ch_work_dtbt_3","text":"樂天和錢員外青龍寺上方望舊山詩雲：「舊峯松雪舊溪雲，悵望今朝遙屬君，共道使臣非俗吏，南山莫動北山文。」頃於乾道四年講筵開日，蒙上書此章於扇以賜，改「使臣」為「侍臣」雲。","sortOrder":60},
  {"id":"s_work_dtbt_3_61","chapterId":"ch_work_dtbt_3","text":"容齋隨筆","sortOrder":61},
  {"id":"s_work_dtbt_4_1","chapterId":"ch_work_dtbt_4","text":"卷第二(二十四則)","sortOrder":1},
  {"id":"s_work_dtbt_4_2","chapterId":"ch_work_dtbt_4","text":"唐重牡丹","sortOrder":2},
  {"id":"s_work_dtbt_4_3","chapterId":"ch_work_dtbt_4","text":"歐陽公牡丹釋名雲：「牡丹初不載文字，唐人如沈、宋、元、白之流，皆善詠花，當時有一花之異者，彼必形於篇什，而寂無傳焉，唯劉夢得有詠魚朝恩宅牡丹詩，但雲一叢千朵而已，亦不雲其美且異也。」予按，白公集有白牡丹一篇十四韻，又秦中吟十篇，內買花一章，凡百言，雲：「共道牡丹時，相隨買花去。一叢深色花，十戶中人賦。」而諷諭樂府有牡丹芳一篇，三百四十七字，絕道花之妖豔，至有「遂使王公與卿士，遊花冠蓋日相望」，「花開花落二十日，一城之人皆若狂」之語。又寄微之百韻詩雲：「唐昌玉蕊會，崇敬牡丹期。」註：「崇敬寺牡丹花，多與微之有期。」又惜牡丹詩雲：「明朝風起應吹盡，夜惜衰紅把火看。」醉歸盩厔詩雲：「數日非關王事繫，牡丹花盡始歸來。」元微之有入永壽寺看牡丹詩八韻，和樂天秋題牡丹叢三韻，酬胡三詠牡丹一絕，又有五言二絕句。許渾亦有詩雲：「近來無奈牡丹何，數十千錢買一窠。」徐凝雲：「三條九陌花時節，萬馬千車看牡丹。」又雲：「何人不愛牡丹花，占斷城中好物華。」然則元、白未嘗無詩，唐人未嘗不重此花也。","sortOrder":3},
  {"id":"s_work_dtbt_4_4","chapterId":"ch_work_dtbt_4","text":"長歌之哀","sortOrder":4},
  {"id":"s_work_dtbt_4_5","chapterId":"ch_work_dtbt_4","text":"嬉笑之怒，甚於裂眥，長歌之哀，過於慟哭。此語誠然。元微之在江陵，病中聞白樂天左降江州，作絕句雲：「殘燈無焰影幢幢，此夕聞君謫九江。垂死病中驚起坐，暗風吹雨入寒窗。」樂天以為：「此句他人尚不可聞，况僕心哉！」微之集作「垂死病中仍悵望」，此三字既不佳，又不題為病中作，失其意矣。東坡守彭城，子由來訪之，留百餘日而去，作二小詩曰：「逍遙堂後千尋木，長送中宵風雨聲。誤喜對床尋舊約，不知漂泊在彭城。」「秋來東閤涼如水，客去山公醉似泥。困臥北窗呼不醒，風吹松竹雨凄凄。」東坡以為讀之殆不可為懷，乃和其詩以自解。至今觀之，尚能使人悽然也。","sortOrder":5},
  {"id":"s_work_dtbt_4_6","chapterId":"ch_work_dtbt_4","text":"韋蘇州","sortOrder":6},
  {"id":"s_work_dtbt_4_7","chapterId":"ch_work_dtbt_4","text":"韋蘇州集中，有逢楊開府詩雲：「少事武皇帝，無賴恃恩私。身作里中橫，家藏亡命兒。朝持樗蒱局，暮竊東鄰姬。司隸不敢捕，立在白玉墀。驪山風雪夜，長楊羽獵時。一字都不識，飲酒肆頑癡。武皇升仙去，憔悴被人欺。讀書事已晚，把筆學題詩。兩府始收跡，南宮謬見推。非才果不容，出守撫惸嫠。忽逢楊開府，論舊涕俱垂。」味此詩，蓋應物自敍其少年事也，其不羈乃如此。李肇國史補雲：「應物為性高潔，鮮食寡欲，所居焚香掃地而坐，其為詩馳驟建安已還，各得風韻。」蓋記其折節後來也。唐史失其事，不為立傳。高適亦少落魄，年五十始為詩，即工。皆天分超卓，不可以常理論雲。應物為三衞，正天寶間，所為如是，而吏不敢捕，又以見時政矣。","sortOrder":7},
  {"id":"s_work_dtbt_4_8","chapterId":"ch_work_dtbt_4","text":"古行宮詩","sortOrder":8},
  {"id":"s_work_dtbt_4_9","chapterId":"ch_work_dtbt_4","text":"白樂天長恨歌、上陽人歌，元微之連昌宮詞，道開元間宮禁事，最為深切矣。然微之有行宮一絕句雲：「寥落古行宮，宮花寂寞紅。白頭宮女在，閒坐說玄宗。」語少意足，有無窮之味。","sortOrder":9},
  {"id":"s_work_dtbt_4_10","chapterId":"ch_work_dtbt_4","text":"隔是","sortOrder":10},
  {"id":"s_work_dtbt_4_11","chapterId":"ch_work_dtbt_4","text":"樂天詩雲：「江州去日聽箏夜，白髮新生不願聞。如今格是頭成雪，彈到天明亦任君。」元微之詩雲：「隔是身如夢，頻來不為名，憐君近南住，時得到山行。」格與隔二字義同，格是猶言已是也。","sortOrder":11},
  {"id":"s_work_dtbt_4_12","chapterId":"ch_work_dtbt_4","text":"張良無後","sortOrder":12},
  {"id":"s_work_dtbt_4_13","chapterId":"ch_work_dtbt_4","text":"張良、陳平，皆漢祖謀臣，良之為人，非平可比也。平嘗曰：「我多陰謀，道家之所禁。吾世即廢矣，以吾多陰禍也。」平傳國至曾孫，而以罪絕，如其言。然良之爵但能至子，去其死才十年而絕，後世不復紹封，其禍更促於平，何哉？予蓋嘗考之，沛公攻嶢關，秦將欲連和，良曰：「不如因其懈怠擊之。」公引兵大破秦軍。項羽與漢王約中分天下，既解而東歸矣。良有養虎自遺患之語，勸王回軍追羽而滅之。此其事固不止於殺降也，其無後宜哉！","sortOrder":13},
  {"id":"s_work_dtbt_4_14","chapterId":"ch_work_dtbt_4","text":"周亞夫","sortOrder":14},
  {"id":"s_work_dtbt_4_15","chapterId":"ch_work_dtbt_4","text":"周亞夫距吳、楚，堅壁不出。軍中夜驚，內相攻擊擾亂，至於帳下。亞夫堅臥不起。頃之，復定。吳奔壁東南陬，亞夫使備西北。已而果奔西北，不得入。漢史書之，以為亞夫能持重。按，亞夫軍細柳時，天子先驅至，不得入。文帝稱其不可得而犯。今乃有軍中夜驚相攻之事，安在其能持重乎？","sortOrder":15},
  {"id":"s_work_dtbt_4_16","chapterId":"ch_work_dtbt_4","text":"漢輕族人","sortOrder":16},
  {"id":"s_work_dtbt_4_17","chapterId":"ch_work_dtbt_4","text":"爰盎陷鼂錯，但雲：「方今計，獨有斬錯耳。」而景帝使丞相以下劾奏，遂至父母妻子同產無少長皆棄市。主父偃陷齊王於死，武帝欲勿誅，公孫丞相爭之，遂族偃。郭解客殺人，吏奏解無罪，公孫大夫議，遂族解。且偃、解兩人本不死，因議者之言，殺之足矣，何遽至族乎？漢之輕於用刑如此！","sortOrder":17},
  {"id":"s_work_dtbt_4_18","chapterId":"ch_work_dtbt_4","text":"漏泄禁中語","sortOrder":18},
  {"id":"s_work_dtbt_4_19","chapterId":"ch_work_dtbt_4","text":"京房與漢元帝論幽、厲事，至於十問十答。西漢所載君臣之語，未有如是之詳盡委曲者。蓋漢法漏泄省中語為大罪，如夏侯勝出道上語，宣帝責之，故退不敢言，人亦莫能知者。房初見帝時，出為御史大夫鄭君言之，又為張博道其語，博密記之，後竟以此下獄棄市。今史所載，豈非獄辭乎？王章與成帝論王鳳之罪，亦以王音側聽聞之耳。","sortOrder":19},
  {"id":"s_work_dtbt_4_20","chapterId":"ch_work_dtbt_4","text":"田叔","sortOrder":20},
  {"id":"s_work_dtbt_4_21","chapterId":"ch_work_dtbt_4","text":"貫高謀弒漢祖，事發覺，漢詔趙王，有敢隨王罪三族，唯田叔、孟舒等自髠鉗隨王，趙王既出，上以叔等為郡守。文帝初立，召叔問曰：「公知天下長者乎？」曰：「故雲中守孟舒，長者也。」是時，舒坐虜大入雲中免。上曰：「虜入雲中，孟舒不能堅守，士卒死者數白人，長者固殺人乎？」叔叩頭曰：「夫貫高等謀反，天子下明詔，趙有敢隨張王者，罪三族。然孟舒自髠鉗，隨張王，以身死之，豈自知為雲中守哉！是乃所以為長者。」上曰：「賢哉孟舒！」復召以為雲中守。按，田叔、孟舒同隨張王，今叔指言舒事，幾於自薦矣。叔不自以為嫌，但欲直孟舒之事，文帝不以為過，一言開悟，為之復用舒，君臣之誠意相與如此。","sortOrder":21},
  {"id":"s_work_dtbt_4_22","chapterId":"ch_work_dtbt_4","text":"孟舒魏尚","sortOrder":22},
  {"id":"s_work_dtbt_4_23","chapterId":"ch_work_dtbt_4","text":"雲中守孟舒，坐虜大入雲中免。田叔對文帝曰：「匈奴來為邊寇，孟舒知士卒罷敝，不忍出言，士爭臨城死敵，如子為父，以故死者數百人。孟舒豈驅之哉！」上曰：「賢哉孟舒！」復召以為雲中守。又馮唐對文帝曰：「魏尚為雲中守，虜嘗一入，尚率車騎擊之。士卒終日力戰。上功幕府，坐首虜差六級，下吏削爵。臣以為陛下罰太重。」上赦魏尚，復以為雲中守。按，孟舒、魏尚，皆以文帝時為雲中守，皆坐匈奴入寇獲罪，皆得士死力，皆用他人言復故官，事切相類，疑其只一事雲。","sortOrder":23},
  {"id":"s_work_dtbt_4_24","chapterId":"ch_work_dtbt_4","text":"秦用他國人","sortOrder":24},
  {"id":"s_work_dtbt_4_25","chapterId":"ch_work_dtbt_4","text":"七國虎爭天下，莫不招致四方遊士。然六國所用相，皆其宗族及國人，如齊之田忌、田嬰、田文，韓之公仲、公叔，趙之奉陽、平原君，魏王至以太子為相。獨秦不然，其始與之謀國以開霸業者，魏人公孫鞅也。其他若樓緩趙人，張儀、魏冉、范睢皆魏人，蔡澤燕人，呂不韋韓人，李斯楚人。皆委國而聽之不疑，卒之所以兼天下者，諸人之力也。燕昭王任郭隗、劇辛、樂毅，幾滅強齊，辛、毅皆趙人也。楚悼王任吳起為相，諸侯患楚之強，蓋衞人也。","sortOrder":25},
  {"id":"s_work_dtbt_4_26","chapterId":"ch_work_dtbt_4","text":"曹參趙括","sortOrder":26},
  {"id":"s_work_dtbt_4_27","chapterId":"ch_work_dtbt_4","text":"漢高祖疾甚，呂後問曰：「蕭相國既死，誰令代之。」上曰：「曹參可。」蕭何事惠帝，病，上問曰：「君即百歲後，誰可代君？」對曰：「知臣莫若主。」帝曰：「曹參何如？」曰：「帝得之矣。」曹參相齊，聞何薨，告舍人趣治行，吾且入相。居無何，使者果召參。趙括自少時學兵法，其父奢不能難，然不謂善，謂其母曰：「趙若必將之，破趙軍者必括也。」後廉頗與秦相持，秦應侯行千金為反間於趙，曰：「秦之所畏，獨趙括耳。」趙王以括代頗將。藺相如諫，王不聽。括母上書言括不可使，王又不聽。秦王聞括已為趙將，乃陰使白起代王齕，遂勝趙。曹參之宜為相，高祖以為可，惠帝以為可，蕭何以為可，參自以為可，故漢用之而興。趙括之不宜為將，其父以為不可，母以為不可，大臣以為不可，秦王知之，相應侯知之，將白起知之，獨趙王以為可，故用之而敗。嗚呼！將相安危所係，可不監哉！且秦以白起易王齕，而趙乃以括代廉頗，不待於戰，而勝負之形見矣。","sortOrder":27},
  {"id":"s_work_dtbt_4_28","chapterId":"ch_work_dtbt_4","text":"信近於義","sortOrder":28},
  {"id":"s_work_dtbt_4_29","chapterId":"ch_work_dtbt_4","text":"「信近於義，言可復也。恭近於禮，遠恥辱也。因不失其親，亦可宗也。」程明道曰：「因恭信而不失其所以親，近於禮義，故亦可宗。」伊川曰：「因不失於相近，亦可尚也。」又曰：「因其近禮義而不失其親，亦可宗也。况於盡禮義者乎？」范純父曰：「君子所因者本，而立愛必自親始，親親必及人。故曰因不失其親。」呂與叔分為三事。謝顯道曰：「君師友三者，雖非天屬，亦可以親，捨此三者之外，吾恐不免於諂賤。惟親不失其所親，然後可為宗也。」楊中立曰：「信不失義，恭不悖禮，又因不失其親焉，是亦可宗也。」尹彥明曰：「因其近，雖未足以盡禮義之本，亦不失其所宗尚也。」予竊以謂義與禮之極，多至於不親，能至於不失其親，斯為可宗也。然未敢以為是。(「可為宗」，館本作「為可宗」。)","sortOrder":29},
  {"id":"s_work_dtbt_4_30","chapterId":"ch_work_dtbt_4","text":"剛毅近仁","sortOrder":30},
  {"id":"s_work_dtbt_4_31","chapterId":"ch_work_dtbt_4","text":"剛毅者，必不能令色；木訥者，必不為巧言。此近仁鮮仁之辨也。","sortOrder":31},
  {"id":"s_work_dtbt_4_32","chapterId":"ch_work_dtbt_4","text":"忠恕違道","sortOrder":32},
  {"id":"s_work_dtbt_4_33","chapterId":"ch_work_dtbt_4","text":"曾子曰：「夫子之道，忠恕而已矣。」中庸曰：「忠恕違道不遠。」學者疑為不同。伊川雲：「中庸恐人不喻，乃指而示之近。」又雲：「忠恕固可以貫道，子思恐人難曉，故降一等言之。」又雲：「中庸以曾子之言雖是如此，又恐人尚疑忠恕未可便為道。故曰違道不遠。」遊定夫雲：「道一而已，豈參彼此所能豫哉？此忠恕所以違道，為其未能一以貫之也。雖然，欲求入道者，莫近於此。此所以違道不遠也。」楊中立雲：「忠恕固未足以盡道，然而違道不遠矣。」侯師聖雲：「子思之忠恕，施諸己而不願，亦勿施於人。此已是違道。若聖人，則不待施諸己而不願，然後勿施諸人也。」諸公之說大抵不同。予竊以為道不可名言，既麗於忠恕之名，則為有跡。故曰違道。然非忠恕二字亦無可以明道者。故曰不遠。非謂其未足以盡道也。違者違去之謂，非違畔之謂。老子曰：「上善若水，水善利萬物而不爭，處衆人之所惡，故幾於道。」蘇子由解雲：「道無所不在，無所不利，而水亦然。然而既已麗於形，則於道有間矣。故曰幾於道。然而可名之善，未有若此者。故曰上善。」其說與此略同。","sortOrder":33},
  {"id":"s_work_dtbt_4_34","chapterId":"ch_work_dtbt_4","text":"求為可知","sortOrder":34},
  {"id":"s_work_dtbt_4_35","chapterId":"ch_work_dtbt_4","text":"「不患無位，患所以立，不患莫己知，求為可知也。」為之說者，皆以為當求為可知之行。唯謝顯道雲：「此論猶有求位求可知之道，在至論則不然，難用而莫我知，斯我貴矣，夫復何求？」予以為君子不以無位為患，而以無所立為患；不以莫己知為患，而以求為可知為患。第四句蓋承上文言之。夫求之有道，若汲汲然求為可知，則亦無所不至矣。","sortOrder":35},
  {"id":"s_work_dtbt_4_36","chapterId":"ch_work_dtbt_4","text":"里仁","sortOrder":36},
  {"id":"s_work_dtbt_4_37","chapterId":"ch_work_dtbt_4","text":"「里仁為美。擇不處仁，焉得智？」孟子論函矢巫匠之術，而引此以質之，說者多以里為居，居以親仁為美。予嘗記一說雲，函矢巫匠皆里中之仁也。然於仁之中有不仁存焉，則仁亦在夫擇之而已矣。嘗於鄭景望言之，景望不以為然。予以為此特謂閭巷之間所推以為仁者，固在所擇，正合孟子之意。不然，仁之為道大矣，尚安所擇而處哉？","sortOrder":37},
  {"id":"s_work_dtbt_4_38","chapterId":"ch_work_dtbt_4","text":"漢采衆議","sortOrder":38},
  {"id":"s_work_dtbt_4_39","chapterId":"ch_work_dtbt_4","text":"漢元帝時，珠厓反，連年不定。上與有司議大發軍，待詔賈捐之建議，以為不當擊。上以問丞相、御史，御史大夫陳萬年以為當擊，丞相於定國以為捐之議是，上從之，遂罷珠厓郡。匈奴呼韓邪單於既事漢，上書願保塞上穀以西，請罷邊備塞吏卒，以休天子人民。天子令下有司議，議者皆以為便，郎中侯應習邊事，以為不可許。上問狀，應對十策，有詔勿議罷邊塞事。成帝時，匈奴使者欲降，下公卿議，議者言宜如故事受其降。光祿大夫穀永以為不如勿受，天子從之。使者果詐也。哀帝時，單於求朝，帝欲止之，以問公卿，亦以為虛費府帑，可且勿許。單於使辭去。黃門郎揚雄上書諫，天子寤焉，召還匈奴使者，更報單於書而許之。安帝時，大將軍鄧騭欲棄涼州，幷力北邊，會公卿集議，皆以為然，郎中虞詡陳三不可，乃更集四府，皆從詡議。北匈奴復強，西域諸國既絕於漢，公卿多以為宜閉玉門關絕西域。鄧太後召軍司馬班勇問之，勇以為不可，於是從勇議。順帝時，交阯蠻叛，帝召公卿百官及四府掾屬，問以方略，皆議遣大將發兵赴之，議郎李固駁之，乞選刺史太守以往，四府悉從固議，嶺外復平。靈帝時，涼州兵亂不解，司徒崔烈以為宜棄，詔會公卿百官議之，議郎傅燮以為不可，帝從之。此八事者，所係利害甚大，一時公卿百官既同定議矣，賈捐之以下八人，皆以郎大夫之微，獨陳異說。漢元、成、哀、安、順、靈皆非明主，悉能違衆而聽之，大臣無賢愚亦不復執前說，蓋猶有公道存焉。每事皆能如是，天下其有不治乎？","sortOrder":39},
  {"id":"s_work_dtbt_4_40","chapterId":"ch_work_dtbt_4","text":"漢母後","sortOrder":40},
  {"id":"s_work_dtbt_4_41","chapterId":"ch_work_dtbt_4","text":"漢母後預政，不必臨朝及少主，雖長君亦然。文帝繫周勃，薄太後曰：「絳侯綰皇帝璽，將兵於北軍，不以此時反，今居一小縣，顧欲反邪？」帝謝曰：「吏方驗而出之。」遂赦勃。吳、楚反誅，景帝欲續之，竇太後曰：「吳王老人也，宜為宗室順善，今乃首亂天下，奈何續其後！」不許吳，許立楚後。郅都害臨江王，竇太後怒，會匈奴中都以漢法。帝曰：「都忠臣。」欲釋之。後曰：「臨江王獨非忠臣乎？」於是斬都。武帝用王臧、趙綰，太皇竇太後不悅儒術，綰請毋奏事東宮，後大怒，求得二人奸利事以責上，上下綰、臧吏，殺之。竇嬰、田蚡廷辯，王太後大怒不食，曰：「我在也，而人皆藉吾弟，且帝寧能為石人邪！」帝不直蚡，特為太後故殺嬰。韓嫣得幸於上，江都王為太後泣，請得入宿衞比嫣，後繇此銜嫣，嫣以奸聞，後使使賜嫣死。上為謝，終不能得。成帝幸張放，太後以為言，帝常涕泣而遣之。","sortOrder":41},
  {"id":"s_work_dtbt_4_42","chapterId":"ch_work_dtbt_4","text":"田千秋郅惲","sortOrder":42},
  {"id":"s_work_dtbt_4_43","chapterId":"ch_work_dtbt_4","text":"漢武帝殺戾太子，田千秋訟太子冤曰：「子弄父兵當何罪？」帝大感悟曰：「父子之間，人所難言也。公獨明其不然，公當遂為吾輔佐。」遂拜為丞相。光武廢郭後，郅惲言曰：「夫婦之好，父不能得之於子，况臣能得之於君乎？是臣所不敢言。雖然，願陛下念其可否之計，無令天下有議社稷而已。」帝曰：「惲善恕己量主。」遂以郭氏為中山王太後，卒以壽終。此二人者，可謂善處人骨肉之間，諫不費詞，婉而能入者矣。","sortOrder":43},
  {"id":"s_work_dtbt_4_44","chapterId":"ch_work_dtbt_4","text":"戾太子","sortOrder":44},
  {"id":"s_work_dtbt_4_45","chapterId":"ch_work_dtbt_4","text":"戾太子死，武帝追悔，為之族江充家，黃門蘇文助充譖太子，至於焚殺之。李壽加兵刃於太子，亦以他事族。田千秋以一言至為丞相，又作思子宮，為歸來望思之臺。然其孤孫囚繫於郡邸，獨不能釋之，至於掖庭令養視而不問也，豈非漢法至嚴，既坐太子以反逆之罪，雖心知其寃，而有所不赦者乎？","sortOrder":45},
  {"id":"s_work_dtbt_4_46","chapterId":"ch_work_dtbt_4","text":"灌夫任安","sortOrder":46},
  {"id":"s_work_dtbt_4_47","chapterId":"ch_work_dtbt_4","text":"竇嬰為丞相，田蚡為太尉，同日免。蚡後為丞相，而嬰不用無勢，諸公稍自引而怠驁，唯灌夫獨否。衞青為大將軍，霍去病才為校尉，已而皆為大司馬。青日衰，去病日益貴。青故人門下多去事去病，唯任安不肯去。灌夫、任安，可謂賢而知義矣。然皆以他事卒不免於族誅，事不可料如此。","sortOrder":47},
  {"id":"s_work_dtbt_4_48","chapterId":"ch_work_dtbt_4","text":"單於朝漢","sortOrder":48},
  {"id":"s_work_dtbt_4_49","chapterId":"ch_work_dtbt_4","text":"漢宣帝黃龍元年正月，匈奴單於來朝，二月歸國，十二月帝崩。元帝竟寧元年正月，又來朝，五月帝崩。故哀帝時，單於願朝，時帝被疾，或言匈奴從上遊來厭人。自黃龍、竟寧時，中國輒有大故，上由是難之。既不許矣，俄以揚雄之言，復許之。然元壽二年正月，單於朝，六月帝崩。事之偶然符合，有如此者。","sortOrder":49},
  {"id":"s_work_dtbt_4_50","chapterId":"ch_work_dtbt_4","text":"容齋隨筆","sortOrder":50},
  {"id":"s_work_dtbt_5_1","chapterId":"ch_work_dtbt_5","text":"卷第三(二十一則)","sortOrder":1},
  {"id":"s_work_dtbt_5_2","chapterId":"ch_work_dtbt_5","text":"進士試題","sortOrder":2},
  {"id":"s_work_dtbt_5_3","chapterId":"ch_work_dtbt_5","text":"唐穆宗長慶元年，禮部侍郎錢徽知舉，放進士鄭朗等三十三人，後以段文昌言其不公，詔中書舍人王起、知製誥白居易重試，駁放盧公亮等十人，貶徽江州刺史。白公集有奏狀論此事，大略雲：「伏料自欲重試進士以來論奏者甚衆。蓋以禮部試進士，例許用書策，兼得通宵，得通宵則思慮必周，用書冊則文字不錯。昨重試之日，書策不容一字，木燭只許兩條，迫促驚忙，幸皆成就，若比禮部所試事校不同。」及駁放公亮等敕文，以為孤竹管賦出於周禮正經，閱其程試之文，多是不知本末。乃知唐試進士許挾書及見燭如此。國朝淳化三年，太宗試進士，出巵言日出賦題，孫何等不知所出，相率扣殿檻乞上指示之，上為陳大義。景德二年，御試天道猶張弓賦。後禮部貢院言，近年進士惟鈔略古今文賦，懷挾入試，昨者御試以正經命題，多懵所出，則知題目不示以出處也。大中祥符元年，試禮部進士，內出清明象天賦等題，仍錄題解，摹印以示之。至景祐元年，始詔御藥院，御試日進士題目，具經史所出，摹印給之，更不許上請。","sortOrder":3},
  {"id":"s_work_dtbt_5_4","chapterId":"ch_work_dtbt_5","text":"儒人論佛書","sortOrder":4},
  {"id":"s_work_dtbt_5_5","chapterId":"ch_work_dtbt_5","text":"韓文公送文暢序，言儒人不當舉浮屠之說以告僧。其語雲：「文暢浮屠也，如欲聞浮屠之說，當自就其師而問之，何故謁吾徒而來請也？」元微之作永福寺石壁記雲：「佛書之妙奧，僧當為予言，予不當為僧言。」二公之語，可謂至當。","sortOrder":5},
  {"id":"s_work_dtbt_5_6","chapterId":"ch_work_dtbt_5","text":"和歸去來","sortOrder":6},
  {"id":"s_work_dtbt_5_7","chapterId":"ch_work_dtbt_5","text":"今人好和歸去來詞，予最敬晁以道所言。其答李持國書雲：「足下愛淵明所賦歸去來辭，遂同東坡先生和之，僕所未喻也。建中靖國間，東坡和歸去來，初至京師，其門下賓客從而和者數人，皆自謂得意也，陶淵明紛然一日滿人目前矣。參寥忽以所和篇示予，率同賦，予謝之曰：『童子無居位，先生無並行，與吾師共推東坡一人於淵明間可也。』參寥即索其文，袖之出，吳音曰：『罪過公，悔不先與公話。』今輒以厚於參寥者為子言。」昔大宋相公謂陶公歸去來是南北文章之絕唱，五經之鼓吹。近時繪畫歸去來者，皆作大聖變，和其辭者，如即事遣興小詩，皆不得正中者也。","sortOrder":7},
  {"id":"s_work_dtbt_5_8","chapterId":"ch_work_dtbt_5","text":"四海一也","sortOrder":8},
  {"id":"s_work_dtbt_5_9","chapterId":"ch_work_dtbt_5","text":"海一而已，地之勢西北高而東南下，所謂東、北、南三海，其實一也。北至於青、滄，則雲北海，南至於交、廣，則雲南海，東漸吳、越，則雲東海，無由有所謂西海者。詩、書、禮經所載四海，蓋引類而言之。漢西域傳所雲蒲昌海，疑亦渟居一澤爾。班超遣甘英往條支，臨大海，蓋即南海之西雲。","sortOrder":9},
  {"id":"s_work_dtbt_5_10","chapterId":"ch_work_dtbt_5","text":"李太白","sortOrder":10},
  {"id":"s_work_dtbt_5_11","chapterId":"ch_work_dtbt_5","text":"世俗多言李太白在當塗采石，因醉泛舟於江，見月影俯而取之，遂溺死，故其地有捉月臺。予按李陽冰作太白草堂集序雲：「陽冰試絃歌於當塗，公疾亟，草稿萬卷，手集未修，枕上授簡，俾為序。」又李華作太白墓誌，亦雲：「賦臨終歌而卒。」乃知俗傳良不足信，蓋與謂杜子美因食白酒牛炙而死者同也。","sortOrder":11},
  {"id":"s_work_dtbt_5_12","chapterId":"ch_work_dtbt_5","text":"太白雪讒","sortOrder":12},
  {"id":"s_work_dtbt_5_13","chapterId":"ch_work_dtbt_5","text":"李太白以布衣入翰林，既而不得官。唐史言高力士以脫靴為恥，摘其詩以激楊貴妃，為妃所沮止。今集中有雪讒詩一章，大率載婦人淫亂敗國，其略雲：「彼婦人之猖狂，不如鵲之彊彊。彼婦人之淫昏，不如鶉之奔奔。坦蕩君子，無悅簧言。」又雲：「妲己滅紂，褒女惑周。漢祖呂氏，食其在傍。秦皇太後，毐亦淫荒。螮蝀作昏，遂掩太陽。萬乘尚爾，匹夫何傷。詞殫意窮，心切理直。如或妄談，昊天是殛。」予味此詩，豈非貴妃與祿山淫亂，而白曾發其奸乎？不然，則「飛燕在昭陽」之句，何足深怨也？","sortOrder":13},
  {"id":"s_work_dtbt_5_14","chapterId":"ch_work_dtbt_5","text":"冉有問衛君","sortOrder":14},
  {"id":"s_work_dtbt_5_15","chapterId":"ch_work_dtbt_5","text":"冉有曰：「夫子為衞君乎？」子貢曰：「吾將問之。」入，曰：「伯夷、叔齊何人也？」曰：「古之賢人也。」曰：「怨乎？」曰：「求仁而得仁，又何怨？」出，曰：「夫子不為也。」說者皆評較蒯聵、輒之是非，多至數百言，惟王逢原以十字蔽之，曰：「賢兄弟讓，知惡父子爭矣。」最為簡妙。蓋夷、齊以兄弟讓國，而夫子賢之，則不與衞君以父子爭國可知矣。晁以道亦有是語，而結意不同。尹彥明之說，與逢原同。唯楊中立雲：「世之說者，以謂善兄弟之讓，則惡父子之爭可知，失其旨矣。」其意為不可曉。","sortOrder":15},
  {"id":"s_work_dtbt_5_16","chapterId":"ch_work_dtbt_5","text":"商頌","sortOrder":16},
  {"id":"s_work_dtbt_5_17","chapterId":"ch_work_dtbt_5","text":"宋自微子至戴公，禮樂廢壞。正考甫得商頌十二篇於周之太師，後又亡其七，至孔子時，所存才五篇爾。宋，商王之後也，於先代之詩如是，則其他可知。夫子所謂「商禮吾能言之，宋不足徵也」。蓋有嘆於此。杞以夏後之裔，至於用夷禮，尚何有於文獻哉？郯國小於杞、宋，少昊氏遠於夏、商，而鳳鳥名官，郯子枚數不忘，曰：「吾祖也，我知之。」其亦賢矣。","sortOrder":17},
  {"id":"s_work_dtbt_5_18","chapterId":"ch_work_dtbt_5","text":"俗語有所本","sortOrder":18},
  {"id":"s_work_dtbt_5_19","chapterId":"ch_work_dtbt_5","text":"俗語謂錢一貫有畸曰千一、千二，米一石有畸曰石一、石二，長一丈有畸曰丈一、丈二之類。按考工記：「殳長尋有四尺。」註雲：「八尺曰尋，殳長丈二。」史記張儀傳，尺一之檄，漢淮南王安書雲，丈一之組，匈奴傳，尺一牘，後漢，尺一詔書，唐，城南去天尺五之類，然則亦有所本雲。","sortOrder":19},
  {"id":"s_work_dtbt_5_20","chapterId":"ch_work_dtbt_5","text":"鄱陽學","sortOrder":20},
  {"id":"s_work_dtbt_5_21","chapterId":"ch_work_dtbt_5","text":"鄱陽學在城外東湖之北，相傳以為范文正公作郡守時所創。予考國史，范公以景祐三年乙亥歲四月知饒州，四年十二月，詔自今須藩鎮乃得立學，他州勿聽，是月，范公移潤州。餘襄公集有饒州新建州學記，實起於慶曆五年乙酉歲，其郡守曰都官員外郎張君，其略雲：「先是郡先聖祠宮棟宇隳剝，前守亦嘗相土，而未遑締治，於是即其基於東湖之北偏而經營之。」浮梁人金君卿郎中作郡學莊田記雲：「慶曆四年春，詔郡國立學，時守都官副郎張侯譚始營之，明年學成。」與餘公記合。范公在饒時，延君卿置館舍，使公有意建學，記中豈無一言及之？蓋是時公既為執政，去郡十年矣。所謂前守相土者不知為何人？","sortOrder":21},
  {"id":"s_work_dtbt_5_22","chapterId":"ch_work_dtbt_5","text":"國忌休務","sortOrder":22},
  {"id":"s_work_dtbt_5_23","chapterId":"ch_work_dtbt_5","text":"刑統載唐大和七年敕：「准令，國忌日唯禁飲酒舉樂，至於科罰人吏，都無明文。但緣其日不合釐務，官曹即不得決斷刑獄，其小小笞責，在禮律固無所妨，起今以後，縱有此類，臺府更不要舉奏。」舊唐書載此事，因御史臺奏均王傅王堪男國忌日於私第科決作人，故降此詔。蓋唐世國忌休務，正與私忌義等，故雖刑獄亦不決斷，謂之不合釐務者此也。今在京百官，唯雙忌作假，以其拜跪多，又晝漏已數刻，若單忌獨三省歸休耳，百司坐曹決獄與常日亡異，視古誼為不同。元微之詩雲：「縛遣推囚名御史，狼藉囚徒滿田地，明日不推緣國忌。」又可證也。","sortOrder":23},
  {"id":"s_work_dtbt_5_24","chapterId":"ch_work_dtbt_5","text":"漢昭順二帝","sortOrder":24},
  {"id":"s_work_dtbt_5_25","chapterId":"ch_work_dtbt_5","text":"漢昭帝年十四，能察霍光之忠，知燕王上書之詐，誅桑弘羊、上官桀，後世稱其明。然和帝時，竇憲兄弟專權，太後臨朝，共圖殺害。帝陰知其謀，而與內外臣僚莫由親接，獨知中常侍鄭衆不事豪黨，遂與定議誅憲，時亦年十四，其剛決不下昭帝，但范史發明不出，故後世無稱焉。順帝時，梁商為大將軍輔政，商以小黃門曹節用事於中，遣子冀與交友，而宦官忌其寵，反欲害之。中常侍張逵、蘧政、楊定等，與左右連謀，共譖商及中常侍曹騰、孟賁，雲欲議廢立，請收商等按罪。帝曰：「大將軍父子我所親，騰、賁我所愛，必無是，但汝曹共妬之耳。」逵等知言不用，遂出矯詔收縛騰、賁。帝震怒，收逵等殺之，此事尤與昭帝相類。霍光忠於國，而為子禹覆其宗，梁商忠於國，而為子冀覆其宗，又相似。但順帝復以政付冀，其明非昭帝比，故不為人所稱。","sortOrder":25},
  {"id":"s_work_dtbt_5_26","chapterId":"ch_work_dtbt_5","text":"三女後之賢","sortOrder":26},
  {"id":"s_work_dtbt_5_27","chapterId":"ch_work_dtbt_5","text":"王莽女為漢平帝後，自劉氏之廢，常稱疾不朝會。莽敬憚傷哀，欲嫁之，後不肯，及莽敗，後曰：「何面目以見漢家。」自投火中而死。楊堅女為周宣帝後，知其父有異圖，意頗不平，形於言色，及禪位，憤惋愈甚。堅內甚愧之，欲奪其志，後誓不許，乃止。李昪女為吳太子璉妃，昪既篡吳，封為永興公主，妃聞人呼公主，則流涕而辭。三女之事略同，可畏而仰，彼為其父者，安所置愧乎？","sortOrder":27},
  {"id":"s_work_dtbt_5_28","chapterId":"ch_work_dtbt_5","text":"賢父兄子弟","sortOrder":28},
  {"id":"s_work_dtbt_5_29","chapterId":"ch_work_dtbt_5","text":"宋謝晦為右衞將軍，權遇已重，自彭城還都迎家，賓客輻凑。兄瞻驚駭曰：「汝名位未多，而人歸趣乃爾，此豈門戶之福邪？」乃以籬隔門庭，曰：「吾不忍見此。」又言於宋公裕，特乞降黜，以保衰門。及晦立佐命功，瞻意憂懼，遇病，不療而卒。晦果覆其宗。顏竣於孝武有功貴重，其父延之，常語之曰：「吾平生不喜見要人，今不幸見汝。」嘗早詣竣，見賓客盈門，竣尚未起，延之怒曰：「汝出糞土之中，升雲霞之上，遽驕傲如此，其能久乎？」竣竟為孝武所誅。延之、瞻可謂賢父兄矣。","sortOrder":29},
  {"id":"s_work_dtbt_5_30","chapterId":"ch_work_dtbt_5","text":"隋高熲拜為僕射，其母戒之曰：「汝富貴已極，但有一斫頭爾！」熲由是常恐禍變，及罷免為民，歡然無恨色，後亦不免為煬帝所誅。唐潘孟陽為侍郎，年未四十，母曰：「以爾之材，而位丞郎，使吾憂之。」嚴武卒，母哭曰：「而今而後，吾知免為官婢。」三者可謂賢母矣。","sortOrder":30},
  {"id":"s_work_dtbt_5_31","chapterId":"ch_work_dtbt_5","text":"褚淵助蕭道成篡宋為齊，淵從弟炤謂淵子賁曰：「不知汝家司空將一家物與一家，亦復何謂？」及淵為司徒，炤嘆曰：「門戶不幸，乃復有今日之拜。」淵卒，世子賁恥其父失節，服除遂不仕，以爵與其弟，屏居終身。齊王晏助明帝奪國，從弟思遠曰：「兄將來何以自立？若及此引決，猶可保全門戶。」及拜驃騎將軍，集會子弟，謂思遠兄思微曰：「隆昌之末，阿戎勸吾自裁，若從其語，豈有今日？」思遠曰：「如阿戎所見，今猶未晚也。」晏嘆曰：「世乃有勸人死者！」晏果為明帝所誅。炤、賁、思遠，可謂賢子弟矣。","sortOrder":31},
  {"id":"s_work_dtbt_5_32","chapterId":"ch_work_dtbt_5","text":"蔡君謨帖","sortOrder":32},
  {"id":"s_work_dtbt_5_33","chapterId":"ch_work_dtbt_5","text":"蔡君謨一帖雲：「襄昔之為諫臣，與今之為詞臣，一也，為諫臣有言責，世人自見疏，今無是焉，世人見親，襄之於人，未始異之，而人之觀故有以異也。」觀此帖，乃知昔時居臺諫者，為人所疏如此。今則反是，方為此官時，其門揮汗成雨，一徙他局，可張爵羅，風俗媮薄甚矣。又有送荔枝與昭文相公一帖雲：「襄再拜，宿來伏惟台候起居萬福。閩中荔枝，唯陳家紫號為第一，輒獻左右，以伸野芹之誠，幸賜收納，謹奉手狀上聞不宣。襄上昭文相公閣下。」是時，侍從與宰相往還，其禮蓋如是，今之不情苛禮，吁可厭哉！","sortOrder":33},
  {"id":"s_work_dtbt_5_34","chapterId":"ch_work_dtbt_5","text":"親王與侍從官往還","sortOrder":34},
  {"id":"s_work_dtbt_5_35","chapterId":"ch_work_dtbt_5","text":"神宗有御筆一紙，乃為潁王時封還李受門狀者，狀雲：「右諫議大夫、天章閣待製兼侍講李受起居皇子大王。」而其外封，題曰：「台銜回納。」下雲：「皇子忠武軍節度使、檢校太尉、同中書門下平章事、上柱國潁王名謹封。」名乃親書。其後受之子覆以黃，繳進，故藏於顯謨閣。先公得之於燕，始知國朝故事，親王與從官往還公禮如此。","sortOrder":35},
  {"id":"s_work_dtbt_5_36","chapterId":"ch_work_dtbt_5","text":"三傳記事","sortOrder":36},
  {"id":"s_work_dtbt_5_37","chapterId":"ch_work_dtbt_5","text":"秦穆公襲鄭，晉納邾捷菑，三傳所書略相似。左氏書秦事曰：「杞子自鄭告於秦曰：『潛師以來，國可得也。』穆公訪諸蹇叔，蹇叔曰：『勞師以襲遠，非所聞也，且行千里，其誰不知！』公辭焉，召孟明出師。蹇叔哭之曰：『孟子，吾見師之出，而不見其入也。』公曰：『爾何知！中壽，爾墓之木拱矣。』蹇叔之子與師，哭而送之曰：『晉人禦師必於殽，殽有二陵焉，必死是間，餘收爾骨焉。』秦師遂東。」公羊曰：「秦伯將襲鄭，百里子與蹇叔子諫曰：『千里而襲人，未有不亡者也。』秦伯怒曰：『若爾之年者，宰上之木拱矣，爾曷知！』師出，百里子與蹇叔子送其子而戒之曰：『爾即死，必於殽嶔巖，吾將尸爾焉。』子揖師而行，百里子與蹇叔子從其子而哭之。秦伯怒曰：『爾曷為哭吾師？』對曰：『臣非敢哭君師，哭臣之子也。』」穀梁曰：「秦伯將襲鄭，百里子與蹇叔子諫曰：『千里而襲人，未有不亡者也。』秦伯曰：『子之冢木已拱矣，何知？』師行，百里子與蹇叔子送其子而戒之曰：『女死必於殽之巖唫之下，我將尸女於是。』師行，百里子與蹇叔子隨其子而哭之，秦伯怒曰：『何為哭吾師也！』二子曰：『非敢哭師也，哭吾子也，我老矣，彼不死，則我死矣。』」","sortOrder":37},
  {"id":"s_work_dtbt_5_38","chapterId":"ch_work_dtbt_5","text":"其書邾事，左氏曰：「邾文公元妃齊薑，生定公，二妃晉姬，生捷菑。文公卒，邾人立定公。捷菑奔晉，晉趙盾以諸侯之師八百乘，納之。邾人辭曰：『齊出貜且長。』宣子曰：『辭順而弗從，不祥。』乃還。」公羊曰：「晉郤缺帥師，革車八百乘，以納接菑於邾婁，力沛然若有餘而納之，邾婁人辭曰：『接菑，晉出也，貜且，齊出也。子以其指則接菑也四，貜且也六，子以大國壓之，則未知齊、晉孰有之也。貴則皆貴矣，雖然，貜且也長。』郤缺曰：『非吾力不能納也，義實不爾克也。』引師而去之。」穀梁曰：「長轂五百乘，地千里，過宋、鄭、滕、薛，敻入千乘之國，欲變人之主，至城下，然後知，何知之晚也！捷菑，晉出也，貜且，齊出也；貜且，正也，捷菑，不正也。」","sortOrder":38},
  {"id":"s_work_dtbt_5_39","chapterId":"ch_work_dtbt_5","text":"予謂秦之事，穀梁紆餘有味，邾之事，左氏語簡而切，欲為文記事者，當以是觀之。","sortOrder":39},
  {"id":"s_work_dtbt_5_40","chapterId":"ch_work_dtbt_5","text":"張嘉貞","sortOrder":40},
  {"id":"s_work_dtbt_5_41","chapterId":"ch_work_dtbt_5","text":"唐張嘉貞為幷州長史、天兵軍使，明皇欲相之，而忘其名，詔中書侍郎韋抗曰：「朕嘗記其風操，今為北方大將，張姓而複名，卿為我思之。」抗曰：「非張齊丘乎？今為朔方節度使。」帝即使作詔以為相，夜閱大臣表疏，得嘉貞所獻，遂相之。議者謂明皇欲大用人，而鹵莽若是，非得嘉貞表疏，則誤相齊丘矣。予考其事大為不然。按開元八年，嘉貞為相，而齊丘以天寶八載始為朔方節度，相去三十年，安得如上所雲者？又是時明皇臨御未久，方厲精為治，不應置相而不審其名位，蓋鄭處誨所著明皇雜錄妄載其事，史家誤采之也，資治通鑑棄不取雲。","sortOrder":41},
  {"id":"s_work_dtbt_5_42","chapterId":"ch_work_dtbt_5","text":"張九齡作牛公碑","sortOrder":42},
  {"id":"s_work_dtbt_5_43","chapterId":"ch_work_dtbt_5","text":"張九齡為相，明皇欲以涼州都督牛仙客為尚書，執不可，曰：「仙客河湟一使典耳，擢自胥史，目不知書，陛下必用仙客，臣實恥之。」帝不悅，因是遂罷相。觀九齡集中，有贈涇州刺史牛公碑，蓋仙客之父，譽之甚至，雲：「福善莫大於有後，仙客為國之良，用商君耕戰之國，修充國羌胡之具，出言可復，所計而然，邊捍長城，主恩前席。」正稱其在涼州時，與所諫止尚書事，亦才一年，然則與仙客非有夙嫌，特為公家忠計耳。","sortOrder":43},
  {"id":"s_work_dtbt_5_44","chapterId":"ch_work_dtbt_5","text":"唐人告命","sortOrder":44},
  {"id":"s_work_dtbt_5_45","chapterId":"ch_work_dtbt_5","text":"唐人重告命，故顏魯公自書告身，今猶有存者。韋述集賢註記，記一事尤著，漫載於此：「開元二十三年七月，製加皇子榮王已下官爵，令宰相及朝官工書者，就集賢院寫告身以進，於是宰相張九齡、裴耀卿、李林甫，朝士蕭太師嵩，李尚書暠，崔少保琳、陳黃門希烈，嚴中書挺之，張兵部均，韋太常陟，褚諫議庭誨等十三人，各寫一通，裝縹進內，上大悅，賜三相絹各三百匹，餘官各二百匹。」以唐書考之，是時，十三王並授開府儀同三司，詔詣東宮、尚書省，上日百官集送，有司供帳設樂，悉拜王府官屬，而不書此事。","sortOrder":45},
  {"id":"s_work_dtbt_5_46","chapterId":"ch_work_dtbt_5","text":"典章輕廢","sortOrder":46},
  {"id":"s_work_dtbt_5_47","chapterId":"ch_work_dtbt_5","text":"典章故事，有一時廢革遂不可復者。牧守銅魚之製，新除刺史給左魚，到州取州庫右魚合契。周顯德六年，詔以特降製書，何假符契？遂廢之。唐兩省官上事宰臣，送上，四相共坐一榻，各據一隅，謂之押角。晉天福五年，敕廢之。","sortOrder":47},
  {"id":"s_work_dtbt_5_48","chapterId":"ch_work_dtbt_5","text":"容齋隨筆","sortOrder":48},
  {"id":"s_work_dtbt_6_1","chapterId":"ch_work_dtbt_6","text":"卷第四(二十三則)","sortOrder":1},
  {"id":"s_work_dtbt_6_2","chapterId":"ch_work_dtbt_6","text":"張浮休書","sortOrder":2},
  {"id":"s_work_dtbt_6_3","chapterId":"ch_work_dtbt_6","text":"張芸叟與石司理書雲：「頃遊京師，求謁先達之門，每聽歐陽文忠公、司馬溫公、王荊公之論，於行義文史為多，唯歐陽公多談吏事。既久之，不免有請：『大凡學者之見先生，莫不以道德文章為欲聞者，今先生多教人以吏事，所未諭也。』公曰：『不然。吾子皆時才，異日臨事，當自知之。大抵文學止於潤身，政事可以及物。吾昔貶官夷陵，方壯年，未厭學，欲求史、漢一觀，公私無有也。無以遣日，因取架閣陳年公案，反覆觀之，見其枉直乖錯不可勝數，以無為有，以枉為直，違法徇情，滅親害義，無所不有。且夷陵荒遠褊小，尚如此，天下固可知也。當時仰天誓心曰：自爾遇事不敢忽也。』是時蘇明允父子亦在焉，嘗聞此語。」又有答孫子發書，多論資治通鑑，其略雲：溫公嘗曰：「吾作此書，唯王勝之嘗閱之終篇，自餘君子求乞欲觀，讀未終紙，已欠伸思睡矣。書十九年方成，中間受了人多少語言陵藉」雲雲。此兩事，士大夫罕言之，浮休集百卷無此二篇，今豫章所刊者，附之集後。","sortOrder":3},
  {"id":"s_work_dtbt_6_4","chapterId":"ch_work_dtbt_6","text":"溫公客位榜","sortOrder":4},
  {"id":"s_work_dtbt_6_5","chapterId":"ch_work_dtbt_6","text":"司馬溫公作相日，親書榜稿揭於客位，曰：「訪及諸君，若睹朝政闕遺，庶民疾苦，欲進忠言者，請以奏牘聞於朝廷，光得與同僚商議，擇可行者進呈，取旨行之。若但以私書寵諭，終無所益。若光身有過失，欲賜規正，即以通封書簡分付吏人，令傳入，光得內自省訟，佩服改行。至於整會官職差遣、理雪罪名，凡幹身計，幷請一面進狀，光得與朝省衆官公議施行。若在私第垂訪，不請語及。某再拜咨白。」乾道九年，公之曾孫伋出鎮廣州，道過贛，獲觀之。","sortOrder":5},
  {"id":"s_work_dtbt_6_6","chapterId":"ch_work_dtbt_6","text":"李頎詩","sortOrder":6},
  {"id":"s_work_dtbt_6_7","chapterId":"ch_work_dtbt_6","text":"歐陽公好稱誦唐嚴維詩「柳塘春水慢，花塢夕陽遲」及楊衡「竹徑通幽處，禪房花木深」之句，以為不可及。予絕喜李頎詩雲：「遠客坐長夜，雨聲孤寺秋。請量東海水，看取淺深愁。」且作客涉遠，適當窮秋，暮投孤村古寺中，夜不能寐，起坐凄惻，而聞簷外雨聲，其為一時襟抱，不言可知，而此兩句十字中，盡其意態，海水喻愁，非過語也。","sortOrder":7},
  {"id":"s_work_dtbt_6_8","chapterId":"ch_work_dtbt_6","text":"詩中用茱萸字","sortOrder":8},
  {"id":"s_work_dtbt_6_9","chapterId":"ch_work_dtbt_6","text":"劉夢得雲：「詩中用茱萸字者凡三人。杜甫雲『醉把茱萸子細看』，王維雲『插遍茱萸少一人』，朱放雲『學他年少插茱萸』，三君所用，杜公為優。」予觀唐人七言，用此者又十餘家，漫錄於後。王昌齡「茱萸插鬢花宜壽」，戴叔倫「插鬢茱萸來未盡」，盧綸「茱萸一朵映華簪」，權德輿「酒泛茱萸晚易曛」，白居易「舞鬟擺落茱萸房」，「茱萸色淺未經霜」，楊衡「強插茱萸隨衆人」，張諤「茱萸凡作幾年新」，耿湋「髮稀那敢插茱萸」，劉商「郵筒不解獻茱萸」，崔櫓「茱萸冷吹溪口香」，周賀「茱萸城裏一尊前」，比之杜句，真不侔矣。","sortOrder":9},
  {"id":"s_work_dtbt_6_10","chapterId":"ch_work_dtbt_6","text":"鬼宿渡河","sortOrder":10},
  {"id":"s_work_dtbt_6_11","chapterId":"ch_work_dtbt_6","text":"宋蒼梧王當七夕夜，令楊玉夫伺織女渡河，曰：「見，當報我；不見，當殺汝。」錢希白洞微志載：「蘇德哥為徐肇祀其先人，曰：『當夜半可已。』蓋俟鬼宿渡河之後。」翟公巽作祭儀十卷，雲：「或祭於昏，或祭於旦，皆非是，當以鬼宿渡河為候，而鬼宿渡河，常在中夜，必使人仰占以俟之。」葉少蘊雲：「公巽博學多聞，援證皆有據，不肯碌碌同衆，所見必過人。」予按天上經星終古不動，鬼宿隨天西行，春昏見於南，夏晨見於東，秋夜半見於東，冬昏見於東，安有所謂渡河及常在中夜之理？織女昏晨與鬼宿正相反，其理則同。蒼梧王荒悖小兒，不足笑，錢、翟、葉三公皆名儒碩學，亦不深考如此。杜詩雲：「牛女漫愁思，秋期猶渡河，」「牛女年年渡，何曾風浪生？」梁劉孝儀詩雲：「欲待黃昏至，含嬌淺渡河。」唐人七夕詩皆有此說，此自是牽俗遣詞之過，故杜老又有詩雲：「牽牛出河西，織女處其東。萬古永相望，七夕誰見同。神光竟難候，此事終蒙朧。」蓋自洞曉其實，非他人比也。","sortOrder":11},
  {"id":"s_work_dtbt_6_12","chapterId":"ch_work_dtbt_6","text":"府名軍額","sortOrder":12},
  {"id":"s_work_dtbt_6_13","chapterId":"ch_work_dtbt_6","text":"雍州，軍額曰永興，府曰京兆，而守臣以「知永興軍府事兼京兆府路安撫使」結銜。鎮州，軍額曰成德，府曰真定，而守臣以「知成德軍府事兼真定府路安撫使」結銜，政和中，始正以府額為稱。荊州，軍額曰荊南，府曰江陵，而守臣則曰「知荊南」，通判曰「通判荊南」，自餘掾幕縣官則曰「江陵府」，淳熙四年，始盡以「江陵」為稱。孟州，軍額曰河陽三城，無府額，而守臣曰「知河陽軍州事」。陝州無府額，而守臣曰「知陝州軍府事」，法令行移，亦曰「陝府」。","sortOrder":13},
  {"id":"s_work_dtbt_6_14","chapterId":"ch_work_dtbt_6","text":"馬融皇甫規","sortOrder":14},
  {"id":"s_work_dtbt_6_15","chapterId":"ch_work_dtbt_6","text":"漢順帝時，西羌叛，遣征西將軍馬賢將十萬人討之。武都太守馬融上疏曰：「賢處處留滯，必有潰叛之變。臣願請賢所不用關東兵五千，裁假部隊之號，盡力率厲，三旬之中必克破之。」不從。賢果與羌戰敗，父子皆沒，羌遂寇三輔，燒園陵。詔武都太守趙沖督河西四郡兵追擊。安定上計掾皇甫規上疏曰：「臣比年以來，數陳便宜：羌戎未動，策其將反；馬賢始出，知其必敗。願假臣屯列坐食之兵五千，出其不意，與沖共相首尾。土地山穀，臣所曉習，可不煩方寸之印，尺帛之賜，可以滌患。」帝不能用。趙沖擊羌不利，羌寇充斥，涼部震恐，沖戰死，累年然後定。按馬融、皇甫規之言曉然易見，而所請兵皆不過五千，然訖不肯從，乃知宣帝納用趙充國之冊為不易得，所謂明主可為忠言也。","sortOrder":15},
  {"id":"s_work_dtbt_6_16","chapterId":"ch_work_dtbt_6","text":"孟蜀避唐諱","sortOrder":16},
  {"id":"s_work_dtbt_6_17","chapterId":"ch_work_dtbt_6","text":"蜀本石九經皆孟昶時所刻，其書「淵世民」三字皆缺畫，蓋為唐高祖、太宗諱也。昶父知祥，嘗為莊宗、明宗臣，然於「存勖嗣源」字乃不諱。前蜀王氏已稱帝，而其所立龍興寺碑，言及唐諸帝，亦皆半闕，乃知唐之澤遠矣。","sortOrder":17},
  {"id":"s_work_dtbt_6_18","chapterId":"ch_work_dtbt_6","text":"翰苑親近","sortOrder":18},
  {"id":"s_work_dtbt_6_19","chapterId":"ch_work_dtbt_6","text":"白樂天渭村退居寄錢翰林詩，敍翰苑之親近雲：「曉從朝興慶，春陪宴柏梁。分庭皆命婦，對院即儲皇。貴主冠浮動，親王轡鬧裝。金鈿相照耀，朱紫間熒煌。毬簇桃花騎，歌巡竹葉觴。窪銀中貴帶，昂黛內人妝。賜禊東城下，頒酺曲水傍。樽罍分聖酒，妓樂借仙倡。」蓋唐世宮禁與外廷不至相隔絕，故杜子美詩：「戶外昭容紫袖垂，雙瞻御座引朝儀。」又雲：「舍人退食收封事，宮女開函近御筵。」而學士獨稱內相，至於與命婦分庭，見貴主冠服、內人黛妝，假仙倡以佐酒，他司無比也。","sortOrder":19},
  {"id":"s_work_dtbt_6_20","chapterId":"ch_work_dtbt_6","text":"寧馨阿堵","sortOrder":20},
  {"id":"s_work_dtbt_6_21","chapterId":"ch_work_dtbt_6","text":"「寧馨」、「阿堵」，晉宋間人語助耳。後人但見王衍指錢雲：「舉阿堵物却。」又山濤見衍曰：「何物老媼生寧馨兒？」今遂以阿堵為錢，寧馨兒為佳兒，殊不然也。前輩詩「語言少味無阿堵，冰雪相看有此君」，又「家無阿堵物，門有寧馨兒」，其意亦如此。宋廢帝之母王太後疾篤，帝不往視，後怒謂侍者：「取刀來剖我腹，那得生寧馨兒！」觀此，豈得為佳？顧長康畫人物，不點目睛，曰：「傳神寫照正在阿堵中。」猶言「此處」也。劉真長譏殷淵源曰：「田舍兒，強學人作爾馨語。」又謂桓溫曰：「使君，如馨地寧可鬥戰求勝？」王導與何充語曰：「正自爾馨。」王恬撥王胡之手曰：「冷如鬼手馨，強來捉人臂。」至今吳中人語言尚多用寧馨字為問，猶言「若何」也。劉夢得詩：「為問中華學道者，幾人雄猛得寧馨。」蓋得其義。以寧字作平聲讀。","sortOrder":21},
  {"id":"s_work_dtbt_6_22","chapterId":"ch_work_dtbt_6","text":"鳳毛","sortOrder":22},
  {"id":"s_work_dtbt_6_23","chapterId":"ch_work_dtbt_6","text":"宋孝武嗟賞謝鳳之子超宗曰：「殊有鳳毛。」今人以子為鳳毛，多謂出此。按世說，王劭風姿似其父導，桓溫曰：「大奴固自有鳳毛。」其事在前，與此不同。","sortOrder":23},
  {"id":"s_work_dtbt_6_24","chapterId":"ch_work_dtbt_6","text":"牛米","sortOrder":24},
  {"id":"s_work_dtbt_6_25","chapterId":"ch_work_dtbt_6","text":"燕慕容皝以牛假貧民，使佃苑中，稅其什之八；自有牛者，稅其七。參軍封裕諫，以為魏、晉之世，假官田牛者不過稅其什六，自有牛者中分之，不取其七八也。予觀今吾鄉之俗，募人耕田，十取其五，而用主牛者，取其六，謂之牛米，蓋晉法也。","sortOrder":25},
  {"id":"s_work_dtbt_6_26","chapterId":"ch_work_dtbt_6","text":"為文矜誇過實","sortOrder":26},
  {"id":"s_work_dtbt_6_27","chapterId":"ch_work_dtbt_6","text":"文士為文，有矜誇過實，雖韓文公不能免。如石鼓歌極道宣王之事偉矣，至雲：「孔子西行不到秦，掎摭星宿遺羲娥。陋儒編詩不收拾，二雅褊迫無委蛇。」是謂三百篇皆如星宿，獨此詩如日月也。「二雅褊迫」之語，尤非所宜言。今世所傳石鼓之詞尚在，豈能出吉日、車攻之右？安知非經聖人所刪乎？","sortOrder":27},
  {"id":"s_work_dtbt_6_28","chapterId":"ch_work_dtbt_6","text":"送孟東野序","sortOrder":28},
  {"id":"s_work_dtbt_6_29","chapterId":"ch_work_dtbt_6","text":"韓文公送孟東野序雲：「物不得其平則鳴。」然其文雲：「在唐、虞時，咎陶、禹其善鳴者，而假之以鳴。夔假於韶以鳴，伊尹鳴殷，周公鳴周。」又雲：「天將和其聲，而使鳴國家之盛。」然則非所謂不得其平也。","sortOrder":29},
  {"id":"s_work_dtbt_6_30","chapterId":"ch_work_dtbt_6","text":"噴嚏","sortOrder":30},
  {"id":"s_work_dtbt_6_31","chapterId":"ch_work_dtbt_6","text":"今人噴嚏不止者，必噀唾祝雲「有人說我」，婦人尤甚。予按終風詩：「寤言不寐，願言則嚏。」鄭氏箋雲：「我其憂悼而不能寐，女思我心如是，我則嚏也。今俗人嚏，雲『人道我』，此古之遺語也。」乃知此風自古以來有之。","sortOrder":31},
  {"id":"s_work_dtbt_6_32","chapterId":"ch_work_dtbt_6","text":"野史不可信","sortOrder":32},
  {"id":"s_work_dtbt_6_33","chapterId":"ch_work_dtbt_6","text":"野史雜說，多有得之傳聞及好事者緣飾，故類多失實，雖前輩不能免，而士大夫頗信之。姑摭真宗朝三事於左。","sortOrder":33},
  {"id":"s_work_dtbt_6_34","chapterId":"ch_work_dtbt_6","text":"魏泰東軒錄雲：「真宗次澶淵，語寇萊公曰：『虜騎未退，何人可守天雄軍？』公言參知政事王欽若。退即召王於行府，諭以上意，授敕俾行。王未及有言，公遽酌大白飲之，命曰『上馬杯』，且曰：『參政勉之，回日即為同列也。』王馳騎入魏，越十一日虜退，召為同中書門下平章事。或雲王公數進疑詞於上前，故萊公因事出之。」予按澶淵之役乃景德元年九月，是時萊公為次相，欽若為參政；閏九月，欽若判天雄，二年四月，罷政；三年，萊公罷相，欽若復知樞密院，至天禧元年始拜相，距景德初元凡十四年。","sortOrder":34},
  {"id":"s_work_dtbt_6_35","chapterId":"ch_work_dtbt_6","text":"其二事者，沈括筆談雲：「向文簡拜右僕射，真宗謂學士李昌武曰：『朕自即位以來，未嘗除僕射，敏中應甚喜。』昌武退朝，往候之，門闌悄然。明日再對，上笑曰：『向敏中大耐官職。』」存中自註雲：「向公拜僕射，年月未曾考於國史，因見中書記，是天禧元年八月，而是年二月王欽若亦加僕射。」予按真宗朝自敏中之前拜僕射者六人：呂端、李沆、王旦皆自宰相轉，陳堯叟以罷樞密使拜，張齊賢以故相拜，王欽若自樞密使轉。及敏中轉右僕射，與欽若加左僕射同日降製，是時李昌武死四年矣。昌武者，宗諤也。","sortOrder":35},
  {"id":"s_work_dtbt_6_36","chapterId":"ch_work_dtbt_6","text":"其三事者，存中筆談又雲：「時丁晉公從真宗巡幸，禮成，詔賜輔臣玉帶。時輔臣八人，行在祗候庫止有七帶，尚衣有帶，謂之『比玉』，價直數百萬，上欲以足其數。公心欲之，而位在七人之下，度必不及己，乃諭有司：『某自有小私帶可服，候還京別賜可也。』既各受賜，而晉公一帶僅如指闊，上顧近侍速易之，遂得尚衣御帶。」予按景德元年，真宗巡幸西京，大中祥符元年，巡幸泰山，四年，幸河中，丁謂皆為行在三司使，未登政府。七年，幸亳州，謂始以參知政事從。時輔臣六人，王旦、向敏中為宰相，王欽若、陳堯叟為樞密使，皆在謂上，謂之下尚有樞密副使馬知節，即不與此說合。且既為玉帶，而又名「比玉」，尤可笑。魏泰無足論，沈存中不應爾也。(「越十一日」，一作「越七日」。)","sortOrder":36},
  {"id":"s_work_dtbt_6_37","chapterId":"ch_work_dtbt_6","text":"謗書","sortOrder":37},
  {"id":"s_work_dtbt_6_38","chapterId":"ch_work_dtbt_6","text":"司馬遷作史記，於封禪書中述武帝神仙、鬼竈、方士之事甚備，故王允謂之謗書。國朝景德、祥符間，治安之極，王文穆、陳文忠、陳文僖、丁晉公諸人造作天書符瑞，以為固寵容悅之計。及真宗上仙，王沂公懼貽後世譏議，故請藏天書於梓宮以滅跡。而實錄之成，乃文穆監修，其載崇奉宮廟，祥雲芝鶴，唯恐不詳，遂為信史之累，蓋與太史公謗書意異而實同也。","sortOrder":38},
  {"id":"s_work_dtbt_6_39","chapterId":"ch_work_dtbt_6","text":"王文正公","sortOrder":39},
  {"id":"s_work_dtbt_6_40","chapterId":"ch_work_dtbt_6","text":"祥符以後，凡天書禮文、宮觀典冊、祭祀巡幸、祥瑞頌聲之事，王文正公旦實為參政宰相，無一不預。官自侍郎至太保，公心知得罪於清議，而固戀患失，不能决去。及其臨終，乃欲削髮僧服以斂，何所補哉？魏野贈詩，所謂「西祀東封今已了，好來相伴赤松遊」，可謂君子愛人以德，其箴戒之意深矣。歐陽公神道碑，悉隱而不書，蓋不可書也。雖持身公清，無一可議，然特張禹、孔光、胡廣之流雲。","sortOrder":40},
  {"id":"s_work_dtbt_6_41","chapterId":"ch_work_dtbt_6","text":"晉文公","sortOrder":41},
  {"id":"s_work_dtbt_6_42","chapterId":"ch_work_dtbt_6","text":"晉公子重耳自狄適他國凡七，衞成公、曹共公、鄭文公皆不禮焉，齊桓公妻以女，宋襄公贈以馬，楚成王享之，秦穆公納之，卒以得國。衞、曹、鄭皆同姓，齊、宋、秦、楚皆異姓，非所謂「豈無他人，不如同姓」也。晉文公卒未葬，秦師伐鄭滅滑，無預晉事，晉先軫以為秦不哀吾喪，而伐吾同姓，背秦大惠，使襄公墨衰絰而伐之。雖幸勝於殽，終啟焚舟之戰，兩國交兵，不復修睦者數百年。先軫是年死於狄，至孫縠而誅滅，天也。","sortOrder":42},
  {"id":"s_work_dtbt_6_43","chapterId":"ch_work_dtbt_6","text":"南夷服諸葛","sortOrder":43},
  {"id":"s_work_dtbt_6_44","chapterId":"ch_work_dtbt_6","text":"蜀劉禪時，南中諸郡叛，諸葛亮征之，孟獲為夷漢所服，七戰七擒，曰：「公，天威也，南人不復反矣。」蜀志所載，止於一時之事。國朝淳化中，李順亂蜀，招安使雷有終遣嘉州士人辛怡顯使於南詔，至姚州，其節度使趙公美以書來迎，雲：「當境有瀘水，昔諸葛武侯戒曰：『非貢獻征討，不得輒渡此水；若必欲過，須致祭，然後登舟。』今遣本部軍將賫金龍二條、金錢二千文幷設酒脯，請先祭享而渡。」乃知南夷心服，雖千年如初。嗚呼，可謂賢矣！事見怡顯所作雲南錄。","sortOrder":44},
  {"id":"s_work_dtbt_6_45","chapterId":"ch_work_dtbt_6","text":"二疏贊","sortOrder":45},
  {"id":"s_work_dtbt_6_46","chapterId":"ch_work_dtbt_6","text":"作議論文字，須考引事實無差忒，乃可傳信後世。東坡先生作二疏圖贊雲：「孝宣中興，以法馭人。殺蓋、韓、楊，蓋三良臣。先生憐之，振袂脫屣。使知區區，不足驕士。」其立意超卓如此。然以其時考之，元康三年二疏去位，後二年蓋寬饒誅，又三年韓延壽誅，又三年楊惲誅。方二疏去時，三人皆亡恙。蓋先生文如傾河，不復效常人尋閱質究也。","sortOrder":46},
  {"id":"s_work_dtbt_6_47","chapterId":"ch_work_dtbt_6","text":"李宓伐南詔","sortOrder":47},
  {"id":"s_work_dtbt_6_48","chapterId":"ch_work_dtbt_6","text":"唐天寶中，南詔叛，劍南節度使鮮於仲通討之，喪士卒六萬人。楊國忠掩其敗狀，仍敍其戰功。時募兵擊南詔，人莫肯應募，國忠遣御史分道捕人，連枷送詣軍所，行者愁怨，所在哭聲振野。至十三載，劍南留後李宓將兵七萬往擊南詔。南詔誘之深入，閉壁不戰，宓糧盡，士卒瘴疫及饑死什七八，乃引還。蠻追擊之，宓被擒，全軍皆沒。國忠隱其敗，更以捷聞，益發兵討之。此通鑑所紀。舊唐書雲：「李宓率兵擊蠻於西洱河，糧盡軍旋，馬足陷橋，為閤羅鳳所擒。」新唐書亦雲：「宓敗死於西洱河。」予按高適集中有李宓南征蠻詩一篇，序雲：「天寶十一載，有詔伐西南夷，丞相楊公兼節製之寄，乃奏前雲南太守李宓涉海自交趾擊之，往復數萬里，十二載四月，至於長安。君子是以知廟堂使能，而李公效節。予忝斯人之舊，因賦是詩。」其略曰：「肅穆廟堂上，深沉節製雄。遂令感激士，得建非常功。鼓行天海外，轉戰蠻夷中。長驅大浪破，急擊羣山空。餉道忽已遠，縣軍垂欲窮。野食掘田鼠，晡餐兼僰僮。收兵列亭候，拓地彌西東。瀘水夜可涉，交州今始通。歸來長安道，召見甘泉宮。」其所稱述如此，雖詩人之言未必皆實，然當時之人所賦，其事不應虛言，則宓蓋歸至長安，未嘗敗死，其年又非十三載也。味詩中掘鼠餐僮之語，則知糧盡危急，師非勝歸明甚。","sortOrder":48},
  {"id":"s_work_dtbt_6_49","chapterId":"ch_work_dtbt_6","text":"浮梁陶器","sortOrder":49},
  {"id":"s_work_dtbt_6_50","chapterId":"ch_work_dtbt_6","text":"彭器資尚書文集有送許屯田詩，曰：「浮梁巧燒，顏色比瓊玖。因官射利疾，衆喜君獨不。父老爭嘆息，此事古未有。」註雲：「浮梁父老言，自來作知縣不買器者一人，君是也。作饒州不買者一人，今程少卿嗣宗是也。」惜乎不載許君之名。","sortOrder":50},
  {"id":"s_work_dtbt_6_51","chapterId":"ch_work_dtbt_6","text":"容齋隨筆","sortOrder":51},
  {"id":"s_work_dtbt_7_1","chapterId":"ch_work_dtbt_7","text":"卷第五(二十五則)","sortOrder":1},
  {"id":"s_work_dtbt_7_2","chapterId":"ch_work_dtbt_7","text":"漢唐八相","sortOrder":2},
  {"id":"s_work_dtbt_7_3","chapterId":"ch_work_dtbt_7","text":"蕭、曹、丙、魏、房、杜、姚、宋為漢、唐名相，不待誦說。然前六君子皆終於位，而姚、宋相明皇，皆不過三年。姚以二子及親吏受賂，其罷猶有說，宋但以嚴禁惡錢及疾負罪而妄訴不已者，明皇用優人戲言而罷之，二公終身不復用。宋公罷相時，年才五十八，後十七年乃薨。繼之者如張嘉貞、張說、源乾曜、王晙、宇文融、裴光庭、蕭嵩、牛仙客，其才可睹矣。唯杜暹、李元紘為賢，亦清介齪齪自守者。釋騏驥而不乘，焉皇皇而更索，可不惜哉！蕭何且死，所推賢唯曹參；魏、丙同心輔政；房喬每議事，必曰非如晦莫能籌之；姚崇避位，薦宋公自代。唯賢知賢，宜後人之莫及也。","sortOrder":3},
  {"id":"s_work_dtbt_7_4","chapterId":"ch_work_dtbt_7","text":"六卦有坎","sortOrder":4},
  {"id":"s_work_dtbt_7_5","chapterId":"ch_work_dtbt_7","text":"易乾、坤二卦之下，繼之以屯、蒙、需、訟、師、比，六者皆有坎，聖人防患備險之意深矣！","sortOrder":5},
  {"id":"s_work_dtbt_7_6","chapterId":"ch_work_dtbt_7","text":"晉之亡與秦隋異","sortOrder":6},
  {"id":"s_work_dtbt_7_7","chapterId":"ch_work_dtbt_7","text":"自堯、舜及今，天下裂而復合者四：周之末為七戰國，秦合之；漢之末分為三國，晉合之；晉之亂分為十餘國，爭戰三百年，隋合之；唐之後又分為八九國，本朝合之。然秦始皇一傳而為胡亥，晉武帝一傳而為惠帝，隋文帝一傳而為煬帝，皆破亡其社稷。獨本朝九傳百七十年，乃不幸有靖康之禍，蓋三代以下治安所無也。秦、晉、隋皆相似，然秦、隋一亡即掃地，晉之東雖曰「牛繼馬後」，終為守司馬氏之祀，亦百有餘年。蓋秦、隋毒流四海，天實誅之，晉之八王擅兵，孽後盜政，皆本於惠帝昏蒙，非得罪於民，故其亡也，與秦、隋獨異。","sortOrder":7},
  {"id":"s_work_dtbt_7_8","chapterId":"ch_work_dtbt_7","text":"上官桀","sortOrder":8},
  {"id":"s_work_dtbt_7_9","chapterId":"ch_work_dtbt_7","text":"漢上官桀為未央廄令，武帝嘗體不安，及愈，見馬，馬多瘦，上大怒：「令以我不復見馬邪？」欲下吏，桀頓首曰：「臣聞聖體不安，日夜憂懼，意誠不在馬。」言未卒，泣數行下。上以為忠，由是親近，至於受遺詔輔少主。義縱為右內史，上幸鼎湖，病久，已而卒起幸甘泉，道不治，上怒曰：「縱以我為不行此道乎？」銜之，遂坐以他事棄市。二人者其始獲罪一也，桀以一言之故超用，而縱及誅，可謂幸不幸矣。","sortOrder":9},
  {"id":"s_work_dtbt_7_10","chapterId":"ch_work_dtbt_7","text":"金日磾","sortOrder":10},
  {"id":"s_work_dtbt_7_11","chapterId":"ch_work_dtbt_7","text":"金日磾沒入宮，輸黃門養馬。武帝遊宴見馬，後宮滿側，日磾等數十人牽馬過殿下，莫不竊視，至日磾，獨不敢。日磾容貌甚嚴，馬又肥好，上奇焉，即日拜為馬監，後受遺輔政。日磾與上官桀皆因馬而受知，武帝之取人，可謂明而不遺矣。","sortOrder":11},
  {"id":"s_work_dtbt_7_12","chapterId":"ch_work_dtbt_7","text":"漢宣帝忌昌邑王","sortOrder":12},
  {"id":"s_work_dtbt_7_13","chapterId":"ch_work_dtbt_7","text":"漢廢昌邑王賀而立宣帝，賀居故國，帝心內忌之，賜山陽太守張敞璽書，戒以謹備盜賊。敞條奏賀居處，著其廢亡之效。上知賀不足忌，始封為列侯。光武廢太子彊為東海王而立顯宗，顯宗即位，待彊彌厚。宣、顯皆雜霸道，治尚剛嚴，獨此事顯優於宣多矣。","sortOrder":13},
  {"id":"s_work_dtbt_7_14","chapterId":"ch_work_dtbt_7","text":"平津侯","sortOrder":14},
  {"id":"s_work_dtbt_7_15","chapterId":"ch_work_dtbt_7","text":"公孫平津本傳稱其意忌內深，殺主父偃，徙董仲舒，皆其力。然其可稱者兩事：武帝置蒼海、朔方之郡，平津數諫，以為罷弊中國以奉無用之地，願罷之。上使朱買臣等難之，乃謝曰：「山東鄙人，不知其便若是，願罷西南夷專奉朔方。」上乃許之。卜式上書，願輸家財助邊，蓋迎合主意。上以語平津，對曰：「此非人情，不軌之臣不可以為化而亂法，願勿許。」乃罷式。當武帝好大喜功而能如是，概之後世，足以為賢相矣！惜不以式事載本傳中。","sortOrder":15},
  {"id":"s_work_dtbt_7_16","chapterId":"ch_work_dtbt_7","text":"韓信周瑜","sortOrder":16},
  {"id":"s_work_dtbt_7_17","chapterId":"ch_work_dtbt_7","text":"世言韓信伐趙，趙廣武君請以奇兵塞井陘口，絕其糧道，成安君不聽。信使間人窺知其不用廣武君策，還報，則大喜，乃敢引兵遂下，遂勝趙。使廣武計行，信且成禽，信蓋自言之矣。周瑜拒曹公於赤壁，部將黃蓋獻火攻之策，會東南風急，悉燒操船，軍遂敗。使天無大風，黃蓋不進計，則瑜未必勝。是二說者，皆不善觀人者也。夫以韓信敵陳餘，猶以猛虎當羊豕爾。信與漢王語，請北舉燕、趙，正使井陘不得進，必有他奇策矣。其與廣武君言曰：「向使成安君聽子計，僕亦禽矣。」蓋謙以求言之詞也。方孫權問計於周瑜，瑜已言操冒行四患，將軍禽之宜在今日。劉備見瑜，恨其兵少。瑜曰：「此自足用，豫州但觀瑜破之。」正使無火攻之說，其必有以製勝矣。不然，何以為信、瑜？","sortOrder":17},
  {"id":"s_work_dtbt_7_18","chapterId":"ch_work_dtbt_7","text":"漢武賞功明白","sortOrder":18},
  {"id":"s_work_dtbt_7_19","chapterId":"ch_work_dtbt_7","text":"衞青為大將軍，霍去病始為校尉，以功封侯，青失兩將軍，亡翕侯，功不多，不益封。其後各以五萬騎深入，去病益封五千八百戶，裨校封侯益邑者六人，而青不得益封，吏卒無封者。武帝賞功，必視法如何，不以貴賤為高下，其明白如此。後世處此，必曰青久為上將，俱出塞致命，正不厚賞，亦當有以慰其心，不然，他日無以使人，蓋失之矣。","sortOrder":19},
  {"id":"s_work_dtbt_7_20","chapterId":"ch_work_dtbt_7","text":"周召房杜","sortOrder":20},
  {"id":"s_work_dtbt_7_21","chapterId":"ch_work_dtbt_7","text":"召公為保，周公為師，相成王為左右。觀此二相，則刑措四十年，頌聲作於下，不言可知。唐貞觀三年二月，房玄齡為左僕射，杜如晦為右僕射，魏徵參預朝政。觀此三相，則三百年基業之盛，概可見矣。","sortOrder":21},
  {"id":"s_work_dtbt_7_22","chapterId":"ch_work_dtbt_7","text":"三代書同文","sortOrder":22},
  {"id":"s_work_dtbt_7_23","chapterId":"ch_work_dtbt_7","text":"三代之時，天下書同文，故春秋左氏所載人名字，不以何國，大抵皆同。鄭公子歸生，魯公孫歸父，蔡公孫歸生，楚仲歸，齊析歸父，皆字子家。楚成嘉，鄭公子嘉，皆字子孔。鄭公孫段、印段，宋褚師段，皆字子石。鄭公子喜，宋樂喜，皆字子罕。楚公子黑肱，鄭公孫黑，孔子弟子狄黑，皆字子晳。魯公子翬，鄭公孫揮，皆字子羽。邾子克，楚鬭克，周王子克，宋司馬之臣克，皆字曰儀。晉籍偃，荀偃，鄭公子偃，吳言偃，皆字曰遊。晉羊舌赤，魯公西赤，皆字曰華。楚公子側，魯孟之側，皆字曰反。魯冉耕，宋司馬耕，皆字曰牛。顏無繇、仲由，皆字曰路。","sortOrder":23},
  {"id":"s_work_dtbt_7_24","chapterId":"ch_work_dtbt_7","text":"周世中國地","sortOrder":24},
  {"id":"s_work_dtbt_7_25","chapterId":"ch_work_dtbt_7","text":"成周之世，中國之地最狹，以今地里考之，吳、越、楚、蜀、閩皆為蠻；淮南為羣舒；秦為戎。河北真定、中山之境，乃鮮虞、肥、鼓國。河東之境，有赤狄、甲氏、留吁、鐸辰、潞國。洛陽為王城，而有楊拒、泉臯、蠻氏、陸渾、伊雒之戎。京東有萊、牟、介、莒，皆夷也。（木巳）都雍丘，今汴之屬邑，亦用夷禮。邾近於魯，亦曰夷。其中國者，獨晉、衞、齊、魯、宋、鄭、陳、許而已，通不過數十州，蓋於天下特五分之一耳。","sortOrder":25},
  {"id":"s_work_dtbt_7_26","chapterId":"ch_work_dtbt_7","text":"李後主梁武帝","sortOrder":26},
  {"id":"s_work_dtbt_7_27","chapterId":"ch_work_dtbt_7","text":"東坡書李後主去國之詞雲：「『最是蒼皇辭廟日，教坊猶奏別離歌，揮淚對宮娥。』以為後主失國，當慟哭於廟門之外，謝其民而後行，乃對宮娥聽樂，形於詞句。」予觀梁武帝啟侯景之禍，塗炭江左，以致覆亡，乃曰：「自我得之，自我失之，亦復何恨。」其不知罪己亦甚矣！竇嬰救灌夫，其夫人諫止之，嬰曰：「侯自我得之，自我捐之，無所恨。」梁武用此言而非也。","sortOrder":27},
  {"id":"s_work_dtbt_7_28","chapterId":"ch_work_dtbt_7","text":"詩什","sortOrder":28},
  {"id":"s_work_dtbt_7_29","chapterId":"ch_work_dtbt_7","text":"詩二雅及頌前三卷題曰：「某詩之什。」陸德明釋雲：「歌詩之作，非止一人，篇數既多，故以十篇編為一卷，名之為什。」今人以詩為篇什，或稱譽他人所作為佳什，非也。","sortOrder":29},
  {"id":"s_work_dtbt_7_30","chapterId":"ch_work_dtbt_7","text":"易舉正","sortOrder":30},
  {"id":"s_work_dtbt_7_31","chapterId":"ch_work_dtbt_7","text":"唐蘇州司戶郭京有周易舉正三卷，雲：「曾得王輔嗣、韓康伯手寫註定傳授真本，比校今世流行本及國學、鄉貢舉人等本，或將經入註，用註作經，小象中間以下句，反居其上，爻辭註內移，後義却處於前，兼有脫遺，兩字顛倒謬誤者，並依定本舉正其訛，凡一百三節。」今略取其明白者二十處載於此：坤初六：「履霜堅冰至。象曰：履霜，陰始凝也，馴致其道，至堅冰也。」今本於象文「霜」字下誤增「堅冰」二字。屯六三象曰：「即鹿無虞何？以從禽也。」今本脫「何」字。師六五：「田有禽，利執之，無咎。」元本「之」字行書向下引腳，稍類「言」字，轉寫相仍，故誤作「言」，觀註義亦全不作言字釋也。比九五象曰：「失前禽，舍逆取順也。」今本誤倒其句。賁：「亨，不利有攸往。」今本「不」字誤作「小」字。「剛柔交錯，天文也，文明以止，人文也。」註雲：「剛柔交錯而成文焉，天之文也。」今本脫「剛柔交錯」一句。坎卦「習坎」上脫「坎」字。姤：「九四，包失魚。」註：「二有其魚，故失之也。」今本誤作「一尢魚」。蹇：「九三，往蹇來正。」今本作「來反」。困初六象曰：「入於幽穀，不明也。」今本「穀」字下多「幽」字。鼎彖：「聖人亨以享上帝，以養聖賢。」註雲：「聖人用之，上以享上帝而下以養聖賢。」今本正文多「而大亨」三字，故註文亦誤增「大亨」二字。震彖曰：「不喪匕鬯，出可以守宗廟社稷，以為祭主也。」今本脫「不喪匕鬯」一句。漸象曰：「君子以居賢德，善風俗。」註雲：「賢德以止巽則居，風俗以止巽乃善。」今本正文脫「風」字。豐九四象：「遇其夷主，吉，志行也。」今文脫「志」字。中孚彖：「豚魚吉，信及也。」今本「及」字下多「豚魚」二字。小過彖：「柔得中，是以可小事也。」今本脫「可」字，而「事」字下誤增「吉」字。六五象曰：「密雲不雨，已止也。」註：「陽已止下故也。」今本正文作「已上」，故註亦誤作「陽已上故止也」。既濟彖曰：「既濟，亨小，小者亨也。」今本脫一「小」字。繫辭：「二多譽，四多懼。」註雲：「懼，近也。」今本誤以「近也」字為正文，而註中又脫「懼」字。雜卦：「蒙稚而著。」今本「稚」誤作「雜」字。予頃於福州道藏中見此書而傳之，及在後省見晁公武所進易解，多引用之，世罕有其書也。","sortOrder":31},
  {"id":"s_work_dtbt_7_32","chapterId":"ch_work_dtbt_7","text":"其惟聖人乎","sortOrder":32},
  {"id":"s_work_dtbt_7_33","chapterId":"ch_work_dtbt_7","text":"乾卦：「其惟聖人乎。」魏王肅本作「愚人」，後結句始作「聖人」，見陸德明釋文。","sortOrder":33},
  {"id":"s_work_dtbt_7_34","chapterId":"ch_work_dtbt_7","text":"易說卦","sortOrder":34},
  {"id":"s_work_dtbt_7_35","chapterId":"ch_work_dtbt_7","text":"易說卦荀爽九家集解乾「為木果」之下，更有四，曰：為龍，為車，為衣，為言。坤後有八，曰：為牝，為迷，為方，為囊，為裳，為黃，為帛，為漿。震後有三，曰：為王，為鵠，為鼓。巽後有二，曰：為楊，為鸛。坎後有八，曰：為宮，為律，為可，為棟，為叢棘，為狐，為蒺藜，為桎梏。離後有一，曰：為牝牛。艮後有三，曰：為鼻，為虎，為狐。兌後有二，曰：為常，為輔頰。註雲：「常，西方神也。」陸德明以其與王弼本不同，故載於釋文。按震為龍與乾同，故虞翻、幹寶本作駹。","sortOrder":35},
  {"id":"s_work_dtbt_7_36","chapterId":"ch_work_dtbt_7","text":"元二之災","sortOrder":36},
  {"id":"s_work_dtbt_7_37","chapterId":"ch_work_dtbt_7","text":"後漢鄧騭傳：「拜為大將軍，時遭元二之災，人士饑荒，死者相望，盜賊羣起，四夷侵畔。」章懷註雲：「元二即元元也，古書字當再讀者，即於上字之下為小二字，言此字當兩度言之。後人不曉，遂讀為元二，或同之陽九，或附之百六，良由不悟，致斯乖舛。今岐州石鼓銘，凡重言者皆為二字，明驗也。」漢碑有楊孟文石門頌雲：「中遭元二，西夷虐殘。」孔耽碑雲：「遭元二轗軻，人民相食。」趙明誠金石跋雲：「若讀為元元，不成文理，疑當時自有此語，漢註未必然也。」按王充論衡恢國篇雲：「今上嗣位，元二之間，嘉德布流。三年，零陵生芝草。四年，甘露降五縣。五年，芝復生。六年，黃龍見。」蓋章帝時事。考之本紀，所書建初三年以後諸瑞皆同，則知所謂元二者，謂建初元年、二年也。既稱嘉德布流以致祥瑞，其為非災眚之語，益可决疑。安帝永初元年、二年，先零滇羌寇叛，郡國地震、大水。鄧騭以二年十一月拜大將軍，則知所謂元二者，謂永初元年、二年也。凡漢碑重文不皆用小二字，豈有范史一部唯獨一處如此，予兄丞相作隸釋，論之甚詳。予修國史日，撰欽宗紀贊，用靖康元二之禍，實本於此。","sortOrder":37},
  {"id":"s_work_dtbt_7_38","chapterId":"ch_work_dtbt_7","text":"聖人汙","sortOrder":38},
  {"id":"s_work_dtbt_7_39","chapterId":"ch_work_dtbt_7","text":"孟子曰：「宰我、子貢、有若智足以知聖人。汙，不至阿其所好。」趙岐註雲：「三人之智足以識聖人。汙，下也。言三人雖小汙不平，亦不至於其所好，阿私所愛而空譽之。」詳其文意，足以識聖人是一句。汙，下也，自是一節。蓋以下字訓汙也，其義明甚。而老蘇先生乃作一句讀，故作三子知聖人汙論，謂：「三子之智，不足以及聖人高深幽絕之境，徒得其下焉耳。」此說竊謂不然，夫謂「夫子賢於堯、舜，自生民以來未有」，可謂大矣，猶以為汙下何哉？程伊川雲：「有若等自能知夫子之道，假使汙下，必不為阿好而言。」其說正與趙氏合。大抵漢人釋經子，或省去語助，如鄭氏箋毛詩「奄觀銍艾」雲：「奄，久。觀，多也。」蓋以久訓奄，以多訓觀。近者黃啟宗有補禮部韻略，於「淹」字下添「奄」字，註雲：「久觀也。」亦是誤以箋中五字為一句。","sortOrder":39},
  {"id":"s_work_dtbt_7_40","chapterId":"ch_work_dtbt_7","text":"廿（卉之中豎通底）卌字","sortOrder":40},
  {"id":"s_work_dtbt_7_41","chapterId":"ch_work_dtbt_7","text":"今人書二十字為廿，三十字為（卉之中豎通底），四十為卌，皆說文本字也。廿音入，二十幷也。（卉之中豎通底）音先合反，三十之省便，古文也。卌音先立反，數名，今直以為四十字。按秦始皇凡刻石頌德之辭，皆四字一句。泰山辭曰：「皇帝臨位，二十有六年。」琅邪臺頌曰：「維二十六年，皇帝作始。」之罘頌曰：「維二十九年，時在中春。」東觀頌曰：「維二十九年，皇帝春遊。」會稽頌曰：「德惠修長，三十有七年。」此史記所載，每稱年者，輒五字一句。嘗得泰山辭石本，乃書為「廿有六年」，想其餘皆如是，而太史公誤易之，或後人傳寫之訛耳，其實四字句也。","sortOrder":41},
  {"id":"s_work_dtbt_7_42","chapterId":"ch_work_dtbt_7","text":"字省文","sortOrder":42},
  {"id":"s_work_dtbt_7_43","chapterId":"ch_work_dtbt_7","text":"今人作字省文，以禮為禮，以處為処，以與為與，凡章奏及程文書冊之類不敢用，然其實皆說文本字也。許叔重釋禮字雲：「古文。」処字雲：「止也，得幾而止。或從處。」與字雲：「賜予也，與與同。」然則當以省文者為正。","sortOrder":43},
  {"id":"s_work_dtbt_7_44","chapterId":"ch_work_dtbt_7","text":"劍辟咡","sortOrder":44},
  {"id":"s_work_dtbt_7_45","chapterId":"ch_work_dtbt_7","text":"曲禮記童子事曰：「負劍辟咡詔之。」鄭氏註雲：「負，謂置之於背。劍，謂挾之於旁。辟咡詔之，謂傾頭與語。口旁曰咡。」歐陽公作其父瀧岡阡表雲：「回顧乳者劍汝而立於旁。」正用此義。今廬陵石刻由存，衢州所刊六一集，已得其真，或者不曉，遂易劍為抱，可嘆也！","sortOrder":45},
  {"id":"s_work_dtbt_7_46","chapterId":"ch_work_dtbt_7","text":"國初人至誠","sortOrder":46},
  {"id":"s_work_dtbt_7_47","chapterId":"ch_work_dtbt_7","text":"真宗時，幷州謀帥，上謂輔臣曰：「如張齊賢、溫仲舒皆可任，但以其嘗歷樞近，或有固辭，宜召至中書詢問，願往則授之。」及召二人至，齊賢辭以恐為人所讒。仲舒曰：「非敢有辭，但在尚書班已十年，若得改官端揆，賜都部署添給，敢不承命？」輔臣以聞，上曰：「是皆不欲往也，勿強之。」王元之自翰林學士以本官刑部郎中知黃州，遣其子嘉祐獻書於中書門下，以為：「朝廷設官，進退必以禮，一失錯置，咎在廊廟。某一任翰林學士，三任製誥舍人，以國朝舊事言之，或得給事中，或得侍郎，或為諫議大夫。某獨異於斯，斥去不轉一級，與錢穀俗吏，混然無別，執政不言，人將安仰？」予謂仲舒嘗為二府，至於自求遷轉及增請給；元之一代剛正名臣，至於公移牋書，引例乞轉。唯其至誠不矯偽故也。後之人外為大言，避寵辭祿，而陰有營求，失其本真者多矣，風俗使然也。","sortOrder":47},
  {"id":"s_work_dtbt_7_48","chapterId":"ch_work_dtbt_7","text":"史館玉牒所","sortOrder":48},
  {"id":"s_work_dtbt_7_49","chapterId":"ch_work_dtbt_7","text":"國朝熙寧以前，祕書省無著作局，故置史館，設修撰、直館之職。元豐官製行，有祕書官，則其職歸於監、少及著作郎、佐矣。而紹興中復置史館修撰、檢討，是與本省為二也。宗正寺修玉牒官亦然。官製既行，其職歸於卿、丞矣。而紹興中復差侍從為修牒，又以他官兼檢討，是與本寺為二也。然則今有戶部，可別置三司，有吏、刑部，可別置審官、審刑院矣。又玉牒舊製，每十年一進，謂甲子歲進書，則甲戌、甲申歲復然。今乃從建隆以來再行補修，每及十年則一進，以故不過三二年輒一行賞，書局僭賞，此最甚焉。","sortOrder":49},
  {"id":"s_work_dtbt_7_50","chapterId":"ch_work_dtbt_7","text":"稗沙門","sortOrder":50},
  {"id":"s_work_dtbt_7_51","chapterId":"ch_work_dtbt_7","text":"寶積經說僧之無行者曰：「譬如麥田，中生稗麥，其形似麥，不可分別。爾時田夫，作如是念，謂此稗麥，盡是好麥，後見穟生，爾乃知非。如是沙門，在於衆中，似是持戒有德行者。施主見時，謂盡是沙門，而彼癡人，實非沙門，是名稗沙門。」此喻甚佳，而文士鮮曾引用，聊志於此。","sortOrder":51},
  {"id":"s_work_dtbt_7_52","chapterId":"ch_work_dtbt_7","text":"容齋隨筆","sortOrder":52},
  {"id":"s_work_dtbt_8_1","chapterId":"ch_work_dtbt_8","text":"卷第六(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_8_2","chapterId":"ch_work_dtbt_8","text":"建武中元","sortOrder":2},
  {"id":"s_work_dtbt_8_3","chapterId":"ch_work_dtbt_8","text":"成都有漢蜀郡太守何君造尊楗閣碑，其末雲：「建武中元二年六月。」按范史本紀，建武止三十一年，次年改為中元，直書為中元元年。觀此所刻，乃是雖別為中元，猶冠以建武，如文、景帝中元、後元之類也。又祭祀志載封禪後赦天下詔，明言雲：「以建武三十二年為建武中元元年。」東夷倭國傳雲：「建武中元二年，來奉貢。」援據甚明。而宋莒公作紀年通譜乃雲：「紀、志所載不同，必傳寫脫誤。」學者失於精審，以意刪去，殆亦不深考耳。韓莊敏家一銅斗，銘雲：「新始建國、天鳳上戊六年。」又紹興中郭金州得一鉦，銘雲：「新始建國、地皇上戊二年。」按王莽始建國之後改天鳳，又改地皇，茲二器各冠以始元者，自莽之製如此，亦猶其改易郡名不常，每下詔猶繫其故名之類耳，不可用中元為比也。","sortOrder":3},
  {"id":"s_work_dtbt_8_4","chapterId":"ch_work_dtbt_8","text":"帶職人轉官","sortOrder":4},
  {"id":"s_work_dtbt_8_5","chapterId":"ch_work_dtbt_8","text":"紹興中，王浚明以右奉直大夫直祕閣，乞磨勘，吏部擬朝議大夫，時相以為既帶職，則朝議、奉直為一等，遂超轉中奉。其後曾慥踵之。紹興末，向伯奮亦用此，繼而續觱復然。後省有言，不應驀三級，自是但得朝議。予按故事，官製未行時，前行郎中遷少卿，有出身，得太常，無出身，司農。繼轉光祿，即今奉直、朝議也。自少卿遷大卿、監，有出身，得光祿卿，無出身，歷司農卿、少府監、衞尉卿，然後至光祿。若帶職，則自少農以上徑得光祿，不涉餘級，至有超五資者。然則浚明等不為過，蓋昔日職名不輕與人，故恩典亦異。又自承務郎至奉議詞人，但三轉，而帶職者乃與餘人同作六階不小異，乃有司之失也。","sortOrder":5},
  {"id":"s_work_dtbt_8_6","chapterId":"ch_work_dtbt_8","text":"上下四方","sortOrder":6},
  {"id":"s_work_dtbt_8_7","chapterId":"ch_work_dtbt_8","text":"上下四方不可窮竟，正雜莊、列、釋氏之寓言，曼衍不能說也。列子：「商湯問於夏革曰：『上下八方有極盡乎？』革曰：『不知也。』湯固問，革曰：『無則無極，有則有盡，朕何以知之？然無極之外，復無無極，無盡之中，復無無盡，無極復無無極，無盡復無無盡，朕是以知其無極無盡也，而不知其有極有盡也，焉知天地之表，不有大天地者乎？』」大集經：「『風住何處？』曰：『風住虛空。』又問：『虛空為何所住？』答言：『虛空住於至處。』又問：『至處復何所住？』答言：『至處何所住者，不可宣說，何以故？遠離一切諸處所故，一切處所所不攝故，非數非稱不可量故，是故至處無有住處。』」二家之說，如是而已。","sortOrder":7},
  {"id":"s_work_dtbt_8_8","chapterId":"ch_work_dtbt_8","text":"魏相蕭望之","sortOrder":8},
  {"id":"s_work_dtbt_8_9","chapterId":"ch_work_dtbt_8","text":"趙廣漢之死由魏相，韓延壽之死由蕭望之。魏、蕭賢公卿也，忍以其私陷二材臣於死地乎？楊惲坐語言怨望，而廷尉當以為大逆不道。以其時考之，乃於定國也。史稱定國為廷尉，民自以不寃，豈其然乎？宣帝治尚嚴，而三人者，又從而輔翼之，為可恨也！","sortOrder":9},
  {"id":"s_work_dtbt_8_10","chapterId":"ch_work_dtbt_8","text":"姓氏不可考","sortOrder":10},
  {"id":"s_work_dtbt_8_11","chapterId":"ch_work_dtbt_8","text":"姓氏所出，後世茫不可考，不過證以史傳，然要為難曉。自姚、虞、唐、杜、薑、田、范、劉之外，餘蓋紛然雜出。且以左傳言之：申氏出於四嶽，周有申伯，然鄭又有申侯，楚有申舟，又有申公巫臣，魯有申繻、申棖，晉有申書，齊有申鮮虞。賈氏姬姓之國，以國氏，然晉有賈華，又狐射姑亦曰賈季，齊有賈舉。黃氏嬴姓之國，然金天氏之後，又有沈、姒、蓐、黃之黃，晉有黃淵。孔氏出於商，孔子其後也。然衞有孔達，宋有孔父，鄭有孔叔，陳有孔寧，齊有孔虺，而鄭子孔之孫又為孔張。高氏出於齊，然子尾之後又為高彊，鄭有高克，宋有高哀。國氏亦出於齊，然邢有國子，鄭子國之孫又為國參。晉有慶鄭，齊有慶克，陳有慶虎。衞有石碏，齊有石之紛如，鄭有石（毚下之兔作大），周有石尚，宋有石彄。晉有陽處父，楚有陽丐，魯有陽虎。孫氏出於衞，而楚有叔敖，齊有孫書，吳有孫武。郭氏出於虢，而晉有郭偃，齊有郭最，又有所謂郭公者。千載之下，遙遙世祚，將安所質究乎？","sortOrder":11},
  {"id":"s_work_dtbt_8_12","chapterId":"ch_work_dtbt_8","text":"畏無難","sortOrder":12},
  {"id":"s_work_dtbt_8_13","chapterId":"ch_work_dtbt_8","text":"聖人不畏多難而畏無難，故曰：「惟有道之主能持勝。」使秦不幷六國，二世未亡；隋不一天下服四夷，煬帝不亡；苻堅不平涼取蜀、滅燕翦代，則無肥水之役；唐莊宗不滅梁下蜀，則無嗣源之禍；李景不取閩幷楚，則無淮南之失。","sortOrder":13},
  {"id":"s_work_dtbt_8_14","chapterId":"ch_work_dtbt_8","text":"綠竹青青","sortOrder":14},
  {"id":"s_work_dtbt_8_15","chapterId":"ch_work_dtbt_8","text":"毛公解衞詩淇奧，分綠竹為二物，曰：「綠，王芻也。竹，萹竹也。」韓詩：竹字作（萍之平作毒），音徒沃反，亦以為萹筑。郭璞雲：「王芻，今呼白腳莎，即菉蓐豆也。萹竹似小藜，赤莖節，好生道旁，可食。」又雲：「有草似竹，高五六尺，淇水側人謂之菉竹。」按此諸說，皆北人不見竹之語耳。漢書：「下淇園之竹以為揵。」寇恂為河內太守，伐淇園竹為矢百餘萬。衞詩又有「籊籊竹竿，以釣於淇」之句，所謂綠竹，豈不明甚，若白腳莎、菉豆，安得雲猗猗青青哉？","sortOrder":15},
  {"id":"s_work_dtbt_8_16","chapterId":"ch_work_dtbt_8","text":"孔子欲討齊","sortOrder":16},
  {"id":"s_work_dtbt_8_17","chapterId":"ch_work_dtbt_8","text":"陳成子弒齊簡公，孔子告於魯哀公，請討之。公曰：「告夫三子者。」之三子告，不可。左傳曰：「孔子請伐齊，公曰：『魯為齊弱久矣，子之伐之，將若之何？』對曰：『陳常弒其君，民之不與者半，以魯之衆，加齊之半，可伐也。』」說者以為孔子豈較力之強弱，但明其義而已。能順人心而行天討，何患不克？使魯君從之，孔子其使於周，請命乎天子，正名其罪。至其所以勝齊者，孔子之餘事也。予以為魯之不能伐齊，三子之不欲伐齊，周之不能討齊，通國知之矣。孔子為此舉，豈真欲以魯之半，力敵之哉？蓋是時三子無君與陳氏等，孔子上欲悟哀公，下欲警三子。使哀公悟其意，必察三臣之擅國，思有以製之，起孔子而付以政，其正君君、臣臣之分不難也。使三子者警，必將曰：魯小於齊，齊臣弒君而欲致討，吾三臣或如是，彼齊、晉大國，肯置而不問乎？惜其君臣皆不識聖人之深旨。自是二年，孔子亡，又十一年，哀公竟偪於三子而孫於越，比之簡公，僅全其身爾。","sortOrder":17},
  {"id":"s_work_dtbt_8_18","chapterId":"ch_work_dtbt_8","text":"韓退之","sortOrder":18},
  {"id":"s_work_dtbt_8_19","chapterId":"ch_work_dtbt_8","text":"舊唐史韓退之傳，初言：「愈常以為魏、晉已還，為文者多拘偶對，而經誥之指歸，不復振起。故所為文抒意立言，自成一家新語，後學之士取為師法。當時作者甚衆，無以過之，故世稱韓文。」而又雲：「時有恃才肆意，亦盭孔、孟之旨。若南人妄以柳宗元為羅池神，而愈撰碑以實之。李賀父名晉，不應進士，而愈為賀作諱辯，令舉進士。又為毛穎傳，譏戲不近人情。此文章之甚紕繆者。撰順宗實錄，繁簡不當，敍事拙於取捨，頗為當代所非。」裴晉公有寄李翱書曰：「昌黎韓愈，僕知之舊矣，其人信美材也。近或聞諸儕類雲：恃其絕足，往往奔放，不以文立製，而以文為戲。可矣乎？今之不及之者，當大為防焉爾。」舊史謂愈為紕繆，固不足責，晉公亦有是言，何哉？考公作此書時，名位猶未達，其末雲：「昨弟來，欲度及時幹進，度昔歲取名，不敢自高。今孤煢若此，遊宦謂何？是不能復從故人之所勉耳！但置力田園，苟過朝夕而已。」然則公出征淮西，請愈為行軍司馬，又令作碑，蓋在此累年之後，相知已深，非復前比也。","sortOrder":19},
  {"id":"s_work_dtbt_8_20","chapterId":"ch_work_dtbt_8","text":"誕節受賀","sortOrder":20},
  {"id":"s_work_dtbt_8_21","chapterId":"ch_work_dtbt_8","text":"唐穆宗即位之初年，詔曰：「七月六日，是朕載誕之辰，其日，百寮命婦宜於光順門進名參賀，朕於門內與百寮相見。」明日，又敕受賀儀宜停。先是，左丞韋綬奏行之，宰臣以古無降誕受賀之禮，奏罷之，然次年復行賀禮。誕節之製，起於明皇，令天下宴集休假三日，肅宗亦然，代、德、順三宗皆不置節名，及文宗以後，始置宴如初。則受賀一事，蓋自長慶年至今用之也。","sortOrder":21},
  {"id":"s_work_dtbt_8_22","chapterId":"ch_work_dtbt_8","text":"左氏書事","sortOrder":22},
  {"id":"s_work_dtbt_8_23","chapterId":"ch_work_dtbt_8","text":"左傳書晉惠公背秦穆公事曰：「晉侯之入也，秦穆姬屬賈君焉，且曰，盡納羣公子。晉侯烝於賈君，又不納羣公子，是以穆姬怨之；晉侯許賂中大夫，既而皆背之；賂秦伯以河外列城五，東盡虢略，南及華山，內及解梁城，既而不與；晉饑，秦輸之粟，秦饑，晉閉之糴。故秦伯伐晉。」觀此一節，正如獄吏治囚，蔽罪議法，而皋陶聽之，何所伏竄，不待韓原之戰，其曲直勝負之形見矣。晉厲公絕秦，數其五罪，書詞鏗訇，極文章鼓吹之妙，然其實皆誣秦。故傳又書雲：「秦桓公既與晉厲公為令狐之盟，而又召狄與楚，欲道以伐晉。」杜元凱註雲：「據此三事，以正秦罪。」左氏於文反復低昂，無所不究其至，觀秦、晉爭戰二事，可窺一斑矣。","sortOrder":23},
  {"id":"s_work_dtbt_8_24","chapterId":"ch_work_dtbt_8","text":"狐突言詞有味","sortOrder":24},
  {"id":"s_work_dtbt_8_25","chapterId":"ch_work_dtbt_8","text":"晉侯使太子申生伐東山皋落氏，以十二月出師，衣之偏衣，佩之金玦。左氏載狐突所嘆八十餘言，而詞義五轉。其一曰：「時，事之徵也。衣，身之章也。佩，衷之旗也。」其二曰：「敬其事，則命以始。服其身，則衣之純。用其衷，則佩之度。」其三曰：「今命以時卒，閟其事也。衣之尨服，遠其躬也。佩以金玦，棄其衷也。」其四曰：「服以遠之，時以閟之。」其五曰：「尨涼，冬殺，金寒，玦離。」其宛轉有味，皆可咀嚼。國語亦多此體，有至六七轉，然大抵緩而不切。","sortOrder":25},
  {"id":"s_work_dtbt_8_26","chapterId":"ch_work_dtbt_8","text":"宣髮","sortOrder":26},
  {"id":"s_work_dtbt_8_27","chapterId":"ch_work_dtbt_8","text":"考工記：「車人之事，半矩謂之宣。」註：「頭髮顥落曰宣。易：『巽為宣髮。』宣字本或作寡。」周易：「巽為寡髮。」釋文雲：「本又作宣，黑白雜為宣髮。」宣髮二字甚奇。","sortOrder":27},
  {"id":"s_work_dtbt_8_28","chapterId":"ch_work_dtbt_8","text":"邾文公楚昭王","sortOrder":28},
  {"id":"s_work_dtbt_8_29","chapterId":"ch_work_dtbt_8","text":"邾文公卜遷於繹，史曰：「利於民而不利於君。」邾子曰：「命在養民，死之短長，時也。民苟利矣，遷也吉莫如之。」遂遷於繹，未幾而卒。君子曰：「知命。」楚昭王之季年，有雲如衆赤鳥，夾日以飛三日。周太史曰：「其當王身乎！若禜之，可移於令尹、司馬。」王曰：「除腹心之疾而置諸股肱，何益？不穀不有大過，天其夭諸？有罪受罰，又焉移之？」遂弗禜。孔子曰：「楚昭王知大道矣，其不失國也宜哉！」按宋景公出人君之言三，熒惑為之退舍，邾文、楚昭之言，亦是物也，而終不蒙福，天道遠而不可知如此。","sortOrder":29},
  {"id":"s_work_dtbt_8_30","chapterId":"ch_work_dtbt_8","text":"杜悰","sortOrder":30},
  {"id":"s_work_dtbt_8_31","chapterId":"ch_work_dtbt_8","text":"唐懿宗鹹通二年二月，以杜悰為相，一日，兩樞密使詣中書，宣徽使楊公慶繼至，獨揖悰受宣，三相起避。公慶出書授悰，發之，乃宣宗大漸時，宦官請鄆王監國奏也，且曰：「當時宰相無名者，當以反法處之。」悰反復讀，復封以授公慶，曰：「主上欲罪宰相，當於延英面示聖旨。」公慶去，悰謂兩樞密曰：「內外之臣，事猶一體，今主上新踐阼，固當以仁愛為先，豈得遽贊成殺宰相事！若習以性成，則中尉、樞密豈得不自憂乎！」兩樞密相顧默然，徐曰：「當具以公言白至尊，非公重德，無人及此。」三相復來見悰，微請宣意，悰無言。三相惶怖，乞存家族。悰曰：「勿為他慮。」既而寂然。及延英開，上色甚悅。此資治通鑑所載也。新唐史雲：宣宗世，夔王處大明宮，而鄆王居十六宅。帝大漸，遺詔立夔王，而中尉王宗貫迎鄆王立之，是為懿宗。久之，遣樞密使楊慶詣中書獨揖悰。他宰相畢諴、杜審權、蔣伸不敢進，乃授悰中人請帝監國奏，因諭悰劾大臣名不在者。悰語之如前所雲，慶色沮去，帝怒亦釋。予以史考之，懿宗即位之日，宰相四人，曰令孤綯、曰蕭鄴、曰夏侯孜、曰蔣伸，至是時唯有伸在，三人者罷去矣。諴及審權乃懿宗自用者，無由有斯事。蓋野史之妄，而二書誤采之。溫公以唐事屬之范祖禹，其審取可謂詳盡，尚如此。信乎，修史之難哉！","sortOrder":31},
  {"id":"s_work_dtbt_8_32","chapterId":"ch_work_dtbt_8","text":"唐書世系表","sortOrder":32},
  {"id":"s_work_dtbt_8_33","chapterId":"ch_work_dtbt_8","text":"新唐宰相世系表皆承用逐家譜牒，故多有謬誤，內沈氏者最可笑，其略雲：「沈氏出自姬姓。周文王子聃叔季，字子揖，食采於沈，今汝南平輿沈亭是也。魯成公八年，為晉所滅。沈子生逞，字修之，奔楚，遂為沈氏。生嘉，字惟良，嘉生尹戊，戊生諸梁，諸梁子尹射，字修文。其後入漢，有為齊王太傅敷德侯者，有為驃騎將軍者，有為彭城侯者。」宋書沈約自敍雲：「金天氏之後，沈國在汝南平輿，定公四年，為蔡所滅。秦末有逞者，徵丞相不就。」其後頗與唐表同。按聃季所封自是一國，與沈了不相涉。春秋成公八年，晉侵沈，獲沈子揖。昭二十三年，吳敗頓、胡、沈、蔡之師於鷄父，沈子逞滅。定四年，蔡滅沈，殺沈子嘉。今表雲聃季字子揖，成八年為晉所滅，是文王之子壽五百餘歲矣。逞為吳所殺，而表雲奔楚，宋書雲秦召為丞相。沈尹戊為楚將，戰死於柏舉，正與嘉之死同時，而以為嘉之子。尹射書於左傳，三十四年始書諸梁，乃以為其子。又春秋時人立字皆從子及伯仲，豈有修之、惟良、修文之比。漢列侯表豈有所謂敷德、彭城侯？百官表豈有所謂驃騎將軍沈達者？沈約稱一時文宗，妄譜其上世名氏官爵，固可嗤誚，又不分別兩沈國。其金天氏之裔，沈、姒、蓐、黃之沈，封於汾川，晉滅之，春秋之沈，封於汝南，蔡滅之，顧合而為一，豈不讀左氏乎？歐陽公略不筆削，為可恨也！","sortOrder":33},
  {"id":"s_work_dtbt_8_34","chapterId":"ch_work_dtbt_8","text":"魯昭公","sortOrder":34},
  {"id":"s_work_dtbt_8_35","chapterId":"ch_work_dtbt_8","text":"春秋之世，列國之君失守社稷，其國皆即日改立君，無虛位以俟者。惟魯昭公為季孫意如所逐而孫於齊，又適晉，凡八年乃沒。意如在國攝事主祭，歲具從者之衣屨而歸之於乾侯，公薨之明年，喪還故國，然後其弟公子宋始即位，他國無此比也。豈非魯秉周禮，雖不幸逐君，猶存厥位，而不敢絕之乎？其後哀公孫於越，左傳終於是年，不知悼年以何時立也。","sortOrder":35},
  {"id":"s_work_dtbt_8_36","chapterId":"ch_work_dtbt_8","text":"州縣失故名","sortOrder":36},
  {"id":"s_work_dtbt_8_37","chapterId":"ch_work_dtbt_8","text":"今之州縣，以累代移徙改割之故，往往或失其故名，或州異而縣不同者。如：建昌軍在江西，而建昌縣乃隸南康；南康軍在江東，而南康縣乃隸南安；南安軍在江西，而南安縣乃隸泉州；韶州為始興郡，而始興縣外屬贛州為南康郡，而南康縣外屬鬱林為州，而鬱林縣隸貴州；桂陽為軍，而桂陽縣隸郴州。此類不可悉數。","sortOrder":37},
  {"id":"s_work_dtbt_8_38","chapterId":"ch_work_dtbt_8","text":"嚴州當為莊","sortOrder":38},
  {"id":"s_work_dtbt_8_39","chapterId":"ch_work_dtbt_8","text":"嚴州本名睦州，宣和中以方寇之故改焉。雖以威嚴為義，然實取嚴陵灘之意也。殊不考子陵乃莊氏，東漢避顯宗諱以「莊」為「嚴」，故史家追書以為嚴光，後世當從實可也。","sortOrder":39},
  {"id":"s_work_dtbt_8_40","chapterId":"ch_work_dtbt_8","text":"容齋隨筆","sortOrder":40},
  {"id":"s_work_dtbt_9_1","chapterId":"ch_work_dtbt_9","text":"卷第七(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_9_2","chapterId":"ch_work_dtbt_9","text":"孟子書百里奚","sortOrder":2},
  {"id":"s_work_dtbt_9_3","chapterId":"ch_work_dtbt_9","text":"柳子厚復杜溫夫書雲：「生用助字，不當律令，所謂乎、歟、耶、哉、夫也者，疑辭也。矣、耳、焉也者，决辭也。今生則一之，宜考前聞人所使用，與吾言類且異，精思之則益也。」予讀孟子百里奚一章曰：「曾不知以食牛幹秦繆公之為汙也，可謂智乎？不可諫而不諫，可謂不智乎？知虞公之將亡而先去之，不可謂不智也。時舉於秦，知繆公之可與有行也而相之，可謂不智乎？」味其所用助字，開闔變化，使人之意飛動，此難以為溫夫輩言也。","sortOrder":3},
  {"id":"s_work_dtbt_9_4","chapterId":"ch_work_dtbt_9","text":"韓柳為文之旨","sortOrder":4},
  {"id":"s_work_dtbt_9_5","chapterId":"ch_work_dtbt_9","text":"韓退之自言：作為文章，上規姚、姒、盤、誥、春秋、易、詩、左氏、莊、騷、太史、子雲、相如，閎其中而肆其外。柳子厚自言：每為文章，本之書、詩、禮、春秋、易，參之穀梁氏以厲其氣，參之孟、荀以暢其支，參之莊、老以肆其端，參之國語以博其趣，參之離騷以致其幽，參之太史公以著其潔。此韓、柳為文之旨，要學者宜思之。","sortOrder":5},
  {"id":"s_work_dtbt_9_6","chapterId":"ch_work_dtbt_9","text":"李習之論文","sortOrder":6},
  {"id":"s_work_dtbt_9_7","chapterId":"ch_work_dtbt_9","text":"李習之答朱載言書論文最為明白周盡，雲：「六經創意造言，皆不相師。故其讀春秋也，如未嘗有詩也；其讀詩也，如未嘗有易也；其讀易也，如未嘗有書也；其讀屈原、莊周也，如未嘗有六經也。如山有岱、華、嵩、衡焉，其同者高也，其草木之榮，不必均也。如瀆有濟、淮、河、江焉，其同者出源到海也，其曲直淺深，不必均也。天下之語文章有六說焉：其尚異者曰，文章詞句，奇險而已；其好理者曰，文章敍意，苟通而已；溺於時者曰，文章必當對；病於時者曰，文章不當對；愛難者曰，宜深，不當易；愛易者曰，宜通，不當難。此皆情有所偏滯，未識文章之所主也。義不深不至於理，而辭句怪麗者有之矣，劇秦美新、王褒僮約是也。其理往往有是者，而詞章不能工者有之矣，王氏中說、俗傳太公家教是也。古之人能極於工而已，不知其辭之對與否、易與難也。『憂心悄悄，慍於羣小』，非對也；『遘閔既多，受侮不少』，非不對也；『朕堲讒說殄行，震驚朕師』，『菀彼桑柔，其下侯旬，捋采其劉』，非易也；『光被四表，格於上下』，『十畝之間兮，桑者閑閑兮』，非難也。六經之後，百家之言興，老聃、列、莊至於劉向、揚雄，皆自成一家之文，學者之所師歸也。故義雖深，理雖當，詞不工者不成文，宜不能傳也。」其論於文者如此，後學宜志之。","sortOrder":7},
  {"id":"s_work_dtbt_9_8","chapterId":"ch_work_dtbt_9","text":"魏鄭公諫語","sortOrder":8},
  {"id":"s_work_dtbt_9_9","chapterId":"ch_work_dtbt_9","text":"魏鄭公諫止唐太宗封禪，中間數語，引喻剴切，曰：「今有人十年長患，療治且愈，此人應皮骨僅存，便欲使負米一石，日行百里，必不可得。隋氏之亂，非止十年，陛下為之良醫，疾苦雖已乂安，未甚充實。告成天地，臣切有疑。」太宗不能奪。此語見於公諫錄及舊唐書，而新史不載，資治通鑑記其諫事，亦刪此一節，可惜也！","sortOrder":9},
  {"id":"s_work_dtbt_9_10","chapterId":"ch_work_dtbt_9","text":"虞世南","sortOrder":10},
  {"id":"s_work_dtbt_9_11","chapterId":"ch_work_dtbt_9","text":"虞世南卒後，太宗夜夢見之，有若平生。翌日，下製曰：「世南奄隨物化，倏移歲序。昨因夜夢，忽睹其人，追懷遺美，良增悲嘆！宜資冥助，申朕思舊之情。可於其家為設五百僧齋，幷為造天尊像一軀。」夫太宗之夢世南，蓋君臣相與之誠所致，宜恤其子孫，厚其恩典可也。齋僧、造像，豈所應作？形之製書，著在國史，惜哉，太宗而有此也！","sortOrder":11},
  {"id":"s_work_dtbt_9_12","chapterId":"ch_work_dtbt_9","text":"七發","sortOrder":12},
  {"id":"s_work_dtbt_9_13","chapterId":"ch_work_dtbt_9","text":"枚乘作七發，創意造端，麗旨腴詞，上薄騷些，蓋文章領袖，故為可喜。其後繼之者，如傅毅七激、張衡七辯、崔駰七依、馬融七廣、曹植七啟、王粲七釋、張協七命之類，規仿太切，了無新意。傅玄又集之以為七林，使人讀未終篇，往往棄諸幾格。柳子厚晉問，乃用其體，而超然別立新機杼，激越清壯，漢、晉之間，諸文士之弊，於是一洗矣。東方朔答客難，自是文中傑出，揚雄擬之為解嘲，尚有馳騁自得之妙。至於崔駰達旨、班固賓戲、張衡應閒，皆屋下架屋，章摹句寫，其病與七林同，及韓退之進學解出，於是一洗矣。毛穎傳初成，世人多笑其怪，雖裴晉公亦不以為可，惟柳子獨愛之。韓子以文為戲，本一篇耳，妄人既附以革華傳，至於近時，羅文、江瑤、葉嘉、陸吉諸傳，紛紜雜沓，皆託以為東坡，大可笑也。","sortOrder":13},
  {"id":"s_work_dtbt_9_14","chapterId":"ch_work_dtbt_9","text":"將軍官稱","sortOrder":14},
  {"id":"s_work_dtbt_9_15","chapterId":"ch_work_dtbt_9","text":"前漢書百官表：「將軍皆周末官，秦因之。」予按國語：「鄭文公以詹伯為將軍。」又：「吳夫差十旌一將軍。」左傳：「豈將軍食之而有不足。」檀弓：「衞將軍。」文子：「魯使慎子為將軍。」然則其名久矣。彭寵為奴所縛，呼其妻曰：「趣為諸將軍辦裝。」東漢書註雲：「呼奴為將軍，欲其赦己也。」今吳人語猶謂小蒼頭為將軍，蓋本諸此。","sortOrder":15},
  {"id":"s_work_dtbt_9_16","chapterId":"ch_work_dtbt_9","text":"北道主人","sortOrder":16},
  {"id":"s_work_dtbt_9_17","chapterId":"ch_work_dtbt_9","text":"秦、晉圍鄭，鄭人謂秦盍舍鄭以為東道主。蓋鄭在秦之東，故雲。今世稱主人為東道者，此也。東漢載北道主人，乃有三事：「常山太守鄧晨會光武於鉅鹿，請從擊邯鄲，光武曰：『偉卿以一身從我，不如以一郡為我北道主人。』」又：「光武至薊，將欲南歸，耿弇以為不可，官屬腹心皆不肯，光武指弇曰：『是我北道主人也。』」「彭寵將反，光武問朱浮，浮曰：『大王倚寵為北道主人，今既不然，所以失望。』」後人罕引用之。","sortOrder":17},
  {"id":"s_work_dtbt_9_18","chapterId":"ch_work_dtbt_9","text":"洛中盱江八賢","sortOrder":18},
  {"id":"s_work_dtbt_9_19","chapterId":"ch_work_dtbt_9","text":"司馬溫公序賻禮，書閭閻之善者五人，呂南公作不欺述，書三人，皆以卑微不見於史氏。予頃修國史，將以綴於孝行傳而不果成，聊紀之於此。溫公所書皆陝州夏縣人。曰醫劉太，居親喪，不飲酒食肉終三年，以為今世士大夫所難能。其弟永一，尤孝友廉謹。夏縣有水災，民溺死者以百數，永一執竿立門首，他人物流入門者，輒擿出之。有僧寓錢數萬於其室而死，永一詣縣自陳，請以錢歸其子弟。鄉人負債不償者，毀其券。曰周文粲，其兄嗜酒，仰弟為生，兄或時酗毆粲，鄰人不平而唁之，粲怒曰：「兄未嘗毆我，汝何離間吾兄弟也！」曰蘇慶文者，事繼母以孝聞，常語其婦曰：「汝事吾母小不謹，必逐汝！」繼母少寡而無子，由是安其室終身。曰臺亨者，善畫，朝廷修景靈宮，調天下畫工詣京師，事畢，詔選試其優者，留翰林授官祿，亨名第一。以父老固辭，歸養於田里。南公所書皆建昌南城人。曰陳策，嘗買騾，得不可被鞍者，不忍移之他人，命養於野廬，俟其自斃。其子與猾駔計，因經過官人喪馬，即磨破騾背，以衒賈之。既售矣，策聞，自追及，告以不堪。官人疑策愛也，祕之。策請試以鞍，亢亢終日不得被，始謝還焉。有人從策買銀器若羅綺者，策不與羅綺。其人曰：「向見君帑有之，今何靳？」策曰：「然，有質錢而沒者，歲月已久，絲力糜脆不任用，聞公欲以嫁女，安可以此物病公哉！」取所當與銀器投熾炭中，曰：「吾恐受質人或得銀之非真者，故為公驗之。」曰危整者，買鮑魚，其駔舞秤權陰厚整。魚人去，身留整傍，請曰：「公買止五斤，已為公密倍入之，願畀我酒。」整大驚，追魚人數里返之，酬以直。又飲駔醇酒，曰：「汝所欲酒而已，何欺寒人為？」曰曾叔卿者，買陶器欲轉易於北方，而不果行。有人從之併售者，叔卿與之，已納價，猶問曰：「今以是何之？」其人對：「欲效公前謀耳。」叔卿曰：「不可，吾緣北方新有災荒，是故不以行，今豈宜不告以誤君乎？」遂不復售。而叔卿家苦貧，妻子饑寒不恤也。嗚呼，此八人者賢乎哉！","sortOrder":19},
  {"id":"s_work_dtbt_9_20","chapterId":"ch_work_dtbt_9","text":"王導小名","sortOrder":20},
  {"id":"s_work_dtbt_9_21","chapterId":"ch_work_dtbt_9","text":"顏魯公書遠祖西平靖侯顏含碑，晉李闡之文也。雲：「含為光祿大夫，馮懷欲為王導降禮，君不從，曰：『王公雖重，故是吾家阿龍。』君是王親丈人，故呼王小字。」晉書亦載此事，而不書小字。世說：「王丞相拜司空，桓廷尉嘆曰：『人言阿龍超，阿龍故自超。』」呼三公小字，晉人浮虛之習如此。","sortOrder":21},
  {"id":"s_work_dtbt_9_22","chapterId":"ch_work_dtbt_9","text":"漢書用字","sortOrder":22},
  {"id":"s_work_dtbt_9_23","chapterId":"ch_work_dtbt_9","text":"太史公陳涉世家：「今亡亦死，舉大計亦死，等死，死國可乎？」又曰：「戍死者固什六七，且壯士不死即已，死即舉大名耳！」叠用七死字，漢書因之。漢溝洫志載賈讓治河策雲：「河從河內北至黎陽為石隄，激使東抵東郡平剛；又為石隄，使西北抵黎陽、觀下；又為石隄，使東北抵東郡津北；又為石隄，使西北抵魏郡昭陽；又為石隄，激使東北。百餘里間，河再西三東。」凡五用石隄字，而不為冗複，非後人筆墨畦徑所能到也。","sortOrder":23},
  {"id":"s_work_dtbt_9_24","chapterId":"ch_work_dtbt_9","text":"薑嫄簡狄","sortOrder":24},
  {"id":"s_work_dtbt_9_25","chapterId":"ch_work_dtbt_9","text":"毛公註生民詩，薑嫄生後稷「履帝武敏歆」之句，曰：「從於高辛帝而見於天也。」玄鳥詩，「天命玄鳥，降而生商」之句，曰：「春分玄鳥降，簡狄配高辛帝，帝與之祈於郊禖而生契，故本其為天所命，以玄鳥至而生焉。」其說本自明白。至鄭氏箋始雲：「帝，上帝也。敏，拇也。祀郊禖時，有大人之跡，薑嫄履之，足不能滿，履其拇指之處，心體歆歆然如有人道感己者，遂有身，後則生子。」又謂：「鳦遺卵，簡狄吞之而生契。」其說本於史記，謂：「薑嫄出野，見巨人跡，忻然踐之，因生稷。」「簡狄行浴，見燕墮卵，取吞之，因生契。」此二端之怪妄，先賢辭而闢之多矣。歐陽公謂稷、契非高辛之子，毛公於史記不取履跡之怪，而取其訛繆之世次。按漢書毛公趙人，為河間獻王博士，然則在司馬子長之前數十年，謂為取史記世次，亦不然。蓋世次之說，皆出於世本，故荒唐特甚，其書今亡。夫適野而見巨跡，人將走避之不暇，豈復故欲踐履，以求不可知之禨祥；飛鳥墮卵，知為何物，而遽取吞之。以古揆今，人情一也，今之愚人未必爾，而謂古聖人之後妃為之，不待辨而明矣。","sortOrder":25},
  {"id":"s_work_dtbt_9_26","chapterId":"ch_work_dtbt_9","text":"羌慶同音","sortOrder":26},
  {"id":"s_work_dtbt_9_27","chapterId":"ch_work_dtbt_9","text":"王觀國彥賓、吳棫材老，有學林及葉韻補註、毛詩音二書皆雲：詩、易、太玄凡用慶字，皆與陽字韻葉，蓋羌字也。引蕭該漢書音義，慶音羌。又曰：「漢書亦有作羌者，班固幽通賦『慶未得其雲已』，文選作羌，而他未有明證。」予按揚雄傳所載反離騷：「慶夭顦而喪榮。」註雲：「慶，辭也，讀與羌同。」最為切據。","sortOrder":27},
  {"id":"s_work_dtbt_9_28","chapterId":"ch_work_dtbt_9","text":"佐命元臣","sortOrder":28},
  {"id":"s_work_dtbt_9_29","chapterId":"ch_work_dtbt_9","text":"盛王創業，必有同德之英輔，成垂世久長之計，不如是，不足以為一代宗臣。伊尹、周公之事見於詩、書，可考也。漢蕭何佐高祖，其始入關，即收秦丞相御史律令圖書，以周知天下阸塞，戶口多少，強弱處，民所疾苦。高祖失職為漢王，欲攻項羽，周勃、灌嬰、樊噲皆勸之，何獨曰：「今衆弗如，百戰百敗，願王王漢中，收用巴蜀，然後還定三秦。」王用其言。此劉氏興亡至計也。進韓信為大將，使當一面，定魏、趙、燕、齊，高祖得顓心與楚角，無北顧憂；且死，引曹參代己，而畫一之法成；約三章以蠲秦暴，拊百姓以申漢德。四百年基業，此焉肇之。唐房玄齡佐太宗，初在秦府，己獨收人物致幕下，與諸將密相申結，引杜如晦與參籌帷。及為宰相，粲然興起治功，以州縣成天下之治，以租庸調天下之財，以八百府、十六衞本天下之兵，以諫爭付王、魏，以兵事付靖、勣，御夷狄有道，用賢材有術。三百年基業，此焉肇之。其後製節度使而州縣之治壞，更二稅法而租庸之理壞，變府兵為彍騎、諸衞為神策而軍政壞，雖有名臣良輔，不能救也。趙韓王佐藝祖，監方鎮之勢，削支郡以損其強，置轉運、通判使掌錢穀以奪其富，參命京官知州事以分其黨，祿諸大功臣於環衞而不付以兵，收天下驍銳於殿巖而不使外重。建法立製，審官用人，一切施為，至於今是賴。此三君子之後，代天理物，碩大光明者，世有其人，所謂一時之相爾。蕭之孫有罪及無子，凡六絕國，漢輒紹封之。國朝褒錄韓王苗裔，未嘗或忘。唯房公之亡未十年，以其子故，奪襲爵、停配享，訖唐之世不復續，唐家亦少恩哉！","sortOrder":29},
  {"id":"s_work_dtbt_9_30","chapterId":"ch_work_dtbt_9","text":"名世英宰","sortOrder":30},
  {"id":"s_work_dtbt_9_31","chapterId":"ch_work_dtbt_9","text":"曹參為相國，日夜飲醇酒不事事，而畫一之歌興。王導輔佐三世，無日用之益，而歲計有餘，末年略不復省事，自嘆曰：「人言我憒憒，後人當思我憒憒。」謝安石不存小察，經遠無競。唐之房、杜，傳無可載之功。趙韓王得士大夫所投利害文字，皆置二大甕，滿則焚之。李文靖以中外所陳一切報罷，雲：「以此報國。」此六七君子，蓋非揚己取名，瞭然使戶曉者，真名世英宰也！豈曰不事事哉？","sortOrder":31},
  {"id":"s_work_dtbt_9_32","chapterId":"ch_work_dtbt_9","text":"檀弓誤字","sortOrder":32},
  {"id":"s_work_dtbt_9_33","chapterId":"ch_work_dtbt_9","text":"檀弓載吳侵陳事曰：「陳太宰嚭使於師，夫差謂行人儀曰：『是夫也多言，盍嘗問焉，師必有名，人之稱斯師也者，則謂之何？』太宰嚭曰：『其不謂之殺厲之師與！』」按嚭乃吳夫差之宰，陳遣使者正用行人，則儀乃陳臣也。記禮者簡策差互，故更錯其名，當雲「陳行人儀使於師，夫差使太宰嚭問之」，乃善。忠宣公作春秋詩引斯事，亦嘗辯正雲。","sortOrder":33},
  {"id":"s_work_dtbt_9_34","chapterId":"ch_work_dtbt_9","text":"薛能詩","sortOrder":34},
  {"id":"s_work_dtbt_9_35","chapterId":"ch_work_dtbt_9","text":"薛能者，晚唐詩人，格調不能高，而妄自尊大。其海棠詩序雲：「蜀海棠有聞，而詩無聞，杜子美於斯，興象不出，沒而有懷。天之厚餘，謹不敢讓，風雅盡在蜀矣，吾其庶幾。」然其語不過曰：「青苔浮落處，暮柳閒開時。帶醉遊人插，連陰彼叟移。晨前清露濕，晏後惡風吹。香少傳何許，妍多畫半遺」而已。又有荔枝詩序曰：「杜工部老居西蜀，不賦是詩，豈有意而不及歟？白尚書曾有是作，興旨卑泥，與無詩同。予遂為之題，不愧不負，將來作者，以其荔枝首唱，愚其庶幾。」然其語不過曰：「顆如松子色如櫻，未識蹉跎欲半生。歲杪監州曾見樹，時新入座久聞名」而已。又有折楊柳十首，敍曰：「此曲盛傳，為詞者甚衆，文人才子，各衒其能，莫不條似舞腰，葉如眉翠，出口皆然，頗為陳熟。能專於詩律，不愛隨人，搜難抉新，誓脫常態，雖欲勿伐，知音者其舍諸？」然其詞不過曰：「華清高樹出離宮，南陌柔條帶暖風。誰見輕陰是良夜，瀑泉聲畔月明中。」「洛橋晴影覆江船，羌笛秋聲濕塞煙。閒想習池公宴罷，水蒲風絮夕陽天」而已。別有柳枝詞五首，最後一章曰：「劉、白蘇臺總近時，當初章句是誰推。纖腰舞盡春楊柳，未有儂家一首詩。」自註雲：「劉、白二尚書，繼為蘇州刺史，皆賦楊柳枝詞，世多傳唱，雖有才語，但文字太僻，宮商不高耳。」能之大言如此，但稍推杜陵，視劉、白以下蔑如也。今讀其詩，正堪一笑。劉之詞曰：「城外春風吹酒旗，行人揮袂日西時。長安陌上無窮樹，唯有垂楊管別離。」白之詞雲：「紅板江橋清酒旗，館娃宮暖日斜時。可憐雨歇東風定，萬樹千條各自垂。」其風流氣概，豈能所可髣髴哉！","sortOrder":35},
  {"id":"s_work_dtbt_9_36","chapterId":"ch_work_dtbt_9","text":"漢晉太常","sortOrder":36},
  {"id":"s_work_dtbt_9_37","chapterId":"ch_work_dtbt_9","text":"漢自武帝以後，丞相無爵者乃封侯，其次雖御史大夫，亦不以爵封為閒。唯太常一卿，必以見侯居之，而職典宗廟園陵，動輒得咎，由元狩以降，以罪廢斥者二十人。意武帝陰欲損侯國，故使居是官以困之爾。表中所載：酇侯蕭壽成，坐犧牲瘦；蓼侯孔臧，坐衣冠道橋壞；鄲侯周仲居，坐不收赤側錢；繩侯周平，坐不繕園屋；睢陵侯張昌，坐乏祠；陽平侯杜相，坐擅役鄭舞人；廣阿侯任越人，坐廟酒酸；江鄒侯靳石，坐離宮道橋苦惡；戚侯李信成，坐縱丞相侵神道；俞侯欒賁，坐雍犧牲不如令；山陽侯張當居，坐擇博士弟子不以實；成安侯韓延年，坐留外國文書；新畤侯趙弟，坐鞫獄不實；牧丘侯石德，坐廟牲瘦；當塗侯魏不害，坐孝文廟風發瓦；轑陽侯江德，坐廟郎夜飲失火；蒲侯蘇昌，坐泄官書；弋陽侯任宮，坐人盜茂陵園物，建平侯杜緩，坐盜賊多。自酇侯至牧丘十四侯，皆奪國，武帝時也。自當塗至建平五侯，但免官，昭、宣時也。下及晉世，此風猶存，惠帝元康四年，大風，廟闕屋瓦有數枚傾落，免太常荀（上宀下禹）。五年，大風，蘭臺主者求索阿棟之間，得瓦小邪十五處，遂禁止太常，復興刑獄。陵上荊一枝圍七寸二分者被斫，司徒、太常奔走道路，太常禁止不解，蓋循習漢事雲。","sortOrder":37},
  {"id":"s_work_dtbt_9_38","chapterId":"ch_work_dtbt_9","text":"容齋隨筆","sortOrder":38},
  {"id":"s_work_dtbt_10_1","chapterId":"ch_work_dtbt_10","text":"卷第八(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_10_2","chapterId":"ch_work_dtbt_10","text":"諸葛公","sortOrder":2},
  {"id":"s_work_dtbt_10_3","chapterId":"ch_work_dtbt_10","text":"諸葛孔明千載人，其用兵行師，皆本於仁義節製，自三代以降，未之有也。蓋其操心製行，一出於誠，生於亂世，躬耕隴畝，使無徐庶之一言，玄德之三顧，則苟全性命，不求聞達必矣。其始見玄德，論曹操不可與爭鋒，孫氏可與為援而不可圖，唯荊、益可以取，言如蓍龜，終身不易。二十餘年之間，君信之，士大夫仰之，夷夏服之，敵人畏之。上有以取信於主，故玄德臨終，至雲「嗣子不才，君可自取」；後主雖庸懦無立，亦舉國聽之而不疑。下有以見信於人，故廢廖立而立垂泣，廢李嚴而嚴致死。後主左右奸辟側佞，充塞於中，而無一人有心害疾者。魏盡據中州，乘操、丕積威之後，猛士如林，不敢西向發一矢以臨蜀，而公六出征之，使魏畏蜀如虎。司馬懿案行其營壘處所，嘆為天下奇才。鍾會伐蜀，使人至漢川祭其廟，禁軍士不得近墓樵採，是豈智力策慮所能致哉？魏延每隨公出，輒欲請兵萬人，與公異道會於潼關，公製而不許，又欲請兵五千，循秦嶺而東，直取長安，以為一舉而鹹陽以西可定。史臣謂公以為危計不用，是不然。公真所謂義兵不用詐謀奇計，方以數十萬之衆，據正道而臨有罪，建旗鳴鼓，直指魏都，固將飛書告之，擇日合戰，豈復翳行竊步，事一旦之譎以規鹹陽哉！司馬懿年長於公四歲，懿存而公死，纔五十四耳，天不祚漢，非人力也。「霸氣西南歇，雄圖歷數屯。」杜詩盡之矣。","sortOrder":3},
  {"id":"s_work_dtbt_10_4","chapterId":"ch_work_dtbt_10","text":"沐浴佩玉","sortOrder":4},
  {"id":"s_work_dtbt_10_5","chapterId":"ch_work_dtbt_10","text":"「石駘仲卒，有庶子六人，卜所以為後者，曰：『沐浴佩玉則兆。』五人者皆沐浴佩玉。石祁子曰：『孰有執親之喪而沐浴佩玉者乎？』不沐浴佩玉。」此檀弓之文也，今之為文者不然，必曰「沐浴佩玉則兆，五人者如之，祁子獨不可，曰：『孰有執親之喪若此者乎？』」似亦足以盡其事，然古意衰矣。","sortOrder":5},
  {"id":"s_work_dtbt_10_6","chapterId":"ch_work_dtbt_10","text":"談叢失實","sortOrder":6},
  {"id":"s_work_dtbt_10_7","chapterId":"ch_work_dtbt_10","text":"後山陳無己著談叢六卷，高簡有筆力，然所載國朝事，失於不考究，多爽其實，漫析數端於此。","sortOrder":7},
  {"id":"s_work_dtbt_10_8","chapterId":"ch_work_dtbt_10","text":"其一雲：「呂許公惡韓、富、范三公，欲廢之而不能，及西軍罷，盡用三公及宋莒公、夏英公於二府，皆其仇也。呂既老，大事猶問，遂請出大臣行三邊，既建議，乃數出道者院宿，范公奉使陝西，宿此院，相見雲雲。」按呂公罷相，詔有同議大事之旨，公辭，乃慶曆三年三月，至九月致仕矣。四年七月，富、范始奉使，又三公入二府時，莒公自在外，英公拜樞密使而中輟，後二年莒方復入，安有五人同時之事？","sortOrder":8},
  {"id":"s_work_dtbt_10_9","chapterId":"ch_work_dtbt_10","text":"其二雲：「杜正獻、丁文簡為河東宣撫，任布之子上書歷詆執政，至雲至於臣父，亦出遭逢，謂其非德選也。杜戲丁曰：『賢郎亦要牢籠。』丁深銜之。其後二公同在政府，蘇子美進奏事作，杜避嫌不預，丁論以深文，子美坐廢為民，杜亦罷去。一言之謔，貽禍如此。」按杜公以執政使河東時，丁以學士為副，慶曆四年十一月進奏獄起，杜在相位，五年正月罷，至五月，丁公方從翰林參知政事，安有深文論子美之說？且杜公重厚，當無以人父子為謔之理，丁公長者也，肯追仇一言陷賢士大夫哉？","sortOrder":9},
  {"id":"s_work_dtbt_10_10","chapterId":"ch_work_dtbt_10","text":"其三雲：「張乖崖自成都召為參知政事，既至而腦疽作，求補外，乃知杭州而疾愈。上使中人往伺之，言且將召也，丁晉公以白金賂使者，還言如故，乃不召。」按張兩知成都，其初還朝為戶部使、中丞，始知杭州，是時，丁方在侍從；其後自蜀知昇州，丁為三司使。豈有如前所書之事？","sortOrder":10},
  {"id":"s_work_dtbt_10_11","chapterId":"ch_work_dtbt_10","text":"其四雲：「乖崖在陳，聞晉公逐萊公，知禍必及己，乃延三大戶與之博，出彩骰子勝其一坐，乃買田宅為歸計以自汚，晉公聞之，亦不害也。」按張公以祥符六年知陳州，八年卒，後五年當天禧四年，寇公方罷相，旋坐貶，豈有所謂乖崖自汚之事？","sortOrder":11},
  {"id":"s_work_dtbt_10_12","chapterId":"ch_work_dtbt_10","text":"茲四者所係不細，乃誕漫如此。蓋前輩不家藏國史，好事者肆意飾說為美聽，疑若可信，故誤人紀述。後山之書，必傳於後世，懼詒千載之惑，予是以辨之。","sortOrder":12},
  {"id":"s_work_dtbt_10_13","chapterId":"ch_work_dtbt_10","text":"石砮","sortOrder":13},
  {"id":"s_work_dtbt_10_14","chapterId":"ch_work_dtbt_10","text":"東坡作石砮記雲：「禹貢荊州貢礪、砥、砮、丹及箘、簵、楛，梁州貢砮、磬。至春秋時，隼集於陳廷，楛矢貫之，石砮長尺有咫，問於孔子，孔子不近取之荊、梁，而遠取之肅慎，則荊、梁之不貢此久矣。顏師古曰：『楛木堪為笴，今豳以北皆用之。』以此考之，用楛為矢，至唐猶然，而用石為砮，則自春秋以來莫識矣。」按晉書挹婁傳：有石砮、楛矢，國有山出石，其利入鐵；周武王時，獻其矢、砮；魏景元末亦來貢；晉元帝中興，又貢石砮；後通貢於石虎，虎以夸李壽者也。唐書黑水靺鞨傳：其矢，石鏃長二寸。蓋楛砮遺法，然則東坡所謂春秋以來莫識，恐不考耳。予家有一砮，正長二寸，豈黑水物乎？","sortOrder":14},
  {"id":"s_work_dtbt_10_15","chapterId":"ch_work_dtbt_10","text":"陶淵明","sortOrder":15},
  {"id":"s_work_dtbt_10_16","chapterId":"ch_work_dtbt_10","text":"陶淵明高簡閒靖，為晉、宋第一輩人。語其飢則簞瓢屢空，缾無儲粟；其寒則裋褐穿結，絺綌冬陳；其居則環堵蕭然，風日不蔽。窮困之狀，可謂至矣。讀其與子儼等疏雲：「恨室無萊婦，抱茲苦心。汝等雖不同生，當思四海皆兄弟之義，管仲、鮑叔，分財無猜，他人尚爾，况同父之人哉！」然則猶有庶子也。責子詩雲：「雍、端年十三。」此兩人必異母爾。淵明在彭澤，悉令公田種秫，曰：「吾常得醉於酒足矣。」妻子固請種秔，乃使二頃五十畝種秫，五十畝種秔。其自叙亦雲：「公田之利，足以為酒，故便求之。」猶望一稔而逝，然仲秋至冬，在官八十餘日，即自免去職。所謂秫秔，蓋未嘗得顆粒到口也，悲夫！","sortOrder":16},
  {"id":"s_work_dtbt_10_17","chapterId":"ch_work_dtbt_10","text":"東晉將相","sortOrder":17},
  {"id":"s_work_dtbt_10_18","chapterId":"ch_work_dtbt_10","text":"西晉南渡，國勢至弱，元帝為中興主，已有雄武不足之譏，餘皆童幼相承，無足稱算。然其享國百年，五胡雲擾，竟不能窺江、漢，苻堅以百萬之衆，至於送死淝水，後以強臣擅政，鼎命乃移，其於江左之勢，固自若也，是果何術哉？嘗考之矣，以國事付一相，而不貳其任，以外寄付方伯，而不輕其權，文武二柄，既得其道，餘皆可概見矣。百年之間，會稽王昱、道子、元顯以宗室，王敦、二桓以逆取，姑置勿言，卞壼、陸玩、郗鑒、陸曄、王彪之坦之不任事，其真託國者，王導、庾亮、何充、庾冰、蔡謨、殷浩、謝安、劉裕八人而已。方伯之任，莫重於荊、徐，荊州為國西門，刺史常都督七八州事，力雄強，分天下半，自渡江訖於太元，八十餘年，荷閫寄者，王敦、陶侃、庾氏之亮翼、桓氏之溫豁沖石民八人而已，非終於其軍不輒易，將士服習於下，敵人畏敬於外，非忽去忽來，兵不適將，將不適兵之比也。頃嘗為主上論此，蒙欣然領納，特時有不同，不能行爾。","sortOrder":18},
  {"id":"s_work_dtbt_10_19","chapterId":"ch_work_dtbt_10","text":"賞魚袋","sortOrder":19},
  {"id":"s_work_dtbt_10_20","chapterId":"ch_work_dtbt_10","text":"衡山有唐開元二十年所建南嶽真君碑，衡州司馬趙頤貞撰，荊府兵曹蕭誠書，末雲，別駕賞魚袋、上柱國光大晊。賞魚袋之名不可曉，他處未之見也。","sortOrder":20},
  {"id":"s_work_dtbt_10_21","chapterId":"ch_work_dtbt_10","text":"浯溪留題","sortOrder":21},
  {"id":"s_work_dtbt_10_22","chapterId":"ch_work_dtbt_10","text":"永州浯溪，唐人留題頗多，其一雲：「太僕卿分司東都韋瓘，太中二年過此。餘大和中以中書舍人謫宦康州，逮今十六年。去冬罷楚州刺史，今年二月有桂林之命，纔經數月，又蒙除替，行次靈川，聞改此官，分司優閒，誠為忝幸。」按新唐書：「瓘仕累中書舍人，與李德裕善，李宗閔惡之，德裕罷相，貶為明州長史，終桂管觀察使。」以題名證之，乃自中書謫康州，又不終於桂，史之誤如此。瓘所稱十六年前，正當大和七年，是時，德裕方在相位，八年十一月始罷，然則瓘之去國，果不知坐何事也。","sortOrder":22},
  {"id":"s_work_dtbt_10_23","chapterId":"ch_work_dtbt_10","text":"皇甫湜詩","sortOrder":23},
  {"id":"s_work_dtbt_10_24","chapterId":"ch_work_dtbt_10","text":"皇甫湜、李翱，雖為韓門弟子，而皆不能詩，浯溪石間有湜一詩，為元結而作，其詞雲：「次山有文章，可惋只在碎。然長於指叙，約潔多餘態。心語適相應，出句多分外。於諸作者間，拔戟成一隊。中行雖富劇，粹美君可蓋。子昂感遇佳，未若君雅裁。退之全而神，上與千年對。李杜才海翻，高下非可概。文於一氣間，為物莫與大。先王路不荒，豈不仰吾輩。石屏立衙衙，溪口揚素瀨。我思何人知，徙倚如有待。」味此詩乃論唐人文章耳，風格殊無可采也。","sortOrder":24},
  {"id":"s_work_dtbt_10_25","chapterId":"ch_work_dtbt_10","text":"人物以義為名","sortOrder":25},
  {"id":"s_work_dtbt_10_26","chapterId":"ch_work_dtbt_10","text":"人物以義為名者，其別最多。仗正道曰義，義師、義戰是也。衆所尊戴者曰義，義帝是也。與衆共之曰義，義倉、義社、義田、義學、義役、義井之類是也。至行過人曰義，義士、義俠、義姑、義夫、義婦之類是也。自外入而非正者曰義，義父、義兒、義兄弟、義服之類是也。衣裳器物亦然。在首曰義髻，在衣曰義襴、義領，合中小合子曰義子之類是也。合衆物為之，則有義漿、義墨、義酒。禽畜之賢，則有義犬、義烏、義鷹、義鶻。","sortOrder":26},
  {"id":"s_work_dtbt_10_27","chapterId":"ch_work_dtbt_10","text":"人君壽考","sortOrder":27},
  {"id":"s_work_dtbt_10_28","chapterId":"ch_work_dtbt_10","text":"三代以前，人君壽考有過百年者。自漢、晉、唐、三國，南北下及五季，凡百三十六君，唯漢武帝、吳大帝、唐高祖至七十一，玄宗七十八，梁武帝八十三，自餘至五六十者亦鮮。即此五君而論之。梁武召侯景之禍，幽辱告終，旋以亡國；玄宗身致大亂，播遷失意，飲恨而沒。享祚久長，翻以為害，固已不足言。漢武末年，巫蠱事起，自皇太子、公主、皇孫皆不得其死，悲傷愁沮，羣臣上壽，拒不舉觴，以天下付之八歲兒。吳大帝廢太子和，殺愛子魯王霸。唐高祖以秦王之故，兩子十孫同日併命，不得已而禪位，其方寸為如何？然則五君者雖有崇高之位，享耆耋之壽，竟何益哉！若光堯太上皇帝之福，真可於天人中求之。","sortOrder":28},
  {"id":"s_work_dtbt_10_29","chapterId":"ch_work_dtbt_10","text":"韓文公佚事","sortOrder":29},
  {"id":"s_work_dtbt_10_30","chapterId":"ch_work_dtbt_10","text":"韓文公自御史貶陽山，新舊二唐史，皆以為坐論宮市事。按公赴江陵途中詩，自叙此事甚詳，雲：「是年京師旱，田畝少所收。有司恤經費，未免煩誅求。傳聞閭里間，赤子棄渠溝。我時出衢路，餓者何其稠！適會除御史，誠當得言秋。拜疏移閤門，為忠寧自謀。上陳人疾苦，無令絕其喉。下言畿甸內，根本理宜優。積雪驗豐熟，幸寬待蠶麰。天子惻然感，司空嘆綢繆。謂言即施設，乃反遷炎洲！」皇甫湜作公神道碑雲：「關中旱饑，人死相枕藉，吏刻取恩，先生列言天下根本，民急如是，請寬民徭而免田租，專政者惡之，遂貶。」然則不因論宮市明甚。碑又書三事雲：「公為河南令，魏、鄆、幽、鎮各為留邸，貯潛卒以槖罪亡，公將擿其禁，斷民署吏，俟旦發，留守尹大恐，遽止之，是後鄆邸果謀反，將屠東都，以應淮、蔡。及從討元濟，請於裴度，須精兵千人，間道以入，必擒賊。未及行，李愬自文城夜入，得元濟。三軍之士，為公恨。復謂度曰：今借聲勢，王承宗可以辭取，不煩兵矣。得柏耆，口授其詞，使耆執筆書之，持以入鎮州，承宗遂割德、棣二州以獻。」李翱作公行狀，所載略同。而唐書並逸其事，且以鎮州之功，專歸柏耆，豈非未嘗見湜文集乎？資治通鑑亦僅言耆以策幹愈，愈為白度，為書遣之耳。","sortOrder":30},
  {"id":"s_work_dtbt_10_31","chapterId":"ch_work_dtbt_10","text":"論韓公文","sortOrder":31},
  {"id":"s_work_dtbt_10_32","chapterId":"ch_work_dtbt_10","text":"劉夢得、李習之、皇甫持正、李漢，皆稱誦韓公之文，各極其摯。劉之語雲：「高山無窮，太華削成。人文無窮，夫子挺生。鸞鳳一鳴，蜩螗革音。手持文柄，高視寰海。權衡低昂，瞻我所在。三十餘年，聲名塞天。」習之雲：「建武以還，文卑質喪。氣萎體敗，剽剝不讓。撥去其華，得其本根。包劉越嬴，幷武同殷。六經之風，絕而復新。學者有歸，大變於文。」又雲：「公每以為自揚雄之後，作者不出，其所為文，未嘗效前人之言而固與之幷，後進之士有志於古文者，莫不視以為法。」皇甫雲：「先生之作，無圓無方，主是歸工，抉經之心，執聖之權，尚友作者，跂邪觝異，以扶孔子，存皇之極。茹古涵今，無有端涯。鯨鏗春麗，驚耀天下，栗密窈眇，章妥句適，精能之至，鬼入神出，姬氏以來，一人而已。」又雲：「屬文意語天出，業孔子、孟軻而侈其文，焯焯烈烈，為唐之章。」又雲：「如長江秋註，千里一道，然施於灌激，或爽於用。」此論似為不知公者。漢之語雲：「詭然而蛟龍翔，蔚然而虎鳳躍，鏘然而韶鈞鳴，日光玉潔，周情孔思，千態萬貌，卒澤於道德仁義，炳如也。」是四人者，所以推高韓公，可謂盡矣。及東坡之碑一出，而後衆說盡廢。其略雲：「匹夫而為百世師，一言而為天下法，是皆有以參天地之化，關盛衰之運。自東漢以來，道喪文弊，歷唐貞觀開元而不能救，獨公談笑而麾之，天下靡然從公，復歸於正。文起八代之衰，道濟天下之溺，豈非參天地而獨存者乎？」騎龍白雲之詩，蹈厲發越，直到雅、頌，所謂若捕龍蛇、搏虎豹者，大哉言乎！","sortOrder":32},
  {"id":"s_work_dtbt_10_33","chapterId":"ch_work_dtbt_10","text":"治生從宦","sortOrder":33},
  {"id":"s_work_dtbt_10_34","chapterId":"ch_work_dtbt_10","text":"韓詩曰：「居閒食不足，從仕力難任。兩事皆害性，一生常苦心。」然治生從宦，自是兩塗，未嘗有兼得者。張釋之以貲為郎，十年不得調，曰：「久宦減兄仲之產，不遂。」欲免歸。司馬相如亦以貲為郎，因病免，家貧無以自業，至從故人於臨邛，及歸成都，家徒四壁立而已。","sortOrder":34},
  {"id":"s_work_dtbt_10_35","chapterId":"ch_work_dtbt_10","text":"真宗末年","sortOrder":35},
  {"id":"s_work_dtbt_10_36","chapterId":"ch_work_dtbt_10","text":"真宗末年屬疾，每視朝不多語言，命令間或不能周審，前輩雜傳記多以為權臣矯製，而非也。錢文僖在翰林，有天禧四年筆錄，紀逐日瑣細家事，及一時奏對，幷他所聞之語，今略載於此。寇萊公罷相之夕，錢公當製，上問：「與何官得？」錢奏雲：「王欽若近出，除太子太保。」上曰：「近上是甚？」雲：「太子太傅。」上曰：「與太子太傅。」又雲：「更與一優禮。」錢奏但請封國公而已。時樞密有五員，而中書只參政李迪一人，後月餘，召學士楊大年，宣雲：「馮拯與吏書，李迪與吏侍。」更無他言。楊奏：「若只轉官，合中書命詞，唯樞密使、平章事，却學士院降製。」上雲：「與樞密使、平章事。」楊亦憂慮，而不復審，退而草製，以迪為吏部侍郎、集賢相，拯為樞密相。又四日，召知製誥晏殊，殊退，乃召錢。上問：「馮拯如何商量？」錢奏：「外論甚美，只為密院却有三員正使，三員副使，中書依舊一員，以此外人疑訝。」上雲：「如何安排？」錢奏：「若却令拯入中書，即是彰昨來錯誤，但於曹利用、丁謂中選一人過中書，即幷不妨事。」上曰：「誰得？」錢奏：「丁謂是文官，合入中書。」上雲：「入中書。」遂奏授同平章事。又奏兼玉清宮使，又奏兼昭文國史。又乞加曹利用平章事。上雲：「與平章事。」","sortOrder":36},
  {"id":"s_work_dtbt_10_37","chapterId":"ch_work_dtbt_10","text":"按此際大除拜，本真宗啟其端，至於移改曲折，則其柄乃係詞臣，可以舞文容奸，不之覺也。寇公免相四十日，周懷政之事方作，溫公記聞，蘇子由龍川志，范蜀公東齋記事，皆誤以為因懷政而罷，非也。予嘗以錢錄示李燾，燾采取之，又誤以召晏公為寇罷之夕，亦非也。","sortOrder":37},
  {"id":"s_work_dtbt_10_38","chapterId":"ch_work_dtbt_10","text":"容齋隨筆","sortOrder":38},
  {"id":"s_work_dtbt_11_1","chapterId":"ch_work_dtbt_11","text":"卷第九(二十八則)","sortOrder":1},
  {"id":"s_work_dtbt_11_2","chapterId":"ch_work_dtbt_11","text":"霍光賞功","sortOrder":2},
  {"id":"s_work_dtbt_11_3","chapterId":"ch_work_dtbt_11","text":"漢武帝外事四夷，出爵勸賞，凡將士有軍功，無問貴賤，未有不封侯者。及昭帝時，大鴻臚田廣明平益州夷，斬首捕虜三萬，但賜爵關內侯。蓋霍光為政，務與民休息，故不欲求邊功，益州之師，不得已耳，與唐宋璟抑郝靈佺斬默啜之意同。然數年之後，以范明友擊烏桓，傅介子刺樓蘭，皆即侯之，則為非是，蓋明友，光女婿也。","sortOrder":3},
  {"id":"s_work_dtbt_11_4","chapterId":"ch_work_dtbt_11","text":"尺棰取半","sortOrder":4},
  {"id":"s_work_dtbt_11_5","chapterId":"ch_work_dtbt_11","text":"莊子載惠子之語曰：「一尺之棰，日取其半，萬世不竭。」雖為寓言，然此理固具。蓋但取其半，正碎為微塵，餘半猶存，雖至於無窮可也。特所謂卵有毛、鷄三足、犬可以為羊、馬有卵、火不熱、龜長於蛇、飛鳥之景未嘗動，如是之類，非詞說所能了也。","sortOrder":5},
  {"id":"s_work_dtbt_11_6","chapterId":"ch_work_dtbt_11","text":"漢文失材","sortOrder":6},
  {"id":"s_work_dtbt_11_7","chapterId":"ch_work_dtbt_11","text":"漢文帝見李廣曰：「惜廣不逢時，令當高祖世，萬戶侯豈足道哉！」賈山上書言治亂之道，借秦為喻，其言忠正明白，不下賈誼，曾不得一官，史臣猶贊美文帝，以為山言多激切，終不加罰，所以廣諫爭之路。觀此二事，失材多矣。吳、楚反時，李廣以都尉戰昌邑下顯名，以梁王授廣將軍印，故賞不行。武帝時，五為將軍擊匈奴，無尺寸功，至不得其死。三朝不遇，命也夫！","sortOrder":7},
  {"id":"s_work_dtbt_11_8","chapterId":"ch_work_dtbt_11","text":"陳軫之說疎","sortOrder":8},
  {"id":"s_work_dtbt_11_9","chapterId":"ch_work_dtbt_11","text":"戰國權謀之士，遊說從橫，皆趨一時之利，殊不顧義理曲直所在。張儀欺楚懷王，使之絕齊而獻商於之地。陳軫諫曰：「張儀必負王，商於不可得而齊、秦合，是北絕齊交，西生秦患。」其言可謂善矣。然至雲：「不若陰合而陽絕於齊，使人隨張儀，苟與吾地，絕齊未晚。」是軫不深計齊之可絕與否，但以得地為意耳。及秦負約，楚王欲攻之。軫又勸曰：「不如因賂之以一名都，與之幷兵而攻齊，是我亡地於秦，取償於齊也。」此策尤乖謬不義。且秦加亡道於我，乃欲賂以地，齊本與國，楚無故而絕之，宜割地致幣，卑詞謝罪，復求其援，而反欲攻之，軫之說於是疎矣。乃知魯仲連、虞卿為豪傑之士，非軫輩所能企及也。","sortOrder":9},
  {"id":"s_work_dtbt_11_10","chapterId":"ch_work_dtbt_11","text":"顏率兒童之見","sortOrder":10},
  {"id":"s_work_dtbt_11_11","chapterId":"ch_work_dtbt_11","text":"秦興師臨周而求九鼎，周君患之。顏率請借救於齊。乃詣齊王許以鼎，齊為發兵救周，而秦兵罷。齊將求鼎，周君又患之。顏率復詣齊曰：「願獻九鼎，不識何塗之從而致之齊？」齊王將寄徑於梁、於楚，率皆以為不可，齊乃止。戰國策首載此事，蓋以為奇謀。予謂此特兒童之見爾！爭戰雖急，要當有信。今一紿齊可也，獨不計後日諸侯來伐，誰復肯救我乎？疑必無是事，好事者飾之爾。故史記、通鑑皆不取。","sortOrder":11},
  {"id":"s_work_dtbt_11_12","chapterId":"ch_work_dtbt_11","text":"皇甫湜正閏論","sortOrder":12},
  {"id":"s_work_dtbt_11_13","chapterId":"ch_work_dtbt_11","text":"晉魏以來，正閏之說紛紛，前人論之多矣。蓋以宋繼晉，則至陳而無所終，由隋而推之，為周為魏，則上無所起。故司馬公於通鑑取南朝承晉訖於陳亡，然後係之隋開皇九年，姑藉其年以紀事，無所抑揚也。唯皇甫湜之論不然，曰：「晉之南遷，與平王避戎之事同，而元魏種實匈奴，自為中國之位號。謂之滅耶，晉實未改；謂之禪耶，已無所傳。而往之著書者有帝元，今之為錄者皆閏晉，失之遠矣。晉為宋，宋為齊，齊為梁，江陵之滅，則為周矣。陳氏自樹而奪，無容於言。故自唐推而上，唐受之隋，隋得之周，周取之梁，推梁而上以至於堯、舜，為得天下統。則陳僭於南，元閏於北，其不昭昭乎？」此說亦有理。然予復考之，滅梁江陵者，魏文帝也，時歲在甲戌。又三年丁丑，周乃代魏。不得雲江陵之滅，則為周也。","sortOrder":13},
  {"id":"s_work_dtbt_11_14","chapterId":"ch_work_dtbt_11","text":"簡師之賢","sortOrder":14},
  {"id":"s_work_dtbt_11_15","chapterId":"ch_work_dtbt_11","text":"皇甫持正集有送簡師序，雲：「韓侍郎貶潮州，浮圖之士，歡快以抃，師獨憤起訪餘求序行，資適潮，不顧蛇山鱷水萬里之嶮毒，若將朝得進拜而夕死者。師雖佛其名，而儒其行；雖夷狄其衣服，而人其知。不猶愈於冠儒冠，服朝服，惑溺於經怪之說以斁彝倫邪？」予讀其文，想見簡師之賢，而惜其名無傳於後世，故表而出之。","sortOrder":15},
  {"id":"s_work_dtbt_11_16","chapterId":"ch_work_dtbt_11","text":"老人推恩","sortOrder":16},
  {"id":"s_work_dtbt_11_17","chapterId":"ch_work_dtbt_11","text":"唐世赦宥，推恩於老人絕優。開元二十三年，耕籍田。侍老百歲以上，版授上州刺史；九十以上，中州刺史；八十以上，上州司馬。二十七年，赦。百歲以上，下州刺史，婦人郡君；九十以上，上州司馬，婦人縣君；八十以上，縣令，婦人鄉君。天寶七載，京城七十以上本縣令，六十以上縣丞，天下侍老除官與開元等。國朝之製，百歲者始得初品官封，比唐不侔矣。淳熙三年，以太上皇帝慶壽之故，推恩稍優，遂有增年詭籍以冒榮命者。使如唐日，將如何哉！","sortOrder":17},
  {"id":"s_work_dtbt_11_18","chapterId":"ch_work_dtbt_11","text":"唐三傑","sortOrder":18},
  {"id":"s_work_dtbt_11_19","chapterId":"ch_work_dtbt_11","text":"漢高祖以蕭何、張良、韓信為人傑，此三人者真足以當之也。唐明皇同日拜宋璟、張說、源乾曜三故相官，帝賦三傑詩，自寫以賜。其意蓋以比蕭、張等也。說與乾曜豈璟比哉！明皇可謂不知臣矣。","sortOrder":19},
  {"id":"s_work_dtbt_11_20","chapterId":"ch_work_dtbt_11","text":"忠義出天資","sortOrder":20},
  {"id":"s_work_dtbt_11_21","chapterId":"ch_work_dtbt_11","text":"忠義守節之士，出於天資，非關居位貴賤，受恩深淺也。王莽移漢祚，劉歆以宗室之雋、導之為逆，孔光以宰相輔成其事。而龔勝以故大夫守誼以死。郭欽、蔣詡以刺史、郡守，栗融、禽慶、曹竟、蘇章以儒生，皆去官不仕。陳鹹之家，至不用王氏臘。蕭道成宋，褚淵、王儉，奕世達宦，身為帝甥、主壻，所以縱臾滅劉，唯恐不速。而死節者乃王蘊、卜伯興、黃回、任候伯之輩耳。安祿山、朱泚之變，陳希烈、張均、張垍、喬琳、李忠臣，皆以宰相世臣，為之丞弼。而甄濟、權皋、劉海賓、段秀實，或以幕府小吏，或以廢斥列卿，捐身立節，名震海內。人之賢不肖，相去何止天冠地屨乎！","sortOrder":21},
  {"id":"s_work_dtbt_11_22","chapterId":"ch_work_dtbt_11","text":"劉歆不孝","sortOrder":22},
  {"id":"s_work_dtbt_11_23","chapterId":"ch_work_dtbt_11","text":"事親孝，故忠可移於君，是以求忠臣必於孝子之門。劉歆事父，雖不載不孝之跡，然其議論每與向異同。故向拳拳於國家，欲抑王氏以崇劉氏，而歆乃力贊王莽，倡其凶逆，至為之國師公，又改名秀以應圖讖，竟亦不免為莽所誅，子棻、女愔皆以戮死。使天道每如是，不善者其知懼乎！","sortOrder":23},
  {"id":"s_work_dtbt_11_24","chapterId":"ch_work_dtbt_11","text":"漢法惡誕謾","sortOrder":24},
  {"id":"s_work_dtbt_11_25","chapterId":"ch_work_dtbt_11","text":"李廣以私忿殺霸陵尉，上書自陳謝罪。武帝報之曰：「報忿除害，朕之所圖於將軍也。若乃免冠徒跣，稽顙請罪，豈朕之指哉！」張敞殺絮舜，上書曰：「臣待罪京兆，絮舜本臣素所厚吏，以臣有章劾當免，受記考事，謂臣『五日京兆』，背恩忘義。臣竊以舜無狀，枉法以誅之。臣賊殺不辜，鞫獄故不直，死無所恨。」宣帝引拜為刺史。漢世法令，最惡誕謾罔上。廣、敞雖妄殺人，一語陳情，則赦之不問，所以開臣下不敢為欺之路也。武帝待張湯非不厚，及問魯謁居事，謂其懷詐面欺，殺之不貸，真得御臣之法。","sortOrder":25},
  {"id":"s_work_dtbt_11_26","chapterId":"ch_work_dtbt_11","text":"漢官名","sortOrder":26},
  {"id":"s_work_dtbt_11_27","chapterId":"ch_work_dtbt_11","text":"漢官名有不書於百官表，而因事乃見者。如行冤獄使者，因張敞殺絮舜而見；美俗使者，因何並代嚴詡而見；河隄使者，因王延世塞決河而見；直指使者，因暴勝之而見。豈非因事置官，事已即罷乎？","sortOrder":27},
  {"id":"s_work_dtbt_11_28","chapterId":"ch_work_dtbt_11","text":"五胡亂華","sortOrder":28},
  {"id":"s_work_dtbt_11_29","chapterId":"ch_work_dtbt_11","text":"劉聰乘晉之衰，盜竊中土，身死而嗣滅，男女無少長皆戕於靳準。劉曜承其後，不能十年，身為人禽。石勒嘗盛矣，子奪於虎。虎盡有秦、魏、燕、齊、韓、趙之地，死不一年，而後嗣屠戮，無一遺種。慕容雋乘石氏之亂，跨據河山，亦僅終其身，至子而滅。苻堅之興，又非劉、石比，然不能自免，社稷為墟。慕容垂乘苻氏之亂，盡復燕祚，死未期年，基業傾覆。此七人者，皆夷狄亂華之巨擘也，而不能久如此。今之金虜，為國八十年，傳數酋矣，未亡何邪？","sortOrder":29},
  {"id":"s_work_dtbt_11_30","chapterId":"ch_work_dtbt_11","text":"石宣為彗","sortOrder":30},
  {"id":"s_work_dtbt_11_31","chapterId":"ch_work_dtbt_11","text":"石虎將殺其子宣，佛圖澄諫曰：「陛下若加慈恕，福祚猶長，若必誅之，宣當為彗星下掃鄴宮。」虎不從。明年，虎死。二年，國亡。晉史書之以為澄言之驗。予謂此乃石氏窮凶極虐，為天所棄。豈一逆子便能上幹玄象，起彗孛乎？宣殺其弟韜，又欲行冒頓之事，寧有不問之理？澄言既妄，史氏誤信而載之，資治通鑑亦失於不刪也。","sortOrder":31},
  {"id":"s_work_dtbt_11_32","chapterId":"ch_work_dtbt_11","text":"三公改他官","sortOrder":32},
  {"id":"s_work_dtbt_11_33","chapterId":"ch_work_dtbt_11","text":"國初以來，宰相帶三公官居位，及罷去，多有改他官者。范質自司徒、侍中改太子太傅，王溥自司空改太子太保，呂蒙正自司空改太子太師是也。天禧以前唯趙普、王旦乃依舊公師，仍復遷秩。天聖而後，恩典始隆，張士遜致仕，至以兵部尚書得太傅雲。","sortOrder":33},
  {"id":"s_work_dtbt_11_34","chapterId":"ch_work_dtbt_11","text":"帶職致仕","sortOrder":34},
  {"id":"s_work_dtbt_11_35","chapterId":"ch_work_dtbt_11","text":"熙寧以前，待製學士致仕者，率遷官而解其職。若有疾就閒者，亦換為集賢院學士。蓋不以近職處散地也。帶職致仕，方自熙寧中王素始。後改集賢學士為修撰，政和中又改為右文雲。","sortOrder":35},
  {"id":"s_work_dtbt_11_36","chapterId":"ch_work_dtbt_11","text":"朋友之義","sortOrder":36},
  {"id":"s_work_dtbt_11_37","chapterId":"ch_work_dtbt_11","text":"朋友之義甚重。天下之達道五，君臣、父子、兄弟、夫婦而至朋友之交。故天子至於庶人，未有不須友以成者。「天下俗薄，而朋友道絕。」見於詩。「不信乎朋友，弗獲乎上。」見於中庸、孟子。「朋友信之」，孔子之志也；「車馬衣裘，與朋友共」，子路之志也；「與朋友交而信」，曾子之志也。周禮六行，五曰任，謂信於友也。漢、唐以來，猶有范張、陳雷、元白、劉柳之徒，始終相與，不以死生貴賤易其心。本朝百年間，此風尚存。嗚呼，今亡矣！","sortOrder":37},
  {"id":"s_work_dtbt_11_38","chapterId":"ch_work_dtbt_11","text":"高科得人","sortOrder":38},
  {"id":"s_work_dtbt_11_39","chapterId":"ch_work_dtbt_11","text":"國朝自太平興國以來，以科舉羅天下士，士之策名前列者，或不十年而至公輔。呂文穆公蒙正、張文定公齊賢之徒是也。及嘉祐以前，亦指日在清顯。東坡送章子平序，以謂仁宗一朝十有三榜，數其上之三人，凡三十有九，其不至於公卿者，五人而已。蓋為士者知其身必達，故自愛重而不肯為非，天下公望亦以鼎貴期之，故相與愛惜成就，以待其用。至嘉祐四年之製，前三名始不為通判，第一人才得評事、簽判，代還升通判，又任滿，始除館職。王安石為政，又殺其法，恩數既削，得人亦衰矣。觀天聖初榜，宋鄭公郊、葉清臣、鄭文肅公戩、高文莊公若訥、曾魯公公亮五人連名，二宰相、二執政、一三司使。第二榜，王文忠公堯臣、韓魏公琦、趙康靖公槩連名。第三榜，王宣徽拱辰，劉相沆、孫文懿公抃連名。楊寘榜，寘不幸即死，王岐公珪、韓康公絳、王荊公安石連名。劉煇榜，煇不顯，胡右丞宗愈、安門下燾、劉忠肅公摯、章申公惇連名。其盛如此。治平以後，第一人作侍從，蓋可數矣。","sortOrder":39},
  {"id":"s_work_dtbt_11_40","chapterId":"ch_work_dtbt_11","text":"辛慶忌","sortOrder":40},
  {"id":"s_work_dtbt_11_41","chapterId":"ch_work_dtbt_11","text":"漢成帝將立趙飛燕為皇後，怒劉輔直諫，囚之掖廷獄，左將軍辛慶忌等上書救輔，遂得減死。朱雲請斬張禹，上怒，將殺之，慶忌免冠解印綬，叩頭殿下曰：「此臣素著狂直，臣敢以死爭。」叩頭流血。上意解，然後得已。慶忌此兩事，可與汲黯、王章同科。班史不書於本傳，但言其為國虎臣，匈奴、西域敬其威信而已。方爭朱雲時，公卿在前，曾無一人助之以請，為可羞也。","sortOrder":41},
  {"id":"s_work_dtbt_11_42","chapterId":"ch_work_dtbt_11","text":"楚懷王","sortOrder":42},
  {"id":"s_work_dtbt_11_43","chapterId":"ch_work_dtbt_11","text":"秦楚之際，楚懷王以牧羊小兒，為項氏所立，首尾才三年。以事考之，東坡所謂天下之賢主也。項梁之死，王幷呂臣、項羽軍，自將之，羽不敢爭。見宋義論兵事，即以為上將軍，而羽乃為次將。擇諸將入關，羽怨秦，奮勢願與沛公西，王以羽慓悍禍賊，不許，獨遣沛公，羽不敢違。及秦既亡，羽使人還報王，王曰：「如約。」令沛公王關中。此數者，皆能自製命，非碌碌孱主受令於強臣者，故終不能全於項氏。然遣將救趙滅秦，至於有天下，皆出其手。太史公作史記，當為之立本紀，繼於秦後，迨其亡，則次以漢高祖可也。而乃立項羽本紀，義帝之事特附見焉，是直以羽為代秦也，其失多矣。高祖嘗下詔，以秦皇帝、楚隱王亡後，為置守冢，幷及魏、齊、趙三王，而義帝乃高祖故君，獨缺不問，豈簡策脫佚乎？","sortOrder":43},
  {"id":"s_work_dtbt_11_44","chapterId":"ch_work_dtbt_11","text":"范增非人傑","sortOrder":44},
  {"id":"s_work_dtbt_11_45","chapterId":"ch_work_dtbt_11","text":"世謂范增為人傑，予以為不然。夷考平生，蓋出戰國從橫之餘，見利而不知義者也。始勸項氏立懷王，及羽奪王之地，遷王於郴，已而弒之，增不能引君臣大誼，爭之以死。懷王與諸將約，先入關中者王之，沛公既先定關中，則當如約，增乃勸羽殺之，又徙之蜀漢。羽之伐趙，殺上將宋義，增為末將，坐而視之。坑秦降卒，殺秦降王，燒秦宮室，增皆親見之，未嘗聞一言也。至於滎陽之役，身遭反間，然後發怒而去。嗚呼，疏矣哉！東坡公論此事偉甚，猶未盡也。","sortOrder":45},
  {"id":"s_work_dtbt_11_46","chapterId":"ch_work_dtbt_11","text":"翰苑故事","sortOrder":46},
  {"id":"s_work_dtbt_11_47","chapterId":"ch_work_dtbt_11","text":"翰苑故事，今廢棄無餘。唯學士入朝，猶有朱衣院吏雙引至朝堂而止，及景靈宮行香，則引至立班處。公文至三省不用申狀，但尺紙直書其事，右語雲：「諮報尚書省伏候裁旨，月日押。」謂之諮報。此兩事僅存。","sortOrder":47},
  {"id":"s_work_dtbt_11_48","chapterId":"ch_work_dtbt_11","text":"唐揚州之盛","sortOrder":48},
  {"id":"s_work_dtbt_11_49","chapterId":"ch_work_dtbt_11","text":"唐世鹽鐵轉運使在揚州，盡斡利權，判官多至數十人，商賈如織。故諺稱「揚一益二」，謂天下之盛，揚為一而蜀次之也。杜牧之有「春風十里珠簾」之句，張祜詩雲：「十里長街市井連，月明橋上看神仙。人生只合揚州死，禪智山光好墓田。」王建詩雲：「夜市千燈照碧雲，高樓紅袖客紛紛。如今不似時平日，猶自笙歌徹曉聞！」徐凝詩雲：「天下三分明月夜，二分無賴是揚州。」其盛可知矣。自畢師鐸、孫儒之亂，蕩為丘墟。楊行密復葺之，稍成壯藩，又燬於顯德。本朝承平百七十年，尚不能及唐之什一，今日真可酸鼻也！","sortOrder":49},
  {"id":"s_work_dtbt_11_50","chapterId":"ch_work_dtbt_11","text":"張祜詩","sortOrder":50},
  {"id":"s_work_dtbt_11_51","chapterId":"ch_work_dtbt_11","text":"唐開元、天寶之盛，見於傳記、歌詩多矣，而張祜所詠尤多，皆他詩人所未嘗及者。如正月十五夜燈雲：「千門開鎖萬燈明，正月中旬動帝京。三百內人連袖舞，一時天上著詞聲。」上巳樂雲：「猩猩血染繫頭標，天上齊聲舉畫橈。却是內人爭意切，六宮紅袖一時招。」春鶯囀雲：「興慶池南柳未開，太真先把一枝梅。內人已唱春鶯囀，花下傞傞軟舞來。」又有大酺樂、邠王小管、李謨笛、寧哥來、邠娘羯鼓、退宮人、耍娘歌、悖拏兒舞、阿保鳥湯、雨霖鈴、香囊子等詩，皆可補開、天遺事，絃之樂府也。","sortOrder":51},
  {"id":"s_work_dtbt_11_52","chapterId":"ch_work_dtbt_11","text":"古人無忌諱","sortOrder":52},
  {"id":"s_work_dtbt_11_53","chapterId":"ch_work_dtbt_11","text":"古人無忌諱。如季武子成寢，杜氏之葬在西階之下，請合葬焉，許之，入宮而不敢哭，武子命之哭。曾子與客立於門側，其徒有父死，將出哭於巷者，曾子曰：「反哭於爾次。」北面而弔焉。伯高死於衞，赴於孔子，孔子曰：「夫由賜也見我，吾哭諸賜氏。」遂哭於子貢寢門之外，命子貢為之主，曰：「為爾哭也來者，拜之。」夫以國卿之寢階，許外人入哭而葬，己所居室，而令門弟子哭其親，朋友之喪，而受哭於寢門之外，今人必不然者也。聖賢所行，固為盡禮，季孫宿亦能如是。以古方今，相去何直千萬也。","sortOrder":53},
  {"id":"s_work_dtbt_11_54","chapterId":"ch_work_dtbt_11","text":"宰我不詐","sortOrder":54},
  {"id":"s_work_dtbt_11_55","chapterId":"ch_work_dtbt_11","text":"宰我以三年之喪為久，夫子以食稻衣錦問之曰：「於女安乎？」曰：「安。」後人以是譏宰我，謂孔門高第乃如是。殊不知其由衷之言，不為詐隱，所以為孔門高第也。魯悼公之喪，孟敬子曰：「食粥，天下之達禮也，吾三臣者之不能居公室也，四方莫不聞矣，勉而為瘠，毋乃使人疑夫不以情居瘠者乎哉！我則食食。」樂正子春之母死，五日而不食，曰：「吾悔之，自吾母而不得吾情，吾惡乎用吾情！」謂勉強過禮也。夫不情之惡，賢者所深戒，雖孟敬子之不臣，寧廢禮食食，不肯不情而為瘠。蓋先王之澤未遠，故不肖者亦能及之。","sortOrder":55},
  {"id":"s_work_dtbt_11_56","chapterId":"ch_work_dtbt_11","text":"李益盧綸詩","sortOrder":56},
  {"id":"s_work_dtbt_11_57","chapterId":"ch_work_dtbt_11","text":"李益、盧綸，皆唐大曆十才子之傑者。綸於益為內兄，嘗秋夜同宿，益贈綸詩曰：「世故中年別，餘生此會同。却將愁與病，獨對朗陵翁。」綸和曰：「戚戚一西東，十年今始同。可憐風雨夜，相問兩衰翁。」二詩雖絕句，讀之使人悽然，皆奇作也。","sortOrder":57},
  {"id":"s_work_dtbt_11_58","chapterId":"ch_work_dtbt_11","text":"容齋隨筆","sortOrder":58},
  {"id":"s_work_dtbt_12_1","chapterId":"ch_work_dtbt_12","text":"卷第十(二十則)","sortOrder":1},
  {"id":"s_work_dtbt_12_2","chapterId":"ch_work_dtbt_12","text":"楊彪陳羣","sortOrder":2},
  {"id":"s_work_dtbt_12_3","chapterId":"ch_work_dtbt_12","text":"魏文帝受禪，欲以楊彪為太尉，彪辭曰：「彪備漢三公，耄年被病，豈可贊惟新之朝？」乃授光祿大夫。相國華歆以形色忤旨，徙為司徒而不進爵。帝久不懌，以問尚書令陳羣曰：「我應天受禪，相國及公獨不怡，何也？」羣對曰：「臣與相國，曾臣漢朝，心雖悅喜，猶義形於色。」夫曹氏漢，忠臣義士之所宜痛心疾首，縱力不能討，忍復仕其朝為公卿乎？歆、羣為一世之賢，所立不過如是。彪遜辭以免禍，亦不敢一言及曹氏之所以得。蓋自黨錮禍起，天下賢士大夫如李膺、范滂之徒，屠戮殆盡，故所存者如是而已。士風不競，悲夫！章惇、蔡京為政，欲殄滅元祐善類，正士禁錮者三十年，以致靖康之禍，其不為歆、羣者幾希矣！","sortOrder":3},
  {"id":"s_work_dtbt_12_4","chapterId":"ch_work_dtbt_12","text":"袁盎溫嶠","sortOrder":4},
  {"id":"s_work_dtbt_12_5","chapterId":"ch_work_dtbt_12","text":"趙談常害袁盎，盎兄子種曰：「君與鬥，廷辱之，使其毀不用。」文帝出，談參乘，盎前曰：「天子所與共六尺輿者，皆天下豪英，陛下奈何與刀鋸餘人載？」上笑下談，談泣下車。溫嶠將去王敦，而懼錢鳳為之奸謀，因敦餞別，嶠起行酒，至鳳，擊鳳幘墜，作色曰：「錢鳳何人，溫太真行酒而敢不飲！」及發後，鳳入說敦曰：「嶠於朝廷甚密，未必可信。」敦曰：「太真昨醉，小加聲色，豈得以此便相讒貳。」由是鳳謀不行。二者之智如此。","sortOrder":5},
  {"id":"s_work_dtbt_12_6","chapterId":"ch_work_dtbt_12","text":"日飲亡何","sortOrder":6},
  {"id":"s_work_dtbt_12_7","chapterId":"ch_work_dtbt_12","text":"漢書爰盎傳：「南方卑濕，君能日飲亡何。」顏師古註雲：「無何，言更無餘事。」而史記盎傳作「日飲毋苛」，蓋言南方不宜多飲耳。今人多用「亡何」字。","sortOrder":7},
  {"id":"s_work_dtbt_12_8","chapterId":"ch_work_dtbt_12","text":"爰盎小人","sortOrder":8},
  {"id":"s_work_dtbt_12_9","chapterId":"ch_work_dtbt_12","text":"爰盎真小人，每事皆借公言而報私怨，初非盡忠一意為君上者也。嘗為呂祿舍人，故怨周勃。文帝禮下勃，何豫盎事，乃有「非社稷臣」之語，謂勃不能爭呂氏之事，適會成功耳。致文帝有輕勃心，既免使就國，遂有廷尉之難。嘗謁丞相申屠嘉，嘉弗為禮，則之丞相舍折困之。為趙談所害，故沮止其參乘。素不好鼂錯，故因吳反事請誅之。蓋盎本安陵羣盜，宜其忮心忍戾如此，死於刺客，非不幸也。","sortOrder":9},
  {"id":"s_work_dtbt_12_10","chapterId":"ch_work_dtbt_12","text":"唐書判","sortOrder":10},
  {"id":"s_work_dtbt_12_11","chapterId":"ch_work_dtbt_12","text":"唐銓選擇人之法有四：一曰身，謂體貌豐偉；二曰言，言辭辯正；三曰書，楷法遒美；四日判，文理優長。凡試判登科謂之入等，甚拙者謂之藍縷，選未滿而試文三篇謂之宏辭，試判三條謂之拔萃。中者即授官。既以書為藝，故唐人無不工楷法，以判為貴，故無不習熟。而判語必駢儷，今所傳龍筋鳳髓判及白樂天集甲乙判是也。自朝廷至縣邑，莫不皆然，非讀書善文不可也。宰臣每啟擬一事，亦必偶數十語，今鄭畋敕語、堂判猶存。世俗喜道瑣細遺事，參以滑稽，目為花判，其實乃如此，非若今人握筆據案，只署一字亦可。國初尚有唐餘波，久而革去之。但體貌豐偉，用以取人，未為至論。","sortOrder":11},
  {"id":"s_work_dtbt_12_12","chapterId":"ch_work_dtbt_12","text":"古彝器","sortOrder":12},
  {"id":"s_work_dtbt_12_13","chapterId":"ch_work_dtbt_12","text":"三代彝器，其存至今者，人皆寶為奇玩。然自春秋以來，固重之矣。經傳所記，取郜大鼎於宋，魯以吳壽夢之鼎賄荀偃，晉賜子產莒之二方鼎，齊賂晉以紀甗、玉磬，徐賂齊以甲父之鼎，鄭賂晉以襄鐘，衞欲以文之舒鼎、定之鞶鑑納魯侯，樂毅為燕破齊，祭器設於寧臺，大呂陳於元英，故鼎反乎磨室是已。","sortOrder":13},
  {"id":"s_work_dtbt_12_14","chapterId":"ch_work_dtbt_12","text":"玉蘂杜鵑","sortOrder":14},
  {"id":"s_work_dtbt_12_15","chapterId":"ch_work_dtbt_12","text":"物以希見為珍，不必異種也。長安唐昌觀玉蘂，乃今瑒花，又名米囊，黃魯直易為山礬者。潤州鶴林寺杜鵑，乃今映山紅，又名紅躑躅者。二花在江東彌山亙野，殆與榛莽相似。而唐昌所產，至於神女下遊，折花而去，以踐玉峯之期，鶴林之花，至以為外國僧鉢盂中所移，上玄命三女下司之，已逾百年，終歸閬苑。是不特土俗罕見，雖神仙亦不識也。王建宮詞雲：「太儀前日暖房來，囑向昭陽乞藥栽。敕賜一窠紅躑躅，謝恩未了奏花開。」其重如此，蓋宮禁中亦鮮雲。","sortOrder":15},
  {"id":"s_work_dtbt_12_16","chapterId":"ch_work_dtbt_12","text":"禮寺失職","sortOrder":16},
  {"id":"s_work_dtbt_12_17","chapterId":"ch_work_dtbt_12","text":"唐開元中，封孔子為文宣王，顏子為兗公，閔子至子夏為侯，羣弟子為伯。本朝祥符中，進封公為國公，侯為郡公，伯為侯。紹興二十五年，太上皇帝御製贊七十五首，而有司但具唐爵，故宸翰所標，皆用開元國邑，其失於考據如此，今當請而正之可也。紹興末，胡馬飲江，既而自斃，詔加封馬當、采石、金山三水府。太常寺按籍，係四字王，當加至六字。及降告命至其處，廟令以舊告來，則已八字矣。逐郡為繳回新命，而別易二美名以寵之。禮寺之失職類此。方完顏亮據淮上，予從樞密行府於建康，嘗致禱大江，能令虜不得渡者，當奏冊為帝。洎事定，朝廷許如約。朱丞相漢章曰：「四瀆當一體，獨帝江神，禮乎？」予曰：「懲勸之道，人神一也。彼洪河長淮，受國家祭祀血食，不為不久，當胡騎之來，如行枕席，唯大江滔滔天險，坐遏巨敵之衝，使其百萬束手倒戈而退，此其靈德陰功，於河、淮何如？自五嶽進冊之後，今蔣廟、陳果仁祠亦稱之，江神之帝，於是為不忝矣。」朱公終以為不可，亦僅改兩字。吁，可惜哉！","sortOrder":17},
  {"id":"s_work_dtbt_12_18","chapterId":"ch_work_dtbt_12","text":"徐凝詩","sortOrder":18},
  {"id":"s_work_dtbt_12_19","chapterId":"ch_work_dtbt_12","text":"徐凝以「瀑布界破青山」之句，東坡指為惡詩，故不為詩人所稱說。予家有凝集，觀其餘篇，亦自有佳處，今漫紀數絕於此。漢宮曲雲：「水色簾前流玉霜，趙家飛燕侍昭陽。掌中舞罷簫聲絕，三十六宮秋夜長。」憶揚州雲：「蕭娘臉下難勝淚，桃葉眉頭易得愁。天下三分明月夜，二分無賴是揚州。」相思林雲：「遠客遠遊新過嶺，每逢芳樹問芳名。長林遍是相思樹，爭遣愁人獨自行。」玩花雲：「一樹梨花春向暮，雪枝殘處怨風來。明朝漸校無多去，看到黃昏不欲回。」將歸江外辭韓侍郎雲：「一生所遇唯元白，天下無人重布衣。欲別朱門淚先盡，白頭遊子白身歸。」皆有情致，宜其見知於微之、樂天也。但俗子妄作樂天詩，繆為賞激，以起東坡之誚耳。","sortOrder":19},
  {"id":"s_work_dtbt_12_20","chapterId":"ch_work_dtbt_12","text":"梅花橫參","sortOrder":20},
  {"id":"s_work_dtbt_12_21","chapterId":"ch_work_dtbt_12","text":"今人梅花詩詞，多用參橫字，蓋出柳子厚龍城錄所載趙師雄事，然此實妄書，或以為劉無言所作也。其語雲：「東方已白，月落參橫。」且以冬半視之，黃昏時參已見，至丁夜則西沒矣，安得將旦而橫乎？秦少遊詩：「月落參橫畫角哀，暗香消盡令人老。」承此誤也。唯東坡雲：「紛紛初疑月掛樹，耿耿獨與參橫昏。」乃為精當。老杜有「城擁朝來客，天橫醉後參」之句，以全篇考之，蓋初秋所作也。","sortOrder":21},
  {"id":"s_work_dtbt_12_22","chapterId":"ch_work_dtbt_12","text":"致仕之失","sortOrder":22},
  {"id":"s_work_dtbt_12_23","chapterId":"ch_work_dtbt_12","text":"大夫七十而致事，謂之得謝，美名也。漢韋賢、薛廣德、疏廣、疏受，或縣安車以示子孫，賣黃金以侈君賜，為榮多矣。至於龔勝、鄭弘輩，亦詔策褒表，郡縣力問，合於三代敬老之義。本朝尤重之，大臣告老，必寵以東宮師傅、侍從。耆艾若晁迥、孫奭、李柬之亦然。宣和以前，蓋未有既死而方乞致仕者，南渡之後，故實散亡，於是朝奉、武翼郎以上，不以內外高卑，率為此舉。其最甚而無理者，雖宰相輔臣，考終於位，其家發哀即服，降旨聲鍾給賻，既已閱日，方且為之告廷出命，綸書之中，不免有親醫藥、介壽康之語。如秦太師、萬俟丞相、陳魯公、沈必先、王時亨、鄭仲益是已。其在外者，非易簀屬纊，不復有請，間千百人中有一二焉，則知與不知，駭惜其死，子弟遊宦遠地，往往飲泣不寧，謁急奔命，故及無事日，不敢為之。紹興二十九年，予為吏部郎，因輪對，奏言：「乞令吏部立法，自今日以往，當得致仕恩澤之人物故者，即以告所在州，州上省部，然後夷考其平生，非有贓私過惡於式有累者，輒官其後人。若真能陳義引年，或辭榮知止者，乞厚其節禮，以厲風俗，賢於率天下為偽也。」太上覽奏欣納曰：「朕記得此事之廢，方四十年，當如卿語。」既下三省，諸公多以為是，而首相湯岐公獨難之，其議遂寢，今不復可正雲。","sortOrder":23},
  {"id":"s_work_dtbt_12_24","chapterId":"ch_work_dtbt_12","text":"南班宗室","sortOrder":24},
  {"id":"s_work_dtbt_12_25","chapterId":"ch_work_dtbt_12","text":"南班宗室，自來只以本官奉朝請。自隆興以後，始帶宮觀使及提舉。今嗣濮王、永陽、恩平、安定王以下皆然，非製也。","sortOrder":25},
  {"id":"s_work_dtbt_12_26","chapterId":"ch_work_dtbt_12","text":"省郎稱謂","sortOrder":26},
  {"id":"s_work_dtbt_12_27","chapterId":"ch_work_dtbt_12","text":"除省郎者，初降旨揮，但雲：「除某部郎官。」蓋以知州資序者，當為郎中，不及者為員外郎。及吏部擬告身細銜，則始直書之。其兼權者，初雲「權某部郎官」，洎入銜及文書，皆曰「權員外郎」，已是他部郎中，則曰「權郎中」。至紹興末，馮方以館職攝吏部，欲為異，則繫銜曰：「兼權尚書吏部郎官。」予嘗叩其說，馮曰：「所被省劄只言『權郎官』，故不敢耳。」予曰：「省劄中豈有『尚書』二字乎？」馮無以對，然訖不肯改。自後相承效之，至今告命及符牒所書，亦雲「權郎官」，固已甚野，至於尚左、侍右之名，遂入除目，皆小吏不諳熟故事，馴以致然，書之記註，為不美耳。","sortOrder":27},
  {"id":"s_work_dtbt_12_28","chapterId":"ch_work_dtbt_12","text":"水衡都尉二事","sortOrder":28},
  {"id":"s_work_dtbt_12_29","chapterId":"ch_work_dtbt_12","text":"龔遂為渤海太守，宣帝召之，議曹王生願從，遂不忍逆。及引入宮，王生隨後呼曰：「天子即問君何以治渤海，宜曰：『皆聖主之德，非小臣之力也。』」遂受其言。上果問以治狀，遂對如王生言。天子悅其有讓，笑曰：「君安得長者之言而稱之？」遂曰：「乃臣議曹教戒臣也。」上拜遂水衡都尉，以王生為丞。予謂遂之治郡，功效著明，宣帝不以為賞，而顧悅其佞詞乎！宜其起王成膠東之偽也。褚先生於史記中又載武帝時，召北海太守，有文學卒史王先生自請與太守俱。太守入宮，王先生曰：「天子即問君何以治北海令無盜賊，君對曰何哉？」守曰：「選擇賢材，各任之以其能，賞異等，罰不肖。」王先生曰：「是自譽自伐功，不可也。願君對言：『非臣之力，盡陛下神靈威武所變化也。』」太守如其言。武帝大笑，曰：「安得長者之言而稱之，安所受之？」對曰：「受之文學卒史。」於是以太守為水衡都尉，王先生為丞。二事不應相類如此，疑即龔遂，而褚誤書也。","sortOrder":29},
  {"id":"s_work_dtbt_12_30","chapterId":"ch_work_dtbt_12","text":"程嬰杵臼","sortOrder":30},
  {"id":"s_work_dtbt_12_31","chapterId":"ch_work_dtbt_12","text":"春秋於魯成公八年書晉殺趙同、趙括，於十年書晉景公卒。相去二年。而史記乃有屠岸賈欲滅趙氏，程嬰、公孫杵臼共匿趙孤，十五年景公復立趙武之說。以年世考之，則自同、括死後，景公又卒，厲公立八年而弒，悼公立又五年矣，其乖妄如是。嬰、杵臼之事，乃戰國俠士刺客所為，春秋時風俗無此也。元豐中，吳處厚以皇嗣未立，上書乞立二人廟，訪求其墓，優加封爵。敕令河東路訪尋遺跡，得其冢於絳州太平縣。詔封嬰為成信侯，杵臼為忠智侯，廟食於絳。後又以為韓厥存趙，追封為公。三人皆以春秋祠於祚德廟。且自晉景公至元豐，千六百五十年矣，古先聖帝、明王之墓，尚不可考，區區二士，豈復有兆域所在乎？絳郡以朝命所訪，姑指他丘壟為之詞以塞責耳。此事之必不然者也。處厚之書進御，即除將作丞，狃於出位陳言以得寵祿，遂有訐蔡新州十詩之事，所獲幾何，貽笑無極，哀哉！","sortOrder":31},
  {"id":"s_work_dtbt_12_32","chapterId":"ch_work_dtbt_12","text":"戰國自取亡","sortOrder":32},
  {"id":"s_work_dtbt_12_33","chapterId":"ch_work_dtbt_12","text":"秦以關中之地，日夜東獵六國，百有餘年，悉禽滅之。雖雲得地利，善為兵，故百戰百勝，以予考之，實六國自有以致之也。韓、燕弱小，置不足論。彼四國者，魏以惠王而衰，齊以閔王而衰，楚以懷王而衰，趙以孝成王而衰，皆本於好兵貪地之故。魏承文侯、武侯之後，表裏山河，大於三晉，諸侯莫能與之爭。而惠王數伐韓、趙，志吞邯鄲，挫敗於齊，軍覆子死，卒之為秦所困，國日以蹙，失河西七百里，去安邑而都大梁，數世不振，訖於殄國。閔王承威、宣之後，山東之建國莫強焉。而狃於伐宋之利，南侵楚，西侵三晉，欲幷二周為天子，遂為燕所屠。雖賴田單之力，得復亡城，子孫沮氣，孑孑自保，終墮秦計，束手為虜。懷王貪商於六百里，受詐張儀，失其名都，喪其甲士，不能取償，身遭囚辱以死。趙以上黨之地，代韓受兵，利令智昏，輕用民死，同日坑於長平者過四十萬，幾於社稷為墟，幸不即亡，終以不免。此四國之君，苟為保境睦鄰，畏天自守，秦雖強大，豈能加我哉！","sortOrder":33},
  {"id":"s_work_dtbt_12_34","chapterId":"ch_work_dtbt_12","text":"臨敵易將","sortOrder":34},
  {"id":"s_work_dtbt_12_35","chapterId":"ch_work_dtbt_12","text":"臨敵易將，固兵家之所忌，然事當審其是非，當易而不易，亦非也。秦以白起易王齕而勝趙，以王翦易李信而滅楚，魏公子無忌易晉鄙而勝秦，將豈不可易乎？燕以騎劫易樂毅而敗，趙以趙括易廉頗而敗，以趙蔥易李牧而滅，魏使人代信陵君將，亦滅，將豈可易乎？","sortOrder":35},
  {"id":"s_work_dtbt_12_36","chapterId":"ch_work_dtbt_12","text":"司空表聖詩","sortOrder":36},
  {"id":"s_work_dtbt_12_37","chapterId":"ch_work_dtbt_12","text":"東坡稱司空表聖詩文高雅，有承平之遺風，蓋嘗自列其詩之有得於文字之表者二十四韻，恨當時不識其妙。又雲：「表聖論其詩，以為得味外味，如『綠樹連村暗，黃花入麥稀』，此句最善。又『棋聲花院閉，幡影石壇高』，吾嘗獨入白鶴觀，松陰滿地，不見一人，惟聞棋聲，然後知此句之工，但恨其寒儉有僧態。」予讀表聖一鳴集，有與李生論詩一書，乃正坡公所言者，其餘五言句雲，「人家寒食月，花影午時天」，「雨微吟足思，花落夢無憀」，「坡暖冬生筍，松涼夏健人」，「川明虹照雨，樹密鳥衝人」，「夜短猿悲減，風和鵲喜靈」，「馬色經寒慘，鵰聲帶晚饑」，「客來當意愜，花發遇歌成」。七言句雲，「孤嶼池痕春漲滿，小欄花韻午晴初」，「五更惆悵迴孤枕，由自殘燈照落花」。皆可稱也。","sortOrder":37},
  {"id":"s_work_dtbt_12_38","chapterId":"ch_work_dtbt_12","text":"漢丞相","sortOrder":38},
  {"id":"s_work_dtbt_12_39","chapterId":"ch_work_dtbt_12","text":"漢丞相或終於位，或免就國，或免為庶人，或致仕，或以罪死，其復召用者，但為光祿大夫或特進，優遊散秩，未嘗有除他官者也。御史大夫則間為九卿、將軍。至東漢則大不然。始於光武時，王梁罷大司空而為中郎將，其後三公去位，輒復為大夫、列卿。如崔烈歷司徒、太尉之後，乃為城門校尉，其體貌大臣之禮亦衰矣！","sortOrder":39},
  {"id":"s_work_dtbt_12_40","chapterId":"ch_work_dtbt_12","text":"冊禮不講","sortOrder":40},
  {"id":"s_work_dtbt_12_41","chapterId":"ch_work_dtbt_12","text":"唐封拜後妃王公及贈官，皆行冊禮。文宗大和四年，以裴度守司徒平章重事，度上表辭冊命，其言雲：「臣此官已三度受冊，有靦面目。」從之。然則唐世以為常儀，辭者蓋鮮。唯國朝以此禮為重，自皇後、太子之外，雖王公之貴，率一章乞免即止，典禮益以不講，良為可惜！","sortOrder":41},
  {"id":"s_work_dtbt_12_42","chapterId":"ch_work_dtbt_12","text":"容齋隨筆","sortOrder":42},
  {"id":"s_work_dtbt_13_1","chapterId":"ch_work_dtbt_13","text":"卷第十一(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_13_2","chapterId":"ch_work_dtbt_13","text":"將帥貪功","sortOrder":2},
  {"id":"s_work_dtbt_13_3","chapterId":"ch_work_dtbt_13","text":"以功名為心，貪軍旅之寄，此自將帥習氣，雖古來賢卿大夫，未有能知止自斂者也。廉頗既老，飯斗米，肉十斤，被甲上馬，以示可用，致困郭開之口，終不得召。漢武帝大擊匈奴，李廣數自請行，上以為老，不許，良久，乃許之，卒有東道失軍之罪。宣帝時，先零羌反，趙充國年七十餘，上老之，使丙吉問誰可將，曰：「亡逾於老臣者矣。」即馳至金城，圖上方略，雖全師製勝，而禍及其子卬。光武時，五溪蠻夷畔，馬援請行，帝愍其老，未許。援自請曰：「臣尚能被甲上馬。」帝令試之，援據鞍顧盼，以示可用。帝笑曰：「矍鑠哉是翁也！」遂用為將，果有壺頭之厄。李靖為相，以足疾就第，會吐穀渾寇邊，即往見房喬曰：「吾雖老，尚堪一行。」既平其國，而有高甑生誣罔之事，幾於不免。太宗將伐遼，召入謂曰：「高麗未服，公亦有意乎？」對曰：「今疾雖衰，陛下誠不棄，病且瘳矣。」帝憫其老，不許。郭子儀年八十餘，猶為關內副元帥、朔方河中節度，不求退身，竟為德宗冊罷。此諸公皆人傑也，猶不免此，况其下者乎！","sortOrder":3},
  {"id":"s_work_dtbt_13_4","chapterId":"ch_work_dtbt_13","text":"漢二帝治盜","sortOrder":4},
  {"id":"s_work_dtbt_13_5","chapterId":"ch_work_dtbt_13","text":"漢武帝末年，盜賊滋起，大羣至數千人，小羣以百數。上使使者衣繡衣，持節虎符，發兵以興擊，斬首大部或至萬餘級。於是作「沈命法」，曰：「羣盜起不發覺，覺而弗捕滿品者，二千石以下至小吏主者皆死。」其後小吏畏誅，雖有盜，弗敢發，恐不能得，坐課累府，府亦使不言。故盜賊寖多，上下相為匿，以避文法焉。光武時，羣盜處處並起。遣使者下郡國，聽羣盜自相糾擿，五人共斬一人者除其罪。吏雖逗留回避故縱者，皆勿問，聽以禽討為效。其牧守令長坐界內有盜賊而不收捕者，及以畏愞捐城委守者，皆不以為負，但取獲賊多少為殿最，唯蔽匿者乃罪之。於是更相追捕，賊並解散。此二事均為治盜，而武帝之嚴，不若光武之寬，其效可睹也。","sortOrder":5},
  {"id":"s_work_dtbt_13_6","chapterId":"ch_work_dtbt_13","text":"漢唐封禪","sortOrder":6},
  {"id":"s_work_dtbt_13_7","chapterId":"ch_work_dtbt_13","text":"漢光武建武三十年，車駕東巡，羣臣上言，即位三十年，宜封禪泰山。詔曰：「即位三十年，百姓怨氣滿腹，吾誰欺？欺天乎！何事汙七十二代之編錄！若郡縣遠遣吏上壽，盛稱虛美，必髠令屯田。」從此羣臣不敢復言。後二年，上齋，夜讀河圖會昌符，曰「赤劉之九，會命岱宗」。感此文，乃詔梁松等按索河雒讖文言九世封禪事者，遂奏三十六事，於是求武帝元封故事，以三月行封禪禮。唐太宗貞觀五年，羣臣以四夷鹹服，表請封禪。詔不許。六年，復請。上曰：「卿輩皆以封禪為帝王盛事，朕意不然，若天下乂安，家給人足，雖不封禪，庸何傷乎？昔秦始皇封禪，而漢文帝不封禪，後世豈以文帝之賢不及始皇邪？且事天掃地而祭，何必登泰山之顛，封數尺之土，然後可以展其誠敬乎？」已而欲從其請，魏鄭公獨以為不可，發六難以爭之，至以謂崇虛名而受實害，會河南、北大水，遂寢。十年，復使房喬裁定其禮，將以十六年二月，有事於泰山，會星孛太微而罷。予謂二帝皆不世出盛德之主，灼知封禪之非，形諸詔告，可謂著明。然不能幾時，自為翻覆，光武惑於讖記，太宗好大喜名，以今觀之，蓋所以累善政耳。","sortOrder":7},
  {"id":"s_work_dtbt_13_8","chapterId":"ch_work_dtbt_13","text":"漢封禪記","sortOrder":8},
  {"id":"s_work_dtbt_13_9","chapterId":"ch_work_dtbt_13","text":"應劭漢官儀載馬第伯封禪儀記，正紀建武東封事，每稱天子為國家，其敍山勢峭嶮，登陟勞困之狀極工，予喜誦之。其略雲：「是朝上山，騎行，往往道峻峭，下騎步，牽馬，乍步乍騎且相半。至中觀，留馬，仰望天關，如從穀底仰觀抗峯。其為高也，如視浮雲，其峻也，石壁窅窱，如無道徑。遙望其人，端如行朽兀，或為白石，或雪，久之，白者移過樹，乃知是人也。殊不可上，四布僵臥石上，亦賴齎酒脯，處處有泉水，復勉強相將行，到天關，自以已至也，問道中人，言尚十餘里。其道旁山脅，仰視巖石松樹，鬱鬱蒼蒼，若在雲中。俯視溪穀，碌碌不可見丈尺。直上七里，賴其羊腸逶迤，名曰環道，往往有絙索，可得而登也。兩從者扶挾，前人相牽，後人見前人履底，前人見後人頂，如畫。初上此道，行十餘步一休，稍疲，咽唇燋，五六步一休，牒牒據頓地，不避暗溼，前有燥地，目視而兩腳不隨。」又雲：「封畢，詔百官以次下，國家隨後，道迫小，步從匍匐邪上，起近炬火，止亦駱驛，步從觸擊大石，石聲正讙，但讙石無相應和者。腸不能已，口不能默。明日，太醫令問起居，國家雲：『昨上下山，欲行迫前人，欲休則後人所蹈，道峻危險。國家不勞。』」又雲：「東山名曰日觀，鷄一鳴時，見日始欲出，長三丈所。秦觀者望見長安，吳觀者望見會稽，周觀者望見齊。」凡記文之工悉如此，而未嘗見稱於昔賢，秦、吳、周三觀，亦無曾用之者。今應劭書脫略，唯劉昭補註東漢志僅有之，亦非全篇也。","sortOrder":9},
  {"id":"s_work_dtbt_13_10","chapterId":"ch_work_dtbt_13","text":"楊虞卿","sortOrder":10},
  {"id":"s_work_dtbt_13_11","chapterId":"ch_work_dtbt_13","text":"劉禹錫有寄毘陵楊給事詩雲：「曾主魚書輕刺史，今朝自請左魚來。青雲直上無多地，却要斜飛取勢回。」以其時考之，蓋楊虞卿也。按唐文宗大和七年，以李德裕為相，與之論朋黨事。時給事中楊虞卿蕭澣、中書舍人張元夫依附權要，上幹執政，下撓有司，上聞而惡之，於是出虞卿為常州刺史，澣為鄭州刺史，元夫為汝州刺史。皆李宗閔客也。他日，上復言及朋黨，宗閔曰：「臣素知之，故虞卿輩，臣皆不與美官。」德裕曰：「給事中、中書舍人非美官而何？」宗閔失色。然則虞卿之刺毘陵，乃為朝廷所逐耳，禹錫猶以為自請，詩人之言，渠可信哉！","sortOrder":11},
  {"id":"s_work_dtbt_13_12","chapterId":"ch_work_dtbt_13","text":"屯蒙二卦","sortOrder":12},
  {"id":"s_work_dtbt_13_13","chapterId":"ch_work_dtbt_13","text":"屯、蒙二卦，皆二陽而四陰。屯以六二乘初九之剛，蒙以六三乘九二之剛。而屯之爻曰「女子貞不字，十年乃字」，蒙之爻曰「勿用取女，見金夫，不有躬」，其正邪不同如此者。蓋屯二居中得正，不為初剛所誘，而上從九五，所以為貞。蒙三不中不正，見九二之陽，悅而下從之，而舍上九之正應，所以勿用。士之守身居世，而擇所從所處，尚監茲哉！","sortOrder":13},
  {"id":"s_work_dtbt_13_14","chapterId":"ch_work_dtbt_13","text":"漢誹謗法","sortOrder":14},
  {"id":"s_work_dtbt_13_15","chapterId":"ch_work_dtbt_13","text":"漢宣帝詔羣臣議武帝廟樂，夏侯勝曰：「武帝竭民財力，奢泰亡度，天下虛耗，百姓流離，赤地數千里，亡德澤於民，不宜為立廟樂。」於是丞相、御史劾奏勝非議詔書，毀先帝，不道。遂下獄，繫再更冬，會赦，乃得免。章帝時，孔僖、崔駰遊太學，相與論武帝始為天子，崇信聖道，及後恣己，忘其前善。為鄰房生告其誹謗先帝，刺譏當世，下吏受訊，僖以書自訟，乃勿問。元帝時，賈捐之論珠厓事曰：「武帝籍兵厲馬，攘服夷狄，天下斷獄萬數，寇賊並起，軍旅數發，父戰死於前，子鬥傷於後，女子乘亭障，孤兒號於道，老母寡婦飲泣巷哭，是皆廓地泰大，征伐不休之故也。」考三人所指武帝之失，捐之言最切，而三帝或罪或否，豈非夏侯非議詔書，僖、駰誹謗，皆漢法所禁，如捐之直指其事，則在所不問乎？","sortOrder":15},
  {"id":"s_work_dtbt_13_16","chapterId":"ch_work_dtbt_13","text":"誼向觸諱","sortOrder":16},
  {"id":"s_work_dtbt_13_17","chapterId":"ch_work_dtbt_13","text":"賈誼上疏文帝曰：「生為明帝，沒為明神。使顧成之廟，稱為太宗，上配太祖，與漢亡極。雖有愚幼不肖之嗣，猶得蒙業而安。植遺腹，朝委裘，而天下不亂。」又雲：「萬年之後，傳之老母弱子。」此既於生時談死事，至雲「傳之老母」，則是言其當終於太後之前，又目其嗣為「愚幼不肖」，可謂指斥。而帝不以為過，誼不以為疑。劉向上書成帝諫王氏事曰：「王氏與劉氏，且不並立，陛下為人子孫，守持宗廟，而令國祚移於外親，降為皂隸，縱不為身，奈宗廟何！」又雲：「天命所授者博，非獨一姓。」此乃於國存時說亡語，而帝不以為過，向不以為疑，至乞援近宗室，幾於自售，亦不以為嫌也。兩人皆出於忠精至誠，故盡言觸忌諱而不自覺。文帝以寬待下，聖德固爾，而成帝亦能容之，後世難及也。","sortOrder":17},
  {"id":"s_work_dtbt_13_18","chapterId":"ch_work_dtbt_13","text":"小貞大貞","sortOrder":18},
  {"id":"s_work_dtbt_13_19","chapterId":"ch_work_dtbt_13","text":"人君居尊位，倒持太阿，政令有所不行，德澤有所不下，身為寄坐，受人指麾，危亡之形，且立至矣。故易有「屯其膏，小貞，吉；大貞，凶」之戒，謂當以漸而正之。說者多引魯昭公、高貴鄉公為比，予謂此自係一時國家之隆替，君身之禍福，蓋有剛决而得志，隱忍而危亡者，不可一概論也。漢宣帝之誅霍禹，和帝之誅竇憲，桓宗之誅梁冀，魏孝莊之誅爾朱榮，剛決而得志者也。魯昭公之討季氏，齊簡公之謀田常，高貴鄉公之討司馬昭，晉元帝之征王敦，唐文宗之謀宦者，潞王之徙石敬瑭，漢隱帝之殺郭威，剛决而失者也。若齊鬱林王知鸞之異志，欲取之而不能，漢獻帝知曹操之不臣，欲圖之而不果，唐昭宗知朱溫之必，欲殺之而不克，皆翻以及亡，雖欲小正之，豈可得也？","sortOrder":19},
  {"id":"s_work_dtbt_13_20","chapterId":"ch_work_dtbt_13","text":"唐詩戲語","sortOrder":20},
  {"id":"s_work_dtbt_13_21","chapterId":"ch_work_dtbt_13","text":"士人於棋酒間，好稱引戲語，以助譚笑，大抵皆唐人詩，後生多不知所從出，漫識所記憶者於此。「公道世間惟白髮，貴人頭上不曾饒」，杜牧送隱者詩也。「因過竹院逢僧話，又得浮生半日閒」，李涉詩也。「只恐為僧僧不了，為僧得了盡輸僧」，「啼得血流無歇處，不如緘口過殘春」，杜荀鶴詩也。「數聲風笛離亭晚，君向瀟湘我向秦」，鄭穀詩也。「今朝有酒今朝醉，明日愁來明日愁」，「勸君不用分明語，語得分明出轉難」，「自家飛絮猶無定，爭解垂絲絆路人」，「明年更有新條在，撓亂春風卒未休」，「采得百花成蜜後，不知辛苦為誰甜」，羅隱詩也。高駢在西川，築城禦蠻，朝廷疑之，徙鎮荊南，作風箏詩以見意曰：「昨夜箏聲響碧空，宮商信任往來風。依稀似曲才堪聽，又被吹將別調中。」今人亦好引此句也。","sortOrder":21},
  {"id":"s_work_dtbt_13_22","chapterId":"ch_work_dtbt_13","text":"何進高叡","sortOrder":22},
  {"id":"s_work_dtbt_13_23","chapterId":"ch_work_dtbt_13","text":"東漢末，何進將誅宦官，白皇太後悉罷中常侍、小黃門，使還里舍。張讓子婦，太後之妹也。讓向子婦叩頭曰：「老臣得罪，當與新婦俱歸私門，唯受恩累世，今當遠離宮殿，願復一入直，得暫奉望太後顏色，死不恨矣。」子婦為言之，乃詔諸常侍皆復入直。不數日，進乃為讓所殺，董卓隨以兵至，讓等雖死，漢室亦亡。北齊和士開在武成帝世，奸蠧敗國。及後主嗣立，宰相高叡與婁定遠白胡太後，出士開為兗州刺史。後欲留士開過百日，叡守之以死，苦言之。士開載美女珠簾賂定遠曰：「蒙王力，用為方伯，今當遠出，願得一辭覲二宮。」定遠許之，士開由是得見太後及帝，進說曰：「臣出之後，必有大變，今已得入，復何所慮。」於是出定遠為青州而殺叡。後二年，士開雖死，齊室亦亡。嗚呼！奸佞之難去久矣！何進、高叡，不惜隕身破家，為漢、齊社稷計，而張讓、士開以談笑一言，變如反掌，忠良受禍，宗廟為墟。乃知背脅瘭疽，决之不可不速；虎狼在穽，養之則自貽害。可不戒哉！","sortOrder":23},
  {"id":"s_work_dtbt_13_24","chapterId":"ch_work_dtbt_13","text":"南鄉掾史","sortOrder":24},
  {"id":"s_work_dtbt_13_25","chapterId":"ch_work_dtbt_13","text":"金石刻有晉南鄉太守司馬整碑，其陰刻掾史以下姓名，合三百五十一。議曹祭酒十一人，掾二十九人，諸曹掾、史、書佐、循行、幹百三十一人，從掾位者九十六人，從史位者三十一人，部曲督將三十六人，其冗如此。以晉史考之，南鄉本南陽西界，魏武平荊州，始分為郡。至晉泰始中，所管八縣，才二萬戶耳，而掾史若是之多！掾史既然，吏士又可知矣。民力安得不困哉！整乃宗室安平王孚之孫也。","sortOrder":25},
  {"id":"s_work_dtbt_13_26","chapterId":"ch_work_dtbt_13","text":"漢景帝忍殺","sortOrder":26},
  {"id":"s_work_dtbt_13_27","chapterId":"ch_work_dtbt_13","text":"漢景帝恭儉愛民，上繼文帝，故亦稱為賢君。考其天資，則刻戾忍殺之人耳。自在東宮時，因博戲殺吳太子，以起老濞之怨。即位之後，不思罪己，一旦於三郡中而削其二，以速兵端。正信用鼂錯，付以國事，及爰盎之說行，但請斬錯而已，帝令有司劾錯以大逆，遂父母妻子同產皆棄市。七國之役，下詔以深入多殺為功，比三百石以上皆殺，無有所置，敢有議詔及不如詔者，皆要斬。周亞夫以功為丞相，坐爭封匈奴降將事病免，心惡之，賜食不置箸，叱之使起，昧於敬禮大臣之義，卒以非罪置之死，悲哉！光武遣馮異征赤眉，敕之曰：「征伐非必略地屠城，要在平定安集之耳。諸將非不健鬥，然好虜掠。卿本能御吏士，念自修敕，無為郡縣所苦。」光武此言，視景帝詔書，為不侔矣。","sortOrder":27},
  {"id":"s_work_dtbt_13_28","chapterId":"ch_work_dtbt_13","text":"燕昭漢光武之明","sortOrder":28},
  {"id":"s_work_dtbt_13_29","chapterId":"ch_work_dtbt_13","text":"樂毅為燕破齊，或讒之昭王曰：「齊不下者兩城耳，非其力不能拔，欲久仗兵威以服齊人，南面而王耳。」昭王斬言者，遣使立毅為齊王。毅惶恐不受，以死自誓。馮異定關中，自以久在外，不自安。人有章言異威權至重，百姓歸心，號為「鹹陽王」，光武以章示異。異上書謝，詔報曰：「將軍之於國家，恩猶父子，何嫌何疑，而有懼意？」及異破隗囂，諸將欲分其功，璽書誚大司馬以下，稱異功若丘山。今人鹹知毅、異之為名將，然非二君之明，必困讒口矣。田單復齊國，信陵君敗秦兵，陳湯誅郅支，盧植破黃巾，鄧艾平蜀，王濬平吳，謝安却苻堅，慕容垂挫桓溫，史萬歲破突厥，李靖滅吐穀渾，郭子儀、李光弼中興唐室，李晟復京師，皆有大功於社稷，率為譖人所惎，或至殺身。區區庸主不足責，唐太宗亦未能免。營營青蠅，亦可畏哉！","sortOrder":29},
  {"id":"s_work_dtbt_13_30","chapterId":"ch_work_dtbt_13","text":"周南召南","sortOrder":30},
  {"id":"s_work_dtbt_13_31","chapterId":"ch_work_dtbt_13","text":"毛詩序曰：「關雎、麟趾之化，王者之風，故繫之周公，南，言化自北而南也。鵲巢、騶虞之德，諸侯之風也，先王之所以教，故繫之召公。周南、召南，正始之道。」據文義，「周公」、「召公」二「公」字，皆合為「南」字，則與上下文相應，蓋簡策誤耳。「王者之風」，恐不當繫之周公，而「先王之所以教」，又與召公自不相涉也。","sortOrder":31},
  {"id":"s_work_dtbt_13_32","chapterId":"ch_work_dtbt_13","text":"易中爻","sortOrder":32},
  {"id":"s_work_dtbt_13_33","chapterId":"ch_work_dtbt_13","text":"易繫辭雲：「雜物撰德，辨是與非，則非其中爻不備。」中爻者，謂二三四及三四五也。如坤坎為師，而六五之爻曰「長子帥師」，以正應九二而言，蓋指二至四為震也。坤艮為謙，而初六之爻曰「用涉大川」，蓋自是而上，則六二、九三、六四為坎也。歸妹之六五曰「帝乙歸妹」，以下配九二而言，蓋指震也。而泰之六五亦曰「帝乙歸妹」，固亦下配九二，而九三、六四、六五，蓋震體雲。他皆類此。","sortOrder":33},
  {"id":"s_work_dtbt_13_34","chapterId":"ch_work_dtbt_13","text":"容齋隨筆","sortOrder":34},
  {"id":"s_work_dtbt_14_1","chapterId":"ch_work_dtbt_14","text":"卷第十二(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_14_2","chapterId":"ch_work_dtbt_14","text":"利涉大川","sortOrder":2},
  {"id":"s_work_dtbt_14_3","chapterId":"ch_work_dtbt_14","text":"易卦辭稱「利涉大川」者七，「不利涉」者一。爻辭稱「利涉」者二，「用涉」者一，「不可涉」者一。需、訟、未濟，指坎體而言。益、中孚，指巽體而言。渙指坎、巽而言。蓋坎為水，有大川之象。而巽為木，木可為舟楫以濟川。故益之彖曰「木道乃行」，中孚之彖曰「乘木舟虛」，渙之彖曰「乘木有功」。又舟楫之利，實取諸渙，正合二體以取象也。謙、蠱則中爻有坎，同人、大畜則中爻有巽。頤之反，對大過，方有巽體，五去之遠，所以言「不可涉」，上則變而之對卦，故「利涉」雲。","sortOrder":3},
  {"id":"s_work_dtbt_14_4","chapterId":"ch_work_dtbt_14","text":"光武棄馮衍","sortOrder":4},
  {"id":"s_work_dtbt_14_5","chapterId":"ch_work_dtbt_14","text":"漢室中興，固皆光武之功，然更始既即天子位，光武受其爵秩，北面為臣矣，及平王郎，定河北，詔令罷兵，辭不受召，於是始貳焉。更始方困於赤眉，而光武殺其將謝躬、苗曾，取洛陽，下河東，翻為腹心之疾。後世以成敗論人，故不復議。予謂光武知更始不材，必敗大業，逆取順守，尚為有辭。彼鮑永、馮衍，始堅守幷州，不肯降下，聞更始已亡，乃罷兵來歸，曰：「誠慚以其衆幸富貴。」其忠義之節，凜然可稱。光武不能顯而用之，聞其言而不悅。永後以他立功見用，而衍終身擯斥，羣臣亦無為之言者，吁可嘆哉！","sortOrder":5},
  {"id":"s_work_dtbt_14_6","chapterId":"ch_work_dtbt_14","text":"恭顯議蕭望之","sortOrder":6},
  {"id":"s_work_dtbt_14_7","chapterId":"ch_work_dtbt_14","text":"弘恭、石顯議置蕭望之於牢獄，漢元帝知其不肯就吏，而訖可其奏，望之果自殺，帝召顯等責問以議不詳，皆免冠謝，乃已。王氏五侯奢僭，成帝內銜之，一旦赫怒，詔尚書奏誅薄昭故事，然特欲恐之，實無意誅也。竇憲恃宮掖聲勢，奪公主園，章帝切責，有孤雛腐鼠之比，然竟不繩其罪。三君之失政，前史固深譏之矣。司馬公謂元帝始疑望之不肯就獄，恭、顯以為必無憂，其欺既明，終不能治，可謂易欺而難寤也。予謂師傅大臣進退罪否，人主當決之於心，何為謀及宦者？且望之先時已嘗下廷尉矣，使其甘於再辱，忍恥對吏，將遂以恭、顯之議為是耶！望之死與不死，不必論也。成帝委政外家，先漢顛覆，章帝仁柔無斷，後漢遂衰，皆無足責。","sortOrder":7},
  {"id":"s_work_dtbt_14_8","chapterId":"ch_work_dtbt_14","text":"鼂錯張湯","sortOrder":8},
  {"id":"s_work_dtbt_14_9","chapterId":"ch_work_dtbt_14","text":"鼂錯為內史，言事輒聽，幸傾九卿，及為御史大夫，權任出丞相右。張湯為御史，每朝奏事，國家用日旰，丞相取充位，天下事皆決湯。蕭望之為御史，意輕丞相，遇之無禮。三人者，賢否雖不同，然均為非誼，各以他事至死，抑有以致之邪！","sortOrder":9},
  {"id":"s_work_dtbt_14_10","chapterId":"ch_work_dtbt_14","text":"逸詩書","sortOrder":10},
  {"id":"s_work_dtbt_14_11","chapterId":"ch_work_dtbt_14","text":"逸書、逸詩，雖篇名或存，既亡其辭，則其義不復可考。而孔安國註尚書，杜預註左傳，必欲強為之說。書「汨作」註雲，「言其治民之功」；「咎單作明居」註雲，「咎單，主土地之官。作明居，民法」。左傳「國子賦轡之柔矣」註雲，「義取寬政以安諸侯，若柔轡之御剛馬」。如此之類。予頃教授福州日，林之奇少穎為書學諭，講「帝釐下土」數語，曰：「知之為知之，堯典、舜典之所以可言也；不知為不知，九共、槀飫，略之可也。」其說最純明可嘉，林君有書解行於世，而不載此語，故為表出之。","sortOrder":11},
  {"id":"s_work_dtbt_14_12","chapterId":"ch_work_dtbt_14","text":"刑罰四卦","sortOrder":12},
  {"id":"s_work_dtbt_14_13","chapterId":"ch_work_dtbt_14","text":"易六十四卦，而以刑罰之事著於大象者凡四焉。噬嗑曰「先王以明罰敕法」，豐曰「君子以折獄致刑」，賁曰「君子以明庶政，無敢折獄」，旅曰「君子以明慎用刑而不留獄」。噬嗑、旅上卦為離，豐、賁下卦為離。離，明也。聖人知刑獄為人司命，故設卦觀象，必以文明為主，而後世付之文法俗吏，何邪？","sortOrder":13},
  {"id":"s_work_dtbt_14_14","chapterId":"ch_work_dtbt_14","text":"巽為魚","sortOrder":14},
  {"id":"s_work_dtbt_14_15","chapterId":"ch_work_dtbt_14","text":"易卦所言魚，皆指巽也。姤卦巽下乾上，故九二有魚，九四無魚。井內卦為巽，故二有射鮒之象。中孚外卦為巽，故曰「豚魚吉」。剝卦五陰而一陽。方一陰自下生，變乾為姤，其下三爻，乃巽體也。二陰生而為遯，則六二、九三、九四乃巽體。三陰生而為否，則六三、九四、九五乃巽體。四陰生而為觀，則上三爻乃巽體。至五陰為剝，則巽始亡。故六五之爻辭曰「貫魚」，蓋指下四爻皆從巽來，如魚駢頭而貫也。或曰：「說卦不言『巽為魚』，今何以知之？」曰：「以類而知之，說卦所不該者多矣。如『長子』、『長女』、『中女』、『少女』見於震、巽、離、兌中，而坎、艮之下，不言『為中男』、『為少男』之類，他可推也。」","sortOrder":15},
  {"id":"s_work_dtbt_14_16","chapterId":"ch_work_dtbt_14","text":"三省長官","sortOrder":16},
  {"id":"s_work_dtbt_14_17","chapterId":"ch_work_dtbt_14","text":"中書、尚書令在西漢時為少府官屬，與太官、湯官、上林諸令品秩略等，侍中但為加官，在東漢亦屬少府，而秩稍增，尚書令為千石，然銅印墨綬，雖居幾要，而去公卿甚遠，至或出為縣令。魏、晉以來，浸以華重，唐初遂為三省長官，居真宰相之任，猶列三品。大曆中乃升正二品。入國朝，其位益尊，敍班至在太師之上，然只以為親王及使相兼官，無單拜者。見任宰相帶侍中者才五人：范魯公質、趙韓王普、丁晉公謂、馮魏公拯、韓魏王琦。尚書令又最貴，除宗王外，不以假人。趙韓王、韓魏王始贈真令，韓公官止司徒，及贈尚書令，乃詔自今更不加增，蓋不欲以三師之官，贅其稱也。政和初，蔡京改侍中、中書令為左輔、右弼，而不置尚書令，以為太宗皇帝曾任此官。殊不知乃唐之太宗為之，故郭子儀不敢拜，非本朝也。","sortOrder":17},
  {"id":"s_work_dtbt_14_18","chapterId":"ch_work_dtbt_14","text":"王珪李靖","sortOrder":18},
  {"id":"s_work_dtbt_14_19","chapterId":"ch_work_dtbt_14","text":"杜子美送重表姪王評事詩雲：「我之曾老姑，爾之高祖母。爾祖未顯時，歸為尚書婦。隋朝大業末，房杜俱交友。長者來在門，荒年自餬口。家貧無供給，客位但箕帚。俄頃羞頗珍，寂寥人散後。」雲雲。「上雲天下亂，宜與英俊厚。向竊窺數公，經綸亦俱有。次問最少年，虬髯十八九。子等成大名，皆因此人手。下雲風雲合，龍虎一吟吼。願展丈夫雄，得辭兒女醜。秦王時在坐，真氣驚戶牖。及乎貞觀初，尚書踐台斗。夫人常肩輿，上殿稱萬壽。至尊均嫂叔，盛事垂不朽。」觀此詩，疑指王珪。珪相唐太宗，贈禮部尚書。然細考其事，大不與史合。蔡絛詩話引唐書列女傳雲：「珪母盧氏，識房、杜必貴。」質之此詩，則珪母乃杜氏也。桐江詩話雲：「不特不姓盧，乃珪之妻，非母也。」予按唐列女傳元無此事，珪傳末只雲：「始隱居時，與房玄齡、杜如晦善，二人過其家，母李窺之，知其必貴。」蔡說妄雲有傳，又誤以李為盧，皆不足辨。但唐高祖在位日，太子建成與秦王不睦，以權相傾。珪為太子中允，說建成曰：「秦王功蓋天下，中外歸心，殿下但以長年，位居東宮，無大功以鎮服海內，今劉黑闥散亡之餘，宜自擊之，以取功名。」建成乃請行。其後楊文幹之事起，高祖責以兄弟不睦，歸罪珪等而流之。太宗即位，乃召還任用。久之，宴近臣於丹霄殿，長孫無忌曰：「王珪、魏徵，昔為仇讎，不謂今日得同此宴。」上曰：「珪、徵盡心所事，我故用之。」然則珪與太宗，非素交明矣。唐書載李氏事，亦采之小說，恐未必然，而杜公稱其祖姑事，不應不實。且太宗時宰相，別無姓王者，真不可曉也。","sortOrder":19},
  {"id":"s_work_dtbt_14_20","chapterId":"ch_work_dtbt_14","text":"又有杜光庭虬鬚客傳雲，隋煬帝幸江都，命楊素留守西京，李靖以布衣往謁，竊其一妓，道遇異人，與俱至太原，因劉文靜以見州將之子，言其真英主，傾家資與靖，使助創業之舉，即太宗也。按史載唐公擊突厥，靖察有非常志，自囚上急變。後高祖定京師，將斬之而止，必無先識太宗之事。且煬帝在江都時，楊素死已十餘年矣。此一傳，大抵皆妄雲。","sortOrder":20},
  {"id":"s_work_dtbt_14_21","chapterId":"ch_work_dtbt_14","text":"虎夔藩","sortOrder":21},
  {"id":"s_work_dtbt_14_22","chapterId":"ch_work_dtbt_14","text":"黃魯直宿舒州太湖觀音院詩雲：「汲烹寒泉窟，伐燭古松根。相戒莫浪出，月黑虎夔藩。」夔字甚新，其意蓋言抵觸之義，而莫究所出。惟杜工部課伐木詩序雲：「課隸人入穀斬陰木，晨征暮返，我有藩籬，是闕是補，旅次於小安。山有虎，知禁。若恃爪牙之利，必昏黑摚突。夔人屋壁，列樹白桃，鏝焉牆，實以竹，示式遏。為與虎近，混淪乎無良賓客。」其詩句有雲：「藉汝跨小籬，乳獸待人肉。虎穴連里閭，久客懼所觸。」乃知魯直用此序中語。然杜公在夔府所作詩，所謂「夔人」者，述其土俗耳，本無抵觸之義，魯直蓋誤用之。","sortOrder":22},
  {"id":"s_work_dtbt_14_23","chapterId":"ch_work_dtbt_14","text":"又寺齋睡起絕句雲：「人言九事八為律，儻有江船吾欲東。」按主父偃傳，「上書言九事，其八事為律令，一事諫伐匈奴」，謂八事為律令而言，則為字當作去聲讀，今魯直似以為平聲，恐亦誤也。","sortOrder":23},
  {"id":"s_work_dtbt_14_24","chapterId":"ch_work_dtbt_14","text":"曹操用人","sortOrder":24},
  {"id":"s_work_dtbt_14_25","chapterId":"ch_work_dtbt_14","text":"曹操為漢鬼蜮，君子所不道，然知人善任使，實後世之所難及。荀彧、荀攸、郭嘉皆腹心謀臣，共濟大事，無待贊說。其餘智效一官，權分一郡，無小無大，卓然皆稱其職。恐關中諸將為害，則屬司隸校尉鍾繇以西事，而馬騰、韓遂遣子入侍。當天下亂離，諸軍乏食，則以棗祗、任峻建立屯田，而軍國饒裕，遂芟羣雄。欲復鹽官之利，則使衞覬鎮撫關中，而諸將服。河東未定，以杜畿為太守，而衞固、范先束手禽戮。幷州初平，以梁習為刺史，而邊境肅清。揚州陷於孫權，獨有九江一郡，付之劉馥而恩化大行。馮翊困於鄜盜，付之鄭渾而民安寇滅。代郡三單於，恃力驕恣，裴潛單車之郡，而單於讋服。方得漢中，命杜襲督留事，而百姓自樂，出徙於洛、鄴者，至八萬口。方得馬超之兵，聞當發徙，驚駭欲變，命趙儼為護軍，而相率還降，致於東方者亦二萬口。凡此十者，其為利豈不大哉！張遼走孫權於合肥，郭淮拒蜀軍於陽平，徐晃却關羽於樊，皆以少製衆，分方面憂。操無敵於建安之時，非幸也。","sortOrder":25},
  {"id":"s_work_dtbt_14_26","chapterId":"ch_work_dtbt_14","text":"漢士擇所從","sortOrder":26},
  {"id":"s_work_dtbt_14_27","chapterId":"ch_work_dtbt_14","text":"漢自中平黃巾之亂，天下震擾，士大夫莫不擇所從，以為全身遠害之計，然非豪傑不能也。荀彧少時，以潁川四戰之地，勸父老亟避之，鄉人多懷土不能去，彧獨率宗族往冀州，袁紹待以上賓之禮，彧度紹終不能定大業，去而從曹操，其鄉人留者，多為賊所殺。袁紹遣使迎汝南士大夫，和洽獨往荊州，劉表以上客待之，洽曰：「所以不從本初，避爭地也。昏世之主，不可黷近，久而不去，讒慝將興。」遂南之武陵，其留者多為表所害。曹操牧兗州，陳留太守張邈與之親友。郡士高柔獨以為邈必乘間為變，率鄉人欲避之，衆皆以曹、張相親，不然其言。柔舉家適河北，邈果叛操。郭嘉初見袁紹，謂其謀臣辛評等曰：「智者審於量主，袁公多端寡要，好謀無決，難與共濟大難，吾將更舉以求主，子盍去乎？」評等曰：「袁氏今最強，去將何之？」嘉不復言，遂去依曹操。操召見，與論天下事。出曰：「真吾主也。」杜襲、趙儼、繁欽避亂荊州，欽數見奇於表，襲曰：「所以俱來者，欲全身以待時耳。子若見能不已，非吾徒也。」及天子都許，儼曰：「曹鎮東必能濟華夏，吾知歸矣，遂詣操。」河間邢顒在無終，聞操定冀州，謂田疇曰：「聞曹公法令嚴，民厭亂矣，亂極則平，請以身先。」遂裝還鄉里。疇曰：「顒，天民之先覺者也。」孫策定丹陽，呂範請暫領都督，策曰：「子衡已有大衆，豈宜復屈小職！」範曰：「今捨本土而託將軍者，欲濟世務也，譬猶同舟涉海，一事不牢，即俱受其敗，此亦範計，非但將軍也。」策從之。周瑜聞策聲問，便推結分好，及策卒權立，瑜謂權可與共成大業，遂委心服事焉。諸葛亮在襄陽，劉表不能起，一見劉備，事之不疑。此諸人識見如是，安得困於亂世哉！","sortOrder":27},
  {"id":"s_work_dtbt_14_28","chapterId":"ch_work_dtbt_14","text":"劉公榮","sortOrder":28},
  {"id":"s_work_dtbt_14_29","chapterId":"ch_work_dtbt_14","text":"王戎詣阮籍，時兗州刺史劉昶字公榮在坐，阮謂王曰：「偶有二斗美酒，當與君共飲。彼公榮者無預焉。」二人交觴酬酢，公榮遂不得一杯，而言語談戲，三人無異。或有問之者，阮曰：「勝公榮者，不得不與飲酒，不如公榮者，不可不與飲酒，唯公榮可不與飲酒。」此事見戎傳，而世說為詳。又一事雲，公榮與人飲酒，雜穢非類，人或譏之，答曰：「勝公榮者，不可不與飲，不如公榮者，亦不可不與飲，是公榮輩者，又不可不與飲，故終日共飲而醉。」二者稍不同。公榮待客如是，費酒多矣，顧不蒙一杯於人乎？東坡詩雲：「未許低頭拜東野，徒言共飲勝公榮。」蓋用前事也。","sortOrder":29},
  {"id":"s_work_dtbt_14_30","chapterId":"ch_work_dtbt_14","text":"元豐官製","sortOrder":30},
  {"id":"s_work_dtbt_14_31","chapterId":"ch_work_dtbt_14","text":"元豐官製初成，欲以司馬公為御史大夫，又將俟建儲時，以公及呂申公為保傅。元祐初，起文潞公於既老，議處以侍中、中書令，為言者所攻，乃改平章軍國重事。自後習以為製，不復除此等官，以謂前無故事，其實不然也。紹興二十五年十月，中批右正言張扶除太常卿，執政言自來太常不置卿，遂改宗正，復言之，乃以為國子祭酒。近歲除莫濟祕書監，濟辭避累日，然後就職。已而李燾、陳騤、鄭丙皆為之，均曰：「職事官，何不可除之有？」","sortOrder":31},
  {"id":"s_work_dtbt_14_32","chapterId":"ch_work_dtbt_14","text":"耳餘袁劉","sortOrder":32},
  {"id":"s_work_dtbt_14_33","chapterId":"ch_work_dtbt_14","text":"張耳、陳餘少時為刎頸交，其後爭權，相與致死地而不厭，蓋勢利之極，其究必然。韓馥舉冀州以迎袁紹，而終以懼死。劉璋開門延劉備，坐失益州。翟讓提兵授李密，而舉族不免。爾朱兆以六鎮之衆付高歡而卒斃於歡手。紹、密、歡忘其所自，不足深責。孰謂玄德之長者而忍為此邪！","sortOrder":33},
  {"id":"s_work_dtbt_14_34","chapterId":"ch_work_dtbt_14","text":"周漢存國","sortOrder":34},
  {"id":"s_work_dtbt_14_35","chapterId":"ch_work_dtbt_14","text":"周之初，諸侯千八百國，至王赧之亡，所存者才八國耳，七戰國與衞也。然趙、韓、魏分晉而立，齊田氏代薑而興，其有土各不及二百年，俱非舊邦。秦始皇乃呂氏子，楚幽王乃黃氏子，所謂嬴、羋之先，當不歆非類。然則惟燕、衞二姬姓存，而衞至胡亥世乃絕，若以為召公、康叔之德，則周公豈不及乎！","sortOrder":35},
  {"id":"s_work_dtbt_14_36","chapterId":"ch_work_dtbt_14","text":"漢列侯八百餘人，及光武而存者，平陽、建平、富平三侯耳。建平以先降梁王，永奪國。平陽為曹參之後，富平為張安世之後，參猶有創業之功，若安世則湯子也，史稱其推賢揚善，固宜有後，然輕重其心，殺人亦多矣，獨無餘殃乎！漢侯之在王莽朝，皆不奪國，光武乃但許宗室復故，餘皆除之，雖酇侯亦不紹封，不知曹、張兩侯，何以能獨全也？","sortOrder":36},
  {"id":"s_work_dtbt_14_37","chapterId":"ch_work_dtbt_14","text":"曹操殺楊脩","sortOrder":37},
  {"id":"s_work_dtbt_14_38","chapterId":"ch_work_dtbt_14","text":"曹操殺楊脩之後，見其父彪，問曰：「公何瘦之甚？」對曰：「愧無日磾先見之明，猶懷老牛（舌氐）犢之愛。」操為之改容。古文苑載操與彪書，數脩之罪，以為恃豪父之勢，每不與吾同懷，將延足下尊門大累，便令刑之。且贈彪錦裘二領，八節角桃杖一枝，青牸牛二頭，八百里驊騮馬一匹，四望通幰七香車一乘，驅使二人。又遺其妻裘、鞾、有心青衣二人，錢絹甚厚。卞夫人亦與袁夫人書雲：「賢郎有蓋世文才，闔門欽敬，明公性急，輒行軍法。」以衣服、文絹、房子官錦、香車送之。彪及袁夫人皆答書引愆致謝。是時漢室將亡，政在曹氏，袁公四世宰相，為漢宗臣，固操之所忌，彪之不死其手，幸矣。嗚呼危哉！","sortOrder":38},
  {"id":"s_work_dtbt_14_39","chapterId":"ch_work_dtbt_14","text":"古人重國體","sortOrder":39},
  {"id":"s_work_dtbt_14_40","chapterId":"ch_work_dtbt_14","text":"古人為邦，以國體為急，初無小大強弱之異也。其所以自待，及以之待人，亦莫不然。故執言修辭，非賢大夫不能盡。楚申舟不假道於宋而聘齊，宋華元止之，曰：「過我而不假道，鄙我也。鄙我，亡也。殺其使者，必伐我。伐我，亦亡也。亡，一也。」乃殺之。及楚子圍宋既急，猶曰：「城下之盟，有以國斃，不能從也。」鄭三卿為盜所殺，餘盜在宋，鄭人納賂以請之。師慧曰：「以千乘之相，易淫樂之矇，宋無人焉故也。」子罕聞之，固請而歸其賂。晉韓宣子有環在鄭商，謁諸鄭伯，子產弗與，曰：「大國之求，無禮以斥之，何饜之有？吾且為鄙邑，則失位矣。若大國令而共無藝，鄭鄙邑也，亦弗為也。」晉合諸侯於平丘，子產爭貢賦之次，子大叔咎之。子產曰：「國不競亦陵，何國之為！」鄭駟偃娶於晉，偃卒，鄭人舍其子而立其弟，晉人來問，子產對客曰：「若寡君之二三臣，其即世者，晉大夫而專製其位，是晉之縣鄙也，何國之為！」楚囚鄭印堇父，獻於秦，鄭以貨請之。子產曰：「不獲。受楚之功，而取貨於鄭，不可謂國，秦不其然。若曰鄭國微君之惠，楚師其猶在敝邑之城下。」弗從，秦人不予。更幣，從子產而後獲之。讀此數事，知春秋列國各數百年，其必有道矣。","sortOrder":40},
  {"id":"s_work_dtbt_14_41","chapterId":"ch_work_dtbt_14","text":"容齋隨筆","sortOrder":41},
  {"id":"s_work_dtbt_15_1","chapterId":"ch_work_dtbt_15","text":"卷第十三(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_15_2","chapterId":"ch_work_dtbt_15","text":"諫說之難","sortOrder":2},
  {"id":"s_work_dtbt_15_3","chapterId":"ch_work_dtbt_15","text":"韓非作說難，而死於說難，蓋諫說之難，自古以然。至於知其所欲說，迎而拒之，然卒至於言聽而計行者，又為難而可喜者也。秦穆公執晉侯，晉陰飴甥往會盟，其為晉遊說無可疑者。秦伯曰：「晉國和乎？」對曰：「不和。小人曰必報仇，君子曰必報德。」秦伯曰：「國謂君何？」曰：「小人謂之不免，君子以為必歸；以德為怨，秦不其然。」秦遂歸晉侯。秦伐趙，趙求救於齊，齊欲長安君為質。太後不肯，曰：「復言者老婦必唾其面。」左師觸龍願見，後盛氣而揖之入，知其必用此事來也。左師徐坐，問後體所苦，繼乞以少子補黑衣之缺。後曰：「丈夫亦愛憐少子乎？」曰：「甚於婦人。」然後及其女燕後，乃極論趙王三世之子孫無功而為侯者，禍及其身。後既寤，則言：「長安君何以自託於趙？」於是後曰：「恣君之所使。」長安遂出質。范雎見疏於秦，蔡澤入秦，使人宣言感怒雎，曰：「燕客蔡澤天下辯士也。彼一見秦王，必奪君位。」雎曰：「百家之說，吾既知之，衆口之辯，吾皆摧之，是惡能奪我位乎？」使人召澤，謂之曰：「子宣言欲代我相，有之乎？」對曰：「然。」即引商君、吳起、大夫種之事。雎知澤欲困己以說，謬曰：「殺身成名，何為不可？」澤以身名俱全之說誘之，極之以閎夭、周公之忠聖。今秦王不倍功臣，不若秦孝公、楚越王，雎之功不若三子，勸其歸相印以讓賢。雎竦然失其宿怒，忘其故辯，敬受命，延入為上客。卒之代為秦相者澤也。秦始皇遷其母，下令曰：「敢以太後事諫者殺之。」死者二十七人矣。茅焦請諫，王召鑊將亨之。焦數以桀、紂狂悖之行，言未絕口，王母子如初。呂甥之言出於義，左師之計伸於愛，蔡澤之說激於理，若茅焦者真所謂劘虎牙者矣。范雎親困穰侯而奪其位，何遽不如澤哉！彼此一時也。","sortOrder":3},
  {"id":"s_work_dtbt_15_4","chapterId":"ch_work_dtbt_15","text":"韓馥劉璋","sortOrder":4},
  {"id":"s_work_dtbt_15_5","chapterId":"ch_work_dtbt_15","text":"韓馥以冀州迎袁紹，其僚耿武、閔純、李歷、趙浮、程渙等諫止之，馥不聽。紹既至，數人皆見殺。劉璋迎劉備，主簿黃權王累、名將楊懷高沛止之，璋逐權，不納其言，二將後為備所殺。王浚受石勒之詐，督護孫緯及將佐皆欲拒勒，浚怒欲斬之，果為勒所殺。武、純、懷、沛諸人謂之忠於所事可矣，若雲擇君，則未也。嗚呼！生於亂世，至死不變，可不謂賢矣乎？","sortOrder":5},
  {"id":"s_work_dtbt_15_6","chapterId":"ch_work_dtbt_15","text":"蕭房知人","sortOrder":6},
  {"id":"s_work_dtbt_15_7","chapterId":"ch_work_dtbt_15","text":"漢祖至南鄭，韓信亡去，蕭何自追之。上罵曰：「諸將亡者以十數，公無所追；追信，詐也。」何曰：「諸將易得，至如信，國士亡雙，必欲爭天下，非信無可與計事者。」乃拜信大將，遂成漢業。唐太宗為秦王時，府屬多外遷，王患之。房喬曰：「去者雖多不足吝，杜如晦王佐才也，王必欲經營四方，捨如晦無共功者。」乃表留幕府，遂為名相。二人之去留，係興替治亂如此，蕭、房之知人，所以為莫及也。樊噲從高祖起豐、沛，勸霸上之還，解鴻門之厄，功亦不細矣，而韓信羞與為伍。唐儉贊太宗建大策，發蒲津之謀，定突厥之計，非庸臣也，而李靖以為不足惜。蓋以信、靖而視噲、儉，猶熊羆之與狸狌耳。帝王之功，非一士之略，必待將如韓信，相如杜公，而後用之，不亦難乎！惟能置蕭、房於帷幄中，拔茅彙進，則珠玉無脛而至矣。","sortOrder":7},
  {"id":"s_work_dtbt_15_8","chapterId":"ch_work_dtbt_15","text":"兪似詩","sortOrder":8},
  {"id":"s_work_dtbt_15_9","chapterId":"ch_work_dtbt_15","text":"英州之北三十里有金山寺，予嘗至其處，見法堂後壁題兩絕句。僧雲：「廣州鈐轄兪似之妻趙夫人所書。」詩句洒落不凡，而字畫徑四寸，遒健類薛稷，極可喜。數年後又過之，僧空無人，壁亦隳圮，猶能追憶其語，為紀於此，其一雲：「莫遣韝鷹飽一呼，將軍誰志滅匈奴？年來萬事灰人意，只有看山眼不枯。」其二雲：「傳食膠膠擾擾間，林泉高步未容攀。興來尚有平生屐，管領東南到處山。」蓋似所作也。","sortOrder":9},
  {"id":"s_work_dtbt_15_10","chapterId":"ch_work_dtbt_15","text":"吳激小詞","sortOrder":10},
  {"id":"s_work_dtbt_15_11","chapterId":"ch_work_dtbt_15","text":"先公在燕山，赴北人張總侍御家集。出侍兒佐酒，中有一人，意狀摧抑可憐，叩其故，乃宣和殿小宮姬也。坐客翰林直學士吳激賦長短句紀之，聞者揮涕。其詞曰：「南朝千古傷心地，還唱後庭花。舊時王、謝，堂前燕子，飛向誰家？恍然相遇，仙姿勝雪，宮髻堆鴉。江州司馬，青衫濕淚，同是天涯。」激字彥高，米元章壻也。","sortOrder":11},
  {"id":"s_work_dtbt_15_12","chapterId":"ch_work_dtbt_15","text":"君子為國","sortOrder":12},
  {"id":"s_work_dtbt_15_13","chapterId":"ch_work_dtbt_15","text":"傳曰：「不有君子，其能國乎？」古之為國，言辭抑揚，率以有人無人占輕重。晉以詐取士會於秦，繞朝曰：「子無謂秦無人，吾謀適不用也。」楚子反曰：「以區區之宋，猶有不欺人之臣，可以楚而無乎？」宋受鄭賂，鄭師慧曰：「宋必無人。」魯盟臧紇之罪，紇曰：「國有人焉。」賈誼論匈奴之嫚侮，曰：「倒懸如此，莫之能解，猶謂國有人乎？」後之人不能及此，然知敵之不可犯，猶曰彼有人焉，未可圖也。一士重於九鼎，豈不信然？","sortOrder":13},
  {"id":"s_work_dtbt_15_14","chapterId":"ch_work_dtbt_15","text":"兌為羊","sortOrder":14},
  {"id":"s_work_dtbt_15_15","chapterId":"ch_work_dtbt_15","text":"兌為羊，易之稱羊者凡三卦。夬之九四曰「牽羊悔亡」，歸妹之上六曰「士刲羊，無血」，皆兌也。大壯內外卦為震與乾，而三爻皆稱羊者，自復之一陽推而上之，至二為臨，則兌體已見，故九三曰「羝羊觸藩，羸其角」，言三陽為泰而消兌也。自是而陽上進，至於乾而後已。六五「喪羊於易」，謂九三、九四、六五為兌也，上六復「觸藩不能退」，蓋陽方夬決，豈容上兌儼然乎？九四中爻亦本兌，而雲「不羸」者，賴震陽之壯耳。","sortOrder":15},
  {"id":"s_work_dtbt_15_16","chapterId":"ch_work_dtbt_15","text":"晏子揚雄","sortOrder":16},
  {"id":"s_work_dtbt_15_17","chapterId":"ch_work_dtbt_15","text":"齊莊公之難，晏子不死不亡，而曰：「君為社稷死則死之，為社稷亡則亡之；若為己死而為己亡，非其私暱，誰敢任之？」及崔杼、慶封盟國人曰：「所不與崔、慶者。」晏子嘆曰：「嬰所不唯忠於君，利社稷者是與，有如上帝！」晏子此意正與豫子所言衆人遇我之義同，特不以身殉莊公耳。至於毅然據正以社稷為辭，非豫子可比也。揚雄仕漢，親蹈王莽之變，退託其身於列大夫中，不與高位者同其死，抱道沒齒，與晏子同科。世儒或以劇秦美新貶之；是不然，此雄不得已而作也。夫誦述新莽之德，止能美於暴秦，其深意固可知矣。序所言配五帝冠三王，開闢以來未之聞，直以戲莽爾。使雄善為諛佞，撰符命，稱功德，以邀爵位，當與國師公同列，豈固窮如是哉？","sortOrder":17},
  {"id":"s_work_dtbt_15_18","chapterId":"ch_work_dtbt_15","text":"一以貫之","sortOrder":18},
  {"id":"s_work_dtbt_15_19","chapterId":"ch_work_dtbt_15","text":"「一以貫之」之語，聖賢心學也，夫子以告曾子、子貢，而學者猶以為不同。尹彥明曰：「子貢之於學，不及曾子也如此。孔子於曾子，不待其問而告之，曾子復深喻之曰『唯』。至於子貢，則不足以知之矣，故先發『多學而識之』之問，果不能知之以為然也，又復疑其不然而請焉，方告之曰『予一以貫之』。雖聞其言，猶不能如曾子之唯也。」范淳父亦曰：「先攻子貢之失，而後語以至要。」予竊以為二子皆孔門高第也，其聞言而唯，與夫聞而不復問，皆已默識於言意之表矣。世儒所以卑子貢者，為其先然「多學而識之」之旨也，是殆不然。方聞聖言如是，遽應曰「否」，非弟子所以敬師之道也，故對曰「然」，而即繼以「非與」之問，豈為不能知乎？或者至以為孔子擇而告參、賜，蓋非餘人所得聞，是又不然。顏氏之子，冉氏之孫，豈不足以語此乎？曾子於一「唯」之後，適門人有問，故發其「忠恕」之言。使子貢是時亦有從而問者，其必有以詔之矣。","sortOrder":19},
  {"id":"s_work_dtbt_15_20","chapterId":"ch_work_dtbt_15","text":"裴潛陸俟","sortOrder":20},
  {"id":"s_work_dtbt_15_21","chapterId":"ch_work_dtbt_15","text":"曹操以裴潛為代郡太守，服烏丸三單於之亂。後召潛還，美其治代之功，潛曰：「潛於百姓雖寬，於諸胡為峻。今繼者必以潛為治過嚴，而事加寬惠；彼素驕恣，過寬必弛，既弛又將攝之以法，此怨叛所由生也。以勢料之，代必復叛。」於是操深悔還潛之速。後數十日，單於反問果至。元魏以陸俟為懷荒鎮將，高車諸莫弗訟俟嚴急無恩，復請前鎮將郎孤。魏使孤代俟，俟既至，言曰：「不過期年，郎孤必敗，高車必叛。」世祖切責之。明年，諸莫弗果殺孤而叛。帝召俟問曰：「何以知其然？」俟曰：「高車不知上下之禮，故臣製之以法，使知分限，而諸莫弗訟臣無恩，稱孤之美。孤獲還鎮，悅其稱譽，專用寬恕待之，無禮之人，易生驕慢，孤必將復以法裁之，衆心怨懟，必生禍亂矣！」帝然之。裴潛、陸俟，可謂知為治之道矣。鄭子產戒子大叔曰：「惟有德者能以寬服人，其次莫如猛。」大叔不忍猛而寬，是以致萑苻之盜，故孔子有寬猛相濟之說。烏丸、高車，不知禮法，裴、陸先之以威，使其久而服化，必漸施之以寬政矣。後之人讀紙上語，專以鷹擊毛摯為治，而不思救弊之術，無問華夷，吾見其敗也。","sortOrder":21},
  {"id":"s_work_dtbt_15_22","chapterId":"ch_work_dtbt_15","text":"拔亡為存","sortOrder":22},
  {"id":"s_work_dtbt_15_23","chapterId":"ch_work_dtbt_15","text":"燕樂毅伐齊，下七十餘城，所存者唯莒、即墨兩城耳，賴田單之力，齊復為齊，尺寸之土無所失。曹操牧兗州，州叛迎呂布，郡縣八十城皆應之，唯鄄城、范、東阿不動，賴荀彧、程昱之力，卒全三城以待操，州境復安。古之人拔亡為存，轉禍為福，如此多矣。靖康、建炎間，國家不競，秦、魏、齊、韓之地，名都大邑數百，翦而為戎，越五十年矣，以今準古，豈曰無人乎哉？","sortOrder":23},
  {"id":"s_work_dtbt_15_24","chapterId":"ch_work_dtbt_15","text":"孫吳四英將","sortOrder":24},
  {"id":"s_work_dtbt_15_25","chapterId":"ch_work_dtbt_15","text":"孫吳奄有江左，亢衡中州，固本於策、權之雄略，然一時英傑，如周瑜、魯肅、呂蒙、陸遜四人者，真所謂社稷心膂，與國為存亡之臣也。自古將帥，未嘗不矜能自賢，疾勝己者，此諸賢則不然。孫權初掌事，肅欲北還，瑜止之，而薦之於權曰：「肅才宜佐時，當廣求其比，以成功業。」後瑜臨終與權牋曰：「魯肅忠烈，臨事不苟，若以代瑜，死不朽矣！」肅遂代瑜典兵。呂蒙為尋陽令，肅見之曰：「卿今者才略非復吳下阿蒙。」遂拜蒙母，結友而別。蒙遂亦代肅。蒙在陸口，稱疾還，權問：「誰可代者？」蒙曰：「陸遜意思深長，才堪負重，觀其規慮，終可大任，無復是過也。」遜遂代蒙。四人相繼，居西邊三四十年，為威名將，曹操、劉備、關羽皆為所挫，雖更相汲引，而孫權委心聽之，吳之所以為吳，非偶然也。","sortOrder":25},
  {"id":"s_work_dtbt_15_26","chapterId":"ch_work_dtbt_15","text":"東坡羅浮詩","sortOrder":26},
  {"id":"s_work_dtbt_15_27","chapterId":"ch_work_dtbt_15","text":"東坡遊羅浮山，作詩示叔黨，其末雲：「負書從我盍歸去，羣仙正草新宮銘。汝應奴隸蔡少霞，我亦季孟山玄卿。」坡自註曰：「唐有夢書新宮銘者，雲紫陽真人山玄卿撰。其略曰：『良常西麓，原澤東泄。新宮宏宏，崇軒（車獻）（車獻）。』又有蔡少霞者，夢人遣書碑銘曰：『公昔乘魚車，今履瑞雲，躅空仰塗，綺輅輪囷。』其末題雲，五雲書閣吏蔡少霞書。」予按唐小說薛用弱集異記，載蔡少霞夢人召去，令書碑，題雲：蒼龍溪新宮銘，紫陽真人山玄卿撰。其詞三十八句，不聞有五雲閣吏之說。魚車瑞雲之語，乃逸史所載陳幼霞事，雲蒼龍溪主歐陽某撰。蓋坡公誤以幼霞為少霞耳。玄卿之文，嚴整高妙，非神仙中人嵇叔夜、李太白之流不能作，今紀於此，雲：「良常西麓，源澤東泄。新宮宏宏，崇軒（車獻）（車獻）。雕珉盤礎，鏤檀竦楶。碧瓦鱗差，瑤階肪截。閣凝瑞霧，樓橫祥霓。騶虞巡徼，昌明捧闑。珠樹規連，玉泉矩洩。靈飆遐集，聖日俯哳。太上遊儲，無極便闕。百神守護，諸真班列。仙翁鵠立，道師冰潔。飲玉成漿，饌瓊為屑。桂旗不動，蘭幄互設。妙樂競奏，流鈴間發。天籟虛徐，風簫泠澈。鳳歌諧律，鶴舞會節。三變玄雲，九成絳雪。易遷徒語，童初詎說。如毀乾坤，自有日月。清寧二百三十一年四月十二日建。」予頃作廣州三清殿碑，仿其體為銘詩曰：「天池北阯，越領東鹿。銀宮旟旟，瑤殿矗矗。陛納九齒，閶披四目。楯角儲清，簷牙袤縟。雕牖（穀甘）閜，鏤楹熠煜。元尊端拱，泰上秉籙。繡黼周張，神光睟穆。寶帳流黃，溫幈結綠。翠鳳於旗，紫霓溜褥。星伯振鷺，仙翁立鵠。昌明侍幾，眉連捧纛。月節下墮，曦輪旁燭。凍雨清塵，矞雲散縠。鈞籟虛徐，流鈴祿續。童初渟瀯，勾漏蓄縮。嶽君有衡，海帝維儵。中邊何護，時節朝宿。颶母淪威，瘧妃謝毒。丹厓罷徼，赤子纍福。億齡聖壽，萬世宋籙。」凡四十句，讀者或許之，然終不近也。","sortOrder":27},
  {"id":"s_work_dtbt_15_28","chapterId":"ch_work_dtbt_15","text":"魏明帝容諫","sortOrder":28},
  {"id":"s_work_dtbt_15_29","chapterId":"ch_work_dtbt_15","text":"魏明帝時，少府楊阜上疏，欲省宮人諸不見幸者，乃召御府吏問後宮人數。吏守舊令，對曰：「禁密，不得宣露。」阜怒，杖吏一百，數之曰：「國家不與九卿為密，反與小吏為密乎？」帝愈嚴憚之。房玄齡、高士廉問少府少監竇德素北門近有何營造，德素以聞。太宗大怒，謂玄齡等曰：「君但知南牙耳，北門小小營造，何預君事耶？」玄齡等拜謝。夫太宗之與明帝，不待比擬，觀所以責玄齡之語，與夫嚴憚楊阜之事，不迨遠矣；賢君一話一言，為後世法。惜哉！魏史以謂「羣臣直諫之言，帝雖不能盡用，然皆優容之，雖非誼主，亦可謂有君人之量矣。」","sortOrder":29},
  {"id":"s_work_dtbt_15_30","chapterId":"ch_work_dtbt_15","text":"漢世謀於衆","sortOrder":30},
  {"id":"s_work_dtbt_15_31","chapterId":"ch_work_dtbt_15","text":"兩漢之世，事無小大，必謀之於衆人，予前論之矣，然亦有持以藉口掩衆議者。霍光薨後，宣帝出其親屬補吏，張敞言：「朝臣宜有明言霍氏顓製，請罷三侯就第。明詔以恩不聽，羣臣以義固爭而後許之。今明詔自親其文，非策之得者也。」哀帝欲封董賢等，王嘉言：「宜延問公卿、大夫、博士、議郎，明正其義，然後乃加爵土；不然，恐大失衆心。暴平其事，必有言當封者，在陛下所從；天下雖不說，咎有所分，不獨在陛下。前成帝初封淳於長，其事亦議。穀永以長當封，衆人歸咎於永，先帝不獨蒙其譏。」哀帝乃止。是知委曲遷就，使恩出君上，過歸於下，漢代多如此也。","sortOrder":31},
  {"id":"s_work_dtbt_15_32","chapterId":"ch_work_dtbt_15","text":"國朝會要","sortOrder":32},
  {"id":"s_work_dtbt_15_33","chapterId":"ch_work_dtbt_15","text":"國朝會要，自元豐三百卷之後，至崇寧、政和間，復置局修纂。宣和初，王黼秉政，罷修書五十八所。時會要已進一百十卷，餘四百卷亦成，但局中欲節次覬賞，故未及上。既有是命，局官以謂若朝廷許立限了畢，不過三兩月可以投進。而黼務悉矯蔡京所為，故一切罷之，官吏既散，文書皆為棄物矣。建炎三年，外舅張淵道為太常博士，時禮寺典籍散佚亡幾，而京師未陷，公為宰相言：「宜遣官往訪故府，取見存圖籍，悉輦而來，以備掌故。」此若緩而甚急者也。宰相不能用，其後逆豫竊據，鞠為煨燼。吁，可惜哉！","sortOrder":33},
  {"id":"s_work_dtbt_15_34","chapterId":"ch_work_dtbt_15","text":"孫臏減竈","sortOrder":34},
  {"id":"s_work_dtbt_15_35","chapterId":"ch_work_dtbt_15","text":"孫臏勝龐涓之事，兵家以為奇謀，予獨有疑焉，雲：「齊軍入魏地為十萬竈，明日為五萬竈，又明日為二萬竈。」方師行逐利，每夕而興此役，不知以幾何人給之，又必人人各一竈乎？龐涓行三日而大喜曰：「齊士卒亡者過半。」則是所過之處必使人枚數之矣，是豈救急赴敵之師乎？又雲：「度其暮當至馬陵，乃斫大樹，白而書之，曰：『龐涓死於此樹之下。』遂伏萬弩，期日暮見火舉而俱發。涓果夜至斫木下，見白書，鑽火燭之。讀未畢，萬弩俱發。」夫軍行遲速，既非他人所料，安能必其以暮至，不差晷刻乎？古人坐於車中，既雲暮矣，安知樹間之有白書？且必舉火讀之乎？齊弩尚能俱發，而涓讀八字未畢。皆深不可信。殆好事者為之，而不精考耳。","sortOrder":35},
  {"id":"s_work_dtbt_15_36","chapterId":"ch_work_dtbt_15","text":"蟲鳥之智","sortOrder":36},
  {"id":"s_work_dtbt_15_37","chapterId":"ch_work_dtbt_15","text":"竹鷄之性，遇其儔必鬥。捕之者掃落葉為城，置媒其中，而隱身於後操罔焉。激媒使之鳴，聞者，隨聲必至，閉目飛入城，直前欲鬥，而罔已起，無得脫者，蓋目既閉則不復見人。鷓鴣性好潔，獵人於茂林間淨掃地，稍散穀於上，禽往來行遊，且步且啄，則以（米離）竿取之。麂行草莽中，畏人見其跡，但循一徑，無問遠近也。村民結繩為繯，置其所行處，麂足一絓，則倒懸於枝上，乃生獲之。江南多土蜂，人不能識其穴，往往以長紙帶黏於肉，蜂見之必銜入穴，乃躡尋得之，熏取其子。蟲鳥之智，自謂周身矣，如人之不仁何？","sortOrder":37},
  {"id":"s_work_dtbt_15_38","chapterId":"ch_work_dtbt_15","text":"容齋隨筆","sortOrder":38},
  {"id":"s_work_dtbt_16_1","chapterId":"ch_work_dtbt_16","text":"卷第十四(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_16_2","chapterId":"ch_work_dtbt_16","text":"張文潛論詩","sortOrder":2},
  {"id":"s_work_dtbt_16_3","chapterId":"ch_work_dtbt_16","text":"前輩議論，有出於率然不致思而於理近礙者，張文潛雲：「詩三百篇，雖雲婦人女子小夫賤隸所為，要之非深於文章者不能作，如『七月在野』至『入我牀下』，於七月已下，皆不道破，直至十月方言蟋蟀，非深於文章者能為之邪？」予謂三百篇固有所謂女婦小賤所為，若周公、召康公穆公、衞武公、芮伯、凡伯、尹吉甫、仍叔、家父、蘇公、宋襄公、秦康公、史克、公子奚斯，姓氏明見於大序，可一概論之乎？且七月在野，八月在宇，九月在戶，本自言農民出入之時耳，鄭康成始幷入下句，皆指為蟋蟀，正已不然，今直稱此五句為深於文章者，豈其餘不能過此乎？以是論詩，隘矣。","sortOrder":3},
  {"id":"s_work_dtbt_16_4","chapterId":"ch_work_dtbt_16","text":"漢祖三詐","sortOrder":4},
  {"id":"s_work_dtbt_16_5","chapterId":"ch_work_dtbt_16","text":"漢高祖用韓信為大將，而三以詐臨之：信既定趙，高祖自成皋度河，晨自稱漢使馳入信壁，信未起，即其臥，奪其印符，麾召諸將易置之；項羽死，則又襲奪其軍；卒之偽遊雲夢而縛信。夫以豁達大度開基之主，所行乃如是，信之終於謀逆，蓋有以啟之矣。","sortOrder":5},
  {"id":"s_work_dtbt_16_6","chapterId":"ch_work_dtbt_16","text":"有心避禍","sortOrder":6},
  {"id":"s_work_dtbt_16_7","chapterId":"ch_work_dtbt_16","text":"有心於避禍，不若無心於任運，然有不可一概論者。董卓盜執國柄，築塢於郿，積穀為三十年儲，自雲：「事不成，守此足以畢老。」殊不知一敗則掃地，豈容老於塢耶？公孫瓚據幽州，築京於易地，以鐵為門，樓櫓千重，積穀三百萬斛，以為足以待天下之變，殊不知梯衝舞於樓上，城豈可保耶？曹爽為司馬懿所奏，桓範勸使舉兵，爽不從，曰：「我不失作富家翁。」不知誅滅在旦暮耳，富可復得耶？張華相晉，當賈後之難不能退，少子以中台星坼，勸其遜位，華不從，曰：「天道玄遠，不如靜以待之。」竟為趙王倫所害。方事勢不容髮，而欲以靜待，又可嗤也。他人無足言，華博物有識，亦闇於幾事如此哉！","sortOrder":7},
  {"id":"s_work_dtbt_16_8","chapterId":"ch_work_dtbt_16","text":"蹇解之險","sortOrder":8},
  {"id":"s_work_dtbt_16_9","chapterId":"ch_work_dtbt_16","text":"蹇卦艮下坎上，見險而止，故諸爻皆有蹇難之辭。獨六二重言蹇蹇，說者以為六二與九五為正應，如臣之事君，當以身任國家之責，雖蹇之又蹇，亦匪躬以濟之，此解釋文義之旨也。若尋繹爻畫，則有說焉，蓋外卦一坎，諸爻所同，而自六二推之，上承九三、六四，又為坎體，是一卦之中已有二坎也，故重言之。解卦坎下震上，動而免乎險矣。六三將出險，乃有負乘致寇之咎，豈非上承九四、六五又為坎乎？坎為輿為盜，既獲出險而復蹈焉，宜其可醜而致戎也，是皆中爻之義雲。","sortOrder":9},
  {"id":"s_work_dtbt_16_10","chapterId":"ch_work_dtbt_16","text":"士之處世","sortOrder":10},
  {"id":"s_work_dtbt_16_11","chapterId":"ch_work_dtbt_16","text":"士之處世，視富貴利祿，當如優伶之為參軍，方其據幾正坐，噫嗚訶箠，羣優拱而聽命，戲罷則亦已矣。見紛華盛麗，當如老人之撫節物，以上元、清明言之，方少年壯盛，晝夜出遊，若恐不暇，燈收花暮，輒悵然移日不能忘，老人則不然，未嘗置欣戚於胸中也。覩金珠珍玩，當如小兒之弄戲劇，方雜然前陳，疑若可悅，即委之以去，了無戀想。遭橫逆機穽，當如醉人之受罵辱，耳無所聞，目無所見，酒醒之後，所以為我者自若也，何所加損哉？","sortOrder":11},
  {"id":"s_work_dtbt_16_12","chapterId":"ch_work_dtbt_16","text":"張全義治洛","sortOrder":12},
  {"id":"s_work_dtbt_16_13","chapterId":"ch_work_dtbt_16","text":"唐洛陽經黃巢之亂，城無居人，縣邑荒圮，僅能築三小城，又遭李罕之爭奪，但遺餘堵而已。張全義招懷理葺，復為壯藩，五代史於全義傳書之甚略，資治通鑑雖稍詳，亦不能盡。輒采張文定公所著搢紳舊聞記，芟取其要而載於此，曰：「今荊襄淮沔創痍之餘，綿地數千里，長民之官，用守邊保障之勞，超階擢職，不知幾何人？其真能髣髴全義所為者，吾未見其人也，豈局於文法譏議，有所製而不得騁乎？全義始至洛，於麾下百人中，選可使者十八人，命之曰屯將，人給一旗一牓。於舊十八縣中，令招農戶自耕種，流民漸歸。又選可使者十八人，命之曰屯副，民之來者綏撫之，除殺人者死，餘但加杖，無重刑，無租稅，歸者漸衆。又選諳書計者十八人，命之曰屯判官，不一二年，每屯戶至數千。於農隙時，選丁夫，教以弓矢槍劍，為坐作進退之法。行之一二年，得丁夫二萬餘人，有盜賊即時擒捕。關市之賦，迨於無籍，刑寬事簡，遠近趨之如市，五年之內，號為富庶，於是奏每縣除令簿主之。喜民力耕織者，知某家蠶麥善，必至其家，悉召老幼親慰勞之，賜以酒食茶果，遺之布衫裙袴，喜動顏色。見稼田中無草者，必下馬觀之，召田主賜衣服，若禾下有草，耕地不熟，則集衆決責之。或訴以闕牛，則召責其鄰伍曰：『此少牛，如何不衆助？』自是民以耕桑為務，家家有蓄積，水旱無饑人，在任四十餘年，至今廟食。」嗚呼！今之君子，其亦肯以全義之心施諸人乎？","sortOrder":13},
  {"id":"s_work_dtbt_16_14","chapterId":"ch_work_dtbt_16","text":"博古圖","sortOrder":14},
  {"id":"s_work_dtbt_16_15","chapterId":"ch_work_dtbt_16","text":"政和、宣和間，朝廷置書局以數十計，其荒陋而可笑者莫若博古圖。予比得漢匜，因取一冊讀之，發書捧腹之餘，聊識數事於此。父癸匜之銘曰「爵方父癸」。則為之說曰：「周之君臣，其有癸號者，惟齊之四世有癸公，癸公之子曰哀公，然則作是器也，其在哀公之時歟？故銘曰『父癸』者此也。」夫以十幹為號，及稱父甲、父丁、父癸之類，夏、商皆然，編圖者固知之矣，獨於此器表為周物，且以為癸公之子稱其父，其可笑一也。周義母匜之銘曰「仲姞義母作」。則為之說曰：「晉文公杜祁讓偪姞而己次之，趙孟雲『母義子貴』，正謂杜祁，則所謂仲姞者自名也，義母者襄公謂杜祁也。」夫周世姞姓女多矣，安知此為偪姞，杜祁但讓之在上，豈可便為母哉？既言仲姞自名，又以為襄公為杜祁所作，然則為誰之物哉？其可笑二也。漢註水匜之銘曰「始建國元年正月癸酉朔日製」。則為之說曰：「漢初始元年十二月改為建國，此言元年正月者，當是明年也。」按漢書王莽以初始元年十二月癸酉朔日，竊即真位，遂以其日為始建國元年正月，安有明年却稱元年之理？其可笑三也。楚姬盤之銘曰「齊侯作楚姬寶盤」。則為之說曰：「楚與齊從親，在齊湣王之時，所謂齊侯，則湣王也。周末諸侯自王，而稱侯以銘器，尚知止乎禮義也。」夫齊、楚之為國，各數百年，豈必當湣王時從親乎？且湣王在齊諸王中最為驕暴，嘗稱東帝，豈有肯自稱侯之理？其可笑四也。漢梁山鋗之銘曰「梁山銅造」。則為之說曰：「梁山銅者，紀其所貢之地，梁孝王依山鼓鑄，為國之富，則銅有自來矣。」夫即山鑄錢，乃吳王濞耳，梁山自是山名，屬馮翊夏陽縣，於梁國何預焉？其可笑五也。觀此數說，他可知矣。","sortOrder":15},
  {"id":"s_work_dtbt_16_16","chapterId":"ch_work_dtbt_16","text":"士大夫論利害","sortOrder":16},
  {"id":"s_work_dtbt_16_17","chapterId":"ch_work_dtbt_16","text":"士大夫論利害，固當先陳其所以利之實，然於利之中而有小害存焉，亦當科別其故，使人主擇而處之，乃合毋隱勿欺之義。趙充國征先零，欲罷騎兵而屯田，宣帝恐虜聞兵罷，且攻擾田者。充國曰：「虜小寇盜，時殺人民，其原未可卒禁。誠令兵出而虜絕不為寇，則出兵可也。即今同是，而釋坐勝之道，非所以視蠻夷也。」班勇乞復置西域校尉，議者難曰：「班將能保北虜不為邊害乎？」勇曰：「今置州牧以禁盜賊，若州牧能保盜賊不起者，臣亦願以要斬保匈奴之不為邊害也。今通西域，則虜勢必弱，為患微矣。若勢歸北虜，則中國之費不止十億。置之誠便。」此二人論事，可謂極盡利害之要，足以為法也。","sortOrder":17},
  {"id":"s_work_dtbt_16_18","chapterId":"ch_work_dtbt_16","text":"舒元輿文","sortOrder":18},
  {"id":"s_work_dtbt_16_19","chapterId":"ch_work_dtbt_16","text":"舒元輿，唐中葉文士也，今其遺文所存者才二十四篇。既以甘露之禍死，文宗因觀牡丹，摘其賦中桀句曰：「向者如迓，背者如訣。拆者如語，含者如咽。俯者如怨，仰者如悅。」為之泣下。予最愛其玉筯篆志論李斯、李陽冰之書，其詞曰：「斯去千年，冰生唐時，冰復去矣，後來者誰！後千年有人，誰能待之？後千年無人，篆止於斯！嗚呼主人，為吾寶之！」此銘有不可名言之妙，而世或鮮知之。","sortOrder":19},
  {"id":"s_work_dtbt_16_20","chapterId":"ch_work_dtbt_16","text":"絕唱不可和","sortOrder":20},
  {"id":"s_work_dtbt_16_21","chapterId":"ch_work_dtbt_16","text":"韋應物在滁州，以酒寄全椒山中道士，作詩曰：「今朝郡齋冷，忽念山中客。澗底束荊薪，歸來煑白石。欲持一樽酒，遠慰風雨夕。落葉滿空山，何處尋行跡？」其為高妙超詣，固不容夸說，而結尾兩句，非復語言思索可到。東坡在惠州，依其韻作詩寄羅浮鄧道士曰：「一杯羅浮春，遠餉采薇客。遙知獨酌罷，醉臥松下石。幽人不可見，清嘯聞月夕。聊戲菴中人，空飛本無跡。」劉夢得「山圍故國周遭在，潮打空城寂寞回」之句，白樂天以為後之詩人，無復措詞。坡公仿之曰：「山圍故國城空在，潮打西陵意未平。」坡公天才，出語驚世，如追和陶詩，真與之齊驅，獨此二者，比之韋、劉為不侔，豈非絕唱寡和，理自應爾邪。","sortOrder":21},
  {"id":"s_work_dtbt_16_22","chapterId":"ch_work_dtbt_16","text":"贈典輕重","sortOrder":22},
  {"id":"s_work_dtbt_16_23","chapterId":"ch_work_dtbt_16","text":"國朝未改官製以前，從官丞、郎、直學士以降，身沒大抵無贈典，唯尚書、學士有之，然亦甚薄，餘襄公、王素自工書得刑書，蔡君謨自端明、禮侍得吏侍耳。元豐以後，待製以上皆有四官之恩，後遂以為常典，而致仕又遷一秩。梁揚祖終寶文學士、宣奉大夫，既以致仕轉光祿，遂贈特進、龍圖學士，蓋以為銀青、金紫、特進只三官，故增其職，是從左丞得僕射也。節度使舊製贈侍中或太尉，官製行，多贈開府。秦檜創立檢校少保之例，以贈王德、葉夢得、張澄，近歲王彥遂用之，實無所益也。元祐中，王巖叟終於朝奉郎、端明殿學士，以嘗簽書樞密院，故超贈正議大夫。楊願終於朝奉郎、資政殿學士，但贈朝請大夫，以執政而贈郎秩，輕重為不侔，皆掌故之失也。","sortOrder":23},
  {"id":"s_work_dtbt_16_24","chapterId":"ch_work_dtbt_16","text":"揚之水","sortOrder":24},
  {"id":"s_work_dtbt_16_25","chapterId":"ch_work_dtbt_16","text":"左傳所載列國人語言書訊，其辭旨如出一手。說者遂以為皆左氏所作，予疑其不必然，乃若潤色整齊，則有之矣，試以詩證之：揚之水三篇，一周詩，一鄭詩，一晉詩，其二篇皆曰「不流束薪」，「不流束楚」。邶之穀風曰「習習穀風，以陰以雨」，雅之穀風曰「習習穀風，維風及雨」。「在南山之陽」，「在南山之下」，「在南山之側」；「在浚之郊」，「在浚之都」，「在浚之城」；「在河之滸」，「在河之漘」，「在河之涘」；「山有樞，隰有榆」，「山有苞櫟，隰有六駮」，「山有蕨薇，隰有（木巳）桋」；「言秣其馬」，「言采其虻」，「言觀其旂」，「言韔其弓」。皆雜出於諸詩，而興致一也。蓋先王之澤未遠，天下書同文，師無異道，人無異習，出口成言，皆止乎禮義，是以不謀而同爾。","sortOrder":25},
  {"id":"s_work_dtbt_16_26","chapterId":"ch_work_dtbt_16","text":"李陵詩","sortOrder":26},
  {"id":"s_work_dtbt_16_27","chapterId":"ch_work_dtbt_16","text":"文選編李陵、蘇武詩，凡七篇，人多疑「俯觀江、漢流」之語，以為蘇武在長安所作，何為乃及江、漢？東坡雲「皆後人所擬也」。予觀李詩雲「獨有盈觴酒，與子結綢繆」。盈字正惠帝諱，漢法觸諱者有罪，不應陵敢用之，益知坡公之言為可信也。","sortOrder":27},
  {"id":"s_work_dtbt_16_28","chapterId":"ch_work_dtbt_16","text":"大曲伊涼","sortOrder":28},
  {"id":"s_work_dtbt_16_29","chapterId":"ch_work_dtbt_16","text":"今樂府所傳大曲，皆出於唐，而以州名者五，伊、涼、熙、石、渭也。涼州今轉為梁州，唐人已多誤用，其實從西涼府來也。凡此諸曲，唯伊、涼最著，唐詩詞稱之極多，聊紀十數聯，以資談助。如：「老去將何散旅愁？新教小玉唱伊州」，「求守管絃聲款逐，側商調裏唱伊州」，「鈿蟬金雁皆零落，一曲伊州淚萬行」，「公子邀歡月滿樓，雙成揭調唱伊州」，「賺殺唱歌樓上女，伊州誤作石州聲」，「胡部笙歌西部頭，梨園弟子和涼州」，「唱得涼州意外聲，舊人空數米嘉榮」，「霓裳奏罷唱梁州，紅袖斜翻翠黛愁」，「行人夜上西城宿，聽唱涼州雙管逐」，「丞相新裁別離曲，聲聲飛出舊梁州」，「只愁拍盡涼州杖，畫出風雷是撥聲」，「一曲涼州今不清，邊風蕭颯動江城」，「滿眼由來是舊人，那堪更奏梁州曲」，「昨夜蕃軍報國仇，沙州都護破梁州」，「邊將皆承主恩澤，無人解道取涼州」。皆王建、張祜、劉禹錫、王昌齡、高駢、溫庭筠、張籍諸人詩也。","sortOrder":29},
  {"id":"s_work_dtbt_16_30","chapterId":"ch_work_dtbt_16","text":"元次山元子","sortOrder":30},
  {"id":"s_work_dtbt_16_31","chapterId":"ch_work_dtbt_16","text":"元次山有文編十卷，李商隱作序，今九江所刻是也。又有元子十卷，李紓作序，予家有之，凡一百五篇，其十四篇已見於文編，餘者大抵澶漫矯亢。而第八卷中所載（上宀下昏）方國二十國事，最為譎誕，其略雲：「方國之（亻嘼），盡身皆方，其俗惡圓。設有問者，曰『汝心圓』，則兩手破胸露心，曰『此心圓耶？』圓國則反之。言國之（亻嘼），三口三舌。相乳國之（亻嘼），口以下直為一竅。無手國足便於手。無足國膚行如風。」其說頗近山海經，固已不韙，至雲：「惡國之（亻嘼），男長大則殺父，女長大則殺母。忍國之（亻嘼），父母見子，如臣見君。無鼻之國，兄弟相逢則相害。觸國之（亻嘼），子孫長大則殺之。」如此之類，皆悖理害教，於事無補。次山中興頌與日月爭光，若此書，不作可也，惜哉！","sortOrder":31},
  {"id":"s_work_dtbt_16_32","chapterId":"ch_work_dtbt_16","text":"次山謝表","sortOrder":32},
  {"id":"s_work_dtbt_16_33","chapterId":"ch_work_dtbt_16","text":"元次山為道州刺史，作舂陵行，其序雲：「州舊四萬餘戶，經賊以來，不滿四千，大半不勝賦稅。到官未五十日，承諸使徵求符牒二百餘封，皆曰『失期限者罪至貶削』。於戲！若悉應其命，則州縣破亂，刺史欲焉逃罪？若不應命，又即獲罪戾。吾將靜以安人，待罪而已。」其辭甚苦，大略雲：「州小經亂亡，遺人實困疲。朝餐是草根，暮食乃木皮。出言氣欲絕，意速行步遲。追呼尚不忍，况乃鞭扑之。郵亭傳急符，來往跡相追。更無寬大恩，但有迫催期。欲令鬻兒女，言發恐亂隨。奈何重驅逐，不使存活為？安人天子命，符節我所持。逋緩違詔令，蒙責固所宜。」又賊退示官吏一篇，言賊攻永破邵，不犯此州，蓋蒙其傷憐而已，諸使何為忍苦征斂。其詩雲：「城小賊不屠，人貧傷可憐。是以陷鄰境，此州獨見全。使臣將王命，豈不如賊焉？今彼征斂者，迫之如火煎。」二詩憂民慘切如此。故杜老以為：「今盜賊未息，知民疾苦，得結輩十數公，落落參錯天下為邦伯，天下少安，立可待矣。」遂有「兩章對秋月，一字偕華星」之句。今次山集中，載其謝上表兩通，其一雲：「今日刺史，若無武略，以製暴亂；若無文才，以救疲弊；若不清廉，以身率下；若不變通，以救時須，則亂將作矣。臣料今日州縣堪征稅者無幾，已破敗者實多，百姓戀墳墓者蓋少，思流亡者乃衆，則刺史宜精選謹擇以委任之，固不可拘限官次，得之貨賄出之權門者也。」其二雲：「今四方兵革未寧，賦斂未息，百姓流亡轉甚，官吏侵刻日多，實不合使凶庸貪猥之徒，凡弱下愚之類，以貨賂權勢，而為州縣長官。」觀次山表語，但因謝上而能極論民窮吏惡，勸天子以精擇長吏，有謝表以來，未之見也。世人以杜老褒激之故，或稍誦其詩，以中興頌故誦其文，不聞有稱其表者，予是以備錄之，以風後之君子。次山臨道州，歲在癸卯，唐代宗初元廣德也。","sortOrder":33},
  {"id":"s_work_dtbt_16_34","chapterId":"ch_work_dtbt_16","text":"光武仁君","sortOrder":34},
  {"id":"s_work_dtbt_16_35","chapterId":"ch_work_dtbt_16","text":"漢光武雖以征伐定天下，而其心未嘗不以仁恩招懷為本。隗囂受官爵而復叛，賜詔告之曰：「若束手自詣，保無他也。」公孫述據蜀，大軍征之垂滅矣，猶下詔諭之曰：「勿以來歙、岑彭受害自疑，今以時自詣，則家族全，詔書手記不可數得，朕不食言。」遣馮異西征，戒以平定安集為急。怒吳漢殺降，責以失斬將弔民之義，可謂仁君矣。蕭銑舉荊楚降唐，而高祖怒其逐鹿之對，誅之於市，其隘如此，新史猶以高祖為聖，豈理也哉？","sortOrder":35},
  {"id":"s_work_dtbt_16_36","chapterId":"ch_work_dtbt_16","text":"容齋隨筆","sortOrder":36},
  {"id":"s_work_dtbt_17_1","chapterId":"ch_work_dtbt_17","text":"卷第十五(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_17_2","chapterId":"ch_work_dtbt_17","text":"張文潛哦蘇杜詩","sortOrder":2},
  {"id":"s_work_dtbt_17_3","chapterId":"ch_work_dtbt_17","text":"「溪迴松風長，蒼鼠竄古瓦。不知何王殿，遺締絕壁下。陰房鬼火青，壞道哀湍瀉。萬籟真笙竽，秋色正蕭灑。美人為黃土，况乃粉黛假。當時侍金輿，故物獨石馬。憂來藉草坐，浩歌淚盈把。冉冉征途間，誰是長年者？」此老杜玉華宮詩也。張文潛暮年在宛丘，何大圭方弱冠，往謁之，凡三日，見其吟哦此詩不絕口，大圭請其故。曰：「此章乃風、雅鼓吹，未易為子言。」大圭曰：「先生所賦，何必減此？」曰：「平生極力模寫，僅有一篇稍似之，然未可同日語。」遂誦其離黃州詩，偶同此韻，曰：「扁舟發孤城，揮手謝送者。山回地勢卷，天豁江面瀉。中流望赤壁，石腳插水下。昏昏煙霧嶺，歷歷漁樵舍。居夷實三載，鄰里通借假。別之豈無情，老淚為一洒。篙工起鳴鼓，輕櫓健於馬。聊為過江宿，寂寂樊山夜。」此其音響節奏，固似之矣，讀之可默喻也。又好誦東坡梨花絕句，所謂「梨花淡白柳深青，柳絮飛時花滿城，惆悵東欄一株雪，人生看得幾清明」者，每吟一過，必擊節賞嘆不能已，文潛蓋有省於此雲。","sortOrder":3},
  {"id":"s_work_dtbt_17_4","chapterId":"ch_work_dtbt_17","text":"任安田仁","sortOrder":4},
  {"id":"s_work_dtbt_17_5","chapterId":"ch_work_dtbt_17","text":"任安、田仁，皆漢武帝時能臣也，而漢史載其事甚略，褚先生曰：「兩人俱為衞將軍舍人，家監使養惡齧馬。仁曰：『不知人哉家監也！』安曰：『將軍尚不知人，何乃家監也！』後有詔募擇衞將軍舍人以為郎。會賢大夫趙禹來，悉召舍人百餘人，以次問之，得田仁、任安，曰：『獨此兩人可耳，餘無可用者。』將軍上籍以聞。詔召此二人，帝遂用之。仁刺舉三河，時河南、河內太守皆杜周子弟，河東太守石丞相子孫，仁已刺三河，皆下吏誅死。」觀此事，可見武帝求才不遺微賤，得人之盛，誠非後世所及。然班史言：「霍去病既貴，衞青故人門下多去事之，唯任安不肯去。」又言：「衞將軍進言仁為郎中。」與褚先生所書為不同。杜周傳雲：「兩子夾河為郡守，治皆酷暴。」亦不書其所終，皆闕文也。","sortOrder":5},
  {"id":"s_work_dtbt_17_6","chapterId":"ch_work_dtbt_17","text":"杜延年杜欽","sortOrder":6},
  {"id":"s_work_dtbt_17_7","chapterId":"ch_work_dtbt_17","text":"前漢書稱：杜延年本大將軍霍光吏，光持刑罰嚴，延年輔之以寬，論議持平，合和朝廷；杜欽在王鳳幕府，救解馮野王、王尊之罪過，當世善政，多出於欽。予謂光以侯史吳之事，一朝殺九卿三人，延年不能諫。王章言王鳳之過，天子感寤，欲退鳳，欽令鳳上疏謝罪。上不忍廢鳳，鳳欲遂退，欽說之而止。章死，衆庶冤之，欽復說鳳，以為：「天下不知章實有罪，而以為坐言事，宜因章事舉直言極諫，使天下鹹知主上聖明，不以言罪下。若此，則流言消釋矣。」鳳白行其策。夫新莽盜國，權輿於鳳，鳳且退而復止，皆欽之謀。若欽者，蓋漢之賊也，而謂當世善政出其手，豈不繆哉？","sortOrder":7},
  {"id":"s_work_dtbt_17_8","chapterId":"ch_work_dtbt_17","text":"范曄作史","sortOrder":8},
  {"id":"s_work_dtbt_17_9","chapterId":"ch_work_dtbt_17","text":"范曄在獄中，與諸甥侄書曰：「吾既造後漢，詳觀古今著述及評論，殆少可意者。班氏最有高名，既任情無例，不可甲乙，唯志可推耳。博贍可不及之，整理未必愧也。吾雜傳論，皆有精意深旨。至於循吏以下及六夷諸序論，筆勢縱放，實天下之奇作。其中合者，往往不減過秦篇。嘗共比方班氏所作，非但不愧之而已。贊自是吾文之傑思，殆無一字空設，奇變不窮，同合異體，乃自不知所以稱之。此書行，故應有賞音者。自古體大而思精，未有此也。」曄之高自夸詡如此。至以謂過班固，固豈可過哉？曄所著序論，了無可取，列傳如鄧禹、竇融、馬援、班超、郭泰諸篇者，蓋亦有數也，人苦不自知，可發千載一笑。","sortOrder":9},
  {"id":"s_work_dtbt_17_10","chapterId":"ch_work_dtbt_17","text":"唐詩人有名不顯者","sortOrder":10},
  {"id":"s_work_dtbt_17_11","chapterId":"ch_work_dtbt_17","text":"溫公詩話雲：「唐之中葉，文章特盛，其姓名湮沒不傳於世者甚衆，如：河中府鶴雀樓有王之奐、暢諸二詩。二人皆當時所不數，而後人擅詩名者，豈能及之哉！」予觀少陵集中所載韋迢、郭受詩，少陵酬答，至有「新詩錦不如」，「自得隨珠覺夜明」之語，則二人詩名可知矣，然非編之杜集，幾於無傳焉。又有嚴惲惜花一絕雲：「春光冉冉歸何處，更向花前把一杯。盡日問花花不語，為誰零落為誰開？」前人多不知誰作，乃見於皮、陸唱和集中。大率唐人多工詩，雖小說戲劇，鬼物假託，莫不宛轉有思致，不必顓門名家而後可稱也。(奐、暢諸，館本作渙、暢當。)","sortOrder":11},
  {"id":"s_work_dtbt_17_12","chapterId":"ch_work_dtbt_17","text":"蘇子由詩","sortOrder":12},
  {"id":"s_work_dtbt_17_13","chapterId":"ch_work_dtbt_17","text":"蘇子由南窗詩雲：「京城三日雪，雪盡泥方深。閉門謝還往，不聞車馬音。西齋書帙亂，南窗朝日升。展轉守牀榻，欲起復不能。開戶失瓊玉，滿階松竹陰。故人遠方來，疑我何苦心。疏拙自當爾，有酒聊共斟。」此其少年時所作也。東坡好書之，以為人間當有數百本，蓋閑淡簡遠得味外之味雲。","sortOrder":13},
  {"id":"s_work_dtbt_17_14","chapterId":"ch_work_dtbt_17","text":"呼君為爾汝","sortOrder":14},
  {"id":"s_work_dtbt_17_15","chapterId":"ch_work_dtbt_17","text":"東坡雲：「凡人相與號呼者，貴之則曰公，賢之則曰君，自其下則爾汝之。雖王公之貴，天下貌畏而心不服，則進而君公，退而爾汝者多矣。」予謂此論特後世之俗如是爾，古之人心口一致，事從其真，雖君臣父子之間，出口而言，不復顧忌，觀詩、書所載可知矣。箕子陳洪範，對武王而汝之。金縢策祝，周公所以告大王、王季、文王三世祖考也，而呼之曰爾三王，自稱曰予。至雲：「爾之許我，我其以璧與珪，歸俟爾命，爾不許我，我乃屏璧與珪。」殆近乎相質責而邀索也。天保報上之詩，曰「天保定爾，俾爾戩穀」，閟宮頌君之詩，曰「俾爾熾而昌」，「俾爾昌而熾」，及節南山、正月、板蕩、卷阿、既醉、瞻卬諸詩，皆呼王為爾。大明曰「上帝臨女」，指武王也。民勞曰「王欲玉女」，指厲王也。至或稱為小子，雖幽、厲之君，亦受之而不怒。嗚呼！三代之風俗，可復見乎？晉武公請命乎天子，其大夫賦無衣，所謂「不如子之衣」，亦指周王也。","sortOrder":15},
  {"id":"s_work_dtbt_17_16","chapterId":"ch_work_dtbt_17","text":"世事不可料","sortOrder":16},
  {"id":"s_work_dtbt_17_17","chapterId":"ch_work_dtbt_17","text":"秦始皇幷六國，一天下，東遊會稽，度浙江，撊然謂子孫帝王萬世之固，不知項籍已縱觀其旁，劉季起喟然之嘆於鹹陽矣。曹操芟夷羣雄，遂定海內，身為漢相，日夜窺伺龜鼎，不知司馬懿已入幕府矣。梁武帝殺東昏侯，覆齊祚，而侯景以是年生於漠北。唐太宗殺建成、元吉，遂登天位，而武後已生於幷州。宣宗之世，無故而復河、隴，戎狄既衰，藩鎮順命，而朱溫生矣。是豈智力謀慮所可為哉？","sortOrder":17},
  {"id":"s_work_dtbt_17_18","chapterId":"ch_work_dtbt_17","text":"蔡君謨帖語","sortOrder":18},
  {"id":"s_work_dtbt_17_19","chapterId":"ch_work_dtbt_17","text":"韓獻肅公守成都時，蔡君謨與之書曰：「襄啟：歲行甫新，魯鈍之資，日益衰老。雖勉就職務，其於精力不堪勞苦。念君之生，相距旬日，如聞年來補治有方，當愈強健，果如何哉？襄於京居，尚留少時，佇君還軫，伸眉一笑，傾懷之極。今因樊都官西行，奉書問動靜，不一一。襄上子華端明閣下。」此帖語簡而情厚，初無寒溫之問，寢食之祝，講德之佞也。今風俗日以媮薄，士大夫之獧浮者，於尺牘之間，益出新巧，習貫自然，雖有先達篤實之賢，亦不敢自拔以速嘲罵。每詒書多至十數紙，必繫銜，相與之際，悉忘其真，言語不情，誠意掃地。相呼不以字，而雲某丈，僭紊官稱，無復差等，觀此其少愧乎！憶二紀之前，予在館中，見曾監吉甫與人書，獨不作劄子，且以字呼同舍，同舍因相約雲：「曾公前輩可尊，是宜曰丈，餘人自今各以字行，其過誤者罰一直。」行之幾月，從官郎省，欣然皆欲一變，而有欲敗此議者，載酒飲同舍，乞仍舊。於是從約皆解，遂不可復革，可為一嘆。","sortOrder":19},
  {"id":"s_work_dtbt_17_20","chapterId":"ch_work_dtbt_17","text":"孔氏野史","sortOrder":20},
  {"id":"s_work_dtbt_17_21","chapterId":"ch_work_dtbt_17","text":"世傳孔毅甫野史一卷，凡四十事，予得其書於清江劉靖之所，載趙清獻為青城宰，挈散樂妓以歸，為邑尉追還，大慟且怒，又因與妻忿爭，由此惑志。文潞公守太原，辟司馬溫公為通判，夫人生日，溫公獻小詞，為都漕唐子方峻責。歐陽永叔、謝希深、田元均、尹師魯在河南，攜官妓遊龍門，半月不返，留守錢思公作簡招之，亦不答。范文正與京東人石曼卿、劉潛之類相結以取名，服中上萬言書，甚非言不文之義。蘇子瞻被命作儲祥宮記，大貂陳衍幹當宮事，得旨置酒與蘇高會，蘇陰使人發，御史董敦逸即有章疏，遂墮計中。又雲子瞻四六表章不成文字。其他如潞公、范忠宣、呂汲公、吳冲卿、傅獻簡諸公，皆不免譏議。予謂決非毅甫所作，蓋魏泰碧雲騢之流耳。溫公自用龐潁公辟，不與潞公、子方同時，其謬妄不待攻也。靖之乃原甫曾孫，佳士也，而跋是書雲：「孔氏兄弟曾大父行也，思其人欲聞其言久矣，故錄而藏之。」汪聖錫亦書其後，但記上官彥衡一事，豈弗深考雲。","sortOrder":21},
  {"id":"s_work_dtbt_17_22","chapterId":"ch_work_dtbt_17","text":"有若","sortOrder":22},
  {"id":"s_work_dtbt_17_23","chapterId":"ch_work_dtbt_17","text":"史記有若傳雲：「孔子沒，弟子以若狀似孔子，立以為師。他日，進問曰：『昔夫子當行，使弟子持雨具，已而果雨。弟子問何以知之，夫子曰，詩不雲乎？月離於畢，俾滂沱矣。昨暮月不宿畢乎？他日，月宿畢，竟不雨。商瞿年長無子，孔子曰瞿年四十後當有五丈夫子。已而果然。敢問何以知此？』有若無以應。弟子起曰：『有子避之，此非子之座也！』」予謂此兩事殆近於星曆卜祝之學，何足以為聖人，而謂孔子言之乎？有若不能知，何所加損，而弟子遽以是斥退之乎？孟子稱「子夏、子張、子遊，以若似聖人，欲以所事孔子事之，曾子不可」，但言「江、漢秋陽不可尚」而已，未嘗深詆也。論語記諸善言，以有子之言為第二章，在曾子之前；使有避坐之事，弟子肯如是哉？檀弓載有子聞曾子「喪欲速貧，死欲速朽」兩語，以為「非君子之言」，又以為「夫子有為言之」。子遊曰：「甚哉！有子之言似夫子也。」則其為門弟子所敬久矣，太史公之書，於是為失矣。且門人所傳者道也，豈應以狀貌之似而師之邪？世所圖七十二賢畫像，其畫有若遂與孔子略等，此又可笑也。","sortOrder":23},
  {"id":"s_work_dtbt_17_24","chapterId":"ch_work_dtbt_17","text":"張天覺為人","sortOrder":24},
  {"id":"s_work_dtbt_17_25","chapterId":"ch_work_dtbt_17","text":"張天覺為人賢否，士大夫或不詳知。方大觀、政和間，時名甚著，多以忠直許之。蓋其作相適承蔡京之後，京弄國為奸，天下共疾，小變其政，便足以致譽，飢者易為食，故蒙賢者之名，靖康初政，遂與司馬公、范文正同被褒典。予以其實考之，彼直奸人之雄爾。其外孫何麒作家傳雲：「為熙寧御史，則逐於熙寧；為元祐廷臣，則逐於元祐；為紹聖諫官，則逐於紹聖；為崇寧大臣，則逐於崇寧；為大觀宰相，則逐於政和。」其跡是矣，而實不然。為御史時，以斷獄失當，為密院所治，遂摭博州事以報之，三樞密皆乞去，故坐貶。為諫官時，首攻內侍陳衍以搖宣仁，至比之於呂、武；乞追奪司馬公、呂申公贈謚，仆碑毀樓；論文潞公背負國恩，呂汲公動搖先烈；辯呂惠卿、蔡確無罪。後以交通潁昌富民蓋漸故，又貶。元符末，除中書舍人，謝表歷詆元祐諸賢，雲：「當元祐之八九年，擢黨人之二十輩。」及在相位，乃以與郭天信交結而去耳。平生言行如此，而得美譽，則以蔡京不相能之故。然皆章子厚門下客，其始非不同也。京拜相之詞，天覺所作，是以得執政雲。","sortOrder":25},
  {"id":"s_work_dtbt_17_26","chapterId":"ch_work_dtbt_17","text":"為文論事","sortOrder":26},
  {"id":"s_work_dtbt_17_27","chapterId":"ch_work_dtbt_17","text":"為文論事，當反復致志，救首救尾，則事詞章著，覽者可以立決。陳湯斬郅支而功未錄，劉向上疏論之，首言：「周方叔、吉甫誅獫玁。」次言：「齊桓公有滅項之罪，君子以功覆過。李廣利靡億萬之費，捐五萬之師，厪獲宛王之首，孝武不錄其過，封為列侯。」末言：「常惠隨欲擊之烏孫，鄭吉迎自來之日逐，皆裂土受爵。」然後極言：「今康居國強於大宛，郅支之號，重於宛王，殺使者罪甚於留馬，而不煩漢士，不費斗糧，比於貳師，功德百之。」又曰：「言威武勤勞則大於方叔、吉甫，列功覆過則優於齊桓、貳師，近事之功則高於安遠、長羅，而大功未著，小惡數布，臣竊痛之！」於是天子乃下詔議封。蓋其一疏抑揚援證，明白如此，故以丞相匡衡、中書石顯，出力沮害，竟不能奪。不然，衡、顯之議，豈區區一故九卿所能亢哉？","sortOrder":27},
  {"id":"s_work_dtbt_17_28","chapterId":"ch_work_dtbt_17","text":"連昌宮詞","sortOrder":28},
  {"id":"s_work_dtbt_17_29","chapterId":"ch_work_dtbt_17","text":"元微之、白樂天，在唐元和、長慶間齊名。其賦詠天寶時事，連昌宮詞、長恨歌皆膾炙人口，使讀之者情性蕩搖，如身生其時，親見其事，殆未易以優劣論也。然長恨歌不過述明皇追愴貴妃始末，無他激揚，不若連昌詞有監戒規諷之意，如雲：「姚崇、宋璟作相公，勸諫上皇言語切。長官清貧太守好，揀選皆言由相至。開元之末姚、宋死，朝廷漸漸由妃子。祿山宮裏養作兒，虢國門前鬧如市。弄權宰相不記名，依稀憶得楊與李。廟謨顛倒四海搖，五十年來作瘡痏。」其末章及官軍討淮西，乞「廟謨休用兵」之語，蓋元和十一、二年間所作，殊得風人之旨，非長恨比雲。","sortOrder":29},
  {"id":"s_work_dtbt_17_30","chapterId":"ch_work_dtbt_17","text":"二士共談","sortOrder":30},
  {"id":"s_work_dtbt_17_31","chapterId":"ch_work_dtbt_17","text":"維摩詰經言，文殊從佛所將詣維摩丈室問疾，菩薩隨之者以萬億計，曰：「二士共談，必說妙法。」予觀杜少陵寄李太白詩雲：「何時一尊酒，重與細論文。」使二公真踐此言，時得洒掃撰杖屨於其側，所謂不二法門，不傳之妙，啟聰擊蒙，出膚寸之澤以潤千里者，可勝道哉！","sortOrder":31},
  {"id":"s_work_dtbt_17_32","chapterId":"ch_work_dtbt_17","text":"張子韶祭文","sortOrder":32},
  {"id":"s_work_dtbt_17_33","chapterId":"ch_work_dtbt_17","text":"先公自嶺外徙宜春，沒於保昌，道出南安，時猶未聞檜相之死。張子韶先生來致祭，其文但雲：「維某年月日具官某，謹以清酌之奠昭告於某官之靈，嗚呼哀哉，伏惟尚饗！」其情旨哀愴，乃過於詞，前人未有此格也。","sortOrder":33},
  {"id":"s_work_dtbt_17_34","chapterId":"ch_work_dtbt_17","text":"京師老吏","sortOrder":34},
  {"id":"s_work_dtbt_17_35","chapterId":"ch_work_dtbt_17","text":"京師盛時，諸司老吏，類多識事體，習典故。翰苑有孔目吏，每學士製草出，必據案細讀，疑誤輒告。劉嗣明嘗作皇子剃胎髮文，用克長克君之語，吏持以請，嗣明曰：「此言堪為長堪為君，真善頌也。」吏拱手曰：「內中讀文書不如是，最以語忌為嫌，既剋長又剋君，殆不可用也。」嗣明悚然亟易之。靖康歲都城受圍，禦敵器甲刓弊。或言太常寺有舊祭服數十，閒無所用，可以藉甲。少卿劉珏即具藁欲獻於朝，以付書史。史作字楷而敏，平常無錯誤，珏將上馬，立俟之，既至，而結銜脫兩字。趣使更寫，至於三，其誤如初。珏怒責之，逡巡謝曰：「非敢誤也，某小人竊妄有管見，在禮，『祭服敝則焚之』。今國家迫急，誠不宜以常日論，然容臺之職，唯當秉禮。少卿固體國，不若俟朝廷來索則納之，賢於先自背禮而有獻也。」珏愧嘆而止，後每為人言，嘉賞其意。今之胥徒，雖公府右職，省寺掌故，但能鼓扇獧浮，顧賕謝為業，簿書期會之間，乃漫不之曉，求如彼二人，豈可得哉！","sortOrder":35},
  {"id":"s_work_dtbt_17_36","chapterId":"ch_work_dtbt_17","text":"曹操唐莊宗","sortOrder":36},
  {"id":"s_work_dtbt_17_37","chapterId":"ch_work_dtbt_17","text":"曹操在兗州，引兵東擊陶謙於徐，而陳宮潛迎呂布為兗牧，郡縣皆叛，賴程昱、荀彧之力，全東阿、鄄、范三城以待操。操還，執昱手曰：「微子之力，吾無所歸矣。」表為東平相。唐莊宗與梁人相持於河上，梁將王檀乘虛襲晉陽。城中無備，幾陷者數四，賴安金全帥子弟擊却之於內，石君立引昭義兵破之於外，晉陽獲全。而莊宗以策非己出，金全等賞皆不行。操終有天下，莊宗雖能滅梁，旋踵覆亡，考其行事，概可睹矣。","sortOrder":37},
  {"id":"s_work_dtbt_17_38","chapterId":"ch_work_dtbt_17","text":"雲中守魏尚","sortOrder":38},
  {"id":"s_work_dtbt_17_39","chapterId":"ch_work_dtbt_17","text":"史記、漢書所記馮唐救魏尚事，其始雲：「魏尚為雲中守，與匈奴戰，上功幕府，一言不相應，文吏以法繩之，其賞不行。臣以為陛下賞太輕，罰太重。」而又申言之雲：「且雲中守魏尚，坐上功首虜差六級，陛下下之吏，削其爵，罰作之。」重言雲中守及姓名，而文勢益遒健有力，今人無此筆也。","sortOrder":39},
  {"id":"s_work_dtbt_17_40","chapterId":"ch_work_dtbt_17","text":"容齋隨筆","sortOrder":40},
  {"id":"s_work_dtbt_18_1","chapterId":"ch_work_dtbt_18","text":"卷第十六(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_18_2","chapterId":"ch_work_dtbt_18","text":"文章小伎","sortOrder":2},
  {"id":"s_work_dtbt_18_3","chapterId":"ch_work_dtbt_18","text":"「文章一小伎，於道未為尊。」雖杜子美有激而雲，然要為失言，不可以訓。文章豈小事哉！易賁之彖言：「剛柔交錯，天文也；文明以止，人文也。觀乎天文，以察時變；觀乎人文，以化成天下。」孔子稱帝堯煥乎有文章。子貢曰：「夫子之文章，可得而聞。」詩美衞武公，亦雲有文章。堯、舜、禹、湯、文、武、成、康之聖賢，桀、紂、幽、厲之昏亂，非詩書以文章載之，何以傳？伏羲畫八卦，文王重之，非孔子以文章翼之，何以傳？孔子至言要道，託孝經、論語之文而傳。曾子、子思、孟子傳聖人心學，使無中庸及七篇之書，後人何所窺門戶？老、莊絕滅禮學，忘言去為，而五千言與內、外篇極其文藻。釋氏之為禪者，謂語言為累，不知大乘諸經可廢乎？然則詆為小伎，其理謬矣！彼後世為詞章者，逐其末而忘其本，玩其華而落其實，流宕自遠，非文章過也。杜老所雲「文章千古事」，「已似愛文章」，「文章日自負」，「文章實致身」，「文章開宎奧」，「文章憎命達」，「名豈文章著」，「枚乘文章老」，「文章敢自誣」，「海內文章伯」，「文章曹植波瀾闊」，「庾信文章老更成」，「豈有文章驚海內」，「每語見許文章伯」，「文章有神交有道」，如此之類，多指詩而言，所見狹矣！","sortOrder":3},
  {"id":"s_work_dtbt_18_4","chapterId":"ch_work_dtbt_18","text":"三長月","sortOrder":4},
  {"id":"s_work_dtbt_18_5","chapterId":"ch_work_dtbt_18","text":"釋氏以正、五、九月為「三長月」，故奉佛者皆茹素。其說雲：天帝釋以大寶鏡，輪照四天下，寅、午、戌月，正臨南贍部洲，故當食素以徼福。官司謂之「斷月」，故受驛券有所謂羊肉者，則不支。俗謂之「惡月」，士大夫赴官者，輒避之。或人以謂唐日藩鎮蒞事，必大享軍，屠殺羊豕至多，故不欲以其月上事，今之他官，不當爾也。然此說亦無所經見。予讀晉書禮志，穆帝納後，欲用九月，九月是「忌月」。北齊書雲高洋謀魏，其臣宋景業言：「宜以仲夏受禪。」或曰：「五月不可入官，犯之，終於其位。」景業曰：「王為天子，無復下期，豈得不終於其位乎？」乃知此忌相承，由來已久，竟不能曉其義及出何經典也。","sortOrder":5},
  {"id":"s_work_dtbt_18_6","chapterId":"ch_work_dtbt_18","text":"兄弟直西垣","sortOrder":6},
  {"id":"s_work_dtbt_18_7","chapterId":"ch_work_dtbt_18","text":"秦少遊集中，有與鮮於子駿書雲：「今中書舍人皆以伯仲繼直西垣，前世以來未有其事，誠國家之美，非特衣冠之盛也。除書始下，中外欣然，舉酒相屬。」予以其時考之，蓋元祐二年，謂蘇子由、曾子開、劉貢甫也。子由之兄子瞻，子開之兄子固、子宣，貢甫之兄原甫，皆經是職，故少遊有此語雲。紹興二十九年，予仲兄始入西省，至隆興二年，伯兄繼之，乾道三年，予又繼之，相距首尾九歲。予作謝表雲：「父子相承，四上鑾坡之直；弟兄在望，三陪鳳閣之遊。」比之前賢，實為遭際，固為門戶榮事，然亦以此自愧也。","sortOrder":7},
  {"id":"s_work_dtbt_18_8","chapterId":"ch_work_dtbt_18","text":"續樹萱錄","sortOrder":8},
  {"id":"s_work_dtbt_18_9","chapterId":"ch_work_dtbt_18","text":"頃在祕閣抄書，得續樹萱錄一卷，其中載隱君子元撰夜見吳王夫差，與唐諸詩人吟詠事。李翰林詩曰：「芙蓉露濃紅壓枝，幽禽感秋花畔啼，玉人一去未回馬，梁間燕子三見歸。」張司業曰：「綠頭鴨兒咂萍藻，采蓮女郎笑花老。」杜舍人曰：「鼓鼙夜戰北窗風，霜葉沿階貼亂紅。」三人皆全篇。杜工部曰：「紫領寬袍漉酒巾，江頭蕭散作閒人。」白少傅曰：「不因霜葉辭林去，的當山翁未覺秋。」李賀曰：「魚鱗甃空排嫩碧，露桂梢寒掛團璧。」三人皆未終篇。細味其體格語句，往往逼真。後閱秦少遊集，有秋興九首，皆擬唐人，前所載鹹在焉。關子東為秦集序雲「擬古數篇，曲盡唐人之體」，正謂是也。何子楚雲：「續萱錄乃王性之所作，而託名他人。」今其書才有三事，其一曰賈博喻，一曰全若虛，一曰元撰，詳命名之義，蓋取諸子虛、亡是公雲。","sortOrder":9},
  {"id":"s_work_dtbt_18_10","chapterId":"ch_work_dtbt_18","text":"館職名存","sortOrder":10},
  {"id":"s_work_dtbt_18_11","chapterId":"ch_work_dtbt_18","text":"國朝館閣之選，皆天下英俊，然必試而後命。一經此職，遂為名流。其高者，曰集賢殿修撰、史館修撰、直龍圖閣、直昭文館、史館、集賢院、祕閣。次曰集賢、祕閣校理。官卑者，曰館閣校勘、史館檢討，均謂之館職。記註官缺，必於此取之，非經修註，未有直除知製誥者。官至員外郎則任子，中外皆稱為學士。及元豐官製行，凡帶職者，皆遷一官而罷之，而置祕書省官，大抵與職事官等，反為留滯。政和以後，增修撰直閣貼職為九等，於是材能治辦之吏、貴遊乳臭之子，車載斗量，其名益輕。南渡以來，初除校書正字，往往召試，雖曰館職不輕畀，然其遷敍，反不若寺監之徑捷。至推排為郎，即失其故步，混然無別矣。","sortOrder":11},
  {"id":"s_work_dtbt_18_12","chapterId":"ch_work_dtbt_18","text":"南宮適","sortOrder":12},
  {"id":"s_work_dtbt_18_13","chapterId":"ch_work_dtbt_18","text":"南宮適問羿、奡不得其死，禹、稷有天下，言力可賤而德可貴。其義已盡，無所可答，故夫子俟其出而嘆其為君子，奬其尚德，至於再言之，聖人之意斯可見矣。然明道先生雲：「以禹、稷比孔子，故不答。」范淳父以為禹、稷有天下，故夫子不敢答，弗敢當也。楊龜山雲：「禹、稷之有天下，不止於躬稼而已，孔子未盡然其言，故不答。然而不正之者，不責備於其言，以沮其尚德之志也，與所謂『雍之言然』則異矣。」予竊謂南宮之問，初無以禹、稷比孔子之意，不知二先生何為有是言？若龜山之語，淺之已甚！獨謝顯道雲：「南宮適知以躬行為事，是以謂之君子。知言之要，非尚德者不能，在當時發問間，必有目擊而道存，首肯之意，非直不答也。」其說最為切當。","sortOrder":13},
  {"id":"s_work_dtbt_18_14","chapterId":"ch_work_dtbt_18","text":"吳王殿","sortOrder":14},
  {"id":"s_work_dtbt_18_15","chapterId":"ch_work_dtbt_18","text":"漢高祖五年，以長沙、豫章、象郡、桂林、南海立番君吳芮為長沙王。十二年，以三郡封吳王濞，而豫章亦在其中。又趙佗先有南海，後擊幷桂林、象郡。則芮所有，但長沙一郡耳。按芮本為秦番陽令，故曰番君。項羽已封為衡山王，都邾。邾，今之黃州也。復侵奪其地。故高祖徙之長沙而都臨湘，一年薨，則其去番也久矣。今吾邦猶指郡正廳為吳王殿，以謂芮為王時所居。牛僧孺玄怪錄載，唐元和中，饒州刺史齊推女，因止州宅誕育，為神人擊死，後有仙官治其事，雲：「是西漢鄱陽王吳芮。今刺史宅，是芮昔時所居。」皆非也。","sortOrder":15},
  {"id":"s_work_dtbt_18_16","chapterId":"ch_work_dtbt_18","text":"王衛尉","sortOrder":16},
  {"id":"s_work_dtbt_18_17","chapterId":"ch_work_dtbt_18","text":"漢高祖怒蕭何，謂王衞尉曰：「李斯相秦皇帝，有善歸主，有惡自予，今相國請吾苑以自媚於民，故繫治之。」衞尉曰：「秦以不聞其過亡天下，李斯之分過，又何足法哉！」唐太宗疑三品以上輕魏王，責之曰：「我見隋家諸王，一品以下皆不免其躓頓，我自不許兒子縱橫耳。」魏鄭公曰：「隋高祖不知禮義，寵縱諸子，使行非禮，尋皆罪黜，不可以為法，亦何足道。」觀高祖、太宗一時失言，二臣能因其所言隨即規正，語意既直，於激切中有婉順體，可謂得諫爭之大義。雖微二帝，其孰不降心以聽乎！","sortOrder":17},
  {"id":"s_work_dtbt_18_18","chapterId":"ch_work_dtbt_18","text":"前代為監","sortOrder":18},
  {"id":"s_work_dtbt_18_19","chapterId":"ch_work_dtbt_18","text":"人臣引古規戒，當近取前代，則事勢相接，言之者有證，聽之者足以監。詩曰：「殷監不遠，在夏後之世。」周書曰：「今惟殷墜厥命，我其可不大監！」又曰：「我不可不監於有殷。」又曰：「有殷受天命，惟有歷年，惟不敬厥德，乃早墜厥命。」周公作無逸，稱商三宗。漢祖命羣臣言吾所以有天下，項氏所以失天下，命陸賈著秦所以失天下。張釋之為文帝言秦、漢之間事，秦所以失，漢所以興。賈山借秦為喻。賈誼請人主引商、周、秦事而觀之。魏鄭公上書於太宗雲：「方隋之未亂，自謂必無亂；方隋之未亡，自謂必無亡。臣願當今動靜以隋為監。」馬周雲：「煬帝笑齊、魏之失國，今之視煬帝，亦猶煬帝之視齊、魏也。」張玄素諫太宗治洛陽宮曰：「乾陽畢功，隋人解體，恐陛下之過，甚於煬帝。若此役不息，同歸於亂耳！」考詩、書所載及漢、唐諸名臣之論，有國者之龜鏡也，議論之臣，宜以為法。","sortOrder":19},
  {"id":"s_work_dtbt_18_20","chapterId":"ch_work_dtbt_18","text":"治盜法不同","sortOrder":20},
  {"id":"s_work_dtbt_18_21","chapterId":"ch_work_dtbt_18","text":"唐崔安潛為西川節度使，到官不詰盜。曰：「盜非所由通容，則不能為。」乃出庫錢置三市，置榜其上，曰：「告捕一盜，賞錢五百緡。侶者告捕，釋其罪，賞同平人。」未幾，有捕盜而至者。盜不服，曰：「汝與我同為盜十七年，贓皆平分，汝安能捕我？」安潛曰：「汝既知吾有榜，何不捕彼以來？則彼應死，汝受賞矣。汝既為所先，死復何辭？」立命給捕者錢，使盜視之，然後殺盜於市。於是諸盜與其侶互相疑，無地容足，夜不及旦，散逃出境，境內遂無一人為盜。予每讀此事，以為策之上者。及得李公擇治齊州事，則又不然。齊素多盜，公擇痛治之，殊不止。他日得黠盜，察其可用，刺為兵，使直事鈴下。間問以盜發輒得而不衰止之故。曰：「此繇富家為之囊。使盜自相推為甲乙，官吏巡捕及門，擒一人以首，則免矣。」公擇曰：「吾得之矣。」乃令凡得藏盜之家，皆發屋破柱，盜賊遂清。予乃知治世間事，不可泥紙上陳跡。如安潛之法可謂善矣，而齊盜反恃此以為沈命之計，則變而通之，可不存乎其人哉！","sortOrder":21},
  {"id":"s_work_dtbt_18_22","chapterId":"ch_work_dtbt_18","text":"和詩當和意","sortOrder":22},
  {"id":"s_work_dtbt_18_23","chapterId":"ch_work_dtbt_18","text":"古人酬和詩，必答其來意，非若今人為次韻所局也。觀文選所編何劭、張華、盧諶、劉琨、二陸、三謝諸人贈答，可知已。唐人尤多，不可具載。姑取杜集數篇，略紀於此。高適寄杜公雲：「媿爾東西南北人。」杜則雲：「東西南北更堪論。」高又有詩雲：「草玄今已畢，此外更何言？」杜則雲：「草玄吾豈敢，賦或似相如。」嚴武寄杜雲：「興發會能馳駿馬，終須重到使君灘。」杜則雲：「枉沐旌麾出城府，草茅無逕欲教鋤。」杜公寄嚴詩雲：「何路出巴山」，「重巖細菊斑，遙知簇鞍馬，回首白雲間。」嚴答雲：「臥向巴山落月時」，「籬外黃花菊對誰，跂馬望君非一度。」杜送韋迢雲：「洞庭無過雁，書疏莫相忘。」迢雲：「相憶無南雁，何時有報章？」杜又雲：「雖無南去雁，看取北來魚。」郭受寄杜雲：「春興不知凡幾首？」杜答雲：「藥裹關心詩總廢。」皆如鐘磬在簴，叩之則應，往來反復，於是乎有餘味矣。","sortOrder":23},
  {"id":"s_work_dtbt_18_24","chapterId":"ch_work_dtbt_18","text":"稷有天下","sortOrder":24},
  {"id":"s_work_dtbt_18_25","chapterId":"ch_work_dtbt_18","text":"「稷躬稼而有天下」、「泰伯三以天下讓」、「文王一怒而安天下之民」，皆以子孫之事追言之。是時，稷始封於邰，古公方邑於梁山之下，文王才有岐周之地，未得雲天下也。禹未嘗躬稼，因稷而稱之。","sortOrder":25},
  {"id":"s_work_dtbt_18_26","chapterId":"ch_work_dtbt_18","text":"一世人材","sortOrder":26},
  {"id":"s_work_dtbt_18_27","chapterId":"ch_work_dtbt_18","text":"一世人材，自可給一世之用。苟有以致之，無問其取士之門如何也。今之議者，多以科舉經義、詩賦為言，以為詩賦浮華無根柢，不能致實學，故其說常右經而左賦。是不然。成周之時，下及列國，皆官人以世。周之劉、單、召、甘，晉之韓、趙、荀、魏，齊之高、國、陳、鮑，衞之孫、甯、孔、石，宋之華、向、皇、樂，鄭之罕、駟、國、遊，魯之季、孟、臧、展，楚之鬭、蒍、申、屈，皆世不乏賢，與國終畢。漢以經術及察舉，魏、晉以州鄉中正，東晉、宋、齊以門第，唐及本朝以進士，而參之以任子，皆足以盡一時之才。則所謂科目，特借以為梯階耳！經義、詩賦，不問可也。","sortOrder":27},
  {"id":"s_work_dtbt_18_28","chapterId":"ch_work_dtbt_18","text":"王逢原","sortOrder":28},
  {"id":"s_work_dtbt_18_29","chapterId":"ch_work_dtbt_18","text":"王逢原以學術，邢居實以文采，有盛名於嘉祐、元豐間。然所為詩文，多怨抑沈憤，哀傷涕泣，若辛苦憔悴不得其平者，故皆不克壽，逢原年二十八，居實纔二十。天畀其才而嗇其壽，吁，可惜哉！","sortOrder":29},
  {"id":"s_work_dtbt_18_30","chapterId":"ch_work_dtbt_18","text":"吏文可笑","sortOrder":30},
  {"id":"s_work_dtbt_18_31","chapterId":"ch_work_dtbt_18","text":"吏文行移，只用定本，故有絕可笑者。如文官批書印紙，雖宮、觀、嶽、廟，亦必雲不曾請假；或已登科級，見官臺省清要，必雲不曾應舉若試刑法。予在西掖時，漢州申顯惠侯神，頃係宣撫司便宜加封昭應公，乞換給製書。禮、寺看詳，謂不依元降指揮於一年限內自陳，欲符下漢州，告示本神知委。予白丞相別令勘當，乃得改命。淳熙六年，予以大禮恩澤改奏一歲兒，吏部下饒州，必欲保官狀內聲說被奏人曾與不曾犯決笞，有無翦刺，及曾與不曾先經補官因罪犯停廢，別行改奏；又令供與予係是何服屬。父之於子而問何服屬，一歲嬰兒而問曾與不曾入仕坐罪，豈不大可笑哉！","sortOrder":31},
  {"id":"s_work_dtbt_18_32","chapterId":"ch_work_dtbt_18","text":"靖康時事","sortOrder":32},
  {"id":"s_work_dtbt_18_33","chapterId":"ch_work_dtbt_18","text":"鄧艾伐蜀，劉禪既降，又敕薑維使降於鍾會，將士鹹怒，拔刀斫石。魏圍燕於中山既久，城中將士皆思出戰，至數千人，相率請於燕主，慕容隆言之尤力，為慕容麟沮之而罷。契丹伐晉連年，晉拒之，每戰必勝。其後，杜重威陰謀欲降，命將士出陳於外，士皆踴躍，以為出戰，既令解甲，士皆慟哭，聲振原野。予頃修靖康實錄，竊痛一時之禍，以堂堂大邦，中外之兵數十萬，曾不能北向發一矢、獲一胡，端坐都城，束手就斃！虎旅雲屯，不聞有如蜀、燕、晉之憤哭者。近讀朱新仲詩集，有記昔行一篇，正敍此時事。其中雲：「老种憤死不得戰，汝霖疽發何由痊？」乃知忠義之士，世未嘗無之，特時運使然耳。","sortOrder":33},
  {"id":"s_work_dtbt_18_34","chapterId":"ch_work_dtbt_18","text":"幷韶","sortOrder":34},
  {"id":"s_work_dtbt_18_35","chapterId":"ch_work_dtbt_18","text":"梁武帝時，有交趾人幷韶者，富於詞藻，詣選求官，而吏部尚書蔡撙以幷姓無前賢，除廣陽門郎。韶恥之，遂還鄉里謀作亂。夫用門地族望為選舉低昂，乃晉、宋以來弊法，蔡撙賢者也，不能免俗，何哉？","sortOrder":35},
  {"id":"s_work_dtbt_18_36","chapterId":"ch_work_dtbt_18","text":"讖緯之學","sortOrder":36},
  {"id":"s_work_dtbt_18_37","chapterId":"ch_work_dtbt_18","text":"圖讖星緯之學，豈不或中，然要為誤人，聖賢所不道也。眭孟睹公孫病己之文，勸漢昭帝求索賢人，禪以帝位，而不知宣帝實應之，孟以此誅。孔熙先知宋文帝禍起骨肉，江州當出天子，故謀立江州刺史彭城王，而不知孝武實應之，熙先以此誅。當塗高之讖，漢光武以詰公孫述，袁術、王浚皆自以姓名或父字應之，以取滅亡，而其兆為曹操之魏。兩角犢子之讖，周子諒以劾牛仙客，李德裕以議牛僧孺，而其兆為朱溫。隋煬帝謂李氏當有天下，遂誅李金才之族，而唐高祖乃代隋。唐太宗知女武將竊國命，遂濫五娘子之誅，而阿武婆幾易姓。武後謂代武者劉，劉無強姓，殆流人也，遂遣六道使悉殺之，而劉幽求佐臨淄王平內難，韋、武二族皆殄滅。晉張華、郭璞，魏崔伯深，皆精於天文卜筮，言事如神，而不能免於身誅家族，况其下者乎！","sortOrder":37},
  {"id":"s_work_dtbt_18_38","chapterId":"ch_work_dtbt_18","text":"真假皆妄","sortOrder":38},
  {"id":"s_work_dtbt_18_39","chapterId":"ch_work_dtbt_18","text":"江山登臨之美，泉石賞玩之勝，世間佳境也，觀者必曰如畫。故有「江山如畫」，「天開圖畫即江山」，「身在畫圖中」之語。至於丹青之妙，好事君子嗟嘆之不足者，則又以逼真目之。如老杜「人間又見真乘黃」，「時危安得真致此」，「悄然坐我天姥下」，「斯須九重真龍出」，「憑軒忽若無丹青」，「高堂見生鶻」，「直訝杉松冷」，「兼疑菱荇香」之句是也。以真為假，以假為真，均之為妄境耳。人生萬事如是，何特此耶？","sortOrder":39},
  {"id":"s_work_dtbt_19_1","chapterId":"ch_work_dtbt_19","text":"卷第一(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_19_2","chapterId":"ch_work_dtbt_19","text":"是書先已成十六卷，淳熙十四年八月在禁林日，入侍至尊壽皇聖帝清閑之燕，聖語忽雲：「近見甚齋隨筆。」邁竦而對曰：「是臣所著容齋隨筆，無足采者。」上曰：「（口煞）有好議論。」邁起謝，退而詢之，乃婺女所刻，賈人販鬻於書坊中，貴人買以入，遂塵乙覽。書生遭遇，可謂至榮。因復裒臆說綴於後，懼與前書相亂，故別以一二數而目曰續，亦十六卷雲。紹熙三年三月十日邁序。","sortOrder":2},
  {"id":"s_work_dtbt_19_3","chapterId":"ch_work_dtbt_19","text":"顏魯公","sortOrder":3},
  {"id":"s_work_dtbt_19_4","chapterId":"ch_work_dtbt_19","text":"顏魯公忠義大節，照映今古，豈唯唐朝人士罕見比倫，自漢以來，殆可屈指也。考其立朝出處，在明皇時，為楊國忠所惡，由殿中侍御史出東都、平原。肅宗時，以論太廟築壇事，為宰相所惡，由御史大夫出馮翊。為李輔國所惡，由刑部侍郎貶蓬州。代宗時，以言祭器不飭，元載以為誹謗，由刑部尚書貶峽州。德宗時，不容於楊炎，由吏部尚書換東宮散秩。盧（木巳）之擅國也，欲去公，數遣人問方鎮所便，公往見之，責其不見容，由是銜恨切骨。是時年七十有五，竟墮（木巳）之詭計而死，議者痛之。嗚呼！公既知（木巳）之惡己，盍因其方鎮之問，欣然從之。不然，則高舉遠引，掛冠東去，（木巳）之所甚欲也。而乃眷眷京都，終不自為去就，以蹈危機，春秋責備賢者，斯為可恨。司空圖隱於王官穀，柳璨以詔書召之，圖陽為衰野，墮笏失儀，得放還山。璨之奸惡過於（木巳），圖非公比也，卒全身於大亂之世，然則公之委命賊手，豈不大可惜也哉！雖然，公囚困於淮西，屢折李希烈，卒之捐身徇國，以激四海義烈之氣，貞元反正，實為有助焉。豈天欲全畀公以萬世之名，故使一時墮於橫逆以成始成終者乎！","sortOrder":4},
  {"id":"s_work_dtbt_19_5","chapterId":"ch_work_dtbt_19","text":"戒石銘","sortOrder":5},
  {"id":"s_work_dtbt_19_6","chapterId":"ch_work_dtbt_19","text":"「爾俸爾祿，民膏民脂，下民易虐，上天難欺。」太宗皇帝書此，以賜郡國，立於廳事之南，謂之戒石銘。按成都人景煥，有野人閑話一書，乾德三年所作，其首篇頒令箴，載蜀王孟昶為文頒諸邑雲：「朕念赤子，旰食宵衣。言之令長，撫養惠綏。政存三異，道在七絲。驅鷄為理，留犢為規。寛猛得所，風俗可移。無令侵削，無使瘡痍。下民易虐，上天難欺。賦輿是切，軍國是資。朕之賞罰，固不逾時。爾俸爾祿，民膏民脂。為民父母，莫不仁慈。勉爾為戒，體朕深思。」凡二十四句。昶區區愛民之心，在五季諸僭偽之君為可稱也，但語言皆不工，唯經表出者，詞簡理盡，遂成王言，蓋詩家所謂奪胎換骨法也。","sortOrder":6},
  {"id":"s_work_dtbt_19_7","chapterId":"ch_work_dtbt_19","text":"雙生子","sortOrder":7},
  {"id":"s_work_dtbt_19_8","chapterId":"ch_work_dtbt_19","text":"今時人家雙生男女，或以後生者為長，謂受胎在前；或以先生者為長，謂先後當有序。然固有經一日或亥、子時生，則弟乃先兄一日矣。辰時為弟，巳時為兄，則弟乃先兄一時矣。按春秋公羊傳隱公元年，立適以長不以賢，立子以貴不以長，何休註雲：「子謂左右媵及姪娣之子，質家親親先立娣，文家尊尊先立姪，其雙生也，質家據見立先生，文家據本意立後生。」乃知長幼之次，自商、周以來不同如此。","sortOrder":8},
  {"id":"s_work_dtbt_19_9","chapterId":"ch_work_dtbt_19","text":"李建州","sortOrder":9},
  {"id":"s_work_dtbt_19_10","chapterId":"ch_work_dtbt_19","text":"建安城東二十里，有梨山廟，相傳為唐刺史李公祠。予守郡日，因作祝文曰：「亟回哀眷。」書吏持白回字犯相公名，請改之，蓋以為李回也。後讀文藝李頻傳，懿宗時，頻為建州刺史，以禮法治下。時朝政亂，盜興相椎敓，而建賴頻以安。卒官下，州為立廟梨山，歲祠之，乃證其為頻。繼往禱而祝之雲，俟獲感應，則當刻石紀實。已而得雨，遂為作碑。偶閱唐末人石文德所著唐朝新纂一書，正紀頻事，雲除建州牧，卒於郡。曹松有詩悼之曰：「出旌臨建水，謝世在公堂。苦集休藏篋，清資罷轉郎。瘴中無子奠，嶺外一妻孀。恐是浮吟骨，東歸就故鄉。」其身後事落拓如此。傳又雲：「頻喪歸壽昌，父老相與扶柩葬之。天下亂，盜發其冢，縣人隨加封掩。」則無後可見雲。稽神錄載一事，亦以為回，徐鉉失於不審也。","sortOrder":10},
  {"id":"s_work_dtbt_19_11","chapterId":"ch_work_dtbt_19","text":"侍從官","sortOrder":11},
  {"id":"s_work_dtbt_19_12","chapterId":"ch_work_dtbt_19","text":"自觀文殿大學士至待製，為侍從官，令文所載也。紹興三十一年，完顏亮死於廣陵，車駕將幸建康，從官列銜上奏，乞同班入對。時湯岐公以大觀文為行宮留守，寄聲欲聯名，衆以名位不同為辭。岐公曰：「思退亦侍從也。」然竟不克從。紹熙二年，吏部鄭尚書僑上章乞薦士，詔令在內近臣臺諫、在外侍從，各舉六人堪充朝士者。吏部遍牒，但及內任從官與在外待製以上，而前宰相執政皆不預。安有從官得薦人，而舊弼乃不然，有司之失也。","sortOrder":12},
  {"id":"s_work_dtbt_19_13","chapterId":"ch_work_dtbt_19","text":"存亡大計","sortOrder":13},
  {"id":"s_work_dtbt_19_14","chapterId":"ch_work_dtbt_19","text":"國家大策，係於安危存亡，方變故交切，幸而有智者陳至當之謀，其聽而行之，當如捧漏罋以沃焦釜。而愚荒之主，暗於事幾，且惑於諛佞孱懦者之言，不旋踵而受其禍敗，自古非一也。曹操自將征劉備，田豐勸袁紹襲其後，紹辭以子疾不行。操征烏戎，劉備說劉表襲許，表不能用，後皆為操所滅。唐兵征王世充於洛陽，竇建德自河北來救，太宗屯虎牢以扼之，建德不得進，其臣淩敬請悉兵濟河，攻取懷州、河陽，逾太行，入上黨，徇汾、晉，趣蒲津，蹈無人之境，取勝可以萬全，關中駭震，則鄭圍自解。諸將曰：「淩敬書生，何為知戰事，其言豈可用？」建德乃謝敬。其妻曹氏，又勸令乘唐國之虛，連營漸進，以取山北，西抄關中，唐必還師自救，鄭圍何憂不解。建德亦不從，引衆合戰，身為人擒，國隨以滅。唐莊宗既取河北，屯兵朝城，梁之君臣，謀數道大舉，令董璋引陝虢、澤潞之兵趣太原，霍彥威以汝、洛之兵寇鎮定，王彥章以禁軍攻鄆州，段凝以大軍當莊宗。莊宗聞之，深以為憂。而段凝不能臨機決策，梁主又無斷，遂以致亡。石敬瑭以河東叛，耶律德光赴救，敗唐兵而圍之，廢帝問策於羣臣。時德光兄贊華，因爭國之故，亡歸在唐，吏部侍郎龍敏請立為契丹主，令天雄、盧龍二鎮分兵送之，自幽州趣西樓，朝廷露檄言之，虜必有內顧之慮，然後選募精銳以擊之，此解圍一算也，帝深以為然。而執政恐其無成，議竟不決，唐遂以亡。皇家靖康之難，胡騎犯闕，孤軍深入，後無重援，亦有出奇計乞用師搗燕者，天未悔禍，噬臍弗及，可勝嘆哉！","sortOrder":14},
  {"id":"s_work_dtbt_19_15","chapterId":"ch_work_dtbt_19","text":"唐人詩不傳","sortOrder":15},
  {"id":"s_work_dtbt_19_16","chapterId":"ch_work_dtbt_19","text":"韓文公送李礎序雲：「李生溫然為君子，有詩八百篇，傳詠於時。」又盧尉墓誌雲：「君能為詩，自少至老，詩可錄傳者，在紙凡千餘篇。無書不讀，然止用以資為詩。任登封尉，盡寫所為詩，投留守鄭餘慶，鄭以書薦於宰相。」觀此，則李、盧二子之詩多而可傳。又裴迪與王維同賦輞川諸絕，載於維集，此外更無存者。杜子美有寄裴十詩雲「知君苦思緣詩瘦」，乃迪也，其能詩可知。今考之唐史藝文志，凡別集數百家，無其書，其姓名亦不見於他人文集，諸類詩文中亦無一篇。白樂天作元宗簡集序雲：「著格詩一百八十五，律詩五百九。」至悼其死，曰：「遺文三十軸，軸軸金玉聲。」謂其古常而不鄙，新奇而不怪。今世知其名者寡矣，而況於詩乎！乃知前賢遺稿，湮沒非一，真可惜也！","sortOrder":16},
  {"id":"s_work_dtbt_19_17","chapterId":"ch_work_dtbt_19","text":"泰誓四語","sortOrder":17},
  {"id":"s_work_dtbt_19_18","chapterId":"ch_work_dtbt_19","text":"孔安國古文尚書，自漢以來，不列於學官，故左氏傳所引者，杜預輒註為逸書。劉向說苑臣術篇一章雲：「泰誓曰：『附下而罔上者死，附上而罔下者刑。與聞國政而無益於民者退，在上位而不能進賢者逐。』此所以勸善而黜惡也。」漢武帝元朔元年，詔責中外不興廉舉孝。有司奏議曰：「夫附下罔上者死，附上罔下者刑。與聞國政而無益於民者斥，在上位而不能進賢者退。此所以勸善黜惡也。」其語與說苑所載正同。而諸家註釋，至於顏師古，皆不能援以為證。今之泰誓，初未嘗有此語也。漢宣帝時，河內女子得泰誓一篇獻之，然年月不與序相應，又不與左傳、國語、孟子衆書所引泰誓同，馬、鄭、王肅諸儒皆疑之，今不復可考。","sortOrder":18},
  {"id":"s_work_dtbt_19_19","chapterId":"ch_work_dtbt_19","text":"重陽上巳改日","sortOrder":19},
  {"id":"s_work_dtbt_19_20","chapterId":"ch_work_dtbt_19","text":"唐文宗開成元年，歸融為京兆尹，時兩公主出降，府司供帳事繁，又俯近上巳曲江賜宴，奏請改日。上曰：「去年重陽取九月十九日，未失重陽之意，今改取十三日可也。」且上巳、重陽，皆有定日，而至展一旬，乃知鄭穀所賦十日菊詩雲「自緣今日人心別，未必秋香一夜衰」，亦為未盡也。唯東坡公有「菊花開時即重陽」之語，故記其在海南蓺菊九畹，以十一月望，與客泛酒作重九雲。","sortOrder":20},
  {"id":"s_work_dtbt_19_21","chapterId":"ch_work_dtbt_19","text":"田宅契券取直","sortOrder":21},
  {"id":"s_work_dtbt_19_22","chapterId":"ch_work_dtbt_19","text":"隋書志：「晉自過江，凡貨賣奴婢馬牛田宅，有文券，率錢一萬，輸估四百入官，賣者三百，買者一百。無文券者，隨物所堪，亦百分收四，名為散估。歷宋、齊、梁、陳，如此以為常。以人競商販，不為田業，故使均輸，欲為懲勸。雖以此為辭，其實利在侵削也。」今之牙契投稅，正出於此，田宅所係者大，奉行唯謹，至於奴婢馬牛，雖著於令甲，民不復問。然官所取過多，幷郡邑導行之費，蓋百分用其十五六，又皆買者獨輸，故為數多者率隱減價直，賒立歲月，坐是招激訐訴。頃嘗因奏對，上章乞蠲其半，使民不作偽以息爭，則自言者必多，亦以與為取之義。既下有司，而戶部引條製沮其說。","sortOrder":22},
  {"id":"s_work_dtbt_19_23","chapterId":"ch_work_dtbt_19","text":"公子奚斯","sortOrder":23},
  {"id":"s_work_dtbt_19_24","chapterId":"ch_work_dtbt_19","text":"閟宮詩曰：「新廟奕奕，奚斯所作。」其辭只謂奚斯作廟，義理甚明。鄭氏之說，亦雲作薑嫄廟也。而揚子法言，乃曰正考甫嘗睎尹吉甫，公子奚斯睎正考甫。宋鹹註文，以謂奚斯慕考甫而作魯頌，蓋子雲失之於前，而宋又成其過耳。故吳祕又巧為之說曰：「正考甫商頌蓋美禘祀之事，而奚斯能作閔公之廟，亦睎詩之教也，而魯頌美之。」於義迂矣。司馬溫公亦以謂奚斯作閟宮之詩。兼正考甫只是得商頌於周大師耳，初非自作也。班固、王延壽亦雲奚斯頌魯，後漢曹褒曰：「奚斯頌魯，考甫詠商。」註引薛君韓詩傳雲：「是詩公子奚斯所作。」皆相承之誤。","sortOrder":24},
  {"id":"s_work_dtbt_19_25","chapterId":"ch_work_dtbt_19","text":"唐藩鎮幕府","sortOrder":25},
  {"id":"s_work_dtbt_19_26","chapterId":"ch_work_dtbt_19","text":"唐世士人初登科或未仕者，多以從諸藩府辟置為重。觀韓文公送石洪、溫造二處士赴河陽幕序，可見禮節。然其職甚勞苦，故亦或不屑為之。杜子美從劍南節度嚴武辟為參謀，作詩二十韻呈嚴公雲：「胡為來幕下，只合在舟中。束縛酬知己，蹉跎效小忠。周防期稍稍，太簡遂怱怱。曉入朱扉啟，昏歸畫角終。不成尋別業，未敢息微躬。會希全物色，時放倚梧桐。」而其題曰遣悶，意可知矣。韓文公從徐州張建封辟為推官，有書上張公雲：「受牒之明日，使院小吏持故事節目十餘事來，其中不可者，自九月至二月，皆晨入夜歸，非有疾病事故，輒不許出，若此者非愈之所能也。若寛假之，使不失其性，寅而入，盡辰而退，申而入，終酉而退，率以為常，亦不廢事。苟如此，則死於執事之門無悔也。」杜、韓之旨，大略相似雲。","sortOrder":26},
  {"id":"s_work_dtbt_19_27","chapterId":"ch_work_dtbt_19","text":"文中子門人","sortOrder":27},
  {"id":"s_work_dtbt_19_28","chapterId":"ch_work_dtbt_19","text":"王氏中說，所載門人，多貞觀時知名卿相，而無一人能振師之道者，故議者往往致疑。其最所稱高第，曰程、仇、董、薛，考其行事，程元、仇璋、董常無所見，獨薛收在唐史有列傳，蹤跡甚為明白。收以父道衡不得死於隋，不肯仕，聞唐高祖興，將應義舉，郡通守堯君素覺之，不得去。及君素東連王世充，遂挺身歸國，正在丁丑、戊寅歲中。丁丑為大業十三年，又為義寧元年，戊寅為武德元年，是年三月煬帝遇害於江都，蓋大業十四年也。而杜淹所作文中子世家雲：「十三年江都難作，子有疾，召薛收謂曰：吾夢顏回稱孔子歸休之命。乃寢疾而終。」殊與收事不合，歲年亦不同，是為大可疑者也。又稱李靖受詩及問聖人之道，靖既雲「丈夫當以功名取富貴，何至作章句儒」，恐必無此也。今中說之後，載文中次子福畤所錄雲：「杜淹為御史大夫，與長孫太尉有隙。」予按淹以貞觀二年卒，後二十一年，高宗即位，長孫無忌始拜太尉，其不合於史如此。故或者疑為阮逸所作，如所謂薛收元經傳，亦非也。","sortOrder":28},
  {"id":"s_work_dtbt_19_29","chapterId":"ch_work_dtbt_19","text":"晉燕用兵","sortOrder":29},
  {"id":"s_work_dtbt_19_30","chapterId":"ch_work_dtbt_19","text":"萬事不可執一法，而兵為甚。晉文公圍曹，攻門者多死，曹人尸諸城上。晉侯患之，聽輿人之謀曰：「稱舍於墓。」言若將發冢者。師遷焉，曹人凶懼，因其凶而攻之，遂入曹。燕將騎劫攻齊即墨，田單縱反間言，吾懼燕人掘吾城外冢墓。燕軍乃盡掘冢墓，燒死人，齊人望見皆涕泣，其欲出戰，怒自十倍，已而果敗燕軍。觀晉、燕之所以用計則同，而其成敗頓異者何邪？晉但舍於墓，陽為若將發冢，故曹人懼，而燕真為之，以激怒齊人故爾。","sortOrder":30},
  {"id":"s_work_dtbt_19_31","chapterId":"ch_work_dtbt_19","text":"李衛公帖","sortOrder":31},
  {"id":"s_work_dtbt_19_32","chapterId":"ch_work_dtbt_19","text":"李衞公在朱崖，表弟某侍郎遣人餉以衣物，公有書答謝之，曰：「天地窮人，物情所棄，雖有骨肉，亦無音書，平生舊知，無復弔問。閣老至仁念舊，再降專人，兼賜衣服器物茶藥至多，開緘發紙，涕咽難勝。大海之中，無人拯恤，資儲蕩盡，家事一空，百口嗷然，往往絕食，塊獨窮悴，終日苦飢，唯恨垂沒之年，須作餒而之鬼。十月末，伏枕七旬，藥物陳裛，又無醫人，委命信天，幸而自活。」書後雲閏十一月二十日，從表兄崖州司戶參軍同正李德裕狀侍郎十九弟。按德裕以大中二年十月自潮州司馬貶崖州，所謂閏十一月，正在三年，蓋到崖纔十餘月爾，而窮困苟生已如是。唐書本傳雲：「貶之明年卒。」則是此書既發之後，旋踵下世也。當是時宰相皆其怨仇，故雖骨肉之親，平生之舊，皆不敢復通音問。而某侍郎至於再遣專使，其為高義絕俗可知，惜乎姓名不可得而考耳。此帖藏禁中，後出付祕閣，今勒石於道山堂西。紹興中趙忠簡公亦謫朱崖，士大夫畏秦氏如虎，無一人敢輒寄聲，張淵道為廣西帥，屢遣兵校持書及藥石、酒（麥丏）為饋。公嘗答書雲：「鼎之為己為人，一至於此。」其述酸寒苦厄之狀，略與衞公同。既而亦終於彼，手札今尚存於張氏。姚崇曾孫勖為李公厚善，及李譖逐，擿索支黨，無敢通勞問。既居海上，家無資，病無湯劑，勖數饋餉候問，不傅時為厚薄，其某侍郎之徒與！","sortOrder":32},
  {"id":"s_work_dtbt_19_33","chapterId":"ch_work_dtbt_19","text":"王孫賦","sortOrder":33},
  {"id":"s_work_dtbt_19_34","chapterId":"ch_work_dtbt_19","text":"王延壽王孫賦，載於古文苑，其辭有雲「顏狀類乎老翁，軀體似乎小兒」，謂猴也。乃知杜詩「顏狀老翁為」蓋出諸此。","sortOrder":34},
  {"id":"s_work_dtbt_19_35","chapterId":"ch_work_dtbt_19","text":"漢郡國諸官","sortOrder":35},
  {"id":"s_work_dtbt_19_36","chapterId":"ch_work_dtbt_19","text":"西漢鹽鐵、膳羞、陂湖、工服之屬，郡縣各有司局斡之，其名甚多，然居之者罕。嘗見於史傳，今略以地理志所載言之，凡鐵官三十八，鹽官二十九，工官九，皆不暇紀其處。自餘若京兆有船司空，為主船官。太原有挏馬官，主牧馬，元名家馬官。遼東有牧師官，交趾有羞官，南郡有發弩官，嚴道有水官，丹陽有銅官，桂陽有金官，南海有洭浦官，南郡江夏有雲夢官，九江有陂官、湖官，朐忌、魚復有橘官，鄱陽黃金采，主采金，亦有官。在內則奉常之均官、食官，司農之斡官，少府之大官主膳食，湯官主餅餌，導官主擇米，如是者蓋以百數。","sortOrder":36},
  {"id":"s_work_dtbt_19_37","chapterId":"ch_work_dtbt_19","text":"漢獄名","sortOrder":37},
  {"id":"s_work_dtbt_19_38","chapterId":"ch_work_dtbt_19","text":"漢以廷尉主刑獄，而中都他獄亦不一。宗正屬官有左右都司空。鴻臚有別火令丞，郡邸獄。少府有若盧獄令，考工共工獄。執金吾有寺互、都船獄。又有上林詔獄，水司空掖受祕獄，暴室、請室、居室、徒官之名。張湯傳蘇林曰：「漢儀註獄二十六所。」東漢志雲：「孝武帝所置，世祖皆省之。」東漢洎唐，雖鞫囚非一處，然不至如是其多。國朝但有大理及臺獄，元豐、紹聖間，蔡確、章子厚起同文館獄之類，非故事也。","sortOrder":38},
  {"id":"s_work_dtbt_19_39","chapterId":"ch_work_dtbt_19","text":"容齋續筆","sortOrder":39},
  {"id":"s_work_dtbt_20_1","chapterId":"ch_work_dtbt_20","text":"卷第二(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_20_2","chapterId":"ch_work_dtbt_20","text":"權若訥馮澥","sortOrder":2},
  {"id":"s_work_dtbt_20_3","chapterId":"ch_work_dtbt_20","text":"唐中宗既流殺五王，再復武氏陵廟。右補闕權若訥上疏，以為：「天地日月等字，皆則天能事，賊臣敬暉等輕紊前規，削之無益於淳化，存之有光於孝理。又神龍製書，一事以上，並依貞觀故事，豈可近捨母儀，遠尊祖德。」疏奏，手製褒美。欽宗在位，懲王安石、蔡京之誤國，政事悉以仁宗為法。左諫議大夫馮澥上言：「仁宗皇帝，陛下之高祖也，神宗皇帝，陛下之祖也，子孫之心，寧有厚薄。王安石、司馬光皆天下之大賢，其優劣等差，自有公論，願無作好惡，允執厥中，則是非自明矣。」詔榜朝堂。侍御史李光駁之，不聽，復為右正言崔鶠所擊。宰相不復問，而遷澥吏部侍郎。按若訥與澥兩人，議論操持絕相似，蓋澥在崇寧中，首上書乞廢元祐皇後，自選人除寺監丞，其始終大節，不論可見。建炎初元，乃超居政地，公議憤之。","sortOrder":3},
  {"id":"s_work_dtbt_20_4","chapterId":"ch_work_dtbt_20","text":"歲旦飲酒","sortOrder":4},
  {"id":"s_work_dtbt_20_5","chapterId":"ch_work_dtbt_20","text":"今人元日飲屠酥酒，自小者起，相傳已久，然固有來處。後漢李膺、杜密以黨人同繫獄，值元日，於獄中飲酒，曰：「正旦從小起。」時鏡新書晉董勛雲：「正旦飲酒先從小者，何也？勛曰：『俗以小者得歲，故先酒賀之，老者失時，故後飲酒。』」初學記載四民月令雲：「正旦進酒次第，當從小起，以年小者起先。」唐劉夢得、白樂天元日舉酒賦詩，劉雲：「與君同甲子，壽酒讓先杯。」白雲：「與君同甲子，歲酒合誰先。」白又有歲假內命酒一篇雲：「歲酒先拈辭不得，被君推作少年人。」顧況雲：「不覺老將春共至，更悲攜手幾人全。還丹寂寞羞明鏡，手把屠蘇讓少年。」裴夷直雲：「自知年幾偏應少，先把屠蘇不讓春。儻更數年逢此日，還應惆悵羨他人。」成文幹雲：「戴星先捧祝堯觴，鏡裏堪驚兩鬢霜。好是燈前偷失笑，屠蘇應不得先嘗。」方幹雲：「纔酌屠蘇定年齒，坐中皆笑鬢毛斑。」然則尚矣。東坡亦雲：「但把窮愁博長健，不辭最後飲屠酥。」其義亦然。","sortOrder":5},
  {"id":"s_work_dtbt_20_6","chapterId":"ch_work_dtbt_20","text":"存歿絕句","sortOrder":6},
  {"id":"s_work_dtbt_20_7","chapterId":"ch_work_dtbt_20","text":"杜子美有存歿絕句二首雲：「席謙不見近彈棋，畢曜仍傳舊小詩。玉局他年無限笑，白楊今日幾人悲。」「鄭公粉繪隨長夜，曹霸丹青已白頭。天下何曾有山水，人間不解重驊騮。」每篇一存一歿。蓋席謙、曹霸存，畢、鄭歿也。黃魯直荊江亭即事十首，其一雲：「閉門覓句陳無己，對客揮毫秦少遊。正字不知溫飽未，西風吹淚古藤州。」乃用此體。時少遊歿而無己存也。近歲新安胡仔著漁隱叢話，謂魯直以今時人形入詩句，蓋取法於少陵，遂引此句，實失於詳究雲。","sortOrder":7},
  {"id":"s_work_dtbt_20_8","chapterId":"ch_work_dtbt_20","text":"湯武之事","sortOrder":8},
  {"id":"s_work_dtbt_20_9","chapterId":"ch_work_dtbt_20","text":"湯、武之事，古人言之多矣。惟漢轅固、黃生爭辯最詳。黃生曰：「湯、武非受命，乃殺也。」固曰：「不然，桀、紂荒亂，天下之心皆歸湯、武。湯、武因天下之心而誅桀、紂，不得已而立，非受命為何？」黃生曰：「冠雖敝必加於首，履雖新必貫於足。今桀、紂雖失道，君上也，湯、武雖聖，臣下也，反因過而誅之，非殺而何？」景帝曰：「食肉毋食馬肝，未為不知味；言學者毋言湯、武受命，未為愚。」遂罷。顏師古註雲：「言湯、武為殺，是背經義，故以馬肝為喻也。」東坡志林雲：「武王非聖人也，昔者孔子蓋罪湯、武，伯夷、叔齊不食周粟，而孔子予之，其罪武王也甚矣。至孟軻始亂之，使當時有良史，南巢之事，必以叛書，牧野之事，必以弒書。湯、武仁人也，必將為法受惡。」可謂至論。然予竊考孔子之序書，明言伊尹相湯伐桀，成湯放桀於南巢，武王伐商，武王勝商殺受，各蔽以一語，而大指皦如，所謂六蓺折衷，無待於良史復書也。","sortOrder":9},
  {"id":"s_work_dtbt_20_10","chapterId":"ch_work_dtbt_20","text":"張釋之傳誤","sortOrder":10},
  {"id":"s_work_dtbt_20_11","chapterId":"ch_work_dtbt_20","text":"漢書紀傳志表，矛盾不同非一，然唯張釋之為甚。本傳雲：「釋之為騎郎，事文帝十年不得調，亡所知名，欲免歸。中郎將袁盎惜其去，請徙補謁者，後拜為廷尉，逮事景帝，歲餘，為淮南相。」而百官公卿表所載，文帝即位三年，釋之為廷尉，至十年，書廷尉昌、廷尉嘉又二人，凡歷十三年，景帝乃立，而張敺為廷尉，則是釋之未嘗十年不調，及未嘗以廷尉事景帝也。","sortOrder":11},
  {"id":"s_work_dtbt_20_12","chapterId":"ch_work_dtbt_20","text":"張於二廷尉","sortOrder":12},
  {"id":"s_work_dtbt_20_13","chapterId":"ch_work_dtbt_20","text":"張釋之為廷尉，天下無寃民。於定國為廷尉，人自以不寃。此漢史所稱也。兩人在職皆十餘年。周勃就國，人上書告勃欲反，下廷尉逮捕，吏稍侵辱之，勃以千金與獄吏，吏使以公主為證，太後亦以為無反事，乃得赦出。釋之正為廷尉，不能救，但申理犯蹕、盜環一二細事耳。楊惲為人告驕奢不悔過，下廷尉案驗，始得所予孫會宗書，定國當惲大逆無道，惲坐要斬。惲之罪何至於是？其徇主之過如此。傳所謂決疑平法，務在哀矜者，果何為哉！","sortOrder":13},
  {"id":"s_work_dtbt_20_14","chapterId":"ch_work_dtbt_20","text":"漢唐置郵","sortOrder":14},
  {"id":"s_work_dtbt_20_15","chapterId":"ch_work_dtbt_20","text":"趙充國在金城，上書言先零、罕羌事，六月戊申奏，七月甲寅璽書報從其計。按金城至長安一千四百五十里，往反倍之，中間更下公卿議臣，而自上書至得報，首尾纔七日。唐開元十年八月己卯夜，權楚璧等作亂，時明皇幸洛陽，相去八百餘里。壬午，遣河南尹王怡如京師按問宣慰，首尾纔三日。置郵傳命，既如此其速，而廷臣共議，蓋亦未嘗淹久，後世所不及也。","sortOrder":15},
  {"id":"s_work_dtbt_20_16","chapterId":"ch_work_dtbt_20","text":"龍且張步","sortOrder":16},
  {"id":"s_work_dtbt_20_17","chapterId":"ch_work_dtbt_20","text":"韓信擊趙，李左車勸陳餘勿與戰，餘曰：「今如此避弗擊，諸侯謂吾怯，而輕來伐我。」遂與信戰，身死國亡。是時，信方為漢將，始攻下魏、代，威聲猶未暴白，陳餘易之，尚不足訝。及滅趙服燕，則關東六國，既定其四矣。信伐齊，楚使龍且來救。或言漢兵不可當，龍且曰：「吾平生知韓信為人易與耳，不足畏也，何為而止？」一戰而沒，項隨以亡。耿弇討張步，斬其大將軍費邑，走邑之弟敢，進攻西安、臨淄，拔其城，又走其弟藍，勢如破竹。先是，弇已破尤來、大槍、延岑、彭寵、富平、獲索矣。時步所盜齊地，太半為弇所得。然步猶曰：「以尤來、大肜十餘萬衆，吾皆即其營而破之。今弇兵少於彼，又皆疲勞，何足摧乎？」竟出兵大戰，兄弟成擒。兵法雲：「知彼知己，百戰不殆。」龍且、張步，豈復識此哉！梁臨川王宏伐魏，魏元英禦之，宏停軍不前。魏人勸英進據洛水，英曰：「蕭臨川雖騃，其下有良將韋、裴之屬，未可輕也。宜且觀形勢，勿與交鋒。」宏卒敗退，英之識見，非前人可比也。然遂進軍圍鍾離，魏邢巒以為不可，魏主召使還，英表稱必克，為曹景宗、韋叡所挫，失亡二十餘萬人。智於前而昧於後，為可恨耳！","sortOrder":17},
  {"id":"s_work_dtbt_20_18","chapterId":"ch_work_dtbt_20","text":"義理之說無窮","sortOrder":18},
  {"id":"s_work_dtbt_20_19","chapterId":"ch_work_dtbt_20","text":"經典義理之說最為無窮，以故解釋傳疏，自漢至今，不可概舉，至有一字而數說者。姑以周易革卦言之，「已日乃孚，革而信之。」自王輔嗣以降，大抵謂即日不孚，已日乃孚，已字讀如矣音，蓋其義亦止如是耳。唯朱子發讀為戊己之己。予昔與易僧曇瑩論及此，問之曰：「或讀作己(音紀)日如何？」瑩曰：「豈唯此也，雖作巳(音似)日亦有義。」乃言曰：「天元十幹，自甲至己，然後為庚，庚者革也，故己日乃孚，猶雲從此而革也。十二辰自子至巳六陽，數極則變而之陰，於是為午，故巳日乃孚，猶雲從此而變也。」用是知好奇者欲穿鑿附會，固各有說雲。","sortOrder":19},
  {"id":"s_work_dtbt_20_20","chapterId":"ch_work_dtbt_20","text":"開元五王","sortOrder":20},
  {"id":"s_work_dtbt_20_21","chapterId":"ch_work_dtbt_20","text":"唐明皇兄弟五王，兄申王撝以開元十二年，寧王憲、邠王守禮以二十九年，弟岐王範以十四年，薛王業以二十二年薨，至天寶時已無存者。楊太真以三載方入宮，而元稹連昌宮詞雲：「百官隊仗避岐、薛，楊氏諸姨車鬭風。」李商隱詩雲：「夜半宴歸宮漏永，薛王沉醉壽王醒。」皆失之也。","sortOrder":21},
  {"id":"s_work_dtbt_20_22","chapterId":"ch_work_dtbt_20","text":"巫蠱之禍","sortOrder":22},
  {"id":"s_work_dtbt_20_23","chapterId":"ch_work_dtbt_20","text":"漢世巫蠱之禍，雖起於江充，然事會之來，蓋有不可曉者。武帝居建章宮，親見一男子帶劍入中龍華門，疑其異人，命收之，男子捐劍走，逐之弗獲。上怒，斬門候，閉長安城門，大索十一日，巫蠱始起。又嘗晝寢，夢木人數十，持杖欲擊己，乃驚寤，因是體不平，遂苦忽忽善忘。此兩事可謂異矣。木將腐，蠹實生之。物將壞，蟲實生之。是時帝春秋已高，忍而好殺，李陵所謂法令無常，大臣無罪夷滅者數十家。由心術既荒，隨念招妄，男子、木人之兆，皆迷不復開，則謫見於天，鬼瞰其室。禍之所被，以妻則衞皇後，以子則戾園，以兄子則屈氂，以女則諸邑、陽石公主，以婦則史良娣，以孫則史皇孫。骨肉之酷如此，豈復顧他人哉？且兩公主實衞後所生，太子未敗數月前，皆已下獄誅死，則其母與兄豈有全理？固不待於江充之譖也。","sortOrder":23},
  {"id":"s_work_dtbt_20_24","chapterId":"ch_work_dtbt_20","text":"唐詩無諱避","sortOrder":24},
  {"id":"s_work_dtbt_20_25","chapterId":"ch_work_dtbt_20","text":"唐人歌詩，其於先世及當時事，直辭詠寄，略無避隱。至宮禁嬖昵，非外間所應知者，皆反復極言，而上之人亦不以為罪。如白樂天長恨歌諷諫諸章，元微之連昌宮詞，始末皆為明皇而發。杜子美尤多，如兵車行、前後出塞、新安吏、潼關吏、石壕吏、新婚別、垂老別、無家別、哀王孫、悲陳陶、哀江頭、麗人行、悲青阪、公孫舞劍器行，終篇皆是。其他波及者，五言如：「憶昨狼狽初，事與古先別。」「不聞夏商衰，中自誅褒妲。」「是時妃嬪戮，連為糞土叢。」「中宵焚九廟，雲漢為之紅。」「先帝正好武，寰海未凋枯。」「拓境功未已，元和辭大爐。」「內人紅袖泣，王子白衣行。」「毀廟天飛雨，焚宮火徹明。」「南內開元曲，常時弟子傳。法歌聲變轉，滿座涕潺湲。」「御氣雲樓敞，含風綵仗高。仙人張內樂，王母獻宮桃。」「須為下殿走，不可好樓居。」「固無牽白馬，幾至著青衣。」「奪馬悲公主，登車泣貴嬪。」「兵氣淩行在，妖星下直廬。」「落日留王母，微風倚少兒。」「能畫毛延壽，投壺郭舍人。」「鬭鷄初賜錦，舞馬更登牀。」「驪山絕望幸，花萼罷登臨。」「殿瓦鴛鴦坼，宮簾翡翠虛。」七言如：「關中小兒壞紀綱，張後不樂上為忙。」「天子不在鹹陽宮，得不哀痛塵再蒙。」「曾貌先帝照夜白，龍池十日飛霹靂。」「要路何日罷長戟，戰自青羌連白蠻。」「豈謂盡煩回紇馬，翻然遠救朔方兵。」如此之類，不能悉書。此下如張祜賦連昌宮、元日仗、千秋樂、大酺樂、十五夜燈、熱戲樂、上巳樂、邠王小管、李謨笛、退宮人、玉環琵琶、春鶯囀、寧哥來、容兒鉢頭、邠娘羯鼓、耍娘歌、悖挐兒舞、華清宮、長門怨、集靈臺、阿保鳥湯、馬嵬歸、香囊子、散花樓、雨霖鈴等三十篇，大抵詠開元、天寶間事。李義山華清宮、馬嵬、驪山、龍池諸詩亦然。今之詩人不敢爾也。","sortOrder":25},
  {"id":"s_work_dtbt_20_26","chapterId":"ch_work_dtbt_20","text":"李晟傷國體","sortOrder":26},
  {"id":"s_work_dtbt_20_27","chapterId":"ch_work_dtbt_20","text":"將帥握重兵居閫外，當國家多事時，其奉上承命，尤當以恭順為主。唐李晟在德宗朝，破朱泚，復長安，功名震耀，蓋社稷宗臣也。然嘗將神策軍戍蜀，及還以營妓自隨，節度使張延賞追而返之，由是有隙。晟既立大功，上召延賞入相，晟表陳其過惡，上重違其意，乃止。後歲餘，上命韓滉諭旨於晟使釋怨，滉因使晟表薦，延賞遂為相。然則輔相之拜罷，皆大將得製之，其傷國體甚矣。德宗猜忌刻薄，渠能釋然！晟之失兵柄，正緣此耳。國學武成王廟，本列晟於十哲，乾道中有旨，退於從祀，壽皇聖意豈非出此乎？","sortOrder":27},
  {"id":"s_work_dtbt_20_28","chapterId":"ch_work_dtbt_20","text":"元和六學士","sortOrder":28},
  {"id":"s_work_dtbt_20_29","chapterId":"ch_work_dtbt_20","text":"白樂天分司東都，有詩上李留守相公，其序言：「公見過池上，泛舟舉酒，話及翰林舊事，因成四韻。」後兩聯雲：「白首故情在，青雲往事空。同時六學士，五相一漁翁。」此詩蓋與李絳者，其詞正紀元和二年至六年事。予以其時考之，所謂五相者，裴垍、王涯、杜元穎、崔羣及絳也。紹興二十八年三月，予入館，明年八月，除吏部郎官，一時同舍祕書丞虞雍公幷甫、著作郎陳魏公應求、祕書郎史魏公直翁、校書郎王魯公季海，皆至宰相，汪莊敏公明遠至樞密使，恩數與宰相等，甚類元和事雲。","sortOrder":29},
  {"id":"s_work_dtbt_20_30","chapterId":"ch_work_dtbt_20","text":"二傳誤後世","sortOrder":30},
  {"id":"s_work_dtbt_20_31","chapterId":"ch_work_dtbt_20","text":"自左氏載石碏事，有「大義滅親」之語，後世援以為說，殺子孫，害兄弟。如漢章帝廢太子慶，魏孝文殺太子恂，唐高宗廢太子賢者，不可勝數。公羊書魯隱公、桓公事，有「子以母貴，母以子貴」之語，後世援以為說，廢長立少，以妾為後妃。如漢哀帝尊傅昭儀為皇太太後，光武廢太子彊而立東海王陽，唐高宗廢太子忠而立孝敬者，亦不可勝數。","sortOrder":31},
  {"id":"s_work_dtbt_20_32","chapterId":"ch_work_dtbt_20","text":"卜子夏","sortOrder":32},
  {"id":"s_work_dtbt_20_33","chapterId":"ch_work_dtbt_20","text":"魏文侯以卜子夏為師。按史記所書，子夏少孔子四十四歲，孔子卒時，子夏年二十八矣。是時，周敬王四十一年，後一年元王立，歷貞定王、考王，至威烈王二十三年，魏始為侯，去孔子卒時七十五年。文侯為大夫二十二年而為侯，又十六年而卒，姑以始侯之歲計之，則子夏已百三歲矣，方為諸侯師，豈其然乎？","sortOrder":33},
  {"id":"s_work_dtbt_20_34","chapterId":"ch_work_dtbt_20","text":"父子忠邪","sortOrder":34},
  {"id":"s_work_dtbt_20_35","chapterId":"ch_work_dtbt_20","text":"漢王氏擅國，王章、梅福嘗言之，唯劉向勤勤懇懇，上封事極諫，至雲：「事勢不兩大，王氏與劉氏亦且不並立。陛下為人子孫，守持宗廟，而令國祚移於外親，降為皂隸。為後嗣憂，昭昭甚明。」其言痛切如此。而子歆乃用王莽舉為侍中，為莽典文章，倡導在位，褒揚功德，安漢、宰衡之名，皆所共謀，馴致攝，卒之身亦不免。魏陳矯事曹氏，三世為之盡忠，明帝憂社稷，問曰：「司馬懿忠正，可謂社稷之臣乎？」矯曰：「朝廷之望，社稷未知也。」懿竟竊國柄。至孫炎魏為晉，而矯之子騫乃用佐命勳，位極公輔。晉郗愔忠於王室，而子超黨於桓氏，為溫建廢立之謀。超死，愔哀悼成疾。後見超書一箱，悉與溫往反密計，遂大怒曰：「小子死恨晚！」更不復哭。晉史以為有大義之風。向、矯、愔之忠如是，三子不勝誅矣！","sortOrder":35},
  {"id":"s_work_dtbt_20_36","chapterId":"ch_work_dtbt_20","text":"蘇張說六國","sortOrder":36},
  {"id":"s_work_dtbt_20_37","chapterId":"ch_work_dtbt_20","text":"蘇秦、張儀同學於鬼穀，而其從橫之辯，如冰炭水火之不同，蓋所以設心者異耳。蘇欲六國合從以擯秦，故言其強。謂燕地方二千餘里，帶甲數十萬，車六百乘，騎六千匹；謂趙地亦方二千餘里，帶甲數十萬，車千乘，騎萬匹；謂韓地方九百里，帶甲數十萬，天下之強弓勁弩，皆從韓出，韓卒之勇，一人當百；謂魏地方千里，卒七十萬；齊地方二千餘里，臨菑之卒，固已二十一萬；楚地方五千里，帶甲百萬，車千乘，騎萬匹。至於張儀，則欲六國為橫以事秦，故言其弱。謂梁地方不過千里，卒不過三十萬；韓地險惡，卒不過二十萬；臨菑、即墨非齊之有；斷趙右肩；黔、巫非楚有；易水、長城非燕有。然而六王皆聳聽敬從，舉國而付之，未嘗有一語相折難者，彼皆長君，持國之日久，逮其臨事，乃顧如桔橰，隨人俯仰，得不危亡幸矣哉！且一國之勢，猶一家也。今夫主一家之政者，較量生理，名田若幹頃，歲收穀粟若幹；蓺園若幹畝，歲收桑麻若幹；邸舍若幹區，為錢若幹；下至牛羊犬鷄，莫不有數，自非童騃孱愚之人，未有不能件析而枚數者，何待於疏遠遊客為吾借箸而籌哉？苟一以為多，一以為寡，將遂挈挈然舉而信之乎？鼂錯說景帝曰：「高帝大封同姓，齊七十餘城，楚四十餘城，吳五十餘城，分天下半。」以漢之廣，三國渠能分其半，此錯欲削諸侯，故盛言其大爾。膠西王將與吳反，羣臣諫曰：「諸侯地不能當漢十二，為叛逆非計也。」是時反者即吳、楚、諸齊，此膠西臣欲止王之謀，故盛言其小爾。二者視蘇、張之言，疑若相似，而用心則否，聽之者惟能知彼知己，則善矣。","sortOrder":37},
  {"id":"s_work_dtbt_20_38","chapterId":"ch_work_dtbt_20","text":"容齋三筆","sortOrder":38},
  {"id":"s_work_dtbt_21_1","chapterId":"ch_work_dtbt_21","text":"卷第三(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_21_2","chapterId":"ch_work_dtbt_21","text":"兔葵燕麥","sortOrder":2},
  {"id":"s_work_dtbt_21_3","chapterId":"ch_work_dtbt_21","text":"劉禹錫再遊玄都觀詩序雲：「唯兔葵燕麥，動搖春風耳。」今人多引用之。予讀北史邢邵傳載邵一書雲：「國子雖有學官之名，而無教授之實，何異兔絲燕麥，南箕北斗哉？」然則此語由來久矣。爾雅曰：「莃，兔葵。籥，雀麥。」郭璞註曰：「頗似葵而葉小，狀如藜；雀麥即燕麥，有毛。」廣志曰：「菟葵，爚之可食。」古歌曰：「田中菟絲，何嘗可絡？道邊燕麥，何嘗可穫？」皆見於太平御覽。上林賦：「葴析苞荔，」張揖註曰：「析，似燕麥，音斯。」葉庭珪海錄碎事雲：「兔葵，苗如龍芮，花白莖紫。燕麥草似麥，亦曰雀麥。」但未詳出於何書。","sortOrder":3},
  {"id":"s_work_dtbt_21_4","chapterId":"ch_work_dtbt_21","text":"北狄俘虜之苦","sortOrder":4},
  {"id":"s_work_dtbt_21_5","chapterId":"ch_work_dtbt_21","text":"元魏破江陵，盡以所俘士民為奴，無問貴賤，蓋北方夷俗皆然也。自靖康之後，陷於金虜者，帝子王孫，宦門仕族之家，盡沒為奴婢，使供作務。每人一月支稗子五斗，令自舂為米，得一斗八升，用為餱糧。歲支麻五把，令緝為裘，此外更無一錢一帛之入。男子不能緝者，則終歲裸體，虜或哀之，則使執爨，雖時負火得煖氣，然纔出外取柴，歸再坐火邊，皮肉即脫落，不日輒死。惟喜有手藝，如醫人、繡工之類，尋常只團坐地上，以敗席或蘆藉襯之。遇客至開筵，引能樂者使奏技，酒闌客散，各復其初，依舊環坐刺繡，任其生死，視如草芥。先公在英州，為攝守蔡寯言之，蔡書於甲戌日記，後其子大器錄以相示，此松漠記聞所遺也。","sortOrder":5},
  {"id":"s_work_dtbt_21_6","chapterId":"ch_work_dtbt_21","text":"太守刺史贈吏民官","sortOrder":6},
  {"id":"s_work_dtbt_21_7","chapterId":"ch_work_dtbt_21","text":"漢薛宣為左馮翊，池陽令舉廉吏獄掾王立，未及召，立妻受囚家錢，慚恐自殺。宣移書池陽曰：「其以府決曹掾書立之柩，以顯其魂。」顏師古註雲：「以此職追贈也。」後魏幷州刺史以部民吳悉達兄弟行著鄉里，板贈其父渤海太守。此二者皆以太守、刺史而擅贈吏民官職，不以為過，後世不敢然也。","sortOrder":7},
  {"id":"s_work_dtbt_21_8","chapterId":"ch_work_dtbt_21","text":"李元亮詩啟","sortOrder":8},
  {"id":"s_work_dtbt_21_9","chapterId":"ch_work_dtbt_21","text":"建昌縣士人李元亮，山房公擇尚書族子也，抱材尚氣，不以辭色假人。崇寧中在大學，蔡薿為學錄，元亮惡其人，不以所事前廊之禮事之。蔡擢第魁多士，元亮失意歸鄉。大觀二年冬，復詣學，道過和州。蔡解褐即超用，纔二年，至給事中，出補外，正臨此邦。元亮不肯入謁。蔡自到官，即戒津吏門卒，凡士大夫往來，無問官高卑，必飛報，雖布衣亦然。既知其來，便命駕先造所館。元亮驚喜出迎，謝曰：「所以來，顓為門下之故。方脩贄見之禮，須明旦扣典客，不意給事先生卑躬下賤如此，前贄不可復用，當別撰一通，然後敬謁。」蔡退，元亮旋營一啟，旦而往焉，其警策曰：「定館而見長者，古所不然；輕身以先匹夫，今無此事。」蔡摘讀嗟激，留宴連夕，贈以五十萬錢，且致書延譽於諸公間，遂登三年貢士科。元亮亦工詩，如「人閑知晝永，花落見春深」，「朝雨未休還暮雨，臘寒纔過又春寒」，皆佳句也。","sortOrder":9},
  {"id":"s_work_dtbt_21_10","chapterId":"ch_work_dtbt_21","text":"元魏改功臣姓氏","sortOrder":10},
  {"id":"s_work_dtbt_21_11","chapterId":"ch_work_dtbt_21","text":"魏孝文自代遷洛，欲大革胡俗，既自改拓跋為元氏，而諸功臣舊族自代來者，以姓或重複，皆改之。於是拔拔氏為長孫氏，達奚氏為奚氏，乙旃氏為叔孫氏，丘穆陵氏為穆氏，步六孤氏為陸氏，賀賴氏為賀氏，獨孤氏為劉氏，賀樓氏為樓氏，勿忸於氏為於氏，尉遲氏為尉氏，其用夏變夷之意如此。然至於其孫恭帝，翻以中原故家，易賜蕃姓，如李弼為徒河氏，趙肅、趙貴為乙弗氏，劉亮為侯莫陳氏，楊忠為普六茹氏，王雄為可頻氏，李虎、閻慶為大野氏，辛威為普毛氏，田宏為紇幹氏，耿豪為和稽氏，王勇為庫汗氏，楊紹為叱利氏，侯植為侯伏侯氏，竇熾為紇豆陵氏，李穆為拔氏，陸通為步六孤氏，楊纂為莫胡盧氏，寇儁為若口引氏，段永為爾綿氏，韓褒為侯呂陵氏，裴文舉為賀蘭氏，王軌為烏丸氏，陳忻為尉遲氏，樊深為萬紐於氏，一何其不循乃祖彝憲也！是時蓋宇文泰顓國，此事皆出其手，遂復國姓為拓跋，而九十九姓改為單者，皆復其舊。泰方以時俗文敝，命蘇綽倣周書作大誥，又悉改官名，復周六卿之製，顧乃如是，殆不可曉也。","sortOrder":11},
  {"id":"s_work_dtbt_21_12","chapterId":"ch_work_dtbt_21","text":"東坡和陶詩","sortOrder":12},
  {"id":"s_work_dtbt_21_13","chapterId":"ch_work_dtbt_21","text":"陶淵明集歸田園居六詩，其末「種苗在東皋」一篇，乃江文通雜體三十篇之一，明言斅陶徵君田居，蓋陶之三章雲：「種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。」故文通雲：「雖有荷鋤倦，濁酒聊自適。」正擬其意也。今陶集誤編入，東坡據而和之。又「東方有一士」詩十六句，復重載於擬古九篇中，坡公遂亦兩和之，皆隨意即成，不復細考耳。陶之首章雲：「榮榮窗下蘭，密密堂前柳。初與君別時，不謂行當久。出門萬里客，中道逢嘉友。未言心先醉，不在接杯酒。蘭枯柳亦衰，遂令此言負。」坡和雲：「有客扣我門，繫馬庭前柳。庭空鳥雀噪，門閉客立久。主人枕書臥，夢我平生友。忽聞剝啄聲，驚散一杯酒。倒裳起謝客，夢覺兩愧負。」二者金石合奏，如出一手，何止子由所謂遂與比轍者哉！","sortOrder":13},
  {"id":"s_work_dtbt_21_14","chapterId":"ch_work_dtbt_21","text":"孔戣鄭穆","sortOrder":14},
  {"id":"s_work_dtbt_21_15","chapterId":"ch_work_dtbt_21","text":"唐孔戣在穆宗時為尚書左丞，上書去官，天子以為禮部尚書致仕，吏部侍郎韓愈奏疏曰：「戣為人守節清苦，議論正平，年纔七十，筋力耳目，未覺衰老，憂國忘家，用意至到。如戣輩，在朝不過三數人，陛下不宜苟順其求，不留自助也。」不報。明年正月，戣薨。國朝鄭穆在元祐中以寶文閣待製兼國子祭酒請老，提舉洞霄宮，給事中范祖禹言：「穆雖年出七十，精力尚強，古者大夫七十而致仕，有不得謝，則賜之幾杖，祭酒居師資之地，正宜處老成，願毋輕聽其去。」亦不報。然穆亦至明年卒。二事絕相類。","sortOrder":15},
  {"id":"s_work_dtbt_21_16","chapterId":"ch_work_dtbt_21","text":"陳季常","sortOrder":16},
  {"id":"s_work_dtbt_21_17","chapterId":"ch_work_dtbt_21","text":"陳慥字季常，公弼之子，居於黃州之岐亭，自稱「龍丘先生」，又曰「方山子」。好賓客，喜畜聲妓，然其妻柳氏絕凶妒，故東坡有詩雲：「龍丘居士亦可憐，談空說有夜不眠。忽聞河東師子吼，拄杖落手心茫然。」河東師子，指柳氏也。坡又嘗醉中與季常書雲：「一絕乞秀英君。」想是其妾小字。黃魯直元祐中有與季常簡曰：「審柳夫人時須醫藥，今已安平否？公暮年來想漸求清淨之樂，姬媵無新進矣，柳夫人比何所念以致疾邪？」又一帖雲：「承諭老境情味，法當如此，所苦既不妨遊觀山川，自可損藥石，調護起居飲食而已。河東夫人亦能哀憐老大，一任放不解事邪？」則柳氏之妒名，固彰著於外，是以二公皆言之雲。","sortOrder":17},
  {"id":"s_work_dtbt_21_18","chapterId":"ch_work_dtbt_21","text":"文用謚字","sortOrder":18},
  {"id":"s_work_dtbt_21_19","chapterId":"ch_work_dtbt_21","text":"先王謚以尊名，節以壹惠，故謂為易名。然則謚之為義，正訓名也。司馬長卿諭蜀文曰：「身死無名，謚為至愚。」顏註雲：「終以愚死，後葉傳稱，故謂之謚。」柳子厚招海賈文曰：「君不返兮謚為愚。」二人所用，其意則同。唯王子淵簫賦曰：「幸得謚為洞簫兮，蒙聖主之渥恩。」李善謂：「謚者號也，言得謚為簫而常施用之。」以器物名為謚，其語可謂奇矣。","sortOrder":19},
  {"id":"s_work_dtbt_21_20","chapterId":"ch_work_dtbt_21","text":"高唐神女賦","sortOrder":20},
  {"id":"s_work_dtbt_21_21","chapterId":"ch_work_dtbt_21","text":"宋玉高唐、神女二賦，其為寓言託興甚明。予嘗即其詞而味其旨，蓋所謂發乎情，止乎禮義，真得詩人風化之本。前賦雲：「楚襄王望高唐之上有雲氣，問玉曰：『此何氣也？』對曰：『所謂朝雲者也。昔者先王嘗遊高唐，夢見一婦人，曰，妾巫山之女也，願薦枕蓆。王因幸之。』」後賦雲：「襄王既使玉賦高唐之事，其夜王寢，夢與神女遇，復命玉賦之。」若如所言，則是王父子皆與此女荒淫，殆近於聚麀之醜矣。然其賦雖篇首極道神女之美麗，至其中則雲：「澹清靜其愔嫕兮，性沈詳而不煩。意似近而若遠兮，若將來而復旋。褰餘幬而請御兮，願盡心之惓惓。懷貞亮之潔清兮，卒與我乎相難。頩薄怒以自持兮，曾不可乎犯幹。歡情未接，將辭而去。遷延引身，不可親附。願假須臾，神女稱遽。闇然而冥，忽不知處。」然則神女但與懷王交御，雖見夢於襄，而未嘗及亂也。玉之意可謂正矣。今人詩詞，顧以襄王藉口，考其實則非是。頩，音疋零反，斂容怒色也。柳子厚謫龍說有「奇女頩爾怒」之語，正用此也。","sortOrder":21},
  {"id":"s_work_dtbt_21_22","chapterId":"ch_work_dtbt_21","text":"其言明且清","sortOrder":22},
  {"id":"s_work_dtbt_21_23","chapterId":"ch_work_dtbt_21","text":"禮記緇衣篇：「詩雲，昔吾有先正，其言明且清。國家以寧，都邑以成，庶民以生。誰能秉國成？不自為正，卒勞百姓。」鄭氏註不言何詩。今毛詩節南山章但有下三句而微不同。經典釋文雲：「從第一句至庶民以生五句，今詩皆無此語，或皆逸詩也。」予按文選張華答何劭詩曰：「周任有遺規，其言明且清。」然則周任所作也。而李善註曰：「子思子詩雲，昔吾有先正，其言明且清。」世之所存子思子亦無之，不知善何所據？意當時或有此書，善必不妄也，特不及周任遺規之義，又不可曉。","sortOrder":23},
  {"id":"s_work_dtbt_21_24","chapterId":"ch_work_dtbt_21","text":"侍從轉官","sortOrder":24},
  {"id":"s_work_dtbt_21_25","chapterId":"ch_work_dtbt_21","text":"元豐未改官製以前，用職事官寄祿。自諫議大夫轉給事中，(學士轉中書舍人。)歷三侍郎、(學士轉左曹禮、戶、吏部，餘人轉右曹工、刑、兵部。)左右丞，(吏侍轉左，兵侍轉右。)然後轉六尚書，各為一官。尚書轉僕射，非曾任宰相者不許轉，今之特進是也。故侍從止於吏書，由諫議至此凡十一轉。其庶僚久於卿列者，則自光祿卿轉祕書監，繼歷太子賓客，遂得工部侍郎。蓋以不帶待製以上職，不許入兩省給、諫耳。元豐改諫議為太中大夫，給、舍為通議，六侍郎同為正議，左右丞為光祿。兵、戶、刑、禮、工書同為銀青，吏書金紫。但六轉，視舊法損其五。元祐中以為太簡，增正議、光祿、銀青為左右，然亦纔九資。大觀二年，置通奉以易右正議，正奉以易右光祿，宣奉以易左光祿，以右銀青為光祿，而至銀青者去其左字，今皆仍之。比倣舊製，今之通奉，乃工、禮侍郎，正議乃刑、戶，正奉乃兵、吏，宣奉乃左右丞，三光祿乃六尚書也。凡侍從序遷至金紫無止法，建炎以前多有之。紹興以來，階官到此絕少，唯梁揚祖、葛勝仲致仕得之。近歲有司不能探賾典故，予以宣奉當磨勘，又該覃霈，顏師魯在天官，徑給回授一據，而不明言其所由。比程叔達由宣奉納祿不遷官，而於待製閣名升二等。程大昌亦然，以龍圖直學士徑升本學士，尤非也。予任中書舍人日，已階太中，及以集英修撰出外，吏部不復為理年勞，凡十八年，始以待製得通議，殊可笑。蓋臺省之中，無復有老吏矣。","sortOrder":25},
  {"id":"s_work_dtbt_21_26","chapterId":"ch_work_dtbt_21","text":"曹子建七啟","sortOrder":26},
  {"id":"s_work_dtbt_21_27","chapterId":"ch_work_dtbt_21","text":"「原頭火燒淨兀兀，野雉畏鷹出復沒。將軍欲以巧伏人，盤馬彎弓惜不發。地形漸窄觀者多，雉驚弓滿勁箭加。衝人決起百餘尺，紅翎白鏃隨傾斜。將軍仰笑軍吏賀，五色離披馬前墮。」此韓昌黎雉帶箭詩，東坡嘗大字書之，以為絕妙。予讀曹子建七啟論羽獵之美雲：「人稠網密，地逼勢脅。」乃知韓公用意所來處。七啟又雲：「名穢我身，位累我躬。」與佛氏八大人覺經所書「心是惡源，形為罪藪」，皆修己正心之要語也。","sortOrder":27},
  {"id":"s_work_dtbt_21_28","chapterId":"ch_work_dtbt_21","text":"奸鬼為人禍","sortOrder":28},
  {"id":"s_work_dtbt_21_29","chapterId":"ch_work_dtbt_21","text":"晉景公疾病，求醫於秦，秦伯使醫緩為之，未至，公夢疾為二孺子，曰：「彼良醫也，懼傷我，焉逃之？」其一曰：「居肓之上，膏之下，若我何？」醫至，曰：「疾不可為也。」隋文帝以子秦孝王俊有疾，馳召名醫許智藏，俊夢亡妃崔氏泣曰：「本來相迎，如聞許智藏將至，其人當必相苦，奈何！」明夜復夢，曰：「吾得計矣，當入靈府中以避之。」及智藏至，診俊脈，曰：「疾已入心，不可救也。」二奸鬼之害人，如出一轍。近世許叔微家一婦人，夢二蒼頭，前者雲：「到也未？」後者應雲：「到也。」以手中物擊一下，遂魘。覺後心痛不可忍，叔微以神精丹餌之，痛止而愈。此事亦與上二者相似。","sortOrder":29},
  {"id":"s_work_dtbt_21_30","chapterId":"ch_work_dtbt_21","text":"監司待巡檢","sortOrder":30},
  {"id":"s_work_dtbt_21_31","chapterId":"ch_work_dtbt_21","text":"今監司巡歷郡邑，巡檢、尉必迎於本界首，公裳危立，使者從車內遣謁吏謝之，即揖而退，未嘗以客禮延之也。至有倨橫之人，責橋道不整，驅之車前，使徒步與卒伍齒者。予記張文定公所著縉紳舊聞中一事雲：「餘為江西轉運使，往虔州，巡檢殿直(今保義成忠郎。)康懷琪，乘舟於三十里相接，又欲送至大庾縣，遂與偕行。及至縣驛，驛正廳東西各有一房，予居其左，康處於右。日晚，命之同食，起行數百步，逼暮而退。夜聞康暴得疾，餘亟趨至康所，康已具舟將歸虔，須臾數人扶翼而下，餘策杖隨之。」觀此，則是使者與巡檢同驛而處，同席而食，至於步行送之登舟，今代未之見也。","sortOrder":31},
  {"id":"s_work_dtbt_21_32","chapterId":"ch_work_dtbt_21","text":"十二分野","sortOrder":32},
  {"id":"s_work_dtbt_21_33","chapterId":"ch_work_dtbt_21","text":"十二國分野，上屬二十八宿，其為義多不然，前輩固有論之者矣。其甚不可曉者，莫如晉天文志謂：「自危至奎為娵訾，於辰在亥，衞之分野也，屬幷州。」且衞本受封於河內商虛，後徙楚丘。河內乃冀州所部，漢屬司隸，其他邑皆在東郡，屬兗州，於幷州了不相幹，而幷州之下所列郡名，乃安定、天水、隴西、酒泉、張掖諸郡，自係涼州耳。又謂：「自畢至東井為實沈，於辰在申，魏之分野也，屬益州。」且魏分晉地，得河內、河東數十縣，於益州亦不相幹，而雍州為秦，其下乃列雲中、定襄、雁門、代、太原、上黨諸郡，蓋又自屬幷州及幽州耳。謬亂如此，而出於李淳風之手，豈非蔽於天而不知地乎！","sortOrder":33},
  {"id":"s_work_dtbt_21_34","chapterId":"ch_work_dtbt_21","text":"公孫五樓","sortOrder":34},
  {"id":"s_work_dtbt_21_35","chapterId":"ch_work_dtbt_21","text":"南燕慕容超嗣位之後，悉以國事付公孫五樓，燕業為衰。晉劉裕伐之，或曰：「燕人若塞大峴之險，堅壁清野，大軍深入，將不能自歸。」裕曰：「鮮卑貪婪，不知遠計，謂我不能持久，不過進據臨朐，退守廣固，必不能守險清野。」超聞有晉師，引羣臣會議，五樓曰：「吳兵輕果，利在速戰，不可爭鋒，宜據大峴，使不得入。各命守宰，依險自固，焚蕩資儲，芟除禾苗，使敵無所資。彼僑軍無食，可以坐製。若縱使入峴，出城逆戰，此下策也。」超不聽，裕過大峴，燕兵不出，喜形於色，遂一舉滅燕。觀五樓之計，正裕之所憚也。超平生信用五樓，獨於此不然，蓋天意也。五樓亦可謂智士，足與李左車比肩。後世奸妄擅國，以誤大事者多矣，無所謂五樓之智也。","sortOrder":35},
  {"id":"s_work_dtbt_21_36","chapterId":"ch_work_dtbt_21","text":"薦士稱字著年","sortOrder":36},
  {"id":"s_work_dtbt_21_37","chapterId":"ch_work_dtbt_21","text":"漢、魏以來諸公上表薦士，必首及本郡名，次著其年，又稱其字。如漢孔融薦禰衡表雲「處士平原禰衡，年二十四，字正平」，齊任昉為蕭揚州作薦士表雲「祕書丞琅邪王暕，年二十一，字思晦」，「前候官令東海王僧孺，年三十五，字僧孺」是也。唐以來乃無此式。","sortOrder":37},
  {"id":"s_work_dtbt_21_38","chapterId":"ch_work_dtbt_21","text":"兄弟邪正","sortOrder":38},
  {"id":"s_work_dtbt_21_39","chapterId":"ch_work_dtbt_21","text":"王安石引用小人，造作新法，而弟安國力非之。韓絳附會安石製置三司條例以得宰相，而弟維力爭之。曾布當元符、靖國之間，陰禍善類，而弟肇移書力勸之。兄弟邪正之不同如此。","sortOrder":39},
  {"id":"s_work_dtbt_21_40","chapterId":"ch_work_dtbt_21","text":"容齋續筆","sortOrder":40},
  {"id":"s_work_dtbt_22_1","chapterId":"ch_work_dtbt_22","text":"卷第四(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_22_2","chapterId":"ch_work_dtbt_22","text":"淮南守備","sortOrder":2},
  {"id":"s_work_dtbt_22_3","chapterId":"ch_work_dtbt_22","text":"周世宗舉中原百郡之兵，南征李景。當是時，周室方強，李氏政亂，以之討伐，雲若易然。而自二年之冬，訖五年之春，首尾四年，至於乘輿三駕，僅得江北。先是河中李守貞叛漢，遣其客朱元來唐求救，遂仕於唐。樞密使查文徽妻之以女。是時，請兵復諸州，即取舒、和。後以恃功偃蹇，唐將奪其兵，元怒而降周。景械其妻，欲戮之。文徽方執政，表乞其命，景批雲：「只斬朱元妻，不殺查家女。」竟斬於市。郭廷謂不能守濠州，以家在江南，恐為唐所種族，遣使詣金陵稟命，然後出降。則知周師所以久者，景法度猶存，尚能製將帥死命故也。紹興之季，虜騎犯淮，逾月之間，十四郡悉陷。予親見沿淮諸郡守，盡掃官庫儲積，分寓京口，雲預被旨許令移治。是乃平時無虞，則受極邊之賞，一有緩急，委而去之，寇退則反，了無分毫絓於吏議，豈復肯以固守為心也哉？","sortOrder":3},
  {"id":"s_work_dtbt_22_4","chapterId":"ch_work_dtbt_22","text":"周世宗","sortOrder":4},
  {"id":"s_work_dtbt_22_5","chapterId":"ch_work_dtbt_22","text":"周世宗英毅雄傑，以衰亂之世，區區五六年間，威武之聲，震懾夷夏，可謂一時賢主，而享年不及四十，身沒半歲，國隨以亡。固天方授宋，使之驅除。然考其行事，失於好殺，用法太嚴，羣臣職事，小有不舉，往往置之極刑，雖素有才幹聲名，無所開宥，此其所短也。薛居正舊史紀載翰林醫官馬道元進狀，訴壽州界被賊殺其子，獲正賊見在宿州，本州不為勘斷。帝大怒，遣竇儀乘馹往按之。及獄成，坐族死者二十四人。儀奉辭之日，帝旨甚峻，故儀之用刑，傷於深刻，知州趙礪坐除名。此事本只馬氏子一人遭殺，何至於族誅二十四家，其他可以類推矣。太祖實錄竇儀傳有此事，史臣但歸咎於儀雲。","sortOrder":5},
  {"id":"s_work_dtbt_22_6","chapterId":"ch_work_dtbt_22","text":"竇貞固","sortOrder":6},
  {"id":"s_work_dtbt_22_7","chapterId":"ch_work_dtbt_22","text":"竇貞固，漢隱帝相也。周世罷政，以司徒就第。後范質用此官在中書，乃歸洛陽。常與編戶課役，貞固不能堪，訴於留守向拱，拱不聽。熙寧初，富韓公為相，神宗嘗對大臣稱知河南府李中師治狀。公以中師厚結中人，因對曰：「陛下何從知之？」中師銜其沮己，及再尹河南，富公已老，乃籍其戶，令出免役錢，與富民等。乃知君子失勢之時，小人得易而侮之，如向拱、李中師輩，固不乏也。","sortOrder":7},
  {"id":"s_work_dtbt_22_8","chapterId":"ch_work_dtbt_22","text":"鄭　權","sortOrder":8},
  {"id":"s_work_dtbt_22_9","chapterId":"ch_work_dtbt_22","text":"唐穆宗時，以工部尚書鄭權為嶺南節度使，卿大夫相率為詩送之。韓文公作序，言：「權功德可稱道。家屬百人，無數畝之宅，僦屋以居，可謂貴而能貧，為仁者不富之效也。」舊唐史權傳雲：「權在京師，以家人數多，奉入不足，求為鎮，有中人之助，南海多珍貨，權頗積聚以遺之，大為朝士所嗤。」又薛廷老傳雲：「鄭權因鄭註得廣州節度，權至鎮，盡以公家珍寶赴京師，以酬恩地。廷老以右拾遺上疏，請按權罪，中人由是切齒。」然則其為人，乃貪邪之士爾！韓公以為仁者何邪？","sortOrder":9},
  {"id":"s_work_dtbt_22_10","chapterId":"ch_work_dtbt_22","text":"黨錮牽連之賢","sortOrder":10},
  {"id":"s_work_dtbt_22_11","chapterId":"ch_work_dtbt_22","text":"漢黨錮之禍，知名賢士死者以百數，海內塗炭，其名跡章章者，並載於史。而一時牽連獲罪，甘心以受刑誅，皆節義之士，而位行不顯，僅能附見者甚多。李膺死，門生故吏並被禁錮。侍御史景毅之子，為膺門徒，未有錄牒，不及於譴。毅慨然曰：「本謂膺賢，遣子師之，豈可以漏籍苟安！」遂自表免歸。高城人巴肅被收，自載詣縣，縣令欲解印綬與俱去，肅不可。范滂在征羌，詔下急捕。督郵吳導至縣，抱詔書，閉傳舍，伏牀而泣。滂自詣獄，縣令郭揖大驚，出解印綬，引與俱亡。滂曰：「滂死則禍塞，何敢以罪累君！」張儉亡命，困迫遁走，所至，破家相容。其所經歷，伏重誅者以十數。復流轉東萊，上李篤家。外黃令毛欽操兵到門，篤謂曰：「張儉亡非其罪，縱儉可得，寧忍執之乎？」欽撫篤曰：「蘧伯玉恥獨為君子，足下如何自專仁義？」嘆息而去。儉得免。後數年，上祿長和海上言：「黨人錮及五族，非經常之法。」由是自從祖以下，皆得解釋。此數君子之賢如是，東漢尚名節，斯其驗歟？","sortOrder":11},
  {"id":"s_work_dtbt_22_12","chapterId":"ch_work_dtbt_22","text":"漢代文書式","sortOrder":12},
  {"id":"s_work_dtbt_22_13","chapterId":"ch_work_dtbt_22","text":"漢代文書，臣下奏朝廷，朝廷下郡國，有漢官典儀、漢舊儀等所載，然不若金石刻所著見者為明白。史晨祠孔廟碑，前雲：「建寧二年三月癸卯朔七日己酉，魯相臣晨，長史臣謙頓首死罪上尚書，臣晨頓首頓首，死罪死罪。」末雲：「臣晨誠惶誠恐，頓首頓首，死罪死罪上尚書。」副言太傅、太尉、司徒、司空、大司農府。樊毅復華下民租碑，前後與此同。無極山碑：「光和四年某月辛卯朔廿二日壬子，太常臣耽、丞敏頓首上尚書。」末雲：「臣耽愚戇，頓首頓首上尚書。製曰：可。大尚(讀為太常。)承書從事，某月十七日丁丑，尚書令忠奏雒陽宮。光和四年八月辛酉朔十七日丁丑，尚書令忠下。」又雲：「光和四年八月辛酉朔十七日丁丑，太常耽、丞敏下。」常山相孔廟碑，前雲：「司徒臣雄，司空臣戒，稽首言。」末雲：「臣雄、臣戒愚戇，誠惶誠恐，頓首頓首，死罪死罪，臣稽首以聞。製曰：可。元嘉三年三月廿七日壬寅，奏雒陽宮。元嘉三年三月丙子朔廿七日壬寅，司徒雄、司空戒下魯相。」又雲：「永興元年六月甲辰朔十八日辛酉，魯相平，行長史事、卞守長擅，叩頭死罪，敢言之司徒、司空府。」末雲：「平惶恐叩頭，死罪死罪，上司空府。」此碑有三公奏天子，朝廷下郡國，郡國上公府三式，始末詳備。文惠公隸釋有之。無極山祠事，以丁丑日奏雒陽宮，是日下太常，孔廟事，以壬寅日奏雒陽宮，亦以是日下魯相，又以見漢世文書之不滯留也。","sortOrder":13},
  {"id":"s_work_dtbt_22_14","chapterId":"ch_work_dtbt_22","text":"資治通鑑","sortOrder":14},
  {"id":"s_work_dtbt_22_15","chapterId":"ch_work_dtbt_22","text":"司馬公修資治通鑑，辟范夢得為官屬，嘗以手帖論纘述之要，大抵欲如左傳敍事之體。又雲：「凡年號皆以後來者為定。如武德元年，則從正月，便為唐高祖，更不稱隋義寧二年。梁開平元年正月，便不稱唐天祐四年。」故此書用以為法。然究其所窮，頗有窒而不通之處。公意正以春秋定公為例，於未即位，即書正月為其元年。然昭公以去年十二月薨，則次年之事，不得復係於昭。故定雖未立，自當追書。兼經文至簡，不過一二十字，一覽可以了解。若通鑑則不侔，隋煬帝大業十三年，便以為恭皇帝上，直至下卷之末，恭帝立，始改義寧，後一卷，則為唐高祖。蓋凡涉歷三卷，而煬帝固存，方書其在江都時事。明皇後卷之首，標為肅宗至德元載，至一卷之半，方書太子即位。代宗下卷雲：「上方勵精求治，不次用人。」乃是德宗也。莊宗同光四年，便係於天成，以為明宗，而卷內書命李嗣源討鄴，至次卷首，莊宗方殂。潞王清泰三年，便標為晉高祖，而卷內書石敬瑭反，至卷末始為晉天福。凡此之類，殊費分說。此外，如晉、宋諸胡僭國，所封建王公，及除拜卿相，纖悉必書，有至二百字者。又如西秦丞相南川宣公出連乞都卒，魏都坐大官章安侯封懿、天部大人白馬文正公崔宏、宜都文成王穆觀、鎮遠將軍平舒侯燕鳳、平昌宣王和其奴卒，皆無關於社稷治亂。而周勃薨，乃不書。及書漢章帝行幸長安，進幸槐里、岐山，又幸長平，御池陽宮，東至高陵，十二月丁亥還宮；又乙未幸東阿，北登太行山，至天井關，夏四月乙卯還宮。又書魏主七月戊子如魚池，登青岡原，甲午還宮；八月己亥如瀰澤，甲寅登牛頭山，甲子還宮。如此行役，無歲無之，皆可省也。","sortOrder":15},
  {"id":"s_work_dtbt_22_16","chapterId":"ch_work_dtbt_22","text":"弱小不量力","sortOrder":16},
  {"id":"s_work_dtbt_22_17","chapterId":"ch_work_dtbt_22","text":"楚莊王伐蕭，蕭人囚熊相宜僚及公子丙。王曰：「勿殺，吾退。」蕭人殺之，王怒，遂滅蕭。楚伐莒，莒人囚楚公子平。楚人曰：「勿殺，吾歸而俘。」莒人殺之，楚師圍莒，莒潰，遂入鄆。齊侯伐魯，圍龍，頃公之嬖人盧蒲就魁門焉，龍人囚之。齊侯曰：「勿殺，吾與而盟，無入而封。」弗聽，殺而膊諸城上。齊遂取龍。夫以齊、楚之大，而莒一小國，蕭一附庸，龍一邊邑，方受攻之際，幸能囚執其人，強敵許以勿殺而退師，乃不度德量力，致怨於彼，至於亡滅，可謂失計。傳稱子產善相小國，使當此時，必有以處之矣。","sortOrder":17},
  {"id":"s_work_dtbt_22_18","chapterId":"ch_work_dtbt_22","text":"田橫呂布","sortOrder":18},
  {"id":"s_work_dtbt_22_19","chapterId":"ch_work_dtbt_22","text":"田橫既敗，竄居海島中。高帝遣使召之，曰：「橫來，大者王，小者乃侯耳。」橫遂與二客詣雒陽。將至，謂客曰：「橫始與漢王俱南面稱孤，今漢王為天子，而橫乃為亡虜，北面事之，其愧固已甚矣！」即自剄。橫不顧王侯之爵，視死如歸，故漢祖流涕稱其賢，班固以為雄才。韓退之道出其墓下，為文以弔曰：「自古死者非一，夫子至今有耿光。」其英烈凜然，至今猶有生氣也。呂布為曹操所縛，將死之際，乃語操曰：「明公之所患，不過於布，今已服矣。令布將騎，明公將步，天下不足定也。」操竟殺之。布之材未必在橫下，而欲忍恥事仇。故東坡詩曰：「猶勝白門窮呂布，欲將鞍馬事曹瞞。」蓋笑之也。劉守光以燕敗，為晉王所擒，既知不免，猶呼曰：「王將復唐室以成霸業，何不赦臣使自效？」此又庸奴下才，無足責者。","sortOrder":19},
  {"id":"s_work_dtbt_22_20","chapterId":"ch_work_dtbt_22","text":"中山宜陽","sortOrder":20},
  {"id":"s_work_dtbt_22_21","chapterId":"ch_work_dtbt_22","text":"戰國事雜出於諸書，故有不可考信者。魏文侯使樂羊伐中山，克之，以封其子。故任座雲：「君得中山不以封君之弟，而以封君之子。」翟璜雲：「中山已拔，無使守之，臣進李克。」而趙世家書武靈王以中山負齊之強，侵暴其地，銳欲報之，至於變胡服，習騎射，累年乃與齊、燕共滅之，遷其王於膚施。此去魏文侯時已百年，中山不應既亡而復存，且膚施屬上郡，本魏地，為秦所取，非趙可得而置他人，誠不可曉。惟樂毅傳雲：「魏取中山，後中山復國，趙復滅之。」史記六國表：「威烈王十二年，中山武公初立。」徐廣曰：「周定王之孫，西周桓公之子。」此尤不然。宜陽於韓為大縣，顯王三十四年，秦伐韓，拔之。故屈宜臼雲：前年秦拔宜陽。正是昭侯時。歷宣惠王、襄王，而秦甘茂又拔宜陽，相去幾三十年，得非韓嘗失此邑，既而復取之乎？","sortOrder":21},
  {"id":"s_work_dtbt_22_22","chapterId":"ch_work_dtbt_22","text":"相六畜","sortOrder":22},
  {"id":"s_work_dtbt_22_23","chapterId":"ch_work_dtbt_22","text":"莊子載徐無鬼見魏武侯，告之以相狗、馬。荀子論堅白同異雲：「曾不如好相鷄、狗之可以為名也。」史記褚先生於日者傳後雲：「黃直，丈夫也，陳君夫，婦人也，以相馬立名天下。留長孺以相彘立名。滎陽褚氏以相牛立名。皆有高世絕人之風。」今時相馬者間有之，相牛者殆絕，所謂鷄、狗、彘者，不復聞之矣。劉向七略相六畜三十八卷，謂骨法之度數，今無一存。","sortOrder":23},
  {"id":"s_work_dtbt_22_24","chapterId":"ch_work_dtbt_22","text":"卜筮不同","sortOrder":24},
  {"id":"s_work_dtbt_22_25","chapterId":"ch_work_dtbt_22","text":"洪範七稽疑，擇建立卜筮人，有「龜從，筮逆」之說。禮記：「卜筮不相襲。」謂卜不吉，則又筮，筮不吉，則又卜，以為瀆龜筴。左傳晉獻公欲以驪姬為夫人，卜之不吉，筮之吉。公曰：「從筮。」卜人曰：「筮短龜長，不如從長。」魯穆薑徙居東宮，筮之，遇艮之八。史曰：「是謂艮之隨。」杜預註雲：「周禮大卜掌三易，雜用連山、歸藏，二易皆以七、八為占，故言遇艮之八。史疑古易遇八為不利，故更以周易占，變爻得隨卦也。」漢武帝時，聚會占家問之，某日可取婦乎？五行家曰：可。堪輿家曰：不可。建除家曰：不吉。叢辰家曰：大凶。曆家曰：小凶。天人家曰：小吉。太一家曰：大吉。辯訟不決，以狀聞。製曰：「避諸死忌，以五行為主。」則曆卜諸家，自古蓋不同矣。唐呂才作廣濟陰陽百忌曆，世多用之。近又有三曆會同集，蒐羅詳盡。姑以擇日一事論之，一年三百六十日，若泥而不通，殆無一日可用也。","sortOrder":25},
  {"id":"s_work_dtbt_22_26","chapterId":"ch_work_dtbt_22","text":"日　者","sortOrder":26},
  {"id":"s_work_dtbt_22_27","chapterId":"ch_work_dtbt_22","text":"墨子書貴義篇雲：「子墨子北之齊，遇日者。日者曰：『帝以今日殺黑龍於北方，而先生之色黑，不可以北。』子墨子不聽，遂北，至淄水，不遂而反。日者曰：『我謂先生不可以北。』子墨子曰：『南之人不得北，北之人不得南，其色有黑者，有白者，何故皆不遂也。且帝以甲乙殺青龍於東方，以丙丁殺赤龍於南方，以庚辛殺白龍於西方，以壬癸殺黑龍於北方，若子之言，不可用也。』」史記作日者列傳，蓋本於此。徐廣曰：「古人占候卜筮，通謂之日者。」如以五行所直之日而殺其方龍，不知其旨安在，亦可謂怪矣。","sortOrder":27},
  {"id":"s_work_dtbt_22_28","chapterId":"ch_work_dtbt_22","text":"柳子厚黨叔文","sortOrder":28},
  {"id":"s_work_dtbt_22_29","chapterId":"ch_work_dtbt_22","text":"柳子厚、劉夢得，皆坐王叔文黨廢黜。劉頗飾非解謗，而柳獨不然。其答許孟容書雲：「早歲與負罪者親善，始奇其能，謂可以共立仁義，裨教化。暴起領事，人所不信，射利求進者，百不一得，一旦快意，更恣怨讟，詆訶萬狀，盡為敵仇。」及為叔文母劉夫人墓銘，極其稱誦，謂：「叔文堅明直亮，有文武之用。待詔禁中，道合儲後。獻可替否，有康弼調護之勤。訏謨定命，有扶翼經緯之績。將明出納，有彌綸通變之勞。內贊謨畫，不廢其位。利安之道，將施於人。而夫人終於堂，知道之士，為蒼生惜焉！」其語如此。夢得自作傳雲：「順宗即位時，有寒儁王叔文以善弈棋得通籍博望，因間隙得言及時事，上大奇之。叔文自言猛之後，有遠祖風，唯呂溫、李景儉、柳宗元以為信。然三子皆與予厚善，日夕過，言其能。叔文實工言治道，能以口辯移人。既得用，其所施為，人不以為當。上素被疾，詔下內禪，宮掖事祕，功歸貴臣，於是叔文貶死。」韓退之於兩人為執友，至修順宗實錄，直書其事雲：「叔文密結有當時名欲僥倖而速進者劉禹錫、柳宗元等十數人，定為死交，蹤跡詭祕。既得志，劉、柳主謀議唱和，采聽外事。及敗，其黨皆斥逐。」此論切當，雖朋友之義，不能以少蔽也。","sortOrder":29},
  {"id":"s_work_dtbt_22_30","chapterId":"ch_work_dtbt_22","text":"漢武心術","sortOrder":30},
  {"id":"s_work_dtbt_22_31","chapterId":"ch_work_dtbt_22","text":"史記龜策傳：「今上即位，博開蓺能之路，悉延百端之學，通一技之士鹹得自效。數年之間，太卜大集。會上欲擊匈奴，西攘大宛，南收百越，卜筮至預見表象，先圖其利。及猛將推鋒執節，獲勝於彼，而蓍龜時日亦有力於此。上尤加意，賞賜至或數千萬。如丘子明之屬，富溢貴寵，傾於朝廷。至以卜筮射蠱道，巫蠱時或頗中。素有眦睚不快，因公行誅，恣意所傷，以破族滅門者，不可勝數。百僚蕩恐，皆曰龜策能言。後事覺奸窮，亦誅三族。」漢書音義，以為史遷沒後十篇闕，有錄無書。元、成之間，褚先生補闕，言辭鄙陋，日者、龜策列傳在焉。故後人頗薄其書。然此卷首言「今上即位」，則是史遷指武帝，其載巫蠱之寃如是。今之論議者，略不及之。資治通鑑亦棄不取，使丘子明之惡，不復著見。此由武帝博采異端，馴致斯禍。儻心術趨於正當，不如是之酷也。","sortOrder":31},
  {"id":"s_work_dtbt_22_32","chapterId":"ch_work_dtbt_22","text":"禁天高之稱","sortOrder":32},
  {"id":"s_work_dtbt_22_33","chapterId":"ch_work_dtbt_22","text":"周宣帝自稱天元皇帝，不聽人有天、高、上、大之稱。官名有犯，皆改之。改姓高者為薑，九族稱高祖者為長祖。政和中，禁中外不許以龍、天、君、玉、帝、上、聖、皇等為名字。於是毛友龍但名友；葉天將但名將；樂天作但名作；句龍如淵但名句如淵；衞上達賜名仲達；葛君仲改為師仲；方天任為大任；方天若為元若；餘聖求為應求；周綱字君舉，改曰元舉；程振字伯玉，改曰伯起；程瑀亦字伯玉，改曰伯禹；張讀字聖行，改曰彥行。蓋蔡京當國，遏絕史學，故無有知周事者。宣和七年七月，手詔以昨臣僚建請，士庶名字有犯天、玉、君、聖及主字者悉禁，既非上帝名諱，又無經據，諂佞不根，貽譏後世，罷之。","sortOrder":33},
  {"id":"s_work_dtbt_22_34","chapterId":"ch_work_dtbt_22","text":"宣和冗官","sortOrder":34},
  {"id":"s_work_dtbt_22_35","chapterId":"ch_work_dtbt_22","text":"宣和元年，蔡京將去相位，臣僚方疏官僚冗濫之敝，大略雲：「自去年七月至今年三月，遷官論賞者五千餘人。如：辰州招弓弩手，而樞密院支差房推恩者八十四人；兗州升為府，而三省兵房推恩者三百三十六人。至有入仕纔二年，而轉十官者。今吏部兩選朝奉大夫至朝請大夫六百五十五員，橫行右武大夫至通侍二百二十九員，修武郎至武功大夫六千九百九十一員，小使臣二萬三千七百餘員，選人一萬六千五百餘員。吏員猥冗，差註不行。」詔三省樞密院令遵守成法。然此詔以四月庚子下，而明日辛丑以賞西陲誅討之功，太師蔡京，宰相餘深、王黼，知樞密院鄧洵武，各與一子官，執政皆遷秩。天子命令如是即日廢格之，京之罪惡至矣！","sortOrder":35},
  {"id":"s_work_dtbt_22_36","chapterId":"ch_work_dtbt_22","text":"容齋續筆","sortOrder":36},
  {"id":"s_work_dtbt_23_1","chapterId":"ch_work_dtbt_23","text":"卷第五(十三則)","sortOrder":1},
  {"id":"s_work_dtbt_23_2","chapterId":"ch_work_dtbt_23","text":"秦隋之惡","sortOrder":2},
  {"id":"s_work_dtbt_23_3","chapterId":"ch_work_dtbt_23","text":"自三代訖於五季，為天下君而得罪於民，為萬世所麾斥者，莫若秦與隋，豈二氏之惡浮於桀、紂哉？蓋秦之後即為漢，隋之後即為唐，皆享國久長。一時論議之臣，指引前世，必首及之，信而有徵，是以其事暴白於方來，彌遠彌彰而不可蓋也。嘗試裒舉之。","sortOrder":3},
  {"id":"s_work_dtbt_23_4","chapterId":"ch_work_dtbt_23","text":"張耳曰：「秦為亂政虐刑，殘滅天下，北為長城之役，南有五嶺之戍，外內騷動，頭會箕斂，重以苛法，使父子不相聊。」張良曰：「秦為無道，故沛公得入關，為天下除殘去賊。」陸賈曰：「秦任刑法不變，卒滅嬴氏。」王衞尉曰：「秦以不聞其過亡天下。」張釋之曰：「秦任刀筆之吏，爭以亟疾苛察相高，以故不聞其過，陵夷至於二世，天下土崩。」賈山借秦為喻曰：「為宮室之麗，使其後世曾不得聚廬而託處，為馳道之麗，後世不得邪徑而託足，為葬埋之麗，後世不得蓬顆而託葬。以千八百國之民自養，力罷不能勝其役，財盡不能勝其求，人與之為怨，家與之為讎，天下已壞而弗自知，身死纔數月耳，而宗廟滅絕。」賈誼曰：「商君遺禮誼，棄仁恩，幷心於進取，行之二歲，秦俗日敗，滅四維而不張，君臣乖亂，六親殃戮，萬民離叛，社稷為虛。」又曰：「使趙高傅胡亥，而教之獄。今日即位，明日射人，其視殺人若刈草菅然。置天下於法令刑罰，德澤亡一有，而怨毒盈於世，下憎惡之如仇讎。」鼂錯曰：「秦發卒戍邊，有萬死之害，而亡銖兩之報。天下明知禍烈及己也，陳勝首倡，天下從之如流水。」又曰：「任不肖而信讒賊，民力罷盡，矜奮自賢，法令煩憯，刑罰暴酷，親疏皆危，外內鹹怨，絕祀亡世。」董仲舒曰：「秦重禁文學，不得挾書，棄捐禮誼而惡聞之。其心欲盡滅先聖之道，而顓為自恣苟簡之治。自古以來，未嘗有以亂濟亂，大敗天下之民如秦者也。」又曰：「師申、商之法，行韓非之說，憎帝王之道，以貪狼為俗，賦斂亡度，竭民財力，羣盜並起，死者相望，而奸不息。」淮南王安曰：「秦使尉屠睢攻越，鑿渠通道，曠日引久，發謫戍以備之，往者莫反，亡逃相從，羣為盜賊。於是山東之難始興。」吾丘壽王曰：「秦廢王道，立私議，去仁恩而任刑戮，至於赭衣塞路，羣盜滿山。」主父偃曰：「秦任戰勝之威，功齊三代，務勝不休，暴兵露師，百姓靡敝，孤寡老弱，不能相養，死者相望，天下始叛。」徐樂曰：「秦之末世，民困而主不恤，下怨而上不知，俗已亂而政不修，陳涉之所以為資也。此之謂土崩。」嚴安曰：「秦一海內之政，壞諸侯之城，為知巧權利者進，篤厚忠正者退。法嚴令苛，意廣心逸。兵禍北結於胡，南掛於越，宿兵於無用之地，進而不得退，天下大畔，滅世絕祀。」司馬相如曰：「二世持身不謹，亡國失勢，信讒不寤，宗廟滅絕。」伍被曰：「秦為無道，百姓欲為亂者十室而五。使徐福入海，欲為亂者十室而六。使尉佗攻百越，欲為亂者十室而七。作阿房之宮，欲為亂者十室而八。」路溫舒曰：「秦有十失，其一尚存，治獄之吏是也。」賈捐之曰：「興兵遠攻，貪外虛內，天下潰畔，禍卒在於二世之末。」劉向曰：「始皇葬於驪山，下錮三泉，多殺宮人，生埋工匠，計以萬數，天下苦其役而反之。」梅福曰：「秦為無道，削仲尼之跡，絕周公之軌，禮壞樂崩，王道不通，張誹謗之網，以為漢驅除。」穀永曰：「秦所以二世十六年而亡者，養生泰奢，奉終泰厚也。」劉歆曰：「燔經書，殺儒士，設挾書之法，行是古之罪，道術由是遂滅。」凡漢人之論秦惡者如此。","sortOrder":4},
  {"id":"s_work_dtbt_23_5","chapterId":"ch_work_dtbt_23","text":"唐高祖曰：「隋氏以主驕臣諂亡天下。」孫伏伽曰：「隋以惡聞其過亡天下。」薛收傳：「秦王平洛陽，觀隋宮室，嘆曰：『煬帝無道，殫人力以事夸侈。』收曰：『後主奢虐是矜，死一夫之手，為後世笑。』」張元素曰：「自古未有如隋亂者，得非君自專、法日亂乎？造乾陽殿，伐木於豫章，一材之費，已數十萬工。乾陽畢功，隋人解體。」魏徵曰：「煬帝信虞世基，賊遍天下而不得聞。」又曰：「隋唯責不獻食，或供奉不精，為此無限，而至於亡。方其未亂，自謂必無亂，未亡，自謂必不亡。所以甲兵亟動，徭役不息。」又曰：「恃其富強，不虞後患，役萬物以自奉養，子女玉帛是求，宮室臺榭是飾。外示威重，內行險忌，上下相蒙，人不堪命，以致隕匹夫之手。」又曰：「文帝驕其諸子，使至夷滅。」馬周曰：「貯積者固有國之常，要當人有餘力而後收之，豈人勞而強斂之以資寇邪？隋貯洛口倉，而李密因之；積布帛東都，而王世充據之；西京府庫，亦為國家之用。」陳子昂曰：「煬帝恃四海之富，鑿渠決河，疲生人之力，中國之難起，身死人手，宗廟為墟。」楊相如曰：「煬帝自恃其強，不憂時政。言同堯、舜，跡如桀、紂，舉天下之大，一擲棄之。」吳兢曰：「煬帝驕矜自負，以為堯、舜莫己若，而諱亡憎諫。乃曰：『有諫我者，當時不殺，後必殺之。』自是謇諤之士去而不顧，外雖有變，朝臣鉗口，帝不知也。」柳宗元曰：「隋氏環四海以為鼎，跨九垠以為爐，爨以毒燎，煽以虐焰，沸涌灼爛，號呼騰蹈。」李珏曰：「隋文帝勞於小務，以疑待下，故二世而亡。」凡唐人之論隋惡者如此。","sortOrder":5},
  {"id":"s_work_dtbt_23_6","chapterId":"ch_work_dtbt_23","text":"漢唐二武","sortOrder":6},
  {"id":"s_work_dtbt_23_7","chapterId":"ch_work_dtbt_23","text":"東坡雲：「古之君子，必憂治世而危明主，明主有絕人之資，而治世無可畏之防。」美哉斯言！漢之武帝，唐之武後，不可謂不明，而巫蠱之禍，羅織之獄，天下塗炭，後妃公卿，交臂就戮，後世聞二武之名，則憎惡之。蔡確作詩，用郝甑山上元間事，宣仁謂以吾比武後；蘇轍用武帝奢侈窮兵虛耗海內為諫疏，哲宗謂至引漢武上方先朝。皆以之得罪。人君之立政，可不監茲！","sortOrder":7},
  {"id":"s_work_dtbt_23_8","chapterId":"ch_work_dtbt_23","text":"玉川子","sortOrder":8},
  {"id":"s_work_dtbt_23_9","chapterId":"ch_work_dtbt_23","text":"韓退之寄盧仝詩雲：「玉川先生洛城裏，破屋數間而已矣。一奴長鬚不裹頭，一婢赤腳老無齒。昨晚長鬚來下狀，隔牆惡少惡難似。每騎屋山下窺瞰，渾舍驚怕走折趾。立召賊曹呼五百，盡取鼠輩尸諸市。」夫奸盜固不義，然必有謂而發，非貪慕貨財，則挑暴子女。如玉川之貧，至於鄰僧乞米，隔牆居者豈不知之？若為色而動，窺見室家之好，是以一赤腳老婢隕命也，惡少可謂枉著一死。予讀韓詩至此，不覺失笑。仝集中有所思一篇，其略雲：「當時我醉美人家，美人顏色嬌如花。今日美人棄我去，青樓珠箔天之涯。夢中醉臥巫山雲，覺來淚滴湘江水。湘江兩岸花木深，美人不見愁人心。相思一夜梅花發，忽到窗前疑是君。」則其風味殊不淺，韓詩當亦含譏諷乎？","sortOrder":9},
  {"id":"s_work_dtbt_23_10","chapterId":"ch_work_dtbt_23","text":"銀青階","sortOrder":10},
  {"id":"s_work_dtbt_23_11","chapterId":"ch_work_dtbt_23","text":"唐自肅、代以後，賞人以官爵，久而浸濫，下至州郡胥吏軍班校伍，一命便帶銀青光祿大夫階，殆與無官者等。明宗長興二年，詔不得薦銀青階為州縣官，賤之至矣。晉天福中，中書舍人李詳上疏，以為十年以來，諸道職掌，皆許推恩，藩方薦論，動逾數百，乃至藏典書吏，優伶奴僕，初命則至銀青階，被服皆紫袍象笏，名器僭濫，貴賤不分。請自今節度州聽奏大將十人，他州止聽奏都押牙、都虞候、孔目官。從之。馮拯之父俊，當周太祖時，補安遠鎮將，以銀青光祿檢校太子賓客兼御史大夫。至本朝端拱中，拯登朝，遇郊恩始贈大理評事。予八世從祖師暢，暢子漢卿，卿子膺圖，在南唐時，皆得銀青階，至檢校尚書、祭酒。然樂平縣帖之，全稱姓名，其差徭正與里長等。元豐中，李清臣論官製，奏言：「國朝踵襲近代因循之弊，牙校有銀青光祿大夫階，卒長開國而有食邑。」蓋為此也。今除授蕃官，猶用此製。紹興二十八年，廣西經略司申安化三州蠻蒙全計等三百十八人進奉，乞補官勛，皆三班借差。三班差使，悉帶銀青祭酒，而等第加勛，文安公在西垣為之命詞。","sortOrder":11},
  {"id":"s_work_dtbt_23_12","chapterId":"ch_work_dtbt_23","text":"買馬牧馬","sortOrder":12},
  {"id":"s_work_dtbt_23_13","chapterId":"ch_work_dtbt_23","text":"國家買馬，南邊於邕管，西邊於岷、黎，皆置使提督，歲所綱發者蓋逾萬匹。使臣、將校得遷秩轉資，沿道數十州，驛程券食、圉薪芻之費，其數不貲，而江、淮之間，本非騎兵所能展奮，又三牙遇暑月，放牧於蘇、秀以就水草，亦為逐處之患。因讀五代舊史雲：「唐明宗問樞密使范延光內外馬數。對曰：『三萬五千匹。』帝嘆曰：『太祖在太原，騎軍不過七千。先皇自始至終，馬纔及萬。今有鐵馬如是，而不能使九州混一，是吾養士練將之不至也。』延光奏曰：『國家養馬太多，計一騎士之費可贍步軍五人，三萬五千騎，抵十五萬步軍，既無所施，虛耗國力。』帝曰：『誠如卿言。肥騎士而瘠吾民，民何負哉？』」明宗出於蕃戎，猶能以愛民為念。李克用父子以馬上立國製勝，然所蓄只如此。今蓋數倍之矣。尺寸之功不建，可不惜哉！且明宗都洛陽，正臨中州，尚以為騎士無所施。然則今雖純用步卒，亦未為失計也。","sortOrder":13},
  {"id":"s_work_dtbt_23_14","chapterId":"ch_work_dtbt_23","text":"杜詩用字","sortOrder":14},
  {"id":"s_work_dtbt_23_15","chapterId":"ch_work_dtbt_23","text":"律詩用自字、相字、共字、獨字、誰字之類，皆是實字，及彼我所稱，當以為對，故杜老未嘗不然。今略紀其句於此：「徑石相縈帶，川雲自去留。」「山花相映發，水鳥自孤飛。」「衰顏聊自哂，小吏最相輕。」「高城秋自落，雜樹晚相迷。」「百鳥各相命，孤雲無自心。」「勝地初相引，徐行得自娛。」「雲裏相呼疾，沙邊自宿稀。」「暗飛螢自照，水宿鳥相呼。」「猿掛時相學，鷗行炯自如。」「自吟詩送老，相勸酒開顏。」「俱飛蛺蝶元相逐，並蒂芙蓉本自雙。」「自去自來堂上燕，相親相近水中鷗。」「此時對雪遙相憶，送客逢春可自由。」「梅花欲開不自覺，棣萼一別永相望。」「桃花氣暖眼自醉，春渚日落夢相牽。」此以自字對相字也。「自須開竹徑，誰道避雲蘿。」「自笑燈前舞，誰憐醉後歌。」「死去憑誰報，歸來始自憐。」「哀歌時自短，醉舞為誰醒。」「離別人誰在，經過老自休。」「永夜角聲悲自語，中天月色好誰看。」此以自字對誰字也。「野人時獨往，雲木曉相參。」「正月鶯相見，非時鳥共聞。」「江上形容吾獨老，天涯風俗病相親。」「縱飲久判人共棄，懶朝真與世相違。」「此日此時人共得，一談一笑俗相看。」此以共字、獨字對相字也。","sortOrder":15},
  {"id":"s_work_dtbt_23_16","chapterId":"ch_work_dtbt_23","text":"唐虞象刑","sortOrder":16},
  {"id":"s_work_dtbt_23_17","chapterId":"ch_work_dtbt_23","text":"虞書：「象刑惟明。」象者法也。漢文帝詔，始雲：「有虞氏之時，畫衣冠、異章服以為戮，而民弗犯。」武帝詔亦雲：「唐虞畫象，而民不犯。」白虎通雲：「畫象者，其衣服象五刑也。犯墨者蒙巾，犯劓者赭著其衣，犯髕者以墨蒙其髕，犯宮者屝，屝，草屨也，大辟者布衣無領。」其說雖未必然，揚雄法言，「唐、虞象刑惟明」，說者引前詔以證，然則唐、虞之所以齊民，禮義榮辱而已，不專於刑也。秦之末年，赭衣半道，而奸不息。國朝之製，減死一等及胥吏兵卒配徒者，湼其面而刺之，本以示辱，且使人望而識之耳。久而益多，每郡牢城營，其額常溢，殆至十餘萬，兇盜處之恬然。蓋習熟而無所恥也。羅隱讒書雲：「九人冠而一人髽，則髽者慕而冠者勝，九人髽而一人冠，則冠者慕而髽者勝。」正謂是歟？老子曰：「民常不畏死，奈何以死懼之。若使民常畏死，則為惡者吾得執而殺之，孰敢？」可謂至言。荀卿謂象刑為治古不然。亦正論也。","sortOrder":17},
  {"id":"s_work_dtbt_23_18","chapterId":"ch_work_dtbt_23","text":"崔常牛李","sortOrder":18},
  {"id":"s_work_dtbt_23_19","chapterId":"ch_work_dtbt_23","text":"士大夫一時論議，自各有是非，不當一一校其平生賢否也。常為宰相，唐德宗初立，議羣臣喪服，以為遺詔雲「天下吏人三日釋服」，古者卿大夫從君而服，皇帝二十七日而除，在朝羣臣亦當如之。祐甫以為遺詔無朝臣、庶人之別，凡百執事，孰非吏人？皆應三日釋服。相與力爭，不能堪，奏貶祐甫。已而坐欺罔貶，祐甫代之。議者以祐甫之賢，遠出右，故不復評其事。然揆之以理，則之言為然。李德裕為西川節度使，吐蕃維州副使悉怛謀請降。德裕遣兵據其城，具奏其狀，欲因是搗西戎腹心。百官議皆請如德裕策。宰相牛僧孺曰：「吐蕃之境，四面各萬里，失一維州未能損其勢。比來修好，約罷戍兵，彼若來責失信，上平涼坂，萬騎綴回中，怒氣直辭，不三日至鹹陽橋。此時西南數千里外得百維州，何所用之？」文宗以為然，詔以城歸吐蕃。由是德裕怨僧孺益深。議者亦以德裕賢於僧孺，鹹謂牛、李私憾不釋，僧孺嫉德裕之功，故沮其事。然以今觀之，則僧孺為得，司馬溫公斷之以義利，兩人曲直始分。","sortOrder":19},
  {"id":"s_work_dtbt_23_20","chapterId":"ch_work_dtbt_23","text":"盜賊怨官吏","sortOrder":20},
  {"id":"s_work_dtbt_23_21","chapterId":"ch_work_dtbt_23","text":"陳勝初起兵，諸郡縣苦秦吏暴，爭殺其長吏以應勝。晉安帝時，孫恩亂東土，所至醢諸縣令以食其妻子，不肯食者輒支解之。隋大業末，羣盜蜂起，得隋官及士族子弟皆殺之。黃巢陷京師，其徒各出大掠，殺人滿街，巢不能禁，尤憎官吏，得者皆殺之。宣和中，方臘為亂，陷數州，凡得官吏，必斷臠支體，探其肺腸，或熬以膏油，叢鏑亂射，備盡楚毒，以償怨心。杭卒陳通為逆，每獲一命官，亦即梟斬。豈非貪殘者為吏，倚勢虐民，比屋抱恨，思一有所出久矣，故乘時肆志，人自為怒乎？","sortOrder":21},
  {"id":"s_work_dtbt_23_22","chapterId":"ch_work_dtbt_23","text":"作詩先賦韻","sortOrder":22},
  {"id":"s_work_dtbt_23_23","chapterId":"ch_work_dtbt_23","text":"南朝人作詩多先賦韻，如梁武帝華光殿宴飲連句，沈約賦韻，曹景宗不得韻，啟求之，乃得競病兩字之類是也。予家有陳後主文集十卷，載王師獻捷，賀樂文思，預席羣僚，各賦一字，仍成韻，上得盛病柄令橫映敻幷鏡慶十字，宴宣猷堂，得迮格白赫易夕擲斥坼啞十字，幸舍人省，得日謐一瑟畢訖橘質帙實十字。如此者凡數十篇。今人無此格也。","sortOrder":23},
  {"id":"s_work_dtbt_23_24","chapterId":"ch_work_dtbt_23","text":"後妃命數","sortOrder":24},
  {"id":"s_work_dtbt_23_25","chapterId":"ch_work_dtbt_23","text":"左傳所載鄭文公之子十餘人，其母皆貴冑，而子多不得其死，惟賤妾燕姞生穆公，獨繼父有國，子孫蕃衍盛大，與鄭存亡。薄姬入漢王宮，歲餘不得幸，其所善管夫人、趙子兒先幸漢王，為言其故，王即召幸之，歲中生文帝，自有子後希見。及呂後幽諸幸姬不得出宮，而薄氏以希見故，得從子之代，為代太後。終之承漢大業者，文帝也。景帝召程姬，程姬有所避不願進，而飭侍者唐兒使夜往，上醉不知而幸之，遂有身，生長沙王發。以母微無寵，故王卑濕貧國。漢之宗室十有餘萬人，而中興炎祚，成四百年之基者，發之五世孫光武也。元帝為太子，所愛司馬良娣死，怒諸娣妾，莫得進見。宣帝令皇後擇後宮家人子五人，虞侍太子。後令旁長御問所欲，太子殊無意於五人者，不得已於皇後，強應曰：「此中一人可。」乃王政君也。一幸有身，生成帝，自有子後，希復進見。然歷漢四世，為天下母六十餘載。觀此四後妃者，可謂承恩有限，而光華啟佑，與同輩遼絕，政君遂為先漢之禍。天之所命，其亦各有數乎？徽宗皇帝有子三十人，唯高宗皇帝再復大業。顯仁皇後在宮掖時，亦不肯與同列爭進，甚類薄太後雲。","sortOrder":25},
  {"id":"s_work_dtbt_23_26","chapterId":"ch_work_dtbt_23","text":"公為尊稱","sortOrder":26},
  {"id":"s_work_dtbt_23_27","chapterId":"ch_work_dtbt_23","text":"柳子厚房公銘陰曰：「天子之三公稱公，王者之後稱公，諸侯之入為王卿士亦曰公，尊其道而師之稱曰公。古之人通謂年之長者曰公。而大臣罕能以姓配公者，唐之最著者曰房公。」東坡墨君堂記雲：「凡人相與稱呼者，貴之則曰公。」范曄漢史：「惟三公乃以姓配之，未嘗或紊。」如鄧禹稱鄧公，吳漢稱吳公，伏公湛、宋公宏、牟公融、袁公安、李公固、陳公寵、橋公玄、劉公寵、崔公烈、胡公廣、王公龔、楊公彪、荀公爽、皇甫公嵩、曹公操是也。三國亦有諸葛公、司馬公、顧公、張公之目。其在本朝，唯韓公、富公、范公、歐陽公、司馬公、蘇公為最著也。","sortOrder":27},
  {"id":"s_work_dtbt_23_28","chapterId":"ch_work_dtbt_23","text":"臺城少城","sortOrder":28},
  {"id":"s_work_dtbt_23_29","chapterId":"ch_work_dtbt_23","text":"晉宋間，謂朝廷禁省為臺，故稱禁城為臺城，官軍為臺軍，使者為臺使，卿士為臺官，法令為臺格。需科則曰臺有求須，調發則曰臺所遣兵。劉夢得賦金陵五詠，故有臺城一篇。今人於他處指言建康為臺城，則非也。晉益州刺史治大城，蜀郡太守治少城，皆在成都，猶雲大城、小城耳。杜子美在蜀日，賦詩故有「東望少城」之句。今人於他處指成都為少城，則非也。","sortOrder":29},
  {"id":"s_work_dtbt_23_30","chapterId":"ch_work_dtbt_23","text":"容齋三筆","sortOrder":30},
  {"id":"s_work_dtbt_24_1","chapterId":"ch_work_dtbt_24","text":"卷第六(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_24_2","chapterId":"ch_work_dtbt_24","text":"蕨萁養人","sortOrder":2},
  {"id":"s_work_dtbt_24_3","chapterId":"ch_work_dtbt_24","text":"自古凶年饑歲，民無以食，往往隨所值以為命，如范蠡謂吳人就蒲蠃於東海之濱；蘇子卿掘野鼠所去草實，及齧雪與旃毛幷咽之；王莽教民煮木為酪；南方人饑餓，羣入野澤掘鳧茈；鄧禹軍士食藻菜；建安中，鹹陽人拔取酸棗、藜藿以給食；晉郗鑒在鄒山，兗州百姓掘野鼠、蟄燕；幽州人以桑椹為糧，魏道武亦以供軍；岷蜀食芋。如此而已。吾州外邑，（山樂）崌山在樂平、德興境，李羅萬斛山在浮梁、樂平、鄱陽境，皆綿亘百餘里，山出蕨萁。乾道辛卯、紹熙癸丑歲旱，村民無食，爭往取其根。率以昧旦荷鋤往掘，深至四五尺，壯者日可得六十斤。持歸搗取粉，水澄細者煮食之，如粔籹狀，每根二斤可充一夫一日之食。冬晴且暖，田野間無不出者，或不遠數十里，多至數千人。自九月至二月終，蕨抽拳則根無力，於是始止。蓋救餓羸者半年，天之生物，為人世之利至矣！古人不知用之，傳記亦不載，豈他邦不產此乎？","sortOrder":3},
  {"id":"s_work_dtbt_24_4","chapterId":"ch_work_dtbt_24","text":"賢士隱居者","sortOrder":4},
  {"id":"s_work_dtbt_24_5","chapterId":"ch_work_dtbt_24","text":"士子修己篤學，獨善其身，不求知於人，人亦莫能知者，所至或有之，予每惜其無傳。比得上虞李孟傳錄示四事，故謹書之。","sortOrder":5},
  {"id":"s_work_dtbt_24_6","chapterId":"ch_work_dtbt_24","text":"其一曰，慈溪蔣季莊，當宣和間，鄙王氏之學，不事科舉，閉門窮經，不妄與人接。高抑崇閌居明州城中，率一歲四五訪其廬。季莊聞其至，必倒屣出迎，相對小室，極意講論，自晝竟夜，殆忘寢食。告去則送之數里，相得歡甚。或問抑崇曰：「蔣君不多與人周旋，而獨厚於公，公亦惓惓於彼，願聞其故？」抑崇曰：「閌終歲讀書，凡有疑而未判，與所缺而未知者，每積至數十，輒一扣之，無不迎刃而解。」而蔣之所長，他人未必能知之。世之所謂知己其是乎？","sortOrder":6},
  {"id":"s_work_dtbt_24_7","chapterId":"ch_work_dtbt_24","text":"其二曰，王茂剛，居明之林村，在巖壑深處，有弟不甚學問，使顓治生以餬口，而刻意讀書，足跡未嘗妄出，尤邃於周易。沈煥通判州事，嘗訪之。其見趣絕出於傳註之外雲。氣象嚴重，窺其所得，蓋進而未已也。","sortOrder":7},
  {"id":"s_work_dtbt_24_8","chapterId":"ch_work_dtbt_24","text":"其三曰，顧主簿，不知何許人，南渡後寓於慈溪。廉介有常，安於貧賤，不蘄人之知。至於踐履間，雖細事不苟也。平旦起，俟賣菜者過門，問菜把直幾何，隨所言酬之。他飲食布帛亦然。久之人皆信服，不忍欺。苟一日之用足，則玩心墳典，不事交遊。里中有不安其分、武斷強忮者，相與譏之，曰：「汝豈顧主簿耶？」","sortOrder":8},
  {"id":"s_work_dtbt_24_9","chapterId":"ch_work_dtbt_24","text":"其四曰，周日章，信州永豐人。操行介潔，為邑人所敬。開門授徒，僅有以自給，非其義一毫不取。家至貧，常終日絕食，鄰里或以薄少致饋。時時不繼，寧與妻子忍餓，卒不以求人。隆寒披紙裘，客有就訪，亦欣然延納。望其容貌，聽其論議，莫不聳然。縣尉謝生遺以襲衣，曰：「先生未嘗有求，吾自欲致其勤勤耳，受之無傷也。」日章笑答曰：「一衣與萬鍾等耳，儻無名受之，是不辨禮義也。」卒辭之。汪聖錫亦知其賢，以為近於古之所謂獨行者。","sortOrder":9},
  {"id":"s_work_dtbt_24_10","chapterId":"ch_work_dtbt_24","text":"是四君子，真可書史策雲。","sortOrder":10},
  {"id":"s_work_dtbt_24_11","chapterId":"ch_work_dtbt_24","text":"張籍陳無己詩","sortOrder":11},
  {"id":"s_work_dtbt_24_12","chapterId":"ch_work_dtbt_24","text":"張籍在他鎮幕府，鄆帥李師古又以書幣辟之，籍却而不納，而作節婦吟一章寄之，曰：「君知妾有夫，贈妾雙明珠。感君纏綿意，繫在紅羅襦。妾家高樓連苑起，良人執戟明光裏。知君用心如日月，事夫誓擬同生死。還君明珠雙淚垂，何不相逢未嫁時？」陳無己為潁州教授，東坡領郡，而陳賦妾薄命篇，言為曾南豐作，其首章雲：「主家十二樓，一身當三千。古來妾薄命，事主不盡年。起舞為主壽，相送南陽阡。忍著主衣裳，為人作春妍？有聲當徹天，有淚當徹泉。死者恐無知，妾身長自憐。」全用籍意。或謂無己輕坡公，是不然。前此無己官於彭城，坡公由翰林出守杭，無己越境見之於宋都，坐是免歸，故其詩雲：「一代不數人，百年能幾見？昔為馬首銜，今為禁門鍵。一雨五月涼，中宵大江滿。風帆目力短，江空歲年晚。」其尊敬之盡矣。薄命擬况，蓋不忍師死而遂倍之，忠厚之至也！","sortOrder":12},
  {"id":"s_work_dtbt_24_13","chapterId":"ch_work_dtbt_24","text":"杜詩誤字","sortOrder":13},
  {"id":"s_work_dtbt_24_14","chapterId":"ch_work_dtbt_24","text":"李適之在明皇朝為左相，為李林甫所擠去位，作詩曰：「避賢初罷相，樂聖且銜杯。為問門前客，今朝幾箇來？」故杜子美飲中八仙歌雲：「左相日興費萬錢，飲如長鯨吸百川，銜杯樂聖稱避賢。」正詠適之也。而今所行本誤以「避賢」為「世賢」，絕無意義，兼「世」字是太宗諱，豈敢用哉？秦州雨晴詩雲：「天永秋雲薄，從西萬里風。」謂秋天遼永，風從萬里而來，可謂廣大。而集中作「天水」，此乃秦州郡名，若用之入此篇，其致思淺矣。和李表丈早春作雲：「力疾坐清曉，來詩悲早春。」正答其意。而集中作「來時」，殊失所謂和篇本旨。","sortOrder":14},
  {"id":"s_work_dtbt_24_15","chapterId":"ch_work_dtbt_24","text":"東坡詩用老字","sortOrder":15},
  {"id":"s_work_dtbt_24_16","chapterId":"ch_work_dtbt_24","text":"東坡賦詩，用人姓名，多以老字足成句。如壽州龍潭雲「觀魚幷記老莊周」，病不赴會雲「空對親舂老孟光」，看潮雲「猶似浮江老阿童」，贈黃山人雲「說禪長笑老浮屠」，元長老衲裙雲「乞與佯狂老萬回」，東軒雲「掛冠知有老蕭郎」，侍立邇英雲「定似香山老居士」，贈李道士雲「知是香山老居士」，蒜山亭雲「奇逸多聞老敬通」，汶公東堂雲「一帖空存老遂良」，次韻韶守雲「華髮蕭蕭老遂良」，遊羅浮雲「還須略報老同叔」，贈辯才雲「中有老法師」，寄子由雲「青山老從事」，贈眼醫雲「忘言老尊宿」，「妙高臺中老比丘」，謝惠酒雲「青州老從事」，謝餉魚雲「誰似老方朔」，贈吳子野扇雲「得之老月師」，次韻李端叔雲「此是老牛戩」。是皆以為助語，非真謂其老也，大抵七言則於第五字用之，五言則於第三字用之。若其他錯出，如「再說走老瞞」，「故人餘老龐」，「老濞宮粧傳父祖」，「便腹從人笑老韶」，「老可能為竹寫真」，「不知老奘幾時歸」之類，皆隨語勢而然。白樂天雲「每被老元偷格律」，蓋亦有自來矣。","sortOrder":16},
  {"id":"s_work_dtbt_24_17","chapterId":"ch_work_dtbt_24","text":"杜詩命意","sortOrder":17},
  {"id":"s_work_dtbt_24_18","chapterId":"ch_work_dtbt_24","text":"杜公詩命意用事，旨趣深遠，若隨口一讀，往往不能曉解，姑紀一二篇以示好事者。如：「能畫毛延壽，投壺郭舍人。每蒙天一笑，復似物皆春。政化平如水，皇恩斷若神。時時用抵戲，亦未雜風塵。」第三聯意味頗與前語不相聯貫，讀者或以為疑。按杜之旨，本謂技藝倡優，不應蒙人主顧眄賞接，然使政化如水，皇恩若神，為治大要既無可損，則時時用此輩，亦亡害也。又如：「亂後碧井廢，時清瑤殿深。銅瓶未失水，百丈有哀音。側想美人意，應悲寒甃沉。蛟龍半缺落，猶得折黃金。」此篇蓋見故宮井內汲者得銅瓶而作，然首句便說廢井，則下文翻覆鋪敍為難，而曲折宛轉如是，他人畢一生模寫不能到也。又一篇雲：「鬭鷄初賜錦，舞馬既登牀。簾下宮人出，樓前御柳長。仙遊終一閟，女樂久無香。寂寞驪山道，清秋草木黃。」先忠宣公在北方，得唐人畫驪山宮殿圖一軸，華清宮居山顛，殿外垂簾，宮人無數，穴簾隙而窺，一時伶官戲劇，品類雜沓，皆列於下。杜一詩真所謂親見之也。","sortOrder":18},
  {"id":"s_work_dtbt_24_19","chapterId":"ch_work_dtbt_24","text":"擇福莫若重","sortOrder":19},
  {"id":"s_work_dtbt_24_20","chapterId":"ch_work_dtbt_24","text":"國語載范文子曰：「擇福莫若重，擇禍莫若輕。」且士君子樂天知命，全身遠害，避禍就福，安有迨於禍至擇而處之之理哉？韋昭註雲：「有兩福擇取其重，有兩禍擇取其輕。」蓋以不幸而與禍會，勢不容但已，則權其輕重，順受其一焉。莊子養生主篇雲：「為善無近名，為惡無近刑。」夫孳孳為善，君子之所固然，何至於縱意為惡，而特以不麗於刑為得計哉？是又有說矣，其所謂惡者，蓋與善相對之辭，雖於德為愆義，非若小人以身試禍自速百殃之比也。故下文雲：「可以全生，可以保身，可以盡年。」其旨昭矣。","sortOrder":20},
  {"id":"s_work_dtbt_24_21","chapterId":"ch_work_dtbt_24","text":"用人文字之失","sortOrder":21},
  {"id":"s_work_dtbt_24_22","chapterId":"ch_work_dtbt_24","text":"士人為文，或採已用語言，當深究其旨意，苟失之不考，則必詒論議。紹興七年，趙忠簡公重修哲錄，書成，轉特進，製詞雲：「惟宣仁之誣謗未明，致哲廟之憂勤不顯。」此蓋用范忠宣遺表中語，兩句但易兩字，而甚不然，范之辭雲：「致保佑之憂勤不顯。」專指母後以言，正得其實。今以保佑為哲廟，則了非本意矣。紹興十九年，予為福州教授，為府作謝曆日表，頌德一聯雲：「神祇祖考，既安樂於太平，歲月日時，又明章於庶證。」至乾道中，有外郡亦上表謝曆，蒙其採取用之，讀者以為駢麗精切，予笑謂之曰：「此大有利害，今光堯在德壽，所謂『考』者何哉？」坐客皆縮頸，信乎不可不審也。","sortOrder":22},
  {"id":"s_work_dtbt_24_23","chapterId":"ch_work_dtbt_24","text":"李衛公輞川圖跋","sortOrder":23},
  {"id":"s_work_dtbt_24_24","chapterId":"ch_work_dtbt_24","text":"輞川圖一軸，李趙公題其末雲：「藍田縣鹿苑寺主僧子良贄於予，且曰：『鹿苑即王右丞輞川之第也。右丞篤志奉佛，妻死不再娶，潔居逾三十載。母夫人卒，表宅為寺。今冢墓在寺之西南隅，其圖實右丞之親筆。』予閱玩珍重，永為家藏。」弘憲題其前一行雲：「元和四年八月十三日弘憲題。」弘憲者，吉甫字也。其後衞公又跋雲：「乘閒閱篋書中，得先公相國所收王右丞畫輞川圖，實家世之寶也。先公凡更三十六鎮，故所藏書畫多用方鎮印記。太和二年戊申正月四日，浙江西道觀察等使、檢校禮部尚書兼潤州刺史李德裕恭題。」又一行雲：「開成二年秋七月望日，文饒記。」前後五印：曰淮南節度使印、浙江西道觀察處置等使之印、劍南西川節度使印、山南西道節度使印、鄭滑節度使印，幷贊皇二字。又內合同印，建業文房之印，集賢院藏書印，此三者南唐李氏所用，故後一行曰：「昇元二年十一月三日。」雖今所傳為臨本，然正自超妙。但衞公所志，殊為可疑。唐書李吉甫傳雲：「德宗以來，姑息藩鎮，有終身不易地者。吉甫為相歲餘，凡易三十六鎮。」吉甫平生只為淮南節度耳，今乃言身更三十六鎮，誠大不然。所用印記，如浙西、西川、山西、鄭滑，皆衞公所歷也；且書其父手澤，不言第幾子，而有李字；又自標其字，皆非是，蓋好事者妄為之。白樂天詩所說清源寺，即輞川雲。洪慶善作丹陽洪氏家譜序雲：「丹陽之洪本姓弘，避唐諱改。有弘憲者，元和四年跋輞川圖。」亦大錯也。","sortOrder":24},
  {"id":"s_work_dtbt_24_25","chapterId":"ch_work_dtbt_24","text":"白公夜聞歌者","sortOrder":25},
  {"id":"s_work_dtbt_24_26","chapterId":"ch_work_dtbt_24","text":"白樂天琵琶行，蓋在潯陽江上為商人婦所作。而商乃買茶於浮梁，婦對客奏曲，樂天移船，夜登其舟與飲，了無所忌，豈非以其長安故倡女，不以為嫌邪？集中又有一篇題雲夜聞歌者，時自京城謫潯陽，宿於鄂州，又在琵琶之前。其詞曰：「夜泊鸚鵡洲，秋江月澄澈。鄰船有歌者，發調堪愁絕！歌罷繼以泣，泣聲通復咽。尋聲見其人，有婦顏如雪。獨倚帆檣立，娉婷十七八。夜淚似真珠，雙雙墮明月。借問誰家婦，歌泣何凄切？一問一霑襟，低眉終不說。」陳鴻長恨傳序雲：「樂天深於詩，多於情者也，故所遇必寄之吟詠，非有意於漁色。」然鄂州所見，亦一女子獨處，夫不在焉，瓜田李下之疑，唐人不譏也。今詩人罕談此章，聊復表出。","sortOrder":26},
  {"id":"s_work_dtbt_24_27","chapterId":"ch_work_dtbt_24","text":"謝朏志節","sortOrder":27},
  {"id":"s_work_dtbt_24_28","chapterId":"ch_work_dtbt_24","text":"荀彧佐魏武帝，劉穆之佐宋高祖，高德政佐齊文宣，高熲佐隋文帝，劉文靜佐唐高祖，終之篡漢、晉、魏、周及取隋，其功不細矣。彧以不言伏後事與勸止九錫，飲酖而死。穆之居守丹陽，宋祖北伐，而九錫之旨從北來，愧懼而卒。德政以精神凌逼，為楊愔所譖，熲以為相畜妾，為獨孤後所譖，文靜以妾弟告變，為裴寂所譖，皆不免於誅。蕭道成謀篡宋，欲引謝朏參贊大業，屏人與之語，朏無言。道成必欲引參佐命，以為左長史，從容間道石苞事諷之，朏訖不順指。及受宋禪，方為侍中，不肯解璽綬，引枕而臥，步出府門，道成之子賾欲殺之，道成畏得罪於公議，曰：「殺之適成其名，正當容之度外耳！」遂廢於家。海陵王之世復為侍中，宣城王鸞謀繼大統，多引朝廷名士，朏心不願，乃求出為吳興太守。其弟瀹為吏部尚書，朏致酒與之，曰：「可力飲此，無預人事！」其心蓋惡鸞而末如之何也？朏之志節行義，凜凜如此，司馬溫公猶以為譏，斯亦可恕也已！二筆於士匄、韓厥下略及之，故復詳論於此。","sortOrder":28},
  {"id":"s_work_dtbt_24_29","chapterId":"ch_work_dtbt_24","text":"琵琶亭詩","sortOrder":29},
  {"id":"s_work_dtbt_24_30","chapterId":"ch_work_dtbt_24","text":"江州琵琶亭，下臨江津，國朝以來，往來者多題詠，其工者輒為人所傳。淳熙己亥歲，蜀士郭明復以中元日至亭，賦古風一章，其前雲：「白樂天流落浦湓，作琵琶行，其放懷適意，視憂患死生禍福得喪為何物，非深於道者能之乎？賈傅謫長沙，抑鬱致死；陸相竄南賓，屏絕人事，至從狗竇中度食飲。兩公猶有累乎世，未能如樂天逍遙自得也。予過九江，維舟琵琶亭下，為賦此章。」「香山居士頭欲白，秋風吹作湓城客。眼看世事等虛空，雲夢胸中無一物。舉觴獨醉天為家，詩成萬象遭梳爬。不管時人皆欲殺，夜深江上聽琵琶。賈胡老婦兒女語，淚濕青衫如著雨。此公豈作少狂夢？與世浮沈聊爾汝。我來後公三百年，潯陽至今無管絃。(公詩有「潯陽地僻無音樂」之句。)長安不見遺音寂，依舊匡廬翠掃天。」郭君，成都人，隆興癸未登科，仕不甚達。但賈誼自長沙召還，後為梁王傅乃卒，前所雲少誤矣。吾州餘幹縣東幹越亭有琵琶洲在下，唐劉長卿、張祜輩，皆留題。紹興中，王洋元勃一絕句雲：「塞外烽煙能記否，天涯淪落自心知。眼中風物參差是，只欠江州司馬詩。」真佳句也！","sortOrder":30},
  {"id":"s_work_dtbt_24_31","chapterId":"ch_work_dtbt_24","text":"減損入官人","sortOrder":31},
  {"id":"s_work_dtbt_24_32","chapterId":"ch_work_dtbt_24","text":"唐開元十七年，國子祭酒楊瑒上言：「省司奏限天下明經、進士及第，每年不過百人，竊見流外出身，每歲二千餘人，而明經、進士，不能居其什一，則是服勤道業之士，不如胥吏之得仕也。若以出身人太多，則應諸色裁損，不應獨抑明經、進士。」當時以其言為然。淳熙九年，大減任子員數，是時，吏部四選開具以三年為率，文班進士大約三四百人，任子文武亦如之。而恩倖流外，蓋過二千之數，甚與開元類也。","sortOrder":32},
  {"id":"s_work_dtbt_24_33","chapterId":"ch_work_dtbt_24","text":"韓蘇文章譬喻","sortOrder":33},
  {"id":"s_work_dtbt_24_34","chapterId":"ch_work_dtbt_24","text":"韓、蘇兩公為文章，用譬喻處，重複聯貫，至有七八轉者。韓公送石洪序雲：「論人高下，事後當成敗，若河決下流東註，若駟馬駕輕車就熟路，而王良、造父為之先後也，若燭照數計而龜卜也。」盛山詩序雲：「儒者之於患難，其拒而不受於懷也，若築河堤以障屋霤；其容而消之也，若水之於海，冰之於夏日；其玩而忘之以文辭也，若奏金石以破蟋蟀之鳴、蟲飛之聲。」蘇公百步洪詩雲「長洪斗落生跳波，輕舟南下如投梭。水師絕叫鳧雁起，亂石一綫爭磋磨。有如兔走鷹隼落，駿馬下註千丈坡。斷絃離柱箭脫手，飛電過隙珠翻荷」之類，是也。","sortOrder":34},
  {"id":"s_work_dtbt_24_35","chapterId":"ch_work_dtbt_24","text":"唐昭宗贈諫臣官","sortOrder":35},
  {"id":"s_work_dtbt_24_36","chapterId":"ch_work_dtbt_24","text":"唐僖宗幸蜀，政事悉出內侍田令孜之手。左拾遺孟昭圖、右補闕常濬上疏論事，昭圖坐貶，令孜遣人沉之於蟆頤津，賜濬死。資治通鑑記其事。予讀昭宗實錄，即位之初，贈昭圖起居郎，濬禮部員外郎，以其直諫被戮，故褒之。方時艱危，救亡不暇，而初政及此，通鑑失書之，亦可惜也！","sortOrder":36},
  {"id":"s_work_dtbt_24_37","chapterId":"ch_work_dtbt_24","text":"容齋續筆","sortOrder":37},
  {"id":"s_work_dtbt_25_1","chapterId":"ch_work_dtbt_25","text":"卷第七(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_25_2","chapterId":"ch_work_dtbt_25","text":"田租輕重","sortOrder":2},
  {"id":"s_work_dtbt_25_3","chapterId":"ch_work_dtbt_25","text":"李悝為魏文侯作盡地力之教，雲：「一夫治田百畝，歲收粟百五十石，除十一之稅十五石，餘百三十五石。」蓋十一之外，更無他數也。今時大不然，每當輸一石，而義倉省耗別為一斗二升，官倉明言十加六，復於其間用米之精粗為說，分若幹甲，有至七八甲者，則數外之取亦如之。庾人執槩從而輕重其手，度二石二三斗乃可給。至於水腳、頭子、市例之類，其名不一，合為七八百錢，以中價計之，幷僦船負擔，又須五斗，殆是一而取三。以予所見，唯會稽為輕，視前所雲不能一半也。董仲舒為武帝言：「民一歲力役，三十倍於古，而田租口賦，二十倍於古。」謂一歲之中，失其資產三十及二十倍也。又雲：「或耕豪民之田，見稅十五。」言下戶貧民自無田，而耕墾豪富家田，十分之中以五輸本田主，今吾鄉俗正如此，目為「主客分」雲。","sortOrder":3},
  {"id":"s_work_dtbt_25_4","chapterId":"ch_work_dtbt_25","text":"女子夜績","sortOrder":4},
  {"id":"s_work_dtbt_25_5","chapterId":"ch_work_dtbt_25","text":"漢食貨志雲：「冬，民既入，婦人相從夜績，女工一月得四十五日。」謂一月之中，又得半夜，為四十五日也。必相從者，所以省費燎火，同巧拙而合習俗也。戰國策甘茂亡秦出關，遇蘇代曰：「江上之貧女，與富人女會績而無燭，處女相與語，欲去之。女曰，妾以無燭故，常先至掃室布席，何愛餘明之照四壁者？幸以賜妾。」以是知三代之時，民風和厚勤樸如此，非獨女子也，男子亦然。豳風「晝爾於茅，宵爾索綯」，言晝日往取茅歸，夜作綯索，以待時用也，夜者日之餘，其為益多矣。","sortOrder":5},
  {"id":"s_work_dtbt_25_6","chapterId":"ch_work_dtbt_25","text":"淮南王","sortOrder":6},
  {"id":"s_work_dtbt_25_7","chapterId":"ch_work_dtbt_25","text":"漢淮南厲王死，民作歌以諷文帝曰：「一尺布，尚可縫，一斗粟，尚可舂，兄弟二人不相容。」此史、漢所書也。高誘作鴻烈解敍，及許叔重註文，其辭乃雲：「一尺繒，好童童，一升粟，飽蓬蓬，兄弟二人不能相容。」殊為不同，後人但引尺布斗粟之喻耳。厲王子安復為王，招致賓客方術之士，作為內書二十一篇，外書甚衆；又有中篇八卷，言神仙黃白之術。漢書藝文志淮南內二十一篇，淮南外三十三篇，列於雜家，今所存者二十一卷，蓋內篇也。壽春有八公山，正安所延致客之處，傳記不見姓名，而高誘敍以為蘇飛、李尚、左吳、田由、雷被、毛被、伍被、晉昌等八人，然唯左吳、雷被、伍被見於史。雷被者，蓋為安所斥，而亡之長安上書者，疑不得為賓客之賢也。","sortOrder":7},
  {"id":"s_work_dtbt_25_8","chapterId":"ch_work_dtbt_25","text":"薛國久長","sortOrder":8},
  {"id":"s_work_dtbt_25_9","chapterId":"ch_work_dtbt_25","text":"左傳載魯哀公大夫雲：「禹合諸侯於塗山，執玉帛者萬國，今其存者無數十焉。」漢公孫卿語武帝雲：「黃帝萬諸侯，而神靈之封君七千。」按王製所紀九州，凡千七百七十有三國，多寡殊不侔。以環移之，一君會朝所將吏卒，姑以百人計之，則萬國之衆，當為百萬，塗山之下，將安所歸宿乎？其為躗言，無可疑者。所謂存者數十，考諸經傳，可見者唯薛耳。薛之祖奚仲，為夏禹掌車服大夫，自此受封，歷商及周末，始為宋偃王所滅，其享國千九百餘年，傳六十四代，三代諸侯莫之與比。薛壤地褊小，以詩則不列於國風，以世家則不列於史記，而春秋二百四十二年之間，視同儕邾、杞、滕、鄫，獨未嘗受大國侵伐，則其為邦，亦自有持守之道矣。","sortOrder":9},
  {"id":"s_work_dtbt_25_10","chapterId":"ch_work_dtbt_25","text":"建除十二辰","sortOrder":10},
  {"id":"s_work_dtbt_25_11","chapterId":"ch_work_dtbt_25","text":"建除十二辰，史、漢曆書皆不載，日者列傳但有「建除家以為不吉」一句。惟淮南鴻烈解天文訓篇雲：「寅為建，卯為除，辰為滿，巳為平，主生；午為定，未為執，主陷；申為破，主衡；酉為危，主杓；戌為成，主少德；亥為收，主大德；子為開，主太歲；丑為閉，主太陰。」今會元官曆，每月逢建、平、破、收日，皆不用，以建為月陽，破為月對，平、收隨陰陽月遞互為魁罡也。酉陽雜俎夢篇雲：「周禮以日月星辰各占六夢，謂日有甲乙，月有建破。」今註無此語。正義曰：「按堪輿，黃帝問天老事雲『四月陽建於巳，破於亥，陰建於未，破於癸，是為陽破陰，陰破陽』。」今不知何書所載，但又以十幹為破，未之前聞也。","sortOrder":11},
  {"id":"s_work_dtbt_25_12","chapterId":"ch_work_dtbt_25","text":"俗語算數","sortOrder":12},
  {"id":"s_work_dtbt_25_13","chapterId":"ch_work_dtbt_25","text":"三三如九，三四十二，二八十六，四四十六，三九二十七，四九三十六，六六三十六，五八四十，五九四十五，六九五十四，七九六十三，八九七十二，九九八十一，皆俗語算數，然淮南子中有之。三七二十一，蘇秦說齊王之辭也。漢書律曆志劉歆典領鐘律，奏其辭，亦雲八八六十四。杜預註左傳，天子用八，雲八八六十四人，又六六三十六人，四四十六人。如淳、孟康、晉灼註漢志，亦有二八十六，三四十二，六八四十八，八八六十四等語。","sortOrder":13},
  {"id":"s_work_dtbt_25_14","chapterId":"ch_work_dtbt_25","text":"伾文用事","sortOrder":14},
  {"id":"s_work_dtbt_25_15","chapterId":"ch_work_dtbt_25","text":"唐順宗即位，抱疾不能言，王伾、王叔文以東宮舊人用事，政自己出，即日禁宮市之擾民，五坊小兒之暴閭巷，罷鹽鐵使之月進，出教坊女伎六百還其家。以德宗十年不下赦令，左降官雖有名德才望，不復敍用，即追陸贄、鄭餘慶、韓皋、陽城還京師，起薑公輔為刺史。人情大悅，百姓相聚讙呼。又謀奪宦者兵，既以范希朝及其客韓泰總統京西諸城鎮行營兵馬，中人尚未悟。會諸將以狀來辭，始大怒，令其使歸告其將，「無以兵屬人」。當是時，此計若成，兵柄歸外朝，則定策國老等事，必不至後日之患矣！所交黨與，如陸質、呂溫、李景儉、韓曄、劉禹錫、柳宗元，皆一時豪俊知名之士，惟其居心不正，好謀務速，欲盡據大權，如鄭珣瑜、高郢、武元衡稍異己者，皆亟斥徙，以故不旋踵而身陷罪戮。後世蓋有居伾、文之地，而但務嘯引沾沾小人以為鷹犬者，殆又不足以望其百一雲。白樂天諷諫，元和四年作，其中賣炭翁一篇，蓋為宮市，然則未嘗能絕也。","sortOrder":15},
  {"id":"s_work_dtbt_25_16","chapterId":"ch_work_dtbt_25","text":"五十絃瑟","sortOrder":16},
  {"id":"s_work_dtbt_25_17","chapterId":"ch_work_dtbt_25","text":"李商隱詩雲「錦瑟無端五十絃」，說者以為錦瑟者，令狐丞相侍兒小名，此篇皆寓言，而不知五十絃所起。劉昭釋名箜篌雲：「師延所作靡靡之樂，蓋空國之侯所作也。」段安節樂府錄雲：「箜篌乃鄭、衞之音，以其亡國之聲，故號空國之侯，亦曰坎侯。」吳兢解題雲：「漢武依琴造坎侯，言坎坎應節也。後訛為箜篌。」予按史記封禪書雲：「漢公孫卿為武帝言：『太帝使素女鼓五十絃瑟，悲，帝禁不止，故破其瑟為二十五絃。』於是武帝益召歌兒，作二十五絃及空侯。」應劭曰：「帝令樂人侯調始造此器。」前漢郊祀志備書此事，言「空侯瑟自此起」。顏師古不引劭所註，然則二樂本始，曉然可考，雖劉、吳博洽，亦不深究，且「空」元非國名，其說尤穿鑿也。初學記、太平御覽編載樂事，亦遺而不書。莊子言「魯遽調瑟，二十五絃皆動」，蓋此雲。續漢書雲「靈帝胡服作箜篌」，亦非也。","sortOrder":17},
  {"id":"s_work_dtbt_25_18","chapterId":"ch_work_dtbt_25","text":"遷固用疑字","sortOrder":18},
  {"id":"s_work_dtbt_25_19","chapterId":"ch_work_dtbt_25","text":"東坡作趙德麟字說雲：「漢武帝獲白麟，司馬遷、班固書曰『獲一角獸，蓋麟雲』，蓋之為言，疑之也。」予觀史、漢所紀事，凡致疑者，或曰若，或曰雲，或曰焉，或曰蓋，其語舒緩含深意，姑以封禪書、郊祀志考之，漫記於此。「雍州好畤，自古諸神祠皆聚雲。蓋黃帝時嘗用事，雖晚周亦郊焉。」「三神山，蓋嘗有至者，諸仙人及不死之藥皆在焉。」「未能至，望見之焉。」新垣平望氣言：「有神氣，成五采，若人冠絻焉。」「權火舉而祠，若光輝然屬天焉。」「出長安門，若見五人於道北。」「蓋夜致王夫人之貌雲，天子自帷中望見焉。」「登中嶽太室。從官在山下聞若有言萬歲者雲。」「祭封禪祠，其夜若有光。」封欒大詔：「天若遺朕士而大通焉。」河東迎鼎，「有黃雲蓋焉。」「見神人東萊山，若雲欲見天子。」方士言「蓬萊諸神若將可得。」「天子為塞河，興通天臺，若見有光雲。」「獲若石雲於陳倉。」此外如所謂「及羣臣有言老父，則大以為仙人也。」「可為觀，如緱城，神人宜可致。」「天旱，意乾封乎？」「然其效可睹矣。」詞旨亦相似。","sortOrder":19},
  {"id":"s_work_dtbt_25_20","chapterId":"ch_work_dtbt_25","text":"僭亂的對","sortOrder":20},
  {"id":"s_work_dtbt_25_21","chapterId":"ch_work_dtbt_25","text":"王莽竊位稱新室，公孫述稱成家，袁術稱仲家，董卓郿塢，公孫瓚易京，皆自然的對也。","sortOrder":21},
  {"id":"s_work_dtbt_25_22","chapterId":"ch_work_dtbt_25","text":"月不勝火","sortOrder":22},
  {"id":"s_work_dtbt_25_23","chapterId":"ch_work_dtbt_25","text":"莊子外物篇：「利害相摩，生火甚多，衆人焚和，月固不勝火，於是乎有僓然而道盡。」註雲：「大而暗則多累，小而明則知分。」東坡所引，乃曰：「郭象以為大而暗，不若小而明。陋哉斯言也！為更之曰，月固不勝燭，言明於大者必晦於小，月能燭天地，而不能燭毫釐，此其所以不勝火也，然卒之火勝月耶？月勝火耶？」予記朱元成萍洲可談所載：「王荊公在修撰經義局，因見舉燭，言：『佛書有日月燈光明佛，燈光豈足以配日月乎？』呂惠卿曰：『日煜乎晝，月煜乎夜，燈煜乎日月所不及，其用無差別也。』公大以為然，蓋發言中理，出人意表雲。」予妄意莊子之旨，謂人心如月，湛然虛靜，而為利害所薄，生火熾然，以焚其和，則月不能勝之矣，非論其明暗也。","sortOrder":23},
  {"id":"s_work_dtbt_25_24","chapterId":"ch_work_dtbt_25","text":"靈臺有持","sortOrder":24},
  {"id":"s_work_dtbt_25_25","chapterId":"ch_work_dtbt_25","text":"莊子庚桑楚篇雲：「靈臺者，有持而不知其所持，而不可持者也。」郭象雲：「有持者，謂不動於物耳，其實非持。若知其所持而持之，持則失也。」陳碧虛雲：「真宰存焉，隨其成心而師之。」予謂是皆置論於言意之表，玄之又玄，復採莊子之語以為說，而於本旨殆不然也。嘗記洪慶善雲：「此一章謂持心有道，苟為不知其所以持之，則不復可持矣。」蓋前二人解釋者，為兩「而」字所惑，故從而為之辭。","sortOrder":25},
  {"id":"s_work_dtbt_25_26","chapterId":"ch_work_dtbt_25","text":"董仲舒災異對","sortOrder":26},
  {"id":"s_work_dtbt_25_27","chapterId":"ch_work_dtbt_25","text":"漢武帝建元六年，遼東高廟、長陵高園殿災，董仲舒居家推說其意，草藁未上，主父偃竊其書奏之。上召視諸儒，仲舒弟子呂步舒不知其師書，以為大愚。於是下仲舒吏，當死，詔赦之。仲舒遂不敢復言災異。此本傳所書。而五行志載其對曰：「漢當亡秦大敝之後，承其下流。又多兄弟親戚骨肉之連，驕揚奢侈，恣睢者衆，故天災若語陛下：『非以太平至公，不能治也。視親戚貴屬在諸侯遠正最甚者，忍而誅之，如吾燔遼東高廟乃可；視近臣在國中處旁仄及貴而不正者，忍而誅之，如吾燔高園殿乃可』雲爾。在外而不正者，雖貴如高廟，猶災燔之，况諸侯乎！在內不正者，雖貴如高園殿，猶燔災之，况大臣乎！此天意也。」其後淮南、衡山王謀反，上思仲舒前言，使呂步舒持斧鉞治淮南獄，以春秋誼顓斷於外，不請。既還奏事，上皆是之。凡與王謀反列侯二千石豪傑，皆以罪輕重受誅，二獄死者數萬人。嗚呼！以武帝之嗜殺，時臨御方數歲，可與為善，廟殿之災，豈無他說？而仲舒首勸其殺骨肉大臣，與平生學術大為乖剌，馴致數萬人之禍，皆此書啟之也。然則下吏幾死，蓋天所以激步舒雲，使其就戮，非不幸也。","sortOrder":27},
  {"id":"s_work_dtbt_25_28","chapterId":"ch_work_dtbt_25","text":"李正己獻錢","sortOrder":28},
  {"id":"s_work_dtbt_25_29","chapterId":"ch_work_dtbt_25","text":"唐德宗初即位，淄青節度使李正己，畏上威名，表獻錢三十萬緡。上欲受之，恐見欺，却之則無辭。宰相崔祐甫，請遣使慰勞淄青將士，因以正己所獻錢賜之，使將士人人戴上恩，諸道知朝廷不重貨財。上悅從之。正己大慚服。天下以為太平之治，庶幾可望。紹興三十年，鎮江都統製劉寶乞詣闕奏事，朝廷以其方命刻下，罷就散職。寶規取恩寵，掃一府所有，載以自隨，巨舟連檣，白金至五艦，他所賫挾皆稱是。其始謀蓋雲此行不以何事，必可力買。既至，趑趄國門，不許入覲，或以謂欲上諸內府。予時為樞密檢詳，為丞相言：「援祐甫所陳，乞以寶所賫等第賜其本軍，明降詔書，遣一朝士以寶平生過惡，告諭卒伍，使知明天子惠綏惻怛之意。或寶靳固奄有，刄為己物，則宜因人之言，發命詰問在行之物，本安所出，今安所用？悉取而籍之。就其舟楫，北還充賜，尤可以破其溪壑無厭之謀。」湯岐公當國，不能用也。","sortOrder":29},
  {"id":"s_work_dtbt_25_30","chapterId":"ch_work_dtbt_25","text":"宣室","sortOrder":30},
  {"id":"s_work_dtbt_25_31","chapterId":"ch_work_dtbt_25","text":"漢宣室有殿有閣，皆在未央宮殿北，三輔黃圖以為前殿正室。武帝為竇太主置酒，引內董偃，東方朔曰：「宣室者，先帝之正處也，非法度之政不得入焉。」文帝受釐於此，宣帝常齋居以决事。如淳曰：「布政教之室也。」然則起於高祖時，蕭何所創，為退朝聽政之所。而史記龜策傳雲：「武王圍紂象郎，自殺宣室。」徐廣曰：「天子之居，名曰宣室。」淮南子雲「武王甲卒三千，破紂牧野，殺之宣室。」註曰：「商宮名，一曰獄也。」蓋商時已有此名，漢偶與之同，黃圖乃以為「漢取舊名」，非也。","sortOrder":31},
  {"id":"s_work_dtbt_25_32","chapterId":"ch_work_dtbt_25","text":"昔昔鹽","sortOrder":32},
  {"id":"s_work_dtbt_25_33","chapterId":"ch_work_dtbt_25","text":"薛道衡以「空梁落燕泥」之句，為隋煬帝所嫉。考其詩名昔昔鹽，凡十韻：「垂柳覆金堤，蘼蕪葉復齊。水溢芙蓉沼，花飛桃李蹊。採桑秦氏女，織錦竇家妻。關山別蕩子，風月守空閨。常斂千金笑，長垂雙玉啼。盤龍隨鏡隱，彩鳳逐帷低。飛魂同夜鵲，倦寢憶晨鷄。暗牖懸蛛網，空梁落燕泥。前年過代北，今歲往遼西。一去無消息，那能惜馬蹄！」唐趙嘏廣之為二十章，其燕泥一章雲：「春至今朝燕，花時伴獨啼。飛斜珠箔隔，語近畫梁低。帷卷閒窺戶，牀空暗落泥。誰能長對此，雙去復雙栖。」樂苑以為羽調曲。玄怪錄載「籧篨三娘工唱阿鵲鹽」，又有突厥鹽、黃帝鹽、白鴿鹽、神雀鹽、疏勒鹽、滿座鹽、歸國鹽。唐詩「媚賴吳娘唱是鹽」，「更奏新聲刮骨鹽」。然則歌詩謂之「鹽」者，如吟、行、曲、引之類雲。今南嶽廟獻神樂曲，有黃帝鹽，而俗傳以為「皇帝炎」，長沙志從而書之，蓋不考也。韋縠編唐才調詩，以趙詩為劉長卿，而題為別宕子怨，誤矣。","sortOrder":33},
  {"id":"s_work_dtbt_25_34","chapterId":"ch_work_dtbt_25","text":"將帥當專","sortOrder":34},
  {"id":"s_work_dtbt_25_35","chapterId":"ch_work_dtbt_25","text":"周易師卦：「六三，師或輿尸，凶。」「九五，長子帥師，弟子輿尸，貞凶。」爻意謂用兵當付一帥，苟其儔雜然臨之，則凶矣。輿尸者，衆主也。安慶緒既敗，遁歸相州，肅宗命郭汾陽、李臨淮九節度致討。以二人皆元勳，難相統屬，故不置元帥，但以宦者魚朝恩為觀軍容宣慰處置使，步騎六十萬，為史思明所挫，一戰而潰。憲宗討淮西，命宣武等十六道進軍，雖以韓弘為都統，而身未嘗至。既無統帥，至四年不克，及裴度一出，纔數月即成功。穆宗討王庭湊、朱克融，時裴度鎮河東，亦為都招討使，羣帥如李光顏、烏重嗣，皆當時名將。而翰林學士元稹，意圖宰相，忌度先進，與知樞密魏簡相結，度每奏畫軍事，輒從中沮壞之，故屯守逾年，竟無成績。貞元之誅吳少誠，元和之征盧從史，皆此類也。石晉開運中，為契丹所攻，中國兵力寡弱，桑維翰為宰相，一製指揮節度使十五人。雖杜重威、李守正、張彥澤輩，駑材反虜，然重威為主將，陽城之戰，三人者尚能以身徇國，大敗強胡，耶律德光乘橐駝奔竄，僅而獲免。由是觀之，大將之權，其可不專邪？","sortOrder":35},
  {"id":"s_work_dtbt_25_36","chapterId":"ch_work_dtbt_25","text":"容齋續筆","sortOrder":36},
  {"id":"s_work_dtbt_26_1","chapterId":"ch_work_dtbt_26","text":"卷第八(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_26_2","chapterId":"ch_work_dtbt_26","text":"蓍龜卜筮","sortOrder":2},
  {"id":"s_work_dtbt_26_3","chapterId":"ch_work_dtbt_26","text":"古人重卜筮，其究至於通神，龜為卜，蓍為筮，故曰「假爾泰龜有常，假爾泰筮有常」，「定天下之吉凶，成天下之亹亹」，「所以使民信時日，敬鬼神，畏法令」。舜之命禹，武王之伐紂，召公相宅，周公營成周，未嘗不崑命元龜，襲祥考卜。然筮短龜長，則龜卜猶在易筮之上。漢藝文志、劉向所輯七略，自龜書、夏龜之屬，凡十五家至四百一卷，後世無傳焉。今之揲蓍者，率多流入於影象，所謂龜策，惟市井細人始習此藝。其得不過數錢，士大夫未嘗過而問也。伎術標榜，所在如織，五星、六壬、衍禽、三命、軌析、太一、洞微、紫微、太素、遁甲，人人自以為君平，家家自以為季主，每況愈下。由是藉手於達官要人，舟車交錯於道路，毀譽紛紜，而術益隱矣。周禮：「大卜掌三兆之法，一曰玉兆，二曰瓦兆，三曰原兆。」杜子春雲：「玉兆，顓帝之兆；瓦兆，帝堯之兆；原兆，有周之兆。」「經兆之體皆百有二十，其頌皆千有二百。」又「掌三易之法，曰連山，曰歸藏，曰周易。其經卦皆八，其別皆六十有四。」今獨周易之書存，他不復可見。世謂文王重易六爻為六十四卦，然則夏、商之易已如是矣。左氏傳所載懿氏占曰：「鳳皇於飛，和鳴鏘鏘。有媯之後，將育於薑。」成季之卜曰：「其名曰友，在公之右。同復於父，敬如君所。」晉獻公驪姬之繇曰：「專之渝，攘公之羭。」嫁伯姬之繇曰：「車說其輹，火焚其旗。寇張之弧，侄其從姑。」秦伯伐晉曰：「千乘三去，三去之餘，獲其雄狐。」文公納王，遇黃帝戰於阪泉之兆。鄢陵之戰，晉侯筮曰：「南國（足戚），射其元，王中厥目。」宋伐鄭，趙鞅卜救之，遇水適火，史龜曰：「是謂沈陽，可以興兵，利以伐薑，不利子商。」史墨曰：「盈，水名；子，水位。名位敵，不可幹也。」杜氏謂「鞅姓盈，宋姓子」，蓋言「嬴」與「盈」同也。史趙曰：「是謂如川之滿，不可遊也。」衞莊公卜夢，曰：「如魚竀尾，衡流而方羊裔焉。闔門塞竇，乃自後逾。」此十占皆不可得其說，故杜元凱雲：「凡筮者用周易，則其象可推。非此而往，則臨時占者或取於象，或取於氣，或取於時日、王相以成其占。若盡附會以爻象，則架虛而不經。」可為通論，然亦安知非連山、歸藏所載乎？","sortOrder":3},
  {"id":"s_work_dtbt_26_4","chapterId":"ch_work_dtbt_26","text":"地名異音","sortOrder":4},
  {"id":"s_work_dtbt_26_5","chapterId":"ch_work_dtbt_26","text":"郡邑之名有與本字大不同者，顏師古以為土俗各有別稱者是也。姑以漢書地理志言之：馮翊之櫟陽為「藥陽」，蓮勺為「輦酌」；太原之慮虒為「廬夷」；上黨之沾為「添」；河內之隆慮為「林廬」，蕩陰為「湯陰」；潁川之不羹為「不郎」；南陽之酈為「擲」，堵陽為「者陽」，酇為「讚」；沛之酇為「嵯」，鄲為「多」；清河之鄃為「輸」；汝南之平輿為「平預」；濟陰之宛句為「冤劬」；江夏之沙羨為「沙夷」；九江之橐皋為「拓姑」；廬江之雩婁為「吁閭」；山陽之方與為「房豫」；琅邪之不其為「不基」；東海之承為「證」；長沙之承陽為「烝陽」；臨淮之取慮為「秋廬」；會稽之諸暨為「諸既」，太末為「闥末」；豫章之餘汗為「餘幹」；廣漢之汁方為「十方」；蜀郡之徙為「斯」；益州之味為「昧」；金城之允吾為「鉛牙」，允街為「鉛街」；武威之樸（左上亠下睘右刂）為「蒲環」；張掖之番禾為「盤和」；安定之烏氏為「烏支」；上郡之龜茲為「丘慈」；西河之鵠澤為「梏澤」；代郡之狋氏為「權精」；遼西之且慮為「趄廬」，令支為「鈴祗」；遼東之番汗為「盤寒」；樂浪之黏蟬為「黏提」；南海之番禺為「潘隅」；蒼梧之荔浦為「肄浦」；交趾之羸（阝婁）為「蓮簍」；九真之都龐為「都聾」；日南之西捲為「西權」；淮陽之陽夏為「陽賈」；魯國之蕃為「皮」。皆不可求之於義訓，字書亦不盡載也。","sortOrder":5},
  {"id":"s_work_dtbt_26_6","chapterId":"ch_work_dtbt_26","text":"韓嬰詩","sortOrder":6},
  {"id":"s_work_dtbt_26_7","chapterId":"ch_work_dtbt_26","text":"前漢書儒林傳敍詩雲，漢興，申公作魯詩，後蒼作齊詩，韓嬰作韓詩。又雲，申公為詩訓故。而齊轅固、燕韓生皆為之傳，或取春秋，採雜說，鹹非其本義與不得已，魯最為近之。嬰為文帝博士，景帝時至常山太傅，推詩人之意，作外傳數萬言，其語頗與齊、魯間殊，然歸一也。武帝時，與董仲舒論於上前，精悍分明，仲舒不能難。其後韓氏有王吉、食子公、長孫順之學。藝文志，韓家詩經二十八卷，韓故三十六卷，內傳四卷，外傳六卷，韓說四十一卷。今惟存外傳十卷。慶曆中，將作監主簿李用章序之，命工刊刻於杭，其末又題雲：「蒙文相公改正三千餘字。」予家有其書，讀首卷第二章，曰：「孔子南遊適楚，至於阿穀，有處子佩瑱而浣者。孔子曰：『彼婦人其可與言矣乎！』抽觴以授子貢，曰：『善為之辭。』子貢曰：『吾將南之楚，逢天暑，願乞一飲以表我心。』婦人對曰：『阿穀之水流而趨海，欲飲則飲，何問婦人乎？』受子貢觴，迎流而挹之，置之沙上，曰：『禮固不親授。』孔子抽琴去其軫，子貢往請調其音。婦人曰：『吾五音不知，安能調琴？』孔子抽絺綌五兩以授子貢，子貢曰：『吾不敢以當子身，敢置之水浦。』婦人曰：『子年甚少，何敢受子？子不早去，今竊有狂夫守之者矣。』詩曰：『南有喬木，不可休息。漢有遊女，不可求思。』此之謂也。」觀此章，乃謂孔子見處女而教子貢以微詞三挑之，以是說詩，可乎？其謬戾甚矣，他亦無足言。","sortOrder":7},
  {"id":"s_work_dtbt_26_8","chapterId":"ch_work_dtbt_26","text":"五行衰絕字","sortOrder":8},
  {"id":"s_work_dtbt_26_9","chapterId":"ch_work_dtbt_26","text":"木絕於申，故柛字之訓為木自斃。水土絕於巳，故汜字之訓，說文以為窮瀆，圯字之訓為岸圯及覆。火衰於戌，故烕為滅。金衰於丑，故鈕為鍵閉。製字之義昭矣。","sortOrder":9},
  {"id":"s_work_dtbt_26_10","chapterId":"ch_work_dtbt_26","text":"漢表所記事","sortOrder":10},
  {"id":"s_work_dtbt_26_11","chapterId":"ch_work_dtbt_26","text":"漢書功臣表所記列侯功狀，有紀傳所軼者。韓信擊魏，以木罌缶度軍，表雲：祝阿侯高邑以將軍屬淮陰，擊魏，罌度軍。(史記作「缻」。)蓋此計由邑所建也。信謀發兵襲呂後，其舍人得罪信，信囚欲殺之。舍人弟上書變，告信欲反。晉灼註曰：「楚漢春秋雲，謝公也。」表有滇陽侯樂說，史記作「欒說」，以淮陰舍人告反，侯，蓋非謝公也。須昌侯趙衍從漢王起漢中，雍軍塞渭上，上計欲還，衍言從他道，道通。中牟侯單右車，始，高祖微時，有急，給高祖馬，故得侯。（巳阝）侯黃極忠以羣盜長為臨江將，已而為漢擊臨江王。祁侯繒賀從擊項籍，漢王敗走，賀擊楚迫騎，以故不得進，漢王顧謂賀祁王。(史記作「侯」。)顏師古曰：「謂之祁王，蓋嘉其功，故寵褒之，許以為王也。」他復有與傳小異者。史記張良傳，項梁立韓王成，以良為韓申徒。徐廣雲：「申徒即司徒，語音訛轉也。」而漢表，良以韓申都下韓。師古雲：「韓申都即韓王信也，楚漢春秋作『信都』，古『信』『申』同字。」按良與韓王信了不相幹，顏註誤矣。自「司徒」訛為「申徒」，自「申徒」為「申都」，自「申都」為「信都」，展轉相傳，古書豈復可以字義求也？韓信歸漢，為治粟都尉，表以為票客。師古曰：「與紀傳參錯不同，或者以其票疾而賓客禮之，故雲票客也。」史記作「典客」，索隱以為「粟客」。此外又有官名非史所載者。如：孔聚以執盾從；周竈以長鉟都尉；郭蒙以戶衞；宣虎以重將，重將者，主將領輜重也；耏跖以門尉；棘丘侯襄以執盾隊史；郭亭以塞路，塞路者，主遮塞要路以備敵寇也；丁禮以中涓騎；爰類以慎將，謂以謹慎為將也；許盎以駢鄰說衞，駢鄰者，二馬曰駢，謂並兩騎為軍翼也，說讀曰稅，稅衞者，軍行初舍止之時主為衞也；許瘛以趙右林將，林將者，將士林，猶言羽林之將也；清侯以弩將；留肹以客吏；馮解散以代大與，大與，主爵祿之官也，史記作「太尉」；靳彊以郎中騎千人之類。聊紀於此，以示讀史者雲。","sortOrder":11},
  {"id":"s_work_dtbt_26_12","chapterId":"ch_work_dtbt_26","text":"蕭何紿韓信","sortOrder":12},
  {"id":"s_work_dtbt_26_13","chapterId":"ch_work_dtbt_26","text":"黥布為其臣賁赫告反，高祖以語蕭相國，相國曰：「布不宜有此，恐仇怨妄誣之，請繫赫，使人微驗淮南。」布遂反。韓信為人告反，呂後欲召，恐其不就，乃與蕭相國謀，詐令人稱陳豨已破，紿信曰：「雖病強入賀。」信入，即被誅。信之為大將軍，實蕭何所薦，今其死也，又出其謀，故俚語有「成也蕭何，敗也蕭何」之語。何尚能救黥布，而翻忍於信如此？豈非以高祖出征，呂後居內，而急變從中起，己為留守，故不得不亟誅之，非如布之事尚在疑似之域也。","sortOrder":13},
  {"id":"s_work_dtbt_26_14","chapterId":"ch_work_dtbt_26","text":"彭越無罪","sortOrder":14},
  {"id":"s_work_dtbt_26_15","chapterId":"ch_work_dtbt_26","text":"韓信、英布、彭越皆以謀反誅夷。信乘高祖自將征陳豨之時，欲詐赦諸官徒，發兵襲呂後、太子。布見漢使驗問，即發兵東取荊，西擊楚，對高祖言欲為帝，其為反逆已明。唯越但以稱病不親詣邯鄲之故，上既赦以為庶人，而呂後令人告越復謀反，遂及禍。三人之事，越獨為寃。且扈輒勸越反，越不聽，有司以越不誅輒為反形已具。然則貫高欲殺高祖，張敖不從，其事等耳，乃以為不知狀，而敖得釋，何也？樂說告信，賁赫告布，皆得封列侯。而梁大僕告越不論賞，豈非漢朝亦知其故耶？欒布為越大夫，使於齊而越死，還奏事越頭下，上召罵布，欲烹之，布謂越反形未見，而帝以苛細誅之。上乃釋布，拜為都尉。然則高祖於用刑，為有負於越矣，傷哉！","sortOrder":15},
  {"id":"s_work_dtbt_26_16","chapterId":"ch_work_dtbt_26","text":"蜘蛛結網","sortOrder":16},
  {"id":"s_work_dtbt_26_17","chapterId":"ch_work_dtbt_26","text":"佛經雲：「蠢動含靈，皆有佛性。」莊子雲：「惟蟲能蟲，惟蟲能天。」蓋雖崑蟲之微，天機所運，其善巧方便，有非人智慮技解所可及者。蠶之作繭，蜘蛛之結網，蜂之累房，燕之營巢，蟻之築垤，螟蛉之祝子之類是已。雖然，亦各有幸不幸存乎其間。蛛之結網也，布絲引經，捷急上下，其始為甚難。至於緯而織之，轉盼可就，疏密分寸，未嘗不齊。門檻及花梢竹間，則不終日，必為人與風所敗。唯閑屋垝垣，人跡罕至，乃可久久而享其安。故燕巢幕上，季子以為至危。李斯見吏舍廁中鼠食不潔，近人犬，數驚恐之，倉中之鼠食積粟，居大廡之下，不見人犬之憂，嘆曰：「人之賢不肖，譬如鼠矣，在所自處耳！」豈不信哉？","sortOrder":17},
  {"id":"s_work_dtbt_26_18","chapterId":"ch_work_dtbt_26","text":"孫權稱至尊","sortOrder":18},
  {"id":"s_work_dtbt_26_19","chapterId":"ch_work_dtbt_26","text":"陳壽三國志，固多出於一時雜史，然獨吳書稱孫權為至尊，方在漢建安為將軍時，已如此，至於諸葛亮、周瑜，見之於文字間亦皆然。周瑜病困，與權書曰：「曹公在北，劉備寄寓，此至尊垂慮之日也。」魯肅破曹公還，權迎之，肅曰：「願至尊威德加乎四海。」呂蒙遣鄧玄之說郝普曰：「關羽在南郡，至尊身自臨之。」又曰：「至尊遣兵，相繼於道。」蒙謀取關羽，密陳計策，曰：「羽所以未便東向者，以至尊聖明，蒙等尚存也。」陸遜謂蒙曰：「下見至尊，宜好為計。」甘寧欲圖荊州，曰：「劉表慮既不遠，兒子又劣，至尊當早規之。」權為張遼掩襲，賀齊曰：「至尊人主，常當持重。」權欲以諸葛恪典掌軍糧，諸葛亮書與陸遜曰：「家兄年老，而恪性疏，糧穀軍之要最，足下特為啟至尊轉之。」遜以白權。凡此之類，皆非所宜稱，若以為陳壽作史虛辭，則魏、蜀不然也。","sortOrder":19},
  {"id":"s_work_dtbt_26_20","chapterId":"ch_work_dtbt_26","text":"康山讀書","sortOrder":20},
  {"id":"s_work_dtbt_26_21","chapterId":"ch_work_dtbt_26","text":"杜子美贈李太白詩：「康山讀書處，頭白好歸來。」說者以為即廬山也。吳曾能改齋漫錄內辨誤一卷，正辨是事，引杜田杜詩補遺雲范傳正李白新墓碑雲：「白本宗室子，厥先避仇客蜀，居蜀之彰明，太白生焉。彰明，綿州之屬邑，有大、小康山，白讀書於大康山，有讀書堂尚存。其宅在清廉鄉，後廢為僧房，稱隴西院，蓋以太白得名。院有太白像。」吳君以是證杜句，知康山在蜀，非廬山也。予按當塗所刊太白集，其首載新墓碑，宣、歙、池等州觀察使范傳正撰，凡千五百餘字，但雲：「自國朝已來，編於屬籍，神龍初，自碎葉還廣漢，因僑為郡人。」初無補遺所紀七十餘言，豈非好事者偽為此書，如開元遺事之類，以附會杜老之詩邪？歐陽忞輿地廣記雲：「彰明有李白碑，白生於此縣。」蓋亦傳說之誤，當以范碑為正。","sortOrder":21},
  {"id":"s_work_dtbt_26_22","chapterId":"ch_work_dtbt_26","text":"列國城門名","sortOrder":22},
  {"id":"s_work_dtbt_26_23","chapterId":"ch_work_dtbt_26","text":"郡縣及城門名，用一字者為雅馴近古。今獨姑蘇曰吳郡吳縣，有盤門、閶門、葑門、婁門、齊門，他皆不然。春秋時，列國門名見於左氏傳者，鄭最多，曰渠門、純門、時門、將門、閨門、皇門、鄟門、墓門，又有師之梁、桔柣之門。周曰圉門。魯曰雩門、雉門、稷門、萊門、鹿門，又有子駒之門。公羊傳有爭門、吏門。宋曰耏門、桐門、盧門、曹門、澤門、揚門、桑林之門。邾曰魚門、范門。衞曰閱門，蓋獲之門。齊曰雍門，亦有揚門、鹿門、稷門。吳曰胥門。宋垤澤之門，見孟子。","sortOrder":23},
  {"id":"s_work_dtbt_26_24","chapterId":"ch_work_dtbt_26","text":"緇塵素衣","sortOrder":24},
  {"id":"s_work_dtbt_26_25","chapterId":"ch_work_dtbt_26","text":"陳簡齋墨梅絕句一篇雲：「粲粲江南萬玉妃，別來幾度見春歸。相逢京洛渾依舊，只恨緇塵染素衣。」語意皆妙絕。晉陸機為顧榮贈婦詩雲：「京洛多風塵，素衣化為緇。」齊謝元暉酬王晉安詩雲：「誰能久京洛，緇塵染素衣。」正用此也。","sortOrder":25},
  {"id":"s_work_dtbt_26_26","chapterId":"ch_work_dtbt_26","text":"去國立後","sortOrder":26},
  {"id":"s_work_dtbt_26_27","chapterId":"ch_work_dtbt_26","text":"齊高氏食邑於盧，高弱以盧叛齊，閭丘嬰圍之，弱曰：「苟使高氏有後，請致邑。」齊人立高酀，弱致盧而出奔晉。魯臧氏食邑於防，臧紇得罪，使來告曰：「苟守先祀，敢不辟邑。」乃立臧為，紇致防而奔齊。按弱、紇二人，據地要君，故孔子曰：「臧武仲以防求後於魯，雖曰不要君，吾不信也。」然齊、魯之君，竟如其請，不以要君之故而背之，蓋當是時先王之澤未熄，非若戰國務為詐力權謀之比，所謂殺人之中又有禮焉者也。降及末世，遂有帶甲約降，既解甲即圍而殺之者，不仁孰甚焉！","sortOrder":27},
  {"id":"s_work_dtbt_26_28","chapterId":"ch_work_dtbt_26","text":"詩詞改字","sortOrder":28},
  {"id":"s_work_dtbt_26_29","chapterId":"ch_work_dtbt_26","text":"王荊公絕句雲：「京口、瓜洲一水間，鍾山祗隔數重山。春風又綠江南岸，明月何時照我還。」吳中士人家藏其草，初雲「又到江南岸」，圈去到字，註曰不好，改為過，復圈去而改為入，旋改為滿，凡如是十許字，始定為綠。黃魯直詩：「歸燕略無三月事，高蟬正用一枝鳴。」用字初曰抱，又改曰占、曰在、曰帶、曰要，至用字始定。予聞於錢伸仲大夫如此。今豫章所刻本，乃作「殘蟬猶占一枝鳴」。向巨原雲：「元不伐家有魯直所書東坡念奴嬌，與今人歌不同者數處，如浪淘盡為浪聲沉，周郎赤壁為孫吳赤壁，亂石穿空為崩雲，驚濤拍岸為掠岸，多情應笑我早生華髮為多情應是笑我生華髮，人生如夢為如寄。」不知此本今何在也？","sortOrder":29},
  {"id":"s_work_dtbt_26_30","chapterId":"ch_work_dtbt_26","text":"姑舅為婚","sortOrder":30},
  {"id":"s_work_dtbt_26_31","chapterId":"ch_work_dtbt_26","text":"姑舅兄弟為婚，在禮法不禁，而世俗不曉。按刑統戶婚律雲：「父母之姑舅、兩姨姊妹及姨若堂姨、母之姑、堂姑，己之堂姨及再從姨、堂外甥女、女婿姊妹，並不得為婚姻。」議曰：「父母姑舅、兩姨姊妹，於身無服，乃是父母緦麻，據身是尊，故不合娶。及姨又是父母大功尊；若堂姨雖於父母無服，亦是尊屬；母之姑、堂姑，並是母之小功以上尊；己之堂姨及再從姨、堂外甥女亦謂堂姊妹所生者、女婿姊妹，於身雖並無服，據理不可為婚。並為尊卑混亂，人倫失序之故。」然則中表兄弟姊妹正是一等，其於婚娶，了無所妨。予記政和八年，知漢陽軍王大夫申明此項，敕局看詳，以為如表叔取表侄女，從甥女嫁從舅之類，甚為明白。徽州法司編類續降有全文，今州縣官書判，至有將姑舅兄弟成婚而斷離之者，皆失於不能細讀律令也。惟西魏文帝時，禁中外及從母兄弟姊妹為婚，周武帝又詔不得娶母同姓以為妻妾，宣帝詔母族絕服外者聽婚，皆偏閏之製。漫附於此。","sortOrder":31},
  {"id":"s_work_dtbt_26_32","chapterId":"ch_work_dtbt_26","text":"容齋續筆","sortOrder":32},
  {"id":"s_work_dtbt_27_1","chapterId":"ch_work_dtbt_27","text":"卷第九(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_27_2","chapterId":"ch_work_dtbt_27","text":"三家七穆","sortOrder":2},
  {"id":"s_work_dtbt_27_3","chapterId":"ch_work_dtbt_27","text":"春秋列國卿大夫世家之盛，無越魯三家、鄭七穆者。魯之公族，如臧氏、展氏、施氏、子叔氏、叔仲氏、東門氏、郈氏之類固多，唯孟孫、叔孫、季孫實出於桓公，其傳序累代，皆秉國政，與魯相為久長。若揆之以理，則桓公弒兄奪國，得罪於天，顧使有後如此。鄭靈公亡，無嗣，國人立穆公之子子良，子良辭以公子堅長。乃立堅，是為襄公。襄公將去穆氏，子良爭之，願與偕亡。乃舍之，皆為大夫。其後位卿大夫而傳世者，罕、駟、豐、印、遊、國、良，故曰七穆。然則諸家不逐而獲存，子良之力也。至其孫良霄乃先覆族，而六家為卿如故，此又不可解也。","sortOrder":3},
  {"id":"s_work_dtbt_27_4","chapterId":"ch_work_dtbt_27","text":"貢薛韋匡","sortOrder":4},
  {"id":"s_work_dtbt_27_5","chapterId":"ch_work_dtbt_27","text":"漢元帝紀贊雲：「貢、薛、韋、匡迭為宰相。」謂貢禹、薛廣德、韋元成、匡衡也，四人皆握娖自好，當優柔不斷之朝，無所規救。衡專附石顯，最為邪臣；廣德但有諫御樓船一事；禹傳稱在位數言得失，書數十上；元成傳稱為相七年，守正持重，不及父賢，而文采過之。皆不著其有過。按劉向傳：「宏恭、石顯白逮更生下獄，下太傅韋元成、諫大夫貢禹與廷尉雜考。劾更生前為九卿，坐與蕭望之、周堪謀排許、史，毀離親戚，欲退去之，而獨專權。為臣不忠，幸不伏誅，復蒙恩召用，不悔前過，而教令人言變事，誣罔不道。更生坐免為庶人。」若以漢法論之，更生死有餘罪，幸元帝不殺之耳。京房傳房欲行考功法，石顯及韋丞相皆不欲行。然則韋、貢之所以進用，皆陰附恭、顯而得之。班史隱而不論，唯於石顯傳雲：「貢禹明經著節，顯使人致意，深自結納。因薦禹天子，歷位九卿，至御史大夫。」正在望之死後也。","sortOrder":5},
  {"id":"s_work_dtbt_27_6","chapterId":"ch_work_dtbt_27","text":"兒寬張安世","sortOrder":6},
  {"id":"s_work_dtbt_27_7","chapterId":"ch_work_dtbt_27","text":"漢史有當書之事，本傳不載者。武帝時，兒寬有重罪繫，按道侯韓說諫曰：「前吾丘壽王死，陛下至今恨之；今殺寬，後將復大恨矣！」上感其言，遂貰寬，復用之。宣帝時，張安世嘗不快上，(所為不可上意。)上欲誅之，趙充國以為安世本持橐簪筆事孝武帝數十年，見謂忠謹，宜全度之。安世用是得免。二事不書於寬及安世傳，而於劉向、充國傳中見之。豈非以二人之賢為諱之邪？韓說能以一言救賢臣於垂死，而不於說傳書之，以揚其善，為可惜也。","sortOrder":7},
  {"id":"s_work_dtbt_27_8","chapterId":"ch_work_dtbt_27","text":"深溝高壘","sortOrder":8},
  {"id":"s_work_dtbt_27_9","chapterId":"ch_work_dtbt_27","text":"韓信伐趙，趙陳餘聚兵井陘口禦之。李左車說餘曰：「信乘勝而去國遠鬭，其鋒不可當。願假奇兵從間道絕其輜重，而深溝高壘勿與戰。彼前不得鬭，退不得還，不至十日，信之頭可致麾下。」餘不聽，一戰成擒。七國反，周亞夫將兵往擊，會兵滎陽，鄧都尉曰：「吳、楚兵銳甚，難與爭鋒。願以梁委之，而東北壁昌邑，深溝高壘，使輕兵塞其饟道，以全製其極。」亞夫從之，吳果敗亡。李、鄧之策一也，而用與不用則異耳。秦軍武安西，以攻閼與。趙奢救之，去邯鄲三十里，堅壁，二十八日不行，復益增壘。既乃卷甲而趨之，大破秦軍。奢之將略，所謂玩敵於股掌之上，雖未合戰而勝形已著矣。前所雲鄧都尉者，亞夫故父絳侯客也。鼂錯傳雲：「錯已死，謁者僕射鄧公為校尉，擊吳、楚為將。還，上書言軍事，拜為城陽中尉。」鄧公者，豈非鄧都尉乎？亞夫傳以為此策乃自請而後行，顏師古疑其不同，然以事料之，必非出於己也。","sortOrder":9},
  {"id":"s_work_dtbt_27_10","chapterId":"ch_work_dtbt_27","text":"生之徒十有三","sortOrder":10},
  {"id":"s_work_dtbt_27_11","chapterId":"ch_work_dtbt_27","text":"老子「出生入死」章雲：「出生入死，生之徒十有三，死之徒十有三，人之生，動之死地十有三，夫何故？以其生生之厚。」王弼註曰：「十有三，猶雲十分有三分取其生道，全生之極，十分有三耳；取死之道，全死之極，十分亦有三耳。而民生生之厚，更之無生之地焉。」其說甚淺，且不解釋後一節。唯蘇子由以謂「生死之道，以十言之，三者各居其三矣，豈非生死之道九，而不生不死之道一而已乎？老子言其九不言其一，使人自得之，以寄無思無為之妙。」其論可謂盡矣。","sortOrder":11},
  {"id":"s_work_dtbt_27_12","chapterId":"ch_work_dtbt_27","text":"臧氏二龜","sortOrder":12},
  {"id":"s_work_dtbt_27_13","chapterId":"ch_work_dtbt_27","text":"臧文仲居蔡，孔子以為不智。蔡者，國君之守龜，出蔡地，因以為名焉。左傳所稱「作虛器」，正謂此也。至其孫武仲得罪於魯，出奔邾，使告其兄賈於鑄，且致大蔡焉，曰：「紇之罪不及不祀，子以大蔡納請，其可？」蓋請為先人立後也。賈再拜受龜，使弟為為己請，遂自為也。乃立臧為。為之子曰昭伯，嘗如晉，從弟會竊其寶龜僂句(龜所出地名。)以卜為信與僭，僭吉。僭，不信也。會如晉。昭伯問內子與母弟，皆不對。會之意，欲使昭伯疑其若有他故者。歸而察之，皆無之，執而戮之，逸奔郈。及昭伯從昭公孫於齊，季平子立會為臧氏後，會曰：「僂句不餘欺也。」臧氏二事，皆以龜故，皆以弟而奪兄位，亦異矣。","sortOrder":13},
  {"id":"s_work_dtbt_27_14","chapterId":"ch_work_dtbt_27","text":"有扈氏","sortOrder":14},
  {"id":"s_work_dtbt_27_15","chapterId":"ch_work_dtbt_27","text":"夏書甘誓，啟與有扈大戰於甘，以其「威侮五行，怠棄三正，天用剿絕其命」為辭，孔安國傳雲：「有扈與夏同姓，恃親而不恭。」其罪如此耳。而淮南子齊俗訓曰：「有扈氏為義而亡，知義而不知宜也。」高誘註雲：「有扈，夏啟之庶兄也，以堯、舜舉賢，禹獨與子，故伐啟。啟亡之。」此事不見於他書，不知誘何以知之？傳記散軼，其必有以為據矣。莊子以為「禹攻有扈，國為虛厲」，非也。","sortOrder":15},
  {"id":"s_work_dtbt_27_16","chapterId":"ch_work_dtbt_27","text":"太公丹書","sortOrder":16},
  {"id":"s_work_dtbt_27_17","chapterId":"ch_work_dtbt_27","text":"太公丹書今罕見於世，黃魯直於禮書得其諸銘而書之，然不著其本始。予讀大戴禮武王踐阼篇，載之甚備，故悉紀錄以遺好古君子雲：「武王踐阼三日，召士大夫而問焉，曰：『惡有藏之約，行之行，萬世可以為子孫常者乎？』皆曰：『未得聞也。』然後召師尚父而問焉，曰：『黃帝、顓頊之道可得見與？』師尚父曰：『在丹書。王欲聞之，則齋矣。』王齋三日，尚父端冕奉書，道書之言曰：『「敬勝怠者吉，怠勝敬者滅；義勝欲者從，欲勝義者凶。凡事不強則枉，弗敬則不正，枉者滅廢，敬者萬世。」藏之約，行之行，可以為子孫常者，此言之謂也。』又曰：『以仁得之，以仁守之，其量百世；以不仁得之，以仁守之，其量十世；以不仁得之，以不仁守之，必及其世。』王聞書之言，惕若恐懼。退而為戒書，於席之四端為銘。前左端銘曰：『安樂必敬。』前右端銘曰：『無行可悔。』後左端銘曰：『一反一側，亦不可以忘。』後右端銘曰：『所監不遠，視爾所代。』幾之銘曰：『皇皇惟敬，口生（口後），口戕口。』鑑之銘曰：『見爾前，慮爾後。』盥盤之銘曰：『與其溺於人也，寧溺於淵。溺於淵，猶可遊也；溺於人，不可救也。』楹之銘曰：『毋曰胡殘，其禍將然；毋曰胡害，其禍將大；毋曰胡傷，其禍將長。』杖之銘曰：『惡乎危？於忿疐。惡乎失道？於嗜欲。惡乎相忘？於富貴。』帶之銘曰：『火滅修容，慎戒必共，共則壽。』屨之銘曰：『慎之勞，勞則富。』觴豆之銘曰：『食自杖，食自杖，戒之憍，憍則逃。』戶之銘曰：『夫名難得而易失。無勤弗志，而曰我知之乎？無勤弗及，而曰我杖之乎？擾阻以泥之，若風將至，必先搖搖，雖有聖人，不能為謀也。』牖之銘曰：『隨天之時，以地之財，敬祀皇天，敬以先時。』劍之銘曰：『帶之以為服，動必行德，行德則興，倍德則崩。』弓之銘曰：『屈申之義，發之行之，無忘自過。』矛之銘曰：『造矛造矛，少間弗忍，終身之羞。予一人所聞，以戒後世子孫。』」凡十七銘。賈誼政事書，所陳教太子一節千餘言，皆此書保傅篇之文，然及胡亥、趙高之事，則為漢儒所作可知矣。漢昭帝紀「通保傅傳」，文穎註曰：「賈誼作，在禮大戴記。」其此書乎？荀卿議兵篇：「敬勝怠則吉，怠勝敬則滅；計勝欲則從，欲勝計則凶。」蓋出諸此。左傳晉斐豹「著於丹書」，謂以丹書其罪也。其名偶與之同耳。漢祖有丹書鐵契以待功臣，蓋又不同也。","sortOrder":17},
  {"id":"s_work_dtbt_27_18","chapterId":"ch_work_dtbt_27","text":"漢景帝","sortOrder":18},
  {"id":"s_work_dtbt_27_19","chapterId":"ch_work_dtbt_27","text":"漢景帝為人，甚有可議。鼂錯為內史，門東出，不便，更穿一門南出，南出者，太上皇廟堧垣也。丞相申屠嘉聞錯穿宗廟垣，為奏請誅錯。錯恐，夜入宮上謁，自歸。上至朝，嘉請誅錯。上曰：「錯所穿非真廟垣，乃外堧垣，且又我使為之，錯無罪。」臨江王榮以皇太子廢為王，坐侵太宗廟壖地為宮，詣中尉府對簿責訊，王遂自殺。兩者均為侵宗廟，榮以廢黜失寵，至於殺之，錯方貴幸，故略不問罪，其不公不慈如此！及用袁盎一言，錯即夷族，其寡恩忍殺復如此。","sortOrder":19},
  {"id":"s_work_dtbt_27_20","chapterId":"ch_work_dtbt_27","text":"蕭何先見","sortOrder":20},
  {"id":"s_work_dtbt_27_21","chapterId":"ch_work_dtbt_27","text":"韓信從項梁，居戲下，無所知名。又屬羽，數以策幹羽，羽弗用，乃亡歸漢。陳平事項羽，羽使擊降河內，已而漢攻下之。羽怒，將誅定河內者。平懼誅，乃降漢。信與平固能擇所從，然不若蕭何之先見。何為泗水卒史事，第一。秦御史欲入言召何，何固請，得毋行。則當秦之未亡，已知其不能久矣，不待獻策弗用，及懼罪且誅，然後去之也。","sortOrder":21},
  {"id":"s_work_dtbt_27_22","chapterId":"ch_work_dtbt_27","text":"史漢書法","sortOrder":22},
  {"id":"s_work_dtbt_27_23","chapterId":"ch_work_dtbt_27","text":"史記、前漢所書高祖諸將戰功，各為一體。周勃傳：攻開封，先至城下為多；攻好畤，最；擊鹹陽，最；攻曲遇，最；破臧荼，所將卒當馳道為多；擊胡騎平城下，所將卒當馳道為多。夏侯嬰傳：破李由軍，以兵車趣攻戰疾；從擊章邯，以兵車趣攻戰疾；擊秦軍雒陽東，以兵車趣攻戰疾。灌嬰傳：破秦軍於槓里，疾鬭；攻曲遇，戰疾力；戰於藍田，疾力；擊項佗軍，疾戰。又書：擊項冠於魯下，所將卒斬司馬、騎將各一人；擊破王武軍，所將卒斬樓煩將五人；擊武別將，所將卒斬都尉一人；擊齊軍於歷下，所將卒虜將軍、將吏四十六人；擊田橫，所將卒斬騎將一人；從韓信，卒斬龍且，(所將之卒。)身生得周蘭；破薛郡，身虜騎將；擊項籍陳下，所將卒斬樓煩將二人；追至東城，所將卒共斬籍；擊胡騎晉陽下，所將卒斬白題將一人；攻陳豨，卒斬特將五人；破黥布，身生得左司馬一人，所將卒斬小將十人。傅寬傳：屬淮陰，擊破歷下軍；屬相國參，殘博；屬太尉勃，擊陳豨。酈商傳：與鍾離昧戰，受梁相國印；定上穀，受趙相國印。五人之傳，書法不同如此，灌嬰事尤為複重，然讀之了不覺細瑣，史筆超拔高古，范曄以下豈能窺其籬奧哉？又史記灌嬰傳書：受詔別擊楚軍後；受詔將郎中騎兵；受詔將軍騎別追項籍；受詔別降樓煩以北六縣；受詔幷將燕、趙車騎；受詔別攻陳豨。凡六書受詔字，漢減其三雲。","sortOrder":23},
  {"id":"s_work_dtbt_27_24","chapterId":"ch_work_dtbt_27","text":"薄昭田蚡","sortOrder":24},
  {"id":"s_work_dtbt_27_25","chapterId":"ch_work_dtbt_27","text":"周勃為人告欲反，下廷尉，逮捕，吏稍侵辱之。初，勃以誅諸呂功，益封賜金，盡以予太後弟薄昭。及繫急，昭為言太後，後以語文帝，乃得釋。王恢坐為將軍不出擊匈奴單於輜重，下廷尉，當斬。恢行千金於丞相田蚡，蚡不敢言上，而言於太後。後以蚡言告上，上竟誅恢。蚡者，王太後同母弟也。漢世母後豫聞政事，故昭、蚡憑之以招權納賄，其史所不書者，當非一事也。神宗熙寧七年，天下大旱，帝對朝嗟嘆，欲盡罷法度之不善者。王安石怫然爭之，帝曰：「比兩宮泣下，憂京師亂起，以為更失人心。」安石曰：「兩宮有言，乃向經、曹佾所為耳。」是時，安石力行新法，以為民害，向經、曹佾能獻忠於母後，可謂賢戚里矣，而安石非沮之，使遇薄昭、田蚡，當如何哉？高遵裕坐西征失律抵罪，宣仁聖烈後臨朝，宰相蔡確乞復其官，後曰：「遵裕，靈武之役，塗炭百萬，得免刑誅幸矣，吾何敢顧私恩而違天下公議！」其聖如此，雖有昭、蚡百輩，何所容其奸乎？","sortOrder":25},
  {"id":"s_work_dtbt_27_26","chapterId":"ch_work_dtbt_27","text":"文字結尾","sortOrder":26},
  {"id":"s_work_dtbt_27_27","chapterId":"ch_work_dtbt_27","text":"老子道經「孔德之容」一章，其末雲：「吾何以知衆甫之然哉？以此。」蓋用二字結之。左傳：「叔孫武叔使郈馬正侯犯殺郈宰公若藐，弗能。其圉人曰：『吾以劍過朝，公若必曰：「誰之劍也？」吾稱子以告，必觀之，吾偽固而授之末，則可殺也。』使如之。」孟子載：「齊人一妻一妾而處室者，其良人出，必厭酒肉而後反。問所與飲食者，則盡富貴也。妻瞷其所之，乃之東郭墦間之祭者，乞其餘。歸告其妾曰：『良人者，所仰望而終身也，今若此！』」此二事反復數十百語，而但以「使如之」及「今若此」各三字結之。史記封禪書載武帝用方士言神祠長陵神君，李少君、謬忌、少翁、遊水發根、欒大、公孫卿、史寬舒、丁公、王朔、公玉帶、越人勇之之屬，所言祠竈，化丹沙，求蓬萊安期生，立太一壇，作甘泉宮臺室、柏梁、仙人掌，壽宮神君，鬭棋小方，泰帝神鼎，雲陽美光，緱氏城仙人跡，太室呼萬歲，老父牽狗，白雲起封中，德星出，越祠鷄卜，通天臺，明堂，崑侖，建章宮，五城十二樓，凡數十事，三千言，而其末雲「然其效可睹矣」。則武帝所興為者，皆墮誕罔中，不待一二論說也。文字結尾之簡妙至此。","sortOrder":27},
  {"id":"s_work_dtbt_27_28","chapterId":"ch_work_dtbt_27","text":"國初古文","sortOrder":28},
  {"id":"s_work_dtbt_27_29","chapterId":"ch_work_dtbt_27","text":"歐陽公書韓文後雲：「予少家漢東，有大姓李氏者，其子堯輔頗好學。予遊其家，見有敝篋貯故書在壁間，發而視之，得唐昌黎先生文集六卷，脫落顛倒無次序，因乞以歸讀之。是時，天下未有道韓文者，予亦方舉進士，以禮部詩賦為事。後官於洛陽，而尹師魯之徒皆在，遂相與作為古文，因出所藏昌黎集而補綴之。其後天下學者亦漸趨於古，韓文遂行於世。」又作蘇子美集序雲：「子美之齒少於予，而予學古文，反在其後。天聖之間，學者務以言語聲偶擿裂以相誇尚，子美獨與其兄才翁及穆參軍伯長作為古歌詩雜文，時人頗共非笑之，而子美不顧也。其後學者稍趨於古。獨子美為於舉世不為之時，可謂特立之士也。」柳子厚集有穆修所作後敍雲：「予少嗜觀韓、柳二家之文，柳不全見於世，韓則雖目其全，至所缺墜，亡字失句，獨於集家為甚。凡用力二紀，文始幾定，時天聖九年也。」予讀張景集中柳開行狀雲：「公少誦經籍，天水趙生，老儒也，持韓愈文僅百篇授公曰：『質而不麗，意若難曉，子詳之，何如？』公一覽不能捨，嘆曰：『唐有斯文哉！』因為文章直以韓為宗尚。時韓之道獨行於公，遂名肩愈，字紹先。韓之道大行於今，自公始也。」又雲：「公生於晉末，長於宋初，扶百世之大教，續韓、孟而助周、孔。兵部侍郎王祜得公書曰：『子之文出於今世，真古之文章也。』兵部尚書楊昭儉曰：『子之文章，世無如者已二百年矣。』」開以開寶六年登進士第，景作行狀時，鹹平三年。開序韓文雲：「予讀先生之文，自年十七至於今，凡七年。」然則在國初開已得昌黎集而作古文，去穆伯長時數十年矣。蘇、歐陽更出其後，而歐陽略不及之，乃以為天下未有道韓文者，何也？范文正公作尹師魯集序，亦雲：「五代文體薄弱，皇朝柳仲塗起而麾之。洎楊大年專事藻飾，謂古道不適於用，廢而弗學者久之。師魯與穆伯長力為古文，歐陽永叔從而振之，由是天下之文一變而古。」其論最為至當。","sortOrder":29},
  {"id":"s_work_dtbt_27_30","chapterId":"ch_work_dtbt_27","text":"容齋續筆","sortOrder":30},
  {"id":"s_work_dtbt_28_1","chapterId":"ch_work_dtbt_28","text":"卷第十(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_28_2","chapterId":"ch_work_dtbt_28","text":"經傳煩簡","sortOrder":2},
  {"id":"s_work_dtbt_28_3","chapterId":"ch_work_dtbt_28","text":"左傳：蔡聲子謂楚子木曰：「善為國者，賞不僭而刑不濫。賞僭則懼及淫人；刑濫則懼及善人。若不幸而過，寧僭無濫，與其失善，寧其利淫。」其語本於大禹謨「罪疑惟輕，功疑惟重，與其殺不辜，寧失不經」也。晉叔向詒鄭子產書曰：「先王議事以製，誨之以忠，聳之以行，教之以務，使之以和，臨之以敬，涖之以強，斷之以剛，猶求聖哲之上，明察之官，忠信之長，慈惠之師。」其語本於呂刑「惟良折獄，哲人惟刑」也。旨意則同，而經傳煩簡為不侔矣。","sortOrder":3},
  {"id":"s_work_dtbt_28_4","chapterId":"ch_work_dtbt_28","text":"曹參不薦士","sortOrder":4},
  {"id":"s_work_dtbt_28_5","chapterId":"ch_work_dtbt_28","text":"曹參代蕭何為漢相國，日夜飲酒不事事，自雲：「高皇帝與何定天下，法令既明，遵而勿失，不亦可乎！」是則然矣，然以其時考之，承暴秦之後，高帝創業尚淺，日不暇給，豈無一事可關心者哉？其初相齊，聞膠西蓋公善治黃、老言，使人厚幣請之。蓋公為言治道貴清淨而民自定。參於是避正堂以舍之，其治要用黃、老術。故相齊九年，齊國安集。然入相漢時，未嘗引蓋公為助也。齊處士東郭先生、梁石君隱居深山，蒯徹為參客，或謂徹曰：「先生之於曹相國，拾遺舉過，顯賢進能，二人者，世俗所不及，何不進之於相國乎？」徹以告參，參皆以為上賓。徹善齊人安其生，嘗幹項羽，羽不能用其策。羽欲封此兩人，兩人卒不受。凡此數賢，參皆不之用，若非史策失其傳，則參不薦士之過多矣。","sortOrder":5},
  {"id":"s_work_dtbt_28_6","chapterId":"ch_work_dtbt_28","text":"漢初諸將官","sortOrder":6},
  {"id":"s_work_dtbt_28_7","chapterId":"ch_work_dtbt_28","text":"漢初諸將所領官，多為丞相。如韓信初拜大將軍，後為左丞相擊魏，又拜相國擊齊。周勃以將軍遷太尉，後以相國代樊噲擊燕。樊噲以將軍攻韓王信，遷為左丞相，以相國擊燕。酈商為將軍，以右丞相擊陳豨，以丞相擊黥布。尹恢以右丞相備守淮陽。陳涓以丞相定齊地。然百官公卿表皆不載，蓋蕭何已居相位，諸人者，未嘗在朝廷，特使假其名以為重耳。後世使相之官，本諸此也。","sortOrder":7},
  {"id":"s_work_dtbt_28_8","chapterId":"ch_work_dtbt_28","text":"漢官名","sortOrder":8},
  {"id":"s_work_dtbt_28_9","chapterId":"ch_work_dtbt_28","text":"漢官名既古雅，故書於史者，皆可誦味。如「朝臣齗齗不可光祿勳」，「誰可以為御史大夫者」，「御史大夫言可聽」，「郎中令善愧人」，「丞相議不可用」，「太尉不足與計」，「大將軍尊貴誠重」，「大將軍有揖客」，「京兆尹可立得」，「大夫乘私車來邪」，「天官丞日晏不來」，「謝田大夫曉大司農」，「大司馬欲用是忿恨」，「後將軍數畫軍冊」，「光祿大夫、大中大夫耆艾二人以老病罷」，「駙馬都尉安所受此語」之類。又如所書路中大夫、韓御史大夫、叔孫太傅、鄭尚書、鮑司隸、趙將軍、張廷尉，亦燁然有法。後漢書「執金吾擊郾」，「大司馬當擊宛」，「大司馬習用步騎」等語，尚有前史餘味。","sortOrder":9},
  {"id":"s_work_dtbt_28_10","chapterId":"ch_work_dtbt_28","text":"漢唐輔相","sortOrder":10},
  {"id":"s_work_dtbt_28_11","chapterId":"ch_work_dtbt_28","text":"前漢宰相四十五人，自蕭、曹、魏、丙之外，如陳平、王陵、周勃、灌嬰、張蒼、申屠嘉以高帝故臣，陶青、劉舍、許昌、薛澤、莊青翟、趙周以功臣侯子孫，竇嬰、田蚡、公孫賀、劉屈氂以宗戚，衞綰、李蔡以士伍，唯王陵、申屠嘉及周亞夫、王商、王嘉有剛直之節，薛宣、翟方進有材，其餘皆容身保位，無所建明。至於御史大夫，名為亞相，尤錄錄不足數。劉向所謂御史大夫未有如兒寬者，蓋以餘人可稱者少也。若唐宰相三百餘人，自房、杜、姚、宋之外，如魏徵、王珪、褚遂良、狄仁傑、魏元忠、韓休、張九齡、楊綰、崔祐甫、陸贄、杜黃裳、裴垍、李絳、李藩、裴度、崔羣、韋處厚、李德裕、鄭畋，皆為一時名宰，考其行事，非漢諸人可比也。","sortOrder":11},
  {"id":"s_work_dtbt_28_12","chapterId":"ch_work_dtbt_28","text":"漢武留意郡守","sortOrder":12},
  {"id":"s_work_dtbt_28_13","chapterId":"ch_work_dtbt_28","text":"漢武帝天資高明，政自己出，故輔相之任，不甚擇人，若但使之奉行文書而已。其於除用郡守，尤所留意。莊助為會稽太守，數年不聞問，賜書曰：「君厭承明之廬，懷故土，出為郡吏。間者，闊焉久不聞問。」吾丘壽王為東郡都尉，上以壽王為都尉，不復置太守，詔賜璽書曰：「子在朕前之時，知略輻湊，及至連十餘城之守，任四千石之重，職事並廢，盜賊從橫，甚不稱在前時，何也？」汲黯拜淮陽太守，不受印綬，上曰：「君薄淮陽邪？吾今召君矣，顧淮陽吏民不相得，吾徒得君重，臥而治之。」觀此三者，則知郡國之事無細大，未嘗不深知之，為長吏者常若親臨其上，又安有不盡力者乎？惜其為征伐、奢侈所移，使民間不見德澤，為可恨耳！","sortOrder":13},
  {"id":"s_work_dtbt_28_14","chapterId":"ch_work_dtbt_28","text":"苦蕒菜","sortOrder":14},
  {"id":"s_work_dtbt_28_15","chapterId":"ch_work_dtbt_28","text":"吳歸命侯天紀三年八月，有鬼目菜生工人黃耇家，有蕒菜生工人吳平家，高四尺，厚三分，如枇杷形，上廣尺八寸，下莖廣五寸，兩邊生葉綠色。東觀按圖，名鬼目作芝草，蕒菜作平慮草。以耇為侍芝郎，平為平慮郎，皆銀印青綬。唐五行志，中宗景龍二年，岐州郿縣民王上賓家有苦蕒菜，高三尺餘，上廣尺餘，厚二分。說者以為草妖。予按蕒菜即苦蕒，今俗呼為苦（艹馬）者是也。天紀、景龍之事甚相類，歸命次年亡國，中宗後二年遇害，雖事非此致，亦可謂妖矣。平慮草不知何狀，揚雄甘泉賦「幷閭」註，如淳曰：「幷閭，其葉隨時政，政平則平，政不平則傾也。」顏師古曰：「如氏所說自是平慮耳。」然則亦異草也。鬼目，見爾雅，郭璞雲：「今江東有鬼目草，莖似葛，葉圓而毛如耳璫也，赤色叢生。」廣志曰：「鬼目似梅，南人以飲酒。」南方草木狀曰：「鬼目樹，大者如木子，小者如鴨子，七月、八月熟，色黃，味酸，以蜜煑之，滋味柔嘉，交趾諸郡有之。」交州記曰：「高大如木瓜而小，傾邪不周正。」本草曰：「鬼目，一名東方宿，一名連蟲陸，名羊蹄。」","sortOrder":15},
  {"id":"s_work_dtbt_28_16","chapterId":"ch_work_dtbt_28","text":"唐諸生束脩","sortOrder":16},
  {"id":"s_work_dtbt_28_17","chapterId":"ch_work_dtbt_28","text":"唐六典：「國子生初入，置束帛一篚、酒一壺、脩一案，為束脩之禮。太學、四門、律學、書學、算學皆如國子之法。其習經有暇者，命習隸書，幷國語、說文、字林、三蒼、爾雅，每旬前一日，則試其所習業。」乃知唐世士人多攻書，蓋在六館時，以為常習。其說文、字林、蒼、雅諸書，亦欲責以結字合於古義，不特銓選之時，方取楷法遒美者也。束脩之禮，乃於此見之。開元禮載皇子束脩，束帛一篚五匹，酒一壺二斗，脩一案三脡。皇子服學生之服，至學門外，陳三物於西南，少進曰：「某方受業於先生，敢請見。」執篚者以篚授皇子，皇子跪，奠篚，再拜，博士答再拜，皇子還避，遂進跪取篚，博士受幣，皇子拜訖，乃出。其儀如此，州縣學生亦然。","sortOrder":17},
  {"id":"s_work_dtbt_28_18","chapterId":"ch_work_dtbt_28","text":"范德孺帖","sortOrder":18},
  {"id":"s_work_dtbt_28_19","chapterId":"ch_work_dtbt_28","text":"范德孺有一帖，雲：「純粹忝冒固多，尤是家兄北歸，遂解倒懸之念，慶快安幸，此外何求？四月末雇舟離均，借人至鄧，本待家兄之來。今家兄雖得歸潁昌，而尚未聞來耗。已累遣人稟問所行路及相見之期，人尚未還，未知果能如約否。蓋恐太原接人非久到此，法留半月，則須北去也。」予以其時考之，元符三年四月，德孺除知太原，是月二十一日，忠宣公自鄧州分司，復故秩，許歸潁昌府，則此帖當在五月間，忠宣猶未離永州也。德孺自均州守擢帥河東，至於雇舟借人以行，又雲接人法留半月，過此則須北去，雖欲待其兄，亦不可得。今世為長吏，雖居蕞爾小壘，而欲送還兵士，唯意所須。若接人之來，視其私計辦否為遲速耳，未嘗顧法令以自儆策。使申固要束，稍整攝之，置士大夫於無過之地，亦所以善風俗也。","sortOrder":19},
  {"id":"s_work_dtbt_28_20","chapterId":"ch_work_dtbt_28","text":"民不畏死","sortOrder":20},
  {"id":"s_work_dtbt_28_21","chapterId":"ch_work_dtbt_28","text":"老子曰：「民常不畏死，奈何以死懼之？若使人常畏死，則為奇者吾得執而殺之，孰敢？」讀者至此，多以為老氏好殺。夫老氏豈好殺者哉！旨意蓋以戒時君、世主視民為至愚、至賤，輕盡其命，若刈草菅，使之知民情狀，人人能與我為敵國，懍乎常有朽索馭六馬之懼。故繼之曰：「常有司殺者殺。夫代司殺者殺，是代大匠斫。夫代大匠斫，希有不傷其手矣。」下篇又曰：「人之輕死。以其生生之厚，是以輕死。」且人情莫不欲壽，雖衰貧至骨，瀕於餓隸，其與受僇而死有間矣，烏有不畏者哉？自古以來，時運俶擾，至於空天下而為盜賊，及夷考其故，亂之始生，民未嘗有不靖之心也。秦、漢、隋、唐之末，土崩魚爛，比屋可誅。然凶暴如王仙芝、黃巢，不過僥覬一官而已，使君相御之得其道，豈復有滔天之患哉！龔遂之清渤海，馮異之定關中，高仁厚之平蜀盜，王先成之說王宗侃，民情可見。世之君子，能深味老氏之訓，思過半矣。","sortOrder":21},
  {"id":"s_work_dtbt_28_22","chapterId":"ch_work_dtbt_28","text":"天下有奇士","sortOrder":22},
  {"id":"s_work_dtbt_28_23","chapterId":"ch_work_dtbt_28","text":"天下未嘗無魁奇智略之士，當亂離之際，雖一旅之聚，數城之地，必有策策知名者出其間，史傳所書，尚可考也。鄭燭之武、絃高從容立計，以存其國。後世至不可勝紀，在唐尤多，姑摭其小小者數人載於此。","sortOrder":23},
  {"id":"s_work_dtbt_28_24","chapterId":"ch_work_dtbt_28","text":"武德初，北海賊帥綦公順攻郡城，為郡兵所敗，後得劉蘭成以為謀主，才用數十百人，出奇再奮，北海即降。海州臧君相帥衆五萬來爭，蘭成以敢死士二十人夜襲之，掃空其衆。","sortOrder":24},
  {"id":"s_work_dtbt_28_25","chapterId":"ch_work_dtbt_28","text":"徐圓朗據海岱，或說之曰：「有劉世徹者，才略不世出，名高東夏，若迎而奉之，天下指揮可定。」圓朗使迎之。世徹至，已有衆數千，圓朗使徇譙、杞，東人素聞其名，所向皆下。","sortOrder":25},
  {"id":"s_work_dtbt_28_26","chapterId":"ch_work_dtbt_28","text":"裘甫亂浙東，朝廷遣王式往討，其黨劉暀勸甫引兵取越，憑城郭，據府庫，循浙江築壘以拒之，得間則長驅進取浙西，過大江，掠揚州，還修石頭城而守之，宣歙、江西必有響應者，別以萬人循海而南，襲取福、建，則國家貢賦之地，盡入於我矣。甫不能用。","sortOrder":26},
  {"id":"s_work_dtbt_28_27","chapterId":"ch_work_dtbt_28","text":"高駢之將畢師鐸攻駢，乞師於宣州秦彥，彥兵至，遂下揚州。師鐸遣使趣彥過江，將奉以為主。或說之曰：「僕射順衆心為一方去害，宜復奉高公而佐之，總其兵權，誰敢不服？且秦司空為節度使，廬州、壽州其肯為之下乎？切恐功名成敗未可知也。不若亟止秦司空勿使過江，彼若粗識安危，必未敢輕進，就使他日責我以負約，猶不失為高氏忠臣也。」師鐸不以為然，明日，以告鄭漢章，漢章曰：「此智士也。」求之，弗獲。","sortOrder":27},
  {"id":"s_work_dtbt_28_28","chapterId":"ch_work_dtbt_28","text":"王建鎮成都，攻楊晟於彭州，久不下，民皆竄匿山穀，諸寨日出抄掠之。王先成往說其將王宗侃曰：「民入山穀，以俟招安，今乃從而掠之，與盜賊無異。旦出淘虜，薄暮乃返，曾無守備之意，萬一城中有智者為之畫策，使乘虛奔突，先伏精兵於門內，望淘虜者稍遠，出弓弩手礮各百人，攻寨之一面，又於三面各出耀兵，諸寨鹹自備禦，無暇相救，如此能無敗乎？」宗侃矍然。先成為條列七事為狀，以白王建，建即施行之。榜至三日，山中之民，競出如歸市，浸還故業。","sortOrder":28},
  {"id":"s_work_dtbt_28_29","chapterId":"ch_work_dtbt_28","text":"觀此五者，則其他姓名不傳，與草木俱腐者，蓋不可勝計矣。","sortOrder":29},
  {"id":"s_work_dtbt_28_30","chapterId":"ch_work_dtbt_28","text":"易卦四德","sortOrder":30},
  {"id":"s_work_dtbt_28_31","chapterId":"ch_work_dtbt_28","text":"易元、亨、利、貞，謂之四德，唯乾、坤為能盡之。若屯、隨二卦，但大亨貞。臨、無妄、革三卦，皆大亨以正而已。有亨、利、貞者十一，蒙、同人、離、鹹、兌、恆、遯、萃、渙、小過、既濟也。元、亨、利者一，蠱也。利、貞者八，大畜、大壯、明夷、家人、中孚、蹇、損、漸也。亨、貞者三，需、困、旅也。元、亨者三，大有、升、鼎也。亨、利者五，賁、復、大過、巽、噬嗑也。亨者九，小畜、履、泰、謙、節、坎、震、豐、未濟也。利者五，訟、豫、解、益、夬也。貞者四，師、比、否、頤也。唯八卦皆無之，觀、剝、晉、睽、姤、歸妹、井、艮也。若以卦象索之，如剝、睽、姤猶可強為之辭，他則不復容擬議矣。","sortOrder":31},
  {"id":"s_work_dtbt_28_32","chapterId":"ch_work_dtbt_28","text":"孫堅起兵","sortOrder":32},
  {"id":"s_work_dtbt_28_33","chapterId":"ch_work_dtbt_28","text":"董卓盜國柄，天下共興義兵討之，惟孫堅以長沙太守先至，為卓所憚，獨為有功。故裴松之謂其最有忠烈之稱。然長沙為荊州屬部，受督於刺史王叡。叡先與堅共擊零、桂賊，以堅武官，言頗輕之。及叡舉兵欲討卓，堅乃承案行使者，詐檄殺之，以償曩忿。南陽太守張咨，鄰郡二千石也，以軍資不具之故，又收斬之。是以區區一郡將，乘一時兵威，輒害方伯、鄰守，豈得為勤王乎？劉表在荊州，乃心王室，袁術志於逆亂，堅乃奉其命而攻之，自速其死，皆可議也。","sortOrder":33},
  {"id":"s_work_dtbt_28_34","chapterId":"ch_work_dtbt_28","text":"孫權封兄策","sortOrder":34},
  {"id":"s_work_dtbt_28_35","chapterId":"ch_work_dtbt_28","text":"孫權即帝位，追尊兄策為長沙王，封其子為吳侯。按孫氏奄有江、漢，皆策之功，權特承之耳，而報之之禮不相宜稱。故陳壽評雲：「割據江東，策之基兆也，而權尊崇未至，子止侯爵，於義儉矣。」而孫盛乃雲：「權遠思盈虛之數，正本定名，防微於未兆，可謂為之於未有，治之於未亂。」其說迂謬如此。漢室中興，出於伯升，光武感其功業之不終，建武二年，首封其二子為王，而帝子之封，乃在一年之後。司馬昭繼兄師秉魏政，以次子攸為師後，常雲：「天下者景王之天下。」欲以大業歸攸。以孫權視之，不可同日論也。","sortOrder":35},
  {"id":"s_work_dtbt_28_36","chapterId":"ch_work_dtbt_28","text":"踰年改元","sortOrder":36},
  {"id":"s_work_dtbt_28_37","chapterId":"ch_work_dtbt_28","text":"自漢武帝建元紀年之後，嗣君紹統，必踰年乃改元。雖安帝繼殤帝，亦終延平而為永初。桓帝繼質帝，亦終本初而為建和。唐宣宗以叔繼侄，亦終會昌六年，而改大中。獨本朝太祖以開寶九年十月二十日上仙，太宗嗣位，是年十二月二十二日改為太平興國元年，去新歲纔八日耳。意當時星辰曆象考卜兆祥，必有其說，而國史傳記皆失傳。竊計嶺、蜀之遠，製書到時已是二年之春。是時，宰相薛居正、沈倫、盧多遜失於不考引故實，致行之弗審，使人君即位而無元年，尤為不可也。若唐順宗以貞元二十一年正月嗣位，至八月辛丑，改元永貞。蓋已稱太上皇，嫌於獨無紀年，故亟更之耳。劉禪、孫亮、石宏、苻生、李璟未逾年而改，此不足責。晉惠帝改武帝太熙為永熙，而以為欲長奉先皇之製，亦非也。唐中宗仍武後神龍，梁末帝追承太祖乾化，孟昶仍父知祥明德，漢劉知遠追用晉天福，隱帝仍父乾祐，周世宗仍太祖顯德，皆非禮之正，無足議者。唐哀帝仍昭宗天祐，蓋畏朱溫而不敢雲。","sortOrder":37},
  {"id":"s_work_dtbt_28_38","chapterId":"ch_work_dtbt_28","text":"賊臣遷都","sortOrder":38},
  {"id":"s_work_dtbt_28_39","chapterId":"ch_work_dtbt_28","text":"自漢以來，賊臣竊國命，將欲移鼎，必先遷都以自便。董卓以山東兵起，謀徙都長安，驅民數百萬口，更相蹈藉，悉燒宮廟、官府、居家，二百里內無復鷄犬。高歡自洛陽遷魏於鄴，四十萬戶狼狽就道。朱全忠自長安遷唐於洛，驅徙士民，毀宮室百司，及民間廬舍，長安自是丘墟。卓不旋踵而死，曹操迎天子都許，卒覆劉氏。魏、唐之祚，竟為高、朱所傾。凶盜設心積慮，由來一揆也。","sortOrder":39},
  {"id":"s_work_dtbt_28_40","chapterId":"ch_work_dtbt_28","text":"輿地道里誤","sortOrder":40},
  {"id":"s_work_dtbt_28_41","chapterId":"ch_work_dtbt_28","text":"古今輿地圖志所記某州至某州若幹里，多有差誤。偶閱元祐九域志，姑以吾鄉饒州證之，饒西至洪州三百八十里，而志雲：「西至州界一百七十里，自界首至洪五百六十八里。」於洪州書至饒，又衍二十里，是為七百六十里也。饒至信州三百七十里，而志雲：「東南至本州界二百九十里，自界首至信州三百五十里。」是為六百四十里也。饒至池州四百八十里，而志雲：「北至州界一百九十里，自界首至池州三百八十里。」是為五百七十里也。唐賈耽皇華四達記所紀中都至外國，尤為詳備，其書虔州西南一百十里至潭口驛，又百里至南康縣。然今虔至潭口纔四十里，又五十里即至南康，比之所載不及半也。以所經行處驗之，知其他不然者多矣。","sortOrder":41},
  {"id":"s_work_dtbt_28_42","chapterId":"ch_work_dtbt_28","text":"容齋續筆","sortOrder":42},
  {"id":"s_work_dtbt_29_1","chapterId":"ch_work_dtbt_29","text":"卷第十一(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_29_2","chapterId":"ch_work_dtbt_29","text":"古錞於","sortOrder":2},
  {"id":"s_work_dtbt_29_3","chapterId":"ch_work_dtbt_29","text":"周禮：「鼓人掌教六鼓四金之音聲，以節聲樂。」四金者，錞、鐲、鐃、鐸也。「以金錞和鼓」。鄭氏註雲：「錞，錞於也，圜如碓頭，大上小下，樂作鳴之，與鼓相和。」賈公彥疏雲：「錞於之名，出於漢之大予樂官。」南齊始興王鑑為益州刺史，廣漢什邡民段祚以錞於獻鑑，古禮器也，高三尺六寸六分，圍二尺四寸，圓如筩，銅色黑如漆，甚薄，上有銅馬，以繩縣馬，令去地尺餘，灌之以水，又以器盛水於下，以芒莖當心跪註錞於，以手振芒，則其聲如雷，清響良久乃絕，古所以節樂也。周斛斯徵精三禮，為太常卿。自魏孝武西遷，雅樂廢缺，樂有錞於者，近代絕無此器，或有自蜀得之，皆莫之識。徵曰：「此錞於也。」衆弗之信，遂依幹寶周禮註以芒筒捋之，其聲極清，乃取以合樂焉。宣和博古圖說雲「其製中虛，椎首而殺其下」，王黼亦引段祚所獻為證雲。今樂府金錞，就擊於地，灌水之製，不復考矣。是時，有虎龍錞一，山紋錞一，圜花錞一，縶馬錞一，龜魚錞一，魚錞二，鳳錞一，虎錞七。其最大者重五十一斤，小者七斤。淳熙十四年，澧州慈利縣周赧王墓旁五里山摧，蓋古冢也，其中藏器物甚多。予甥餘玠宰是邑，得一錞，高一尺三寸，上徑長九寸五分，闊八寸，下口長徑五寸八分，闊五寸，虎鈕高一寸二分，闊寸一分，幷尾長五寸五分，重十三斤。紹熙三年，予仲子簽書峽州判官，於長楊縣又得其一，甚大，高二尺，上徑長一尺六分，闊一尺四寸二分，下口長徑九寸五分，闊八寸，虎鈕高二寸五分，足闊三寸四分，幷尾長一尺，重三十五斤。皆虎錞也。予家蓄古彝器百種，此遂為之冠。小錞無損缺，扣之，其聲清越以長。大者破處五寸許，聲不能渾全，然亦可考擊也。後復得一枚，與大者無小異，自峽來，置諸篛籠中，取者不謹，斷其鈕，匠以藥銲而柵之，遂兩兩相對。若三禮圖、景祐大樂圖所畫，形製皆非。東坡志林記始興王鑑一節，雲：「記者能道其尺寸之詳如此，而拙於遣詞，使古器形製不可復得其髣髴，甚可恨也。」正為此雲。","sortOrder":3},
  {"id":"s_work_dtbt_29_4","chapterId":"ch_work_dtbt_29","text":"孫玉汝","sortOrder":4},
  {"id":"s_work_dtbt_29_5","chapterId":"ch_work_dtbt_29","text":"韓莊敏公縝字玉汝，蓋取君子以玉比德，縝密以栗，及王欲玉汝之義，前人未嘗用，最為古雅。按唐登科記，會昌四年及第進士有孫玉汝。李景讓為御史大夫，劾罷侍御史孫玉汝。會稽大慶寺碑，鹹通十一年所立，雲衢州刺史孫玉汝記。榮王宗綽書目，有南北史選練十八卷，雲孫玉汝撰。蓋其人也。","sortOrder":5},
  {"id":"s_work_dtbt_29_6","chapterId":"ch_work_dtbt_29","text":"唐人避諱","sortOrder":6},
  {"id":"s_work_dtbt_29_7","chapterId":"ch_work_dtbt_29","text":"唐人避家諱甚嚴，固有出於禮律之外者。李賀應進士舉，忌之者斥其父名晉肅，以晉與進字同音，賀遂不敢試。韓文公作諱辯，論之至切，不能解衆惑也。舊唐史至謂韓公此文，為文章之紕繆者，則一時橫議可知矣。杜子美有送李二十九弟晉肅入蜀詩，蓋其人雲。裴德融諱「皋」，高鍇以禮部侍郎典貢舉，德融入試，鍇曰：「伊諱『皋』，向某下就試，與及第，困一生事。」後除屯田員外郎，與同除郎官一人，同參右丞盧簡求。到宅，盧先屈前一人入，前人啟雲：「某與新除屯田裴員外同祗候。」盧使驅使官傳語曰：「員外是何人下及第？偶有事，不得奉見。」裴蒼遽出門去。觀此事，尤為乖剌。鍇、簡求皆當世名流，而所見如此。語林載崔殷夢知舉，吏部尚書歸仁晦託弟仁澤，殷夢唯唯而已。無何，仁晦復詣託之，至於三四。殷夢斂色端笏，曰：「某見進表讓此官矣。」仁晦始悟己姓，殷夢諱也。按宰相世系表，其父名龜從，此又與高相類。且父名晉肅，子不得舉進士，父名皋，子不得於主司姓高下登科，父名龜從，子不列姓歸人於科籍，揆之禮律，果安在哉？後唐天成初，盧文紀為工部尚書，新除郎中於鄴公參，文紀以父名嗣業，與同音，竟不見。鄴憂畏太過，一夕雉經於室。文紀坐謫石州司馬。此又可怪也。","sortOrder":7},
  {"id":"s_work_dtbt_29_8","chapterId":"ch_work_dtbt_29","text":"高鍇取士","sortOrder":8},
  {"id":"s_work_dtbt_29_9","chapterId":"ch_work_dtbt_29","text":"高鍇為禮部侍郎，知貢舉，閱三歲，頗得才實。始，歲取四十人，才益少，詔減十人猶不能滿。此新唐書所載也。按登科記，開成元年，中書門下奏：「進士元額二十五人，請加至四十人。」奉敕依奏。是年及二年、三年，鍇在禮部，每舉所放，各四十人。至四年，始令每年放三十人為定，則唐書所雲誤矣。摭言載鍇第一牓裴思謙以仇士良關節取狀頭，鍇庭譴之。思謙回顧厲聲曰：「明年打脊取狀頭。」第二年，鍇知舉，誡門下不得受書題。思謙自攜士良一緘入貢院，既而易紫衣趨至階下，白曰：「軍容有狀薦裴思謙秀才。」鍇接之，書中與求巍峨。鍇曰：「狀元已有人，此外可副軍容意旨。」思謙曰：「卑吏奉軍容處分：『裴秀才非狀元請侍郎不放。』」鍇俛首良久，曰：「然則略要見裴學士。」思謙曰：「卑吏便是也。」鍇不得已，遂從之。思謙及第後宿平康里，賦詩雲：「銀釭斜背解明璫，小語低聲賀玉郎。從此不知蘭麝貴，夜來新惹桂枝香。」然則思謙亦疎俊不羈之士耳。鍇徇凶璫之意，以為舉首，史謂頗得才，實恐未盡然。先是，大和三年，鍇為考功員外郎，取士有不當，監察御史姚中立奏停考功別頭試，六年，侍郎賈餗又奏復之，事見選舉志。","sortOrder":9},
  {"id":"s_work_dtbt_29_10","chapterId":"ch_work_dtbt_29","text":"兵部名存","sortOrder":10},
  {"id":"s_work_dtbt_29_11","chapterId":"ch_work_dtbt_29","text":"唐因隋製，尚書置六曹。吏部、兵部分掌銓選，文屬吏部，武屬兵部。自三品以上官冊授，五品以上製授，六品以下敕授，皆委尚書省奏擬。兩部各列三銓。曰尚書銓，尚書主之。曰東銓，曰西銓，侍郎二人主之。吏居左，兵居右，是為前行。故兵部班級在戶、刑、禮之上。睿宗初政，以宋璟為吏部尚書，李乂、盧從願為侍郎；姚元之為兵部尚書，陸象先、盧懷慎為侍郎。六人皆名臣，二選稱治。其後用人不能悉得賢，然兵部為甚。其變而為三班流外銓，不知自何時。元豐官製行，一切更改，凡選事，無論文武，悉以付吏部。蘇東坡當元祐中拜兵書，謝表雲：「恭惟先帝復六卿之名，本欲後人識三代之舊，古今殊製，閒劇異宜，武選隸於天官，兵政總於樞輔，故司馬之職，獨省文書。」蓋紀其實也。今本曹所掌，惟諸州廂軍名籍，及每大禮，則書寫蕃官加恩告。雖有所轄司局，如金吾街仗司、騏驥車輅象院、法物庫、儀鸞司，不過每季郎官一往耳。名存實亡，一至於是！","sortOrder":11},
  {"id":"s_work_dtbt_29_12","chapterId":"ch_work_dtbt_29","text":"武官名不正","sortOrder":12},
  {"id":"s_work_dtbt_29_13","chapterId":"ch_work_dtbt_29","text":"文官郎、大夫，武官將軍、校尉，自秦、漢以來有之。至於階秩品著，則由晉、魏至唐始定。唐文散階二十九，自開府、特進之下，為大夫者十一，為郎者十六。武散階四十五，為將軍者十二，為校尉者十六。此外懷化、歸德大將軍，訖於司戈、執戟，皆以待蕃戎之君長臣僕。本朝因之。元豐正官製，廢文散階，而易舊省部寺監名，稱為郎、大夫，曰寄祿官。政和中，改選人七階亦為郎，欲以將軍、校尉易橫行以下諸使至三班借職，而西班用事者嫌其塗轍太殊，亦請改為郎、大夫，於是以卒伍廝圉玷汙此名，又以節度使至刺史專為武臣正任。且郎、大夫，漢以處名流，觀察使在唐為方伯，刺史在漢為監司，在唐為郡守，豈介冑恩倖所得處哉？此其名尤不正者也。","sortOrder":13},
  {"id":"s_work_dtbt_29_14","chapterId":"ch_work_dtbt_29","text":"名將晚謬","sortOrder":14},
  {"id":"s_work_dtbt_29_15","chapterId":"ch_work_dtbt_29","text":"自古威名之將，立蓋世之勛，而晚謬不克終者，多失於恃功矜能而輕敵也。關羽手殺袁紹二將顏良、文醜於萬衆之中。及攻曹仁於樊，於禁等七軍皆沒，羽威震華夏，曹操議徙許都以避其銳，其功名盛矣。而不悟呂蒙、陸遜之詐，竟墮孫權計中，父子成禽，以敗大事。西魏王思政鎮守玉壁，高歡連營四十里攻圍之，饑凍而退。及思政徙荊州，舉韋孝寬代己，歡舉山東之衆來攻，凡五十日，復以敗歸，皆思政功也。其後欲以長社為行臺治所，致書於崔猷，猷曰：「襄城控帶京洛，當今要地，如其動靜，易相應接。潁川鄰寇境，又無山川之固，莫若頓兵襄城，而遣良將守潁川，則表裏俱固，人心易安，縱有不虞，豈足為患。」宇文泰令依猷策，思政固請，且約，賊水攻期年、陸攻三年之內，朝廷不煩赴救。已而陷於高澄，身為俘虜。慕容紹宗挫敗侯景，一時將帥皆莫及，而攻圍潁川，不知進退，赴水而死。吳明徹當陳國衰削之餘，北伐高齊，將略人才，公卿以為舉首，師之所至，前無堅城，數月之間，盡復江北之地。然其後攻周彭城，為王軌所困，欲遏歸路。蕭摩訶請擊之，明徹不聽，曰：「搴旗陷陳，將軍事也，長算遠略，老夫事也。」一旬之間，水路遂斷。摩訶又請潛軍突圍，復不許，遂為周人所執，將士三萬皆沒焉。此四人之過，如出一轍。","sortOrder":15},
  {"id":"s_work_dtbt_29_16","chapterId":"ch_work_dtbt_29","text":"唐帝稱太上皇","sortOrder":16},
  {"id":"s_work_dtbt_29_17","chapterId":"ch_work_dtbt_29","text":"唐諸帝稱太上皇者，高祖、睿宗、明皇、順宗凡四君。順宗以病廢之故，不能臨政，高祖以秦王殺建成、元吉，明皇幸蜀，為太子所奪，唯睿宗上畏天戒，發於誠心，為史冊所表。然以事考之，睿宗以先天元年八月，傳位於皇太子，猶五日一受朝，三品以上除授，及大刑政皆自決之。故皇帝之子嗣直、嗣謙、嗣昇封王，皆以上皇誥而出命。又遣皇帝巡邊。二年七月甲子，太平公主誅，明日乙丑，即歸政。然則猶有不獲已也。若夫與堯、舜合其德，則我高宗皇帝、至尊壽皇聖帝為然。","sortOrder":17},
  {"id":"s_work_dtbt_29_18","chapterId":"ch_work_dtbt_29","text":"楊倞註荀子","sortOrder":18},
  {"id":"s_work_dtbt_29_19","chapterId":"ch_work_dtbt_29","text":"唐楊倞註荀子，乃元和十三年。然臣道篇所引：「書曰，從命而不拂，微諫而不倦，為上則明，為下則遜。」註以為伊訓篇，今元無此語。致士篇所引曰：「義刑義殺，勿庸以即，汝惟曰未有順事。」註以為康誥，而不言其有不同者。","sortOrder":19},
  {"id":"s_work_dtbt_29_20","chapterId":"ch_work_dtbt_29","text":"昭宗相朱朴","sortOrder":20},
  {"id":"s_work_dtbt_29_21","chapterId":"ch_work_dtbt_29","text":"唐昭宗出幸華州，方強藩悍鎮，遠近為梗，思得特起奇士任之，以成中興之業。水部郎中何迎，表薦國子博士朱朴才如謝安，朴所善方士許巖士得幸，出入禁中，亦言朴有經濟才。上連日召對，朴有口辯，上悅之，曰：「朕雖非太宗，得卿如魏徵矣。」上憤天下之亂，朴自言得為宰相，月餘可致太平。遂拜為相，製出，中外大驚。唐製詔有製詞，學士韓儀所撰，曰：「夢傅巖而得真相，則商道中興；獵渭濱而載獻臣，則周朝致理。朕自逢多難，渴竚英賢，暗禱鬼神，明祈日月。果得哲輔，契予勤求。朱朴學業優深，識用精敏，久徊翔而不振，彌貞吉以自多。朕知其才，遂召與語。理亂立分於言下，聞所未聞；兵農皆在於術中，得所未得。不覺前席，為之改容；須委化權，用昌衰運。自我拔奇，寧拘品秩；百度羣倫，俟爾康濟。」其美如此。儀者偓之兄，所謂「暗禱鬼神，明祈日月」之語，必當時所授旨意也。朴為相纔半年而罷。後貶郴州司戶參軍，製雲：「不為自審之謀，苟竊相援之力，實因奸幸，潛致顯榮。亦謂術可弭兵，學能活國，冒半歲容身之贊，無一朝輔政之功。唯辱中台，頗興羣論。」嗚呼！昭宗當王室艱危之際，無知人之明，拔朴於庶僚中，位諸公袞，以今觀之，適足詒後人譏笑。新史贊謂：「捭豚臑而拒貙牙，趣亡而已。」悲夫！","sortOrder":21},
  {"id":"s_work_dtbt_29_22","chapterId":"ch_work_dtbt_29","text":"楊國忠諸使","sortOrder":22},
  {"id":"s_work_dtbt_29_23","chapterId":"ch_work_dtbt_29","text":"楊國忠為度支郎，領十五餘使。至宰相，凡領四十餘使。第署一字不能盡，胥吏因是恣為奸欺。新、舊唐史皆不詳載其職。按其拜相製前銜雲：「御史大夫判度支，權知太府卿事，兼蜀郡長史，劍南節度支度、營田等副大使，本道兼山南西道采訪處置使，兩京太府、司農、出納、監倉、祠祭、米炭、宮市、長春九成宮等使，關內道及京畿采訪處置使，拜右相兼吏部尚書、集賢殿崇文館學士、修國史、太清太微宮使。」自餘所領，又有管當租庸、鑄錢等使。以是觀之，概可見矣。宮市之事，鹹謂起於德宗貞元。不知天寶中已有此名，且用宰臣充使也。韓文公作順宗實錄，但雲：「舊事，宮中有要市外物，令官吏主之，與人為市，隨給其直，貞元末以宦者為使。」亦不及天寶時已有之也。","sortOrder":23},
  {"id":"s_work_dtbt_29_24","chapterId":"ch_work_dtbt_29","text":"祖宗朝宰輔","sortOrder":24},
  {"id":"s_work_dtbt_29_25","chapterId":"ch_work_dtbt_29","text":"祖宗朝，宰輔名為禮絕百僚，雖樞密副使，亦在太師一品之上。然至其罷免歸班，則與庶位等。李崇矩自樞密使罷為鎮國軍節度使，旋改左衞大將軍，遂為廣南西道都巡檢使，未幾遣使賫詔徙海南四州都巡檢使，皆非降黜。在南累年，入判金吾街仗司而卒，猶贈太尉。趙安仁嘗參知政事，而判登聞鼓院。張鎔嘗知樞密院，而監諸司庫務。曾孝寬以簽書樞密，服闋，而判司農寺。張宏、李惟清皆自見任樞密副使徙御史中丞。其他以前執政而為三司使、中丞者數人。官製既行，猶多除六曹尚書。自崇寧以來，乃始不然。","sortOrder":25},
  {"id":"s_work_dtbt_29_26","chapterId":"ch_work_dtbt_29","text":"百官避宰相","sortOrder":26},
  {"id":"s_work_dtbt_29_27","chapterId":"ch_work_dtbt_29","text":"劉器之以待製為樞密都承旨，道遇執政出尚書省，相從歸府第，劉去席帽涼衫，斂馬遣人傳語，相揖而過。左相呂汲公歸，呼門下省法吏，問從官道逢宰相如何？吏檢條，但有尚書省官避令僕，兩省官各避其官長，而無兩製避宰相之法，汲公乃止，而心甚不樂。劉以此語人，以為有所據。然以事體揆之，侍從不避宰相，恐為不然，亦無所謂只避官長法，劉公蓋飾說耳。按天聖編敕，諸文武官與宰相相遇於路皆退避，見樞密使、副參知政事，避路同宰相，其文甚明，不應元祐時不行用也。","sortOrder":27},
  {"id":"s_work_dtbt_29_28","chapterId":"ch_work_dtbt_29","text":"百官見宰相","sortOrder":28},
  {"id":"s_work_dtbt_29_29","chapterId":"ch_work_dtbt_29","text":"天聖編敕載文武百官見宰相儀。文明殿學士至龍圖閣直學士，列班於都堂階上，堂吏贊雲：「請，不拜，班首前致詞，訖，退，歸位，列拜。宰相答拜。」兩省官相次同學士之儀。上將軍、大將軍、將軍、御史臺官，及南班文武百僚，序班於中書門外，應節度使至刺史，並綴本班，中丞揖訖，入。宰相降階，南向立於位，乃稱班，文東武西，並北上，臺官南行，北向東上。贊雲：「百僚拜，宰相答拜，訖，退。」內客省使至閤門使見宰相、樞密使，並階上列行拜，不答拜；見參知政事、樞密副使、宣徽使，客禮展拜；皇城使以下諸司使、橫行副使見宰相、樞密使，並階下連姓稱職展拜，不答拜；見參政副樞，並列行拜。若諸司副使、閤門祗候見參樞，亦不答拜。國朝上下等威，其嚴如此。已而浸廢。文潞公、富韓公至和中自外鎮拜相，詔百官班迎於門，言者乃謂隆之以虛禮。元豐定官製，王禹玉、蔡持正為僕射，上日，始用此禮。其後復不行。乾道初，魏仲昌以樞密吏寅緣得副承旨，每謁公府，與侍從同席升車而去。葉子昂為相，獨抑之，使與卿監旅進，送之於右序，不索馬。及王抃以國信所典儀吏為都承旨，且正任觀察使，禮遂均從官矣。","sortOrder":29},
  {"id":"s_work_dtbt_29_30","chapterId":"ch_work_dtbt_29","text":"東坡自引所為文","sortOrder":30},
  {"id":"s_work_dtbt_29_31","chapterId":"ch_work_dtbt_29","text":"東坡為文潞公作德威堂銘，雲：「元祐之初，起公以平章軍國重事，期年，乃求去，詔曰：『昔西伯善養老，而太公自至。魯穆公無人子思之側，則長者去之。公自為謀則善矣，獨不為朝廷惜乎！』又曰：『唐太宗以幹戈之事，尚能起李靖於既老，而穆宗、文宗以燕安之際，不能用裴度於未病。治亂之效，於斯可見。』公讀詔聳然，不敢言去。」按此二詔，蓋元祐二年三月潞公乞致仕不允批答，皆坡所行也。又繳還乞罷青苗狀雲：「近日謫降呂惠卿告詞雲，首建青苗，次行助役。」亦坡所作。張文定公墓志載嘗論次其文凡三百二十字，結之雲：「世以軾為知言。」又述諫用兵雲：「老臣且死，見先帝地下，有以藉口矣。」亦其所作也。幷引責呂惠卿詞亦然。乾道中，邁直翰苑，答陳敏步帥詔雲：「亞夫持重，小棘門、霸上之將軍；不識將屯，冠長樂、未央之衞尉。」後為敏作神道碑，亦引之，正以公為法也。","sortOrder":31},
  {"id":"s_work_dtbt_29_32","chapterId":"ch_work_dtbt_29","text":"容齋續筆","sortOrder":32},
  {"id":"s_work_dtbt_30_1","chapterId":"ch_work_dtbt_30","text":"卷第十二(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_30_2","chapterId":"ch_work_dtbt_30","text":"婦人英烈","sortOrder":2},
  {"id":"s_work_dtbt_30_3","chapterId":"ch_work_dtbt_30","text":"婦人女子，婉孌閨房，以柔順靜專為德，其遇哀而悲，臨事而惑，蹈死而懼，蓋所當然爾。至於能以義斷恩，以智決策，斡旋大事，視死如歸，則幾於烈丈夫矣。齊湣王失國，王孫賈從王，失王之處。其母曰：「汝朝出而晚來，則吾倚門而望；汝暮出而不還，則吾倚閭而望。汝今事王，不知王處，汝尚何歸？」賈乃入市，呼市人攻殺淖齒，而齊亡臣相與求王子立之，卒以復國。馬超叛漢，殺刺史、太守。涼州參軍楊阜出見薑敍於歷城，與議討賊。敍母曰：「韋使君遇難，亦汝之負，但當速發，勿復顧我。」敍乃與趙昂合謀。超取昂子月為質，昂謂妻異曰：「當奈月何？」異曰：「雪君父之大恥，喪元不足為重，況一子哉！」超襲歷城，得敍母，母駡之曰：「汝背父殺君，天地豈久容汝，敢以面目視人乎？」超殺之，月亦死。晉卞壼拒蘇峻，戰死，二子隨父後，亦赴敵而亡。其母拊尸哭曰：「父為忠臣，子為孝子，夫何恨乎！」秦苻堅將伐晉，所幸張夫人引禹、稷、湯、武事以諫曰：「朝野之人，皆言晉不可伐，陛下獨決意行之？」堅不聽，曰：「軍旅之事，非婦人所當預也。」劉裕起兵討逆，同謀孟昶謂妻周氏曰：「我決當作賊，幸早離絕。」周氏曰：「君父母在堂，欲建非常之謀，豈婦人所能諫。事之不成，當於奚官中奉養大家，義無歸志也。」昶起，周氏追昶坐，曰：「觀君舉措，非謀及婦人者，不過欲得財物耳。」指懷中兒示之曰：「此兒可賣，亦當不惜！」遂傾貲以給之。何無忌夜草檄文，其母，劉牢之姊也，登橙密窺之，泣曰：「汝能如此，吾復何恨！」問所與同謀者，曰：「劉裕。」母尤喜，因為言舉事必有成之理以勸之。竇建德救王世充，唐拒之於虎牢。建德妻曹氏勸使乘唐國之虛，西抄關中，唐必還師自救。建德曰：「此非女子所知。」李克用困於上源驛，左右先脫歸者，以汴人為變告其妻劉氏，劉神色不動，立斬之，陰召大將約束，謀保軍以還。克用歸，欲勒兵攻汴，劉氏曰：「公當訴之於朝廷，若擅舉兵相攻，天下孰能辨其曲直？」克用乃止。黃巢死，時溥獻其姬妾。僖宗宣問曰：「汝曹皆勳貴子女，何為從賊？」其居首者對曰：「狂賊凶逆，國家以百萬之衆，失守宗祧。今陛下以不能拒賊，責一女子，置公卿將帥於何地乎？」上不復問，戮之於市。餘人皆悲怖昏醉，獨不飲不泣，至於就刑，神色肅然。唐莊宗臨斬劉守光，守光悲泣哀祈不已，其二妻李氏、祝氏譙之曰：「事已如此，生復何益？妾請先死。」即伸頸就戮。劉仁贍守壽春，幼子崇諫夜泛舟渡淮北，仁贍命斬之。監軍使求救於夫人，夫人曰：「妾於崇諫，非不愛也，然軍法不可私，若貸之，則劉氏為不忠之門矣。」趣命斬之，然後成喪。王師圍金陵，李後主以劉澄為潤州節度使，澄開門降越。後主誅其家，澄女許嫁未適，欲活之。女曰：「叛逆之餘，義不求生。」遂就死。此十餘人者，義風英氣，尚凜凜有生意也。雖載於史策，聊表出之。至於唐高祖起兵太原，女平陽公主在長安，其夫柴紹曰：「尊公將以兵清京師，我欲往，恐不能偕，奈何？」主曰：「公往矣！我自為計。」即奔鄠，發家貲招南山亡命，諭降羣盜，申法誓衆，勒兵七萬，威振關中，與秦王會渭北，分定京師。此其偉烈，又非他人比也。","sortOrder":3},
  {"id":"s_work_dtbt_30_4","chapterId":"ch_work_dtbt_30","text":"無用之用","sortOrder":4},
  {"id":"s_work_dtbt_30_5","chapterId":"ch_work_dtbt_30","text":"莊子雲：「人皆知有用之用，而莫知無用之用。」又雲：「知無用，而始可與言用矣。夫地非不廣且大也，人之所用，容足耳。然則廁足而墊之致黃泉，所謂無用之為用也亦明矣。」此義本起於老子「三十輻共一轂，當其無，有車之用」一章。學記：「鼓無當於五聲，五聲弗得不備；水無當於五色，五色弗得不章。」其理一也。今夫飛者以翼為用，縶其足，則不能飛。走者以足為用，縛其手，則不能走。舉場較藝，所務者才也，而拙鈍者亦為之用。戰陳角勝，所先者勇也，而老怯者亦為之用。則有用、無用，若之何而可分別哉？故為國者，其勿以無用待天下之士，則善矣！","sortOrder":5},
  {"id":"s_work_dtbt_30_6","chapterId":"ch_work_dtbt_30","text":"龍筋鳳髓判","sortOrder":6},
  {"id":"s_work_dtbt_30_7","chapterId":"ch_work_dtbt_30","text":"唐史稱張鷟早慧絕倫，以文章瑞朝廷，屬文下筆輒成，八應製舉，皆甲科。今其書傳於世者，朝野僉載、龍筋鳳髓判也。僉載紀事，皆瑣尾擿裂，且多媟語。百判純是當時文格，全類俳體，但知堆垜故事，而於蔽罪議法處不能深切，殆是無一篇可讀，一聯可味。如白樂天甲乙判則讀之愈多，使人不厭。聊載數端於此：「甲去妻，後妻犯罪，請用子蔭贖罪，甲不許。判雲：『不安爾室，盡孝猶慰母心；薄送我畿，贖罪寧辭子蔭？縱下山之有恕，曷陟屺之無情？』」「辛夫遇盜而死，求殺盜者，而為之妻。或責其失節，不伏。判雲：『夫不報，未足為非；婦道有虧，誠宜自恥。詩著靡他之誓，百代可知；禮垂不嫁之文，一言以蔽。』」「丙居喪，年老毀瘠，或非其過禮，曰：『哀情所鍾。』判雲：『況血氣之既衰，老夫耄矣；縱哀情之罔極，吾子忍之。』」「丙妻有喪，丙於妻側奏樂，妻責之，不伏。判雲：『儼衰麻之在躬，是吾憂也；調絲竹以盈耳，於汝安乎？』」「甲夜行，所由執之，辭雲：『有公事，欲早趨朝，所由以犯禁不聽。』判雲：『非巫馬為政，焉用出以戴星？同宣子俟朝，胡不退而假寐？』」「乙貴達，有故人至，坐之堂下，進以僕妾之食，曰：『故辱而激之。』判雲：『安實敗名，重耳竟慚於舅犯；感而成事，張儀終謝於蘇秦。』」「丙娶妻，無子，父母將出之，辭曰：『歸無所從。』判雲：『雖配無生育，誠合比於斷絃；而歸靡適從，度可同於束縕。』」「乙為三品，見本州刺史不拜，或非之，稱：『品同』。判雲：『或商、周不敵，敢不盡禮事君；今晉、鄭同儕，安得降階卑我？』」若此之類，不背人情，合於法意，援經引史，比喻甚明，非「青錢學士」所能及也。元微之有百餘判，亦不能工。餘襄公集中，亦有判兩卷，粲然可觀。張鷟，字文成，史雲：「調露中，登進士第，考功員外郎騫味道見所對，稱天下無雙。」按登科記，乃上元二年，去調露尚六歲。是年，進士四十五人，鷟名在二十九，既以為無雙，而不列高第？神龍元年，中才膺管樂科，於九人中為第五。景雲二年，中賢良方正科，於二十人中為第三。所謂製舉八中甲科者，亦不然也。","sortOrder":7},
  {"id":"s_work_dtbt_30_8","chapterId":"ch_work_dtbt_30","text":"唐製舉科目","sortOrder":8},
  {"id":"s_work_dtbt_30_9","chapterId":"ch_work_dtbt_30","text":"唐世製舉，科目猥多，徒異其名爾，其實與諸科等也。張九齡以道侔伊、呂策高第，以登科記及會要考之，蓋先天元年九月，明皇初即位，宣勞使所舉諸科九人，經邦治國、材可經國、才堪刺史、賢良方正與此科各一人，藻思清華、興化變俗科各二人。其道侔伊、呂策問殊平平，但雲：「興化致理，必俟得人；求賢審官，莫先任舉。欲遠循漢、魏之規，復存州郡之選，慮牧守之明，不能必鑒。」次及「越騎佽飛，皆出畿甸，欲均井田於要服，遵丘賦於革車」，幷安人重穀，編戶農桑之事，殊不及為天下國家之要道。則其所以待伊、呂者亦狹矣。九齡於神龍二年中材堪經邦科，本傳不書，計亦此類耳。","sortOrder":9},
  {"id":"s_work_dtbt_30_10","chapterId":"ch_work_dtbt_30","text":"淵有九名","sortOrder":10},
  {"id":"s_work_dtbt_30_11","chapterId":"ch_work_dtbt_30","text":"莊子載壺子見季鹹事雲：「鯢旋之潘為淵，止水之潘為淵，流水之潘為淵，淵有九名，此處三焉。」其詳見於列子黃帝篇，盡載其目，曰：「鯢旋之潘為淵，止水之潘為淵，流水之潘為淵，濫水之潘為淵，沃水之潘為淵，氿水之潘為淵，雍水之潘為淵，汧水之潘為淵，肥水之潘為淵，是為九淵。」按爾雅雲「濫水正出」，即檻泉也。「沃泉下出，氿泉穴出，灉者反入，汧者出不流。」又「水決之澤為汧，肥者出同而歸異。」皆禹所名也。爾雅之書，非周公所作，蓋是訓釋三百詩篇所用字，不知列子之時，已有此書否？細碎蟲魚之文，列子決不肯留意，得非偶相同邪？淮南子有九璇之淵，許叔重雲：「至深也。」賈誼弔屈賦：「襲九淵之神龍。」顏師古曰：「九淵，九旋之川，言至深也。」與此不同。","sortOrder":11},
  {"id":"s_work_dtbt_30_12","chapterId":"ch_work_dtbt_30","text":"東坡論莊子","sortOrder":12},
  {"id":"s_work_dtbt_30_13","chapterId":"ch_work_dtbt_30","text":"東坡先生作莊子祠堂記，辯其不詆訾孔子。「嘗疑盜跖、漁父則真若詆孔子者，至於讓王、說劍，皆淺陋不入於道。反復觀之，得其寓言之終曰：『陽子居西遊於秦，遇老子。其往也，舍者將迎其家，公執席，妻執巾櫛，舍者避席，煬者避竈。其反也，與之爭席矣。』去其讓王、說劍、漁父、盜跖四篇，以合於列禦寇之篇，曰：『列禦寇之齊，中道而反，曰，吾驚焉，吾食於十漿，而五漿先饋。』然後悟而笑曰：是固一章也。莊子之言未終，而昧者剿之，以入其言爾。」東坡之識見至矣、盡矣。故其祭徐君猷文雲：「爭席滿前，無復十漿而五饋。」用為一事。今之莊周書寓言第二十七，繼之以讓王、盜跖、說劍、漁父，乃至列禦寇為第三十二篇，讀之者可以渙然冰釋也。予按列子書第二篇內首載禦寇饋漿事數百言，即綴以楊朱爭席一節，正與東坡之旨異世同符，而坡公記不及此，豈非作文時偶忘之乎！陸德明釋文：「郭子玄雲，一曲之才，妄竄奇說，若閼弈、意修之首，危言、遊鳧、子胥之篇，凡諸巧雜，十分有三。漢藝文志莊子五十二篇，即司馬彪、孟氏所註是也，言多詭誕，或似山海經，或類占夢書，故註者以意去取，其內篇衆家並同。」予參以此說，坡公所謂昧者，其然乎？閼弈、遊鳧諸篇，今無復存矣。","sortOrder":13},
  {"id":"s_work_dtbt_30_14","chapterId":"ch_work_dtbt_30","text":"列子書事","sortOrder":14},
  {"id":"s_work_dtbt_30_15","chapterId":"ch_work_dtbt_30","text":"列子書事，簡勁宏妙，多出莊子之右，其言惠盎見宋康王，王曰：「寡人之所說者，勇有力也，客將何以教寡人？」盎曰：「臣有道於此，使人雖勇，刺之不入，雖有力，擊之弗中。」王曰：「善，此寡人之所欲聞也。」盎曰：「夫刺之不入，擊之不中，此猶辱也。臣有道於此，使人雖有勇弗敢刺，雖有力弗敢擊。夫弗敢，非無其志也。臣有道於此，使人本無其志也。夫無其志也，未有愛利之心也。臣有道於此，使天下丈夫女子莫不歡然皆欲愛利之，此其賢於勇有力也，四累之上也。」觀此一段語，宛轉四反，非數百言曲而暢之不能了，而潔淨粹白如此，後人筆力，渠復可到耶！三不欺之義，正與此合。不入不中者，不能欺也；弗敢刺擊者，不敢欺也；無其志者，不忍欺也。魏文帝論三者優劣，斯言足以蔽之。","sortOrder":15},
  {"id":"s_work_dtbt_30_16","chapterId":"ch_work_dtbt_30","text":"天生對偶","sortOrder":16},
  {"id":"s_work_dtbt_30_17","chapterId":"ch_work_dtbt_30","text":"舊說以紅生白熟、腳色手紋、寬焦薄脆之屬，為天生偶對。觸類而索之，得相傳名句數端，亦有經前人紀載者，聊疏於此，以廣多聞。如「三川太守，四目老翁」，「相公公相子，人主主人翁」，「泥肥禾尚瘦，晷短夜差長」，「斷送一生惟有，破除萬事無過」，「北斗七星三四點，南山萬壽十千年」，「迅雷風烈風雷雨，絕地天通天地人」，「筵上枇杷，本是無聲之樂；草間蚱蜢，還同不繫之舟」，皆絕工者。又有用書語兩句而證以俗諺者，如「堯之子不肖，舜之子亦不肖」，諺曰「外甥多似舅」，「吾力足以舉百鈞，而不足以舉一羽」，諺曰「便重不便輕」之類是也。","sortOrder":17},
  {"id":"s_work_dtbt_30_18","chapterId":"ch_work_dtbt_30","text":"銅雀灌硯","sortOrder":18},
  {"id":"s_work_dtbt_30_19","chapterId":"ch_work_dtbt_30","text":"相州，古鄴都，魏太祖銅雀臺在其處，今遺址髣髴尚存。瓦絕大，艾城王文叔得其一，以為硯，餉黃魯直，東坡所為作銘者也。其後復歸王氏。硯之長幾三尺，闊半之。先公自燕還，亦得二硯，大者長尺半寸，闊八寸，中為瓢形，背有隱起六隸字，甚清勁，曰「建安十五年造」。魏祖以建安九年領冀州牧，治鄴，始作此臺雲。小者規範全不逮，而其腹亦有六篆字，曰「大魏興和年造」，中皆作小簇花團。興和乃東魏孝靜帝紀年，是時，正都鄴，與建安相距三百年，其至於今，亦六百餘年矣。二者皆藏侄孫僩處。予為銘建安者曰：「鄴瓦所范，嘻其是邪？幾九百年，來隨漢槎。淬爾筆鋒，肆其滂葩。僩實寶此，以昌我家。」銘興和者曰：「魏元之東，狗腳於鄴。吁其瓦存，亦禪千劫。上林得雁，獲貯歸笈。玩而銘之，衰淚棲睫。」贛州雩都縣，故有灌嬰廟，今不復存。相傳左地嘗為池，耕人往往於其中耕出古瓦，可窾為硯。予向來守郡日所得者，刓缺兩角，猶重十斤，瀋墨如發硎，其光沛然，色正黃，考德儀年，又非銅雀比，亦嘗刻銘於上曰：「范土作瓦，既埴既已。何斷製於火，而卒以囿水？廟於漢侯，今千幾年？何址蹶祀歇，而此獨也存？縣贛之雩，曰若灌池。研為我得，而銘以章之。」蓋紀實也。","sortOrder":19},
  {"id":"s_work_dtbt_30_20","chapterId":"ch_work_dtbt_30","text":"崔斯立","sortOrder":20},
  {"id":"s_work_dtbt_30_21","chapterId":"ch_work_dtbt_30","text":"崔立之，字斯立，在唐不登顯仕，他亦無傳，而韓文公推奬之備至。其藍田丞壁記雲：「種學績文，以蓄其有，泓涵演迤，日大以肆。」其贈崔評事詩雲：「崔侯文章苦捷敏，高浪駕天輸不盡。頃從關外來上都，隨身卷軸車連軫。朝為百賦猶鬱怒，暮作千詩轉遒緊。才豪氣猛易語言，往往蛟螭雜螻蚓。」其寄崔二十六詩雲：「西城員外丞，心跡兩崛奇。往歲戰詞賦，不將勢力隨。傲兀坐試席，深叢見孤羆。文如翻水成，初不用意為。四坐各低面，不敢捩眼窺。佳句喧衆口，考官敢瑕疵？連年收科第，若摘頷底髭。」其美之如是。但記雲「貞元初，挾其能，戰藝於京師，再進再屈於人」，而詩以為「連年收科第」，何其自為異也？予按杭本韓文，作「再屈千人」，蜀本作「再進屈千人」，文苑亦然。蓋他本誤以千字為於也。又登科記「立之以貞元三年第進士，七年，中宏詞科」，正與詩合。觀韓公所言，崔作詩之多可知矣，而無一篇傳於今，豈非螻蚓之雜，惟敏速而不能工邪？","sortOrder":21},
  {"id":"s_work_dtbt_30_22","chapterId":"ch_work_dtbt_30","text":"漢書註冗","sortOrder":22},
  {"id":"s_work_dtbt_30_23","chapterId":"ch_work_dtbt_30","text":"顏師古註漢書，評較諸家之是非，最為精盡，然有失之贅冗及不煩音釋者。其始遇字之假借，從而釋之。既雲「他皆類此」，則自是以降，固不煩申言。然於「循行」字下，必雲「行音下更反」；於「給復」字下，必雲「復音方目反」。至如說讀曰悅，繇讀曰徭，鄉讀曰嚮，解讀曰懈，與讀曰豫，又讀曰歟，雍讀曰壅，道讀曰導，畜讀曰蓄，視讀曰示，艾讀曰乂，竟讀曰境，飭與（來力）同，繇與由同，敺與驅同，晻與暗同，婁古屢字，墬古地字，饟古餉字，古奔字之類，各以百數。解三代曰夏、商、周，中都官曰京師諸官府，失職者失其常業，其重複亦然。貸曰假也，休曰美也，烈曰業也，稱曰副也，靡曰無也，滋曰益也，蕃曰多也，圖曰謀也，耗曰減也，卒曰終也，悉曰盡也，給曰足也，寖曰漸也，則曰法也，風曰化也，永曰長也，省曰視也，仍曰頻也，疾曰速也，比曰頻也，諸字義不深祕，既為之辭，而又數出，至同在一板內再見者，此類繁多，不可勝載。其豁、仇、恢、坐、邾、陝、治、脫、攘、蓺、垣、綰、顓、擅、酣、侔、重、禺、俞、選等字，亦用切腳，皆為可省。志中所註，尤為煩蕪。項羽一傳，伯讀曰霸，至於四言之。若相國何，相國參，太尉勃，太尉亞夫，丞相平，丞相吉，亦註為蕭何、曹參，桓、文、顏、閔必註為齊桓、晉文、顏淵、閔子騫之類，讀是書者，要非童蒙小兒，夫豈不曉，何煩於屢註哉？","sortOrder":23},
  {"id":"s_work_dtbt_30_24","chapterId":"ch_work_dtbt_30","text":"古跡不可考","sortOrder":24},
  {"id":"s_work_dtbt_30_25","chapterId":"ch_work_dtbt_30","text":"郡縣山川之古跡，朝代變更，陵穀推遷，蓋已不可復識。如堯山、歷山，所在多有之，皆指為堯、舜時事，編之圖經。會稽禹墓，尚雲居高丘之顛，至於禹穴，則強名一罅，不能容指，不知司馬子長若之何可探也？舜都蒲坂，實今之河中所謂舜城者，宜歷世奉之唯謹。按張芸叟河中五廢記雲：「蒲之西門所由而出者，兩門之間，即舜城也，廟居其中，唐張宏靖守蒲，嘗修飾之。至熙寧之初，垣墉尚固。曾不五年，而為埏陶者盡矣。舜城自是遂廢。又河之中泠一洲島，名曰中潬，所以限橋。不知其所起，或雲汾陽王所為。以鐵為基，上有河伯祠，水環四周，喬木蔚然。嘉祐八年秋，大水馮襄，了無遺跡。中潬自此遂廢。」顯顯者若此，他可知矣。東坡在鳳翔，作淩虛臺記雲：「嘗試登臺而望其東，則秦穆之祈年、橐泉，其南則漢武之長楊、五柞，其北則隋之仁壽、唐之九成也。記其一時之盛，宏傑詭麗，堅固而不可動。然數世之後，欲求其髣髴，而破瓦頹垣，無復存者。」謂物之廢興成毀，皆不可得而知，則區區泥於陳跡，而必欲求其是，蓋無此理也。漢書地理志，扶風雍縣有橐泉宮，秦孝公起。祈年宮，惠公起。不以為穆公。","sortOrder":25},
  {"id":"s_work_dtbt_30_26","chapterId":"ch_work_dtbt_30","text":"容齋續筆","sortOrder":26},
  {"id":"s_work_dtbt_31_1","chapterId":"ch_work_dtbt_31","text":"卷第十三(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_31_2","chapterId":"ch_work_dtbt_31","text":"科舉恩數","sortOrder":2},
  {"id":"s_work_dtbt_31_3","chapterId":"ch_work_dtbt_31","text":"國朝科舉取士，自太平興國以來，恩典始重。然各出一時製旨，未嘗輒同，士子隨所得而受之，初不以官之大小有所祈訴也。太平之二年，進士一百九人，呂蒙正以下四人得將作丞，餘皆大理評事，充諸州通判。三年，七十四人，胡旦以下四人將作丞，餘並為評事，充通判及監當。五年，一百二十一人，蘇易簡以下二十三人皆將作丞通判。八年，二百三十九人，自王世則以下十八人，以評事知縣，餘授判司簿尉。未幾，世則等移通判，簿尉改知令錄。明年，並遷守評事。雍熙二年，二百五十八人，自梁顥以下二十一人，纔得節察推官。端拱元年，二十八人，自程宿以下，但權知諸縣簿尉。二年，一百八十六人，陳堯叟、曾會至得光祿丞直史館，而第三人姚揆，但防禦推官。淳化三年，三百五十三人，孫何以下，二人將作丞，二人評事，第五人以下，皆吏部註擬。鹹平元年，孫僅但得防推。二年，孫暨以下，但免選註官。蓋此兩榜，真宗在諒闇，禮部所放，故殺其禮。及三年，陳堯咨登第，然後六人將作丞，四十二人評事；第二甲一百三十四人，節度推官、軍事判官；第三甲八十人，防團軍事推官。","sortOrder":3},
  {"id":"s_work_dtbt_31_4","chapterId":"ch_work_dtbt_31","text":"下第再試","sortOrder":4},
  {"id":"s_work_dtbt_31_5","chapterId":"ch_work_dtbt_31","text":"太宗雍熙二年，已放進士百七十九人，或雲：「下第中甚有可取者。」乃令復試，又得洪湛等七十六人，而以湛文采遒麗，特升正榜第三。端拱元年，禮部所放程宿等二十八人，進士葉齊打鼓論榜，遂再試，復放三十一人，而諸科因此得官者至於七百。一時待士可謂至矣。然太平興國末，孟州進士張兩光，以試不合格，縱酒大駡於街衢中，言涉指斥，上怒斬之，同保九輩永不得赴舉。恩威並行，至於如此。(「張兩」，館本作「張雨」。)","sortOrder":5},
  {"id":"s_work_dtbt_31_6","chapterId":"ch_work_dtbt_31","text":"試賦用韻","sortOrder":6},
  {"id":"s_work_dtbt_31_7","chapterId":"ch_work_dtbt_31","text":"唐以賦取士，而韻數多寡，平側次敍，元無定格。故有三韻者，花萼樓賦以題為韻是也。有四韻者，蓂莢賦以「呈瑞聖朝」，舞馬賦以「奏之天廷」，丹甑賦以「國有豐年」，泰階六符賦以「元亨利貞」為韻是也。有五韻者，金莖賦以「日華川上動」為韻是也。有六韻者，止水、魍魎、人鏡、三統指歸、信及豚魚、洪鐘待撞、君子聽音、東郊朝日、蠟日祈天、宗樂德、訓冑子諸篇是也。有七韻者，日再中、射己之鵠、觀紫極舞、五聲聽政諸篇是也。八韻有二平六側者，六瑞賦以「儉故能廣，被褐懷玉」，日五色賦以「日麗九華，聖符土德」，徑寸珠賦以「澤浸四荒，非寶遠物」為韻是也。有三平五側者，宣耀門觀試舉人以「君聖臣肅，謹擇多士」，懸法象魏以「正月之吉，懸法象魏」，玄酒以「薦天明德，有古遺味」，五色土以「王子畢封，依以建社」，通天臺以「洪臺獨出，浮景在下」，幽蘭以「遠芳襲人，悠久不絕」，日月合璧以「兩曜相合，候之不差」，金柅以「直而能一，斯可製動」為韻是也。有五平三側者，金用礪以「商高宗命傅說之官」為韻是也。有六平二側者，旗賦以「風日雲舒，軍容清肅」為韻是也。自大和以後，始以八韻為常。唐莊宗時嘗覆試進士，翰林學士承旨盧質，以後從諫則聖為賦題，以「堯、舜、禹、湯傾心求過」為韻。舊例，賦韻四平四側，質所出韻乃五平三側，大為識者所誚，豈非是時已有定格乎？國朝太平興國三年九月，始詔自今廣文館及諸州府、禮部試進士律賦，並以平側次用韻，其後又有不依次者，至今循之。","sortOrder":7},
  {"id":"s_work_dtbt_31_8","chapterId":"ch_work_dtbt_31","text":"貞元製科","sortOrder":8},
  {"id":"s_work_dtbt_31_9","chapterId":"ch_work_dtbt_31","text":"唐德宗貞元十年，賢良方正科十六人，裴垍為舉首，王播次之，隔一名而裴度、崔羣、皇甫鎛繼之。六名之中，連得五相，可謂盛矣！而邪正敻不侔。度、羣同為元和宰相，而鎛以聚斂賄賂亦居之，度、羣極陳其不可，度恥其同列，表求自退，兩人竟為鎛所毀而去。且三相同時登科，不可謂無事分，而玉石雜糅，薰蕕同器，若默默充位，則是固寵患失，以私妨公，裴、崔之賢，誼難以處也。本朝韓康公、王岐公、王荊公亦同年聯名，熙寧間，康公、荊公為相，岐公參政，故有「一時同榜用三人」之語，頗類此雲。","sortOrder":9},
  {"id":"s_work_dtbt_31_10","chapterId":"ch_work_dtbt_31","text":"貽子錄","sortOrder":10},
  {"id":"s_work_dtbt_31_11","chapterId":"ch_work_dtbt_31","text":"先公自燕歸，得龍圖閣書一策，曰貽子錄，有「御書」兩印存，不言撰人姓名，而序雲：「愚叟受知南平王，政寬事簡。」意必高從誨擅荊渚時，賓僚如孫光憲輩者所編，皆訓儆童蒙。其修進一章雲，鹹通年中，盧子期著初舉子一卷，細大無遺。就試三場，避國諱、宰相諱、主文諱。士人家小子弟，忌用熨斗時把帛，慮有拽白之嫌。燭下寫試無誤筆，即題其後雲「並無揩改塗乙註」，如有，即言字數，其下小書名。同年小錄是雙隻先輩各一人分寫。宴上長少分雙隻相向而坐，元以東為上，儭以西為首，給、舍、員外、遺、補，多來突宴，東先輩不遷，而西先輩避位。及吏部給春關牒，便稱前鄉貢進士，大略有與今製同者，獨避宰相、主文諱，不復講雙隻，先輩之名，他無所見。其林園一章謂茄為酪酥，亦甚新。","sortOrder":11},
  {"id":"s_work_dtbt_31_12","chapterId":"ch_work_dtbt_31","text":"金花帖子","sortOrder":12},
  {"id":"s_work_dtbt_31_13","chapterId":"ch_work_dtbt_31","text":"唐進士登科，有金花帖子，相傳已久，而世不多見。予家藏鹹平元年孫僅榜盛京所得小錄，猶用唐製，以素綾為軸，貼以金花，先列主司四人銜，曰：翰林學士給事中楊，兵部郎中知製誥李，右司諫直史館梁，祕書丞直史館朱，皆押字。次書四人甲子，年若幹，某月某日生，祖諱某，父諱某，私忌某日。然後書狀元孫僅，其所紀與今正同。別用高四寸綾，闊二寸，書「盛京」二字，四主司花書於下，黏於卷首，其規範如此，不知以何年而廢也。但此榜五十人，自第一至十四人，惟第九名劉燁為河南人，餘皆貫開封府，其下又二十五人亦然。不應都人士中選若是之多，疑亦外方人寄名託籍，以為進取之便耳。四主司乃楊礪、李若拙、梁顥、朱台符，皆只為同知舉。","sortOrder":13},
  {"id":"s_work_dtbt_31_14","chapterId":"ch_work_dtbt_31","text":"物之小大","sortOrder":14},
  {"id":"s_work_dtbt_31_15","chapterId":"ch_work_dtbt_31","text":"列禦寇、莊周大言小言，皆出於物理之外。列子所載：「夏革曰：渤海之東，幾億萬里，有大壑焉，實惟無底之穀。中有五山，高下周旋三萬里，山之中間相去七萬里，而五山之根無所連著。帝使巨鼇十五舉首而戴之，叠為三番，六萬歲一交焉。而龍伯之國有大人，舉足不盈數千而暨山所，一釣而連六鼇，合負而趣歸其國。於是岱輿、員嶠二山，沈於大海。」張湛註雲：「以高下周圍三萬里山，而一鼇頭之所戴，而六鼇復為一釣之所引，龍伯之人能幷而負之。計此人之形當百餘萬里，鯤鵬方之，猶蚊蚋蚤蝨耳。太虛之所受，亦奚所不容哉！」莊子逍遙遊，首著鯤鵬事雲：「北溟有魚，其名為鯤，鯤之大不知其幾千里也。化而為鳥，其名為鵬，鵬之徙於南溟，水擊三千里，摶扶搖而上者九萬里。」二子之語大若此。至於小言，則莊子謂：「有國於蝸之左角，曰觸氏，右角曰蠻氏，相與爭地而戰，伏屍數萬，逐北旬有五日而後反。」列子曰：「江浦之間生麼蟲，其名曰焦螟。羣飛而集於蚊睫，弗相觸也，棲宿去來，蚊弗覺也。黃帝與容成子同齋三月，徐以神視，塊然見之，若嵩山之阿，徐以氣聽，砰然聞之，若雷霆之聲。」二子之語小如此。釋氏維摩詰長者居丈室而容九百萬菩薩幷師子座，一芥子之細而能納須彌。皆一理也。張湛不悟其寓言，而竊竊然以太虛無所不容為說，亦隘矣！若吾儒中庸之書，但雲：「天地之大也，人猶有所憾，故君子語大，天下莫能載焉；語小，天下莫能破焉。」則明白洞達，歸於至當，非二氏之學一偏所及也。","sortOrder":15},
  {"id":"s_work_dtbt_31_16","chapterId":"ch_work_dtbt_31","text":"郭令公","sortOrder":16},
  {"id":"s_work_dtbt_31_17","chapterId":"ch_work_dtbt_31","text":"唐人功名富貴之盛，未有出郭汾陽之右者。然至其女孫為憲宗正妃，歷五朝，母天下，終以不得志於宣宗而死，自是支冑不復振。及本朝慶曆四年，訪求厥後，僅得裔孫元亨於布衣中，以為永興軍助教。歐陽公知製誥，行其詞曰：「繼絕世，褒有功，非惟推恩以及遠，所以勸天下之為人臣者焉。況爾先王，名載舊史，勳德之厚，宜其流澤於無窮，而其後裔不可以廢。往服新命，以榮厥家！」且以二十四考中書令之門，而需一助教以為榮，吁，亦淺矣！乃知世祿不朽，如春秋諸國，至數百年者，後代不易得也。","sortOrder":17},
  {"id":"s_work_dtbt_31_18","chapterId":"ch_work_dtbt_31","text":"紀年兆祥","sortOrder":18},
  {"id":"s_work_dtbt_31_19","chapterId":"ch_work_dtbt_31","text":"自漢武建元以來，千餘年間，改元數百，其附會離合為之辭者，不可勝書，固亦有曉然而易見者。如晉元帝永昌，郭璞以為有二日之象，果至冬而亡。桓靈寶大亨，識者以為一人二月了，果以仲春敗。蕭棟、武陵王紀，同歲竊位，皆為天正，以為二人一年而止，其後皆然。齊文宣天保，為一大人只十，果十年而終。然梁明帝蕭巋亦用此，而盡二十三年。或又雲，巋蕞爾一邦，故非禨祥所係。齊後主隆化，為降死；安德王延宗德昌，為得二日。周武帝宣政，為宇文亡日；宣帝大象，為天子冢。蕭琮、晉出帝廣運，為軍走。隋煬帝大業，為大苦末。唐僖宗廣明，為唐去丑口而著黃家日月，以兆巢賊之禍。欽宗靖康，為立十二月康，果在位滿歲，而高宗由康邸建中興之業。熙寧之末將改元，近臣撰三名以進，曰「平成」，曰「美成」，曰「豐亨」，神宗曰：「成字負戈，美成者，犬羊負戈。亨字為子不成，不若去亨而加元。」遂為元豐。若隆興則取建隆、紹興各一字，與唐貞元取貞觀、開元之義同。已而嫌與顏亮貞隆相近，故二年即改乾道。及甲午改純熙，既已布告天下，予時守贛，賀表雲：「天永命而開中興，方茂卜年之統；時純熙而用大介，載新紀號之文。」迨詔至，乃為淳熙，蓋以出處有「告成大武」之語，故不欲用。","sortOrder":19},
  {"id":"s_work_dtbt_31_20","chapterId":"ch_work_dtbt_31","text":"民俗火葬","sortOrder":20},
  {"id":"s_work_dtbt_31_21","chapterId":"ch_work_dtbt_31","text":"自釋氏火化之說起，於是死而焚屍者，所在皆然。固有炎暑之際，畏其穢泄，斂不終日，肉尚未寒而就爇者矣。魯夏父弗忌獻逆祀之議，展禽曰：「必有殃，雖壽而沒，不為無殃。」既其葬也，焚煙徹於上，謂已葬而火焚其棺椁也。吳伐楚，其師居麋，楚司馬子期將焚之，令尹子西曰：「父兄親暴骨焉，不能收，又焚之，不可。」謂前年楚人與吳戰，多死麋中，不可幷焚也。衞人掘褚師定子之墓，焚之於平莊之上。燕騎劫圍齊即墨，掘人冢墓，燒死人，齊人望見涕泣，怒自十倍。王莽作焚如之刑，燒陳良等。則是古人以焚屍為大僇也。列子曰：「楚之南有炎人之國，其親戚死，（歺丂）其肉而棄之，然後埋其骨；秦之西有儀渠之國，其親戚死，聚柴積而焚之，燻則煙上，謂之登遐，然後成為孝子。此上以為政，下以為俗，而未足為異也。」蓋是時其風未行於中國，故列子以儀渠為異，至與（歺丂）肉者同言之。（歺丂）音寡。","sortOrder":21},
  {"id":"s_work_dtbt_31_22","chapterId":"ch_work_dtbt_31","text":"太史日官","sortOrder":22},
  {"id":"s_work_dtbt_31_23","chapterId":"ch_work_dtbt_31","text":"周禮春官之屬曰：「太史掌建邦之六典，以逆邦國之治。正歲年以序事，頒之於官府及都鄙，頒告朔於邦國。」「小史掌邦國之志，奠繫世，辨昭穆。」鄭氏註雲：「太史，日官也。」引左傳「天子有日官，諸侯有日御」為說。志，謂記也。史官主書，國語所謂鄭書及帝繫、世本之屬是也，小史主定之。然則周之史官、日官，同一職耳。故司馬談為漢太史令，而子長以為「文史星曆近乎卜祝之間，固主上所戲弄，倡優畜之，流俗之所輕也」。今太史局正星曆卜祝輩所聚，其長曰太史局令，而隸祕書省，有太史案主之，蓋其源流有自來矣。","sortOrder":23},
  {"id":"s_work_dtbt_31_24","chapterId":"ch_work_dtbt_31","text":"汲冢周書","sortOrder":24},
  {"id":"s_work_dtbt_31_25","chapterId":"ch_work_dtbt_31","text":"汲冢周書今七十篇，殊與尚書體不相類，所載事物亦多過實。其克商解雲「武王先入，適紂所在，射之三發，而後下車，擊之以輕呂，(劍名。)斬之以黃鉞，縣諸大白。商二女既縊，又射之三發，擊之以輕呂，斬之以玄鉞，縣諸小白。」越六日，朝至於周，以三首先馘，入燎於周廟，又用紂於南郊。夫武王之伐紂，應天順人，不過殺之而已。紂既死，何至梟戮俘馘，且用之以祭乎？其不然者也。又言武王狩事，尤為淫侈，至於擒虎二十有二，貓二，麋五千二百三十五，犀十有三，氂七百二十有一，熊百五十一，羆百十八，豕三百五十有二，狢十有八，麂十有六，麝五十，鹿三千五百有二。遂征四方，凡憝國九十有九國，馘磨億有十萬七千七百七十有九，其多如是，雖註家亦雲武王以不殺為仁，無緣所馘如此，蓋大言也。王會篇皆大會諸侯及四夷事，雲：「唐叔、荀叔、周公在左，太公在右。堂下之右，唐公、虞公南面立焉，堂下之左，商公、夏公立焉。」四公者，堯、舜、禹、湯後，商、夏即杞、宋也。又言：俘商寶玉億有百萬。所紀四夷國名，頗古奧，獸畜亦奇崛，以肅真為稷真，獩人為穢人，樂浪之夷為良夷，姑蔑為姑妹，東甌為且甌，渠搜為渠叟，高句麗為高夷。所敍：「穢人前兒，若彌猴，立行，聲似小兒。良夷在子，(獸名。)弊身人首，脂其腹，炙之藿則鳴。揚州禺禺魚、人鹿。青丘狐九尾。東南夷白民乘黃，乘黃者似騏，背有兩角。東越海（上合下虫虫）、海陽、盈車、大蟹。西南戎曰央林，以酋耳，酋耳者，身若虎豹。渠叟以（鼠勺）犬，（鼠勺）犬者，露犬也，能飛食虎豹。區陽戎以（上敝下黽）封，（上敝下黽）封者，若彘，前後有首。蜀人以文翰，文翰者，若皋。康民以稃苡，其實如李，食之宜子。北狄州靡（上弗下禺）（上弗下禺），其形人身枝踵，自笑，笑則上唇翕其目，食人。都郭(亦北狄。)生生，若黃狗，人面能言。奇幹(亦北狄。)善芳，頭若雄鷄，佩之令人不眯。正東高夷嗛羊，嗛羊者，羊而四角。西方之戎曰獨鹿，邛邛距虛。犬戎文馬，而赤（上髟下曷）縞身，目若黃金，名古皇之乘。白州北閭，北閭者，其華若羽，以其木為車，終行不敗。」篇末引伊尹朝獻商書雲：「湯問伊尹，使為四方獻令。伊尹請令，正東以魚皮之鞞、鰂醬、蛟瞂、利劍；正南以珠璣、玳瑁、象齒、文犀；正西以丹青、白旄、江歷、(珠名。)龍角；正北以橐駝、騊駼、駃騠、良弓為獻。湯曰：善。」凡此皆無所質信，姑錄之以貽博雅者。唐太宗時，遠方諸國來朝貢者甚衆，服裝詭異，顏師古請圖以示後，作王會圖，蓋取諸此。漢書所引：「天予不取，反受其咎，毋為權首，將受其咎。」以為逸周書，此亦無之，然則非全書也。","sortOrder":25},
  {"id":"s_work_dtbt_31_26","chapterId":"ch_work_dtbt_31","text":"曹子建論文","sortOrder":26},
  {"id":"s_work_dtbt_31_27","chapterId":"ch_work_dtbt_31","text":"曹子建與楊德祖書雲：「世人著述，不能無病，僕常好人譏彈其文，有不善，應時改定。昔丁敬禮常作小文，使僕潤飾之，僕自以才不過若人，辭不為也。敬禮謂僕：『卿何所疑難，文之佳麗，吾自得之，後世誰相知定吾文者邪？』吾常嘆此達言，以為美談。」子建之論善矣。任昉為王儉主簿，儉出自作文，令昉點正，昉因定數字，儉嘆曰：「後世誰知子定吾文？」正用此語。今世俗相承，所作文或為人詆訶，雖未形之於辭色，及退而怫然者，皆是也。歐陽公作尹師魯銘文，不深辯其獲罪之寃，但稱其為文章簡而有法。或以為不盡，公怒，至詒書他人，深數責之曰：「簡而有法，惟春秋可當之，修於師魯之文不薄矣。又述其學曰『通知古今』，此語若必求其可當者，惟孔、孟也。而世之無識者乃雲雲。此文所以慰吾亡友爾，豈恤小子輩哉！」王荊公為錢公輔銘母夫人蔣氏墓，不稱公輔甲科，但雲：「子官於朝，豐顯矣，里巷之士以為太君榮。」後雲：「孫七人皆幼。」不書其名。公輔意不滿，以書言之，公復書曰：「比蒙以銘文見屬，輒為之而不辭。不圖乃猶未副所欲，欲有所增損。鄙文自有意義，不可改也。宜以見還，而求能如足下意者為之。如得甲科為通判，何足以為太夫人之榮？一甲科通判，苟粗知為辭賦，雖市井小人，皆可以得之，何足道哉？故銘以謂閭巷之士，以為太夫人榮，明天下有識者不以置榮辱也。至於諸孫，亦不足列，孰有五子而無七孫者乎？」二公不喜人之議其文亦如此。","sortOrder":27},
  {"id":"s_work_dtbt_31_28","chapterId":"ch_work_dtbt_31","text":"雨水清明","sortOrder":28},
  {"id":"s_work_dtbt_31_29","chapterId":"ch_work_dtbt_31","text":"曆家以雨水為正月中氣，驚蟄為二月節，清明為三月節，穀雨為三月中氣。而漢世之初，仍周、秦所用，驚蟄在雨水之前，穀雨在清明之前，至於太初，始正之雲。","sortOrder":29},
  {"id":"s_work_dtbt_31_30","chapterId":"ch_work_dtbt_31","text":"容齋續筆","sortOrder":30},
  {"id":"s_work_dtbt_32_1","chapterId":"ch_work_dtbt_32","text":"卷第十四(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_32_2","chapterId":"ch_work_dtbt_32","text":"尹文子","sortOrder":2},
  {"id":"s_work_dtbt_32_3","chapterId":"ch_work_dtbt_32","text":"漢藝文志名家內有尹文子一篇，雲：「說齊宣王。先公孫龍。」劉歆雲：「其學本於黃、老，居稷下，與宋鈃、彭蒙、田駢等同學於公孫龍。」今其書分為上下兩卷，蓋漢末仲長統所銓次也。其文僅五千言，議論亦非純本黃、老者。大道篇曰：「道不足以治則用法；法不足以治則用術；術不足以治則用權；權不足以治則用勢；勢不足則反權。權用則反術；術用則反法；法用則反道；道用則無為而自治。」又曰：「為善使人不能得從，此獨善也。為巧使人不能得為，此獨巧也。未盡善巧之理。為善與衆行之，為巧與衆能之，此善之善者，巧之巧者也。故所貴聖人之治，不貴其獨治，貴其能與衆共治；貴工倕之巧，不貴其獨巧，貴其能與衆共巧也。今世之人，行欲獨賢，事欲獨能，辯欲出羣，勇欲絕衆。獨行之賢，不足以成化；獨能之事，不足以周務；出羣之辯，不可為戶說；絕衆之勇，不可與正陳。凡此四者，亂之所由生。聖人任道、立法，使賢愚不相棄，能鄙不相遺，此至治之術也。」詳味其言，頗流而入於兼愛。莊子末章，敍天下之治方術者，曰：「不累於俗，不飾於物，不苟於人，不忮於衆。願天下之安寧，以活民命，人我之養，畢足而止，以此白心，古之道術有在於是者。宋鈃、尹文聞其風而悅之，作為華山之冠以自表。雖天下不取，強聒而不舍者也。其為人太多，其自為太少。」蓋亦盡其學雲。荀卿非十二子有宋鈃，而文不預。又別一書曰尹子，五卷，共十九篇，其言論膚淺，多及釋氏，蓋晉、宋時衲人所作，非此之謂也。","sortOrder":3},
  {"id":"s_work_dtbt_32_4","chapterId":"ch_work_dtbt_32","text":"帝王訓儉","sortOrder":4},
  {"id":"s_work_dtbt_32_5","chapterId":"ch_work_dtbt_32","text":"帝王創業垂統，規以節儉，貽訓子孫，必其繼世象賢，而後可以循其教，不然，正足取侮笑耳。宋孝武大治宮室，壞高祖所居陰室，於其處起玉燭殿，與衆臣觀之。牀頭有土障，上掛葛燈籠、麻蠅拂。侍中袁顗因盛稱高祖儉素之德，上不答，獨曰：「田舍翁得此，已為過矣！」唐高力士於太宗陵寢宮，見梳箱一、柞木梳一、黑角篦一、草根刷子一，嘆曰：「先帝親正皇極，以致昇平，隨身服用，唯留此物。將欲傳示子孫，永存節儉。」具以奏聞。明皇詣陵，至寢宮，問所留示者何在？力士捧跪上，上跪奉，肅敬如不可勝，曰：「夜光之珍，垂棘之璧，將何以愈此？」即命史官書之典冊。是時，明皇履位未久，厲精為治，故見太宗故物而惕然有感。及侈心一動，窮天下之力不足以副其求，尚何有於此哉？宋孝武不足責也，若齊高帝、周武帝、陳高祖、隋文帝，皆有儉德，而東昏、天元、叔寶、煬帝之淫侈，浮於桀、紂，又不可以語此雲。","sortOrder":5},
  {"id":"s_work_dtbt_32_6","chapterId":"ch_work_dtbt_32","text":"用計臣為相","sortOrder":6},
  {"id":"s_work_dtbt_32_7","chapterId":"ch_work_dtbt_32","text":"唐自貞觀定製，以省臺寺監理天下之務，官修其方，未之或改。明皇因時極盛，好大喜功，於財利之事尤切，故宇文融、韋堅、楊慎矜、王鉷，皆以聚斂刻剝進，然其職不出戶部也。楊國忠得志，乃以御史大夫判度支，權知太府卿及兩京司農太府出納，是時，猶未立判使之名也。肅宗以後，兵興費廣，第五琦、劉晏始以戶部侍郎判諸使，因之拜相，於是鹽鐵有使，度支有判。元琇、班宏、裴延齡、李巽之徒踵相躡，遂浸浸以他官主之，權任益重。憲宗季年，皇甫鎛由判度支，程異由衞尉卿鹽鐵使，並命為相，公論沸騰，不恤也。逮於宣宗，率由此塗大用，馬植、裴休、夏侯孜以鹽鐵，盧商、崔元式、周墀、崔龜從、蕭鄴、劉瑑以度支，魏扶、魏謩、崔慎由、蔣伸以戶部，自是計相不可勝書矣。惟裴度判度支，上言調兵食非宰相事，請以歸有司，其識量宏正，不可同日語也。","sortOrder":7},
  {"id":"s_work_dtbt_32_8","chapterId":"ch_work_dtbt_32","text":"州縣牌額","sortOrder":8},
  {"id":"s_work_dtbt_32_9","chapterId":"ch_work_dtbt_32","text":"州縣牌額，率係於吉凶，以故不敢輕為改易。嚴州分水縣故額，草書「分」字，縣令有作聰明者，謂字體非宜，自真書三字，刻而立之。是年，邑境惡民持刃殺人者衆，蓋「分」字為「八刀」也。徽州之山水清遠，素無火災，紹熙元年，添差通判盧瑢，悉以所作隸字，換郡下扁牓，自譙樓、儀門，凡亭榭、臺觀之類，一切趨新，郡人以為字多燥筆，而於州牌尤為不嚴重，私切憂之。次年四月，火起於郡庫，經一日兩夕乃止，官舍民廬一空。","sortOrder":9},
  {"id":"s_work_dtbt_32_10","chapterId":"ch_work_dtbt_32","text":"盧知猷","sortOrder":10},
  {"id":"s_work_dtbt_32_11","chapterId":"ch_work_dtbt_32","text":"唐之末世，王綱絕紐，學士大夫逃難解散，畏死之不暇。非有扶顛持危之計，能支大廈於將傾者，出力以佐時，則當委身山棲，往而不反，為門戶性命慮可也。白馬之禍，豈李振、柳璨數凶子所能害哉？亦裴、崔、獨孤諸公有以自取耳。偶讀司空表聖集太子太師盧知猷神道碑，見其仕於僖、昭，更歷榮級，至尚書右僕射，以一品致仕，可以歸矣。然由間關跋履，從昭宗播遷，自華幸洛，天祐二年九月乃終，享年八十有六，其得沒於牖下，亦雲幸也。新唐書有傳，附於父後，甚略，雲：「昭宗為劉季述所幽，感憤而卒。」按昭宗以光化三年遭季述之禍，天復元年反正，至知猷亡時，相去五年。傳雲：「子文度，亦貴顯。」而碑載嗣子刑部侍郎膺，亦不同。表聖乃盧幕客，當時作志，必不誤矣。昭宗實錄：「光化四年三月，華州奏，太子太師盧知猷卒。以劉季述之變，感憤成疾，卒年七十五。」正與新唐傳同。蓋唐武、宣以後諸錄，乃宋敏求補撰，簡牘當有散脫者，皆當以司空之碑為正。又按是年四月改元天復，舊唐紀：「十一月，車駕幸鳳翔。朱全忠趨長安，文武百寮太子太師盧知猷已下出迎。」又為可證。宰相世系表：「知猷生文度，而同族曰渥，渥之子膺，刑部侍郎。」二者矛盾如此。","sortOrder":11},
  {"id":"s_work_dtbt_32_12","chapterId":"ch_work_dtbt_32","text":"忌諱諱惡","sortOrder":12},
  {"id":"s_work_dtbt_32_13","chapterId":"ch_work_dtbt_32","text":"周禮春官：「小史詔王之忌諱。」鄭氏曰：「先王死日為忌，名為諱。」禮記王製：「太史典禮，執簡記，奉諱惡。」註雲：「諱者先王名，惡者忌日，若子卯。惡，烏路反。」左傳：「叔弓如滕，子服椒為介。及郊，遇懿伯之忌，叔弓不入。」懿伯，椒之叔父，忌，怨也。「椒曰：公事有公利無私忌，椒請先入。」觀此乃知忌諱之明文。漢人表疏，如東方朔有「不知忌諱」之類，皆戾本旨。今世俗語言多雲「無忌諱」及「不識忌諱」，蓋非也。","sortOrder":13},
  {"id":"s_work_dtbt_32_14","chapterId":"ch_work_dtbt_32","text":"陳涉不可輕","sortOrder":14},
  {"id":"s_work_dtbt_32_15","chapterId":"ch_work_dtbt_32","text":"揚子法言：「或問陳勝吳廣，曰：『亂。』曰：『不若是則秦不亡。』曰：『亡秦乎？恐秦未亡而先亡矣。』」李軌以為：「輕用其身，而要乎非命之運，不足為福先，適足以為禍始。」予謂不然。秦以無道毒天下，六王皆萬乘之國，相踵滅亡，豈無孝子慈孫、故家遺俗？皆奉頭鼠伏。自張良狙擊之外，更無一人敢西向窺其鋒者。陳勝出於戍卒，一旦奮發不顧，海內豪傑之士，乃始雲合響應，並起而誅之。數月之間，一戰失利，不幸隕命於御者之手，身雖已死，其所置遣侯王將相竟亡秦。項氏之起江東，亦矯稱陳王之令而度江。秦之社稷為墟，誰之力也？且其稱王之初，萬事草創，能從陳餘之言，迎孔子之孫鮒為博士，至尊為太師，所與謀議，皆非庸人崛起者可及，此其志豈小小者哉！漢高帝為之置守冢於碭，血食二百年乃絕。子雲指以為亂，何邪？若乃殺吳廣，誅故人，寡恩忘舊，無帝王之度，此其所以敗也。","sortOrder":15},
  {"id":"s_work_dtbt_32_16","chapterId":"ch_work_dtbt_32","text":"士匄韓厥","sortOrder":16},
  {"id":"s_work_dtbt_32_17","chapterId":"ch_work_dtbt_32","text":"晉厲公既殺郤氏三卿，羣臣疑懼。欒書、荀偃執公，召士匄，匄辭不往，召韓厥，厥辭曰：「古人有言曰『殺老牛莫之敢屍。』而況君乎？二三子不能事君，焉用厥也？」二子竟弒公，而不敢以匄、厥為罪，豈非畏敬其忠正乎？唐武德之季，秦王與建成、元吉相忌害，長孫無忌、高士廉、侯君集、尉遲敬德等，日夜勸王誅之，王猶豫未決。問於李靖，靖辭，問於李世勣，世勣辭，王由是重二人。及至登天位，皆任為將相，知其有所守也。晉、唐四賢之識見略等，而無有稱述者，唐史至不書其事，殆非所謂發潛德之幽光也。蕭道成將革命，欲引時賢參贊大業，夜召謝朏，屏人與語，朏竟無一言。及王儉、褚淵之謀既定，道成必欲引朏參佐命，朏亦不肯從，遂不仕齊世，其亦賢矣。","sortOrder":17},
  {"id":"s_work_dtbt_32_18","chapterId":"ch_work_dtbt_32","text":"孔　墨","sortOrder":18},
  {"id":"s_work_dtbt_32_19","chapterId":"ch_work_dtbt_32","text":"墨翟以兼愛無父之故，孟子辭而辟之，至比於禽獸，然一時之論。迨於漢世，往往以配孔子。列子載惠盎見宋康王曰：「孔丘、墨翟，無地而為君，無官而為長，天下丈夫女子，莫不延頸舉踵而願安利之。」鄒陽上書於梁孝王曰：「魯聽季孫之說逐孔子，宋任子冉之計囚墨翟，以孔、墨之辯，不能自免於讒諛。」賈誼過秦雲：「非有仲尼、墨翟之知。」徐樂雲：「非有孔、曾、墨子之賢。」是皆以孔、墨為一等，列、鄒之書不足議，而誼亦如此。韓文公最為發明孟子之學，以為功不在禹下者，正以辟楊、墨耳。而著讀墨子一篇雲：「儒、墨同是堯、舜，同非桀、紂，同修身正心以治天下國家。孔子必用墨子，墨子必用孔子。不相用，不足為孔、墨。」此又何也？魏鄭公南史梁論，亦有「抑揚孔、墨」之語。","sortOrder":19},
  {"id":"s_work_dtbt_32_20","chapterId":"ch_work_dtbt_32","text":"玉川月蝕詩","sortOrder":20},
  {"id":"s_work_dtbt_32_21","chapterId":"ch_work_dtbt_32","text":"盧仝月蝕詩，唐史以謂譏切元和逆黨，考韓文公效仝所作，雲元和庚寅歲十一月。是年為元和五年，去憲宗遇害時尚十載。仝雲：「歲星主福德，官爵奉董、秦。」說者謂「董秦」即李忠臣，嘗為將相而臣朱泚，至於亡身，故仝鄙之。東坡以為：「當秦之鎮淮西日，代宗避吐蕃之難出狩，追諸道兵，莫有至者。秦方在鞠場，趣命治行，諸將請擇日，秦曰：『父母有急難，而欲擇日乎？』即倍道以進。雖末節不終，似非無功而食祿者。」近世有嚴有翼者，著藝苑雌黃，謂坡之言非也，秦守節不終，受泚偽官，為賊居守，何功之足雲？詩譏刺當時，故言及此。坡乃謂非無功而食祿，謬矣！有翼之論，一何輕發至詆坡公為非為謬哉！予按是時秦之死二十七年矣，何為而追刺之？使仝欲譏逆黨，則應首及祿山與泚矣。竊意元和之世，吐突承璀用事，仝以為嬖倖擅位，故用董賢、秦宮輩喻之，本無預李忠臣事也。記前人似亦有此說，而不能省憶其詳。","sortOrder":21},
  {"id":"s_work_dtbt_32_22","chapterId":"ch_work_dtbt_32","text":"詩要點檢","sortOrder":22},
  {"id":"s_work_dtbt_32_23","chapterId":"ch_work_dtbt_32","text":"作詩至百韻，詞意既多，故有失於點檢者。如杜老夔府詠懷，前雲，「滿坐涕潺湲」，後又雲，「伏臘涕漣漣」。白公寄元微之，既雲，「無杯不共持」，又雲，「笑勸迂辛酒」，「華樽逐勝移」，「觥飛白玉巵」，「飲訝卷波遲」，「歸鞍酩酊馳，酡顏烏帽側，醉袖玉鞭垂」，「白醪充夜酌」，「嫌醒自啜醨」，「不飲長如醉」，一篇之中，說酒者十一句。東坡賦中隱堂五詩各四韻，亦有「坡垂似伏鼇」，「崩崖露伏龜」之語，近於意重。","sortOrder":23},
  {"id":"s_work_dtbt_32_24","chapterId":"ch_work_dtbt_32","text":"周蜀九經","sortOrder":24},
  {"id":"s_work_dtbt_32_25","chapterId":"ch_work_dtbt_32","text":"唐貞觀中，魏徵、虞世南、顏師古繼為祕書監，請募天下書，選五品以上子孫工書者，為書手繕寫。予家有舊監本周禮，其末雲，大周廣順三年癸丑五月，雕造九經書畢，前鄉貢三禮郭嵠書。列宰相李穀、范質、判監田敏等銜於後。經典釋文末雲，顯德六年己未三月，太廟室長朱延熙書，宰相范質、王溥如前，而田敏以工部尚書為詳勘官。此書字畫端嚴有楷法，更無舛誤。舊五代史：漢隱帝時，國子監奏周禮、儀禮、公羊、穀梁四經未有印板，欲集學官考校雕造。從之。正尚武之時，而能如是，蓋至此年而成也。成都石本諸經，毛詩、儀禮、禮記，皆祕書省祕書郎張紹文書。周禮者，祕書省校書郎孫朋古書。周易者，國子博士孫逢吉書。尚書者，校書郎周德政書。爾雅者，簡州平泉令張德昭書。題雲，廣政十四年，蓋孟昶時所鐫，其字體亦皆精謹。兩者並用士人筆札，猶有貞觀遺風，故不庸俗，可以傳遠。唯三傳至皇祐元年方畢工，殊不逮前。紹興中，分命兩淮、江東轉運司刻三史板，其兩漢書內，凡欽宗諱，並小書四字，曰「淵聖御名」，或徑易為「威」字，而他廟諱皆祗缺畫，愚而自用，為可笑也。蜀三傳後，列知益州、樞密直學士、右諫議大夫田況銜，大書為三行，而轉運使直史館曹穎叔，提點刑獄、屯田員外郎孫長卿，各細字一行，又差低於況。今雖執政作牧，監司亦與之雁行也。","sortOrder":25},
  {"id":"s_work_dtbt_32_26","chapterId":"ch_work_dtbt_32","text":"冢宰治內","sortOrder":26},
  {"id":"s_work_dtbt_32_27","chapterId":"ch_work_dtbt_32","text":"周禮天官冢宰，其屬有宮正，實掌王宮之戒令糾禁。內宰以陰禮教六宮，以陰禮教九嬪。蓋宮中官之長也。故自後、夫人之外，九嬪、世婦、女御以下，無不列於屬中。後世宮掖之事，非上宰可得而聞也。禮記內則篇記男女事父母、舅姑，細瑣畢載，而首句雲：「後王命冢宰，降德於衆兆民。」則以其治內故也。","sortOrder":27},
  {"id":"s_work_dtbt_32_28","chapterId":"ch_work_dtbt_32","text":"宰相爵邑","sortOrder":28},
  {"id":"s_work_dtbt_32_29","chapterId":"ch_work_dtbt_32","text":"國朝宰相初不用爵邑為輕重，然亦嘗以代升黜。王文康曾任司空，後為太子太師，經太宗登極恩，但封祁國公。呂文穆自司徒謝事為太子太師，經東封西祀恩，不復再得三公，但封徐國、許國公而已。寇忠愍罷相，學士錢惟演以太子太傅處之，真宗令更與些恩數，惟演但乞封國公。王冀公欽若食邑已過萬戶，及謫為司農卿，於銜內盡除去，後再拜相，乃悉還之。湯岐公以大觀文免相，因御史言落職鐫爵。趙衞公坐舉官犯贓，見為使相，但降封益川郡公，削二千戶。今周益公亦然，皆故實所無也。王婺相元封冀，嫌其與欽若同，屢欲改，適有進國史賞，予為擬進韓國製詞，用「有此冀方，莫如韓樂」。既播告矣，而刪定官馮震武以為真宗故封，不許用，遂貼麻為魯，雖著於司封格，馮蓋不知富韓公已用之矣。是時，婺相以食邑過二萬戶為辭，壽皇遣中使至邁所居宣示，令具前此有無體例，及合如何施行事理，擬定聞奏。遂以邑戶無止法復命，乃竟行下。","sortOrder":29},
  {"id":"s_work_dtbt_32_30","chapterId":"ch_work_dtbt_32","text":"楊子一毛","sortOrder":30},
  {"id":"s_work_dtbt_32_31","chapterId":"ch_work_dtbt_32","text":"孟子曰：「楊子取為我，拔一毛而利天下不為也。」楊朱之書，不傳於今，其語無所考。惟列子所載：「楊朱曰：『伯成子高不以一毫利物，舍國而隱耕。古之人損一毫利天下，不與也，人人不損一毫，不利天下，天下治矣。』禽子問楊朱曰：『去子體之一毛以濟一世，汝為之乎？』楊子曰：『世固非一毛之所濟。』禽子曰：『假濟，為之乎？』楊子弗應。禽子出語孟孫陽，陽曰：『有侵若肌膚獲萬金者，若為之乎？』曰：『為之。』曰：『有斷若一節得一國，子為之乎？』禽子默然。陽曰：『積一毛以成肌膚，積肌膚以成一節，一毛固一體萬分中之一物，奈何輕之？』」觀此，則孟氏之言可證矣。","sortOrder":31},
  {"id":"s_work_dtbt_32_32","chapterId":"ch_work_dtbt_32","text":"李長吉詩","sortOrder":32},
  {"id":"s_work_dtbt_32_33","chapterId":"ch_work_dtbt_32","text":"李長吉有羅浮山人詩雲：「欲剪湘中一尺天，吳娥莫道吳刀澀。」正用杜老題王宰畫山水圖歌，「焉得幷州快剪刀，剪取吳松半江水」之句。長吉非蹈襲人後者，疑亦偶同，不失自為好語也。","sortOrder":33},
  {"id":"s_work_dtbt_32_34","chapterId":"ch_work_dtbt_32","text":"子夏經學","sortOrder":34},
  {"id":"s_work_dtbt_32_35","chapterId":"ch_work_dtbt_32","text":"孔子弟子惟子夏於諸經獨有書，雖傳記雜言未可盡信，然要為與他人不同矣。於易則有傳，於詩則有序。而毛詩之學，一雲，子夏授高行子，四傳而至小毛公；一雲，子夏傳曾申，五傳而至大毛公。於禮則有儀禮喪服一篇，馬融、王肅諸儒多為之訓說。於春秋，所雲「不能贊一辭」，蓋亦嘗從事於斯矣。公羊高實受之於子夏，穀梁赤者，風俗通亦雲子夏門人。於論語，則鄭康成以為仲弓、子夏等所撰定也。後漢徐防上疏曰：「詩、書、禮、樂，定自孔子，發明章句，始於子夏。」斯其證雲。","sortOrder":35},
  {"id":"s_work_dtbt_32_36","chapterId":"ch_work_dtbt_32","text":"容齋續筆","sortOrder":36},
  {"id":"s_work_dtbt_33_1","chapterId":"ch_work_dtbt_33","text":"卷第十五(十三則)","sortOrder":1},
  {"id":"s_work_dtbt_33_2","chapterId":"ch_work_dtbt_33","text":"紫閣山村詩","sortOrder":2},
  {"id":"s_work_dtbt_33_3","chapterId":"ch_work_dtbt_33","text":"宣和間，朱勔挾花石進奉之名，以固寵規利。東南部使者郡守多出其門，如徐鑄、應安道、王仲閎輩濟其惡，豪奪漁取，士民家一石一木稍堪玩，即領健卒直入其家，用黃封表志，而未即取，護視微不謹，則被以大不恭罪，及發行，必撤屋決牆而出。人有一物小異，共指為不祥，唯恐芟夷之不速。楊戩、李彥創汝州西城所，任輝彥、李士渙、王滸、毛孝立之徒，亦助之發物供奉，大抵類勔，而又有甚焉者。徽宗患其擾，屢禁止之，然覆出為惡，不能絕也。偶讀白樂天紫閣山北村詩，乃知唐世固有是事。漫錄於此：「晨遊紫閣峯，暮宿山下村。村老見予喜，為予開一罇。舉杯未及飲，暴卒來入門。紫衣挾刀斧，草草十餘人。奪我席上酒，掣我盤中飱。主人退後立，斂手反如賓。中庭有奇樹，種來三十春。主人惜不得，持斧斷其根。口稱采造家，身屬神策軍。主人切勿語，中尉正承恩。」蓋貞元、元和間也。","sortOrder":3},
  {"id":"s_work_dtbt_33_4","chapterId":"ch_work_dtbt_33","text":"李林甫秦檜","sortOrder":4},
  {"id":"s_work_dtbt_33_5","chapterId":"ch_work_dtbt_33","text":"李林甫為宰相，妒賢嫉能，以裴耀卿、張九齡在己上，以李適之爭權，設詭計去之。若其所引用，如牛仙客至終於位，陳希烈及見其死，皆共政六七年。雖兩人伴食諂事，所以能久，然林甫以忮心賊害，亦不朝慍暮喜，尚能容之。秦檜則不然，其始也，見其能助我，自冗散小官，不三二年至執政。史才由御史檢法官超右正言，遷諫議大夫，遂簽書樞密。施鉅由中書檢正、鄭仲熊由正言，同除權吏部侍郎。方受告正謝，施即參知政事，鄭為簽樞。宋樸為殿中侍御史，欲驟用之，令臺中申稱本臺缺檢法主簿，須長貳乃可辟。即就狀奏除侍御史，許薦舉，遽拜中丞，謝日除簽樞，其捷如此。然數人者不能數月而罷。楊願最善佞，至飲食動作悉效之。秦嘗因食，噴嚏失笑，願於倉卒間，亦陽噴飯而笑，左右侍者哂焉。秦察其奉己，愈喜。既歷歲亦厭之，諷御史排擊而預告之，願涕淚交頤。秦曰：「士大夫出處常事耳，何至是？」願對曰：「願起賤微，致身此地，已不啻足，但受太師生成恩，過於父母，一旦別去，何時復望車塵馬足邪？是所以悲也。」秦益憐之，使以本職奉祠，僅三月起知宣州。李若穀罷參政，或曰：「胡不效楊原仲之泣？」李河北人，有直氣。笑曰：「便打殺我，亦撰眼淚不出。」秦聞而大怒，遂有江州居住之命。秦嘗以病謁告，政府獨有餘堯弼，因奏對，高宗訪以機務，一二不能答。秦病愈入見，上曰：「餘堯弼既參大政，朝廷事亦宜使之與聞。」秦退，扣餘曰：「比日榻前所詢何事？」餘具以告。秦呼省吏取公牘閱視，皆已書押。責之曰：「君既書押了，安得言弗知？是故欲相賣耳！」餘離席辯析，不復應。明日臺評交章。段拂為人憒憒，一日，秦在前開陳頗久，遂俯首瞌睡。秦退始覺，殊窘怖，上猶慰拊之，且詢其鄉里。少頃，還殿廊幕中。秦閉目誦佛，典客贊揖至三，乃答。歸政事堂，窮詰其語，無以對，旋遭劾，至於責居。湯思退在樞府，上偶回顧，有所問。秦是日所奏，微不合。即雲：「陛下不以臣言為然，乞問湯思退。」上曰：「此事朕豈不曉，何用問他湯思退？」秦還省見湯，已不樂，謀去之。會其病，迨於亡，遂免。考其所為，蓋出偃月堂之上也。","sortOrder":5},
  {"id":"s_work_dtbt_33_6","chapterId":"ch_work_dtbt_33","text":"註書難","sortOrder":6},
  {"id":"s_work_dtbt_33_7","chapterId":"ch_work_dtbt_33","text":"註書至難，雖孔安國、馬融、鄭康成、王弼之解經，杜元凱之解左傳，顏師古之註漢書，亦不能無失。王荊公詩新經，「八月剝棗」解雲：「剝者，剝其皮而進之，所以養老也。」毛公本註雲：「剝，擊也。」陸德明音普卜反。公皆不用。後從蔣山郊步至民家，問其翁安在？曰：「去撲棗。」始悟前非。即具奏乞除去十三字，故今本無之。洪慶善註楚辭九歌東君篇：「緪瑟兮交鼓，簫鐘兮瑤簴。」引儀禮鄉飲酒章「間歌魚麗，笙由庚。歌南有嘉魚，笙崇丘」為比，雲：「簫鐘者，取二樂聲之相應者互奏之。」既鏤板，置於墳庵，一蜀客過而見之，曰：「一本簫作（扌肅），廣韻訓為擊也。蓋是擊鐘，正與緪瑟為對耳。」慶善謝而亟改之。政和初，蔡京禁蘇氏學，蘄春一士獨杜門註其詩，不與人往還。錢伸仲為黃岡尉，因考校上舍，往來其鄉，三進謁然後得見。首請借閱其書，士人指案側巨編數十，使隨意抽讀，適得和楊公濟梅花十絕：「月地雲階漫一尊，玉奴終不負東昏。臨春結綺荒荊棘，誰信幽香是返魂。」註雲：「玉奴，齊東昏侯潘妃小字。臨春、結綺者，陳後主三閣之名也。」伸仲曰：「所引止於此耳？」曰：「然。」伸仲曰：「唐牛僧孺所作周秦行紀，記入薄太後廟，見古後妃輩，所謂月地雲階見洞仙，東昏以玉兒故，身死國除，不擬負他，乃是此篇所用。先生何為沒而不書？」士人恍然失色，不復一語，顧其子然紙炬悉焚之。伸仲勸使姑留之，竟不可。曰：「吾枉用工夫十年，非君幾貽士林嗤笑。」伸仲每談其事，以戒後生。但玉奴乃楊貴妃自稱，潘妃則名玉兒也。剝棗之說，得於吳說、傅朋，簫鐘則慶善自言也。紹興初，又有傅洪秀才註坡詞，鏤板錢塘，至於「不知天上宮闕，今夕是何年」，不能引「共道人間惆悵事，不知今夕是何年」之句。「笑怕薔薇」，「學畫鴉黃未就」，不能引南部煙花錄，如此甚多。","sortOrder":7},
  {"id":"s_work_dtbt_33_8","chapterId":"ch_work_dtbt_33","text":"書易脫誤","sortOrder":8},
  {"id":"s_work_dtbt_33_9","chapterId":"ch_work_dtbt_33","text":"經典遭秦火之餘，脫亡散落，其僅存於今者，相傳千歲，雖有錯誤，無由復改。漢藝文志載：「劉向以中古文易經校施、孟、梁丘經，或脫去『無咎』、『悔亡』，唯費氏經與古文同。以尚書校歐陽、夏侯三家經文，酒誥脫簡一，召誥脫簡二。率簡二十五字者，脫亦二十五字，簡二十二字者，脫亦二十二字。」今世所存者，獨孔氏古文，故不見二篇脫處。周易雜卦自乾、坤以至需、訟，皆以兩兩相從，而明相反之義，若大過至夬八卦則否。蓋傳者之失也。東坡始正之。元本雲：「大過，顛也。姤，遇也，柔遇剛也。漸，女歸待男行也。頤，養正也。既濟，定也。歸妹，女之終也。未濟，男之窮也。夬，決也，剛決柔也，君子道長，小人道憂也。」坡改雲：「頤，養正也。大過，顛也。姤，遇也，柔遇剛也。夬，決也，剛決柔也，君子道長，小人道憂也。漸，女歸待男行也。歸妹，女之終也。既濟，定也。未濟，男之窮也。」謂如此而相從之次，相反之義，煥然若合符節矣。尚書洪範「四，五紀：一曰歲，二曰月，三曰日，四曰星辰，五曰曆數」，便合繼之以「王省惟歲，卿士惟月，師尹惟日」。至於「月之從星，則以風雨」一章，乃接「五皇極」，亦以簡編脫誤，故失其先後之次。「五皇極」之中，蓋亦有雜「九，五福」之文者。如「斂時五福，用敷錫厥庶民」，「凡厥正人，既富方穀，汝弗能使有好於而家，時人斯其辜，於其無好德，汝雖錫之福，其作汝用咎」，及上文「而康而色，曰予攸好德，汝則錫之福」是也。康誥自「惟三月，哉生魄」至「乃洪大誥治」四十八字，乃是洛誥，合在篇首「周公拜手」之前。武成一篇，王荊公始正之。自「王朝步自周，於征伐商」，即繼以「厎商之罪，告於皇天後土」至「一戎衣，天下大定」，乃繼以「厥四月，哉生明」至「予小子其承厥志」，然後及「乃反商政」，以訖終篇，則首尾亦粲然不紊。","sortOrder":9},
  {"id":"s_work_dtbt_33_10","chapterId":"ch_work_dtbt_33","text":"南陔六詩","sortOrder":10},
  {"id":"s_work_dtbt_33_11","chapterId":"ch_work_dtbt_33","text":"南陔、白華、華黍、由庚、崇邱、由儀六詩，毛公為詩詁訓傳，各置其名，述其義，而亡其辭。鄉飲酒、燕禮雲「笙入堂下，磬南北面立。樂奏南陔、白華、華黍」，「乃間歌魚麗，笙由庚；歌南有嘉魚，笙崇丘；歌南山有臺，笙由儀；乃合樂，周南關雎、葛覃、卷耳，召南鵲巢、采蘋、采蘩」。竊詳文意，所謂歌者，有其辭所以可歌，如魚麗、嘉魚、關雎以下是也；亡其辭者不可歌，故以笙吹之，南陔至於由儀是也。有其義者，謂「孝子相戒以養」、「萬物得由其道」之義，亡其辭者，元未嘗有辭也。鄭康成始以為及秦之世而亡之。又引燕禮「升歌鹿鳴、下管新宮」為比，謂新宮之詩亦亡。按左傳宋公享叔孫昭子，賦新宮。杜註為逸詩，則亦有辭，非諸篇比也。陸德明音義雲：「此六篇蓋武王之詩，周公製禮，用為樂章，吹笙以播其曲。孔子刪定在三百一十一篇內。及秦而亡。」蓋祖鄭說耳。且古詩經刪及逸不存者多矣，何獨列此六名於大序中乎？束晳補亡六篇，不作可也。左傳叔孫豹如晉，晉侯享之，金奏肆夏、韶夏、納夏，工歌文王、大明、、鹿鳴、四牡、皇皇者華。三夏者樂曲名，擊鐘而奏，亦以樂曲無辭，故以金奏，若六詩則工歌之矣，尤可證也。","sortOrder":11},
  {"id":"s_work_dtbt_33_12","chapterId":"ch_work_dtbt_33","text":"紹聖廢春秋","sortOrder":12},
  {"id":"s_work_dtbt_33_13","chapterId":"ch_work_dtbt_33","text":"五聲本於五行，而徵音廢。四瀆源於四方，而濟水絕。周官六典所以布治，而司空之書亡。是固出於無可奈何，非人力所能為也。乃若六經載道，而王安石欲廢春秋。紹聖中，章子厚作相，蔡卞執政，遂明下詔罷此經，誠萬世之罪人也。","sortOrder":13},
  {"id":"s_work_dtbt_33_14","chapterId":"ch_work_dtbt_33","text":"王韶熙河","sortOrder":14},
  {"id":"s_work_dtbt_33_15","chapterId":"ch_work_dtbt_33","text":"王韶取熙河，國史以為嘗遊陝西，采訪邊事，遂詣闕上書。偶讀晁以道集與熙河錢經略書，雲：「熙河一道，曹南院棄而不城者也。其後夏英公喜功名，欲城之，其如韓、范之論何？又其後有一王長官韶者，薄遊陽翟，偶見英公神道碑所載雲雲，遂竊以為策以幹丞相。時丞相是謂韓公，視王長官者稚而狂之。若河外數州，則又王長官棄而不城者也。彼木征之志不淺，鬼章之睥睨尤近而著者，隴拶似若無能，頗聞有子存，實有不可不懼者。」此書蓋是元祐初年，然則韶之本指乃如此。予修史時未得其說也。英公碑，王岐公所作，但雲嘗上十策。若通唃廝囉之屬羌。當時施用之，餘皆不書，不知晁公所指為何也？","sortOrder":15},
  {"id":"s_work_dtbt_33_16","chapterId":"ch_work_dtbt_33","text":"書籍之厄","sortOrder":16},
  {"id":"s_work_dtbt_33_17","chapterId":"ch_work_dtbt_33","text":"梁元帝在江陵，蓄古今圖書十四萬卷，將亡之夕盡焚之。隋嘉則殿有書三十七萬卷，唐平王世充，得其舊書於東都，浮舟泝河，盡覆於砥柱。貞觀、開元募借繕寫，兩都各聚書四部。祿山之亂，尺簡不藏。代宗、文宗時，復行搜采，分藏於十二庫。黃巢之亂，存者蓋尠。昭宗又於諸道求訪，及徙洛陽，蕩然無遺。今人觀漢、隋、唐經籍藝文志，未嘗不茫然太息也。晁以道記本朝王文康初相周世宗，多有唐舊書，今其子孫不知何在。李文正所藏既富，而且闢學館以延學士大夫，不待見主人，而下馬直入讀書。供牢餼以給其日力，與衆共利之。今其家僅有敗屋數楹，而書不知何在也！宋宣獻家兼有畢文簡、楊文莊二家之書，其富蓋有王府不及者。元符中，一夕災為灰燼。以道自謂家五世於茲，雖不敢與宋氏爭多，而校讎是正，未肯自遜。政和甲午之冬，火亦告譴。唯劉壯輿家於廬山之陽，自其祖凝之以來，遺子孫者唯圖書也，其書與七澤俱富矣。於是為作記。今劉氏之在廬山者不聞其人，則所謂藏書殆亦羽化。乃知自古到今，神物亦於斯文為靳靳也。宣和殿、太清樓、龍圖閣御府所儲，靖康蕩析之餘，盡歸於燕，置之祕書省，乃有幸而得存者焉。","sortOrder":17},
  {"id":"s_work_dtbt_33_18","chapterId":"ch_work_dtbt_33","text":"逐貧賦","sortOrder":18},
  {"id":"s_work_dtbt_33_19","chapterId":"ch_work_dtbt_33","text":"韓文公送窮文，柳子厚乞巧文，皆擬揚子雲逐貧賦。韓公進學解擬東方朔客難，柳子晉問篇擬枚乘七發、貞符擬劇秦美新，黃魯直跛奚移文擬王子淵僮約，皆極文章之妙。逐貧一賦幾五百言，文選不收，初學記所載纔百餘字，今人蓋有未之見者，輒錄於此，雲：「揚子遁世，離俗獨處。左鄰崇山，右接曠野。鄰垣乞兒，終貧且窶。禮薄義弊，相與羣聚。惆悵失志，呼貧與語：『汝在六極，投棄荒遐。好為庸卒，刑戮是加。匪惟幼稚，嬉戲土沙。居非近鄰，接屋連家。恩輕毛羽，義薄輕羅。進不由德，退不受訶。久為滯客，其意若何？人皆文繡，餘褐不全。人皆稻粱，我獨藜飡。貧無寶玩，何以接歡。宗室之宴，為樂不槃。徒行負賃，出處易衣。身服百役，手足胼胝。或耘或耔，霑體露肌。朋友道絕，進官凌遲。厥咎安在，職女之為。舍女遠竄，崑崙之顛。爾復我隨，翰飛戾天。舍爾登山，巖穴隱藏。爾復我隨，陟彼高岡。舍爾入海，汎彼柏舟。爾復我隨，載沉載浮。我行爾動，我靜爾休。豈無他人，從我何求？今汝去矣，勿復久留！』貧曰：『唯唯，主人見逐，多言益嗤。心有所懷，願得盡辭。昔我乃祖，崇其明德。克佐帝堯，誓為典則。土階茅茨，匪雕匪飾。爰及季世，縱其昏惑。饕餮之羣，貪富苟得。鄙我先人，乃傲乃驕。瑤臺瓊室，華屋崇高。流酒為池，積肉為崤。是用鵠逝，不踐其朝。三省吾身，謂予無諐。處君之家，福祿如山。忘我大德，思我小怨。堪寒能暑，少而習焉。寒暑不忒，等壽神仙。桀跖不顧，貪類不幹。人皆重蔽，子獨露居。人皆怵惕，子獨無虞。』言辭既罄，色厲目張。攝齊而興，降階下堂。『誓將去汝，適彼首陽。孤竹之子，與我連行。』餘乃避席，辭謝不直：『請不貳過，聞義則服。長與爾居，終無厭極。』貧遂不去，與我遊息。」唐宣宗時，有文士王振自稱「紫邏山人」，有送窮辭一篇，引韓吏部為說，其文意亦工。","sortOrder":19},
  {"id":"s_work_dtbt_33_20","chapterId":"ch_work_dtbt_33","text":"澗松山苗","sortOrder":20},
  {"id":"s_work_dtbt_33_21","chapterId":"ch_work_dtbt_33","text":"詩文當有所本，若用古人語意，別出機杼，曲而暢之，自足以傳示來世。左太沖詠史詩曰：「鬱鬱澗底松，離離山上苗。以彼徑寸莖，蔭此百尺條。世胄躡高位，英俊沉下僚。地勢使之然，由來非一朝。」白樂天續古一篇，全用之，曰：「雨露長纖草，山苗高入雲。風雪折勁木，澗松摧為薪。風摧此何意，雨長彼何因？百尺澗底死，寸莖山上春。」語意皆出太沖，然其含蓄頓挫，則不逮也。","sortOrder":21},
  {"id":"s_work_dtbt_33_22","chapterId":"ch_work_dtbt_33","text":"男子運起寅","sortOrder":22},
  {"id":"s_work_dtbt_33_23","chapterId":"ch_work_dtbt_33","text":"今之五行家學，凡男子小運起於寅，女子小運起於申，莫知何書所載？淮南子氾論訓篇雲：「禮三十而娶。」許叔重註曰：「三十而娶者，陰陽未分時俱生於子，男從子數左行三十年立於巳，女從子數右行二十年亦立於巳，合夫婦，故聖人因是製禮，使男子三十而娶，女二十而嫁。其男子自巳數左行十得寅，故人十月而生於寅，故男子數從寅起；女自巳數右行得申，亦十月而生於申，故女子數從申起。」此說正為起運也。","sortOrder":23},
  {"id":"s_work_dtbt_33_24","chapterId":"ch_work_dtbt_33","text":"宰我作難","sortOrder":24},
  {"id":"s_work_dtbt_33_25","chapterId":"ch_work_dtbt_33","text":"史記稱宰我為齊臨菑大夫，與田常作難，以夷其族，孔子恥之。蘇子由作古史，精為辯之，以為子我者闞止也，與田常爭齊政，為常所殺，以其字亦曰子我，故戰國之書誤以為宰予。此論既出，聖門高第，得免非義之謗。東坡又引李斯諫書，謂「田常陰取齊國，殺宰予於庭」。是其不從田常，故為所殺也。予又考之，子路之死，孔子曰：「由也死矣。」又曰：「天祝予！」哭於中庭，使人覆醢，其悲之如是，不應宰我遇禍，略無一言。孟子所載三子論聖人賢於堯、舜等語，疑是夫子沒後所談，不然，師在而各出意見議之，無復質正，恐非也。然則宰我不死於田常，更可證矣。而淮南子又有一說雲：「將相攝威擅勢，私門成黨，而使道不行。故使陳成、田常、鴟夷子皮得成其難，使呂氏絕祀。」子皮謂范蠡也，蠡浮海變姓名遊齊，時簡公之難已十餘年矣。說苑亦雲：「田常與宰我爭，宰我將攻之，鴟夷子皮告田常，遂殘宰我。」此說尤為無稽，是以蠡為助田氏為齊禍，其不分賢逆如此。","sortOrder":25},
  {"id":"s_work_dtbt_33_26","chapterId":"ch_work_dtbt_33","text":"古人占夢","sortOrder":26},
  {"id":"s_work_dtbt_33_27","chapterId":"ch_work_dtbt_33","text":"漢藝文志七略雜占十八家，以黃帝長柳占夢十一卷，甘德長柳占夢二十卷為首，其說曰：「雜占者，紀百家之象，候善惡之證。衆占非一，而夢為大，故周有其官。」周禮：「太卜，掌三夢之法，一曰致夢，二曰觭夢，三曰鹹陟。」鄭氏以為致夢夏後氏所作，觭夢商人所作，鹹陟者言夢之皆得，周人作焉。而占夢專為一官，以日月星辰占六夢之吉凶，其別：曰正、曰噩、曰思、曰寤、曰喜、曰懼。季冬，聘王夢，獻吉夢於王，王拜而受之。乃舍萌於四方，以贈惡夢。舍萌者，猶釋采也。贈者，送之也。詩、書、禮經所載，高宗夢得說；周文王夢帝與九齡；武王伐紂，夢葉朕卜；宣王考牧，牧人有熊羆虺蛇之夢，召彼故老，訊之占夢。左傳所書尤多。孔子夢坐奠於兩楹。然則古之聖賢，未嘗不以夢為大，是以見於七略者如此。魏、晉方技，猶時時或有之。今人不復留意此卜，雖市井妄術，所在如林，亦無一箇以占夢自名者，其學殆絕矣。","sortOrder":27},
  {"id":"s_work_dtbt_33_28","chapterId":"ch_work_dtbt_33","text":"容齋續筆","sortOrder":28},
  {"id":"s_work_dtbt_34_1","chapterId":"ch_work_dtbt_34","text":"卷第十六(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_34_2","chapterId":"ch_work_dtbt_34","text":"高德儒","sortOrder":2},
  {"id":"s_work_dtbt_34_3","chapterId":"ch_work_dtbt_34","text":"唐高祖起兵太原，使子建成、世民將兵擊西河郡，執郡丞高德儒，世民數之曰：「汝指野鳥為鸞，以欺人主取高官，吾興義兵，正為誅佞人耳。」遂斬之，自餘不戮一人。讀史不熟者，但以為史氏虛設此語，以與指鹿為馬作對耳。按隋大業十一年，有二孔雀飛集寶城朝堂前，親衞校尉高德儒等十餘人見之，奏以為鸞，時孔雀已飛去，無可得驗。詔以德儒誠心冥會，肇見嘉祥，擢拜朝散大夫，餘人皆賜束帛；仍於其地造儀鸞殿。距此時纔二年餘。蓋唐溫大雅所著創業起居註載之，不追書前事故也。新唐書太宗紀，但書雲：「率兵徇西河，斬其郡丞高德儒。」尤為簡略，賴通鑑盡紀其詳。范氏唐鑑只論其被誅一節雲。","sortOrder":3},
  {"id":"s_work_dtbt_34_4","chapterId":"ch_work_dtbt_34","text":"唐朝士俸微","sortOrder":4},
  {"id":"s_work_dtbt_34_5","chapterId":"ch_work_dtbt_34","text":"唐世朝士俸錢至微，除一項之外，更無所謂料券、添給之類者。白樂天為校書郎，作詩曰：「幸逢太平代，天子好文儒。小才難大用，典校在祕書。俸錢萬六千，月給亦有餘。遂使少年心，日日常晏如。」及為翰林學士，當遷官，援薑公輔故事，但乞兼京兆府戶曹參軍，既除此職，喜而言志，至雲：「詔授戶曹掾，捧詔感君恩。弟兄俱簪笏，新婦儼衣巾。羅列高堂下，拜慶正紛紛。喧喧車馬來，賀客滿我門。置酒延賀客，不復憂空罇。」而其所得者，亦俸錢四五萬，廩祿二百石而已。今之主簿、尉，占優飫處，固有倍蓰於此者矣，亦未嘗以為足，古今異宜，不可一概論也。楊文公在真宗朝為翰林學士，而雲：「虛忝甘泉之從臣，終作若敖之餒鬼。」蓋是時尚為鮮薄，非後來比也。","sortOrder":5},
  {"id":"s_work_dtbt_34_6","chapterId":"ch_work_dtbt_34","text":"計然意林","sortOrder":6},
  {"id":"s_work_dtbt_34_7","chapterId":"ch_work_dtbt_34","text":"漢書貨殖傳：「粵王句踐困於會稽之上，乃用范蠡、計然，遂報強吳。」孟康註曰：「姓計名然，越臣也。」蔡謨曰：「『計然』者，范蠡所著書篇名耳，非人也。謂之計然者，所計而然也。羣書所稱句踐之賢佐，種、蠡為首，豈復聞有姓計名然者乎？若有此人，越但用半策，便以致霸，是功重於范蠡，而書籍不見其名，史遷不述其傳乎？」顏師古曰：「蔡說謬矣。古今人表，計然列在第四等，一名計研。班固賓戲：『研、桑心計於無垠。』即謂此耳。計然者，濮上人也，嘗南遊越，范蠡卑身事之，其書則有萬物錄，事見皇覽及晉中經簿。又吳越春秋及越絕書，並作計倪。此則倪、研及然，聲皆相近，實一人耳。何雲書籍不見哉？」","sortOrder":7},
  {"id":"s_work_dtbt_34_8","chapterId":"ch_work_dtbt_34","text":"予按唐貞元中，馬總所述意林一書，抄類諸子百餘家，有范子十二卷，雲：「計然者，葵丘濮上人，姓辛字文子，其先晉國之公子也，為人有內無外，狀貌似不及人，少而明，學陰陽，見微知著，其志沈沈，不肯自顯，天下莫知，故稱曰『計然』。時遨遊海澤，號曰『漁父』。范蠡請其見越王，計然曰：『越王為人烏喙，不可與同利也。』」據此則計然姓名出處，皎然可見。裴駰註史記，亦知引范子。北史蕭大圜雲：「留侯追蹤於松子，陶朱成術於辛文。」正用此事。曹子建表引文子，李善註，以為計然，師古蓋未能盡也。而文子十二卷，李暹註，其序以謂范子所稱計然。但其書一切以老子為宗，略無與范蠡謀議之事，意林所編文子正與此同，所謂范子，乃別是一書，亦十二卷。馬總只載其敍計然及他三事，雲：「餘並陰陽曆數，故不取。」則與文子了不同，李暹之說誤也。唐藝文志范子計然十五卷，註雲：「范蠡問，計然答。」列於農家，其是矣，而今不存。唐世未知尊孟氏，故意林亦列其書，而有差不同者，如伊尹不以一介與人，亦不取一介於人之類。其他所引書，如胡非子、隨巢子、纏子、王孫子、公孫尼子、阮子正部、姚信士緯、殷興通語、牟子、周生烈子、秦菁子、梅子、任弈子、魏朗子、唐滂子、鄒子、孫氏成敗志、蔣子、譙子、鍾子、張儼默記、裴氏新言、袁淮正書、袁子正論、蘇子、陸子、張顯析言、於子、顧子、諸葛子、陳子要言、符子諸書，今皆不傳於世，亦有不知其名者。","sortOrder":8},
  {"id":"s_work_dtbt_34_9","chapterId":"ch_work_dtbt_34","text":"思潁詩","sortOrder":9},
  {"id":"s_work_dtbt_34_10","chapterId":"ch_work_dtbt_34","text":"士大夫發跡壟畝，貴為公卿，謂父祖舊廬為不可居，而更新其宅者多矣。復以醫藥弗便，飲膳難得，自村而遷於邑，自邑而遷於郡者亦多矣。唯翩然委而去之，或遠在數百千里之外，自非有大不得已，則舉動為不宜輕。若夫以為得計，又從而詠歌誇詡之，著於詩文，是其一時思慮，誠為不審，雖名公鉅人，未能或之免也。歐陽公，吉州廬陵人，其父崇公，葬於其里之瀧岡，公自為阡表，紀其平生。而公中年乃欲居潁，其思潁詩序雲：「予自廣陵得請來潁，愛其民淳訟簡，土厚水甘，慨然有終焉之志。爾來思潁之念，未嘗少忘於心，而意之所存，亦時時見於文字。乃發舊稿，得南京以後詩十餘篇，皆思潁之作，以見予拳拳於潁者，非一日也。」又續詩序雲：「自丁家難，服除，入翰林為學士，忽忽八年間，歸潁之志雖未遂，然未嘗一日少忘焉。至於今，年六十有四，免幷得蔡，蔡、潁連疆，因得以為歸老之漸。又得在亳及青十有七篇，附之，時熙寧三年也。」公次年致仕，又一年而薨，其逍遙於潁，蓋無幾時，惜無一語及於松楸之思。崇公惟一子耳，公生四子，皆為潁人，瀧岡之上，遂無復有子孫臨之，是因一代貴達，而墳墓乃隔為他壤。予每讀二序，輒為太息。嗟乎！此文不作可也。若東坡之居宜興，乃因免汝州居住而至，其後自海外北還，無以為歸，復暫至常州，已而捐館。文定公雖居許，而治命反葬於眉山雲。","sortOrder":10},
  {"id":"s_work_dtbt_34_11","chapterId":"ch_work_dtbt_34","text":"劉蕡下第","sortOrder":11},
  {"id":"s_work_dtbt_34_12","chapterId":"ch_work_dtbt_34","text":"唐文宗大和二年三月，親策製舉人賢良方正，劉蕡對策，極言宦官之禍。既而裴休、李郃等二十二人中第，皆除官。考官左散騎常侍馮宿、太常少卿賈餗、庫部郎中龐嚴，見蕡策，皆嘆服，而畏宦官，不敢取。詔下，物論囂然稱屈。諫官、御史欲論奏，執政抑之。李郃曰：「劉蕡下第，我輩登科，能無厚顏！」乃上疏，以為「蕡所對策，漢、魏以來無與為比。今有司以蕡指切左右，不敢以聞，恐忠良道窮，綱紀遂絕。臣所對不及蕡遠甚，乞回臣所授以旌蕡直。」不報。予按是時宰相乃裴度、韋處厚、竇易直，易直不足言，裴、韋之賢，顧獨失此，至於抑言者使勿論奏，豈不有愧於心乎？蕡既由此不得仕於朝，而李郃亦不顯，蓋無敢用之也。令狐楚、牛僧孺，乃能表蕡入幕府，待以師禮，竟為宦人所嫉誣，貶柳州司戶。李商隱贈以詩曰：「漢廷急詔誰先入，楚路高歌自欲翻。萬里相逢歡復泣，鳳巢西隔九重門。」及蕡卒，復以二詩哭之，曰：「一叫千回首，天高不為聞。」又曰：「已為秦逐客，復作楚寃魂。（亻幷）將添恨淚，一洒問乾坤！」其悲之至矣。甘露之事，相去纔七年，未知蕡及見之否乎？","sortOrder":12},
  {"id":"s_work_dtbt_34_13","chapterId":"ch_work_dtbt_34","text":"酒肆旗望","sortOrder":13},
  {"id":"s_work_dtbt_34_14","chapterId":"ch_work_dtbt_34","text":"今都城與郡縣酒務，及凡鬻酒之肆，皆揭大帘於外，以青白布數幅為之，微者隨其高卑小大，村店或掛瓶瓢，標箒稈，唐人多詠於詩。然其製蓋自古以然矣，韓非子雲：「宋人有酤酒者，斗槩甚平，遇客甚謹，為酒甚美，懸幟甚高，而酒不售，遂至於酸。」所謂懸幟者此也。","sortOrder":14},
  {"id":"s_work_dtbt_34_15","chapterId":"ch_work_dtbt_34","text":"賢宰相遭讒","sortOrder":15},
  {"id":"s_work_dtbt_34_16","chapterId":"ch_work_dtbt_34","text":"一代宗臣，當代天理物之任，君上委國而聽之，固為社稷之福，然必不使邪人參其間乃可，不然必為所勝。姑以唐世及本朝之事顯顯者言之，若褚遂良、長孫無忌之遭李義府、許敬宗，張九齡之遭李林甫是已。裴晉公相憲宗，立淮、蔡、青、鄆之功，唐之威令紀綱，既壞而復振，可謂名宰矣。皇甫鎛一共政，則去不旋踵，迨穆、敬、文三宗，主既不明，而元稹、李逢吉、宗閔更撼之，使不得一日安厥位。趙韓王以佐命元勛，而為盧多遜所勝，寇萊公為丁謂所勝，杜祁公、韓、范為陳執中、賈昌朝所勝，富韓公為王介甫所勝，范忠宣為章子厚所勝，趙忠簡為秦會之所勝，大抵皆然也。","sortOrder":16},
  {"id":"s_work_dtbt_34_17","chapterId":"ch_work_dtbt_34","text":"宋齊丘","sortOrder":17},
  {"id":"s_work_dtbt_34_18","chapterId":"ch_work_dtbt_34","text":"自用兵以來，令民間以見錢紐納稅直，既為不堪，然於其中所謂和買折帛，尤為名不正而斂最重。偶閱大中祥符間，太常博士許載著吳唐拾遺錄，所載多諸書未有者。其勸農桑一篇正雲：「吳順義年中，差官興版簿，定租稅，厥田上上者，每一頃稅錢二貫一百文，中田一頃稅錢一貫八百，下田一頃千五百，皆足陌見錢，如見錢不足，許依市價折以金銀。算計丁口課調，亦科錢。宋齊丘時為員外郎，上策乞虛擡時價，而折紬、綿、絹本色，曰：『江淮之地，唐季已來，戰爭之所。今兵革乍息，黎甿始安，而必率以見錢，折以金銀，此非民耕鑿可得也，無興販以求之，是為教民棄本逐末耳。』是時，絹每匹市價五百文，紬六百文，綿每兩十五文，齊丘請絹每匹擡為一貫七百，紬為二貫四百，綿為四十文，皆足錢，丁口課調，亦請蠲除。朝議喧然沮之，謂虧損官錢，萬數不少。齊丘致書於徐知誥曰：『明公總百官，理大國，督民見錢與金銀，求國富庶，所謂擁篲救火，撓水求清，欲火滅水清可得乎？』知誥得書，曰：『此勸農上策也。』即行之。自是不十年間，野無閒田，桑無隙地，自吳變唐，自唐歸宋，民到於今受其賜。」齊丘之事美矣。徐知誥亟聽而行之，可謂賢輔相。而九國志齊丘傳中略不書，資治通鑑亦佚此事。今之君子為國，唯知浚民以益利，豈不有靦於偏閏之臣乎？齊丘平生，在所不論也。","sortOrder":18},
  {"id":"s_work_dtbt_34_19","chapterId":"ch_work_dtbt_34","text":"鹹杬子","sortOrder":19},
  {"id":"s_work_dtbt_34_20","chapterId":"ch_work_dtbt_34","text":"玉篇、唐韻釋杬字雲：「木名，出豫章，煎汁，藏果及卵不壞。」異物志雲：「杬子，音元，鹽鴨子也。」以其用杬木皮汁和鹽漬之。今吾鄉處處有此，乃如蒼耳、益母，莖幹不純是木。小人爭鬭者，取其葉挼摖皮膚，輒作赤腫，如被傷，以誣賴其敵。至藏鴨卵，則又以染其外，使若赭色雲。","sortOrder":20},
  {"id":"s_work_dtbt_34_21","chapterId":"ch_work_dtbt_34","text":"月中桂兔","sortOrder":21},
  {"id":"s_work_dtbt_34_22","chapterId":"ch_work_dtbt_34","text":"酉陽雜俎天咫篇，載月星神異數事。其命名之義，取國語楚靈王曰「是知天咫，安知民則」之說。其紀月中蟾桂，引釋氏書，言須彌山南面有閻扶樹，月過樹，影入月中。或言月中蟾桂，地影也，空處，水影也。予記東坡公鑒空閣詩雲：「明月本自明，無心孰為境。掛空如水鑑，寫此山河影。我觀大瀛海，巨浸與天永。九州居其間，無異蛇盤鏡。空水兩無質，相照但耿耿。妄雲桂兔蟆，俗說皆可屏。」正用此說。其詩在集中，題為和黃秀才。頃予遊南海，西歸之日，泊舟金利山下，登崇福寺，有閣枕江流，標曰「鑒空」，正見詩牌揭其上，蓋當時臨賦處也。","sortOrder":22},
  {"id":"s_work_dtbt_34_23","chapterId":"ch_work_dtbt_34","text":"唐二帝好名","sortOrder":23},
  {"id":"s_work_dtbt_34_24","chapterId":"ch_work_dtbt_34","text":"唐貞觀中，忽有白鵲營巢於寢殿前槐樹上，其巢合歡如腰鼓。左右拜舞稱賀，太宗曰：「我常笑隋煬帝好祥瑞，瑞在得賢，此何足賀？」乃命毀其巢，放鵲於野外。明皇初即位，以風俗奢靡，製乘輿服御金銀器玩，令有司銷毀，以供軍國之用。其珠玉錦繡焚於殿前，天下毋得復采織，罷兩京織錦坊。予謂二帝，皆唐之明主，所言所行，足以垂訓於後，然大要出於好名。鵲巢之異，左右從而獻諛，叱而去之可也，何必毀其巢？珠玉錦繡，勿珍而尚之可也，何必焚之殿前，明以示外，使家至戶曉哉！治道貴於執中，是二者懼不可以為法。其後楊貴妃有寵，織繡之工，專供妃院者七百人，中外爭獻器服珍玩。嶺南經略使張九皋、廣陵長史王翼，以所獻精靡，九皋加三品，翼入為戶部侍郎，天下從風而靡，明皇之始終，一何不同如此哉！","sortOrder":24},
  {"id":"s_work_dtbt_34_25","chapterId":"ch_work_dtbt_34","text":"周禮非周公書","sortOrder":25},
  {"id":"s_work_dtbt_34_26","chapterId":"ch_work_dtbt_34","text":"周禮一書，世謂周公所作，而非也，昔賢以為戰國陰謀之書，考其實，蓋出於劉歆之手。漢書儒林傳，盡載諸經專門師授，此獨無傳。至王莽時，歆為國師，始建立周官經以為周禮，且置博士。而河南杜子春受業於歆，還家以教門徒，好學之士鄭興，及其子衆往師之，此書遂行。歆之處心積慮，用以濟莽之惡，莽據以毒痡四海，如五均、六筦、市官、賒貸，諸所興為，皆是也。故當其時，公孫祿既已斥歆顛倒六經毀師法矣。歷代以來，唯宇文周依六典以建官，至於治民發政，亦未嘗循故轍。王安石欲變亂祖宗法度，乃尊崇其言，至與詩、書均匹，以作三經新義，其序略曰：「其人足以任官，其官足以行法，莫盛乎成周之時；其法可施於後世，其文有見於載籍，莫具乎周官之書。自周之衰，以至於今，太平之遺跡，掃蕩幾盡，學者所見無復全經。於是時也，乃欲訓而發之，臣知其難也。以訓而發之之難，則又以知夫立政造事追而復之之為難。」則安石所學所行實於此乎出。遂謂：「一部之書，理財居其半。」又謂：「泉府，凡國之財用取具焉，歲終，則會其出入而納其餘，則非特摧兼幷，救貧阨，因以足國事之財用。夫然故雖有不庭不虞，民不加賦，而國無乏事。」其後呂嘉問法之而置市易，由中及外，害遍生靈。嗚呼！二王託周官之名以為政，其歸於禍民一也。","sortOrder":26},
  {"id":"s_work_dtbt_34_27","chapterId":"ch_work_dtbt_34","text":"醉尉亭長","sortOrder":27},
  {"id":"s_work_dtbt_34_28","chapterId":"ch_work_dtbt_34","text":"李廣免將軍為庶人，屏居藍田，嘗夜從一騎出，從人田間飲，還至亭，霸陵尉醉呵止廣。後廣拜右北平太守，請尉與俱，至軍而斬之，上書自陳謝罪，武帝報曰：「報忿除害，朕之所圖於將軍也。」王莽竊位，尤備大臣抑奪下權，大司空士夜過奉常亭，亭長呵之，告以官名，亭長醉曰：「寧有符傳邪！」士以馬箠擊亭長，亭長斬士，亡，郡縣逐之。家上書，莽曰：「亭長奉公，勿逐。」大司空王邑斥士以謝。予觀此兩亭尉長，其醉等耳。霸陵尉但呵止李廣，而廣殺之，武帝不問，奉常亭長殺宰士，而王莽反以奉公免之，亦可笑也。","sortOrder":28},
  {"id":"s_work_dtbt_34_29","chapterId":"ch_work_dtbt_34","text":"三易之名","sortOrder":29},
  {"id":"s_work_dtbt_34_30","chapterId":"ch_work_dtbt_34","text":"三易之名，一曰連山，二曰歸藏，三曰周易，皆以兩字為義。今人但稱周易曰易，非也。夏曰連山，其卦以純艮為首，艮為山，山上山下，是名連山。雲氣出內於山，故名易為連山。商曰歸藏，以純坤為首，坤為地，萬物莫不歸而藏於中，故名為歸藏。周曰周易，以純乾為首，乾為天，天能周匝於四時，故名易為周也。太簇為人統，寅為人正。夏以十三月為正，人統，人無為卦首之理，艮漸正月，故以艮為首。林鍾為地統，未之衝丑，故為地正，商以十二月為正，地統，故以坤為首。黃鍾為天統，子為天正，周以十一月為正，天統，故以乾為首。此本出唐賈公彥周禮正義之說，予整齊而紀之。所謂十三月者，承十二月而言，即正月耳。後漢陳寵論之甚詳，本出尚書大傳。","sortOrder":30},
  {"id":"s_work_dtbt_34_31","chapterId":"ch_work_dtbt_34","text":"忠臣名不傳","sortOrder":31},
  {"id":"s_work_dtbt_34_32","chapterId":"ch_work_dtbt_34","text":"古今忠臣義士，其名載於史策者，萬世不朽，然有不幸而泯沒無傳者。南唐後主，淫於浮圖氏，二人繼踵而諫，一獲徒，一獲流。歙人汪煥為第三諫，極言請死，雲：「梁武事佛，刺血寫佛經，散髮與僧踐，捨身為佛奴，屈膝禮和尚，及其終也，餓死於臺城。今陛下事佛，未見刺血、踐髮、捨身、屈膝，臣恐他日猶不得如梁武之事。」後主覽書，赦而官之。又有淮人李雄，當王師弔伐，出守西偏，不遇其敵。雄以國城重圍，不忍端坐，遂東下以救之，陣於溧陽，與王師遇，父子俱沒，諸子不從行者亦死他所，死者凡八人。李氏訖亡，不霑褒贈，其事僅見於吳唐拾遺錄。頃嘗有旨合九朝國史為一書，他日史官為列之於李煜傳，庶足以慰二人於泉下。歐陽公作吳某墓誌雲：「李煜時，為彭澤主簿，曹彬破池陽，遣使者招降郡縣，其令欲以城降，某曰：『吾能為李氏死爾。』乃殺使者，為煜守。煜已降，某為遊兵執送軍中，主將責以殺使者，曰：『固當如是。』主將義而釋之。」其事雖粗見，而集中只雲「諱某」，為可惜也。如靖康之難，朱昭等數人死於震武城之類，予得朱弁所作忠義錄於其子栐，乃為作傳於四朝史中，蓋惜其無傳也。","sortOrder":32},
  {"id":"s_work_dtbt_34_33","chapterId":"ch_work_dtbt_34","text":"唐人酒令","sortOrder":33},
  {"id":"s_work_dtbt_34_34","chapterId":"ch_work_dtbt_34","text":"白樂天詩：「鞍馬呼教住，骰盤喝遣輸。長驅波卷白，連擲采成盧。」註雲：骰盤、卷白波、莫走鞍馬，皆當時酒令。予按皇甫松所著醉鄉日月三卷，載骰子令雲：聚十隻骰子齊擲，自出手六人，依采飲焉。堂印，本采人勸合席，碧油，勸擲外三人。骰子聚於一處，謂之酒星，依采聚散。骰子令中，改易不過三章，次改鞍馬令，不過一章。又有旗幡令、閃擪令、拋打令。今人不復曉其法矣，唯優伶家，猶用手打令以為戲雲。","sortOrder":34},
  {"id":"s_work_dtbt_35_1","chapterId":"ch_work_dtbt_35","text":"卷第一(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_35_2","chapterId":"ch_work_dtbt_35","text":"晁景迂經說","sortOrder":2},
  {"id":"s_work_dtbt_35_3","chapterId":"ch_work_dtbt_35","text":"景迂子晁以道留意六經之學，各著一書，發明其旨，故有易規、書傳、詩序論，中庸、洪範傳、三傳說。其說多與世儒異。","sortOrder":3},
  {"id":"s_work_dtbt_35_4","chapterId":"ch_work_dtbt_35","text":"謂易之學者所謂應、所謂位、所謂承乘、所謂主，皆非是。大抵雲，繫辭言卦爻象數剛柔變通之類非一，未嘗及初應四、二應五、三應六也。以陽居陽、以陰居陰為得位，得位者吉。以陽居陰、以陰居陽為失位，失位者凶。然則九五、九三、六二、六四俱善乎？六五、六三、九二、九四俱不善乎？既為有應無應、得位不得位之說，而求之或不通，則又為承乘之說。謂陰承陽則順，陽承陰則逆，陽乘柔則吉，陰乘剛則凶，其不思亦甚矣。又必以位而論中正，如六二、九五為中且正，則六五、九二俱不善乎？初、上、三、四永不得用中乎？卦各有主，而一概主之於五，亦非也。","sortOrder":4},
  {"id":"s_work_dtbt_35_5","chapterId":"ch_work_dtbt_35","text":"其論書曰：予於堯典，見天文矣，而言四時者不知中星。禹貢敷土治水，而言九州者不知經水。洪範性命之原，而言九疇者不知數。舜於四凶，以堯庭之舊而流放竄殛之。穆王將善其祥刑，而先醜其耄荒。湯之伐桀，出不意而奪農時。文王受命為僭王，召公之不說，類乎無上。太甲以不順伊尹而放，羣叔纔有流言而誅，啟行孥戮之刑以誓不用命，盤庚行劓殄之刑而遷國，周人飲酒而死，魯人不板榦而屋誅。先時不及時而殺無赦。威不可訖，老不足敬，禍不足畏，凶德不足忌之類。惟此經遭秦火煨燼之後，孔壁朽折之餘，孔安國初以隸篆推科斗。既而古今文字錯出東京，乃取正於杜林。傳至唐，彌不能一，明皇帝詔衞包悉以今文易之，其去本幾何其遠矣！今之學者盡信不疑，殆如手授於洙、泗間，不亦惑乎？論堯典中星雲，於春分日而南方井、鬼七宿合，昏畢見者，孔氏之誤也。豈有七宿百九度，而於一夕間畢見者哉？此實春分之一時正位之中星，非常夜昏見之中星也。於夏至而東方角、亢七宿合，昏畢見者，孔氏之誤也。豈有七宿七十七度，而於一夕間畢見者哉？此夏至一時之中星，非常夜昏見者也。秋分、冬至之說皆然。凡此以上，皆晁氏之說。所辯聖典，非所敢知。但驗之天文，不以四時，其同在天者常有十餘宿。自昏至旦，除太陽所舍外，餘出者過三之二，安得言七宿不能於一夕間畢見哉？蓋晁不識星故雲爾。","sortOrder":5},
  {"id":"s_work_dtbt_35_6","chapterId":"ch_work_dtbt_35","text":"其論詩序雲，作詩者不必有序。今之說者曰，序與詩同作，無乃惑歟！且逸詩之傳者，岐下之石鼓也，又安覩序邪？謂晉武公盜立，秦仲者石勒之流，秦襄公取周地，皆不應美。文王有聲為繼伐，是文王以伐紂為志，武王以伐紂為功。庭燎、沔水、鶴鳴、白駒，箴、規、誨、刺於宣王，則雲漢、韓奕、崧高、烝民之作妄也。未有小雅之惡如此，而大雅之善如彼者也。謂子衿、候人、采綠之序駢蔓無益，樛木、日月之序為自戾，定之方中、木瓜之序為不純。孟子、荀卿、左氏、賈誼、劉向漢諸儒，論說及詩多矣，未嘗有一言以詩序為議者，則序之所作晚矣。晁所論是否，亦未敢輒言。但其中有雲，秦康公隳穆公之業，日稱兵於母家，自喪服以尋幹戈，終身戰不知已，而序渭陽，稱其「我見舅氏，如母存焉」，是果純孝歟？陳厲公弒佗代立，而序墓門責佗「無良師傅」，失其類矣。予謂康公渭陽之詩，乃贈送晉文公入晉時所作，去其即位十六年。衰服用兵，蓋晉襄公耳，傳雲「子墨衰絰」者也。康公送公子雍於晉，蓋徇其請。晉背約而與之戰，康公何罪哉？責其稱兵於母家，則不可。陳佗殺威公太子而代之，故蔡人殺佗而立厲公，非厲公罪也。晁詆厲以申佗，亦為不可。","sortOrder":6},
  {"id":"s_work_dtbt_35_7","chapterId":"ch_work_dtbt_35","text":"其論三傳，謂杜預以左氏之耳目，奪夫子之筆削。公羊家失之舛雜，而何休者，又特負於公羊。惟穀梁晚出，監二氏之違畔而正之，然或與之同惡，至其精深遠大者，真得子夏之所傳。范甯又因諸儒而博辯之，申穀梁之志，其於是非亦少公矣，非若杜征南一切申傳，決然不敢異同也。此論最善。","sortOrder":7},
  {"id":"s_work_dtbt_35_8","chapterId":"ch_work_dtbt_35","text":"然則晁公之於羣經，可謂自信篤而不詭隨者矣。","sortOrder":8},
  {"id":"s_work_dtbt_35_9","chapterId":"ch_work_dtbt_35","text":"邳彤酈商","sortOrder":9},
  {"id":"s_work_dtbt_35_10","chapterId":"ch_work_dtbt_35","text":"漢光武討王郎時，河北皆叛，獨鉅鹿、信都堅守，議者謂可因二郡兵自送，還長安。惟邳彤不可，以為若行此策，豈徒空失河北，必更驚動三輔。公既西，則邯鄲之兵，不肯背城主而千里送公，其離散逃亡可必也。光武感其言而止。東坡曰：「此東漢興亡之決，邳彤亦可謂漢之元臣也。」彤在雲臺諸將之中，不為人所標異，至此論出，識者始知其然。漢高祖沒，呂後與審食其謀曰：「諸將故與帝為編戶民，今乃事少主，非盡族是，天下不安。」以故不發喪。酈商見食其曰：「誠如此，天下危矣。陳平、灌嬰將十萬守滎陽，樊噲、周勃將二十萬定燕、代，比聞帝崩，諸將皆誅，必連兵還嚮以攻關中，亡可翹足待也。」食其入言之，乃發喪。然則是時漢室之危，幾於不保，酈商笑談間，廓廓無事，其功豈不大哉？然無有表而出之者！迨呂後之亡，呂祿據北軍，商子寄紿之出遊，使周勃得入。則酈氏父子之於漢，謂之社稷臣可也。寄與劉揭同說呂祿解將印，及文帝論功，揭封侯賜金，而寄不錄，平、勃亦不為之一言，此又不可曉者。其後寄嗣父為侯，又以罪免，惜哉！","sortOrder":10},
  {"id":"s_work_dtbt_35_11","chapterId":"ch_work_dtbt_35","text":"武成之書","sortOrder":11},
  {"id":"s_work_dtbt_35_12","chapterId":"ch_work_dtbt_35","text":"孔子言：「周之德，其可謂至德也已矣。三分天下有其二，以服事殷。」所謂服事者，美其能於紂之世盡臣道也。而史記周本紀雲西伯蓋受命之年稱王，而斷虞芮之訟，其後改法度，製正朔，追尊古公、公季為王。是說之非，自唐梁肅至於歐陽、東坡公、孫明復皆嘗著論，然其失自武成始也。孟子曰：「吾於武成，取二三策而已矣。」今考其書，雲「大王肇基王跡，文王誕膺天命，以撫方夏」，及武王自稱曰「周王發」，皆紂尚在位之辭。且大王居邠，猶為狄所迫逐，安有「肇基王跡」之事？文王但稱西伯，焉得言「誕膺天命」乎？武王未代商，已稱周王，可乎？則武成之書不可盡信，非止「血流漂杵」一端也。至編簡舛誤，特其小小者雲。","sortOrder":12},
  {"id":"s_work_dtbt_35_13","chapterId":"ch_work_dtbt_35","text":"象載瑜","sortOrder":13},
  {"id":"s_work_dtbt_35_14","chapterId":"ch_work_dtbt_35","text":"漢郊祀歌象載瑜章雲：「象載瑜，白集西。」顏師古曰：「象載，象輿也。山出象輿，瑞應車也。」赤蛟章雲「象輿車羲」，即此也。而景星章雲：「象載昭庭。」師古曰：「象謂懸象也。懸象祕事，昭顯於庭也。」二字同出一處，而自為兩說。按樂章詞意，正指瑞應車，言昭列於庭下耳。三劉漢釋之說亦得之，而謂「白集西」為西雍之麟，此則不然。蓋歌詩凡十九章，皆書其名於後，象載瑜前一行雲「行幸雍獲白麟作」，自為前篇「朝隴首，覽西垠」之章，不應又於下篇贅出之也。","sortOrder":14},
  {"id":"s_work_dtbt_35_15","chapterId":"ch_work_dtbt_35","text":"管晏之言","sortOrder":15},
  {"id":"s_work_dtbt_35_16","chapterId":"ch_work_dtbt_35","text":"孟子所書：「齊景公問於晏子曰：『吾欲觀於轉附、朝，遵海而南，放於琅邪，吾何修而可以比於先王觀也？』晏子對曰：『天子諸侯，無非事者。春省耕而補不足，秋省斂而助不給。今也不然。師行而糧食。從流下而忘反謂之流。從流上而忘反謂之連。從獸無厭謂之荒。樂酒無厭謂之亡。先王無流連之樂，荒亡之行。』景公說，大戒於國。」管子內言戒篇曰：「威公將東遊，問於管仲曰：『我遊猶軸轉斛，南至琅邪。司馬曰，亦先王之遊已。何謂也？』對曰：『先王之遊也，春出原農事之不本者，謂之遊。秋出補人之不足者，謂之夕。夫師行而糧食其民者，謂之亡。從樂而不反者，謂之荒。先王有遊夕之業於民，無荒亡之行於身。』威公退再拜，命曰寶法。」觀管、晏二子之語，一何相似，豈非傳記所載容有相犯乎？管氏既自為一書，必不誤，當更考之晏子春秋也。","sortOrder":16},
  {"id":"s_work_dtbt_35_17","chapterId":"ch_work_dtbt_35","text":"共工氏","sortOrder":17},
  {"id":"s_work_dtbt_35_18","chapterId":"ch_work_dtbt_35","text":"禮記祭法、漢書郊祀志，皆言共工氏霸九州，以其無錄而王，故謂之霸。曆志則雲：「雖有水德，在火木之間，非其序也。任知刑以強，故伯而不王。周人遷其行序，故易不載。」註言：「以其非次故去之。」史記律書：「顓帝有共工之陳，以平水害。」文穎曰：「共工，主水官也。少昊氏衰，秉政作虐，故顓帝伐之。本主水官，因為水行也。」然左傳郯子所敍黃帝、炎帝五代所名官，共工氏以水紀，故為水師而水名。杜預雲：「共工氏以諸侯伯有九州者，在神農之前，太昊之後，亦受水瑞，以水名官。」蓋其與炎、黃諸帝，均受五行之瑞，無所低昂，是亦為王明矣。其子曰後土，能平九州，至今祀以為社。前所紀謂「周人去其行序」，恐非也。至於怒觸不周之山，天傾西北，地不滿東南，此說尤為誕罔。洪氏出於此，本曰「共」，左傳所書晉左行共華、魯共劉，皆其裔也。後又推本水德之緒加水於左而為「洪」雲。堯典所稱「共工方鳩僝功」，即舜所流者，非此也。時以名官，故舜命垂為之。","sortOrder":18},
  {"id":"s_work_dtbt_35_19","chapterId":"ch_work_dtbt_35","text":"漢志之誤","sortOrder":19},
  {"id":"s_work_dtbt_35_20","chapterId":"ch_work_dtbt_35","text":"昔人謂顏師古為班氏忠臣，以其註釋紀傳，雖有舛誤，必委曲為之辨故也。如五行志中最多，其最顯顯者，與尚書及春秋乖戾為甚。桑穀共生於朝。劉向以為商道既衰，高宗乘敝而起，既獲顯榮，怠於政事，國將危亡，故桑穀之異見。武丁恐駭，謀於忠賢。顏註曰：「桑穀自太戊時生，而此雲高宗時，其說與尚書大傳不同，未詳其義，或者伏生差謬。」按藝文志自雲：「桑穀共生，太戊以興，鳴雉登鼎，武丁為宗。」乃是本書所言，豈不可為明證，而翻以伏生為謬，何也？僖公二十九年，大雨雹。劉向以為信用公子遂，遂專權自恣，僖公不寤，後二年，殺子赤立宣公。又載文公十六年，蛇自泉宮出。劉向以為其後公子遂殺二子而立宣公。此是文公末年事，而劉向既書之，又誤以為僖。顏無所辨。隱公三年，日有食之。劉向以為其後鄭獲魯隱。註引「狐壤之戰，隱公獲焉」。此自是隱為公子時事耳，左傳記之甚明。宣公十五年，王札子殺召伯、毛伯。董仲舒以為成公時。其他如言楚莊始稱王，晉滅江之類，顏雖隨事敷演，皆雲未詳其說，終不肯正詆其疵也。地理志中沛郡公丘縣曰：「故滕國，周懿王子叔繡所封。」顏引左傳「郜、雍、曹、滕，文之昭也」為證，亦雲未詳其義。真定之肥纍，菑川之劇，泰山之肥城，皆以為肥子國，而遼西之肥如，又雲「肥子奔燕，燕封於此」。魏郡元城縣雲：「魏公子元食邑於此，因而遂氏焉。」常山元氏縣雲：「趙公子元之封邑，故曰元氏。」不應兩邑命名相似如此。正文及志五引虖池河，皆註雲：「虖音呼，池音徒河反。」又「五伯迭興」註雲：「此五伯謂齊威、宋襄、晉文、秦穆、楚莊也。」而諸侯王表「五伯扶其弱」註雲：「謂齊威、宋襄、晉文、秦穆、吳夫差也。」異姓諸侯王表「適戍強於五伯」註雲：「謂崑吾、大彭、豕韋、齊威、晉文也。」均出一書，皆師古註辭，而異同如此。","sortOrder":20},
  {"id":"s_work_dtbt_35_21","chapterId":"ch_work_dtbt_35","text":"漢將軍在御史上","sortOrder":21},
  {"id":"s_work_dtbt_35_22","chapterId":"ch_work_dtbt_35","text":"漢書百官公卿表，御史大夫掌副丞相，位上卿，銀印青綬，前後左右將軍亦位上卿，而金印紫綬。故霍光傳所載羣臣連名奏曰，丞相敞、大將軍光、車騎將軍安世、度遼將軍明友、前將軍增、後將軍充國、御史大夫誼。且雲羣臣以次上殿。然則凡雜將軍，皆在御史大夫上，不必前後左右也。","sortOrder":22},
  {"id":"s_work_dtbt_35_23","chapterId":"ch_work_dtbt_35","text":"上元張燈","sortOrder":23},
  {"id":"s_work_dtbt_35_24","chapterId":"ch_work_dtbt_35","text":"上元張燈，太平御覽所載史記樂書曰：「漢家祀太一，以昏時祠到明。」今人正月望日夜遊觀燈，是其遺事，而今史記無此文。唐韋述兩京新記曰：「正月十五日夜，敕金吾弛禁，前後各一日以看燈。」本朝京師增為五夜，俗言錢忠懿納土，進錢買兩夜，如前史所謂買宴之比。初用十二、十三夜，至崇寧初，以兩日皆國忌，遂展至十七、十八夜。予按國史，乾德五年正月，詔以朝廷無事，區（宀禹）乂安，令開封府更增十七、十八兩夕。然則俗雲因錢氏及崇寧之展日，皆非也。太平興國五年十月下元，京城始張燈如上元之夕，至淳化元年六月，始罷中元、下元張燈。","sortOrder":24},
  {"id":"s_work_dtbt_35_25","chapterId":"ch_work_dtbt_35","text":"七夕用六日","sortOrder":25},
  {"id":"s_work_dtbt_35_26","chapterId":"ch_work_dtbt_35","text":"太平興國三年七月，詔：「七夕嘉辰，著於甲令。今之習俗，多用六日，非舊製也，宜復用七日。」且名為七夕而用六，不知自何時始。然唐世無此說，必出於五代耳。","sortOrder":26},
  {"id":"s_work_dtbt_35_27","chapterId":"ch_work_dtbt_35","text":"宰相參政員數","sortOrder":27},
  {"id":"s_work_dtbt_35_28","chapterId":"ch_work_dtbt_35","text":"太祖登極，仍用周朝范質、王溥、魏仁浦三宰相，四年，皆罷，趙普獨相。越三月，始創參知政事之名，而以命薛居正、呂餘慶，後益以劉熙古，是為一相三參。及普罷去，以居正及沈義倫為相，盧多遜參政。太宗即位，多遜亦拜相。凡六年，三相而無一參。自後頗以二相二參為率。至和二年，文彥博為昭文相，劉沆為史館相，富弼為集賢相，但用程戡一參。惟至道三年呂端以右僕射獨相，而戶部侍郎溫仲舒、禮部侍郎王化基、工部尚書李至、禮部侍郎李沆四參政，前後未之有也。","sortOrder":28},
  {"id":"s_work_dtbt_35_29","chapterId":"ch_work_dtbt_35","text":"朱崖遷客","sortOrder":29},
  {"id":"s_work_dtbt_35_30","chapterId":"ch_work_dtbt_35","text":"唐韋執誼自宰相貶崖州司戶，刺史命攝軍事衙推，牒詞雲：「前件官久在朝廷，頗諳公事，幸期佐理，勿憚縻賢。」當時傳以為笑，然猶未至於挫抑也。盧多遜罷相流崖州，知州乃牙校，為子求昏，多遜不許，遂侵辱之，將加害，不得已，卒與為昏。紹興中，胡邦衡銓竄新州，再徙吉陽，吉陽即朱崖也。軍守張生，亦一右列指使，遇之亡狀，每旬呈，必令囚首詣廷下。邦衡盡禮事之，至作五十韻詩，為其生日壽，性命之憂，朝不謀夕。是時，黎酋聞邦衡名，遣子就學，其居去城三十里，嘗邀致入山，見軍守者，荷枷絣西廡下，酋指而語曰：「此人貪虐已甚，吾將殺之，先生以為何如？」邦衡曰：「其死有餘罪，果若此，足以洗一邦怨心。然既蒙垂問，切有獻焉。賢郎所以相從者，為何事哉？當先知君臣上下之名分。此人固亡狀，要之為一州主，所謂邦君也。欲訴其過，合以告海南安撫司，次至廣西經略司，俟其不行，然後訟於樞密院，今不應擅殺人也。」酋悟，遽釋之，令自書一紙引咎，乃再拜而出。明日，邦衡歸，張詣門悔謝，殊感再生之恩，自此待為上客。邦衡以隆興初在侍從，錄所作生日詩示仲兄文安公，且備言昔日事。乃知去天萬里，身陷九淵，日與死迫，古今一轍也。","sortOrder":30},
  {"id":"s_work_dtbt_35_31","chapterId":"ch_work_dtbt_35","text":"張士貴宋璟","sortOrder":31},
  {"id":"s_work_dtbt_35_32","chapterId":"ch_work_dtbt_35","text":"唐太宗自臨治兵，以部陳不整，命大將軍張士貴杖中郎將等，怒其杖輕，下士貴吏。魏徵諫曰：「將軍之職，為國爪牙，使之執杖，已非後法，況以杖輕下吏乎？」上亟釋之。明皇開元三年，御史大夫宋璟坐監朝堂杖人杖輕，貶睦州刺史，姚崇為宰相，弗能止，盧懷慎亦為相，疾亟，表言璟明時重器，所坐者小，望垂矜錄，上深納之。太宗、明皇，有唐賢君也，而以杖人輕之故，加罪大將軍、御史大夫，可謂失政刑矣。","sortOrder":32},
  {"id":"s_work_dtbt_35_33","chapterId":"ch_work_dtbt_35","text":"韓歐文語","sortOrder":33},
  {"id":"s_work_dtbt_35_34","chapterId":"ch_work_dtbt_35","text":"盤穀序雲：「坐茂林以終日，濯清泉以自潔。采於山，美可茹；釣於水，鮮可食。」醉翁亭記雲：「野花發而幽香，佳木秀而繁陰。臨溪而漁，溪深而魚肥；釀泉為酒，泉香而酒洌。山殽野蔌，雜然而前陳。」歐公文勢，大抵化韓語也。然「釣於水，鮮可食」與「臨溪而漁，溪深而魚肥」、「采於山」與「山殽前陳」之句，煩簡工夫，則有不侔矣。","sortOrder":34},
  {"id":"s_work_dtbt_35_35","chapterId":"ch_work_dtbt_35","text":"容齋三筆","sortOrder":35},
  {"id":"s_work_dtbt_36_1","chapterId":"ch_work_dtbt_36","text":"卷第二(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_36_2","chapterId":"ch_work_dtbt_36","text":"漢宣帝不用儒","sortOrder":2},
  {"id":"s_work_dtbt_36_3","chapterId":"ch_work_dtbt_36","text":"漢宣帝不好儒，至雲俗儒不達時宜，好是古非今，使人眩於名實，不知所守，何足委任。匡衡為平原文學，學者多上書薦衡經明，當世少雙，不宜在遠方。事下蕭望之、梁丘賀。望之奏衡經學精習，說有師道，可觀覽。宣帝不甚用儒，遣衡歸故官。司馬溫公謂俗儒誠不可與為治，獨不可求真儒而用之乎？且是古非今之說，秦始皇、李斯所禁也，何為而效之邪？既不用儒生而專委中書宦官，宏恭、石顯因以擅政事，卒為後世之禍，人主心術，可不戒哉！","sortOrder":3},
  {"id":"s_work_dtbt_36_4","chapterId":"ch_work_dtbt_36","text":"國家府庫","sortOrder":4},
  {"id":"s_work_dtbt_36_5","chapterId":"ch_work_dtbt_36","text":"真宗嗣位之初，有司所上天下每歲賦入大數，是時，至道三年也，凡收穀二千一百七十萬碩，錢四百六十五萬貫，絹、紬一百九十萬匹，絲、綿六百五十八萬兩，茶四十九萬斤，黃蠟三十萬斤。自後多寡不常，然大略具此。方國家全盛，民力充足，故於征輸未能為害。今之事力，與昔者不可同日而語，所謂緡錢之入，殆過十倍。民日削月朘，未知救弊之術，為可慮耳。黃蠟一項，今不聞有此數。","sortOrder":5},
  {"id":"s_work_dtbt_36_6","chapterId":"ch_work_dtbt_36","text":"劉項成敗","sortOrder":6},
  {"id":"s_work_dtbt_36_7","chapterId":"ch_work_dtbt_36","text":"漢高帝、項羽起兵之始，相與北面共事懷王。及入關破秦，子嬰出降，諸將或言誅秦王。高帝曰：「始懷王遣我，固以能寬容，且人已服降，殺之不祥。」乃以屬吏。至羽則不然，既殺子嬰，屠鹹陽，使人致命於懷王。王使如初約，先入關者王其地。羽乃曰：「懷王者，吾家武信君所立耳，非有功伐，何以得顓主約？今定天下，皆將相諸君與籍力也，懷王亡功，固當分其地而王之。」於是陽尊王為義帝，卒至殺之。觀此二事，高帝既成功，猶敬佩王之戒，羽背主約，其末至於如此，成敗之端，不待智者而後知也。高帝微時，嘗繇鹹陽，縱觀秦皇帝，喟然太息曰：「大丈夫當如此矣！」至羽觀始皇，則曰：「彼可取而代也。」雖史家所載，容有文飾，然其大旨，固可見雲。","sortOrder":7},
  {"id":"s_work_dtbt_36_8","chapterId":"ch_work_dtbt_36","text":"占術致禍","sortOrder":8},
  {"id":"s_work_dtbt_36_9","chapterId":"ch_work_dtbt_36","text":"吉凶禍福之事，蓋未嘗不先見其祥。然固有知之信之，而翻取殺身亡族之害者。漢昭帝時，昌邑石自立，上林僵柳復起，蟲食葉曰「公孫病己立」。眭孟上書言，當有從匹夫為天子者，勸帝索賢人而禪位，孟坐祅言誅，而其應乃在孝宣，正名病己。哀帝時，夏賀良以為漢曆中衰，當更受命，遂有陳聖劉太平皇帝之事，賀良坐不道誅。及王莽篡竊，自謂陳後，而光武實應之。宋文帝時，孔熙先以天文圖讖，知帝必以非道晏駕，由骨肉相殘，江州當出天子，遂謀大逆，欲奉江州刺史、彭城王義康。熙先既誅，義康亦被害，而帝竟有子禍，孝武帝乃以江州起兵而即尊位。薄姬在魏王豹宮，許負相之當生天子，豹聞言心喜，因背漢，致夷滅，而其應乃在漢文帝。唐李錡據潤州反，有相者言，丹陽鄭氏女當生天子，錡聞之，納為侍人。錡敗，沒入掖庭，得幸憲宗而生宣宗。五代李守貞為河中節度使，有術者善聽人聲，聞其子婦符氏聲，驚曰：「此天下之母也。」守貞曰：「吾婦猶為天下母，吾取天下，復何疑哉？」於是決反，已而覆亡，而符氏乃為周世宗後。","sortOrder":9},
  {"id":"s_work_dtbt_36_10","chapterId":"ch_work_dtbt_36","text":"絳侯萊公","sortOrder":10},
  {"id":"s_work_dtbt_36_11","chapterId":"ch_work_dtbt_36","text":"漢周勃誅諸呂，立文帝以安劉氏，及為丞相，朝罷趨出，意得甚。上禮之恭，常目送之。爰盎進曰：「丞相何如人也？」上曰：「社稷臣。」盎曰：「絳侯所謂功臣，非社稷臣。社稷臣，主在與在，主亡與亡。方呂後時，諸呂用事，擅相王，絳侯為太尉，本兵柄，弗能正。呂後崩，大臣相與共誅諸呂，太尉主兵，適會其成功，所謂功臣，非社稷臣。丞相如有驕主色，陛下謙遜，臣主失禮，竊為陛下弗取也。」後朝，上益莊，丞相益畏。久之，勃遂有逮繫廷尉之禍，幾於不免。寇萊公決澶淵之策，真宗待之極厚，王欽若深害之。一日會朝，準先退，欽若進曰：「陛下敬畏寇準，為其有社稷功邪？」上曰：「然。」欽若曰：「臣不意陛下出此言！澶淵之役，不以為恥，而謂準有社稷功，何也？」上愕然曰：「何故？」對曰：「城下之盟，雖春秋時小國猶恥之。今以萬乘之貴，而為此舉，是盟於城下也，其何恥如之！」上愀然不能答。由是顧準稍衰，旋即罷相，終海康之貶。嗚呼！絳侯、萊公之功，揭若日月，而盎與欽若以從容一言，移兩明主意，訖致二人於罪斥，讒言罔極，吁可畏哉！","sortOrder":11},
  {"id":"s_work_dtbt_36_12","chapterId":"ch_work_dtbt_36","text":"無名殺臣下","sortOrder":12},
  {"id":"s_work_dtbt_36_13","chapterId":"ch_work_dtbt_36","text":"傳曰：「欲加之罪，其無辭乎？」古者置人於死地，必求其所以死。然固有無罪殺之，而必為之名者。張湯為漢武造白鹿皮幣，大農顏異以為本末不相稱，天子不悅。湯又與異有隙。異與客語初令下有不便者，異不應，微反唇。湯奏當異九卿，見令不便，不入言而腹非，論死。自是後有腹非之法。非，論死。自是後有腹非之法。曹操始用崔琰，後為人所譖，罰為徒隸，使人視之，詞色不撓。操令曰：「琰雖見刑，而對賓客，虬須直視，若有所瞋。」遂賜琰死。隋煬帝殺高熲之後，議新令，久不決。薛道衡謂朝士曰：「向使高熲不死，令決當久行。」有人奏之，帝怒，付執法者推之。裴蘊奏：「道衡有無君之心，推惡於國，妄造禍端。論其罪名，似如隱昧，原其情意，深為悖逆。」帝曰：「公論其逆，妙體本心。」遂令自盡。寃哉此三臣之死也！","sortOrder":13},
  {"id":"s_work_dtbt_36_14","chapterId":"ch_work_dtbt_36","text":"平天冠","sortOrder":14},
  {"id":"s_work_dtbt_36_15","chapterId":"ch_work_dtbt_36","text":"祭服之冕，自天子至於下士執事者皆服之，特以梁數及旒之多少為別。俗呼為平天冠，蓋指言至尊乃得用。范純禮知開封府，中旨鞫淳澤村民謀逆事。審其故，乃嘗入戲場觀優，歸塗見匠者作桶，取而戴於首，曰：「與劉先主如何？」遂為匠擒。明日入對，徽宗問何以處。對曰：「愚人村野無所知，若以叛逆蔽罪，恐辜好生之德，以不應為杖之，足矣。」按後漢輿服志蔡邕註冕冠曰：「鄙人不識，謂之平天冠。」然則其名之傳久矣。","sortOrder":15},
  {"id":"s_work_dtbt_36_16","chapterId":"ch_work_dtbt_36","text":"介推寒食","sortOrder":16},
  {"id":"s_work_dtbt_36_17","chapterId":"ch_work_dtbt_36","text":"左傳晉文公反國，賞從亡者，介之推不言祿，祿亦弗及，推遂與母偕隱而死。晉侯求之不獲，以上為之田，曰：「以志吾過。」綿上者，西河介休縣地也。其事始末只如此。史記則曰：「子推從者書宮門，有『一蛇獨怨』之語。文公見其書，使人召之，則亡。聞其入綿上山中，於是環山封之，名曰介山。」雖與左傳稍異，而大略亦同。至劉向新序始雲：「子推怨於無爵齒，去而之介山之上，文公待之，不肯出。以謂焚其山宜出，遂不出而焚死。」是後雜傳記，如汝南先賢傳則雲：「太原舊俗，以介子推焚骸，一月寒食。」鄴中記雲：「幷州俗，冬至後一百五日，為子推斷火冷食三日。魏武帝以太原、上黨、西河、雁門皆沍寒之地，令人不得寒食，亦為冬至後百有五日也。」按後漢周舉傳雲：「太原一郡，舊俗以介子推焚骸，有龍忌之禁。至其亡月，鹹言神靈不樂舉火，由是士民每冬中輒一月寒食，莫敢煙爨。舉為幷州刺史，乃作弔書置子推廟，言盛冬去火，殘損民命，非賢者之意，宣示愚民，使還溫食。於是衆惑稍解，風俗頗革。」然則所謂寒食，乃是冬中，非今節令二三月間也。","sortOrder":17},
  {"id":"s_work_dtbt_36_18","chapterId":"ch_work_dtbt_36","text":"進士訴黜落","sortOrder":18},
  {"id":"s_work_dtbt_36_19","chapterId":"ch_work_dtbt_36","text":"天禧三年，京西轉運使胡則言滑州進士楊世質等訴本州黜落，即取元試卷，付許州通判崔立看詳，立以為世質等所試，不至紕繆，已牒滑州依例解發。詔轉運司具析不先奏裁直令解發緣由以聞，其試卷仰本州繳進。世質等仍未得解發。及取到試卷，詔貢院定奪，乃言詞理低次，不合充薦，復黜之，而劾胡則、崔立之罪。蓋是時貢舉條製猶未堅定，故有被黜而來訴其枉者。至於省試亦然，如葉齊之類，由此登第。後來無此風矣。","sortOrder":19},
  {"id":"s_work_dtbt_36_20","chapterId":"ch_work_dtbt_36","text":"後漢書載班固文","sortOrder":20},
  {"id":"s_work_dtbt_36_21","chapterId":"ch_work_dtbt_36","text":"班固著漢書，製作之工，如英、莖、鹹、韶，音節超詣，後之為史者，莫能及其髣髴，可謂盡善矣。然至後漢中所載固之文章，斷然如出兩手。觀謝夷吾傳雲，第五倫為司徒，使固作奏薦之，其辭至有「才兼四科，行包九德」之語。其他比喻，引稷、契、咎繇、傅說、伊、呂、周、召、管、晏，以為一人之身，而唐、虞、商、周聖賢之盛者，皆無以過。而夷吾乃在方術傳中，所學者風角占候而已，固之言，一何太過歟？","sortOrder":21},
  {"id":"s_work_dtbt_36_22","chapterId":"ch_work_dtbt_36","text":"趙充國馬援","sortOrder":22},
  {"id":"s_work_dtbt_36_23","chapterId":"ch_work_dtbt_36","text":"前漢先零羌犯塞，趙充國平之，初置金城屬國，以處降羌，西邊遂定。成帝命揚雄頌其圖畫，至比周之方、虎。後漢光武時，西羌入居塞內，來歙奏言，隴西侵殘，非馬援莫能定。乃拜援太守，追討之。羌來和親，於是隴右清靜。而自永平以後，訖於靈帝，十世之間，羌患未嘗少息。故范曄著論，以為：「二漢御戎之方，為失其本。先零侵境，趙充國遷之內地；當煎作寇，馬文淵徙之三輔。貪其暫安之勢，信其馴服之情，計日用之權宜，忘經世之遠略，豈夫識微者之為乎？」援徙當煎於三輔，不見其事。西羌傳雲，援破降先零，徙置天水、隴西、扶風三郡，事已具援傳。然援本傳，蓋無其語，唯段紀明與張奐爭討東羌奏疏，正謂趙、馬之失，至今為梗。充國、文淵，為漢名臣，段貶之如此，故曄據而用之，豈其然乎？","sortOrder":23},
  {"id":"s_work_dtbt_36_24","chapterId":"ch_work_dtbt_36","text":"漢人希姓","sortOrder":24},
  {"id":"s_work_dtbt_36_25","chapterId":"ch_work_dtbt_36","text":"兩漢書所載人姓氏，有後世不著見者甚多，漫紀於此，以助氏族書之脫遺。複姓如公上不害、合傅胡害、室中同、昭涉掉尾、單父右軍、陽城延、息夫躬、遊水發根、吾丘壽王、落下閎、梁丘賀、五鹿充宗、公戶滿意、堂谿惠、申章昌、浩星賜、闕門慶忌、安國少季、馬適建、都尉朝、毋將隆、紅陽長仲、烏氏蠃、周陽由、勝屠公、毋鹽氏、歐侯氏、士孫喜、索盧恢、屠門少、瓜田儀、工師喜、駮馬少伯、公乘歙、鮭陽鴻、弓里遊、公沙穆、胡母班、周生豐、友通期、公緒恭、公族進階、水丘岑、叔先雄。單姓如繒賀、蟲達、靈常、賁赫、其石、旅卿、祕彭祖、革朱、樛樂、泠豐、冥都、澓中翁、蒯徹、直不疑、閎孺、使樂成、桮育、製氏、猗頓、義縱、雋不疑、疏廣、雲敞、枚乘、終軍、鹵公孺、食子公、馯臂、倗宗、衡胡、乘宏、簡卿、炔欽、所忠、假倉、眭孟、（上帶下足）惲、塗惲、射姓、後倉、姓偉、如氏、苴氏、百政、免公、髮福、質氏、濁賢、稽發、萬章、瞯氏、佗羽、繡君賓、漕中叔、栩丹、帛敞、遲昭平、汝臣、駒幾、稱忠、逯普、臺崇、沐茂、匽氏、勞丙、抗徐、闕宣、沮儁、卑整、編訢、亶誦、尋穆、夜龍、弓林、行巡、祋諷、角閎、芳丹、堅鐔、錫光、傜偉、重異、力子都、維氾、詩索、繇延、夷長公、防廣、鐔顯、移良、緱玉、蕃嚮、渠穆、臨孝存、脂習、笮融、茨充、處興、興渠、具瑗、諒輔、騰是、卿仲遼、謁煥、矯慎、晃華、洼丹、禰衡。","sortOrder":25},
  {"id":"s_work_dtbt_36_26","chapterId":"ch_work_dtbt_36","text":"絳灌","sortOrder":26},
  {"id":"s_work_dtbt_36_27","chapterId":"ch_work_dtbt_36","text":"漢書陳平傳，「絳、灌等讒平。」顏師古註雲：「舊說雲，絳，絳侯周勃也，灌，灌嬰也。而楚漢春秋，高祖之臣，別有絳灌，疑昧之文，不可據也。」賈誼傳，「絳、灌、東陽侯之屬盡害之。」註亦以為勃、嬰。按史記陳平世家曰：「絳侯、灌嬰等鹹讒平」，則其為兩人明甚。師古不必為疑辭也。楚漢春秋陸賈所作，皆書當時事，而所言多與史不合。師古蓋屢辨之矣。史、漢外戚竇皇後傳，實書絳侯、灌將軍，此最的證也。夏侯嬰為滕令，故稱滕公。而史幷灌嬰書為滕、灌，賈誼所稱亦然，甚與絳、灌相類。楚漢春秋一書，今不復見，李善註文選劉歆移博士書雲：「楚漢春秋曰，漢已定天下，論羣臣破敵禽將，活死不衰，絳灌、樊噲是也。功成名立，臣為爪牙，世世相屬，百出無邪，絳侯周勃是也。然則絳灌自一人，非絳侯與灌嬰。」師古所謂疑昧之文者此耳。張耳歸漢，即立為趙王，子敖廢為侯，敖子偃嘗為魯王，文帝封為南宮侯，而楚漢春秋有「南宮侯張耳」。淮陰舍人告韓信反，史記表雲欒說，漢表雲樂說，而楚漢以為謝公。其誤可見。","sortOrder":27},
  {"id":"s_work_dtbt_36_28","chapterId":"ch_work_dtbt_36","text":"題詠絕唱","sortOrder":28},
  {"id":"s_work_dtbt_36_29","chapterId":"ch_work_dtbt_36","text":"錢伸仲大夫於錫山所居漆塘村作四亭，自其先人，已有卜築之意而不克就，故名曰「遂初」；先壟在其上，名曰「望雲」；種桃數百千株，名曰「芳美」；鑿地涌泉，或以為與惠山泉同味，名曰「通惠」。求詩於一時名流，自葛魯卿、汪彥章、孫仲益既各極其妙，而母舅蔡載天任四絕獨擅場。遂初亭曰：「結廬傍林泉，偶與初心期。佳處時自領，未應魚鳥知。」望雲亭曰：「白雲來何時，英英冠山椒。西風莫吹去，使我心搖搖。」芳美亭曰：「高人不惜地，自種無邊春。莫隨流水去，恐汚世間塵。」通惠亭曰：「水行天地間，萬派同一指。胡為穿石來？要洗巢由耳。」四篇既出，諸公皆自以為弗及也。吳傅朋遊絲書，賦詩者以百數，汪彥章五言數十句，多用翰墨故事，固已超拔，而劉子翬彥沖古風一篇，蓋為絕唱。其辭雲：「圓清無瑕二三月，時見遊絲轉空闊。誰人寫此一段奇，著紙春風吹不脫。紛紜糾結疑非書，安得龍蛇如許臞。神蹤政喜縈不斷，老眼只愁看若無。定知苗裔出飛白，古人妙處君潛得。勿輕漠漠一縷浮，力遒可掛千鈞石。眷予弟兄情不忘，軸之遠寄悠然堂。謝公遺髯凜若活，衞後落鬒搖人光。翻思長安夜飛蓋，醉哦聲落南山外。亂離契闊四十秋，筆意與人俱老大。政成著腳明河津，外家風流今絕倫。文章固自有機杼，戲事豈足勞心神？」此章尤為馳騁痛快，且卒章含譏諷，正中傅朋之癖。予少時見二公所作，殊敬愛之，至今五十年尚能記憶，懼其益久而不傳，故紀於此。","sortOrder":29},
  {"id":"s_work_dtbt_36_30","chapterId":"ch_work_dtbt_36","text":"秀才之名","sortOrder":30},
  {"id":"s_work_dtbt_36_31","chapterId":"ch_work_dtbt_36","text":"秀才之名，自宋、魏以後，實為貢舉科目之最，而今人恬於習玩，每聞以此稱之，輒指為輕己。因閱北史杜正玄傳載一事雲：「隋開皇十五年，舉秀才，試策高第，曹司以策過左僕射楊素，素怒曰：『周、孔更生，尚不得為秀才，刺史何忽妄舉此人！』乃以策抵地不視。時海內唯正玄一人應秀才，曹司重以啟素，素志在試退正玄，乃使擬相如上林賦、王褒聖主得賢臣頌、班固燕然山銘、張載劍閣銘、白鸚鵡賦，曰：『我不能為君住宿，可至未時令就。』正玄及時並了。素讀數遍，大驚曰：『誠好秀才！』命曹司錄奏。」蓋其重如此。又正玄弟正藏，次年舉秀才，時蘇威監選試，擬賈誼過秦論、尚書湯誓、匠人箴、連理樹賦、幾賦、弓銘，亦應時並就，文無點竄。然則可謂難矣。唐書杜正倫傳雲：「隋世重舉秀才，天下不十人，而正倫一門三秀才，皆高第。」乃此也。","sortOrder":31},
  {"id":"s_work_dtbt_36_32","chapterId":"ch_work_dtbt_36","text":"魏收作史","sortOrder":32},
  {"id":"s_work_dtbt_36_33","chapterId":"ch_work_dtbt_36","text":"魏收作元魏一朝史，修史諸人，多被書錄，飾以美言，夙有怨者，多沒其善。每言：「何物小子，敢共魏收作色，舉之則使上天，按之當使入地。」故衆口喧然，稱為「穢史」。諸家子孫，前後投訴，雲遺其家世職位，或雲不見記錄，或雲妄有非毀，至於坐謗史而獲罪編配，因以致死者。其書今存，視南北八史中，最為冗謬。其自序雲：「漢初，魏無知封高良侯，子均，均子恢，恢子彥，彥子歆，歆子悅，悅子子建，子建子收。」無知於收，為七代祖，而世之相去七百餘年。其妄如是，則其述他人世系與夫事業，可知矣！","sortOrder":33},
  {"id":"s_work_dtbt_36_34","chapterId":"ch_work_dtbt_36","text":"容齋三筆","sortOrder":34},
  {"id":"s_work_dtbt_37_1","chapterId":"ch_work_dtbt_37","text":"卷第三(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_37_2","chapterId":"ch_work_dtbt_37","text":"兔葵燕麥","sortOrder":2},
  {"id":"s_work_dtbt_37_3","chapterId":"ch_work_dtbt_37","text":"劉禹錫再遊玄都觀詩序雲：「唯兔葵燕麥，動搖春風耳。」今人多引用之。予讀北史邢邵傳載邵一書雲：「國子雖有學官之名，而無教授之實，何異兔絲燕麥，南箕北斗哉？」然則此語由來久矣。爾雅曰：「莃，兔葵。籥，雀麥。」郭璞註曰：「頗似葵而葉小，狀如藜；雀麥即燕麥，有毛。」廣志曰：「菟葵，爚之可食。」古歌曰：「田中菟絲，何嘗可絡？道邊燕麥，何嘗可穫？」皆見於太平御覽。上林賦：「葴析苞荔，」張揖註曰：「析，似燕麥，音斯。」葉庭珪海錄碎事雲：「兔葵，苗如龍芮，花白莖紫。燕麥草似麥，亦曰雀麥。」但未詳出於何書。","sortOrder":3},
  {"id":"s_work_dtbt_37_4","chapterId":"ch_work_dtbt_37","text":"北狄俘虜之苦","sortOrder":4},
  {"id":"s_work_dtbt_37_5","chapterId":"ch_work_dtbt_37","text":"元魏破江陵，盡以所俘士民為奴，無問貴賤，蓋北方夷俗皆然也。自靖康之後，陷於金虜者，帝子王孫，宦門仕族之家，盡沒為奴婢，使供作務。每人一月支稗子五斗，令自舂為米，得一斗八升，用為餱糧。歲支麻五把，令緝為裘，此外更無一錢一帛之入。男子不能緝者，則終歲裸體，虜或哀之，則使執爨，雖時負火得煖氣，然纔出外取柴，歸再坐火邊，皮肉即脫落，不日輒死。惟喜有手藝，如醫人、繡工之類，尋常只團坐地上，以敗席或蘆藉襯之。遇客至開筵，引能樂者使奏技，酒闌客散，各復其初，依舊環坐刺繡，任其生死，視如草芥。先公在英州，為攝守蔡寯言之，蔡書於甲戌日記，後其子大器錄以相示，此松漠記聞所遺也。","sortOrder":5},
  {"id":"s_work_dtbt_37_6","chapterId":"ch_work_dtbt_37","text":"太守刺史贈吏民官","sortOrder":6},
  {"id":"s_work_dtbt_37_7","chapterId":"ch_work_dtbt_37","text":"漢薛宣為左馮翊，池陽令舉廉吏獄掾王立，未及召，立妻受囚家錢，慚恐自殺。宣移書池陽曰：「其以府決曹掾書立之柩，以顯其魂。」顏師古註雲：「以此職追贈也。」後魏幷州刺史以部民吳悉達兄弟行著鄉里，板贈其父渤海太守。此二者皆以太守、刺史而擅贈吏民官職，不以為過，後世不敢然也。","sortOrder":7},
  {"id":"s_work_dtbt_37_8","chapterId":"ch_work_dtbt_37","text":"李元亮詩啟","sortOrder":8},
  {"id":"s_work_dtbt_37_9","chapterId":"ch_work_dtbt_37","text":"建昌縣士人李元亮，山房公擇尚書族子也，抱材尚氣，不以辭色假人。崇寧中在大學，蔡薿為學錄，元亮惡其人，不以所事前廊之禮事之。蔡擢第魁多士，元亮失意歸鄉。大觀二年冬，復詣學，道過和州。蔡解褐即超用，纔二年，至給事中，出補外，正臨此邦。元亮不肯入謁。蔡自到官，即戒津吏門卒，凡士大夫往來，無問官高卑，必飛報，雖布衣亦然。既知其來，便命駕先造所館。元亮驚喜出迎，謝曰：「所以來，顓為門下之故。方脩贄見之禮，須明旦扣典客，不意給事先生卑躬下賤如此，前贄不可復用，當別撰一通，然後敬謁。」蔡退，元亮旋營一啟，旦而往焉，其警策曰：「定館而見長者，古所不然；輕身以先匹夫，今無此事。」蔡摘讀嗟激，留宴連夕，贈以五十萬錢，且致書延譽於諸公間，遂登三年貢士科。元亮亦工詩，如「人閑知晝永，花落見春深」，「朝雨未休還暮雨，臘寒纔過又春寒」，皆佳句也。","sortOrder":9},
  {"id":"s_work_dtbt_37_10","chapterId":"ch_work_dtbt_37","text":"元魏改功臣姓氏","sortOrder":10},
  {"id":"s_work_dtbt_37_11","chapterId":"ch_work_dtbt_37","text":"魏孝文自代遷洛，欲大革胡俗，既自改拓跋為元氏，而諸功臣舊族自代來者，以姓或重複，皆改之。於是拔拔氏為長孫氏，達奚氏為奚氏，乙旃氏為叔孫氏，丘穆陵氏為穆氏，步六孤氏為陸氏，賀賴氏為賀氏，獨孤氏為劉氏，賀樓氏為樓氏，勿忸於氏為於氏，尉遲氏為尉氏，其用夏變夷之意如此。然至於其孫恭帝，翻以中原故家，易賜蕃姓，如李弼為徒河氏，趙肅、趙貴為乙弗氏，劉亮為侯莫陳氏，楊忠為普六茹氏，王雄為可頻氏，李虎、閻慶為大野氏，辛威為普毛氏，田宏為紇幹氏，耿豪為和稽氏，王勇為庫汗氏，楊紹為叱利氏，侯植為侯伏侯氏，竇熾為紇豆陵氏，李穆為拔氏，陸通為步六孤氏，楊纂為莫胡盧氏，寇儁為若口引氏，段永為爾綿氏，韓褒為侯呂陵氏，裴文舉為賀蘭氏，王軌為烏丸氏，陳忻為尉遲氏，樊深為萬紐於氏，一何其不循乃祖彝憲也！是時蓋宇文泰顓國，此事皆出其手，遂復國姓為拓跋，而九十九姓改為單者，皆復其舊。泰方以時俗文敝，命蘇綽倣周書作大誥，又悉改官名，復周六卿之製，顧乃如是，殆不可曉也。","sortOrder":11},
  {"id":"s_work_dtbt_37_12","chapterId":"ch_work_dtbt_37","text":"東坡和陶詩","sortOrder":12},
  {"id":"s_work_dtbt_37_13","chapterId":"ch_work_dtbt_37","text":"陶淵明集歸田園居六詩，其末「種苗在東皋」一篇，乃江文通雜體三十篇之一，明言斅陶徵君田居，蓋陶之三章雲：「種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。」故文通雲：「雖有荷鋤倦，濁酒聊自適。」正擬其意也。今陶集誤編入，東坡據而和之。又「東方有一士」詩十六句，復重載於擬古九篇中，坡公遂亦兩和之，皆隨意即成，不復細考耳。陶之首章雲：「榮榮窗下蘭，密密堂前柳。初與君別時，不謂行當久。出門萬里客，中道逢嘉友。未言心先醉，不在接杯酒。蘭枯柳亦衰，遂令此言負。」坡和雲：「有客扣我門，繫馬庭前柳。庭空鳥雀噪，門閉客立久。主人枕書臥，夢我平生友。忽聞剝啄聲，驚散一杯酒。倒裳起謝客，夢覺兩愧負。」二者金石合奏，如出一手，何止子由所謂遂與比轍者哉！","sortOrder":13},
  {"id":"s_work_dtbt_37_14","chapterId":"ch_work_dtbt_37","text":"孔戣鄭穆","sortOrder":14},
  {"id":"s_work_dtbt_37_15","chapterId":"ch_work_dtbt_37","text":"唐孔戣在穆宗時為尚書左丞，上書去官，天子以為禮部尚書致仕，吏部侍郎韓愈奏疏曰：「戣為人守節清苦，議論正平，年纔七十，筋力耳目，未覺衰老，憂國忘家，用意至到。如戣輩，在朝不過三數人，陛下不宜苟順其求，不留自助也。」不報。明年正月，戣薨。國朝鄭穆在元祐中以寶文閣待製兼國子祭酒請老，提舉洞霄宮，給事中范祖禹言：「穆雖年出七十，精力尚強，古者大夫七十而致仕，有不得謝，則賜之幾杖，祭酒居師資之地，正宜處老成，願毋輕聽其去。」亦不報。然穆亦至明年卒。二事絕相類。","sortOrder":15},
  {"id":"s_work_dtbt_37_16","chapterId":"ch_work_dtbt_37","text":"陳季常","sortOrder":16},
  {"id":"s_work_dtbt_37_17","chapterId":"ch_work_dtbt_37","text":"陳慥字季常，公弼之子，居於黃州之岐亭，自稱「龍丘先生」，又曰「方山子」。好賓客，喜畜聲妓，然其妻柳氏絕凶妒，故東坡有詩雲：「龍丘居士亦可憐，談空說有夜不眠。忽聞河東師子吼，拄杖落手心茫然。」河東師子，指柳氏也。坡又嘗醉中與季常書雲：「一絕乞秀英君。」想是其妾小字。黃魯直元祐中有與季常簡曰：「審柳夫人時須醫藥，今已安平否？公暮年來想漸求清淨之樂，姬媵無新進矣，柳夫人比何所念以致疾邪？」又一帖雲：「承諭老境情味，法當如此，所苦既不妨遊觀山川，自可損藥石，調護起居飲食而已。河東夫人亦能哀憐老大，一任放不解事邪？」則柳氏之妒名，固彰著於外，是以二公皆言之雲。","sortOrder":17},
  {"id":"s_work_dtbt_37_18","chapterId":"ch_work_dtbt_37","text":"文用謚字","sortOrder":18},
  {"id":"s_work_dtbt_37_19","chapterId":"ch_work_dtbt_37","text":"先王謚以尊名，節以壹惠，故謂為易名。然則謚之為義，正訓名也。司馬長卿諭蜀文曰：「身死無名，謚為至愚。」顏註雲：「終以愚死，後葉傳稱，故謂之謚。」柳子厚招海賈文曰：「君不返兮謚為愚。」二人所用，其意則同。唯王子淵簫賦曰：「幸得謚為洞簫兮，蒙聖主之渥恩。」李善謂：「謚者號也，言得謚為簫而常施用之。」以器物名為謚，其語可謂奇矣。","sortOrder":19},
  {"id":"s_work_dtbt_37_20","chapterId":"ch_work_dtbt_37","text":"高唐神女賦","sortOrder":20},
  {"id":"s_work_dtbt_37_21","chapterId":"ch_work_dtbt_37","text":"宋玉高唐、神女二賦，其為寓言託興甚明。予嘗即其詞而味其旨，蓋所謂發乎情，止乎禮義，真得詩人風化之本。前賦雲：「楚襄王望高唐之上有雲氣，問玉曰：『此何氣也？』對曰：『所謂朝雲者也。昔者先王嘗遊高唐，夢見一婦人，曰，妾巫山之女也，願薦枕蓆。王因幸之。』」後賦雲：「襄王既使玉賦高唐之事，其夜王寢，夢與神女遇，復命玉賦之。」若如所言，則是王父子皆與此女荒淫，殆近於聚麀之醜矣。然其賦雖篇首極道神女之美麗，至其中則雲：「澹清靜其愔嫕兮，性沈詳而不煩。意似近而若遠兮，若將來而復旋。褰餘幬而請御兮，願盡心之惓惓。懷貞亮之潔清兮，卒與我乎相難。頩薄怒以自持兮，曾不可乎犯幹。歡情未接，將辭而去。遷延引身，不可親附。願假須臾，神女稱遽。闇然而冥，忽不知處。」然則神女但與懷王交御，雖見夢於襄，而未嘗及亂也。玉之意可謂正矣。今人詩詞，顧以襄王藉口，考其實則非是。頩，音疋零反，斂容怒色也。柳子厚謫龍說有「奇女頩爾怒」之語，正用此也。","sortOrder":21},
  {"id":"s_work_dtbt_37_22","chapterId":"ch_work_dtbt_37","text":"其言明且清","sortOrder":22},
  {"id":"s_work_dtbt_37_23","chapterId":"ch_work_dtbt_37","text":"禮記緇衣篇：「詩雲，昔吾有先正，其言明且清。國家以寧，都邑以成，庶民以生。誰能秉國成？不自為正，卒勞百姓。」鄭氏註不言何詩。今毛詩節南山章但有下三句而微不同。經典釋文雲：「從第一句至庶民以生五句，今詩皆無此語，或皆逸詩也。」予按文選張華答何劭詩曰：「周任有遺規，其言明且清。」然則周任所作也。而李善註曰：「子思子詩雲，昔吾有先正，其言明且清。」世之所存子思子亦無之，不知善何所據？意當時或有此書，善必不妄也，特不及周任遺規之義，又不可曉。","sortOrder":23},
  {"id":"s_work_dtbt_37_24","chapterId":"ch_work_dtbt_37","text":"侍從轉官","sortOrder":24},
  {"id":"s_work_dtbt_37_25","chapterId":"ch_work_dtbt_37","text":"元豐未改官製以前，用職事官寄祿。自諫議大夫轉給事中，(學士轉中書舍人。歷三侍郎、學士轉左曹禮、戶、吏部，餘人轉右曹工、刑、兵部。左右丞，吏侍轉左，兵侍轉右。)然後轉六尚書，各為一官。尚書轉僕射，非曾任宰相者不許轉，今之特進是也。故侍從止於吏書，由諫議至此凡十一轉。其庶僚久於卿列者，則自光祿卿轉祕書監，繼歷太子賓客，遂得工部侍郎。蓋以不帶待製以上職，不許入兩省給、諫耳。元豐改諫議為太中大夫，給、舍為通議，六侍郎同為正議，左右丞為光祿。兵、戶、刑、禮、工書同為銀青，吏書金紫。但六轉，視舊法損其五。元祐中以為太簡，增正議、光祿、銀青為左右，然亦纔九資。大觀二年，置通奉以易右正議，正奉以易右光祿，宣奉以易左光祿，以右銀青為光祿，而至銀青者去其左字，今皆仍之。比倣舊製，今之通奉，乃工、禮侍郎，正議乃刑、戶，正奉乃兵、吏，宣奉乃左右丞，三光祿乃六尚書也。凡侍從序遷至金紫無止法，建炎以前多有之。紹興以來，階官到此絕少，唯梁揚祖、葛勝仲致仕得之。近歲有司不能探賾典故，予以宣奉當磨勘，又該覃霈，顏師魯在天官，徑給回授一據，而不明言其所由。比程叔達由宣奉納祿不遷官，而於待製閣名升二等。程大昌亦然，以龍圖直學士徑升本學士，尤非也。予任中書舍人日，已階太中，及以集英修撰出外，吏部不復為理年勞，凡十八年，始以待製得通議，殊可笑。蓋臺省之中，無復有老吏矣。","sortOrder":25},
  {"id":"s_work_dtbt_37_26","chapterId":"ch_work_dtbt_37","text":"曹子建七啟","sortOrder":26},
  {"id":"s_work_dtbt_37_27","chapterId":"ch_work_dtbt_37","text":"「原頭火燒淨兀兀，野雉畏鷹出復沒。將軍欲以巧伏人，盤馬彎弓惜不發。地形漸窄觀者多，雉驚弓滿勁箭加。衝人決起百餘尺，紅翎白鏃隨傾斜。將軍仰笑軍吏賀，五色離披馬前墮。」此韓昌黎雉帶箭詩，東坡嘗大字書之，以為絕妙。予讀曹子建七啟論羽獵之美雲：「人稠網密，地逼勢脅。」乃知韓公用意所來處。七啟又雲：「名穢我身，位累我躬。」與佛氏八大人覺經所書「心是惡源，形為罪藪」，皆修己正心之要語也。","sortOrder":27},
  {"id":"s_work_dtbt_37_28","chapterId":"ch_work_dtbt_37","text":"奸鬼為人禍","sortOrder":28},
  {"id":"s_work_dtbt_37_29","chapterId":"ch_work_dtbt_37","text":"晉景公疾病，求醫於秦，秦伯使醫緩為之，未至，公夢疾為二孺子，曰：「彼良醫也，懼傷我，焉逃之？」其一曰：「居肓之上，膏之下，若我何？」醫至，曰：「疾不可為也。」隋文帝以子秦孝王俊有疾，馳召名醫許智藏，俊夢亡妃崔氏泣曰：「本來相迎，如聞許智藏將至，其人當必相苦，奈何！」明夜復夢，曰：「吾得計矣，當入靈府中以避之。」及智藏至，診俊脈，曰：「疾已入心，不可救也。」二奸鬼之害人，如出一轍。近世許叔微家一婦人，夢二蒼頭，前者雲：「到也未？」後者應雲：「到也。」以手中物擊一下，遂魘。覺後心痛不可忍，叔微以神精丹餌之，痛止而愈。此事亦與上二者相似。","sortOrder":29},
  {"id":"s_work_dtbt_37_30","chapterId":"ch_work_dtbt_37","text":"監司待巡檢","sortOrder":30},
  {"id":"s_work_dtbt_37_31","chapterId":"ch_work_dtbt_37","text":"今監司巡歷郡邑，巡檢、尉必迎於本界首，公裳危立，使者從車內遣謁吏謝之，即揖而退，未嘗以客禮延之也。至有倨橫之人，責橋道不整，驅之車前，使徒步與卒伍齒者。予記張文定公所著縉紳舊聞中一事雲：「餘為江西轉運使，往虔州，巡檢殿直(今保義成忠郎。)康懷琪，乘舟於三十里相接，又欲送至大庾縣，遂與偕行。及至縣驛，驛正廳東西各有一房，予居其左，康處於右。日晚，命之同食，起行數百步，逼暮而退。夜聞康暴得疾，餘亟趨至康所，康已具舟將歸虔，須臾數人扶翼而下，餘策杖隨之。」觀此，則是使者與巡檢同驛而處，同席而食，至於步行送之登舟，今代未之見也。","sortOrder":31},
  {"id":"s_work_dtbt_37_32","chapterId":"ch_work_dtbt_37","text":"十二分野","sortOrder":32},
  {"id":"s_work_dtbt_37_33","chapterId":"ch_work_dtbt_37","text":"十二國分野，上屬二十八宿，其為義多不然，前輩固有論之者矣。其甚不可曉者，莫如晉天文志謂：「自危至奎為娵訾，於辰在亥，衞之分野也，屬幷州。」且衞本受封於河內商虛，後徙楚丘。河內乃冀州所部，漢屬司隸，其他邑皆在東郡，屬兗州，於幷州了不相幹，而幷州之下所列郡名，乃安定、天水、隴西、酒泉、張掖諸郡，自係涼州耳。又謂：「自畢至東井為實沈，於辰在申，魏之分野也，屬益州。」且魏分晉地，得河內、河東數十縣，於益州亦不相幹，而雍州為秦，其下乃列雲中、定襄、雁門、代、太原、上黨諸郡，蓋又自屬幷州及幽州耳。謬亂如此，而出於李淳風之手，豈非蔽於天而不知地乎！","sortOrder":33},
  {"id":"s_work_dtbt_37_34","chapterId":"ch_work_dtbt_37","text":"公孫五樓","sortOrder":34},
  {"id":"s_work_dtbt_37_35","chapterId":"ch_work_dtbt_37","text":"南燕慕容超嗣位之後，悉以國事付公孫五樓，燕業為衰。晉劉裕伐之，或曰：「燕人若塞大峴之險，堅壁清野，大軍深入，將不能自歸。」裕曰：「鮮卑貪婪，不知遠計，謂我不能持久，不過進據臨朐，退守廣固，必不能守險清野。」超聞有晉師，引羣臣會議，五樓曰：「吳兵輕果，利在速戰，不可爭鋒，宜據大峴，使不得入。各命守宰，依險自固，焚蕩資儲，芟除禾苗，使敵無所資。彼僑軍無食，可以坐製。若縱使入峴，出城逆戰，此下策也。」超不聽，裕過大峴，燕兵不出，喜形於色，遂一舉滅燕。觀五樓之計，正裕之所憚也。超平生信用五樓，獨於此不然，蓋天意也。五樓亦可謂智士，足與李左車比肩。後世奸妄擅國，以誤大事者多矣，無所謂五樓之智也。","sortOrder":35},
  {"id":"s_work_dtbt_37_36","chapterId":"ch_work_dtbt_37","text":"薦士稱字著年","sortOrder":36},
  {"id":"s_work_dtbt_37_37","chapterId":"ch_work_dtbt_37","text":"漢、魏以來諸公上表薦士，必首及本郡名，次著其年，又稱其字。如漢孔融薦禰衡表雲「處士平原禰衡，年二十四，字正平」，齊任昉為蕭揚州作薦士表雲「祕書丞琅邪王暕，年二十一，字思晦」，「前候官令東海王僧孺，年三十五，字僧孺」是也。唐以來乃無此式。","sortOrder":37},
  {"id":"s_work_dtbt_37_38","chapterId":"ch_work_dtbt_37","text":"兄弟邪正","sortOrder":38},
  {"id":"s_work_dtbt_37_39","chapterId":"ch_work_dtbt_37","text":"王安石引用小人，造作新法，而弟安國力非之。韓絳附會安石製置三司條例以得宰相，而弟維力爭之。曾布當元符、靖國之間，陰禍善類，而弟肇移書力勸之。兄弟邪正之不同如此。","sortOrder":39},
  {"id":"s_work_dtbt_37_40","chapterId":"ch_work_dtbt_37","text":"容齋三筆","sortOrder":40},
  {"id":"s_work_dtbt_38_1","chapterId":"ch_work_dtbt_38","text":"卷第四(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_38_2","chapterId":"ch_work_dtbt_38","text":"三豎子","sortOrder":2},
  {"id":"s_work_dtbt_38_3","chapterId":"ch_work_dtbt_38","text":"趙為秦所圍，使平原君求救於楚，楚王未肯定從。毛遂曰：「白起，小豎子耳！興師以與楚戰，舉鄢、郢，燒夷陵，辱王之先人，此百世之怨也。」是時，起已數立大功，且勝於長平矣。人告韓信反，漢祖以問諸將，皆曰：「亟發兵坑豎子耳！」帝默然。唯陳平以為兵不如楚精，諸將用兵不能及信。英布反，書聞，上召諸將問計，又曰：「發兵擊之，坑豎子耳！」夫白起、信、布之為人，材能不可揜，以此三人為豎子，是天下無復有壯士也。毛遂之言，祇欲激怒楚王，使之知合從之利害，故不得不以起為懦夫。至如高帝諸將，不過周勃、樊噲之儔。韓信因執而歸，棲棲然處長安為列侯，蓋一匹夫也，而噲喜其過己，趨拜送迎，言稱臣，況於據有全楚萬乘之地，事力強弱，安可同日而語？英布固嘗言：「諸將獨患淮陰、彭越，今皆已死，餘不足畏。」則豎子之對，可謂勇而無謀，殆與張儀詆蘇秦為反覆之人相似。高帝默然，顧深知其非也。至於陳平，則不然矣。若乃韓信謂魏將柏直為豎子，則誠然。柏直庸庸無所知名，漢王亦稱其口尚乳臭，真一豎子也。阮籍登廣武，嘆曰：「時無英雄，使豎子成名。」蓋嘆是時無英雄如昔人者。俗士不達，以為籍譏漢祖，雖李太白亦有是言，失之矣。","sortOrder":3},
  {"id":"s_work_dtbt_38_4","chapterId":"ch_work_dtbt_38","text":"樞密稱呼","sortOrder":4},
  {"id":"s_work_dtbt_38_5","chapterId":"ch_work_dtbt_38","text":"樞密使之名起於唐，本以宦者為之，蓋內諸司之貴者耳。五代始以士大夫居其職，遂與宰相等。自此接於本朝，又有副使、知院事、同知院事、簽書、同簽書之別，雖品秩有高下，然均稱為樞密。明道中，王沂公自故相召為檢校太師、樞密使，李文定公為集賢相，以書迎之於國門，稱曰「樞密太師相公」，予家藏此帖。紹興五年，高宗車駕幸平江，過秀州，執政從行者四人，在前者傳呼「宰相」，趙忠簡也，次呼「樞密」，張魏公也，時為知院事，次呼「參政」，沈必先也，最後又呼「樞密」，則簽書權朝美雲。予為檢詳時，葉審言、黃繼道為長貳，亦同一稱。而二三十年以來，遂有知院、同知之目，初出於典謁、街卒之口，久而朝士亦然，名不雅古，莫此為甚。","sortOrder":5},
  {"id":"s_work_dtbt_38_6","chapterId":"ch_work_dtbt_38","text":"從官事體","sortOrder":6},
  {"id":"s_work_dtbt_38_7","chapterId":"ch_work_dtbt_38","text":"國朝優待侍從，故事體名分多與庶僚不同，然有處之合宜及肆意者。如任知州申發諸司公狀不繫銜，與安撫監司序官往還用大狀不書年，引接用朱衣，通判入都廳之類，皆雜著於令式。其明載國史者尚可考。大中祥符五年六月，詔：「尚書丞郎、兩省給諫知州府，而本部郎中、員外郎及兩省六品以下官充本路轉運使副者，承前例須申報。雖職當統攝，方委於事權，而官有等差，宜明於品級。自今知製誥、觀察使以上知州府處所申轉運司狀，並止簽案檢，令通判以下具銜供申。」張詠以禮部尚書知昇州，上言：「臣官忝六曹，祠部乃本行司局，而例申公狀，似未合宜。望自今尚書丞郎知州者，除申省外，其本行曹局，止簽案檢。」從之。紹興中，范同以前執政知太平州，官係中大夫不帶職，申諸司狀繫銜。提刑張絢封還之，范竟不改。次年轉太中，再任，始去之。劉焞為江西運判，移牒屬郡知、通雲：「請聯銜具報。」邁時以太中守贛，以於式不可，乃作公劄，同通判簽書。劉邦翰曾任權侍郎，以朝議大夫、集英修撰知饒州。趙燁以承議郎提點刑獄，欲居其上，劉不校，趙又畏人議己，於是遇朝拜國忌日，先後行香。王十朋自侍御史徙權吏部侍郎，不拜，除集撰，知饒州，自處如庶官。林大中亦自侍御史改吏侍，不曾供職，除直寶文閣，知贛州，全銜猶帶權知兼勸農事借紫，而盡用從官禮數。黃渙為通判，入都廳，為之不平。鄭汝諧除權侍郎，為東省所繳，不得供職，而以祕撰知池州，公狀至提刑司，不繫銜，為鄧馹牒問。唐瑑以司農少卿，王佐以中書檢正，皆暫兼權戶侍，及出知湖、饒二州，悉用朱衣雙引。此數君皆失於討問典章，非故為尊大也。陳居仁以大中、集撰知鄂州，只用一朱衣，蓋在法，學士乃雙引，人以為得體。邁頃守贛、建，官職與居仁等，而誤用兩朱，殊以自悔。又如監司見前執政，雖本路，並客位下馬。伯氏以故相帶觀文學士帥越，提舉宋藻穿戟門訶殿，雲浙東監司如何不得穿紹興府門，將至廳事，始若勉就客位者。主人亟令掖以還。","sortOrder":7},
  {"id":"s_work_dtbt_38_8","chapterId":"ch_work_dtbt_38","text":"九朝國史","sortOrder":8},
  {"id":"s_work_dtbt_38_9","chapterId":"ch_work_dtbt_38","text":"本朝國史凡三書，太祖、太宗、真宗曰三朝，仁宗、英宗曰兩朝，神宗、哲宗、徽宗、欽宗曰四朝。雖各自紀事，至於諸志若天文、地理、五行之類，不免煩複。元豐中，三朝已就，兩朝且成，神宗專以付曾鞏使合之。鞏奏言：「五朝舊史，皆累世公卿、道德文學、朝廷宗工所共準裁，既已勒成大典，豈宜輒議損益。」詔不許，始謀纂定，會以憂去，不克成。其後神、哲，各自為一史，紹興初，以其是非褒貶皆失實，廢不用。淳熙乙巳，邁承乏修史，丙午之冬，成書進御，遂請合九朝為一，壽皇即以見屬。嘗奏雲：「臣所為區區有請者，蓋以二百年間典章文物之盛，分見三書，倉卒討究，不相貫屬。及累代臣僚，名聲相繼，當如前史以子係父之體，類聚歸一。若夫製作之事，則已經先正名臣之手，是非褒貶，皆有據依，不容妄加筆削。乞以此奏下之史院，俾後來史官，知所以編纘之意，無或輒將成書擅行刪改。」上曰：「如有未穩處，改削無害。」邁既奉詔開院，亦修成三十餘卷矣，而有永思攢宮纔役，才歸即去國，尤袤以高宗皇帝實錄為辭，請權罷史院，於是遂已。祥符中，王旦亦曾修撰兩朝史，今不傳。","sortOrder":9},
  {"id":"s_work_dtbt_38_10","chapterId":"ch_work_dtbt_38","text":"銀牌使者","sortOrder":10},
  {"id":"s_work_dtbt_38_11","chapterId":"ch_work_dtbt_38","text":"金國每遣使出外，貴者佩金牌，次佩銀牌，俗呼為金牌、銀牌郎君。北人以為契丹時如此，牌上若篆字六七，或雲阿骨打花押也。殊不知此本中國之製，五代以來，庶事草創，凡乘置奉使於外，但給樞密院牒。國朝太平興國三年，因李飛雄矯乘馬，詐稱使者，欲作亂，既捕誅之，乃詔自今乘驛者，皆給銀牌，國史雲始復舊製，然則非起於虜也。端拱二年復詔：「先是馳驛使臣給篆書銀牌，自今宜罷之，復給樞密院牒。」","sortOrder":11},
  {"id":"s_work_dtbt_38_12","chapterId":"ch_work_dtbt_38","text":"省錢百陌","sortOrder":12},
  {"id":"s_work_dtbt_38_13","chapterId":"ch_work_dtbt_38","text":"用錢為幣，本皆足陌。梁武帝時，以鐵錢之故，商賈浸以奸詐自破，嶺以東，八十為百，名曰「東錢」；江、郢以上，七十為百，名曰「西錢」；京師以九十為百，名曰「長錢」。大同元年，詔通用足陌，詔下而人不從，錢陌益少，至於末年，遂以三十五為百。唐之盛際，純用足錢。天祐中，以兵亂窘乏，始令以八十五為百。後唐天成，又減其五。漢乾祐中，王章為三司使，復減三。皇朝因漢製，其輸官者，亦用八十，或八十五，然諸州私用，猶有隨俗至於四十八錢。太平興國二年，始詔民間緡錢，定以七十七為百。自是以來，天下承用，公私出納皆然，故名「省錢」。但數十年來，有所謂「頭子錢」，每貫五十六，除中都及軍兵俸料外，自餘州縣官民所當得，其出者每百纔得七十一錢四分，其入者每百為八十二錢四分，元無所謂七十七矣。民間所用，多寡又益不均雲。","sortOrder":13},
  {"id":"s_work_dtbt_38_14","chapterId":"ch_work_dtbt_38","text":"舊官銜冗贅","sortOrder":14},
  {"id":"s_work_dtbt_38_15","chapterId":"ch_work_dtbt_38","text":"國朝官製，沿晚唐、五代餘習，故階銜失之冗贅，予固已數書之。比得皇祐中李端願所書「雪竇山」三大字，其左雲：「鎮潼軍節度觀察留後、金紫光祿大夫、檢校刑部尚書、使持節華州諸軍事、華州刺史，兼御史大夫、上柱國。」凡四十一字。自元豐以後，更使名，罷文散階、檢校官、持節、憲銜、勳官，只雲「鎮潼軍承宣使」六字，比舊省去三十五，可謂簡要。會稽禹廟有唐天復年越王錢鏐所立碑，其全銜九十五字，尤為冗也。","sortOrder":15},
  {"id":"s_work_dtbt_38_16","chapterId":"ch_work_dtbt_38","text":"吏胥侮洗文書","sortOrder":16},
  {"id":"s_work_dtbt_38_17","chapterId":"ch_work_dtbt_38","text":"郡縣胥史，揩易簿案，鄉司尤甚。民已輸租稅，朱批於戶下矣，有所求不遂，復洗去之邑官不能察，而又督理。比其持赤鈔為證，則追逮橫費，為害已深。此特小小者耳，臺省亦然，予除翰林日，所被告命後擬雲「可特授依前正奉大夫充翰林學士」，蓋初書黃時全文，故官告院據以為式，其製當爾。而告身全銜亦雲「告正奉大夫充翰林學士」，予以語吏部蕭照鄰尚書曰：「如此則學士繫銜在官下，於故事有戾，今欲書謝表，當如何？」蕭悚然。旋遣部主事與告院書吏至，乞借元告以去，明日持來，則已改正，移職居官上，但減一「充」字，於行內微覺疏，其外印文，濃淡了無異，其妙至此。","sortOrder":17},
  {"id":"s_work_dtbt_38_18","chapterId":"ch_work_dtbt_38","text":"宣告錯誤","sortOrder":18},
  {"id":"s_work_dtbt_38_19","chapterId":"ch_work_dtbt_38","text":"士大夫告命，間有錯誤，如文官，則猶能自言，書鋪亦不敢大有邀索。獨右列為可憐，而軍伍中出身者尤甚。予檢詳密院諸房日，有涇原副都軍頭乞換授，而所持宣內添註「副」字，為房吏所沮，都頭者不能自明。兩樞密以事見付，予視所添字與正文一體，以白兩樞曰：「使訴者為奸，當妄增品級，不應肯以都頭而自降為副，其為寫宣房之失，無可疑也。」樞以為然，乃為改正。武翼郎李青當磨勘，尚左驗其文書，其始為「大李青」，吏以為罔冒，青無詞以答。周茂振權尚書，閱其告命十餘通，其一告前雲「大李青」，而告身誤去「大」字，故後者相承，只雲「李青」，即日放行遷秩，且給公據付之。兩人者幾困於吏手，幸而獲直。用是以知枉鬱不伸者多矣！","sortOrder":19},
  {"id":"s_work_dtbt_38_20","chapterId":"ch_work_dtbt_38","text":"軍中抵名為官","sortOrder":20},
  {"id":"s_work_dtbt_38_21","chapterId":"ch_work_dtbt_38","text":"紹興以來，兵革務煩，軍中將校除官者，大帥盡藏其告命，只語以所居官，其有事故亡沒者，亦不關申省部除籍，或徑以付他人，至或從白身便為郎、大夫者。楊和王為殿帥，罷一統領使歸部，而申樞密院雲：「此人元姓名曰許超，只是校尉，偶有修武郎李立告，使之鼎名，因得冒轉，續以戰功積累，今為武顯大夫，既已離軍，自合依本姓名及元職位。」超詣院訴，而不能為之詞。予檢詳兵房，為言曰：「一時冒與，自是主將之命。修武以前，固非此人當得。若武翼之後，皆用軍功，使其戰死於陣，則性命須要超承當。今但當剋除不應得九官，而理還其餘資，庶合人情，於理為順。」兩樞密甚然予說，即奏行之。","sortOrder":21},
  {"id":"s_work_dtbt_38_22","chapterId":"ch_work_dtbt_38","text":"禍福有命","sortOrder":22},
  {"id":"s_work_dtbt_38_23","chapterId":"ch_work_dtbt_38","text":"秦氏顓國得志，益厲刑辟，以箝製士大夫，一言語之過差，一文詞之可議，必起大獄，竄之嶺海，於是惡子之無俚者，恃告訐以進。趙超然以「君子之澤，五世而斬」責汀州，吳仲寶以夏二子傳流容州，張淵道以張和公生日詩幾責柳而幸脫，皆是也。予教授福州日，因訪何大圭，忽問：「君識天星乎？」答曰：「未之學。」曰：「豈不能認南方中夏所見列宿乎？」曰：「此却粗識一二。」大圭曰：「君今夕試仰觀熒惑何在？」是時正見於南斗之西。後月餘再相見，時連旬多陰，所謂火曜，已至斗魁之東矣。大圭曰：「使此星入南斗，自有故事。」予聞其語，固已竦然，明日來相訪，曰：「吾曹元不洞曉天文，昨晚葉子廉見顧，言及於此，蹙頞雲：『是名魏星，無人能識，非熒惑也。』」予曰：「十二國星，只在牛、女之下，經星不動，安得轉移？」圭曰：「乾象欲示變，何所不可？子廉雲，『後漢建安二十五年亦曾出。』」蓋秦正封魏國公，圭意比之曹操。予大駭，不復敢酬應。他日，與謝景思、葉晦叔言之，且曰：「使邁為小人告訐之舉，有所不能，萬一此段彰露，為之奈何？」謝、葉曰：「可以言命矣！與是人相識，便是不幸，不如靜以待之。」時歲在己巳，又六年，秦亡，予知免禍，乃始不恐。","sortOrder":23},
  {"id":"s_work_dtbt_38_24","chapterId":"ch_work_dtbt_38","text":"真宗北征","sortOrder":24},
  {"id":"s_work_dtbt_38_25","chapterId":"ch_work_dtbt_38","text":"真宗親征契丹，幸澶淵，以成却敵之功，是時景德元年甲辰，決此計者，寇萊公也。然前五歲，當鹹平二年己亥，契丹寇北邊，上自將禦之，至澶州、大名府，聞范廷召破虜於莫州北，乃還京。時張文定公、李文靖公為相，不知何人贊此決，而後來不傳。用是以知真宗非宴安酖毒而有所畏者，故寇公易以進言。","sortOrder":25},
  {"id":"s_work_dtbt_38_26","chapterId":"ch_work_dtbt_38","text":"宰相不次補","sortOrder":26},
  {"id":"s_work_dtbt_38_27","chapterId":"ch_work_dtbt_38","text":"景德元年七月，宰相李沆薨，時無他相，中書有參知政事王旦、王欽若，不次補。寇準為三司使，真宗欲相之，患其素剛，難獨任，乃先以翰林侍讀學士畢士安為參政，纔一月，並命士安、準為相，而士安居上。旦、欽若各遷官而已。準在太宗朝已兩為執政，今士安乃由侍從超用，惟辟作福，圖任大臣，蓋不應循循歷階而升也。","sortOrder":27},
  {"id":"s_work_dtbt_38_28","chapterId":"ch_work_dtbt_38","text":"外製之難","sortOrder":28},
  {"id":"s_work_dtbt_38_29","chapterId":"ch_work_dtbt_38","text":"中書舍人所承受詞頭，自唐至本朝，皆只就省中起草付吏，逮於告命之成，皆未嘗越日，故其職為難。其以敏捷稱者，如韋承慶下筆輒成，未嘗起草，陸扆初無思慮，揮翰如飛，顏蕘草製數十，無妨談笑，鄭畋動無滯思，同僚閣筆，劉敞臨出局，倚馬一揮九製，皆見書於史策。其遲鈍窘擾者，如陸餘慶至晚不能裁一言，和閉戶精思，徧討羣籍，與夫「斲窗舍人」、「紫微失却張君房」之類，蓋以必欲速成故也。周廣順初，中書舍人劉濤責授少府少監，分司西京，坐遣男頊代草製詞也。頊時為監察御史，亦責復州司戶。自南渡以來，典故散失，每除書之下，先以省劄授之，而續給告，以是遷延稽滯。段拂居官時，纔還家即掩關謝客，畏其趣詞命也。先公使虜歸，除徽猷閣直學士，時劉才邵當製，日於漏舍囑之，至先公出知饒州，幾將一月，猶未受告。其他倩諉朋舊，俾之假手者多矣。故膺此選者，不覺其難，殊與昔異。","sortOrder":29},
  {"id":"s_work_dtbt_38_30","chapterId":"ch_work_dtbt_38","text":"文臣換武使","sortOrder":30},
  {"id":"s_work_dtbt_38_31","chapterId":"ch_work_dtbt_38","text":"祖宗之世，文臣換授武使，皆不越級。錢若水自樞密副使罷守工部侍郎，後除帥幷州，乃換鄧州觀察使。王嗣宗以中丞、侍郎，李士衡以三司使，李維以尚書，王素以端明左丞，亦皆觀察。慶曆初，以陝西四帥方禦夏、羌，欲優其俸賜，故韓琦、范仲淹、王沿、龐籍皆以樞密、龍圖直學士換為廉車。自南渡以來，始大不然。張澄以端明學士，楊倓以敷文學士，便為節度。近者趙師夔、吳琚以待製而換承宣使，不數月間遇恩，即建節鉞。師揆、師垂以祕閣修撰換觀察使，皆度越彝憲，誠異恩也。","sortOrder":31},
  {"id":"s_work_dtbt_38_32","chapterId":"ch_work_dtbt_38","text":"容齋三筆","sortOrder":32},
  {"id":"s_work_dtbt_39_1","chapterId":"ch_work_dtbt_39","text":"卷第五(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_39_2","chapterId":"ch_work_dtbt_39","text":"舜事瞽叟","sortOrder":2},
  {"id":"s_work_dtbt_39_3","chapterId":"ch_work_dtbt_39","text":"孟子之書，上配論語，唯記舜事多誤，故自國朝以來，司馬公、李泰伯及呂南公皆有疑非之說。其最大者，證萬章塗廩、浚井、象入舜宮之問以為然也。孟子既自雲堯使九男事之，二女女焉，百官牛羊倉廩備，以事舜於畎畝之中。則井、廩賤役，豈不能使一夫任其事？堯為天子，象一民耳，處心積慮殺兄而據其妻，是為公朝無復有紀綱法製矣！六藝折中於夫子，四嶽之薦舜，固曰：「瞽子。父頑，母嚚，象傲，克諧以孝，烝烝乂，不格奸。」然則堯試舜之時，頑傲者既已格乂矣。舜履位之後，命禹征有苗，益曰：「帝初於歷山，往於田，日號泣於旻天，於父母，負罪引慝，祗載見瞽瞍，夔夔齋慄，瞽亦允若。」既言允若，豈得復有殺之之意乎？司馬公亦引九男、百官之語，烝烝之對，而不及益贊禹之辭，故詳敍之以示子姪輩。若司馬遷史記、劉向列女傳所載，蓋相承而不察耳。至於桃應有瞽叟殺人之問，雖曰設疑似而請，然亦可謂無稽之言。孟子拒而不答可也，顧再三為之辭，宜其起後學之惑。","sortOrder":3},
  {"id":"s_work_dtbt_39_4","chapterId":"ch_work_dtbt_39","text":"孔子正名","sortOrder":4},
  {"id":"s_work_dtbt_39_5","chapterId":"ch_work_dtbt_39","text":"子路曰：「衞君待子而為政，子將奚先？」子曰：「必也正名乎！」子路曰：「子之迂也！奚其正？」夫子責數之以為「野」。蓋是時夫子在衞，當輒為君之際，留連最久，以其拒父而竊位，故欲正之，此意明白。然子欲適晉，聞其殺鳴犢，臨河而還，謂其無罪而殺士也。里名勝母，曾子不入，邑稱朝歌，墨子回車，邑里之名不善，兩賢去之，安有命世聖人，而肯居無父之國，事不孝之君哉？是可知已！夫子所過者化，不令而行，不言而信，輒待以為政，當非下愚而不移者。苟其用我，必將導之以天理，而趣反其真，所謂命駕虛左而迎其父不難也。則其有補於名義，豈不大哉！為是故不忍亟去以須之。既不吾用，於是慨然反魯。則輒之冥頑悖亂，無所逃於天地之間矣！子路曾不能詳味聖言，執迷不悟，竟於身死其難。惜哉！","sortOrder":5},
  {"id":"s_work_dtbt_39_6","chapterId":"ch_work_dtbt_39","text":"潛火字誤","sortOrder":6},
  {"id":"s_work_dtbt_39_7","chapterId":"ch_work_dtbt_39","text":"今人所用潛火字，如潛火軍兵，潛火器具，其義為防。然以書傳考之，乃當為熸。左傳襄二十六年，楚師大敗，王夷師熸。昭二十三年，子瑕卒，楚師熸。杜預皆註曰：「吳、楚之間謂火滅為熸。」釋文音子潛反，火滅也，禮部韻將廉反，皆讀如殲音。則知當曰熸火。","sortOrder":7},
  {"id":"s_work_dtbt_39_8","chapterId":"ch_work_dtbt_39","text":"永興天書","sortOrder":8},
  {"id":"s_work_dtbt_39_9","chapterId":"ch_work_dtbt_39","text":"大中祥符天書之事，起於佞臣，固無足言。而寇萊公在永興軍，信朱能之詐，亦為此舉，以得召入，再登相位，馴致雷州之禍，鳳德之衰，實為可惜！而天禧實錄所載雲：「周懷政與妖人朱能輩偽造靈命，冀圖恩寵，且日進藥餌。宰相王欽若屢言其妄，復密陳規諫。懷政懼得罪，因共誣譖，言：『捕獲道士譙文易，蓄禁書，有神術，欽若素識之。』故罷相也。」朱能之事，欽若欲以沮寇公之入則有之，謂其陳規諫，當大不然。儻非出於寇，則欽若已攘臂其間矣。實錄蓋欽若提舉日所進，是以溢美，豈能弭後人公議哉！","sortOrder":9},
  {"id":"s_work_dtbt_39_10","chapterId":"ch_work_dtbt_39","text":"王裒嵇紹","sortOrder":10},
  {"id":"s_work_dtbt_39_11","chapterId":"ch_work_dtbt_39","text":"舜之罪也殛鯀，其舉也興禹。鯀之罪足以死，舜徇天下之公議以誅之，故禹不敢怨，而終治水之功，以蓋父之惡。魏王裒、嵇紹，其父死於非命。裒之父儀，猶以為司馬昭安東司馬之故，因語言受害，裒為之終身不西向而坐。紹之父康以魏臣，鍾會譖之於昭，昭方謀篡魏，陰忌之，以故而及誅。紹乃仕於晉武之世，至為惠帝盡節而死。紹之事親，視王裒遠矣！溫公通鑑，猶取其蕩陰之忠，蓋不足道也。","sortOrder":11},
  {"id":"s_work_dtbt_39_12","chapterId":"ch_work_dtbt_39","text":"張詠傳","sortOrder":12},
  {"id":"s_work_dtbt_39_13","chapterId":"ch_work_dtbt_39","text":"張忠定公詠，為一代偉人，而治蜀之績尤為超卓，然實錄所載，了不及之，但雲「出知益州，就加兵部郎中，入為戶部。後馬知節自益徙延，難其代。朝廷以詠前在蜀，寇攘之後，安集有勞，為政明肅，遠民便之，故特命再任」而已。國史本傳略同，而增書促招安使上官正出兵一事。皆詆其知陳州營產業，且與周渭、梁鼎輩五人同傳，殊失之也。韓魏公作公神道碑雲：「公以魁奇豪傑之才，逢時自奮，智略神出，勳業赫赫，震暴當世，誠一世偉人。」道州所刻帖，有公與潭牧書一紙，王荊公跋其後雲：「忠定公歿久矣，而士大夫至今稱之，豈不以剛毅正直有勞於世若公者少歟？」文潞公雲：「予嘗守蜀，睹忠定之像，遺愛在民，欽服已甚。」黃誥雲：「公風烈如此，而不至於宰相，然有忠定之才，而無宰相之位，於公何損？有宰相之位，而無忠定之才，於宰相何益？公雖老死，安肯以此易彼哉！」觀四人之言，史氏發潛德之幽光，為有負矣。","sortOrder":13},
  {"id":"s_work_dtbt_39_14","chapterId":"ch_work_dtbt_39","text":"緋紫假服","sortOrder":14},
  {"id":"s_work_dtbt_39_15","chapterId":"ch_work_dtbt_39","text":"唐宣宗重惜服章，牛叢自司勳員外郎為睦州刺史，上賜之紫，叢既謝，前言曰：「臣所服緋，刺史所借也。」上遽曰：「且賜緋。」然則唐製借服色得於君前服之，國朝之製，到闕則不許。乾道二年，予以起居舍人侍立，見浙西提刑姚憲入對，紫袍金魚。既退，一閤門吏踵其後囁嚅。後兩日，憲辭歸平江，乃緋袍。予疑焉，以問知閤曾覿曰：「聞臨安守與本路監司皆許服所借，而憲昨紫今緋，何也？」覿曰：「監司惟置局在輦下則許服，漕臣是也；若外郡則否，前日姚誤紫，而謁吏不告，已申其罰，且備牒使知之，故今日只本色以入。」姚蓋失於審也，然考功格令既不頒於外，亦自難曉。文惠公知徽州日，借紫，及除江東提舉常平，告身不借。予聞嘗借者當如舊，與郎官薛良朋言之，於是給公據改借。後於江西見轉運判官張堅衣緋，張嘗知泉州，紫袍矣，予舉前說，張欣然即以申考功，已而部符下不許，扣其故，曰：「唯知州借紫而就除本路，雖運判、提舉皆得如初，若他路則不可。」竟不知法如何該說也。若曾因知州府借紫，而後知軍州，其服亦借，不以本路他路也。近吳鎰以知郴州除提舉湖南茶鹽，遂仍借紫，正用前比雲。","sortOrder":15},
  {"id":"s_work_dtbt_39_16","chapterId":"ch_work_dtbt_39","text":"樞密名稱更易","sortOrder":16},
  {"id":"s_work_dtbt_39_17","chapterId":"ch_work_dtbt_39","text":"國朝樞密之名，其長為使，則其貳為副使；其長為知院，則其貳為同知院。如柴禹錫知院，向敏中同知，及曹彬為使，則敏中改副使。王繼英知院，王旦同知，繼馮拯、陳堯叟亦同知，及繼英為使，拯、堯叟乃改簽書院事，而恩例同副使。王欽若、陳堯叟知院，馬知節簽書，及王、陳為使，知節遷副使，其後知節知院，則任中正、周起同知。惟熙寧初，文彥博、呂公弼已為使，而陳升之過闕，留，王安石以升之曾再入樞府，遂除知院。知院與使並置，非故事也，安石之意以沮彥博耳。紹興以來，唯韓世忠、張俊為使，嶽飛為副使。此後除使固多，而其貳只為同知，亦非故事也。又使班視宰相，而乾道職製雜壓，令副使反在同知院之下，尤為未然。","sortOrder":17},
  {"id":"s_work_dtbt_39_18","chapterId":"ch_work_dtbt_39","text":"過稱官品","sortOrder":18},
  {"id":"s_work_dtbt_39_19","chapterId":"ch_work_dtbt_39","text":"士大夫僭妄相尊，日以益甚。予向昔所記文官學士、武官大夫之諺，今又不然。天聖職製：內外文武官不得容人過稱官品，諸節度、觀察，雖檢校官未至太傅者，許稱太傅；防禦使至橫行使，許稱太保；諸司使許稱司徒；幕職官等稱本官；錄事參軍稱都曹；縣令稱長官；判司、簿、尉許稱評事。其太傅、太保，司徒皆一時本等檢校所帶之官也。自後法令不復有此一項，以是其風愈熾，不容整革矣。","sortOrder":19},
  {"id":"s_work_dtbt_39_20","chapterId":"ch_work_dtbt_39","text":"仁宗立嗣","sortOrder":20},
  {"id":"s_work_dtbt_39_21","chapterId":"ch_work_dtbt_39","text":"東坡作范蜀公墓志，雲：「仁宗即位三十五年，未有繼嗣，嘉祐初得疾，中外危恐。公獨上疏乞擇宗室賢者，異其禮物，以系天下心。」凡章十九上。至元祐初，韓維上言，謂其首開建儲之議，其後大臣乃繼有論奏。司馬溫公行狀雲：「至和三年，仁宗始不豫，國嗣未立，天下寒心而不敢言，惟諫官范鎮首發其議，光時為幷州通判，聞而繼之。」按至和三年九月，改為嘉祐元年，歲在丁酉。而前此皇祐五年甲午，有建州人太常博士張述者，以繼嗣未立，上疏曰：「陛下春秋四十四，宗廟社稷之繼，未有託焉。以嫌疑而不決，非孝也；羣臣以諱避而不言，非忠也。願擇宗親才而賢者，異其禮秩，試以職務，俾內外知聖心有所屬。」至和二年丙申，復言之。前後凡七疏，最後語尤激切。蓋述所論乃在兩公之前，而當時及後來莫有知之者，為可惜也！","sortOrder":21},
  {"id":"s_work_dtbt_39_22","chapterId":"ch_work_dtbt_39","text":"郎官員數","sortOrder":22},
  {"id":"s_work_dtbt_39_23","chapterId":"ch_work_dtbt_39","text":"紹熙四年冬，客從中都來，持所抄班朝錄一編相示，蓋朝士官職姓名也。讀至尚書郎，纔有正員四人，其他權攝者亦只六七人耳。因記紹興二十九年，予為吏、禮部時，同舍郎二十人，皆正官。今既限以曾歷監司、郡守，故任館職及寺監、丞者不可進步，其自外召用者，資級已高，曾不數月，必序遷卿、少，以是居之者益少。政和末，郎員冗溢，至於五十有五。侍御史張樸上殿，徽宗諭使論列，退而奏疏，劾十有六人，大略雲：「才品甚下，趨操卑汚，有如汪師心者；性資茸闒，柔佞取容，有如黃願、汪希旦者；淺浮躁妄，為胥輩所輕，有如李莊者；輕侻喧囂，漫不省職，有如李揚者；粗冗不才，褊忿輕發，有如成禔者；人才碌碌，初無可取，有如張高者；志氣衰落，難與任事，有如常者；大言無當，誕詭不情，有如梁子誨者；資望太輕，士論不厭，有如葉椿、唐作求、吳直夫、章芹、李與權、王良欽、強休甫者。乞行罷斥。」從之。考一時標榜，未必盡當，然十六人者後皆不顯，視今日員數，多寡不侔如是。秦檜居相位久，不欲士大夫在朝，末年尤甚。二十四司獨刑部有孫敏脩一員，餘皆兼攝，吏部七司至全付主管告院張雲，兵、工八司，併於一寺主簿。又可怪也！","sortOrder":23},
  {"id":"s_work_dtbt_39_24","chapterId":"ch_work_dtbt_39","text":"東坡慕樂天","sortOrder":24},
  {"id":"s_work_dtbt_39_25","chapterId":"ch_work_dtbt_39","text":"蘇公責居黃州，始自稱東坡居士。詳考其意，蓋專慕白樂天而然。白公有東坡種花二詩雲：「持錢買花樹，城東坡上栽。」又雲：「東坡春向暮，樹木今何如？」又有步東坡詩雲：「朝上東坡步，夕上東坡步。東坡何所愛？愛此新成樹。」又有別東坡花樹詩雲：「何處殷勤重回首？東坡桃李種新成。」皆為忠州刺史時所作也。蘇公在黃，正與白公忠州相似，因憶蘇詩，如贈寫真李道士雲：「他時要指集賢人，知是香山老居士。」贈善相程傑雲：「我似樂天君記取，華顛賞遍洛陽春。」送程懿叔雲：「我甚似樂天，但無素與蠻。」入侍邇英雲：「定似香山老居士，世緣終淺道根深。」而跋曰：「樂天自江州司馬除忠州刺史，旋以主客郎中知製誥，遂拜中書舍人。某雖不敢自比，然謫居黃州，起知文登，召為儀曹，遂忝侍從。出處老少，大略相似，庶幾復享晚節閑適之樂。」去杭州雲：「出處依稀似樂天，敢將衰朽較前賢。」序曰：「平生自覺出處老少粗似樂天。」則公之所以景仰者，不止一再言之，非東坡之名偶爾暗合也。","sortOrder":25},
  {"id":"s_work_dtbt_39_26","chapterId":"ch_work_dtbt_39","text":"縛鷄行","sortOrder":26},
  {"id":"s_work_dtbt_39_27","chapterId":"ch_work_dtbt_39","text":"老杜縛鷄行一篇雲：「小奴縛鷄向市賣，鷄被縛急相喧爭。家中厭鷄食蟲蟻，不知鷄賣還遭烹。蟲鷄於人何厚薄？吾叱奴兒解其縛。鷄蟲得失無了時，註目寒江倚山閣。」此詩自是一段好議論，至結句之妙，非他人所能跂及也。予友李德遠嘗賦東西船行，全擬其意。舉以相示雲：「東船得風帆席高，千里瞬息輕鴻毛。西船見笑苦遲鈍，汗流撐折百張篙。明日風翻波浪異，西笑東船却如此。東西相笑無已時，我但行藏任天理。」是時，德遠誦至三過，頗自喜，予曰：「語意絕工，幾於得奪胎法，只恐行藏任理與註目寒江之句，似不可同日語。」德遠以為知言，銳欲易之，終不能滿意也。","sortOrder":27},
  {"id":"s_work_dtbt_39_28","chapterId":"ch_work_dtbt_39","text":"油污衣詩","sortOrder":28},
  {"id":"s_work_dtbt_39_29","chapterId":"ch_work_dtbt_39","text":"予甫十歲時，過衢州白沙渡，見岸上酒店敗壁間，有題詩兩絕，其名曰犬落水、油污衣。犬詩太俗不足傳，獨後一篇殊有理致。其詞雲：「一點清油污白衣，斑斑駁駁使人疑。縱饒洗遍千江水，爭似當初不污時。」是時甚愛其語，今六十餘年，尚歷歷不忘，漫志於此。","sortOrder":29},
  {"id":"s_work_dtbt_39_30","chapterId":"ch_work_dtbt_39","text":"北虜誅宗王","sortOrder":30},
  {"id":"s_work_dtbt_39_31","chapterId":"ch_work_dtbt_39","text":"紹興庚申，虜主亶誅宗室七十二王，韓昉作詔，略雲：「周行管叔之誅，漢致燕王之辟，茲惟無赦，古不為非。不圖骨肉之間，有懷蜂蠆之毒。皇伯太師宋國王宗磐謂為先帝之元子，常蓄無君之禍心；皇叔太傅兗國王宗儁、虞王宗英、滕王宗偉等，逞躁欲以無厭，助逆謀之妄作。欲申三宥，公議豈容？不煩一兵，羣凶悉殄。已各伏辜，幷除屬籍訖。」紹熙癸丑，今虜主誅其叔鄭王，詔曰：「朕早以嫡孫，欽承先緒。皇叔定武軍節度使鄭王允蹈，屬處諸父，任當重藩，潛引凶徒，共為反計，自以元妃之長子，異於他母之諸王，冀幸國災，窺伺神器。其妹澤國公主長樂牽同產之愛，駙馬都尉唐括蒲剌覩狃連姻之私，預聞其謀，相濟以惡。欲寬燕邸之戮，姑致郭鄰之囚，詢諸羣言，用示大戒。允蹈及其妻卞玉與男按春、阿辛幷公主皆賜自盡，令有司依禮收葬，仍為輟朝。」二事甚相類，蓋其視宗族至親與塗之人無異也。是年冬，倪正父奉使，館於中山，正其誅戮處，相去一月，猶血腥觸人，枯骸塞井，為之終夕不安寢雲。","sortOrder":31},
  {"id":"s_work_dtbt_39_32","chapterId":"ch_work_dtbt_39","text":"州郡書院","sortOrder":32},
  {"id":"s_work_dtbt_39_33","chapterId":"ch_work_dtbt_39","text":"太平興國五年，以江州白鹿洞主明起為褒信主簿。洞在廬山之陽，嘗聚生徒數百人。李煜有國時，割善田數十頃，取其租廩給之；選太學之通經者，俾領洞事，日為諸生講誦。於是起建議以其田入官，故爵命之。白鹿洞由是漸廢。大中祥符二年，應天府民曹誠，即楚丘戚同文舊居造舍百五十間，聚書數千卷，博延生徒，講習甚盛。府奏其事，詔賜額曰應天府書院，命奉禮郎戚舜賓主之，仍令本府幕職官提舉，以誠為府助教。宋興，天下州府有學自此始。其後潭州又有嶽麓書院。及慶曆中，詔諸路州郡皆立學，設官教授，則所謂書院者當合而為一。今嶽麓、白鹿復營之，各自養士，其所廩給禮貌乃過於郡庠。近者巴州亦創置，是為一邦而兩學矣。大學、辟雍並置，尚且不可，是於義為不然也。","sortOrder":33},
  {"id":"s_work_dtbt_39_34","chapterId":"ch_work_dtbt_39","text":"何韓同姓","sortOrder":34},
  {"id":"s_work_dtbt_39_35","chapterId":"ch_work_dtbt_39","text":"韓文公送何堅序雲：「何與韓同姓為近。」嘗疑其說無所從出，後讀史記周本紀，應劭曰：「氏姓註雲，以何姓為韓後。」鄧名世姓氏書辯證雲：「何氏出自姬姓，食采韓原，為韓氏。韓王建為秦所滅，子孫散居陳、楚，江、淮間以韓為何，隨聲變為何氏，然不能詳所出也。」韓王之失國者名安，此雲建，乃齊王之名，鄧筆誤耳。予後讀孫愐唐韻雲：「韓滅，子孫分散江、淮間，音以韓為何，字隨音變，遂為何氏。」乃知名世用此。","sortOrder":35},
  {"id":"s_work_dtbt_39_36","chapterId":"ch_work_dtbt_39","text":"容齋三筆","sortOrder":36},
  {"id":"s_work_dtbt_40_1","chapterId":"ch_work_dtbt_40","text":"卷第六(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_40_2","chapterId":"ch_work_dtbt_40","text":"蕨萁養人","sortOrder":2},
  {"id":"s_work_dtbt_40_3","chapterId":"ch_work_dtbt_40","text":"自古凶年饑歲，民無以食，往往隨所值以為命，如范蠡謂吳人就蒲蠃於東海之濱；蘇子卿掘野鼠所去草實，及齧雪與旃毛幷咽之；王莽教民煮木為酪；南方人饑餓，羣入野澤掘鳧茈；鄧禹軍士食藻菜；建安中，鹹陽人拔取酸棗、藜藿以給食；晉郗鑒在鄒山，兗州百姓掘野鼠、蟄燕；幽州人以桑椹為糧，魏道武亦以供軍；岷蜀食芋。如此而已。吾州外邑，（山樂）崌山在樂平、德興境，李羅萬斛山在浮梁、樂平、鄱陽境，皆綿亘百餘里，山出蕨萁。乾道辛卯、紹熙癸丑歲旱，村民無食，爭往取其根。率以昧旦荷鋤往掘，深至四五尺，壯者日可得六十斤。持歸搗取粉，水澄細者煮食之，如粔籹狀，每根二斤可充一夫一日之食。冬晴且暖，田野間無不出者，或不遠數十里，多至數千人。自九月至二月終，蕨抽拳則根無力，於是始止。蓋救餓羸者半年，天之生物，為人世之利至矣！古人不知用之，傳記亦不載，豈他邦不產此乎？","sortOrder":3},
  {"id":"s_work_dtbt_40_4","chapterId":"ch_work_dtbt_40","text":"賢士隱居者","sortOrder":4},
  {"id":"s_work_dtbt_40_5","chapterId":"ch_work_dtbt_40","text":"士子修己篤學，獨善其身，不求知於人，人亦莫能知者，所至或有之，予每惜其無傳。比得上虞李孟傳錄示四事，故謹書之。","sortOrder":5},
  {"id":"s_work_dtbt_40_6","chapterId":"ch_work_dtbt_40","text":"其一曰，慈溪蔣季莊，當宣和間，鄙王氏之學，不事科舉，閉門窮經，不妄與人接。高抑崇閌居明州城中，率一歲四五訪其廬。季莊聞其至，必倒屣出迎，相對小室，極意講論，自晝竟夜，殆忘寢食。告去則送之數里，相得歡甚。或問抑崇曰：「蔣君不多與人周旋，而獨厚於公，公亦惓惓於彼，願聞其故？」抑崇曰：「閌終歲讀書，凡有疑而未判，與所缺而未知者，每積至數十，輒一扣之，無不迎刃而解。」而蔣之所長，他人未必能知之。世之所謂知己其是乎？","sortOrder":6},
  {"id":"s_work_dtbt_40_7","chapterId":"ch_work_dtbt_40","text":"其二曰，王茂剛，居明之林村，在巖壑深處，有弟不甚學問，使顓治生以餬口，而刻意讀書，足跡未嘗妄出，尤邃於周易。沈煥通判州事，嘗訪之。其見趣絕出於傳註之外雲。氣象嚴重，窺其所得，蓋進而未已也。","sortOrder":7},
  {"id":"s_work_dtbt_40_8","chapterId":"ch_work_dtbt_40","text":"其三曰，顧主簿，不知何許人，南渡後寓於慈溪。廉介有常，安於貧賤，不蘄人之知。至於踐履間，雖細事不苟也。平旦起，俟賣菜者過門，問菜把直幾何，隨所言酬之。他飲食布帛亦然。久之人皆信服，不忍欺。苟一日之用足，則玩心墳典，不事交遊。里中有不安其分、武斷強忮者，相與譏之，曰：「汝豈顧主簿耶？」","sortOrder":8},
  {"id":"s_work_dtbt_40_9","chapterId":"ch_work_dtbt_40","text":"其四曰，周日章，信州永豐人。操行介潔，為邑人所敬。開門授徒，僅有以自給，非其義一毫不取。家至貧，常終日絕食，鄰里或以薄少致饋。時時不繼，寧與妻子忍餓，卒不以求人。隆寒披紙裘，客有就訪，亦欣然延納。望其容貌，聽其論議，莫不聳然。縣尉謝生遺以襲衣，曰：「先生未嘗有求，吾自欲致其勤勤耳，受之無傷也。」日章笑答曰：「一衣與萬鍾等耳，儻無名受之，是不辨禮義也。」卒辭之。汪聖錫亦知其賢，以為近於古之所謂獨行者。","sortOrder":9},
  {"id":"s_work_dtbt_40_10","chapterId":"ch_work_dtbt_40","text":"是四君子，真可書史策雲。","sortOrder":10},
  {"id":"s_work_dtbt_40_11","chapterId":"ch_work_dtbt_40","text":"張籍陳無己詩","sortOrder":11},
  {"id":"s_work_dtbt_40_12","chapterId":"ch_work_dtbt_40","text":"張籍在他鎮幕府，鄆帥李師古又以書幣辟之，籍却而不納，而作節婦吟一章寄之，曰：「君知妾有夫，贈妾雙明珠。感君纏綿意，繫在紅羅襦。妾家高樓連苑起，良人執戟明光裏。知君用心如日月，事夫誓擬同生死。還君明珠雙淚垂，何不相逢未嫁時？」陳無己為潁州教授，東坡領郡，而陳賦妾薄命篇，言為曾南豐作，其首章雲：「主家十二樓，一身當三千。古來妾薄命，事主不盡年。起舞為主壽，相送南陽阡。忍著主衣裳，為人作春妍？有聲當徹天，有淚當徹泉。死者恐無知，妾身長自憐。」全用籍意。或謂無己輕坡公，是不然。前此無己官於彭城，坡公由翰林出守杭，無己越境見之於宋都，坐是免歸，故其詩雲：「一代不數人，百年能幾見？昔為馬首銜，今為禁門鍵。一雨五月涼，中宵大江滿。風帆目力短，江空歲年晚。」其尊敬之盡矣。薄命擬况，蓋不忍師死而遂倍之，忠厚之至也！","sortOrder":12},
  {"id":"s_work_dtbt_40_13","chapterId":"ch_work_dtbt_40","text":"杜詩誤字","sortOrder":13},
  {"id":"s_work_dtbt_40_14","chapterId":"ch_work_dtbt_40","text":"李適之在明皇朝為左相，為李林甫所擠去位，作詩曰：「避賢初罷相，樂聖且銜杯。為問門前客，今朝幾箇來？」故杜子美飲中八仙歌雲：「左相日興費萬錢，飲如長鯨吸百川，銜杯樂聖稱避賢。」正詠適之也。而今所行本誤以「避賢」為「世賢」，絕無意義，兼「世」字是太宗諱，豈敢用哉？秦州雨晴詩雲：「天永秋雲薄，從西萬里風。」謂秋天遼永，風從萬里而來，可謂廣大。而集中作「天水」，此乃秦州郡名，若用之入此篇，其致思淺矣。和李表丈早春作雲：「力疾坐清曉，來詩悲早春。」正答其意。而集中作「來時」，殊失所謂和篇本旨。","sortOrder":14},
  {"id":"s_work_dtbt_40_15","chapterId":"ch_work_dtbt_40","text":"東坡詩用老字","sortOrder":15},
  {"id":"s_work_dtbt_40_16","chapterId":"ch_work_dtbt_40","text":"東坡賦詩，用人姓名，多以老字足成句。如壽州龍潭雲「觀魚幷記老莊周」，病不赴會雲「空對親舂老孟光」，看潮雲「猶似浮江老阿童」，贈黃山人雲「說禪長笑老浮屠」，元長老衲裙雲「乞與佯狂老萬回」，東軒雲「掛冠知有老蕭郎」，侍立邇英雲「定似香山老居士」，贈李道士雲「知是香山老居士」，蒜山亭雲「奇逸多聞老敬通」，汶公東堂雲「一帖空存老遂良」，次韻韶守雲「華髮蕭蕭老遂良」，遊羅浮雲「還須略報老同叔」，贈辯才雲「中有老法師」，寄子由雲「青山老從事」，贈眼醫雲「忘言老尊宿」，「妙高臺中老比丘」，謝惠酒雲「青州老從事」，謝餉魚雲「誰似老方朔」，贈吳子野扇雲「得之老月師」，次韻李端叔雲「此是老牛戩」。是皆以為助語，非真謂其老也，大抵七言則於第五字用之，五言則於第三字用之。若其他錯出，如「再說走老瞞」，「故人餘老龐」，「老濞宮粧傳父祖」，「便腹從人笑老韶」，「老可能為竹寫真」，「不知老奘幾時歸」之類，皆隨語勢而然。白樂天雲「每被老元偷格律」，蓋亦有自來矣。","sortOrder":16},
  {"id":"s_work_dtbt_40_17","chapterId":"ch_work_dtbt_40","text":"杜詩命意","sortOrder":17},
  {"id":"s_work_dtbt_40_18","chapterId":"ch_work_dtbt_40","text":"杜公詩命意用事，旨趣深遠，若隨口一讀，往往不能曉解，姑紀一二篇以示好事者。如：「能畫毛延壽，投壺郭舍人。每蒙天一笑，復似物皆春。政化平如水，皇恩斷若神。時時用抵戲，亦未雜風塵。」第三聯意味頗與前語不相聯貫，讀者或以為疑。按杜之旨，本謂技藝倡優，不應蒙人主顧眄賞接，然使政化如水，皇恩若神，為治大要既無可損，則時時用此輩，亦亡害也。又如：「亂後碧井廢，時清瑤殿深。銅瓶未失水，百丈有哀音。側想美人意，應悲寒甃沉。蛟龍半缺落，猶得折黃金。」此篇蓋見故宮井內汲者得銅瓶而作，然首句便說廢井，則下文翻覆鋪敍為難，而曲折宛轉如是，他人畢一生模寫不能到也。又一篇雲：「鬭鷄初賜錦，舞馬既登牀。簾下宮人出，樓前御柳長。仙遊終一閟，女樂久無香。寂寞驪山道，清秋草木黃。」先忠宣公在北方，得唐人畫驪山宮殿圖一軸，華清宮居山顛，殿外垂簾，宮人無數，穴簾隙而窺，一時伶官戲劇，品類雜沓，皆列於下。杜一詩真所謂親見之也。","sortOrder":18},
  {"id":"s_work_dtbt_40_19","chapterId":"ch_work_dtbt_40","text":"擇福莫若重","sortOrder":19},
  {"id":"s_work_dtbt_40_20","chapterId":"ch_work_dtbt_40","text":"國語載范文子曰：「擇福莫若重，擇禍莫若輕。」且士君子樂天知命，全身遠害，避禍就福，安有迨於禍至擇而處之之理哉？韋昭註雲：「有兩福擇取其重，有兩禍擇取其輕。」蓋以不幸而與禍會，勢不容但已，則權其輕重，順受其一焉。莊子養生主篇雲：「為善無近名，為惡無近刑。」夫孳孳為善，君子之所固然，何至於縱意為惡，而特以不麗於刑為得計哉？是又有說矣，其所謂惡者，蓋與善相對之辭，雖於德為愆義，非若小人以身試禍自速百殃之比也。故下文雲：「可以全生，可以保身，可以盡年。」其旨昭矣。","sortOrder":20},
  {"id":"s_work_dtbt_40_21","chapterId":"ch_work_dtbt_40","text":"用人文字之失","sortOrder":21},
  {"id":"s_work_dtbt_40_22","chapterId":"ch_work_dtbt_40","text":"士人為文，或採已用語言，當深究其旨意，苟失之不考，則必詒論議。紹興七年，趙忠簡公重修哲錄，書成，轉特進，製詞雲：「惟宣仁之誣謗未明，致哲廟之憂勤不顯。」此蓋用范忠宣遺表中語，兩句但易兩字，而甚不然，范之辭雲：「致保佑之憂勤不顯。」專指母後以言，正得其實。今以保佑為哲廟，則了非本意矣。紹興十九年，予為福州教授，為府作謝曆日表，頌德一聯雲：「神祇祖考，既安樂於太平，歲月日時，又明章於庶證。」至乾道中，有外郡亦上表謝曆，蒙其採取用之，讀者以為駢麗精切，予笑謂之曰：「此大有利害，今光堯在德壽，所謂『考』者何哉？」坐客皆縮頸，信乎不可不審也。","sortOrder":22},
  {"id":"s_work_dtbt_40_23","chapterId":"ch_work_dtbt_40","text":"李衛公輞川圖跋","sortOrder":23},
  {"id":"s_work_dtbt_40_24","chapterId":"ch_work_dtbt_40","text":"輞川圖一軸，李趙公題其末雲：「藍田縣鹿苑寺主僧子良贄於予，且曰：『鹿苑即王右丞輞川之第也。右丞篤志奉佛，妻死不再娶，潔居逾三十載。母夫人卒，表宅為寺。今冢墓在寺之西南隅，其圖實右丞之親筆。』予閱玩珍重，永為家藏。」弘憲題其前一行雲：「元和四年八月十三日弘憲題。」弘憲者，吉甫字也。其後衞公又跋雲：「乘閒閱篋書中，得先公相國所收王右丞畫輞川圖，實家世之寶也。先公凡更三十六鎮，故所藏書畫多用方鎮印記。太和二年戊申正月四日，浙江西道觀察等使、檢校禮部尚書兼潤州刺史李德裕恭題。」又一行雲：「開成二年秋七月望日，文饒記。」前後五印：曰淮南節度使印、浙江西道觀察處置等使之印、劍南西川節度使印、山南西道節度使印、鄭滑節度使印，幷贊皇二字。又內合同印，建業文房之印，集賢院藏書印，此三者南唐李氏所用，故後一行曰：「昇元二年十一月三日。」雖今所傳為臨本，然正自超妙。但衞公所志，殊為可疑。唐書李吉甫傳雲：「德宗以來，姑息藩鎮，有終身不易地者。吉甫為相歲餘，凡易三十六鎮。」吉甫平生只為淮南節度耳，今乃言身更三十六鎮，誠大不然。所用印記，如浙西、西川、山西、鄭滑，皆衞公所歷也；且書其父手澤，不言第幾子，而有李字；又自標其字，皆非是，蓋好事者妄為之。白樂天詩所說清源寺，即輞川雲。洪慶善作丹陽洪氏家譜序雲：「丹陽之洪本姓弘，避唐諱改。有弘憲者，元和四年跋輞川圖。」亦大錯也。","sortOrder":24},
  {"id":"s_work_dtbt_40_25","chapterId":"ch_work_dtbt_40","text":"白公夜聞歌者","sortOrder":25},
  {"id":"s_work_dtbt_40_26","chapterId":"ch_work_dtbt_40","text":"白樂天琵琶行，蓋在潯陽江上為商人婦所作。而商乃買茶於浮梁，婦對客奏曲，樂天移船，夜登其舟與飲，了無所忌，豈非以其長安故倡女，不以為嫌邪？集中又有一篇題雲夜聞歌者，時自京城謫潯陽，宿於鄂州，又在琵琶之前。其詞曰：「夜泊鸚鵡洲，秋江月澄澈。鄰船有歌者，發調堪愁絕！歌罷繼以泣，泣聲通復咽。尋聲見其人，有婦顏如雪。獨倚帆檣立，娉婷十七八。夜淚似真珠，雙雙墮明月。借問誰家婦，歌泣何凄切？一問一霑襟，低眉終不說。」陳鴻長恨傳序雲：「樂天深於詩，多於情者也，故所遇必寄之吟詠，非有意於漁色。」然鄂州所見，亦一女子獨處，夫不在焉，瓜田李下之疑，唐人不譏也。今詩人罕談此章，聊復表出。","sortOrder":26},
  {"id":"s_work_dtbt_40_27","chapterId":"ch_work_dtbt_40","text":"謝朏志節","sortOrder":27},
  {"id":"s_work_dtbt_40_28","chapterId":"ch_work_dtbt_40","text":"荀彧佐魏武帝，劉穆之佐宋高祖，高德政佐齊文宣，高熲佐隋文帝，劉文靜佐唐高祖，終之篡漢、晉、魏、周及取隋，其功不細矣。彧以不言伏後事與勸止九錫，飲酖而死。穆之居守丹陽，宋祖北伐，而九錫之旨從北來，愧懼而卒。德政以精神凌逼，為楊愔所譖，熲以為相畜妾，為獨孤後所譖，文靜以妾弟告變，為裴寂所譖，皆不免於誅。蕭道成謀篡宋，欲引謝朏參贊大業，屏人與之語，朏無言。道成必欲引參佐命，以為左長史，從容間道石苞事諷之，朏訖不順指。及受宋禪，方為侍中，不肯解璽綬，引枕而臥，步出府門，道成之子賾欲殺之，道成畏得罪於公議，曰：「殺之適成其名，正當容之度外耳！」遂廢於家。海陵王之世復為侍中，宣城王鸞謀繼大統，多引朝廷名士，朏心不願，乃求出為吳興太守。其弟瀹為吏部尚書，朏致酒與之，曰：「可力飲此，無預人事！」其心蓋惡鸞而末如之何也？朏之志節行義，凜凜如此，司馬溫公猶以為譏，斯亦可恕也已！二筆於士匄、韓厥下略及之，故復詳論於此。","sortOrder":28},
  {"id":"s_work_dtbt_40_29","chapterId":"ch_work_dtbt_40","text":"琵琶亭詩","sortOrder":29},
  {"id":"s_work_dtbt_40_30","chapterId":"ch_work_dtbt_40","text":"江州琵琶亭，下臨江津，國朝以來，往來者多題詠，其工者輒為人所傳。淳熙己亥歲，蜀士郭明復以中元日至亭，賦古風一章，其前雲：「白樂天流落浦湓，作琵琶行，其放懷適意，視憂患死生禍福得喪為何物，非深於道者能之乎？賈傅謫長沙，抑鬱致死；陸相竄南賓，屏絕人事，至從狗竇中度食飲。兩公猶有累乎世，未能如樂天逍遙自得也。予過九江，維舟琵琶亭下，為賦此章。」「香山居士頭欲白，秋風吹作湓城客。眼看世事等虛空，雲夢胸中無一物。舉觴獨醉天為家，詩成萬象遭梳爬。不管時人皆欲殺，夜深江上聽琵琶。賈胡老婦兒女語，淚濕青衫如著雨。此公豈作少狂夢？與世浮沈聊爾汝。我來後公三百年，潯陽至今無管絃。(公詩有「潯陽地僻無音樂」之句。)長安不見遺音寂，依舊匡廬翠掃天。」郭君，成都人，隆興癸未登科，仕不甚達。但賈誼自長沙召還，後為梁王傅乃卒，前所雲少誤矣。吾州餘幹縣東幹越亭有琵琶洲在下，唐劉長卿、張祜輩，皆留題。紹興中，王洋元勃一絕句雲：「塞外烽煙能記否，天涯淪落自心知。眼中風物參差是，只欠江州司馬詩。」真佳句也！","sortOrder":30},
  {"id":"s_work_dtbt_40_31","chapterId":"ch_work_dtbt_40","text":"減損入官人","sortOrder":31},
  {"id":"s_work_dtbt_40_32","chapterId":"ch_work_dtbt_40","text":"唐開元十七年，國子祭酒楊瑒上言：「省司奏限天下明經、進士及第，每年不過百人，竊見流外出身，每歲二千餘人，而明經、進士，不能居其什一，則是服勤道業之士，不如胥吏之得仕也。若以出身人太多，則應諸色裁損，不應獨抑明經、進士。」當時以其言為然。淳熙九年，大減任子員數，是時，吏部四選開具以三年為率，文班進士大約三四百人，任子文武亦如之。而恩倖流外，蓋過二千之數，甚與開元類也。","sortOrder":32},
  {"id":"s_work_dtbt_40_33","chapterId":"ch_work_dtbt_40","text":"韓蘇文章譬喻","sortOrder":33},
  {"id":"s_work_dtbt_40_34","chapterId":"ch_work_dtbt_40","text":"韓、蘇兩公為文章，用譬喻處，重複聯貫，至有七八轉者。韓公送石洪序雲：「論人高下，事後當成敗，若河決下流東註，若駟馬駕輕車就熟路，而王良、造父為之先後也，若燭照數計而龜卜也。」盛山詩序雲：「儒者之於患難，其拒而不受於懷也，若築河堤以障屋霤；其容而消之也，若水之於海，冰之於夏日；其玩而忘之以文辭也，若奏金石以破蟋蟀之鳴、蟲飛之聲。」蘇公百步洪詩雲「長洪斗落生跳波，輕舟南下如投梭。水師絕叫鳧雁起，亂石一綫爭磋磨。有如兔走鷹隼落，駿馬下註千丈坡。斷絃離柱箭脫手，飛電過隙珠翻荷」之類，是也。","sortOrder":34},
  {"id":"s_work_dtbt_40_35","chapterId":"ch_work_dtbt_40","text":"唐昭宗贈諫臣官","sortOrder":35},
  {"id":"s_work_dtbt_40_36","chapterId":"ch_work_dtbt_40","text":"唐僖宗幸蜀，政事悉出內侍田令孜之手。左拾遺孟昭圖、右補闕常濬上疏論事，昭圖坐貶，令孜遣人沉之於蟆頤津，賜濬死。資治通鑑記其事。予讀昭宗實錄，即位之初，贈昭圖起居郎，濬禮部員外郎，以其直諫被戮，故褒之。方時艱危，救亡不暇，而初政及此，通鑑失書之，亦可惜也！","sortOrder":36},
  {"id":"s_work_dtbt_40_37","chapterId":"ch_work_dtbt_40","text":"容齋三筆","sortOrder":37},
  {"id":"s_work_dtbt_41_1","chapterId":"ch_work_dtbt_41","text":"卷第七(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_41_2","chapterId":"ch_work_dtbt_41","text":"執政辭轉官","sortOrder":2},
  {"id":"s_work_dtbt_41_3","chapterId":"ch_work_dtbt_41","text":"真宗天禧元年，合祭天地，禮畢，推恩百僚，宰相以下遷官一等。時參知政事三人，陳彭年自刑部侍郎遷兵部，王曾自左諫議大夫遷給事中，張知白自給事中遷工部侍郎。而知白獨懇辭數四，上敷諭，終不能奪。王曾聞之，亦乞寢恩命。上曰：「知白無他意，但以卿為諫議大夫，班在上，己為給事中，在下，所以固辭，欲品秩有序爾。」於是從知白所請，而優加名數，進階金紫光祿大夫，幷賜功臣爵邑。元祐三年四月，宰執七人，自文彥博仍前太師外，右僕射呂公著除司空、同平章軍國事，中書侍郎呂大防除左僕射，同知樞密院范純仁除右僕射，尚書左丞劉摯除中書侍郎，右丞王存除左丞，唯知樞密院安燾不遷，乃自正議大夫特轉右光祿。燾上章辭，令學士院降詔不允。學士蘇軾以為：「朝廷豈以執政六人，五人進用，故加遷秩以慰其心？既無授受之名，僅似姑息之政，欲奉命草詔，不知所以為詞，伏望從其所請。」御寶批：「可且用一意度作不許詔書進入。」燾竟辭，始免。紹興三十一年，陳康伯自右相拜左相，朱倬自參政拜右相，時葉義問知樞密院，元居倬上，不得遷，朝論謂宜進為使。學士何溥面受草製之旨，曾以為言，高宗不許。紹熙五年七月，主上登極，拜知樞密院趙汝愚為右相，參政陳騤除知院，同知院事餘端禮除參政，而左丞相留正以少保進少傅，乃係特遷，且非覃恩，正固辭，乃止。","sortOrder":3},
  {"id":"s_work_dtbt_41_4","chapterId":"ch_work_dtbt_41","text":"宗室補官","sortOrder":4},
  {"id":"s_work_dtbt_41_5","chapterId":"ch_work_dtbt_41","text":"壽皇聖帝登極赦恩，凡宗子不以服屬遠近，人數多少，其曾獲文解兩次者，並直赴殿試；略通文墨者，所在州量試，即補承信郎。由是入仕者過千人以上。淳熙十六年二月、紹熙五年七月，二赦皆然，故皇族得官不可以數計。偶閱唐昭宗實錄載一事雲：「宗正少卿李克助奏：『準去年十一月赦書，皇三等以上親無官者，每父下放一人出身；皇五等以上親未有出身陪位者，與出身。寺司起請承前舊例，九廟子孫陪位者，每父下放一人出身，共放三百八十人。其諸房宗室等，各赴陪位納到文狀，共一千二十七人。除元不赴陪位，及不納到狀，及違寺司條疏，不取宗室充係落下外，係三百八十人，合放出身。』敕準赦書處分。」予按昭宗以文德元年即位，次年十一月南郊禮畢肆赦，其文略雲：「皇三等以上親，委中書門下各擇有才行者量與改官，無官者，每父下放一人出身；皇五等以上親未有出身陪位者，與出身。」然則亦有三等五等親、陪位與不陪位之差別也。","sortOrder":5},
  {"id":"s_work_dtbt_41_6","chapterId":"ch_work_dtbt_41","text":"孫宣公諫封禪等","sortOrder":6},
  {"id":"s_work_dtbt_41_7","chapterId":"ch_work_dtbt_41","text":"景德、祥符之間，北戎結好，宇內乂寧，一時邪諛之臣，唱為瑞應祺祥，以罔明主，王欽若、陳彭年輩實主張之。天書既降，於是東封、西祀、太清之行，以次丕講，滿朝耆老方正之士，鮮有肯啟昌言以遏其奸焰，雖寇萊公亦為之。而孫宣公奭獨上疏爭救，於再於三，真錄出於欽若提綱，故不能盡載，以故後人罕稱之。予略摘其大概紀於此。","sortOrder":7},
  {"id":"s_work_dtbt_41_8","chapterId":"ch_work_dtbt_41","text":"一章論西祀，曰：「汾陰後土，事不經見。漢都雍，去汾陰至近；河東者，唐王業所起之地，且又都雍，故武帝、明皇行之。今陛下經重關，越險阻，遠離京師根本之固，其為不可甚矣。古者聖王先成民而後致力於神，今土木之功，累年未息，水旱作沴，饑饉居多，乃欲勞民事神，神其享之乎！明皇嬖寵害政，奸佞當塗，以至身播國屯。今議者引開元故事以為盛烈，臣竊不取。今之奸臣，以先帝詔停封禪，故贊陛下，以為繼承先志。且先帝欲北平幽朔，西取繼遷，則未嘗獻一謀，畫一策以佐陛下。而乃卑辭重幣，求和於契丹，蹙國縻爵，姑息於保吉。謂主辱臣死為空言，以誣下罔上為己任，撰造祥瑞，假託鬼神，纔畢東封，便議西幸。以祖宗艱難之業，為佞邪僥倖之資，臣所以長嘆而痛哭也！」","sortOrder":8},
  {"id":"s_work_dtbt_41_9","chapterId":"ch_work_dtbt_41","text":"二章論爭言符瑞，曰：「今野鵰山鹿，並形奏簡，秋旱冬雷，率皆稱賀。將以欺上天，則上天不可欺；將以愚下民，則下民不可愚；將以惑後世，則後世必不信。腹非竊笑，有識盡然。」","sortOrder":9},
  {"id":"s_work_dtbt_41_10","chapterId":"ch_work_dtbt_41","text":"三章論將幸亳州，曰：「國家近日多效唐明皇所為。且明皇非令德之君，觀其禍敗，足為深戒，而陛下反希慕之！近臣知而不諫，得非奸佞乎？明皇奔至馬嵬，楊國忠既誅，乃諭軍士曰：『朕識理不明，寄任失所，近亦覺寤。』然則已晚矣，陛下宜早覺寤，斥遠邪佞，不襲危亂之跡，社稷之福也！」","sortOrder":10},
  {"id":"s_work_dtbt_41_11","chapterId":"ch_work_dtbt_41","text":"四章論朱能天書，曰：「奸憸小人，妄言符瑞，而陛下崇信之，屈至尊以迎拜，歸祕殿以奉安。百僚黎庶，痛心疾首，反唇腹非，不敢直言。臣不避死亡之誅，聽之罪之，惟在聖斷。昔漢文成、五利，妄言不讎，漢武誅之。先帝時，侯莫陳利用方術奸發，誅於鄭州。唐明皇得靈符寶券，皆王鉷、田同秀等所為，不能顯戮，今日見老君於閣上，明日見老君於山中，大臣尸祿以將迎，端士畏威而緘默。及祿山兆亂，輔國劫遷，大命既傾，前功幷棄。今朱能所為是已。願遠思漢武之雄材，近法先帝之英斷，中鑒明皇之召禍，庶幾災害不生，禍亂不作。」","sortOrder":11},
  {"id":"s_work_dtbt_41_12","chapterId":"ch_work_dtbt_41","text":"奭之論諫，雖魏鄭公、陸宣公不能過也。","sortOrder":12},
  {"id":"s_work_dtbt_41_13","chapterId":"ch_work_dtbt_41","text":"赦恩為害","sortOrder":13},
  {"id":"s_work_dtbt_41_14","chapterId":"ch_work_dtbt_41","text":"赦過宥罪，自古不廢，然行之太頻，則惠奸長惡，引小人於大譴之域，其為害固不勝言矣。唐莊宗同光二年大赦，前雲：「罪無輕重，常赦所不原者，鹹赦除之。」而又曰：「十惡五逆、屠牛、鑄錢、故殺人、合造毒藥、持仗行劫、官典犯贓，不在此限。」此製正得其中。當亂離之朝，乃能如是，亦可取也，而今時或不然。","sortOrder":14},
  {"id":"s_work_dtbt_41_15","chapterId":"ch_work_dtbt_41","text":"代宗崇尚釋氏","sortOrder":15},
  {"id":"s_work_dtbt_41_16","chapterId":"ch_work_dtbt_41","text":"唐代宗好祠祀，未甚重佛。元載、王縉、杜鴻漸為相，三人皆好佛。上嘗問以「佛言報應，果為有無」。載等奏：「國家運祚靈長，非宿植福業，何以致之？福業已定，雖時有小災，終不能為害，所以安、史有子禍，僕固病死，回紇、吐蕃不戰而退，此皆非人力所及。」上由是深信之，常於禁中飯僧，有寇至則令僧講仁王經以禳之，寇去則厚加賞賜。胡僧不空，官至卿、監，爵為國公，出入禁闥，勢移權貴，此唐史所載也。予家有嚴郢撰三藏和尚碑，徐季海書，乃不空也，雲：「西域人，氏族不聞於中夏，玄、肅、代三朝皆為國師。代宗初以特進、大鴻臚褒表之。及示疾，又就臥內加開府儀同三司、肅國公。既亡，廢朝三日，贈司空。」其恩禮之寵如此。同時又有僧大濟，為帝常修功德，至殿中監。贈其父惠恭兗州刺史，官為營辦葬事，有敕葬碑，今存。時兵革未盡息，元勛宿將，賞功賦職，不過以此處之，顧施之一僧，繆濫甚矣！","sortOrder":16},
  {"id":"s_work_dtbt_41_17","chapterId":"ch_work_dtbt_41","text":"光武苻堅","sortOrder":17},
  {"id":"s_work_dtbt_41_18","chapterId":"ch_work_dtbt_41","text":"漢光武建武三十年，羣臣請封禪泰山。詔曰：「即位三十年，百姓怨氣滿腹，吾誰欺，欺天乎？若郡縣遠遣吏上壽，盛稱虛美，必髠，令屯田。」於是羣臣不敢復言，其英斷如此。然財二年間，乃因讀河圖會昌符，詔索河雒讖文言九世當封禪者，遂為東封之舉，可謂自相矛盾矣。苻堅禁圖讖之學，尚書郎王佩讀讖，堅殺之，學讖者遂絕。及季年，為慕容氏所困，於長安自讀讖書，雲：「帝出五將久長得。」乃出奔五將山，甫至而為姚萇所執。始禁人為讖學，終乃以此喪身亡國。「久長得」之兆，豈非言久當為姚萇所得乎？又姚與遙同，亦久也。光武與堅非可同日語，特其事偶可議雲。","sortOrder":18},
  {"id":"s_work_dtbt_41_19","chapterId":"ch_work_dtbt_41","text":"周武帝宣帝","sortOrder":19},
  {"id":"s_work_dtbt_41_20","chapterId":"ch_work_dtbt_41","text":"周武帝平齊，中原盡入輿地，陳國不足平也，而雅志節儉，至是愈篤。後宮唯置妃二人，世婦三人，御妻三人，則其下保林、良使輩，度不過數十耳。一傳而至宣帝，奢淫酣縱，自比於天，廣搜美女，以實後宮，儀同以上女不許輒嫁，遂同時立五皇後。父子之賢否不同，一至於此！","sortOrder":20},
  {"id":"s_work_dtbt_41_21","chapterId":"ch_work_dtbt_41","text":"唐觀察使","sortOrder":21},
  {"id":"s_work_dtbt_41_22","chapterId":"ch_work_dtbt_41","text":"唐世於諸道置按察使，後改為采訪處置使，治於所部之大郡。既又改為觀察，其有戎旅之地，即置節度使。分天下為四十餘道，大者十餘州，小者二、三州，但令訪察善惡，舉其大綱。然兵甲、財賦、民俗之事，無所不領，謂之都府，權勢不勝其重，能生殺人，或專私其所領州，而虐視支郡。元結為道州刺史，作舂陵行，以為「諸使誅求符牒二百餘通」，又作賊退示官吏一篇，以為「忍苦裒斂」。陽城守道州，賦稅不時，觀察使數誚責，又遣判官督賦，城自囚於獄。判官去，復遣官來按舉。韓愈送許郢州序雲：「為刺史者常私於其民，不以實應乎府，為觀察使者常急於其賦，不以情信乎州，財已竭而斂不休，人已窮而賦愈急。」韓皋為浙西觀察使，封杖決安吉令孫澥至死。一時所行大抵類此，然每道不過一使臨之耳。今之州郡控製按刺者，率五六人，而臺省不預，毀譽善否，隨其意好，又非唐日一觀察使比也。","sortOrder":22},
  {"id":"s_work_dtbt_41_23","chapterId":"ch_work_dtbt_41","text":"冗濫除官","sortOrder":23},
  {"id":"s_work_dtbt_41_24","chapterId":"ch_work_dtbt_41","text":"自漢以來，官曹冗濫之極者，如更始「竈下養，中郎將，爛羊頭，關內侯」，晉趙王倫「貂不足，狗尾續」，北史周世「員外常侍，道上比肩」，唐武後「補闕連車，拾遺平斗」之諺，皆顯顯著見者。中葉以後，尤為泛濫，張巡在雍丘，纔領一縣千兵，而大將六人，官皆開府特進，然則大將軍告身博一醉，誠有之矣。德宗避難於奉天，渾瑊之童奴曰黃芩，力戰，即封渤海郡王。至於僖、昭之世，遂有「捉船郭使君」、「看馬李僕射」。周行逢據湖湘，境內有「漫天司空、遍地太保」之譏。李茂貞在鳳翔，內外持管籥者，亦呼為司空、太保。韋莊浣花集有贈僕者楊金詩雲：「半年勤苦葺荒居，不獨單寒腹亦虛。努力且為田舍客，他年為爾覓金魚。」是時，人奴腰金曳紫者，蓋不難致也。","sortOrder":24},
  {"id":"s_work_dtbt_41_25","chapterId":"ch_work_dtbt_41","text":"節度使稱太尉","sortOrder":25},
  {"id":"s_work_dtbt_41_26","chapterId":"ch_work_dtbt_41","text":"唐節度使帶檢校官，其初只左右散騎常侍，如李愬在唐鄧時所稱者也，後乃轉尚書及僕射、司空、司徒，能至此者蓋少。僖、昭以降，藩鎮盛強，武夫得志，纔建節鉞，其資級已高，於是復升太保、太傅、太尉，其上惟有太師，故將帥悉稱太尉。元豐定官製，尚如舊貫。崇寧中，改三公為少師、少傅、少保，而以太尉為武階之冠，以是凡管軍者，猶悉稱之。紹興間，葉夢得自觀文殿學士，張澄自端明殿學士，皆拜節度。葉嘗任執政，以暮年擁旄，為儒者之榮，自稱葉太尉。張微時用鄧洵武給使恩出身，羞為武職，但稱尚書如故，其相反如此。","sortOrder":26},
  {"id":"s_work_dtbt_41_27","chapterId":"ch_work_dtbt_41","text":"五代濫刑","sortOrder":27},
  {"id":"s_work_dtbt_41_28","chapterId":"ch_work_dtbt_41","text":"五代之際，時君以殺為嬉，視人命如草芥，唐明宗頗有仁心，獨能斟酌援救。天成三年，京師巡檢軍使渾公兒口奏：有百姓二人，以竹竿習戰鬭之事。帝即傳宣令付石敬瑭處置，敬瑭殺之。次日樞密使安重誨敷奏，方知悉是幼童為戲。下詔自咎，以為失刑，減常膳十日，以謝幽冤；罰敬瑭一月俸；渾公兒削官、杖脊、配流登州；小兒骨肉，賜絹五十匹，粟麥各百碩，便令如法埋葬。仍戒諸道州府，凡有極刑，並須仔細裁遣。此事見舊五代史，新書去之。","sortOrder":28},
  {"id":"s_work_dtbt_41_29","chapterId":"ch_work_dtbt_41","text":"太一推算","sortOrder":29},
  {"id":"s_work_dtbt_41_30","chapterId":"ch_work_dtbt_41","text":"熙寧六年，司天中官正周琮言：「據太一經推算，熙寧七年甲寅歲，太一陽九、百六之數，至是年復元之初，故經言太歲有陽九之災，太一有百六之厄，皆在入元之終或復元之初。陽九、百六當癸丑、甲寅之歲，為災厄之會，而得五福太一移入中都，可以消災為祥。竊詳五福太一自雍熙甲申歲入東南巽宮，故修東太一宮於蘇村；天聖己巳歲入西南坤位，故修西太一宮於八角鎮。望稽詳故事，崇建宮宇。」詔度地於集禧觀之東，於是為中太一宮。時王安石擅國，盡變亂祖宗法度，為宗社之禍，蓋自此始，雖太一照臨，亦不能救也。紹熙四年癸丑、五年甲寅，朝廷之間殊為多事，壽皇聖帝厭代，泰安以久疾退處，人情業業，皆有憂葵恤緯之慮。時無星官曆翁考步推賾，庸詎知非入元、復元之際乎？","sortOrder":30},
  {"id":"s_work_dtbt_41_31","chapterId":"ch_work_dtbt_41","text":"趙丞相除拜","sortOrder":31},
  {"id":"s_work_dtbt_41_32","chapterId":"ch_work_dtbt_41","text":"紹熙五年七月十六日宣麻製，以太中大夫、知樞密院事趙汝愚為特進、右丞相，議者或謂國朝無宗室宰相，且轉官九級非故事。趙上章力辭，不肯入都堂蒞職。越六日，詔改除樞密使，依宰臣超三官。又二日，製除正議大夫、樞密使。邁考按故實，宣和二年，王黼自通議大夫、中書侍郎拜特進、少宰，凡遷八官，黼受之。靖康元年，吳敏自中大夫、知樞密院，拜銀青光祿大夫、少宰，亦遷八官，敏辭之，但以通議就職。秦檜當國，以其子熺為中大夫、知樞密院，已而除觀文殿學士，恩數如右僕射，遂暗轉通奉大夫，踰年，加大學士，徑超七秩為特進，熺處之不疑。舍此三人外，蓋未之有。若自宰相改樞密使，唯夏竦一人。是時以陳執中為昭文相，竦為集賢相，御史言：「竦向在陝西，與執中議論不協，不可同寅政地。」於是貼麻改命，而初製不出。今汝愚先報相麻，後報樞製，乃是經日已久，因固辭以然。又按國史，明道二年，宰臣張士遜、樞密使楊崇勳同日罷，士遜以左僕射判河南府，崇勳以節度使、平章事判許州，明日入謝，崇勳班居上。仁宗問之，士遜奏曰：「崇勳係使相，臣官只僕射，當在下。」即再鎖院，以士遜為使相。是時，學士盛度當製，猶用士遜作相銜，論者非之，謂應用僕射、河南為前銜也。乾道二年，葉顒以前參知政事召還，為知樞密院，未受告而拜左相，邁當製，以新除知樞密院結銜。今汝愚拜相宣麻，已閱八日，故稱新除特進、右丞相。二者皆是也。","sortOrder":32},
  {"id":"s_work_dtbt_41_33","chapterId":"ch_work_dtbt_41","text":"唐昭宗恤錄儒士","sortOrder":33},
  {"id":"s_work_dtbt_41_34","chapterId":"ch_work_dtbt_41","text":"唐昭宗光化三年十二月，左補闕韋莊奏：「詞人才子，時有遺賢，不霑一命於聖明，沒作千年之恨骨。據臣所知，則有李賀、皇甫松、李羣玉、陸龜蒙、趙光遠、溫庭筠、劉德仁、陸逵、傅錫、平曾、賈島、劉稚珪、羅鄴、方幹，俱無顯遇，皆有奇才，麗句清詞，遍在詞人之口，銜冤抱恨，竟為冥路之塵。伏望追賜進士及第，各贈補闕、拾遺。見存唯羅隱一人，亦乞特賜科名，錄升三署。」敕獎莊而令中書門下詳酌處分。次年天復元年赦文，又令中書門下選擇新及第進士中，有久在名場，才沾科級，年齒已高者，不拘常例，各授一官。於是禮部侍郎杜德祥奏：揀到新及第進士陳光問年六十九，曹松年五十四，王希羽年七十三，劉象年七十，柯崇年六十四，鄭希顏年五十九。詔光問、松、希羽可祕書省正字；象、崇、希顏可太子校書。按登科記，是年進士二十六人，光問第四，松第八，希羽第十二，崇、象、希顏居末級。昭宗當斯時離亂極矣，尚能眷眷於寒儒，其可書也。摭言雲：「上新平內難，聞放新進士，喜甚，特敕授官，製詞曰：『念爾登科之際，當予反正之年，宜降異恩，各膺寵命。』時謂此舉為五老牓。」","sortOrder":34},
  {"id":"s_work_dtbt_41_35","chapterId":"ch_work_dtbt_41","text":"容齋三筆","sortOrder":35},
  {"id":"s_work_dtbt_42_1","chapterId":"ch_work_dtbt_42","text":"卷第八(五則)","sortOrder":1},
  {"id":"s_work_dtbt_42_2","chapterId":"ch_work_dtbt_42","text":"徽宗薦嚴疏文","sortOrder":2},
  {"id":"s_work_dtbt_42_3","chapterId":"ch_work_dtbt_42","text":"徽宗以紹興乙卯歲升遐。時忠宣公奉使未反命，滯留冷山，遣使臣沈珍往燕山，建道場於開泰寺，作功德疏曰：「千歲厭世，莫遂乘雲之仙，四海遏音，同深喪考之戚。况故宮為禾黍，改館徒饋於秦牢，新廟遊衣冠，招魂漫歌於楚些。雖置河東之賦，莫止江南之哀，遺民失望而痛心，孤臣久縶惟歐血。伏願盛德之祀，傳百世以彌昌，在天之靈，繼三後而不朽。」北人讀之亦墮淚，爭相傳誦。其後梓宮南還，公已徙燕，率故臣之不忘國恩者，出迎於城北，搏膺大慟，虜俗最重忠義，不以為罪也。","sortOrder":3},
  {"id":"s_work_dtbt_42_4","chapterId":"ch_work_dtbt_42","text":"忠宣公謝表","sortOrder":4},
  {"id":"s_work_dtbt_42_5","chapterId":"ch_work_dtbt_42","text":"建炎三年，先忠宣公銜命使北方，以淮甸賊蜂起，除兼淮南、京東等路撫諭使，俾李成以兵護至南京。公遣書抵成，成方與耿堅圍楚州，答書曰：「汴涸，虹有紅巾，非五千騎不可往。軍食絕，不克唯命。」公陰遣客說堅，堅強成斂兵。公行未至泗，諜雲：「有迎騎甲而來。」副使龔璹憚之，送兵亦不肯前，遂返旆。即上疏言：「李成以餽餉稽緩，有引衆納命建康之語。今靳賽、薛慶方橫，萬一三叛連衡，何以待之？方含垢養晦之時，宜選辯士諭意，優加撫納。」疏奏，高宗即遣使撫諭成，給米五萬斛。初，公戒所遣持奏吏，須疏從中出，乃詣政事堂白副封。時方禁直達，忤宰輔意，以託事滯留為罪，特貶兩秩，而許出滁陽路。紹興十三年使回，始復元官。時已出知饒州，命予作謝表，直敍其故，曰：「論事見從，猶獲稽留之戾。出疆滋久，屢沾曠蕩之恩。始拜明綸，得仍舊秩。伏念臣頃繇乏使，不敢辭難。值三盜之連衡，阻兩淮而薦食，深虞猖獗之患，或起呼吸之間，輒露便宜，冀加勤恤。雖璽書賜報，樂聞充國之建言，而吏議不容，見謂陳湯之生事。虧除官簿，綿歷歲時，敢自意於來歸，遂悉還於所奪。茲蓋忘人之過，與天同功。念臣昔麗於微文，蔽罪本無於他意，故從數赦，俾獲自新。」書印既畢，父兄復共議，秦檜方擅國，見此表語言，未必不怒，乃別草一通引咎曰：「使指稽留，宜速虧除之戾。聖恩深厚，卒從抆拭之科。仰服矜憐，唯知感戴。伏念臣早繇乏使，遂俾行成，值巨寇之臨衝，欲搏人而肆毒，仗節宜圖於報稱，引車何事於逡巡。徐偃出疆，既失受辭之體，申舟假道，初無必死之心。雖蒙貶秩以小懲，尚許立功而自贖。徒行萬里，無補一毫，敢妄冀於隆寬，乃悉還於舊貫。茲蓋忘人之過，撫下以仁。陽為德而陰為刑，未嘗私意，賞有功而赦有罪，皆本好生，坐使孤臣，盡湔宿負」雲雲。前後奉使，無有不轉官者。先公以朝散郎被命，不沾恩凡十五年，而歸僅復所貶，而合磨勘，五官刑部，皆不引用，秦志也。遂終於此階。","sortOrder":5},
  {"id":"s_work_dtbt_42_6","chapterId":"ch_work_dtbt_42","text":"四六名對","sortOrder":6},
  {"id":"s_work_dtbt_42_7","chapterId":"ch_work_dtbt_42","text":"四六駢儷，於文章家為至淺，然上自朝廷命令、詔冊，下而縉紳之間牋書、祝疏，無所不用。則屬辭比事，固宜警策精切，使人讀之激卬，諷味不厭，乃為得體。姑摭前輩及近時綴緝工致者十數聯，以詒同志。","sortOrder":7},
  {"id":"s_work_dtbt_42_8","chapterId":"ch_work_dtbt_42","text":"王元之擬李靖平突厥露布，其敍頡利求降且復謀竄曰：「穽中餓虎，暫為掉尾之求；韝上饑鷹，終有背人之意。」蘄州謝上表曰：「宣室鬼神之問，敢望生還；茂陵封禪之書，已期身後。」","sortOrder":8},
  {"id":"s_work_dtbt_42_9","chapterId":"ch_work_dtbt_42","text":"范文正公微時，嘗冒姓朱，及後歸本宗，作啟曰：「志在逃秦，入境遂稱於張祿；名非霸越，乘舟偶效於陶朱。」用范雎、范蠡，皆當家故事。","sortOrder":9},
  {"id":"s_work_dtbt_42_10","chapterId":"ch_work_dtbt_42","text":"鄧潤甫行貴妃製曰：「關雎之得淑女，無險詖私謁之心；鷄鳴之思賢妃，有警戒相成之道。」","sortOrder":10},
  {"id":"s_work_dtbt_42_11","chapterId":"ch_work_dtbt_42","text":"紹聖中，百僚請御正殿表曰：「皇矣上帝，必臨下而觀四方；大哉乾元，當統天而始萬物。」","sortOrder":11},
  {"id":"s_work_dtbt_42_12","chapterId":"ch_work_dtbt_42","text":"東坡坤成節疏曰：「至哉坤元，德既超於載籍；養以天下，福宜冠於古今。」慰國哀表曰：「大哉孔子之仁，泫然流涕；至矣顯宗之孝，夢若平生。」謝賜帶馬表曰：「枯羸之質，匪伊垂之而帶有餘；斂退之心，非敢後也而馬不進。」","sortOrder":12},
  {"id":"s_work_dtbt_42_13","chapterId":"ch_work_dtbt_42","text":"王履道大燕樂語曰：「五百里采，五百里衞，外包有截之區；八千歲春，八千歲秋，上祝無疆之壽。」除少宰餘深製曰：「蓋四方其訓，以無競維人；必三後協心，而同底於道。」時幷蔡京為三相也。執政以邊功轉官詞曰：「惟皇天付予，庶其在此；率寧人有指，敢弗於從。」","sortOrder":13},
  {"id":"s_work_dtbt_42_14","chapterId":"ch_work_dtbt_42","text":"翟公巽行外國王加恩製曰：「宗祀明堂，所以教諸侯之孝；大賚四海，不敢遺小國之臣。」知越州日，以擅發常平倉米救荒降官，謝表曰：「敢效秦人，坐視越人之瘠；既安劉氏，理知晁氏之危。」","sortOrder":14},
  {"id":"s_work_dtbt_42_15","chapterId":"ch_work_dtbt_42","text":"孫仲益試詞科日，代高麗國王謝賜燕樂表曰：「玉帛萬國，幹舞已格於七旬；簫韶九成，肉味遽忘於三月。」又曰：「蕩蕩乎無能名，雖莫見宮牆之美；欣欣然有喜色，鹹豫聞管籥之音。」自中書舍人知和州，既壓境，見任者拒不納，以啟答郡僚曰：「雖文書銜袖，大人不以為疑；然君命在門，將軍為之不受。」鄰郡不發上供錢米，受旨推究，為平亭其事，鄰守馳啟來謝，答之曰：「包茅不入，敢加問楚之師；輔車相依，自作全虞之計。」","sortOrder":15},
  {"id":"s_work_dtbt_42_16","chapterId":"ch_work_dtbt_42","text":"汪彥章作靖康冊康王文曰：「漢家之厄十世，宜光武之中興；獻公之子九人，惟重耳之尚在。」為中書舍人試潭州，進士何烈卷子內稱臣及聖，問不舉覺，坐罷職，謝表曰：「謂子路使門人為臣，雖誠誖理；而徐邈雲酒中有聖，初亦何心？」又曰：「書馬者與尾而五，常負譴憂；網禽而去面之三，永銜生賜。」宋齊愈坐於金虜立諸臣狀中，輒書「張邦昌」字，送御史臺，責詞曰：「義重於生，雖匹夫不可奪志；士失其守，或一言幾於喪邦。」又曰：「眭孟五行之說，豈所宜言？袁宏九錫之文，茲焉安忍？」責張邦昌詞曰：「雖天奪其衷，坐愚至此；然君異於器，代匱可乎？」知徽州，其鄉郡也，謝啟曰：「城郭重來，疑千載去家之鶴；交遊半在，或一時同隊之魚。」","sortOrder":16},
  {"id":"s_work_dtbt_42_17","chapterId":"ch_work_dtbt_42","text":"何掄除祕書少監，未幾，以口語出守邛，謝啟曰：「雲外三山，風引舟而莫近；海濱八月，槎犯斗以空還。」","sortOrder":17},
  {"id":"s_work_dtbt_42_18","chapterId":"ch_work_dtbt_42","text":"楊政除太尉，湯岐公草製曰：「遠覽漢京，傳楊氏者四世；近稽唐室，書系表者七人。」謂楊震子秉、秉子賜、賜子彪，四世為太尉。李德裕辭太尉雲：「國朝重惜此官，二百年間纔七人。」其用事精確如此。","sortOrder":18},
  {"id":"s_work_dtbt_42_19","chapterId":"ch_work_dtbt_42","text":"蔣子禮拜右相，王詗賀啟曰：「早登黃閣，獨見明公之妙年；今得舊儒，何憂左轄之虛位？」皆用杜詩語「扈聖登黃閣，明公獨妙年」，「左轄頻虛位，今年得舊儒」，亦可稱。","sortOrder":19},
  {"id":"s_work_dtbt_42_20","chapterId":"ch_work_dtbt_42","text":"吾家四六","sortOrder":20},
  {"id":"s_work_dtbt_42_21","chapterId":"ch_work_dtbt_42","text":"乾道初年，張魏公以右相都督江淮。議者謂兩淮保障不可恃，公親往視之。會詔歸朝，未至而免相。文惠公當製，其詞曰：「棘門如兒戲耳，庸謹秋防；袞衣以公歸兮，庶聞辰告。」所謂兒戲者，指邊將也，而讀者乃以為詆魏公。其尾句曰：「春秋責備賢者，慨功業之惟艱；天子加禮大臣，固始終之不替。」所以悵惜之意至矣。王大寶致仕詞曰：「閔勞以事，聖王隆待下之仁；歸絜其身，君子盡遺榮之美。」大寶有遺泄之疾，或又謂有所譏，而實不然。罷相後，起帥浙東，謝表曰：「上丞相之印，方事退藏；懷會稽之章，遽叨進用。」謝生日詩詞啟曰：「五十當貴，適買臣治越之年；八千為秋，辱莊子大椿之譽。」時正五十歲也。","sortOrder":21},
  {"id":"s_work_dtbt_42_22","chapterId":"ch_work_dtbt_42","text":"紹興壬戌詞科代樞密使謝賜玉帶表，文安公曰：「有璞於此必使琢，恍驚製作之工；匪伊垂之則有餘，允謂便蕃之賜。」主司喜焉，擢為第一。","sortOrder":22},
  {"id":"s_work_dtbt_42_23","chapterId":"ch_work_dtbt_42","text":"乙丑年，代謝賜御書周易尚書表，予曰：「八卦之說謂之索，奉以周旋；百篇之義莫得聞，坦然明白。」尾句曰：「但驚奎璧之輝，從天而下；莫測龜龍之祕，行地無疆。」亦忝此選。代福州謝曆日表曰：「神祇祖考，既安樂於太平；歲月日時，又明章於庶徵。」正用詩鳧鷖序「太平之君子，能持盈守成，神祇祖考安樂之也」，洪範庶徵「歲月日時無易，百穀用成，乂用明，俊民用章」，皆上下聯文，未嘗輒增一字。淵聖乾龍節疏曰：「應天而行，早得尊於大有，象日之動，偶蒙難於明夷。」易大有卦「柔得尊位」、「應乎天而時行」，左傳叔孫豹筮遇明夷，「象日之動，故曰君子於行」，彖辭雲「內文明而外柔順，以蒙大難」，亦純用本文。乾道丁亥南郊赦文曰：「皇天後土，監於成命之詩；藝祖太宗，昭我思文之配。」讀者以為壯。後語曰：「天地設位而聖人成能，既撲縕紛之况；雷雨作解而君子赦過，式流汪濊之恩。」此文先三日鎖院所作，冬至日適有雷雪之異，殆成讖雲。葉子昂參知政事，為諫議大夫林安宅所擊罷去，林遂副樞密。已而置獄治其言，皆無實，林責居筠，葉召拜左揆。予草製曰：「既從有北之投，亟下居東之召。有欲為王留者，孰明去就之忠？無以我公歸兮，大慰瞻儀之望。」本意用「公歸」之句，指邦人而言也，故雲「瞻儀」。而御史單時疑之，謂人君而稱臣為我公，彼蓋不詳味詞理耳。子昂坐冬雷罷相，予又當製，曰：「調陰陽而遂萬物，所嗟論道之非；因災異而劾三公，實負應天之愧。」蓋因有諷諫也。嗣濮王加恩製曰：「天神明而照知四方，既下臨於精意；王孫子而本支百世，茲載錫於蕃釐。」又曰：「春秋享祀，獨冠周家之宗盟；老成典刑，蔚為劉氏之祭酒。」士衎製曰：「克羞饋祀，事其先而萬國歡心；肅倡和聲，行於郊而百神受職。」賜宰臣辭免提舉聖政書成轉官詔曰：「為天子父尊之至，永惟傳序之恩；問聖人德何以加，莫越重華之孝。」賜葉資政辭召命詔曰：「見晛曰消，顧何傷於日月；得時則駕，宜亟會於風雲。」賜史大觀文以新蜀帥改越辭免詔曰：「王陽為孝子，敢煩益部之行；莊助留侍中，姑奉會稽之計。」吳璘在興元、修塞兩縣决壞渠為田，獎諭詔曰：「刻石立作三犀牛，重見離堆之利；復陂誰雲兩黃鵠，詎煩鴻卻之謠。」用老杜石犀行雲「秦時蜀太守，刻石立作三犀牛」，及翟方進壞鴻卻陂，童謠雲「反乎覆，陂當復。誰雲者？兩黃鵠」等語也。劉共甫自潭帥除翰林學士，答詔曰：「不見賈生，茲趣長沙之召；既還陸贄，宜膺內相之除。」批執政辭經修哲宗寶訓轉官曰：「念疊矩重規，當賢聖之君七作；而立經陳紀，在謨訓之文百篇。」哲廟正為第七主，而寶訓百卷也。答蔣丞相辭免曰：「永惟萬事之統，知非艱而行惟艱；有不二心之臣，帥以正則罔不正。」禮部為宰臣以顯仁皇後小祥請吉服，奏曰：「練而慨然，禮應順變，期可已矣，懼或過中。」又曰：「漢中天二百而興，益隆大業；舜至孝五十而慕，獨耀前徽。」時高宗聖壽五十四也。辛巳親征詔曰：「惟天惟祖宗，方共扶於基緒；有民有社稷，敢自佚於宴安。」又曰：「歲星臨於吳分，定成肥水之勛；鬭士倍於晉師，可決韓原之勝。」是時，歲星在楚，故雲。檄書曰：「為劉氏左袒，飽聞思漢之忠；徯湯後東征，必慰戴商之望。」又曰：「侯王寧有種乎？人皆可致；富貴是所欲也，時不再來。」紫宸大宴致語曰：「廟謨先定，百官修輔而厥後惟明；黼坐端臨，五帝神聖而其臣莫及。」修聖政轉官詞曰：「念五馬浮江之後，光啟中興；述六龍御天以來，式時猷訓。」又曰：「薦於天而天是受，永言覆燾之恩；問諸朝而朝不知，詎測形容之妙。」汪觀文復官詞曰：「作雷雨之解而宥罪，在法當原；如日月之食而及更，於明何損？」步帥陳敏製曰：「亞夫持重，小棘門、霸上之將軍；不識將屯，冠長樂、未央之衞尉。」吳挺興州製曰：「能得士心，吳起固西河之守；差強人意，廣平開東漢之興。」起復知金州製曰：「惟天不弔，壞萬里之長城；有子而賢，作三軍之元帥。」蕭鷓巴詞曰：「隨會在秦，晉國起六卿之懼；日磾仕漢，秺侯傳七葉之芳。」姚仲復官製曰：「李廣數奇，應恨封侯之相；孟明一眚，終酬拜賜之師。」追封皇第四子邵王詞曰：「舉漢武三王之策，方茂徽章；念周文十子之宗，獨留遺恨。」時已封建三王也。趙忠簡謚製曰：「見夷吾於江左，共知晉室之何憂；還德裕於崖州，豈待令狐之復夢？」王彥贈官詞曰：「申帶礪以丹書之誓，方休甲第之功臣；掛衣冠於神虎之門，竟失戊營之校尉。」向起贈官詞曰：「馳至金城郡，方思充國之忠；生入玉門關，竟負班超之望。」李師顏贈官製曰：「青天上蜀道，久嚴分閫之權；黑水惟梁州，愴失安邊之傑。」襄帥王宣贈官詞曰：「黃河如帶，莫申劉氏之盟；漢水為池，空墮羊公之淚。」王瀹以太常少卿朔祭太廟，忘設象尊、犧尊，降官詞曰：「犧象不設，已廢司彝之供；餼羊空存，殊乖告朔之禮。」潼川神加封詞曰：「駕飛龍兮靈之斿，具嚴渙命；驅厲鬼兮山之左，終相此邦。」青城山蠶叢氏封侯詞曰：「想青神侯國之封，自今以始；雖白帝公孫之盛，於我何加？」陽山龍母詞曰：「居然生子，乘雲氣以為龍；惟爾有神，時雨暘而利物。」魏丞相贈父詞曰：「大名之後必大，非此其身；和戎如樂之和，幸哉有子。」魏蓋以使虜定和議，旋致大用。贈母詞曰：「藏盟府之國功，不殊魏絳；成外家之宅相，重見陽元。」封妻薑氏詞曰：「筮仕於晉曰魏，方開門戶之祥；取妻必齊之薑，孰盛閨闈之美？」虞丞相贈父詞曰：「活千人有封，非其身者在其子；德百世必祀，畸於人者侔於天。」又周仁贈父詞曰：「有子能賢，高舉而集吳地；受予顯服，會同而朝漢京。」用東方朔非有先生傳「高舉遠引，來集吳地」，及兩京賦「春王三朝，會同漢京」也。獎諭吳挺詔曰：「闑外製將軍，方有成於東鄉；舟中皆敵國，應無慮於西河。」梁丞相醴泉使兼侍讀製曰：「珍臺閒館，獨冠皋、伊之倫魁；廣廈細旃，尚論唐、虞之盛際。」又答詔曰：「一言可以興邦，念為臣之不易；三宿而後出晝，勉為王而留行。」王丞相進玉牒加恩製曰：「載籍之傳五三，壯太祖、太宗之立極；賢聖之君六七，耀永昭、永厚之詒謀。」批以旱得雨請御殿曰：「念七月之間則旱，咎徵已深；雖三日已往為霖，憂端未貰。」","sortOrder":23},
  {"id":"s_work_dtbt_42_24","chapterId":"ch_work_dtbt_42","text":"餘不勝書。唯記從兄在泉幕，淮東使者，其友婿也，發京狀薦之。為作謝啟曰：「襟袂相連，夙愧末親之孤陋；雲泥懸望，分無通貴之哀憐。」皆用杜詩。其下句人人知之，上句乃贈李十五丈雲：「孤陋忝末親，等級敢比肩。人生意氣合，相與襟袂連。」此事適著題，而與前送韋書記詩句，偶可整齊用之，故幷紀於此。但以傳示子孫甥侄而已，不足為外人道也。","sortOrder":24},
  {"id":"s_work_dtbt_42_25","chapterId":"ch_work_dtbt_42","text":"唐賢啟狀","sortOrder":25},
  {"id":"s_work_dtbt_42_26","chapterId":"ch_work_dtbt_42","text":"故書中有唐賢啟狀一冊，皆泛泛緘題。其間標為獨孤常州及、劉信州太真、陸中丞長源、呂衡州溫者，各數十篇，亦無可傳誦。時人以其名士，故流行至今。獨孤有與第五相公書雲：「垂示送丘郎中兩詩，詞清興深，常情所不及。『陰天聞斷雁，夜浦送歸人。』醲麗閒遠之外，文句窈窕悽惻，比頃來所示者，才又加等。但吟誦嘆詠，大談於吳中文人耳。」又雲：「昨見送梁侍御六韻，清麗妍雅，妙絕今時，掩映風騷，吟諷不足。」按第五琦乃聚斂之臣，不以文稱，而獨孤獎重之如此。觀表出十字，誠為佳句，乃知唐人工詩者多，不必專門名家而後可稱也。","sortOrder":26},
  {"id":"s_work_dtbt_42_27","chapterId":"ch_work_dtbt_42","text":"容齋三筆","sortOrder":27},
  {"id":"s_work_dtbt_43_1","chapterId":"ch_work_dtbt_43","text":"卷第九(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_43_2","chapterId":"ch_work_dtbt_43","text":"樞密兩長官","sortOrder":2},
  {"id":"s_work_dtbt_43_3","chapterId":"ch_work_dtbt_43","text":"趙汝愚初拜相，陳騤自參知政事除知樞密院，趙辭不受相印，乃改樞密使，而陳已供職累日，朝論謂兩樞長，又名稱不同，為無典故。按熙寧元年觀文殿學士新知大名府陳升之過闕，留知樞密院。故事，樞密使與知院事不並置。時文彥博、呂公弼既為使，神宗以升之三輔政，欲稍異其禮，且王安石意在抑彥博，故特命之。然則自有故事也。","sortOrder":3},
  {"id":"s_work_dtbt_43_4","chapterId":"ch_work_dtbt_43","text":"赦放債","sortOrder":4},
  {"id":"s_work_dtbt_43_5","chapterId":"ch_work_dtbt_43","text":"淳熙十六年二月登極赦：「凡民間所欠債負，不以久近多少，一切除放。」遂有方出錢旬日，未得一息，而幷本盡失之者，人不以為便。何澹為諫大夫，嘗論其事，遂令只償本錢，小人無義，幾至喧噪。紹熙五年七月覃赦，乃只為蠲三年以前者。按晉高祖天福六年八月，赦雲：「私下債負取利及一倍者並放。」此最為得。又雲：「天福五年終以前，殘稅並放。」而今時所放官物，常是以前二年為斷，則民已輸納，無及於惠矣。唯民間房賃欠負，則從一年以前皆免。比之區區五代，翻有所不若也。","sortOrder":5},
  {"id":"s_work_dtbt_43_6","chapterId":"ch_work_dtbt_43","text":"馮道王溥","sortOrder":6},
  {"id":"s_work_dtbt_43_7","chapterId":"ch_work_dtbt_43","text":"馮道為宰相歷數朝，當漢隱帝時，著長樂老自敍，雲：「餘先自燕亡歸河東，事莊宗、明宗、愍帝、清泰帝、晉高祖、少帝、契丹主、漢高祖、今上，三世贈至師傅，階自將仕郎至開府儀同三司，職自幽州巡官至武勝軍節度使，官自試大理評事至兼中書令，正官自中書舍人至戎太傅、漢太師，爵自開國男至齊國公。孝於家，忠於國，口無不道之言，門無不義之貨，下不欺於地，中不欺於人，上不欺於天。其不足者，不能為大君致一統、定八方，誠有愧於歷官，何以答乾坤之施？老而自樂，何樂如之？」道此文載於范質五代通錄，歐陽公、司馬溫公嘗詆誚之，以為無廉恥矣。王溥自周太祖之末為相，至國朝乾德二年罷，嘗作自問詩，述其踐歷，其序雲：「予年二十有五，舉進士甲科，從周祖征河中，改太常丞，登朝時同年生尚未釋褐，不日作相。在廊廟凡十有一年，歷事四朝，去春恩製改太子太保。每思菲陋，當此榮遇，十五年間遂躋極品，儒者之幸，殆無以過。今行年四十三歲，自朝請之暇，但宴居讀佛書，歌詠承平，因作自問詩十五章，以志本末。」此序見三朝史本傳，而詩不傳，頗與長樂敍相類，亦可議也。","sortOrder":7},
  {"id":"s_work_dtbt_43_8","chapterId":"ch_work_dtbt_43","text":"周玄豹相","sortOrder":8},
  {"id":"s_work_dtbt_43_9","chapterId":"ch_work_dtbt_43","text":"唐莊宗時，術士周玄豹以相法言人事，多中。時明宗為內衙指揮使，安重誨使他人易服而坐，召玄豹相之。玄豹曰：「內衙貴將也，此不足當之。」乃指明宗於下坐，曰：「此是也。」因為明宗言其後貴不可言。明宗即位，思玄豹以為神。將召至京師，宰相趙鳳諫，乃止。觀此事，則玄豹之方術可知。然馮道初自燕歸太原，監軍使張承業辟為本院巡官，甚重之。玄豹謂承業曰：「馮生無前程，不可過用。」書記盧質曰：「我曾見杜黃裳寫真圖，道之狀貌酷類焉，將來必副大用，玄豹之言不足信也。」承業於是薦道為霸府從事。其後位極人臣，考終牖下，五代諸臣皆莫能及，則玄豹未得擅唐、許之譽也。道在晉天福中為上相，詔賜生辰器幣。道以幼屬亂離，早喪父母，不記生日，懇辭不受。然則道終身不可問命，獨有形狀可相，而善工亦失之如此。","sortOrder":9},
  {"id":"s_work_dtbt_43_10","chapterId":"ch_work_dtbt_43","text":"鈷鉧滄浪","sortOrder":10},
  {"id":"s_work_dtbt_43_11","chapterId":"ch_work_dtbt_43","text":"柳子厚鈷鉧潭西小丘記雲：「丘之小不能一畝。問其主。曰：『唐氏之棄地，貨而不售。』問其價，曰：『止四百。』予憐而售之。以茲丘之勝，致之灃水鄠、杜，則貴遊之士爭買者，日增千金而愈不可得。今棄是州也，農夫漁父過而陋之，賈四百，連歲不能售。」蘇子美滄浪亭記雲：「予遊吳中，過郡學東，顧草樹鬱然，崇阜廣水，不類乎城中。並水得微徑於雜花修竹之間，東趨數百步，有棄地，三向皆水，旁無民居，左右皆林木相虧蔽。予愛而裴回，遂以錢四萬得之。」予謂二境之勝絕如此，至於人棄不售，安知其後卒為名人賞踐？如滄浪亭者，今為韓蘄王家所有，價直數百萬矣，但鈷鉧復埋沒不可識。士之處世，遇與不遇，其亦如是哉！","sortOrder":11},
  {"id":"s_work_dtbt_43_12","chapterId":"ch_work_dtbt_43","text":"司封失典故","sortOrder":12},
  {"id":"s_work_dtbt_43_13","chapterId":"ch_work_dtbt_43","text":"南渡之後，臺省胥吏舊人多不存，後生習學，加以省記，不復諳悉典章。而司封以閑曹之故，尤為不謹。舊法，大卿、監以上贈父至太尉止，餘官至吏部尚書止。今司封法，餘官至金紫光祿大夫，蓋昔之吏書也，而中散以上贈父至少師止。按政和以前，太尉在太傅上，其上唯有太師，故凡稱攝太尉者，皆為攝太傅，則贈者亦應如此，不應但許至少師也。生為執政，其身後但有子升朝，則累贈可至極品大國公。歐陽公位參知政事、太子少師，後以諸子恩至太師、兗國公，而其子棐亦不過朝大夫耳，見於蘇公祭文及黃門所撰神道碑。比年汪莊敏公任樞密使，以子贈太師，當封國公，而司封以為須一子為侍從乃可，竟不肯施行，不知其說載於何法也？朱漢章却以子贈至大國公。舊少卿、監遇恩，封開國男，食邑三百戶，自後再該加封，則每次增百戶，無止法。今一封即止。舊學士待製，食邑千五百戶以上，每遇恩則加實封，若虛邑五百者，其實封加二百，虛邑三百、二百者，實封加一百。今復不然，雖前執政亦只加虛邑三百耳，故侍從官多至實封百戶即止，尤可笑也。","sortOrder":13},
  {"id":"s_work_dtbt_43_14","chapterId":"ch_work_dtbt_43","text":"老人該恩官封","sortOrder":14},
  {"id":"s_work_dtbt_43_15","chapterId":"ch_work_dtbt_43","text":"晁無咎作積善堂記雲：「大觀元年大赦天下，民百歲男子官，婦人封；仕而父母年九十，官封如民百歲。於是故漳州軍事判官晁仲康之母黃氏年九十一矣，其第四子仲詢走京師狀其事，省中為漳州請，漳州雖沒，赦令初不異往者，丞相以為可而上之，封壽光縣太君。」今自乾道以來，慶典屢下，仕者之父母年七十、八十即得官封，而子已沒者，其家未嘗陳理，為可惜也。","sortOrder":15},
  {"id":"s_work_dtbt_43_16","chapterId":"ch_work_dtbt_43","text":"學士中丞","sortOrder":16},
  {"id":"s_work_dtbt_43_17","chapterId":"ch_work_dtbt_43","text":"淳熙十四年九月，予以雜學士除翰林學士，蔣世脩以諫議大夫除御史中丞，時施聖與在政府，語同列雲：「此二官不常置，今咄咄逼人，吾輩當自點檢。」蓋謂其必大用也，已而皆不然。因考紹興中所除者，不暇縷述，姑從壽皇聖帝以後，至於紹熙五年，枚數之，為學士者九人，仲兄文安公、史魏公、伯兄文惠公、劉忠肅、王日嚴、王魯公、周益公及予，其後李獻之也。二兄、史、劉、王、周皆擢執政，日嚴以耆老拜端明致仕，唯予出補郡，獻之遂踵武。為中丞者六人，辛企李、姚令則、黃德潤、蔣世脩、謝昌國、何自然也。辛、姚、黃皆執政，唯蔣補郡，昌國徙權尚書，即去國，自然以本生母憂持服雲。","sortOrder":17},
  {"id":"s_work_dtbt_43_18","chapterId":"ch_work_dtbt_43","text":"漢高祖父母姓名","sortOrder":18},
  {"id":"s_work_dtbt_43_19","chapterId":"ch_work_dtbt_43","text":"漢高祖父曰太公，母曰媼，見於史者如是而已。皇甫謐、王符始撰為奇語，雲太公名執嘉，又名燸，媼姓王氏。唐弘文館學士司馬貞作史記索隱雲：「母溫氏。是時，打得班固泗水亭長古石碑文，其字分明作『溫』，雲『母溫氏』。與賈膺復、徐彥伯、魏奉古等執對反覆，深嘆古人未聞，聊記異見。」予竊謂固果有此明證，何不載之於漢紀，疑亦後世好事者，如皇甫之徒所增加耳。又嘗在嶺外，見康州龍媼廟碑，亦雲姓溫氏，則指媼為溫者不一也。唐小說纂異記載三史王生醉入高祖廟，見高祖雲：「朕之中外，泗州亭長碑昭然具載外族溫氏。」蓋不根誕妄之說。","sortOrder":19},
  {"id":"s_work_dtbt_43_20","chapterId":"ch_work_dtbt_43","text":"君臣事跡屏風","sortOrder":20},
  {"id":"s_work_dtbt_43_21","chapterId":"ch_work_dtbt_43","text":"唐憲宗元和二年，製君臣事跡。上以天下無事，留意典墳，每覽前代興亡得失之事，皆三復其言。遂采尚書、春秋後傳、史記、漢書、三國志、晏子春秋、吳越春秋、新序、說苑等書君臣行事可為龜鑑者，集成十四篇，自製其序，寫於屏風，列之御座之右，書屏風六扇於中，宣示宰臣。李藩等皆進表稱賀，白居易翰林製詔有批李夷簡及百寮嚴綬等賀表，其略雲：「取而作鑑，書以為屏。與其散在圖書，心存而景慕，不若列之繪素，目睹而躬行，庶將為後事之師，不獨觀古人之象。」又雲：「森然在目，如見其人。論列是非，既庶幾為坐隅之戒；發揮獻納，亦足以開臣下之心。」居易代言，可謂詳盡。又以見唐世人主作一事而中外至於表賀，又答詔勤渠如此，亦幾於叢脞矣。憲宗此書，有辨邪正、去奢泰兩篇，而末年用皇甫鎛而去裴度，荒於遊宴，死於宦侍之手，屏風本意，果安在哉？","sortOrder":21},
  {"id":"s_work_dtbt_43_22","chapterId":"ch_work_dtbt_43","text":"僧道科目","sortOrder":22},
  {"id":"s_work_dtbt_43_23","chapterId":"ch_work_dtbt_43","text":"唐末帝清泰二年二月，功德使奏：「每年誕節，諸州府奏薦僧道，其僧尼欲立講論科、講經科、表白科、文章應製科、持念科、禪科、聲贊科，道士經法科、講論科、文章應製科、表白科、聲贊科、焚修科，以試其能否。」從之。此事見舊五代史記，不知曾行與否，至何時而罷也。蓋是時猶未鬻賣祠部度牒耳。周世宗廢幷寺院，有詔約束雲：「男年十五以上，念得經文一百紙，或讀得五百紙，女年十三以上，念得經文七十紙，或讀得三百紙者，經本府陳狀，乞剃頭，委錄事參軍、本判官試驗。兩京、大名、京兆府、青州各起置戒壇，候受戒時，兩京委祠部差官引試，其三處祗委判官，逐處聞奏。候敕下委祠部給付憑由，方得剃頭受戒。」其防禁之詳如此，非若今時只納錢於官，便可出家也。念經、讀經之異，疑為背誦與對本雲。","sortOrder":23},
  {"id":"s_work_dtbt_43_24","chapterId":"ch_work_dtbt_43","text":"射佃逃田","sortOrder":24},
  {"id":"s_work_dtbt_43_25","chapterId":"ch_work_dtbt_43","text":"漢之法製，大抵因秦，而隨宜損益，不害其為炎漢。唐之法製，大抵因隋，而小加振飾，不害其為盛唐。國家當五季衰亂之後，其究不下秦、隋，然一時設施，固亦有可采取。按周世宗顯德二年，詔：「應逃戶莊田，並許人請射承佃，供納稅租。如三周年內本戶來歸者，其桑田不計荒熟，並交還一半。五周年內歸業者，三分交還一分。如五周年外，除本戶墳塋外，不在交付之限。其近北諸州陷蕃人戶來歸業者，五周年內三分交還二分，十周年內還一半，十五周年內三分還一。此外者，不在交還之限。」其旨明白，人人可曉，非若今之令式文書，盈於幾閣，為猾吏舞文之具，故有捨去物業三五十年，妄人詐稱逃戶子孫，以錢買吏而奪見佃者，為可嘆也。","sortOrder":25},
  {"id":"s_work_dtbt_43_26","chapterId":"ch_work_dtbt_43","text":"周世宗好殺","sortOrder":26},
  {"id":"s_work_dtbt_43_27","chapterId":"ch_work_dtbt_43","text":"史稱周世宗用法太嚴，羣臣職事，小有不舉，往往置之極刑，予既書於續筆矣。薛居正舊史記載其事甚備，而歐陽公多芟去。今略記於此。樊愛能、何徽以用兵先潰，軍法當誅，無可言者。其他如宋州巡檢供奉官竹奉璘以捕盜不獲，左羽林大將軍孟漢卿以監納取耗，刑部員外郎陳渥以檢田失實，濟州馬軍都指揮使康儼以橋道不謹，內供奉官孫延希以督修永福殿而役夫有就瓦中噉飯者，密州防禦副使侯希進以不奉使者命檢視夏苗，左藏庫使符令光以造軍士袍襦不辦，楚州防禦使張順以隱落稅錢，皆抵極刑，而其罪有不至死者。","sortOrder":27},
  {"id":"s_work_dtbt_43_28","chapterId":"ch_work_dtbt_43","text":"孟字義訓","sortOrder":28},
  {"id":"s_work_dtbt_43_29","chapterId":"ch_work_dtbt_43","text":"一字數義，固有之矣。若孟字，只是最長最先之稱，如所謂孟侯、孟孫、元妃孟子、孟春、孟夏之類是也。國語：「優施謂里克妻曰：主孟啗我。」註雲：「大夫之妻稱主，從夫稱也。」而謂孟為里克妻字則非矣。又雲：「孟一作盍。」史記呂後本紀註中引此句，而司馬貞索隱乃雲：「孟者，且也，言且啗我物。」其說無所據。班固幽通賦：「盍孟晉以迨羣。」李善乃註孟為勉。蜀王衍書其臣徐延瓊宅壁為孟言，蜀語謂孟為弱，故以戲之。其後孟知祥得蜀，館於徐第，以為己讖，此義又為無稽也。東坡與歐陽叔弼詩雲：「主孟當啗我，玉鱗金鯉魚。」正用優施語。魯之寶刀曰孟勞，不詳其義。","sortOrder":29},
  {"id":"s_work_dtbt_43_30","chapterId":"ch_work_dtbt_43","text":"向巨原詩","sortOrder":30},
  {"id":"s_work_dtbt_43_31","chapterId":"ch_work_dtbt_43","text":"亡友向巨原，自少時能作詩。予初識之於梁宏夫坐上，未深知之也。是日，偕二友從吳傅朋遊芝山，登五老亭，以「駕言出遊」分韻賦詩。巨原得駕字，其語雲：「茲山何巍巍，氣欲等嵩華。從公二三子，勝日飽閑暇。躋攀謝車輿，自辦兩不借。捫蘿覓幽隥，行椒得孤榭。側送夕陽移，俯視高鳥下。登臨記曩昔，歲月驚代謝。却數一周星，復命千里駕。身從泛梗流，事與浮雲化。朅來共一尊，似為天所赦。明發還問塗，合離足悲吒。」詩成，觀者皆服。傅朋遊絲詩卷數百篇，巨原獨不深嘆美之，頗記其數句曰：「先生著名節，百世追延陵。我評先生賢，不以能書稱。功成磨蒼崖，盛德頌日昇。勿書陵雲榜，華顛踏高層。」句格超峻，其旨皆有規諷，與前所紀劉彥沖古風相類也。後裒其平生所作數千篇，目為葵齋雜藁，倩予為序。時予在章貢，及序成持寄之，則已臥病，僅能於枕上一讀而已。巨原初見韓子蒼，得一詩，曰：「老子真祠地，君來覓紙題。文如士衡俊，年與正平齊。聞說鍾陵郡，官居章水西。涪翁詩律在，佳處可時攜。」而韓集佚不收，但見序中耳。","sortOrder":31},
  {"id":"s_work_dtbt_43_32","chapterId":"ch_work_dtbt_43","text":"葉晦叔詩","sortOrder":32},
  {"id":"s_work_dtbt_43_33","chapterId":"ch_work_dtbt_43","text":"亡友葉黯晦叔，嘗除敕令所刪定官。紹興十九年，為福建帥屬，予嘗因春補諸生，白於府主，邀與同考校，鎖宿貢院兩旬。予作長句雲：「沈沈廣廈清如水，市聲人聲不到耳。一閑十日豈天賜？慚愧紛紛白袍子。相逢更得金玉人，久矣眼中無此士。連牀夜語不成寐，往往鷄聲忽驚起。是中差樂真難名，昔者相過安得此？但憐時節不相謀，正墮清明寒食裏。梨花已空海棠謝，外間物色知餘幾。只恐雨風摧折之，負此一春吾過矣。謝公尋山飽閑暇，應笑腐儒黏故紙。錦囊得句應已多，萬一相思頻寄似。」時謝景思為參議官，故卒章簡之。晦叔和篇雲：「文章萬言抵杯水，世上虛名徒爾耳。我常自笑一生癡，那更將癡笑羣子。大屋沈沈餘百年，到今所閱知幾士？看渠得失自偶然，其間悲喜從何起？君聞我言亦大笑，為說萬事總如此。(缺兩句。)急須了却公家事，門外不知春有幾。(缺三句。)飛雨時聞打窗紙。他年萬一復相從，未必從容今日似。」其語意超新，惜不能盡憶。又嘗雲：「五十六言，大抵多引韻起，若以側句入，尤峻健。如老杜『幽棲地僻經過少，老病人扶再拜難』是也。然此猶是作對，若以散句起又佳。如『苦憶荊州醉司馬，謫官樽俎定常開』是也。」故予自福倅滿歸，晦叔以二詩送別，正用此體。一章雲：「一門伯仲知誰似？四海文章正數君。何事與予如舊識，由來於世兩相聞。閑官各喜光陰賸，勝地空多物色分。忽復翩然從此去，便應變化上青雲。」二章雲：「此地相從驚歲晚，登臨况是客歸時。却將襟抱向誰可？正爾艱難惟子知。情到中年工作惡，別於生世易為悲。梅花盡醉清江上，黯澹西風凍雨垂。」可謂奇作。然相別不兩年即下世，每誦味其語，輒為悽然。因刻所作容齋記，嘗識於末。","sortOrder":33},
  {"id":"s_work_dtbt_43_34","chapterId":"ch_work_dtbt_43","text":"容齋三筆","sortOrder":34},
  {"id":"s_work_dtbt_44_1","chapterId":"ch_work_dtbt_44","text":"卷第十(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_44_2","chapterId":"ch_work_dtbt_44","text":"詞學科目","sortOrder":2},
  {"id":"s_work_dtbt_44_3","chapterId":"ch_work_dtbt_44","text":"熙寧罷詩賦，元祐復之，至紹聖又罷，於是學者不復習為應用之文。紹聖二年，始立宏詞科，除詔、誥、製、敕不試外，其章表、露布、檄書、頌、箴、銘、序、記、誡諭凡九種，以四題作兩場引試，唯進士得預，而專用國朝及時事為題，每取不得過五人。大觀四年，改立詞學兼茂科，增試製誥，內二篇以歷代史故事，每歲一試，所取不得過三人。紹興三年，工部侍郎李擢又乞取兩科裁訂，別立一科，遂增為十二體：曰製、曰誥、曰詔、曰表、曰露布、曰檄、曰箴、曰銘、曰記、曰贊、曰頌、曰序。凡三場，試六篇，每場一古一今，而許卿大夫之任子亦就試，為博學宏詞科，所取不得過五人。任子中選者，賜進士第。雖用唐時科目，而所試文則非也。自乙卯至於紹熙癸丑，二十牓，或三人，或二人，或一人，幷之三十三人，而紹熙庚戌闕不取。其以任子進者，湯岐公至宰相，王日嚴至翰林承旨，李獻之學士，陳子象兵部侍郎，湯朝美右史，陳峴方進用，而予兄弟居其間，文惠公至宰相，文安公至執政，予冒處翰苑。此外皆係已登科人，然擢用者，唯周益公至宰相，周茂振執政，沈德和、莫子齊、倪正父、莫仲謙、趙大本、傅景仁至侍從，葉伯益、季元衡至左右史，餘多碌碌。而見存未顯者，陳宗召也。然則吾家所蒙亦雲過矣。","sortOrder":3},
  {"id":"s_work_dtbt_44_4","chapterId":"ch_work_dtbt_44","text":"唐夜試進士","sortOrder":4},
  {"id":"s_work_dtbt_44_5","chapterId":"ch_work_dtbt_44","text":"唐進士入舉場得用燭，故或者以為自平旦至通宵。劉虛白有「二十年前此夜中，一般燈燭一般風」之句，及三條燭盡之說。按舊五代史選舉志雲：「長興二年，禮部貢院奏當司奉堂帖夜試進士，有何條格者。敕旨：『秋來赴舉，備有常程，夜後為文，曾無舊製。王道以明規是設，公事須白晝顯行，其進士並令排門齊入就試，至閉門時試畢，內有先了者，上曆畫時，旋令先出，其入策亦須晝試，應諸科對策，並依此例。』」則晝試進士，非前例也。清泰二年，貢院又請進士試雜文，並點門入省，經宿就試。至晉開運元年，又因禮部尚書知貢舉竇貞固奏，自前考試進士，皆以三條燭為限，並諸色舉人有懷藏書冊不令就試。未知於何時復有更革。白樂天集中奏狀雲：「進士許用書冊，兼得通宵。」但不明言入試朝暮也。","sortOrder":5},
  {"id":"s_work_dtbt_44_6","chapterId":"ch_work_dtbt_44","text":"納紬絹尺度","sortOrder":6},
  {"id":"s_work_dtbt_44_7","chapterId":"ch_work_dtbt_44","text":"周顯德三年。敕，舊製織造絁紬、絹布、綾羅、錦綺、紗縠等，幅闊二尺起，來年後並須及二尺五分。宜令諸道州府，來年所納官絹，每匹須及一十二兩，其絁紬只要夾密停勻，不定斤兩。其納官紬絹，依舊長四十二尺。乃知今之稅絹，尺度長短闊狹，斤兩輕重，頗本於此。","sortOrder":7},
  {"id":"s_work_dtbt_44_8","chapterId":"ch_work_dtbt_44","text":"朱梁輕賦","sortOrder":8},
  {"id":"s_work_dtbt_44_9","chapterId":"ch_work_dtbt_44","text":"朱梁之惡，最為歐陽公五代史記所斥詈。然輕賦一事，舊史取之，而新書不為拈出。其語雲：「梁祖之開國也，屬黃巢大亂之餘，以夷門一鎮，外嚴烽候，內辟汙萊，厲以耕桑，薄其租賦，士雖苦戰，民則樂輸，二紀之間，俄成霸業。及末帝與莊宗對壘於河上，河南之民，雖困於輦運，亦未至流亡。其義無他，蓋賦斂輕而丘園可戀故也。及莊宗平定梁室，任吏人孔謙為租庸使，峻法以剝下，厚斂以奉上，民產雖竭，軍食尚虧，加之以兵革，因之以饑饉，不四三年，以致顛隕。其義無他，蓋賦役重而寰區失望故也。」予以事考之，此論誠然，有國有家者之龜鑑也。資治通鑑亦不載此一節。","sortOrder":9},
  {"id":"s_work_dtbt_44_10","chapterId":"ch_work_dtbt_44","text":"坎離陰陽","sortOrder":10},
  {"id":"s_work_dtbt_44_11","chapterId":"ch_work_dtbt_44","text":"坎位正北，當幽陰肅殺之地，其象於易為水為月。董仲舒所謂「陰常居大冬，而積於空虛不用之處」，然而謂之陽。離位正南，當文明赫赫之地，於易為日為火。仲舒所謂「陽常居大夏，而以生育長養為事」，然而謂之陰。豈非以陰生於午，陽生於子故邪？司馬貞雲：「天是陽，而南是陽位，故木亦是陽，所以木正為南正也。火是地正，亦稱北正者，火數二，二地數，地陰，主北方，故火正亦稱北正。」究其極摯，頗似難曉，聖人無所雲，古先名儒以至於今，亦未有論之者。","sortOrder":11},
  {"id":"s_work_dtbt_44_12","chapterId":"ch_work_dtbt_44","text":"前執政為尚書","sortOrder":12},
  {"id":"s_work_dtbt_44_13","chapterId":"ch_work_dtbt_44","text":"祖宗朝，曾為執政，其後入朝為他官者甚多。自元豐改官製後，但為尚書。曾孝寬自簽書樞密去位，復拜吏部尚書。韓忠彥自知樞密院出藩，以吏書召。李清臣、蒲宗孟、王存，皆嘗為左丞，而清臣、存復拜吏書，宗孟兵書。先是元祐六年，清臣除目下，為給事中范祖禹封還，朝廷未決，繼又進擬宗孟兵部右丞。蘇轍言：「不如且止。」左僕射呂大防於簾前奏：「諸部久闕尚書，見在人皆資淺，未可用，又不可闕官，須至用前執政。」轍曰：「尚書闕官已數年，何嘗闕事？」遂已。胡宗愈嘗為右丞，召拜禮書、吏書。自崇寧已來，乃不復然。","sortOrder":13},
  {"id":"s_work_dtbt_44_14","chapterId":"ch_work_dtbt_44","text":"河伯娶婦","sortOrder":14},
  {"id":"s_work_dtbt_44_15","chapterId":"ch_work_dtbt_44","text":"史記褚先生所書魏文侯時西門豹為鄴令，問民所疾苦。長老曰：「吾為河伯娶婦，以故貧。」豹問其故，對曰：「鄴三老、廷掾常歲賦斂百姓錢，得數百萬，用其二三十萬為河伯娶婦，與祝巫分其餘錢持歸。巫行視小家女好者，即聘娶，為治齋宮河上，粉飾女，浮之河中而沒。其人家有好女者，多持女遠逃亡，以故城中益空無人。」豹曰：「至娶婦時，吾亦往送。」遂投大巫嫗及三弟子幷三老於河，乃罷去。從是以後，不敢復言為河伯娶婦。予按此事，蓋出於一時雜傳記，疑未必有實。而六國表秦靈公八年，「初以君主妻河。」言初者，自此年而始，不知止於何時，註家無說。司馬貞史記索隱乃雲，初以君主妻河「謂初以此年取他女為君主，君主猶公主也。妻河，謂嫁之河伯，故魏俗猶為河伯娶婦，蓋其遺風。」然則此事秦、魏皆有之矣。","sortOrder":15},
  {"id":"s_work_dtbt_44_16","chapterId":"ch_work_dtbt_44","text":"六經用字","sortOrder":16},
  {"id":"s_work_dtbt_44_17","chapterId":"ch_work_dtbt_44","text":"六經之道同歸，旨意未嘗不一，而用字則有不同者。如佑、祐、右三字一也，而在書為佑，在易為祐，在詩為右。惟、維、唯一也，而在書為惟，在詩為維，在易為唯，左傳亦然。又如易之無字，周禮之灋、眡、薧、鱻、齍、辠、?、（上卥下木）、斞、閷、簭等字，他經皆不然。今人書無咎、無妄，多作無，失之矣。孝宗初登極，以潛邸為佑聖觀，令玉冊官篆牌。奏雲：「篆法佑字無立人，只單作右字。」道士力爭，以為觀名去人，恐不可安跡。有旨特增之。","sortOrder":17},
  {"id":"s_work_dtbt_44_18","chapterId":"ch_work_dtbt_44","text":"鄂州興唐寺鐘","sortOrder":18},
  {"id":"s_work_dtbt_44_19","chapterId":"ch_work_dtbt_44","text":"鄂州城北鳳凰山之陰，有佛剎，曰興唐寺。其小閣有鐘，題志雲：「大唐天祐二年三月十五日新鑄。」勒官階姓名者兩人，一曰金紫光祿大、檢校尚書左僕射、兼御史大陳知新，一曰銀青光祿大、檢校尚書右僕射、兼御史大楊琮。大字之下，皆當有夫字，而悉削去，觀者莫能曉。五代新舊史、九國志並無其說，唯劉道原十國紀年，載楊行密之父名怤，怤與夫同音。是時，行密據淮南，方破杜洪於鄂，而有其地，故將佐為諱之。行密之子渭，建國之後，改文散諸大夫為大卿、御史大夫為御史大憲，更可證也。鄱陽浮洲寺有吳武義二年銅鐘，安國寺有順義三年鐘，皆刺史呂師造。題官稱曰：「光祿大卿、檢校太保、兼御史大卿。」然則亦非大憲也。王得臣麈史嘗辨此事，而雲：「行密遣劉存破鄂州，知新、琮不預。志傳皆略而不書。」予又按楊溥時，劉存以鄂嶽觀察使為都招討使，知新以嶽州刺史為團練使，同將兵擊楚，為所執殺，則知新乃存偏裨，非不預也。","sortOrder":19},
  {"id":"s_work_dtbt_44_20","chapterId":"ch_work_dtbt_44","text":"禰衡輕曹操","sortOrder":20},
  {"id":"s_work_dtbt_44_21","chapterId":"ch_work_dtbt_44","text":"孔融薦禰衡，以為「淑質貞亮，英才卓躒，志懷霜雪，疾惡若讎，任座、史魚，殆無以過，若衡等輩，不可多得」。數稱述於曹操。操欲見之，衡素相輕疾，不肯往，而數有恣言，操懷忿，因召之擊鼓，裸身辱之。融為見操，說其狂疾，求得自謝。操喜，敕門者有客便通，待之極宴，衡乃坐於營門，言語悖逆，操怒，送與劉表。衡為融所薦，東坡謂融視操，特鬼蜮之雄，其勢決不兩立，非融誅操，則操害融。而衡平生唯善融及楊脩，常稱曰：「大兒孔文舉、小兒楊德祖。」融、脩皆死於操手，衡無由得全。漢史言其尚氣剛傲，矯時慢物，此蓋不知其鄙賤曹操，故陷身危機，所謂語言狂悖者，必誦斥其有僭篡之志耳。劉表復不能容，以與黃祖。觀其所著鸚鵡賦，專以自況，一篇之中，三致意焉。如雲：「嬉遊高峻，栖峙幽深。飛不妄集，翔必擇林。雖周旋於羽毛，固殊智而異心。配鸞皇而等美，焉比翼於衆禽？」又雲：「彼賢哲之逢患，猶棲遲以羇旅。矧禽鳥之微物，能馴擾以安處。」又雲：「嗟祿命之衰薄，奚遭時以嶮巇。豈言語以階亂，將不密以致危。」又雲：「顧六翮之殘毀，雖奮迅其焉如。心懷歸而弗果，徒怨毒於一隅。」卒章雲：「苟竭心於所事，敢背惠以忘初。期守死以報德，甘盡辭以效愚。」予每三復其文，而悲傷之。李太白詩雲：「魏帝營八極，蟻觀一禰衡。黃祖斗筲人，殺之受惡名。吳江賦鸚鵡，落筆超羣英。鏘鏘振金石，句句欲飛鳴。摯鶚啄孤鳳，千春傷我情！」此論最為精當也。","sortOrder":21},
  {"id":"s_work_dtbt_44_22","chapterId":"ch_work_dtbt_44","text":"禁中文書","sortOrder":22},
  {"id":"s_work_dtbt_44_23","chapterId":"ch_work_dtbt_44","text":"韓魏公為相，密與仁宗議定立嗣，公曰：「事若行，不可中止，陛下斷自不疑。乞內中批出。」帝意不欲宮人知，曰：「只中書行足矣。」淳熙十四年十月二十二日，壽皇聖帝自德壽持喪還宮，二十五日有旨召對，與吏部尚書蕭燧同引。中使先諭旨曰：「教內翰留身。」既對，乃旋於東華門內行廊下夾一素幄御榻後出一紙，錄唐貞觀中太子承乾監國事以相示。蕭先退，上與邁言，欲令皇太子參決萬幾，使條具合行事宜。仍戒雲：「進入文字須是密。」邁奏言：「當親自書寫實封，詣通進司。」上曰：「也只剪開，不如分付近上一箇內臣。」邁又言：「臣無由可與內臣相聞知，惟御藥是學士院承受文字，尋常只是公家文書傳達，今則不可，欲俟檢索典故了日，却再乞對面納。」上曰：「極好。」於是七日間三得從容。乃知禁廷機事，深畏漏泄如此。(其詳見於所記見聞事實。)","sortOrder":23},
  {"id":"s_work_dtbt_44_24","chapterId":"ch_work_dtbt_44","text":"老子之言","sortOrder":24},
  {"id":"s_work_dtbt_44_25","chapterId":"ch_work_dtbt_44","text":"老子之言，大抵以無為、無名為本，至於絕聖棄智。然所雲：「將欲歙之，必固張之；將欲弱之，必固強之；將欲廢之，必固興之；將欲奪之，必固與之。」乃似於用機械而有心者。微言淵奧，固莫探其旨也。","sortOrder":25},
  {"id":"s_work_dtbt_44_26","chapterId":"ch_work_dtbt_44","text":"孔叢子","sortOrder":26},
  {"id":"s_work_dtbt_44_27","chapterId":"ch_work_dtbt_44","text":"前漢枚乘與吳王濞書曰：「夫以一縷之任，係千鈞之重，上縣無極之高，下垂不測之淵，雖甚愚之人猶知哀其將絕也。馬方駭，鼓而驚之；係方絕，又重鎮之。係絕於天，不可復結。墜入深淵，難以復出。」孔叢子嘉言篇，載子貢之言曰：「夫以一縷之任，係千鈞之重，上縣之於無極之高，下垂之於不測之深，旁人皆哀其絕，而造之者不知其危。馬方駭，鼓而驚之，係方絕，重而鎮之。係絕於高，墜入於深，其危必矣。」枚叔全用此語。漢書註諸家皆不引證，唯李善註文選有之。予按孔叢子一書，漢藝文志不載，蓋劉向父子所未見。但於儒家有太常蓼侯孔臧十篇，今此書之末，有連叢子上下二卷，雲孔臧著書十篇，疑即是已。然所謂叢子者，本陳涉博士孔鮒子魚所論集，凡二十一篇，為六卷。唐以前不為人所稱，至嘉祐四年，宋鹹始為註釋以進，遂傳於世。今讀其文，略無楚、漢間氣骨，豈非齊、梁以來好事者所作乎？孔子家語著錄於漢志，二十七卷，顏師古雲：「非今所有家語也。」","sortOrder":27},
  {"id":"s_work_dtbt_44_28","chapterId":"ch_work_dtbt_44","text":"小星詩","sortOrder":28},
  {"id":"s_work_dtbt_44_29","chapterId":"ch_work_dtbt_44","text":"詩序不知何人所作，或是或非，前人論之多矣。唯小星一篇，顯為可議。大序雲：「惠及下也。」而繼之曰：「夫人惠及賤妾，進御於君。」故毛、鄭從而為之辭，而鄭箋為甚，其釋「肅肅宵征，抱衾與裯」兩句，謂「諸妾肅肅然而行，或早或夜，在於君所，以次序進御。」又雲：「裯者牀帳也，謂諸妾夜行，抱被與牀帳待進御。」且諸侯有一國，其宮中嬪妾雖雲至下，固非閭閻賤微之比，何至於抱衾而行？况於牀帳，勢非一己之力所能致者，其說可謂陋矣。此詩本是詠使者遠適，夙夜征行，不敢慢君命之意，與殷其雷之指同。","sortOrder":29},
  {"id":"s_work_dtbt_44_30","chapterId":"ch_work_dtbt_44","text":"桃源行","sortOrder":30},
  {"id":"s_work_dtbt_44_31","chapterId":"ch_work_dtbt_44","text":"陶淵明作桃源記雲：「源中人自言，先世避秦時亂，率妻子邑人來此絕境，不復出焉，乃不知有漢，無論魏、晉。」系之以詩曰：「嬴氏亂天紀，賢者避其世。黃、綺之商山，伊人亦雲逝。願言躡輕風，高舉尋吾契。」自是之後，詩人多賦桃源行，不過稱贊仙家之樂。唯韓公雲：「神仙有無何渺茫，桃源之說誠荒唐。世俗那知偽為真，至今傳者武陵人。」亦不及淵明所以作記之意。按宋書本傳雲：「潛自以曾祖晉世宰輔，恥復屈身後代。自宋高祖王業漸隆，不復肯仕。所著文章，皆題其年月。義熙以前，則書晉氏年號，自永初以來，唯雲甲子而已。」故五臣註文選用其語。又繼之雲：「意者恥事二姓，故以異之。」此說雖經前輩所詆，然予竊意桃源之事，以避秦為言。至雲「無論魏、晉」，乃寓意於劉裕，託之於秦，借以為喻耳。近時胡宏仁仲一詩，屈折有奇味。大略雲：「靖節先生絕世人，奈何記偽不考真？先生高步窘末代，雅志不肯為秦民。故作斯文寫幽意，要似寰海離風塵。」其說得之矣。","sortOrder":31},
  {"id":"s_work_dtbt_44_32","chapterId":"ch_work_dtbt_44","text":"司封贈典之失","sortOrder":32},
  {"id":"s_work_dtbt_44_33","chapterId":"ch_work_dtbt_44","text":"前所書司封失典故，偶復憶一事，尤為可笑。紹興二十八年，郊祀赦恩，資政殿學士樓炤，父已贈少師，乞加贈，司封以資政殿學士係只封贈一代，父既至少師，不合加贈，獨改封其母范氏、歐陽氏為秦國、魏國夫人。蓋樓公雖嘗為執政，而見居官職須大學士，乃恩及二代，故但用侍從常格。資政殿學士施鉅父仲說，已贈太子太保，加為宮傅，亦不及祖也。乾道六年，仲兄以端明殿學士知太平州。是年郊赦，伯兄已贈祖為太保，而轉運司移牒太平州，雲準吏部牒，取會本路曾任執政官合封贈二代者。仲兄既具以報，又再行下時，祖母及父母已至極品，於是以祖為言，遂復贈太傅，命詞給告，殊非端殿所當得。不知省部一時何所據也？","sortOrder":33},
  {"id":"s_work_dtbt_44_34","chapterId":"ch_work_dtbt_44","text":"辰巳之巳","sortOrder":34},
  {"id":"s_work_dtbt_44_35","chapterId":"ch_work_dtbt_44","text":"律書釋十母十二子之義，大略與今所言同，唯至四月，雲其於十二子為巳，巳者，言陽氣之已盡也。據此，則辰巳之巳，乃為矣音。其他引二十八宿，謂柳為註，畢為濁，昴為留，亦見於毛詩註及左氏傳，如詩謂營室為定星也。","sortOrder":35},
  {"id":"s_work_dtbt_44_36","chapterId":"ch_work_dtbt_44","text":"容齋三筆","sortOrder":36},
  {"id":"s_work_dtbt_45_1","chapterId":"ch_work_dtbt_45","text":"卷第十一(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_45_2","chapterId":"ch_work_dtbt_45","text":"碑志不書名","sortOrder":2},
  {"id":"s_work_dtbt_45_3","chapterId":"ch_work_dtbt_45","text":"碑志之作，本孝子慈孫欲以稱揚其父祖之功德，播之當時，而垂之後世，當直存其名字，無所避隱。然東漢諸銘，載其先代，多只書官。如淳於長夏承碑雲，「東萊府君之孫，太尉掾之中子，右中郎將之弟」，李翊碑雲，「（牜羊）牱太守曾孫，謁者孫，從事君元子」之類是也。自唐及本朝，名人文集所志，往往只稱君諱某字某，至於記序之文，亦然，王荊公為多，殆與求文揚名之旨為不相契。東坡先生送路都曹詩，首言：「乖崖公在蜀，有錄事參軍老病廢事，公責之，遂求去，以詩留別，所謂『秋光都似宦情薄，山色不如歸意濃』者。公驚謝之曰：『吾過矣。同僚有詩人而吾不知。』因留而慰薦之。坡幼時聞父老言，恨不問其姓名。及守潁州，而都曹路君，以小疾求致仕，誦此語，留之不可，乃采前人意作詩送之。」其詩大略雲：「結髮空百戰，市人看先封。誰能搔白首，抱關望夕烽。」則路君之賢而不遇可知矣。然亦不書其名，使之少獲表見，又為可惜也！","sortOrder":3},
  {"id":"s_work_dtbt_45_4","chapterId":"ch_work_dtbt_45","text":"漢文帝不用兵","sortOrder":4},
  {"id":"s_work_dtbt_45_5","chapterId":"ch_work_dtbt_45","text":"史記律書雲：「高祖厭苦軍事，偃武休息。孝文即位，將軍陳武等議曰：『南越、朝鮮，擁兵阻阸，選蠕觀望。宜及士民樂用，征討逆黨，以一封疆。』孝文曰：『朕能任衣冠，念不到此。會呂氏之亂，誤居正位，常戰戰慄慄，恐事之不終。且兵凶器，雖克所願，動亦耗病，謂百姓遠方何？今匈奴內侵，邊吏無功，邊民父子荷兵日久，朕常為動心傷痛，無日忘之。願且堅邊設候，結和通使，休寧北陲，為功多矣。且無議軍。』故百姓無內外之繇，得息肩於田畝，天下富盛，粟至十餘錢。」予謂孝文之仁德如此，與武帝黷武窮兵，為霄壤不侔矣。然班史略不及此事。資治通鑑亦不編入，使其事不甚暴白，惜哉！","sortOrder":5},
  {"id":"s_work_dtbt_45_6","chapterId":"ch_work_dtbt_45","text":"帝王諱名","sortOrder":6},
  {"id":"s_work_dtbt_45_7","chapterId":"ch_work_dtbt_45","text":"帝王諱名，自周世始有此製，然只避之於本廟中耳。「克昌厥後，駿發爾私。」成王時所作詩。昌、發不為文、武諱也。宣王名誦而「吉甫作誦」之句，正在其時。厲王名胡，而「胡為虺蜴」、「胡然厲矣」之句，在其孫幽王時。小國曰胡，亦自若也。襄王名鄭，而鄭不改封。至於出居其國，使者告於秦、晉曰：「鄙在鄭地。」受晉文公朝，而鄭伯傅王。唯秦始皇以父莊襄王名楚，稱楚曰荊，其名曰政，自避其嫌，以正月為一月。蓋已非周禮矣。漢代所謂邦之字曰國，盈之字曰滿，徹之字曰通，雖但諱本字，而吏民犯者有刑。唐太宗名世民，在位之日不偏諱。故戴冑、唐儉為民部尚書，虞世南、李世勣在朝。至於高宗，始改民部為戶部，世勣但為勣。韓公諱辨雲：「今上書及詔，不聞諱滸、勢、秉、機，惟宦官宮妾，乃不敢言喻及機，以為觸犯。」此數者皆其先世嫌名也。本朝尚文之習大盛，故禮官討論，每欲其多，廟諱遂有五十字者。舉場試卷，小涉疑似，士人輒不敢用，一或犯之，往往暗行黜落。方州科舉尤甚，此風殆不可革。然太祖諱下字內有從木從匀者，廣韻於進字中亦收。張魏公以名其子，而音為進。太宗諱字內有從耳從火者，又有梗音，今為人姓如故。高宗諱內從勹從口者亦然。真宗諱從心從亘，音胡登切。若缺其一畫，則為（恒右下去一），遂幷（恒右下去一）字不敢用，而易為常矣。","sortOrder":7},
  {"id":"s_work_dtbt_45_8","chapterId":"ch_work_dtbt_45","text":"家諱中字","sortOrder":8},
  {"id":"s_work_dtbt_45_9","chapterId":"ch_work_dtbt_45","text":"士大夫除官，於官稱及州府曹局名犯家諱者聽回避，此常行之法也。李燾仁甫之父名中，當贈中奉大夫，仁甫請於朝，謂當告家廟，與自身不同，乞用元豐以前官製，贈光祿卿。丞相頗欲許之。予在西垣聞其說，為諸公言，今一變成式，則他日贈中大夫，必為祕書監，贈太中大夫，必為諫議矣，决不可行。遂止。李願為江東提刑，以父名中，所部遂呼為通議，蓋近世率妄稱太中也。李自稱只以本秩曰朝散。黃通老資政之子為臨安通判，府中亦稱為通議，而受之自如。","sortOrder":9},
  {"id":"s_work_dtbt_45_10","chapterId":"ch_work_dtbt_45","text":"記張元事","sortOrder":10},
  {"id":"s_work_dtbt_45_11","chapterId":"ch_work_dtbt_45","text":"自古夷狄之臣來入中國者，必為人用。由餘入秦，穆公以霸，金日磾仕漢，脫武帝五柞之厄。唐世尤多，執失思力、阿史那社爾、李臨淮、高仙芝、渾瑊、李懷光、（足夾）跌光顏、朱邪克用，皆立大功名，不可殫紀。然亦在朝廷所以御之，否則為郭藥師矣。儻使中國英俊，翻致力於異域，忌壯士以資敵國者，固亦多有。賈季在狄，晉六卿以為難日至；桓溫不能留王猛，使為苻堅用；唐莊宗不能知韓延徽，使為阿保機用；皆是也。西夏曩霄之叛，其謀皆出於華州士人張元與吳昊，而其事本末，國史不書。比得田晝承君集，實紀其事雲：「張元、吳昊、姚嗣宗，皆關中人，負氣倜儻，有縱橫才，相與友善。嘗薄遊塞上，觀覘山川風俗，有經略西鄙意。姚題詩崆峒山寺壁，在兩界間，雲：『南粵幹戈未息肩，五原金鼓又轟天。崆峒山叟笑無語，飽聽松聲春晝眠。』范文正公巡邊，見之大驚。又有『踏破賀蘭石，掃清西海塵』之句。張為鸚鵡詩，卒章曰：『好著金籠收拾取，莫教飛去別人家。』吳亦有詩。將謁韓、范二帥，恥自屈，不肯往，乃礱大石，刻詩其上，使壯夫拽之於通衢，三人從後哭之，欲以鼓動二帥。既而果召與相見，躊躇未用間，張、吳徑走西夏。范公以急騎追之，不及，乃表姚入幕府。張、吳既至夏國，夏人倚為謀主，以抗朝廷，連兵十餘年，西方至為疲弊，職此二人為之。時二人家屬羈縻隨州，間使諜者矯中國詔釋之，人未有知者。後乃聞西人臨境，作樂迎此二家而去，自是邊帥始待士矣。姚又有述懷詩曰：『大開雙白眼，只見一青天。』張有雪詩曰：『五丁仗劍決雲霓，直取銀河下帝畿。戰死玉龍三十萬，敗鱗風卷滿天飛。』吳詩獨不傳。觀此數聯，可想見其人非池中物也。」承君所記如此。予謂張、吳在夏國，然後舉事，不應韓、范作帥日尚猶在關中，豈非記其歲時先後不審乎？姚、張詩，筆談諸書，頗亦紀載。張、吳之名，正與羌酋二字同，蓋非偶然也。","sortOrder":11},
  {"id":"s_work_dtbt_45_12","chapterId":"ch_work_dtbt_45","text":"宮室土木","sortOrder":12},
  {"id":"s_work_dtbt_45_13","chapterId":"ch_work_dtbt_45","text":"秦始皇作阿房宮，寫蜀、荊地材至關中，役徒七十萬人。隋煬帝營宮室，近山無大木，皆致之遠方，二千人曳一柱，以木為輪，則戞摩火出，乃鑄鐵為轂，行一二里，轂輒破，別使數百人賫轂，隨而易之，盡日不過行二三十里，計一柱之費，已用數十萬功。大中祥符間，奸佞之臣，罔真宗以符瑞，大興土木之役，以為道宮。玉清昭應之建，丁謂為修宮使，凡役工日至三四萬，所用有秦、隴、岐、同之松，嵐、石、汾、陰之柏，潭、衡、道、永、鼎、吉之梌、柟、櫧，溫、台、衢、吉之檮，永、澧、處之槻、樟，潭、柳、明、越之杉，鄭、淄之青石，衡州之碧石，萊州之白石，絳州之斑石，吳越之奇石，洛水之石卵，宜聖庫之銀朱，桂州之丹砂，河南之赭土，衢州之朱土，梓、信之石青、石綠，磁、相之黛，秦、階之雌黃，廣州之藤黃，孟、澤之槐華，虢州之鉛丹，信州之土黃，河南之胡粉，衞州之白堊，鄆州之蚌粉，兗、澤之墨，歸、歙之漆，萊蕪、興國之鐵。其木石皆遣所在官部兵民入山穀伐取。又於京師置局化銅為鍮、冶金薄、鍛鐵以給用。凡東西三百一十步，南北百四十三步。地多黑土疏惡，於京東北取良土易之，自三尺至一丈有六等。起二年四月，至七年十一月宮成，總二千六百一十區。不及二十年，天火一夕焚爇，但存一殿。是時，役遍天下，而至尊無窮兵黷武、聲色苑囿、嚴刑峻法之舉，故民間樂從，無一違命，視秦、隋二代，萬萬不侔矣。然一時賢識之士，猶為盛世惜之。國史志載其事，欲以為夸，然不若掩之之為愈也。沈括筆談雲：「溫州雁蕩山，前世人所不見。故謝靈運為太守，未嘗遊歷。因昭應宮采木，深入窮山，此境始露於外。」他可知矣。(衞州，一作衡州。)","sortOrder":13},
  {"id":"s_work_dtbt_45_14","chapterId":"ch_work_dtbt_45","text":"歲月日風雷雄雌","sortOrder":14},
  {"id":"s_work_dtbt_45_15","chapterId":"ch_work_dtbt_45","text":"虞喜天文論漢太初曆十一月甲子夜半冬至雲：「歲雄在閼逢，雌在攝提格，月雄在畢，雌在觜，日雄在子。」又雲：「甲歲雄也，畢月雄也，陬月雌也。」大抵以十幹為歲陽，故謂之雄，十二支為歲陰，故謂之雌，但畢、觜為月雄雌不可曉。今之言陰陽者，未嘗用雄雌二字也。郎顗傳引易雌雄祕歷，今亡此書。宋玉風賦有雄風雌風之說。沈約有「雌霓連蜷」之句。春秋元命包曰：「陰陽合而為雷。」師曠占曰：「春雷始起，其音格格，其霹靂者，所謂雄雷，旱氣也。其鳴依依，音不大霹靂者，所謂雌雷，水氣也。」見法苑珠林。予家有故書一種，曰孝經雌雄圖，雲出京房易傳，亦日星占相書也。","sortOrder":15},
  {"id":"s_work_dtbt_45_16","chapterId":"ch_work_dtbt_45","text":"東坡三詩","sortOrder":16},
  {"id":"s_work_dtbt_45_17","chapterId":"ch_work_dtbt_45","text":"東坡初赴惠州，過峽山寺，不值主人，故其詩雲：「山僧本幽獨，乞食况未還。雲碓水自舂，松門風為關。石泉解娛客，琴筑鳴空山。」既至惠州，殘臘獨出，至栖禪寺，亦不逢一僧，故其詩雲：「江邊有微行，詰曲背城市。平湖春草合，步到栖禪寺。堂空不見人，老稚掩關睡。所營在一食，食已寧復事。客行豈無得？施子淨掃地。風松獨不靜，送我作鼓吹。」後在儋耳作觀棋詩，記遊廬山白鶴觀，觀中人皆闔戶晝寢，獨聞棋聲，雲：「五老峯前，白鶴遺址。長松蔭庭，風日清美。我時獨遊，不逢一士。誰歟棋者？戶外屨二。不聞人聲，時聞落子。」其寂寞冷落之味，可以想見，句語之妙，一至於此。","sortOrder":17},
  {"id":"s_work_dtbt_45_18","chapterId":"ch_work_dtbt_45","text":"天文七政","sortOrder":18},
  {"id":"s_work_dtbt_45_19","chapterId":"ch_work_dtbt_45","text":"尚書舜典：「以齊七政。」孔安國本註，謂「日月五星也」。而馬融雲：「七政者北斗七星，各有所主。第一主日；第二主月；第三曰命火，謂熒惑也；第四曰煞土，謂填星也；第五曰代水，謂辰星也；第六曰危木，謂歲星也；第七曰剽金，謂太白也。日月五星各異，故曰七政。」尚書大傳一說，又以為：「七政者，謂春、秋、冬、夏、天文、地理、人道，所以為政也，人道正而萬事順成。」三說不同，然不若孔氏之明白也。","sortOrder":19},
  {"id":"s_work_dtbt_45_20","chapterId":"ch_work_dtbt_45","text":"符讀書城南","sortOrder":20},
  {"id":"s_work_dtbt_45_21","chapterId":"ch_work_dtbt_45","text":"符讀書城南一章，韓文公以訓其子，使之腹有詩、書，致力於學，其意美矣。然所謂「一為公與相，潭潭府中居，不見公與相，起身自犁鋤」等語，乃是覬覦富貴，為可議也。杜牧之寄小侄阿宜詩亦雲：「朝廷用文治，大開官職場。願爾出門去，取官如驅羊。」其意與韓類也。予向為陳鑄作城南堂記，亦及此意雲。","sortOrder":21},
  {"id":"s_work_dtbt_45_22","chapterId":"ch_work_dtbt_45","text":"致仕官上壽","sortOrder":22},
  {"id":"s_work_dtbt_45_23","chapterId":"ch_work_dtbt_45","text":"范蜀公自翰林學士，以本官戶部侍郎致仕，仍居京師，同天節乞隨班上壽，許之。遂著為令。韓康公，元祐二年以司空致仕，太皇太後受冊，乞隨班稱賀，而降詔免赴，二者不同如此。","sortOrder":23},
  {"id":"s_work_dtbt_45_24","chapterId":"ch_work_dtbt_45","text":"五經字義相反","sortOrder":24},
  {"id":"s_work_dtbt_45_25","chapterId":"ch_work_dtbt_45","text":"治之與亂，順之與擾，定之與荒，香之與臭，遂之與潰，皆美惡相對之字。然五經用之或相反，如亂臣十人，亂越我家，惟以亂民，亂為四方新辟，亂為四輔，厥亂明我新造邦，丕乃俾亂之類，以亂訓治也。安擾邦國，擾而毅，擾龍，六擾之類，以擾訓順也。荒度土功，遂荒大東，大王荒之，葛藟荒之之類，以荒訓定也。無聲無臭，胡臭亶時，其臭膻，臭陰達於淵泉之類，以臭訓香也。是用不潰於成，草不潰茂之類，以潰訓遂也。鄭康成箋毛詩潰成，與毛公皆釋為遂，至於潰茂，則以為潰當作彙，彙，茂貌也。自為異同如此。","sortOrder":25},
  {"id":"s_work_dtbt_45_26","chapterId":"ch_work_dtbt_45","text":"鎮星為福","sortOrder":26},
  {"id":"s_work_dtbt_45_27","chapterId":"ch_work_dtbt_45","text":"世之伎術，以五星論命者，大率以火、土為惡，故有晝忌火星夜忌土之語。土，鎮星也，行遲，每至一宮，則二歲四月乃去，以故為災最久。然以國家論之則不然，苻堅欲南伐，歲鎮守斗，識者以為不利。史記天官書雲：「五潢，五帝車舍。火入，旱；金，兵；水，水。」宋均曰：「不言木、土者，德星不為害也。」又雲：「五星犯北落，軍起。火、金、水尤甚。木、土，軍吉。」又雲：「鎮星所居國吉。未當居而居，已去而復，還居之，其國得土。若當居而不居，既已居之，又西東去，其國失土。其居久，其國福厚；其居易，(輕速也。)福薄。」如此則鎮星乃為大福德，與木亡異，豈非國家休祥所係，非民庶可得侔邪？","sortOrder":27},
  {"id":"s_work_dtbt_45_28","chapterId":"ch_work_dtbt_45","text":"東坡引用史傳","sortOrder":28},
  {"id":"s_work_dtbt_45_29","chapterId":"ch_work_dtbt_45","text":"東坡先生作文，引用史傳，必詳述本末，有至百餘字者，蓋欲使讀者一覽而得之，不待復尋繹書策也。如勤上人詩集敍引翟公罷廷尉賓客反覆事，晁君成詩集敍引李郃漢中以星知二使者事，上富丞相書引左史倚相美衞武公事，答李琮書引李固論發兵討交趾事，與朱鄂州書引王濬活巴人生子事，蓋公堂記引曹參治齊事，滕縣公堂記引徐公事，溫公碑引慕容紹宗、李勣事，密州通判題名記引羊叔子、鄒湛事，荔枝嘆詩引唐羌言荔枝事是也。","sortOrder":29},
  {"id":"s_work_dtbt_45_30","chapterId":"ch_work_dtbt_45","text":"兩莫愁","sortOrder":30},
  {"id":"s_work_dtbt_45_31","chapterId":"ch_work_dtbt_45","text":"莫愁者郢州石城人，今郢有莫愁村。畫工傳其貌，好事者多寫寄四遠。唐書樂志曰：「莫愁樂者，出於石城樂，石城有女子名莫愁，善歌謠。」古詞曰「莫愁在何處？莫愁石城西，艇子打兩槳，催送莫愁來」者是也。李義山詩曰：「海外徒聞更九州，他生未卜此生休。空傳虎旅鳴宵柝，無復鷄人送曉籌。此日六軍同駐馬，他時七夕笑牽牛。如何四紀為天子，不及盧家有莫愁？」此莫愁者洛陽人。梁武帝河中之歌曰「河中之水向東流，洛陽女兒名莫愁。莫愁十三能織綺，十四采桑南陌頭，十五嫁為盧家婦，十六生兒似阿侯。盧家蘭室桂為梁，中有鬱金蘇合香，頭上金釵十二行，足下絲履五文章，珊瑚掛鏡爛生光，平頭奴子擎履箱，人生富貴何所望？恨不早嫁東家王」者是也。盧氏之盛如此，所雲「不早嫁東家王」，莫詳其義。近世周美成樂府西河一闋，專詠金陵，所雲「莫愁艇子曾繫」之語，豈非誤指石頭城為石城乎？","sortOrder":31},
  {"id":"s_work_dtbt_45_32","chapterId":"ch_work_dtbt_45","text":"何公橋詩","sortOrder":32},
  {"id":"s_work_dtbt_45_33","chapterId":"ch_work_dtbt_45","text":"英州小市，江水貫其中，舊架木作橋，每不過數年，輒為湍潦所壞。郡守建安何智甫，始叠石為之，方成而東坡還自海外，何求文以紀。坡作四言詩一首，凡五十六句。今載於後集第八卷，所謂「天壤之間，水居其多。人之往來，如鵜在河」是也。予侍親居英，與僧希賜遊南山，步過橋上，讀詩碑。希賜雲：「真本藏於何氏，此有石刻，經黨禁亦不存。」今以板刻之，乃希賜所書也。賜因言何公初請記，坡為賦此詩，既大書矣。而未遣送，郡候兵執役者見之，以告何，何又來謁，坡曰：「軾未到橋所，難以想像落筆。」何即命具食，拉坡偕往。坡曰：「使君是地主，宜先升車。」何謝不敢，乃並轎而行。既至，坡曰：「正堪作詩，晚當奉戒。」抵暮送與之。蓋詩中雲：「我來與公，同載而出。歡呼填道，抱其馬足。」故欲同行，以印此語耳。坡公作詩時，建中靖國元年辛巳。予聞希賜語時，紹興十七年丁卯，相去四十六年。今追憶前事，乃紹熙五年甲寅，又四十七年矣。","sortOrder":33},
  {"id":"s_work_dtbt_45_34","chapterId":"ch_work_dtbt_45","text":"容齋三筆","sortOrder":34},
  {"id":"s_work_dtbt_46_1","chapterId":"ch_work_dtbt_46","text":"卷第十二(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_46_2","chapterId":"ch_work_dtbt_46","text":"眄泰秋娘三女","sortOrder":2},
  {"id":"s_work_dtbt_46_3","chapterId":"ch_work_dtbt_46","text":"白樂天燕子樓詩序雲：「徐州故張尚書，有愛妓曰眄眄，善歌舞，雅多風態。尚書既歿，彭城有舊第，第中有小樓名燕子。眄眄念舊愛而不嫁，居是樓十餘年，幽獨塊然。」白公嘗識之，感舊遊，作二絕句，首章雲：「滿窗明月滿簾霜，被冷燈殘拂臥床。燕子樓中霜月苦，秋來只為一人長。」末章雲：「今春有客洛陽回，曾到尚書冢上來。見說白楊堪作柱，爭教紅粉不成灰。」讀者傷惻。劉夢得泰娘歌雲：「泰娘本韋尚書家主謳者，尚書為吳郡，得之，誨以琵琶，使之歌且舞，攜歸京師。尚書薨，出居民間，為蘄州刺史張愻所得。愻謫居武陵而卒，泰娘無所歸。地荒且遠，無有能知其容與藝者，故日抱樂器而哭。」劉公為歌其事雲：「繁華一旦有消歇，題劍無光履聲絕。蘄州刺史張公子，白馬新到銅駝里。自言買笑擲黃金，月墮雲中從此始。山城少人江水碧，斷雁哀絃風雨夕。朱絃已絕為知音，雲鬢未秋私自惜。舉目風煙非舊時，夢尋歸路多參差。如何將此千行淚，更灑湘江斑竹枝！」杜牧之張好好詩雲：「牧佐故吏部沈公在江西幕，好好年十三，以善歌來樂籍中，隨公移置宣城，後為沈著作所納。見之於洛陽東城，感舊傷懷，題詩以贈曰：君為豫章姝，十三纔有餘。主公再三嘆，謂言天下無。自此每相見，三日已為疏。身外任塵土，尊前極歡娛。飄然集仙客，載以紫雲車。爾來未幾歲，散盡高陽徒。洛城重相見，綽綽為當壚。朋遊今在否，落拓更能無？門館慟哭後，水雲秋景初。洒盡滿襟淚，短歌聊一書。」予謂婦人女子，華落色衰，至於失主無依，如此多矣。是三人者，特見紀於英辭鴻筆，故名傳到今。况於士君子終身不遇而與草木俱腐者，可勝嘆哉！然眄眄節義，非泰娘、好好可及也。(「眄眄」館本作「盼盼」，與香山集合。)","sortOrder":3},
  {"id":"s_work_dtbt_46_4","chapterId":"ch_work_dtbt_46","text":"顏魯公祠堂詩","sortOrder":4},
  {"id":"s_work_dtbt_46_5","chapterId":"ch_work_dtbt_46","text":"予家藏雲林繪監冊，有顏魯公畫像，徐師川題詩曰：「公生開元間，壯及天寶亂。捐軀范陽胡，竟死蔡州叛。其賢似魏徵，天下非貞觀。四帝數十年，一身逢百難。少時讀書史，此事心已斷。老來鬢髮衰，慨嘆功名晚。嗟哉忠義途，捷去不可緩。初無當年悲，只令後世嘆。一朝絕霖雨，南畝常亢旱。小夫計雖得，斯民蓋塗炭。長歌詠君節，千載勇夫愞。敬書子張紳，庶幾古人半。」師川以詩鳴江西，然此篇不為工。嘗記李德遠舉似童敏德遊湖州題公祠堂長句曰：「掛帆一縱疾於鳥，長興夜發吳興曉。杖藜上訪魯公祠，一見目明心皦皦。未說邦人懷使君，且為前古惜忠臣。德宗更用盧杞相，出當斯位誠艱辛。生逆龍鱗死虎口，要與乃兄同不朽。狂童希烈何足罪，奸邪嫉忠假渠手。乃知成仁或殺身，保身不必皆哲人。此公安得世復有，洗空凡馬須騏驎。」童之詩，語意皆超拔，亦臨川人，而終身不得仕，為可惜也！","sortOrder":5},
  {"id":"s_work_dtbt_46_6","chapterId":"ch_work_dtbt_46","text":"閔子不名","sortOrder":6},
  {"id":"s_work_dtbt_46_7","chapterId":"ch_work_dtbt_46","text":"論語所記孔子與人語及門弟子幷對其人問答，皆斥其名，未有稱字者，雖顏、冉高第，亦曰回，曰雍，唯至閔子，獨雲子騫，終此書無損名。昔賢謂論語出於曾子、有子之門人，予意亦出於閔氏。觀所言閔子侍側之辭，與冉有、子貢、子路不同，則可見矣。","sortOrder":7},
  {"id":"s_work_dtbt_46_8","chapterId":"ch_work_dtbt_46","text":"曾晳待子不慈","sortOrder":8},
  {"id":"s_work_dtbt_46_9","chapterId":"ch_work_dtbt_46","text":"傳記所載曾晳待其子參不慈，至雲因鋤菜誤傷瓜，以大杖擊之仆地。孔子謂參不能如虞舜小杖則受，大杖則避，以為陷父於不義，戒門人曰：「參來勿內。」予竊疑無此事，殆戰國時學者妄為之辭。且曾晳與子路、冉有、公西華侍坐，有「浴乎沂，風乎舞雩」之言，涵泳聖教，有超然獨見之妙，於四人之中，獨蒙「吾與」之褒，則其為人之賢可知矣。有子如此，而幾置之死地，庸人且猶不忍，而謂晳為之乎？孟子稱曾子養曾晳酒肉養志，未嘗有此等語也。","sortOrder":9},
  {"id":"s_work_dtbt_46_10","chapterId":"ch_work_dtbt_46","text":"具圓復詩","sortOrder":10},
  {"id":"s_work_dtbt_46_11","chapterId":"ch_work_dtbt_46","text":"吳僧法具，字圓復，有能詩聲，予乃紀之於夷堅志中，殊為不類。比於福州僧智恢處，見其詩藁一紙，字體效王荊公。其送僧一篇雲：「灘聲嘈嘈雜雨聲，舍北舍南春水平。拄杖穿花出門去，五湖風浪白鷗輕。」送翁士特雲：「朝入羊腸暮鹿頭，十三官驛是荊州。具車秣馬曉將發，寒燭燒殘語未休。」竹軒雲：「老竹排簷誰手種，山日未斜寒翠重。六月散髮葉底眠，冷雨斜風頻入夢。冬雕峯木雪縞廬，落眼青青却笑渠。花時吹筍排林上，吳州還見竹溪圖。」和子蒼三馬圖雲：「從來畫馬稱神妙，至今只說江都王。將軍曹霸實季仲，沙苑丞相猶諸郎。龍眠居士善畫馬，獨與二子遙相望。兩馬駢立真驌驦，一馬脫去仍騰驤。浣花老人今已亡，嗚呼三馬誰平章！飽知畫肉亦畫骨，妙處不減黃無雙。」又一篇雲：「燒燈過了客思家，獨立衡門數暝鴉。燕子未歸梅落盡，小窗明月屬梨花。」皆可咀嚼也。吳門僧惟茂，住天台山一禪剎，喜其旦暮見山，作絕句曰：「四面峯巒翠入雲，一溪流水漱山根。老僧只恐山移去，日午先教掩寺門。」甚有詩家風旨，而或者謂山若欲去，豈容人掩住？蓋吳人癡獃習氣也，其說可謂不知音。","sortOrder":11},
  {"id":"s_work_dtbt_46_12","chapterId":"ch_work_dtbt_46","text":"人當知足","sortOrder":12},
  {"id":"s_work_dtbt_46_13","chapterId":"ch_work_dtbt_46","text":"予年過七十，法當致仕，紹熙之末，以新天子臨御，未敢遽有請，故玉隆滿秩，只以本官職居里。鄉袞趙子直不忍使絕祿粟，俾之因任，方用贅食太倉為愧，而親朋謂予爵位不逮二兄，以為耿耿。予誦白樂天初授拾遺詩以語之曰：「奉詔登左掖，束帶參朝議。何言初命卑，且脫風塵吏。杜甫、陳子昂，才名括天地。當時非不遇，尚無過斯位。」其安分知足之意，終身不渝。因略考國朝以來，名卿偉人負一時重望而不躋大用者，如王黃州禹偁，楊文公億，李章武宗諤，張乖崖詠，孫宣公奭，晁少保迥，劉子儀筠，宋景文祁，范蜀公鎮，鄭毅夫獬，滕元發甫，東坡先生，范淳父祖禹，曾子開肇，彭器資汝礪，劉原甫敞，蔡君謨襄，孫莘老覺，近世汪彥章藻，孫仲益覿，諸公皆不過尚書學士，或中年即世，或遷謫留落，或無田以食，或無宅以居，况若我忠宣公者，尚忍言之！則予之忝竊亦已多矣。","sortOrder":13},
  {"id":"s_work_dtbt_46_14","chapterId":"ch_work_dtbt_46","text":"淵明孤松","sortOrder":14},
  {"id":"s_work_dtbt_46_15","chapterId":"ch_work_dtbt_46","text":"淵明詩文率皆紀實，雖寓興花竹間亦然。歸去來辭雲：「景翳翳以將入，撫孤松而盤旋。」其飲酒詩二十首中一篇雲：「青松在東園，衆草沒其姿。凝霜殄異類，卓然見高枝。連林人不覺，獨樹衆乃奇。」所謂孤松者是已，此意蓋以自况也。","sortOrder":15},
  {"id":"s_work_dtbt_46_16","chapterId":"ch_work_dtbt_46","text":"饒州刺史","sortOrder":16},
  {"id":"s_work_dtbt_46_17","chapterId":"ch_work_dtbt_46","text":"饒州良牧守，自吳至今，以政績著者有九賢，郡圃立祠以事，此外知名者蓋鮮。白樂天集有吳府君碑雲：「君諱丹，字真存，以進士第入官。讀書數千卷，著文數萬言。生四五歲，所作戲輒象道家法事。既冠，喜道書，奉真籙，每專氣入靜，不粒食者數歲，飄然有出世心。既壯，在家為長屬，有三幼弟、八稚侄，不忍見其饑寒，慨然有幹祿意。求名得名，家無長物，澹乎自處，與天和始終。享壽命八十二歲，無室家累，無子孫憂，終於饒州。」官次大略如此。吳君在饒，雖無遺事可紀，以其邦君之故，姑志於書。吳為人清淨恬寂，所謂達士，然年過八十尚領郡符，又非為妻子計者，良不可曉。唐之治不播棄黎老，故其居職不自以為過雲。","sortOrder":17},
  {"id":"s_work_dtbt_46_18","chapterId":"ch_work_dtbt_46","text":"紫極觀鐘","sortOrder":18},
  {"id":"s_work_dtbt_46_19","chapterId":"ch_work_dtbt_46","text":"饒州紫極觀有唐鐘一口，形製清堅，非近世工鑄可比。刻銘其上曰：「天寶九載，歲次庚寅，二月庚申朔，十五日癸酉造，通直郎、前監察御史貶樂平員外尉李逢年銘，前鄉貢進士薛彥偉述序，給事郎、行參軍趙從一書，中大夫、使持節鄱陽郡諸軍事、檢校鄱陽郡太守、天水郡開國公上官經野妻扶風郡君韋氏奉為開元天地大寶聖文神武應道皇帝敬造洪鐘一口。」其後列錄事參軍、司功、司法、司士參軍各一人，司戶參軍二人，參軍二人，錄事一人，鄱陽縣令一人、尉二人，又專檢校官、鄱陽縣丞宋守靜，專檢校內供奉道士王朝隱，又道士七人。銘文亦雅潔，字畫不俗，但月朔庚申，則癸酉日當是十四日，鐫之金石而誤如此。浮洲開福院亦有吳武義年一鐘，然非此比也。","sortOrder":19},
  {"id":"s_work_dtbt_46_20","chapterId":"ch_work_dtbt_46","text":"兼中書令","sortOrder":20},
  {"id":"s_work_dtbt_46_21","chapterId":"ch_work_dtbt_46","text":"紹熙五年十二月二十二日，宣麻製除嗣秀王伯圭兼中書令。此官久不除，學士、大夫多不知本末，至或疑為當入都堂治事。邸報至外郡，尤所不曉。邁考之典故，侍中、中書令為兩省長官，自唐以來，居真宰相之位，而中令在侍中上。肅宗以後，始以處大將，故郭子儀、僕固懷恩、朱泚、李晟、韓弘皆為之，其在京則入政事堂，然不預國事。懿、僖、昭之時，員浸多，率由平章事遷兼侍中，繼兼中書令，又遷守中書令，三者均稱使相，皆大敕繫銜而下書使字。五代尤多。國朝創業之初，尚仍舊貫，於是吳越國王錢俶、天雄節度符彥卿、雄武王景、武寧郭從義、保大武行德、成德郭崇、昭義李筠、淮南李重進、永興李洪義、鳳翔王彥超、定難李彝興、荊南高保融、武平周行逢、武寧王晏、武勝侯章、歸義曹元忠十五人同時兼中書令。太宗朝，唯除石守信，而趙普以故相拜。真宗但以處親王。嘉祐末，除宗室東平王允弼、襄陽王允良；元豐中，除曹佾，與允弼、允良相去十七八年，爵秩固存。沈括筆談謂有司以佾新命，言自來不曾有活中書令請俸則例，蓋妄也。官製行，改三使相並為開府儀同三司。元祐以後不復有之，雖崇、觀、政、宣輕用名器，且改為左輔、右弼，然蔡京三為公相，亦不敢居。乾道中，詔於錄黃及告命內除去侍中、中書令，遂廢此官。今當先降指揮復置，則於事體尤愜當也。嗣王終不敢當，於是寢前命，而賜贊拜不名。","sortOrder":21},
  {"id":"s_work_dtbt_46_22","chapterId":"ch_work_dtbt_46","text":"作文字要點檢","sortOrder":22},
  {"id":"s_work_dtbt_46_23","chapterId":"ch_work_dtbt_46","text":"作文字不問工拙小大，要之不可不著意點檢，若一失事體，雖遣詞超卓，亦雲未然。前輩宗工，亦有所不免。歐陽公作仁宗御書飛白記雲：「予將赴亳，假道於汝陰，因得閱書於子履之室。而雲章爛然，輝映日月，為之正冠肅容再拜而後敢仰視，蓋仁宗皇帝之御飛白也。曰，『此寶文閣之所藏也，胡為乎子之室乎？』曰，『曩者天子燕從臣於羣玉，而賜以飛白，予幸得預賜焉。』」烏有記君上宸翰而彼此稱「予」，且呼陸經之字？又登貞觀御書閣記，言太宗飛白，亦自稱「予」。外製集序，歷道慶曆更用大臣，稱呂夷簡、夏竦、韓琦、范仲淹、富弼，皆斥姓名，而曰「顧予何人，亦與其選」，又曰「予時掌誥命」，又曰「予方與修祖宗故事」，凡稱「予」者七。東坡則不然，為王誨亦作此記，其語雲「故太子少傅、安簡王公諱舉正，臣不及見其人矣」雲雲。是之謂知體。","sortOrder":23},
  {"id":"s_work_dtbt_46_24","chapterId":"ch_work_dtbt_46","text":"侍從兩製","sortOrder":24},
  {"id":"s_work_dtbt_46_25","chapterId":"ch_work_dtbt_46","text":"國朝官稱，謂大學士至待製為「侍從」，謂翰林學士、中書舍人為「兩製」，言其掌行內、外製也。舍人官未至者，則雲「知製誥」，故稱美之為三字。謂尚書侍郎為「六部長貳」，謂散騎常侍、給事諫議為「大兩省」。其名稱如此。今盡以在京職事官自尚書至權侍郎及學士、待製均為「侍從」，蓋相承不深考耳。予家藏王（氵公）春秋通義一書，至和元年，鄧州繳進，二年有旨送兩製看詳，於是具奏者十二人皆列名銜：學士七人，曰學士承旨、禮部侍郎楊察，翰林學士、中書舍人趙槩、楊偉，刑部郎中胡宿，吏部郎中歐陽修，起居舍人呂溱，禮部郎中王洙；知製誥五人，曰起居舍人王珪，右司諫賈黯，兵部員外郎韓絳，起居舍人吳奎，右正言劉敞。而他官弗預，此可見也。翰林本以六員為額，劉沆作相，典領溫成後喪事，以王洙同其越禮建明，於是員外用之，嘗為一時言者所論，正此時雲。","sortOrder":25},
  {"id":"s_work_dtbt_46_26","chapterId":"ch_work_dtbt_46","text":"片言解禍","sortOrder":26},
  {"id":"s_work_dtbt_46_27","chapterId":"ch_work_dtbt_46","text":"自古將相大臣，遭罹譖毀，觸君之怒，墮身於危棘將死之域，而以一人片言，轉禍為福，蓋投機中的，使聞之者曉然易寤，然非遭值明主，不能也。蕭何為民請上林苑中空地，高祖大怒，以為多受賈人財物，下何廷尉，械繫之。王衞尉曰：「陛下距楚數歲，陳豨、黥布反，時相國守關中，不以此時為利，乃利賈人之金乎？」上不懌，即日赦出何。絳侯周勃免相就國，人上書告勃欲反，廷尉逮捕勃治之。薄太後謂文帝曰：「絳侯綰皇帝璽，將兵於北軍，不以此時反，今居一小縣，顧欲反邪？」帝即赦勃。此二者，可謂至危不容救，而於立談間見效如此。蕭望之受遺輔政，為許、史、恭、顯所嫉，奏望之與周堪、劉更生朋黨，請「召致廷尉」，元帝不省為下獄也，可其奏。已而悟其非，令出視事。史高言：「上新即位，未以德化聞於天下，而先驗師傅，既下九卿大夫獄，宜因決免。」於是免為庶人。高祖、文帝之明而受言，元帝之昏而遂非，於是可見。","sortOrder":27},
  {"id":"s_work_dtbt_46_28","chapterId":"ch_work_dtbt_46","text":"忠言嘉謨","sortOrder":28},
  {"id":"s_work_dtbt_46_29","chapterId":"ch_work_dtbt_46","text":"揚子法言：「或問忠言嘉謨，曰言合稷、契謂之忠，謨合皋陶謂之嘉。」如子雲之說，則言之與謨，忠之與嘉，分而為二，傳註者皆未嘗為之辭，然則稷、契不能嘉謨，皋陶不能忠言乎？三聖賢遺語可傳於後世者，唯虞書存，五篇之中，皋陶矢謨多矣，稷與契初無一話一言可考，不知子雲何以立此論乎？不若魏鄭公但雲「良臣稷、契、皋陶」，乃為通論。","sortOrder":29},
  {"id":"s_work_dtbt_46_30","chapterId":"ch_work_dtbt_46","text":"免直學士院","sortOrder":30},
  {"id":"s_work_dtbt_46_31","chapterId":"ch_work_dtbt_46","text":"慶元元年正月一日，鄭湜以起居郎直學士院。二月二十三日，趙汝愚罷相，製乃湜所草，議者指為褒詞太過。二十五日，有旨免兼直院，或以為故事所無。按熙寧初，王益柔以知製誥兼直學士院，嘗奏中書熟狀加董氈階官之誤，宰相怒其不申堂，用他事罷其兼直，已而遷龍圖閣直學士。湜亦以罷直求去，不許，越三月而遷權刑部侍郎，甚相類也。","sortOrder":31},
  {"id":"s_work_dtbt_46_32","chapterId":"ch_work_dtbt_46","text":"大賢之後","sortOrder":32},
  {"id":"s_work_dtbt_46_33","chapterId":"ch_work_dtbt_46","text":"杜詩雲：「大賢之後竟陵遲，蕩蕩古今同一體。」乃贈狄梁公曾孫者，至雲「飄泊岷漢，幹謁王侯」，則其衰微可知矣。近見餘幹寓客李氏子雲，本朝三李相，文正公昉、文靖公沆、文定公迪皆一時名宰，子孫亦相繼達宦。然數世之後益為蕭條，又經南渡之厄，今三裔並居餘幹，無一人在仕版。文定濮州之族，今有居越者，雖曰不顯，猶簪纓僅傳，而文正、文靖無聞，可為太息！","sortOrder":33},
  {"id":"s_work_dtbt_46_34","chapterId":"ch_work_dtbt_46","text":"容齋三筆","sortOrder":34},
  {"id":"s_work_dtbt_47_1","chapterId":"ch_work_dtbt_47","text":"卷第十三(十三則)","sortOrder":1},
  {"id":"s_work_dtbt_47_2","chapterId":"ch_work_dtbt_47","text":"鐘鼎銘識","sortOrder":2},
  {"id":"s_work_dtbt_47_3","chapterId":"ch_work_dtbt_47","text":"三代鐘鼎彝器存於今者，其間款識，唯「眉壽萬年」，「子子孫孫永寶用」之語，差可辨認，餘皆茫昧不可讀，談者以為古文質朴固如此，予竊有疑焉。商、周文章，見於詩、書，三盤五誥，雖詰曲聱牙，尚可精求其義，他皆坦然明白，如與人言。自武王丹書諸銘外，其見於經傳者，如湯之盤銘曰：「苟日新，日日新，又日新。」讒鼎之銘曰：「昧旦丕顯，後世猶怠。」正考父鼎銘曰：「一命而僂，再命而傴，三命而俯，循牆而走，亦莫餘敢侮。饘於是，鬻於是，以餬餘口。」（上卥下木）氏量銘曰：「時文思索，允臻其極。嘉量既成，以觀四國。永啟厥後，茲器維則。」祭射侯辭曰：「惟若寧侯，毋或若女不寧侯，不屬於王所，故抗而射女。」衞禮至銘曰：「餘掖殺國子，莫餘敢止。」孔悝鼎銘曰：「六月丁亥，公假於太廟。公曰叔舅，乃祖莊叔，左右成公，成公乃命莊叔，隨難於漢陽，即宮於宗周，奔走無射，啟右獻公，獻公乃命成叔，纂乃祖服。乃考文叔，興舊嗜欲，作率慶士，躬恤衞國，其勤公家，夙夜不解，民鹹曰休哉！公曰叔舅，予女銘，若纂乃考服。悝拜稽首曰：對揚以辟之勤大命，施於烝彝鼎。」扶風美陽鼎銘曰：「王命尸臣，官此栒邑，賜爾旂鸞，黼黻琱戈。尸臣拜手稽首曰：敢對揚天子丕顯休命。」此諸銘未嘗不粲然，何為傳於今者，艱（澀去氵）無緒乃爾。漢去周未遠，武、宣以來，郡國每獲一鼎，至於薦告宗廟，羣臣上壽。竇憲出征，南單於遺以古鼎，容五斗，其銘曰：「仲山甫鼎，其萬年子子孫孫永保用。」憲乃上之，蓋以其難得故也。今世去漢千年，而器寶之出不可勝計，又為不可曉已。武帝獲汾陰脽上鼎，無款識，而備禮迎享，宣帝獲美陽鼎，下羣臣議，張敞乃以有款識之故絀之，又何也？","sortOrder":3},
  {"id":"s_work_dtbt_47_4","chapterId":"ch_work_dtbt_47","text":"犧尊象尊","sortOrder":4},
  {"id":"s_work_dtbt_47_5","chapterId":"ch_work_dtbt_47","text":"周禮司尊彝：「祼用鷄彝、鳥彝，其朝獻用兩獻尊，其再獻用兩象尊。」漢儒註曰：「鷄彝、鳥彝，謂刻而畫之為鷄、鳳凰之形。獻讀為犧，犧尊飾以翡翠，象尊以象鳳凰。或曰：以象骨飾尊。又雲：獻音娑，有婆娑之義。」惟王肅雲：「犧、象二尊，並全牛、象之形，而鑿背為尊。」陸德明釋周禮獻尊之獻，音素何反。而於左氏傳「犧象不出門」，釋犧為許宜反，又素何反。予按今世所存故物，宣和博古圖所寫，犧尊純為牛形，象尊純為象形，而尊在背，正合王肅之說。然則犧字只當讀如本音，鄭司農諸人所雲，殊與古製不類。則知目所未覩而臆為之說者，何止此哉！又今所用爵，除太常禮器之外，郡縣至以木刻一雀，別置杯於背以承酒，不復有兩柱、三足、隻耳、侈口之狀，向在福州見之，尤為可笑也。","sortOrder":5},
  {"id":"s_work_dtbt_47_6","chapterId":"ch_work_dtbt_47","text":"再書博古圖","sortOrder":6},
  {"id":"s_work_dtbt_47_7","chapterId":"ch_work_dtbt_47","text":"予昔年因得漢匜，讀博古圖，嘗載其序述可笑者數事於隨筆，近復盡觀之，其謬妄不可殫舉。當政和、宣和間，蔡京為政，禁士大夫不得讀史，而春秋三傳，真束高閣，故其所引用，絕為乖盾。今一切記之於下，以示好事君子與我同志者。商之癸鼎，只一「癸」字，釋之曰：「湯之父主癸也。」父癸尊之說亦然。至父癸匜，則又以為齊癸公之子。乙鼎銘有「乙毛」兩字，釋之曰：「商有天乙、祖乙、小乙、武乙，太丁之子乙，今銘『乙』，則太丁之子也。」父己鼎曰：「父己者，雍己也。繼雍己者乃其弟太戊，豈非繼其後者乃為之子邪？」至父己尊，則直雲「雍己之子太戊為其父作」。予按以十幹為名，商人無貴賤皆同，而必以為君，所謂「癸」即父癸，「己」即雍己，是六七百年中更無一人同之者矣。商公非鼎銘只一字曰「非」，釋之曰：「據史記有非子者，為周孝王主馬，其去商遠甚。惟公劉五世孫曰公非，考其時當為公非也。」夫以一「非」字，而必強推古人以證之，可謂無理。周益鼎曰：「春秋文公六年有梁氏益，昭公六年有文公益，未知孰是？」予按左傳文八年所紀，乃梁益耳，而杞文公名益姑。周絲駒父鼎曰：「左傳有駒伯，為郤克軍佐，駒其姓也。此曰駒父，其同駒伯為姓邪？」予按左傳，駒伯者郤錡也，錡乃克之子。是時郤氏三卿，錡曰駒伯，犨曰苦成叔，至曰溫季，皆其食采邑名耳，豈得以為姓哉？叔液鼎曰：「考諸前代，叔液之名不見於經傳，惟周八士有叔夜，豈其族歟？」夫伯仲叔季，為兄弟之稱，古人皆然，而必指為叔夜之族，是以「叔」為氏也。周州卣曰：「『州』出於來國，後以『州』為氏。在晉則大夫州綽，在衞則大夫州吁，其為氏則一耳。」予按來國之名無所著見，而州吁乃衞公子，正不讀春秋，豈不知衞詩國風乎？遂以為氏，尤可哂也。周高克尊曰：「高克者，不見於他傳，惟周末衞文公時，有高克將兵，疑克者乃斯人，蓋衞物也。」予按元銘文但雲「伯克」，初無「高」字，高克鄭清人之詩，兒童能誦之，乃以為衞文公時，又言周末，此書局學士，蓋不曾讀毛詩也。周毀敦曰：「銘雲伯和父，和者衞武公也。武公平戎有功，故周平王命之為公。」予按一時列國，雖子男之微，未有不稱公者，安得平王獨命衞武之事？周慧季鬲曰：「慧與惠通，春秋有惠伯、惠叔，虢薑敦有惠仲，而此鬲名之為惠季，豈非惠為氏，而伯仲叔季者乃其序邪？」予按惠伯、惠叔，正與莊伯、戴伯、平仲、敬仲、武叔、穆叔、成季相類，皆上為謚而下為字，烏得以為氏哉？齊侯鎛鐘銘雲：「鹹有九州，處禹之都。」釋之曰：「齊之封域，有臨淄、東萊、北海、高密、膠東、泰山、樂安、濟南、平原，蓋九州也。」予按銘語正謂禹九州耳，今所指言郡名，周世未有，豈得便以為州乎？宋公（音巠）鐘銘曰：「宋公成之（音巠）鐘。」釋之曰：「宋自微子有國二十世，而有共公固成，又一世而有平公成，又七世而有剔公成，未知孰是？」予按宋共公名，史記以為瑕，春秋以為固，初無曰「固成」者。且父既名「成」，而其子復名之可乎？剔成君為弟偃所逐，亦非名「成」也。周雲雷磬曰：「春秋魯饑，臧文仲以玉磬告糴於齊。」按經所書，但雲「臧孫辰告糴於齊」，左傳亦無玉磬之說。漢定陶鼎曰：「漢初有天下，以定陶之地封彭越為梁王，越既叛命，乃以封高祖之子恢，是為定陶共王。」予按恢正封梁王，後徙趙。所謂定陶共王者，元帝之子、哀帝之父名康者也。","sortOrder":7},
  {"id":"s_work_dtbt_47_8","chapterId":"ch_work_dtbt_47","text":"碌碌七字","sortOrder":8},
  {"id":"s_work_dtbt_47_9","chapterId":"ch_work_dtbt_47","text":"今人用碌碌字，本出老子雲：「不欲碌碌如玉，落落如石。」孫愐唐韻引此句及王弼別本以為琭琭，然又為錄錄、娽娽、鹿鹿、陸陸、祿祿凡七字。史記：「毛遂雲：『公等錄錄，因人成事。』」唐韻以為娽娽。漢書蕭何贊雲：「錄錄未有奇節。」顏師古註：「錄錄猶鹿鹿，言在凡庶之中也。」馬援傳：「今更共陸陸。」莊子漁父篇：「祿祿而受變於俗。」後生或不盡知。","sortOrder":9},
  {"id":"s_work_dtbt_47_10","chapterId":"ch_work_dtbt_47","text":"占測天星","sortOrder":10},
  {"id":"s_work_dtbt_47_11","chapterId":"ch_work_dtbt_47","text":"國朝星官曆翁之伎，殊愧漢、唐，故其占測荒茫，幾於可笑。偶讀四朝史天文志雲：「元祐八年十月戊申，星出東壁西，慢流至羽林軍沒。主擢用文士，賢臣在位。」「紹聖元年二月丙午，星出壁東，慢流入濁沒。主天下文章士登用，賢臣在位。」「元符元年六月癸巳，星出室，至壁東沒。主文士入國，賢臣用。」「二年二月癸卯，星出靈臺，北行至軒轅沒。主賢臣在位，天子有子孫之喜。」按是時宣仁上仙，國是丕變，一時正人以次竄斥，章子厚在相位，蔡卞輔之，所謂四星之占，豈不可笑也！子孫之說，蓋陰諂劉後雲。","sortOrder":11},
  {"id":"s_work_dtbt_47_12","chapterId":"ch_work_dtbt_47","text":"政和宮室","sortOrder":12},
  {"id":"s_work_dtbt_47_13","chapterId":"ch_work_dtbt_47","text":"自漢以來，宮室土木之盛，如漢武之甘泉、建章，陳後主之臨春、結綺，隋煬帝之洛陽、江都，唐明皇之華清、連昌，已載史策。國朝祥符中，奸臣導諛，為玉清昭應、會靈、祥源諸宮，議者固以崇侈勞費為戒，然未有若政和蔡京所為也。京既固位，竊國政，招大璫童貫、楊戩、賈詳、藍從熙、何訢五人，分任其事。於是始作延福宮，有穆清、成平、會寧、睿謨、凝和、崑玉、羣玉七殿，東邊有蕙馥、報瓊、蟠桃、春錦、疊瓊、芬芳、麗玉、寒香、拂雲、偃蓋、翠葆、鉛英、雲錦、蘭薰、摘金十五閣，西邊有繁英、雪香、披芳、鉛華、瓊華、文綺、絳萼、穠華、綠綺、瑤碧、清音、秋香、叢玉、扶玉、絳雲，亦十五閣。又疊石為山，建明春閣，其高十一丈，宴春閣廣十二丈。鑿圓池為海，橫四百尺，縱二百六十七尺。鶴莊、鹿砦、孔翠諸柵，蹄尾以數千計。五人者各自為製度，不相沿襲，爭以華靡相誇勝，故名「延福五位」。其後復營萬歲山、艮嶽山，周十餘里，最高一峯九十尺，亭堂樓館不可殫記。徽宗初亦喜之，已而悟其過，有厭惡語，由是力役稍息。靖康遭變，詔取山禽水鳥十餘萬投諸汴渠，拆屋為薪，翦石為砲，伐竹為笓籬，大鹿數千頭，悉殺之以啗衞士。","sortOrder":13},
  {"id":"s_work_dtbt_47_14","chapterId":"ch_work_dtbt_47","text":"僧官試卿","sortOrder":14},
  {"id":"s_work_dtbt_47_15","chapterId":"ch_work_dtbt_47","text":"唐代宗以胡僧不空為鴻臚卿、開府儀同三司，予已論之矣。自其後習以為常，至本朝尚爾。元豐三年，詳定官製所言，譯經僧官，有授試光祿鴻臚卿、少卿者，請自今試卿者，改賜三藏大法師，試少卿者，賜三藏法師。詔試卿改賜六字法師，少卿四字，並冠以譯經三藏。久之復罷。","sortOrder":15},
  {"id":"s_work_dtbt_47_16","chapterId":"ch_work_dtbt_47","text":"大觀算學","sortOrder":16},
  {"id":"s_work_dtbt_47_17","chapterId":"ch_work_dtbt_47","text":"大觀中，置算學如庠序之製，三年三月，詔以文宣王為先師，兗、鄒、荊三國公配饗，十哲從祀，而列自昔著名算數之人，繪像於兩廊，加賜五等之爵。於是中書舍人張邦昌定其名，風後、大橈、隸首、容成、箕子、商高、常僕、鬼臾區、巫鹹九人封公，史蘇、卜徒父、卜偃、梓慎、卜楚丘、史趙、史墨、裨竈、榮方、甘德、石申、鮮於妄人、耿壽昌、夏侯勝、京房、翼奉、李尋、張衡、周興、單颺、樊英、郭璞、何承天、宋景業、蕭吉、臨孝恭、張曾元、王朴二十八人封伯，鄧平、劉洪、管輅、趙達、祖沖之、殷紹、信都芳、許遵、耿詢、劉焯、劉炫、傅仁均、王孝通、瞿曇羅、李淳風、王希明、李鼎祚、邊岡、郎顗、襄楷二十人封子，司馬季主、洛下閎、嚴君平、劉徽、薑岌、張立建、夏侯陽、甄鸞、盧太翼九人封男。考其所條具，固有於傳記無聞者，而高下等差，殊為乖謬。如司馬季主、嚴君平止於男爵，鮮於妄人、洛下閎同定太初曆，而妄人封伯，下閎封男，尤可笑也。十一月又改以黃帝為先師雲。","sortOrder":17},
  {"id":"s_work_dtbt_47_18","chapterId":"ch_work_dtbt_47","text":"十八鼎","sortOrder":18},
  {"id":"s_work_dtbt_47_19","chapterId":"ch_work_dtbt_47","text":"夏禹鑄九鼎，唯見於左傳王孫滿對楚子，及靈王欲求鼎之言，其後史記乃有鼎震及淪入於泗水之說。且以秦之強暴，視衰周如機上肉，何所畏而不取？周亦何辭以却？赧王之亡，盡以寶器入秦，而獨遺此，以神器如是之重，決無淪沒之理。泗水不在周境內，使何人般舁而往，寧無一人知之以告秦邪？始皇使人沒水求之不獲，蓋亦為傳聞所誤。三禮經所載鐘彝名數詳矣，獨未嘗一及之。詩、易所書，固亦可考，以予揣之，未必有是物也。唐武後始復置於通天宮，不知何時而毀。國朝崇寧三年，用方士魏漢津言鑄鼎，四年三月成，於中太一宮之南為殿，名曰九成宮。中央曰帝鼐，北方曰寶鼎，東北曰牡鼎，東方曰蒼鼎，東南曰罔鼎，南方曰彤鼎，西南曰阜鼎，西方曰晶鼎，西北曰魁鼎。奉安之日，以蔡京為定鼎禮儀使。大觀三年，又以鑄鼎之地作寶成宮。政和六年，復用方士王仔昔議，建閣於天章閣西，徙鼎奉安。改帝鼐為隆鼐，餘八鼎皆改焉，名閣曰圓象徽調閣。七年，又鑄神霄九鼎，一曰太極飛雲洞劫之鼎，二曰蒼壺祀天貯醇之鼎，三曰山嶽五神之鼎，四曰精明洞淵之鼎，五曰天地陰陽之鼎，六曰混沌之鼎，七曰浮光洞天之鼎，八曰靈光晃曜鍊神之鼎，九曰蒼龜大蛇蟲魚金輪之鼎。明年鼎成，置於上清寶籙宮神霄殿，遂為十八鼎。繼又詔罷九鼎新名，悉復其舊。今人但知有九鼎，而十八之數，唯朱忠靖公秀水閑居錄略紀之，故詳載於此。","sortOrder":19},
  {"id":"s_work_dtbt_47_20","chapterId":"ch_work_dtbt_47","text":"四朝史志","sortOrder":20},
  {"id":"s_work_dtbt_47_21","chapterId":"ch_work_dtbt_47","text":"四朝國史本紀，皆邁為編修官日所作，至於淳熙乙巳、丙午，又成列傳百三十五卷。惟志二百卷，多出李燾之手，其彙次整理，殊為有功，然亦時有失點檢處。蓋文書廣博，於理固然。職官志雲：「使相以待勛賢故老，及宰相久次罷政者，惟趙普得之。明道末，呂夷簡罷，始復加使相，其後王欽若罷日亦除，遂以為例。」按趙普之後，寇準、陳堯叟、王欽若，皆祥符間自樞密使罷而得之。欽若以天聖初再入相，終於位，夷簡乃在其後十餘年。今言欽若用夷簡故事，則非也。因記新唐書所載：「李泌相德宗，加崇文館大學士。泌建言，學士加大，始中宗時，及張說為之，固辭。乃以學士知院事。至崔圓復為大學士，亦引泌為讓而止。」按崔圓乃肅宗朝宰相，泌之相也，相去三十年，反以為圓引泌為讓，甚類前失也。","sortOrder":21},
  {"id":"s_work_dtbt_47_22","chapterId":"ch_work_dtbt_47","text":"宗室參選","sortOrder":22},
  {"id":"s_work_dtbt_47_23","chapterId":"ch_work_dtbt_47","text":"吏部員多闕少，今為益甚，而選人當註職官簿尉，輒為宗室所奪，蓋以盡壓已到部人之故。按宣和七年八月，臣僚論：「祖宗時宗室無參選法，至崇寧初，大啟僥倖，遂使任意出官，又優為之法，參選一日，即在闔選名次之上。以天支之貴，其間不為無人，而膏粱之習，貪淫縱恣，出為民害者不少。議者頗欲懲革，罷百十人之私恩，為億萬人之公利，誠為至當。若以親愛未忍，姑乞與在部人通理名次。」從之。靖康元年八月，又奏雲：「祖宗時，未有宗室參部之法，神宗時，始選擇差註一二。崇寧初，立法太優，宗室參選之日，在本部名次之上，既壓年月深遠、勞效顯著之人，復占名州大縣、優便豐厚之處。議者頗欲懲革，不註郡守、縣令，與在部人通理名次。」有旨從之。此二段元未嘗衝改，不知何時復紊也。","sortOrder":23},
  {"id":"s_work_dtbt_47_24","chapterId":"ch_work_dtbt_47","text":"元豐庫","sortOrder":24},
  {"id":"s_work_dtbt_47_25","chapterId":"ch_work_dtbt_47","text":"神宗常憤北狄倔強，慨然有恢復幽燕之志，於內帑置庫，自製四言詩曰：「五季失圖，獫玁孔熾。藝祖造邦，思有懲艾。爰設內府，基以募士。曾孫保之，敢忘厥志！」凡三十二庫，每庫以一字揭之，儲積皆滿。又別置庫，賦詩二十字，分揭於上曰：「每虔夕惕心，妄意遵遺業。顧予不武資，何日成戎捷。」其用志如此，國家帑藏之富可知。熙寧元年，以奉宸庫珠子付河北緣邊，於四榷場鬻錢銀，準備買馬，其數至於二千三百四十三萬顆。乾道以來，有封樁、南庫所貯金銀楮券，合為四千萬緡，孝宗尤所垂意。入紹熙以來，頗供好賜之用，似聞日減於舊雲。","sortOrder":25},
  {"id":"s_work_dtbt_47_26","chapterId":"ch_work_dtbt_47","text":"五俗字","sortOrder":26},
  {"id":"s_work_dtbt_47_27","chapterId":"ch_work_dtbt_47","text":"書字有俗體，一律不可復改者，如沖、涼、況、減、決五字，悉以水為冫，(筆陵切，與「冰」同。)雖士人札翰亦然。玉篇正收入於水部中，而冫部之末亦存之，而皆註雲「俗」，乃知由來久矣。唐張參五經文字，亦以為訛。","sortOrder":27},
  {"id":"s_work_dtbt_47_28","chapterId":"ch_work_dtbt_47","text":"容齋三筆","sortOrder":28},
  {"id":"s_work_dtbt_48_1","chapterId":"ch_work_dtbt_48","text":"卷第十四(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_48_2","chapterId":"ch_work_dtbt_48","text":"三教論衡","sortOrder":2},
  {"id":"s_work_dtbt_48_3","chapterId":"ch_work_dtbt_48","text":"唐德宗以誕日歲歲詔佛、老者大論麟德殿，幷召給事中徐岱及趙需、許孟容、韋渠牟講說。始三家若矛盾，然卒而同歸於善，帝大悅，賚予有差。此新書列傳所載也。白樂天集有三教論衡一篇雲：「太和元年十月，皇帝降誕日，奉敕召入麟德殿內道場對御三教談論，略錄大端。第一座：祕書監白居易，安國寺引駕沙門義林，太清宮道士楊弘元。」其序曰：「談論之先，多陳三教，讚揚演說，以啟談端。臣學淺才微，猥登講座。竊以義林法師明大小乘，通內外學，於大衆中能師子吼。臣稽先王典籍，假陛下威靈，發問既來，敢不響答。」然予觀義林所問，首以毛詩稱六義，論語列四科，請備陳名數而已。居易對以孔門之徒三千，其賢者列為四科，毛詩之篇三百，其要者分為六義。然後言六義之數，四科之目，十哲之名。復引佛法比方，以六義可比十二部經，四科可比六度，以十哲可比十大弟子。僧難雲：「曾參至孝，百行之先，何故不列於四科？」居易又為辯析，乃曰：「儒書奧義，既已討論，釋典微言，亦宜發問。」然所問者不過芥子納須彌山一節而已。後問道士黃庭經中養氣存神長生久視之道，道士却問敬一人而千萬人悅。觀其問答旨意，初非幽深微妙，不可測知，唐帝歲以此為誕日上儀，殊為可省。國朝命僧升座祝聖，蓋本於此。","sortOrder":3},
  {"id":"s_work_dtbt_48_4","chapterId":"ch_work_dtbt_48","text":"夫兄為公","sortOrder":4},
  {"id":"s_work_dtbt_48_5","chapterId":"ch_work_dtbt_48","text":"婦人呼夫之兄為伯，於書無所載。予頃使金國時，辟景孫弟輔行，弟婦在家，許齋醮及還家賽願。予為作青詞雲：「頃因兄伯出使，夫貋從行。」雖借用陳平傳「兄伯」之語，而自不以為然。偶憶爾雅釋親篇曰：「婦稱夫之兄為兄公，夫之弟為叔。」於是改兄伯字為兄公，視前所用，大為不侔矣。玉篇妐字音鐘，註雲：「夫之兄也。」然於義訓不若前語。","sortOrder":5},
  {"id":"s_work_dtbt_48_6","chapterId":"ch_work_dtbt_48","text":"政和文忌","sortOrder":6},
  {"id":"s_work_dtbt_48_7","chapterId":"ch_work_dtbt_48","text":"蔡京顓國，以學校科舉箝製多士，而為之鷹犬者，又從而羽翼之。士子程文，一言一字稍涉疑忌，必暗黜之。有鮑輝卿者言：「今州縣學考試，未校文學精弱，先問時忌有無，苟語涉時忌，雖甚工不敢取。若曰：『休兵以息民，節用以豐財，罷不急之役，清入仕之流。』諸如此語，熙、豐、紹聖間，試者共用不以為忌，今悉絀之，所宜禁止。」詔可。政和三年，臣僚又言：「比者試文，有以聖經之言輒為時忌而避之者，如曰『大哉堯之為君』，『君哉舜也』，與夫『製治於未亂，保邦於未危』，『吉凶悔吝生乎動』，『吉凶與民同患』。以為『哉』音與『灾』同，而危亂凶悔非人樂聞，皆避。今當不諱之朝，豈宜有此？」詔禁之。以二者之言考之，知當時試文無辜而坐黜者多矣，其事載於四朝志。","sortOrder":7},
  {"id":"s_work_dtbt_48_8","chapterId":"ch_work_dtbt_48","text":"瞬息須臾","sortOrder":8},
  {"id":"s_work_dtbt_48_9","chapterId":"ch_work_dtbt_48","text":"瞬息、須臾、頃刻，皆不久之辭，與釋氏「一彈指間」，「一剎那頃」之義同，而釋書分別甚備。新婆沙論雲：「百二十剎那，成一怛剎那，六十怛剎那，成一臘縛，二十臘縛，成一牟呼麥多，三十牟呼麥多，成一晝夜。」又毗曇論雲：「一剎那者翻為一念，一怛剎那翻為一瞬，六十怛剎那為一息，一息為一羅婆，三十羅婆為一摩睺羅，翻為一須臾。」又僧祗律雲：「二十念為一瞬，二十瞬名一彈指，二十彈指名一羅預，二十羅預名一須臾，一日一夜有三十須臾。」","sortOrder":9},
  {"id":"s_work_dtbt_48_10","chapterId":"ch_work_dtbt_48","text":"神宗待文武臣","sortOrder":10},
  {"id":"s_work_dtbt_48_11","chapterId":"ch_work_dtbt_48","text":"元豐三年，詔知州軍不應舉京官職官者，許通判舉之。蓋諸州守臣有以小使臣為之，而通判官入京朝，故許之薦舉。今以小使臣守沿邊小郡，而公然薦人改官，蓋有司不舉行故事也。神宗初即位，以刑部郎中劉述，(今朝散大夫。)久不磨勘，特命為吏部郎中。(今朝請大夫。)樞密院言：「左藏庫副使陳昉恬靜，久應磨勘，不肯自言。」帝曰：「右職若效朝士養名，而獎進之，則將習以為高，非便也。」翌日以兵部員外郎張問，(今朝請郎。)十年不磨勘，特遷禮部郎中。(今朝奉大夫。)其旌賞駕御，各自有宜，此所以為綜核名實之善政。(見四朝志。)","sortOrder":11},
  {"id":"s_work_dtbt_48_12","chapterId":"ch_work_dtbt_48","text":"綠竹王芻","sortOrder":12},
  {"id":"s_work_dtbt_48_13","chapterId":"ch_work_dtbt_48","text":"隨筆中載：「毛公釋綠竹王芻，以為北人不見竹，故分綠竹為二物，以綠為王芻。」熙寧初，右贊善大夫吳安度試舍人院，已入等。有司以安度所賦綠竹詩，背王芻古說，而直以為竹，遂黜不取。富韓公為相，言：「史記敍載淇園之竹，正衞產也，安度語有據。」遂賜進士出身。予又記前賢所紀，仁宗時，賈邊試當仁不避於師論，以師為衆，謂其背先儒訓釋，特黜之。蓋是時士風淳厚，論者皆不喜新奇之說，非若王氏之學也。","sortOrder":13},
  {"id":"s_work_dtbt_48_14","chapterId":"ch_work_dtbt_48","text":"親除諫官","sortOrder":14},
  {"id":"s_work_dtbt_48_15","chapterId":"ch_work_dtbt_48","text":"仁宗慶曆三年，用歐陽修、餘靖、王素為諫官，當時名士作詩，有「御筆新除三諫官」之句。元豐八年，詔范純仁為諫議大夫，唐淑問、蘇轍為司諫，朱光庭、范祖禹為正言。宣仁後問宰執，此五人者如何？僉曰：「外望惟允。」章子厚獨曰：「故事，諫官皆薦諸侍從，然後大臣稟奏。今詔除出中，得無有近習援引乎？此門寖不可啟。」後曰：「大臣實皆言之，非左右也。」子厚曰：「大臣當明揚，何為密薦？」由是有以親嫌自言者，呂公著以范祖禹，韓縝、司馬光以范純仁。子厚曰：「臺諫所以糾大臣之越法者，故事，執政初除，苟有親戚及嘗被薦引者，見為臺臣，則皆他徙。今天子幼沖，太皇同聽萬幾，故事不可違。」光曰：「純仁、祖禹實宜在諫列，不可以臣故妨賢，寧臣避位。」子厚曰：「縝、光、公著必不私，他日有懷奸當國者，例此而引其親黨，恐非國之福。」後改除純仁待製，祖禹著作佐郎，然此製亦不能常常恪守也。","sortOrder":15},
  {"id":"s_work_dtbt_48_16","chapterId":"ch_work_dtbt_48","text":"檢放灾傷","sortOrder":16},
  {"id":"s_work_dtbt_48_17","chapterId":"ch_work_dtbt_48","text":"水旱醔傷，農民陳訴，郡縣不能體朝廷德意。或慮減放苗米，則額外加耗之入為之有虧，故往往從窄。比年以來，但有因賑濟虛數而冒賞者，至於蠲租失實，於民不便者，未嘗小懲。宣和之世，執政不能盡賢，而其所施行，蓋猶慰人心。京西運判李祜奏：「房州民數百人，陳言灾傷。知州李悝，取其為首者，杖而徇之城市，以戒妄訴，用此其州蠲稅不及一釐。」詔：「李悝除名，簽書官皆勒停。」祜又奏：「唐、鄧州蠲灾賑乏，悉如法令，均、房州不盡減稅，致有盜賊。」詔：「均、房州守令悉罷，唐、鄧守貳各增一官秩。」百姓見憂，出於徽宗聖意，而大臣能將順也。","sortOrder":17},
  {"id":"s_work_dtbt_48_18","chapterId":"ch_work_dtbt_48","text":"檀弓註文","sortOrder":18},
  {"id":"s_work_dtbt_48_19","chapterId":"ch_work_dtbt_48","text":"檀弓上下篇，皆孔門高第弟子在戰國之前所論次。其文章雄健精工，雖楚、漢間諸人不能及也。而鄭康成所註，又特為簡當，旨意出於言外，今載其兩章以示同志。「衞司寇惠子之喪，子遊為之麻衰，牡麻絰。」註雲：「惠子廢適立庶，為之重服以譏之。」「文子辭曰：子辱與彌牟之弟遊，又辱為之服，敢辭。子遊曰：禮也。文子退反哭。」註：「子遊名習禮，文子亦以為當然，未覺其所譏。」「子遊趨而就諸臣之位。」註：「深譏之。」「文子又辭曰：子辱與彌牟之弟遊，又辱為之服，又辱臨其喪，敢辭。子遊曰：固以請。文子退，扶適子南面而立曰：子辱與彌牟之弟遊，又辱為之服，又辱臨其喪，虎也敢不復位。」註：「覺所譏也。」「子遊趨而就客位。」註：「所譏行。」按此一事，儻非註文明言，殆不可曉。今用五「譏」字，詞意渙然，至最後「覺所譏」「所譏行」六字，尤為透徹也。「季孫之母死，哀公弔焉。曾子與子貢弔焉，閽人為君在，弗內也。曾子與子貢入於其廐而修容焉。子貢先入，閽人曰：鄉者已告矣。」註：「既不敢止，以言下之。」「曾子後入，閽人辟之。」註：「見兩賢相隨，彌益恭也。」今人讀此段，真如親立季氏之庭，親見當時之事，註文尤得其要領雲。","sortOrder":19},
  {"id":"s_work_dtbt_48_20","chapterId":"ch_work_dtbt_48","text":"左傳有害理處","sortOrder":20},
  {"id":"s_work_dtbt_48_21","chapterId":"ch_work_dtbt_48","text":"左傳議論遣辭，頗有害理者，以文章富豔之故，後人一切不復言，今略疏數端，以箴其失。傳雲：「鄭武公、莊公，為平王卿士，王貳於虢。」杜氏謂：「不復專任鄭伯也。」「周公閼與王孫蘇爭政，王叛王孫蘇。」杜氏曰：「叛者，不與也。」夫以君之於臣，而言貳與叛，豈理也哉！「晉平戎於王，單襄公如晉拜成。劉康公徼戎，將遂伐之。叔服曰：背盟而欺大國，不義。」晉范吉射、趙鞅交兵。「劉氏、范氏世為昏姻，萇弘事劉文公，故周與范氏。趙鞅以為討。」夫以天子之使出聘侯國，而言拜成。謂周於晉為欺大國。諸侯之卿跋扈於天子，而言討。皆於名分為不正。其他如晉邢侯殺叔魚，叔魚兄叔向數其惡而尸諸市。其於兄弟之誼為弗篤矣，而託仲尼之語雲：「殺親益榮。」杜氏又謂：「榮名益己。」以弟陳尸為兄榮，尤為失也。","sortOrder":21},
  {"id":"s_work_dtbt_48_22","chapterId":"ch_work_dtbt_48","text":"夫人宗女請受","sortOrder":22},
  {"id":"s_work_dtbt_48_23","chapterId":"ch_work_dtbt_48","text":"戚里宗婦封郡國夫人，宗女封郡縣主，皆有月俸錢米，春冬絹綿，其數甚多，嘉祐祿令所不備載。頃見張掄娶仲儡女，封遂安縣主，月入近百千，內人請給，除糧料院幫勘、左藏庫所支之外，內帑又有添給，外庭不復得知。因記熙寧初，神宗與王安石言，今財賦非不多，但用不節，何由給足？宮中一私身之奉，有及八十貫者，嫁一公主，至用七十萬緡，沈貴妃料錢月八百貫。聞太宗時，宮人惟繫皂紬襜，元德皇後嘗以金覴緣幨而怒其奢。仁宗初定公主俸料，以問獻穆大主，再三始言，其初僅得五貫耳。異時，中官月有止七百錢者。禮與其奢寧儉，自是美事也。一時旨意如此，不聞奉行。以今度之，何止十百倍也。","sortOrder":23},
  {"id":"s_work_dtbt_48_24","chapterId":"ch_work_dtbt_48","text":"蜀茶法","sortOrder":24},
  {"id":"s_work_dtbt_48_25","chapterId":"ch_work_dtbt_48","text":"蜀道諸司，惟茶馬一臺，最為富盛，茶之課利多寡，與夫民間利疚，他邦無由可知。予記東坡集有送周朝議守漢州詩雲：「茶為西南病，甿俗記二李。何人折其鋒，矯矯六君子。」註：「二李，杞與稷也。六君子，謂思道與姪正孺、張永徽、吳醇翁、呂元鈞、宋文輔也。」初，熙寧七年，遣三司幹當公事李杞經畫買茶，以蒲宗閔同領其事。蜀之茶園不殖五穀，惟宜種茶，賦稅一例折輸，錢三百折絹一匹，三百二十折紬一匹，十錢折綿一兩，二錢折草一圍，凡稅額總三十萬。杞創設官場，歲增息為四十萬。其輸受之際，往往壓其斤重，侵其加直。杞以疾去，都官郎中劉佐體量，多其條畫。於是宗閔乃議民茶息收十之三，盡賣於官場，蜀茶盡榷，民始病矣。知彭州呂陶言：「天下茶法既通，蜀中獨行禁榷。况川峽四路所出茶貨，比方東南諸處，十不及一。諸路既許通商，兩川却為禁地，虧損治體，莫甚於斯。且盡榷民茶，隨買隨賣，或今日買十千，明日即作十三千賣之，比至歲終，不可勝算，豈止三分而已。佐、杞、宗閔作為敝法，以困西南生聚。」佐坐罷去，以國子博士李稷代之，陶亦得罪。侍御史周尹復極論榷茶為害，罷為湖北提點刑獄。利路漕臣張宗諤、張升卿，復建議廢茶場司，依舊通商。稷劾其疏謬，皆坐貶秩。茶場司行劄子督綿州彰明縣，知縣宋大章繳奏，以為非所當用。稷又詆其賣直釣奇，坐衝替。一歲之間，通課利及息耗至七十六萬緡有奇，詔錄李杞前勞而官其子。後稷死於永樂城，其代陸師閔言其治茶五年，獲淨息四百二十八萬緡，詔賜田十頃。凡上所書，皆見於國史。坡公所稱思道乃周尹，永徽乃二張之一，元鈞乃呂陶，文輔乃大章也，正孺、醇翁之事不著。","sortOrder":25},
  {"id":"s_work_dtbt_48_26","chapterId":"ch_work_dtbt_48","text":"判府知府","sortOrder":26},
  {"id":"s_work_dtbt_48_27","chapterId":"ch_work_dtbt_48","text":"國朝著令，僕射、宣徽使、使相知州府者為判，其後改僕射為特進，官稱如昔時。唯章子厚罷相守越，製詞結尾雲：「依前特進知越州。」雖曰黜典，亦學士院之誤。同時執政蔣穎叔以手簡與之，猶呼雲判府，而章質夫只雲知府，蓋從其實，予所藏名公法書冊有之。吾鄉彭公器資有遺墨一帖，不知與何人？其辭曰：「某頓首，知郡相公閣下。」是必知州者，故亦不以府字借稱。今世蕞爾小壘，區區一朝官承乏作守，吏民稱為判府，彼固偃然居之不疑。風俗淳澆之異，一至於此！","sortOrder":27},
  {"id":"s_work_dtbt_48_28","chapterId":"ch_work_dtbt_48","text":"歌扇舞衣","sortOrder":28},
  {"id":"s_work_dtbt_48_29","chapterId":"ch_work_dtbt_48","text":"唐李義山詩雲：「鏤月為歌扇，裁雲作舞衣。」同時人張懷慶竊為己作，各增兩字雲：「生情鏤月為歌扇，出性裁雲作舞衣。」致有生吞活剝之誚。予又見劉希夷代閨人春日一聯雲：「池月憐歌扇，山雲愛舞衣。」絕相似。杜老亦雲：「江清歌扇底，野曠舞衣前。」儲光羲雲：「竹吹留歌扇，蓮香入舞衣。」然則唐詩人好以歌扇、舞衣為對也。","sortOrder":29},
  {"id":"s_work_dtbt_48_30","chapterId":"ch_work_dtbt_48","text":"官會折閱","sortOrder":30},
  {"id":"s_work_dtbt_48_31","chapterId":"ch_work_dtbt_48","text":"官會子之作，始於紹興三十年，錢端禮為戶部侍郎，委徽州創樣撩造紙五十萬，邊幅皆不剪裁。初以分數給朝士俸，而於市肆要鬧處置五場，輦見錢收換，每一千別輸錢十，以為吏卒用。商賈入納，外郡綱運，悉同見錢。無欠數陪償及腳乘之費，公私便之。既而印造益多，而實錢浸少，至於十而損一，未及十年，不勝其弊。壽皇念其弗便，出內庫銀二百萬兩售於市，以錢易楮焚棄之，僅解一時之急，時乾道三年也。淳熙十二年，邁自婺召還，見臨安人揭小帖，以七百五十錢兌一楮，因入對言之，喜其復行。天語雲：「此事惟卿知之，朕以會子之故，幾乎十年睡不著。」然是後曩弊又生，且偽造者所在有之。及其敗獲，又未嘗正治其誅，故行用愈輕。迨慶元乙卯，多換六百二十，朝廷以為憂，詔江、浙諸道必以七百七十錢買楮幣一道。此意固善，而不深思，用錢易紙，非有微利，誰肯為之？因記崇寧四年有旨，在京市戶市商人交子，凡一千許損至九百五十，外路九百七十，得貿鬻如法，毋得輒損，願增價者聽。蓋有所贏縮，則可通行，此理固易曉也。","sortOrder":31},
  {"id":"s_work_dtbt_48_32","chapterId":"ch_work_dtbt_48","text":"飛鄰望鄰","sortOrder":32},
  {"id":"s_work_dtbt_48_33","chapterId":"ch_work_dtbt_48","text":"自古所謂四鄰，蓋指東西南北四者而言耳。然貪虐害民者，一切肆其私心。元豐以後，州縣榷賣坊場，而收淨息以募役，行之浸久，弊從而生。往往鬻其抵產，抑配四鄰，四鄰貧乏，則散及飛鄰、望鄰之家，不復問遠近，必得償乃止。飛鄰、望鄰之說，誠所未聞。元祐元年，殿中侍御史呂陶奏疏論之，雖嘗暫革，至紹聖又復然。","sortOrder":33},
  {"id":"s_work_dtbt_48_34","chapterId":"ch_work_dtbt_48","text":"衙參之禮","sortOrder":34},
  {"id":"s_work_dtbt_48_35","chapterId":"ch_work_dtbt_48","text":"今監司、郡守初上事，既受官吏參謁，至晡時，僚屬復伺於客次，胥吏列立廷下通刺曰衙，以聽進退之命，如是者三日。如主人免此禮，則翌旦又通謝刺。此禮之起，不知何時。唐岑參為虢州上佐，有一詩，題為衙郡守還，其辭曰：「世事何反覆，一身難可料。頭白翻折腰，還家私自笑。所嗟無產業，妻子嫌不調。五斗米留人，東溪憶垂釣。」然則由來久矣。韓詩曰：「如今便別官長去，直到新年衙日來。」疑是謂月二日也。","sortOrder":35},
  {"id":"s_work_dtbt_48_36","chapterId":"ch_work_dtbt_48","text":"容齋三筆","sortOrder":36},
  {"id":"s_work_dtbt_49_1","chapterId":"ch_work_dtbt_49","text":"卷第十五(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_49_2","chapterId":"ch_work_dtbt_49","text":"內職命詞","sortOrder":2},
  {"id":"s_work_dtbt_49_3","chapterId":"ch_work_dtbt_49","text":"內庭婦職遷敍，皆出中旨，至中書命詞。如尚書內省官，固知其為長年習事，如司字、典字、掌字，知其為主守之微者。至於紅紫霞帔郡國夫人，則其年齡之長少，爵列之崇庳，無由可以測度。紹興二十八年九月，仲兄以左史直前奏事，時兼權中書舍人，高宗聖訓雲：「有一事待與卿說，昨有宮人宮正者封夫人，乃宮中管事人，六十餘歲，非是嬪御，恐卿不知。」兄奏雲：「係王剛中行詞，剛中除蜀帥，係臣書黃，容臣別撰入。」上頷首。後四日，經筵留身奏事，奏言：「前日面蒙宣諭，永嘉郡張夫人告詞，既得聖旨，即時傳旨三省，欲別撰進。昨日宰臣傳聖旨，令不須別撰。」上曰：「乃皇後閤中老管事人，今六十六歲，宮正乃執事者，昨日宰執奏欲換告，亦無妨礙，不須別進。今已年老多病，但欲得稱呼耳。」蓋昨訓詞中稱其容色雲。","sortOrder":3},
  {"id":"s_work_dtbt_49_4","chapterId":"ch_work_dtbt_49","text":"蔡京除吏","sortOrder":4},
  {"id":"s_work_dtbt_49_5","chapterId":"ch_work_dtbt_49","text":"唐天寶之季，楊國忠以右相兼吏部尚書，大集選人註擬於私第。故事，註官訖，過門下侍中、給事中，國忠呼左相陳希烈於座隅，(時改侍中為左相。)給事中在列，曰：「既對註矣，過門下了矣。」吏部侍郎二人與郎官同咨事，趨走於前，國忠誇謂諸妹曰：「兩個紫袍主事何如？」史策書此，以見國忠顓政舞權也。然猶令侍中、給事同坐，以明非矯。若蔡京之盜弄威柄，則又過之。政和中，以太師領三省事，得治事於家。弟卞以開府在經筵，嘗挾所親將仕郎吳說往見，坐於便室，設一卓，陳筆硯，置玉版紙闊三寸者數十片於上。卞言常州教授某人之淹滯，曰：「自初登科作教官，今已朝奉郎，尚未脫故職。」京問：「何以處之？」卞曰：「須與一提學。」京取一紙，書其姓名及提舉學事字而缺其路分，顧曰：「要何地？」卞曰：「其家極貧，非得俸入優厚處不可。」於是書「河北西路」字，付老兵持出。俄別有一兵齎一雙緘及紫匣來，乃福建轉運判官直龍圖閣鄭可簡，以新茶獻，即就可漏上書「祕撰運副」四字授之。卞方語及吳說曰：「是安中司諫之子，頗能自立。且王逢原外孫，與舒王夫人姻眷，其母老，欲求一見闕省局。」京問：「吳曾踏逐得未？」對曰：「打套局適闕。」又書一紙付出。少頃，卞目吳使先退。吳之從姊嫁門下侍郎薛昂，因館其家，纔還舍，具以告昂，嘆所見除目之迅速。昂曰：「此三者已節次書黃矣。」始知國忠猶落第二義也。","sortOrder":5},
  {"id":"s_work_dtbt_49_6","chapterId":"ch_work_dtbt_49","text":"題先聖廟詩","sortOrder":6},
  {"id":"s_work_dtbt_49_7","chapterId":"ch_work_dtbt_49","text":"兗州先聖廟壁，嘗有題詩者雲：「靈光殿古生秋草，曲阜城荒散晚鴉。惟有孔林殘照日，至今猶屬仲尼家。」不顯姓名，頗為士大夫傳誦。予頃在福州，於呂虛己處，見邵武上官校書詩一冊，內一篇題為州西行，州西者，蔡京所居處也。註雲：「靖康元年作。時京謫湖湘，子孫分竄外郡，所居第摧毀，索寞殆無人跡，故為古調以傷之。」凡三十餘韻，今但記其末聯雲：「君不見喬木參天獨樂園，至今仍是溫公宅。」其意甚與前相類。紹興二十五年冬，秦檜死，空其賜宅，明年，開河，役夫輦泥土堆於牆下。天台士人左君作詩曰：「格天閣在人何在？偃月堂深恨亦深。不見洛陽圖白髮，但知郿塢積黃金。直言動便遭羅織，舉目寧知有照臨。炙手附炎俱不見，可憐泥滓滿牆陰。」語雖紀實，然太露筋骨，不若前兩章渾成也。左頗有才，最善謔，二十八年，楊和王之子偰，除權工部侍郎，時張循王之子子顏、子正，皆帶集英修撰，且進待製矣。會葉審言自侍御史、楊元老自給事中，徙為吏、兵侍郎，蓋以繳論之故。左用歇後語作絕句曰：「木易已為工部侍，弓長肯作集英修。如今臺省無楊葉，豚犬超升卒未休。」左居西湖上，好事請謁，人或畏其口，後竟終於布衣。","sortOrder":7},
  {"id":"s_work_dtbt_49_8","chapterId":"ch_work_dtbt_49","text":"季文子魏獻子","sortOrder":8},
  {"id":"s_work_dtbt_49_9","chapterId":"ch_work_dtbt_49","text":"儗人必於其倫，後世之說也，古人則不然。魯季文子出一莒僕，而歷引舜舉十六相去四凶，曰：「舜有大功二十而為天子，今行父雖未獲一吉人，去一凶矣，於舜之功二十之一也。」晉魏獻子為政，以其子戊為梗陽大夫，謂成鱄曰：「吾與戊也，縣人其以我為黨乎？」鱄誦大雅文王克明克類、克長克君、克順克比、比於文王之句，而以為九德不愆。勤施無私曰類，擇善而從之曰比。言：「主之舉也，近文德矣。」且季孫行父之視舜，魏舒之視文王，何啻天壤之不侔！而行父以自比，舒受人之諛不以為嫌，乃知孟子所謂：「顏淵曰：『舜何人也？予何人也？有為者亦若是。』」非過論也。","sortOrder":9},
  {"id":"s_work_dtbt_49_10","chapterId":"ch_work_dtbt_49","text":"尊崇聖字","sortOrder":10},
  {"id":"s_work_dtbt_49_11","chapterId":"ch_work_dtbt_49","text":"自孔子贊易、孟子論善信之前，未甚以聖為尊崇，雖詩、書、禮經所載亦然也。書稱堯、舜之德，但曰「聰明文思」，「欽明文思」，「濬哲文明」，「溫恭允塞」。至益之對舜，始有「乃聖乃神」之語。洪範「睿作聖」與「恭作肅，從作乂，明作哲，聰作謀」，同列於五事，其究但曰「聖時風若」，咎徵至以蒙為對。「惟聖罔念作狂，惟狂克念作聖」，則以狂與聖為善惡之對也。詩曰：「國雖靡止，或聖或否。」則以聖與否為對也。下文「或哲或謀，或肅或乂」，蓋與五事略同。人之齊聖，不過「飲酒溫克」而已。左傳八愷，齊聖廣淵，明允篤誠，周官六德，知、仁、聖、義、忠、和，皆混於諸字中，了無所異。以故魯以臧武仲為聖人，伯夷、伊尹、柳下惠皆曰聖，而孟子以為否。","sortOrder":11},
  {"id":"s_work_dtbt_49_12","chapterId":"ch_work_dtbt_49","text":"媵字訓","sortOrder":12},
  {"id":"s_work_dtbt_49_13","chapterId":"ch_work_dtbt_49","text":"媵之義為送，春秋所書，晉人衞人來媵，皆送女也。楚辭九章雲：「波滔滔兮來迎，魚鱗鱗兮媵予。」其義亦同。周易鹹卦象曰：「鹹其輔頰舌，滕口說也。」釋文雲：滕，達也。九家皆作乘，而鄭康成、虞翻作媵，而亦訓為送雲。","sortOrder":13},
  {"id":"s_work_dtbt_49_14","chapterId":"ch_work_dtbt_49","text":"周禮奇字","sortOrder":14},
  {"id":"s_work_dtbt_49_15","chapterId":"ch_work_dtbt_49","text":"六經用字，固亦間有奇古者，然惟周禮一書獨多。予謂前賢以為此書出於劉歆，歆常從揚子雲學作奇字，故用以入經。如法為灋、柄為枋、邪為衺、美為媺、呼為嘑、拜為(左扌右上屮中艸下今)、韶為（上殸下召）、怪為傀、暴為虣、擉為簎、風為飌、鮮為鱻、槁為薧、螺為蠃、脾為蠯、魚為?、埋為貍、吹為龡、陔為裓、暗為韽、柝為（木槖）、探為撢、趐為翨、摘為硩、駭為駴、擊為轚、辜為（左木右上古下羊）、掬為輂、羃為榠、藻為薻、昊為（仄之人右日）、叩為敂、艱為囏、魅為鬽，與夫庮、皫、胖、鱐、齍、眂、劀、酏、（上卥下木）、臡、箈、（鬻之米換者）、柶、絼、疈、爂、（上臨下木）、朄之類，皆他經鮮用，予前已書之而不詳悉。若考工記之字，又不可勝載也。","sortOrder":15},
  {"id":"s_work_dtbt_49_16","chapterId":"ch_work_dtbt_49","text":"大禹之書","sortOrder":16},
  {"id":"s_work_dtbt_49_17","chapterId":"ch_work_dtbt_49","text":"夏書五子之歌，述大禹之戒，其前三章是也。禹之謨訓，捨虞、夏二書外，他無所載。漢藝文志雜家者流，有大（上人中夕下幣）三十七篇，雲：「傳言禹所作，其文似後世語。」（上人中夕下幣），古禹字也，意必依仿而作之者，然亦周、漢間人所為，今寂而無傳，亦可惜也。","sortOrder":17},
  {"id":"s_work_dtbt_49_18","chapterId":"ch_work_dtbt_49","text":"隨巢胡非子","sortOrder":18},
  {"id":"s_work_dtbt_49_19","chapterId":"ch_work_dtbt_49","text":"漢書藝文志，墨家者流，有隨巢子六篇，胡非子三篇，皆雲墨翟弟子也。二書今不復存，馬總意林所述，各有一卷，隨巢之言曰：「大聖之行，兼愛萬民，疏而不絕，賢者欣之，不肖者憐之。賢而不欣，是賤德也，不肖不憐，是忍人也。」又有「鬼神賢於聖人」之論，其於兼愛、明鬼，為墨之徒可知。胡非之言曰：「勇有五等：負長劍，赴榛薄，折兕豹，搏熊羆，此獵徒之勇也；負長劍，赴深淵，折蛟龍，搏黿鼉，此漁人之勇也；登高危之上，鵠立四望，顏色不變，此陶嶽之勇也；剽必刺，視必殺，此五刑之勇也；齊威公以魯為南境，魯憂之。曹劌匹夫之士，一怒而刼萬乘之師，存千乘之國，此君子之勇也。」其說亦卑陬無過人處。","sortOrder":19},
  {"id":"s_work_dtbt_49_20","chapterId":"ch_work_dtbt_49","text":"別國方言","sortOrder":20},
  {"id":"s_work_dtbt_49_21","chapterId":"ch_work_dtbt_49","text":"今世所傳揚子雲輶軒使者絕代語釋別國方言，凡十三卷，郭璞序而解之。其末又有漢成帝時劉子駿與雄書，從取方言，及雄答書。以予考之，殆非也。雄自序所為文，漢史本傳但雲：「經莫大於易，故作太玄；傳莫大於論語，作法言；史篇莫善於倉頡，作訓纂；箴莫善於虞箴，作州箴；賦莫深於離騷，反而廣之；辭莫麗於相如，作四賦。」雄平生所為文盡於是矣，初無所謂方言。漢藝文志小學有訓纂一篇。儒家有雄所序三十八篇，註雲：「太玄十九，法言十三，樂四，箴二。」雜賦有雄賦十二篇，亦不載方言。觀其答劉子駿書，稱「蜀人嚴君平」，按君平本姓莊，漢顯帝諱莊，始改曰「嚴」。法言所稱「蜀莊沈冥，蜀莊之才之珍，吾珍莊也」，皆是本字，何獨至此書而曰「嚴」。又子駿只從之求書，而答雲：「必欲脅之以威，陵之以武，則縊死以從命也！」何至是哉？既雲成帝時子駿與雄書，而其中乃雲孝成皇帝，反覆抵牾。又書稱「汝、潁之間」，先漢人無此語也，必漢、魏之際，好事者為之雲。","sortOrder":21},
  {"id":"s_work_dtbt_49_22","chapterId":"ch_work_dtbt_49","text":"縱　臾","sortOrder":22},
  {"id":"s_work_dtbt_49_23","chapterId":"ch_work_dtbt_49","text":"史記衡山王傳：「日夜從容王密謀反事。」漢書傳雲：「日夜縱臾王謀反事。」如淳曰：「臾讀曰勇，縱臾，猶言勉強也。」顏師古曰：「縱，音子勇反。縱臾，謂獎勸也。」揚雄方言雲：「食閻、慫恿，(音與上同。)勸也。南楚凡己不欲喜，而旁人說之，不欲怒，而旁人怒之，謂之食閻，亦謂之慫恿。」今禮部韻略收入，漢註皆不引用。","sortOrder":23},
  {"id":"s_work_dtbt_49_24","chapterId":"ch_work_dtbt_49","text":"總持寺唐敕牒","sortOrder":24},
  {"id":"s_work_dtbt_49_25","chapterId":"ch_work_dtbt_49","text":"唐世符帖文書，今存者亦少，隆興府城內總持寺有一碑，其前一紙，乾符三年，洪州都督府牒僧仲暹；次一紙，中和五年，監軍使帖僧神遇；第三紙，光啟三年十一月，中書門下牒江西觀察使。其後列銜者二十四人，曰：中書侍郎兼兵部尚書平章事杜遜能，門下侍郎兼吏部尚書平章事孔緯，此後檢校左僕射一人，檢校司空二人，檢校司徒八人，檢校太保三人，檢校太傅一人，檢校太尉三人，檢校太師一人，皆帶平章事著姓，太保兼侍中昭度不書韋字，檢校太師兼侍中一人，太師兼中書令一人，皆不著姓，捨杜、孔、韋三正相之外，餘皆小書使字，蓋使相也。後又有節度使鍾傳兩牒，字畫端勁有法，如士人札翰，今時臺省吏文不能及也。嘉祐二年，雒陽人職方員外郎李上交來豫章東湖，見所藏真蹟，為辨之雲：二十一人者，乃張濬、朱玫、李福、李可舉、李罕之、陳敬瑄、王處存、王徽、曹誠、李匡威、李茂貞、王重榮、楊守亮、王鎔、樂彥禎、朱全忠、張全義、拓跋思恭、時溥、王鐸、高駢也。而註雲：「見僖宗紀及實錄。」以予考之，自三相及拓跋、樂彥禎、時溥、張濬、朱全忠、李茂貞諸人外，如李克用、朱瑄、王行瑜皆是時使相，不應缺，而朱玫、王鐸、王重榮、李福皆已死，所謂太師中書令者，史策不載，唯陳敬瑄檢校此官而兼中令，最後者其是歟？他皆不復可究質矣。","sortOrder":25},
  {"id":"s_work_dtbt_49_26","chapterId":"ch_work_dtbt_49","text":"禁旅遷補","sortOrder":26},
  {"id":"s_work_dtbt_49_27","chapterId":"ch_work_dtbt_49","text":"國朝宿衞禁旅遷補之製，以歲月功次而遞進者，謂之排連。大禮後，次年殿庭較藝，乘輿臨軒，曰「推垜子」。其歲滿當去者，隨其本資，高者以正任團練使、刺史補外州總管、鈐轄，小者得州都監，當留者於軍職內升補，謂之轉員。唯推垜之日，以疾不趁赴者，為害甚重。紹興三十二年四月，予以右史午對時將有使事，與上介張才甫同飯於皇城司。有一老兵，幞頭執黑杖子，拜辭皇城幹辦官劉知閤，泣涕哽噎，劉亦為惻然。予問其故，兵以杖相示，滿其上皆揭記士卒姓名營屯事件。雲身是天武第一軍都指揮使，曾立戰功，積官至遙郡團練使，今年滿當出職，若御前呈試了，便得正任使名，而為近郡總管。不幸小疾，遂遭揀汰，只可降移外藩將校，在身官位一切除落，方伏事州都監聽管營部轄。三十年勤勞，一旦如掃，薄命不偶，至於如是。坐者同嘆息憐之。按崇寧四年有詔，諸班直嘗備宿衞，病告滿尚可療者，殿前指揮使補外牢城指揮使，蓋舊法也。","sortOrder":27},
  {"id":"s_work_dtbt_49_28","chapterId":"ch_work_dtbt_49","text":"六言詩難工","sortOrder":28},
  {"id":"s_work_dtbt_49_29","chapterId":"ch_work_dtbt_49","text":"唐張繼詩，今人所傳者唯楓橋夜泊一篇，荊公詩選亦但別詩兩首，樂府有塞孤一篇。而皇甫冉集中，載其所寄六言曰：「京口情人別久，揚州估客來疏。潮至潯陽回去，相思無處通書。」冉酬之，而序言：「懿孫，予之舊好，祗役武昌，有六言詩見憶，今以七言裁答，蓋拙於事者繁而費。」冉之意，以六言為難工，故衍六為七，然自有三章曰：「江上年年春早，津頭日日人行。借問山陰遠近，猶聞薄暮鐘聲。」「水流絕澗終日，草長深山暮雲。犬吠鷄鳴幾處，條桑種杏何人？」「門外水流何處，天邊樹繞誰家。山絕東西多少，朝朝幾度雲遮。」皆清絕可畫，非拙而不能也。予編唐人絕句，得七言七千五百首，五言二千五百首，合為萬首。而六言不滿四十，信乎其難也。","sortOrder":29},
  {"id":"s_work_dtbt_49_30","chapterId":"ch_work_dtbt_49","text":"杯水救車薪","sortOrder":30},
  {"id":"s_work_dtbt_49_31","chapterId":"ch_work_dtbt_49","text":"孟子曰：「仁之勝不仁也，如水勝火，今之為仁者，猶以一杯水救一車薪之火也，不熄，則謂之水不勝火。」予讀文子，其書有雲：「水之勢勝火，一勺不能救一車之薪；金之勢勝木，一刃不能殘一林；土之勢勝水，一塊不能塞一河。」文子周平王時人，孟氏之言蓋本於此。","sortOrder":31},
  {"id":"s_work_dtbt_49_32","chapterId":"ch_work_dtbt_49","text":"詘一人之下","sortOrder":32},
  {"id":"s_work_dtbt_49_33","chapterId":"ch_work_dtbt_49","text":"蕭何諫高祖受漢王之封，曰：「夫能詘於一人之下，而信於萬乘之上者，湯、武是也。」六韜雲：「文王在岐，召太公曰：『吾地小。』太公曰：『天下有粟，賢者食之，天下有民，賢者牧之。屈於一人之下，則申於萬人之上，唯聖人能為之。』」然則蕭何之言，其出於此，而漢書註釋諸家，皆不曾引證。","sortOrder":33},
  {"id":"s_work_dtbt_49_34","chapterId":"ch_work_dtbt_49","text":"秦漢重縣令客","sortOrder":34},
  {"id":"s_work_dtbt_49_35","chapterId":"ch_work_dtbt_49","text":"秦、漢之時，郡守縣令之權極重，雖一令之微，能生死人，故為之賓客者，邑人不敢不敬。單父人呂公善沛令，辟仇從之客，沛中豪傑吏聞令有重客，皆往賀。謂以禮物相慶也。曰：「令有貴客，為具召之，幷召令。」相如竊王孫女歸成都，以貧困復如臨邛，王孫杜門不出。崑弟諸公更謂王孫曰：「長卿人材足依，且又令客，奈何相辱如此！」註雲：「言縣令之客，不可以辱也。」是時為令客者如此。今士大夫為守令故人，往見者雖未必皆賢，豈復蒙此禮敬。稍或戾於法製，微有幹託，其累主人必矣！","sortOrder":35},
  {"id":"s_work_dtbt_49_36","chapterId":"ch_work_dtbt_49","text":"之字訓變","sortOrder":36},
  {"id":"s_work_dtbt_49_37","chapterId":"ch_work_dtbt_49","text":"漢高祖諱邦，荀悅雲：「之字曰國。惠帝諱盈，之字曰滿。」謂臣下所避以相代也。蓋「之」字之義訓變，左傳：「周史以周易見陳侯者，陳侯使筮之，遇觀之否。」謂觀六四變而為否也。他皆仿此。","sortOrder":37},
  {"id":"s_work_dtbt_49_38","chapterId":"ch_work_dtbt_49","text":"容齋三筆","sortOrder":38},
  {"id":"s_work_dtbt_50_1","chapterId":"ch_work_dtbt_50","text":"卷第十六(二十則)","sortOrder":1},
  {"id":"s_work_dtbt_50_2","chapterId":"ch_work_dtbt_50","text":"蹇氏父子","sortOrder":2},
  {"id":"s_work_dtbt_50_3","chapterId":"ch_work_dtbt_50","text":"蹇周輔立江西、福建茶法，以害兩路。其子序辰，在紹聖中，乞編類元祐章疏案牘，人為一帙，置在二府。由是縉紳之禍，無一得脫。此猶未足言，及居元符遏密中，肆音樂自娛。後守蘇州，以天寧節與其父忌日同，輒於前一日設宴，及節日不張樂。其無人臣之義如是，蓋舉世未聞也。","sortOrder":3},
  {"id":"s_work_dtbt_50_4","chapterId":"ch_work_dtbt_50","text":"神臂弓","sortOrder":4},
  {"id":"s_work_dtbt_50_5","chapterId":"ch_work_dtbt_50","text":"神臂弓出於弩遺法，古未有也。熙寧元年，民李宏始獻之入內，副都知張若水方受旨料簡弓弩，取以進。其法以檿木為身，檀為弰，鐵為蹬子鎗頭，銅為馬面牙發，麻繩札絲為絃，弓之身三尺有二寸，絃長二尺有五寸，箭木羽長數寸，射二百四十餘步，入榆木半笴。神宗閱試，甚善之。於是行用，而他弓矢弗能及。紹興五年，韓世忠又侈大其製，更名「克敵弓」，以與金虜戰，大獲勝捷。十二年詞科試日，主司出克敵弓銘為題雲。","sortOrder":5},
  {"id":"s_work_dtbt_50_6","chapterId":"ch_work_dtbt_50","text":"敕令格式","sortOrder":6},
  {"id":"s_work_dtbt_50_7","chapterId":"ch_work_dtbt_50","text":"法令之書，其別有四，敕、令、格、式是也。神宗聖訓曰：「禁於未然之謂敕；禁於已然之謂令；設於此以待彼之至，謂之格；設於此使彼效之，謂之式。」凡入笞杖徒流死，自例以下至斷獄十有二門，麗刑名輕重者，皆為敕；自品官以下至斷獄三十五門，約束禁止者，皆為令；命官庶人之等，倍全分釐之給，有等級高下者，皆為格；表奏、帳籍、關牒、符檄之類，有體製模楷者，皆為式。元豐編敕用此，後來雖數有修定，然大體悉循用之。今假寧一門，實載於格，而公私文書行移，並名為式假，則非也。","sortOrder":7},
  {"id":"s_work_dtbt_50_8","chapterId":"ch_work_dtbt_50","text":"顏魯公戲吟","sortOrder":8},
  {"id":"s_work_dtbt_50_9","chapterId":"ch_work_dtbt_50","text":"陶淵明作閒情賦，寄意女色。蕭統以為白玉微瑕。宋廣平作梅花賦，皮日休以為鐵心石腸人，而亦風流豔冶如此。顏魯公集有七言聯句四絕，其目曰：大言、樂語、嚵語、醉語。於樂語雲：「苦河既濟真僧喜，新知滿坐笑相視。戍客歸來見妻子，學生放假偷向市。」嚵語雲：「拈（飠追）（舌氐）指不知休，欲炙侍立涎交流。過屠大嚼肯知羞，食店門外強淹留。」醉語雲：「逢糟遇（麥曲）便酩酊，覆車墜馬皆不醒。倒著接（上罒下離）髮垂領，狂心亂語無人並。」以公之剛介守正，而作是詩，豈非以文滑稽乎？然語意平常，無可咀嚼，予疑非公詩也。","sortOrder":9},
  {"id":"s_work_dtbt_50_10","chapterId":"ch_work_dtbt_50","text":"紀年用先代名","sortOrder":10},
  {"id":"s_work_dtbt_50_11","chapterId":"ch_work_dtbt_50","text":"唐德宗以建中、興元之亂，思太宗貞觀、明皇開元為不可跂及，故改年為貞元，各取一字以法象之。高宗建炎之元，欲法建隆而下字無所本。孝宗以來，始一切用貞元故事。隆興以建隆、紹興，乾道以乾德、至道，淳熙以淳化、雍熙，紹熙以紹興、淳熙，慶元以慶曆、元祐也。","sortOrder":11},
  {"id":"s_work_dtbt_50_12","chapterId":"ch_work_dtbt_50","text":"中　舍","sortOrder":12},
  {"id":"s_work_dtbt_50_13","chapterId":"ch_work_dtbt_50","text":"官製未改之前，初升朝官，有出身人為太子中允，無出身人為太子中舍，皆今通直郎也。近時士大夫或不能曉，乃稱中書舍人曰中舍，殊可笑雲。蘇子美在進奏院，會館職，有中舍者，欲預席。子美曰：「樂中既無箏、琶、篳、笛，坐上安有國、舍、虞、比。」國謂國子博士，舍謂中舍，虞謂虞部，比謂比部員外、郎中，皆任子官也。","sortOrder":13},
  {"id":"s_work_dtbt_50_14","chapterId":"ch_work_dtbt_50","text":"多赦長惡","sortOrder":14},
  {"id":"s_work_dtbt_50_15","chapterId":"ch_work_dtbt_50","text":"熙寧七年旱，神宗欲降赦，時已兩赦矣。王安石曰：「湯旱，以六事自責，曰政不節與？若一歲三赦，是政不節，非所以弭災也。」乃止。安石平生持論務與衆異，獨此說為至公。近者六年之間，再行覃霈。婺州富人盧助教，以刻核起家，因至田僕之居，為僕父子四人所執，投置杵臼內，搗碎其軀為肉泥，既鞫治成獄，而遇己酉赦恩獲免。至復登盧氏之門，笑侮之曰：「助教何不下莊收穀？」茲事可為冤憤，而州郡失於奏論。紹熙甲寅歲至於四赦，凶盜殺人一切不死，惠奸長惡，何補於治哉？","sortOrder":15},
  {"id":"s_work_dtbt_50_16","chapterId":"ch_work_dtbt_50","text":"奏讞疑獄","sortOrder":16},
  {"id":"s_work_dtbt_50_17","chapterId":"ch_work_dtbt_50","text":"州郡疑獄許奏讞，蓋朝廷之深恩。然不問所犯重輕及情理蠧害，一切縱之，則為壞法。耿延年提點江東刑獄，專務全活死囚，其用心固善。然南康婦人，謀殺其夫甚明，曲貸其命，累勘官翻以失入被罪。予守贛，一將兵逃至外邑，殺村民於深林，民兄後知之，畏申官之費，即焚其尸，事發繫獄，以殺時無證，尸不經驗，奏裁刑寺輒定為斷配。予持敕不下，復奏論之，未下而此兵死於獄。因記元豐中，宣州民葉元，以同居兄亂其妻而殺之，又殺兄子，而強其父與嫂約契，不訟於官。鄰里發其事，州以情理可憫，為上請。審刑院奏欲貸，神宗曰：「罪人已前死，奸亂之事，特出於葉元之口，不足以定罪，且下民雖為無知，抵冒法禁，固宜哀矜。然以妻子之愛，既殺其兄，仍戕其姪，又罔其父，背逆天理，傷敗人倫，宜以毆兄至死律論。」此旨可謂至明矣。","sortOrder":17},
  {"id":"s_work_dtbt_50_18","chapterId":"ch_work_dtbt_50","text":"醫職冗濫","sortOrder":18},
  {"id":"s_work_dtbt_50_19","chapterId":"ch_work_dtbt_50","text":"神宗董正治官，立醫官，額止於四員。及宣和中，自和安大夫至翰林醫官，凡一百十七人，直局至祗候，凡九百七十九人，冗濫如此。三年五月始詔大夫以二十員，郎以三十員，醫效至祗候，以三百人為額，而額外人免改正，但不許作官戶，見帶遙郡人並依元豐舊製，然竟不能循守也。乾道三年正月，隨龍醫官、平和大夫、階州團練使潘攸差判太醫局，請給依能誠例支破。邁時在西掖，取會能誠全支本色，因依誠係和安大夫、潭州觀察使，月請米麥百餘碩，錢數百千，春冬綿絹之屬，比他人十倍，因上章極論之，乞將攸合得請給，令戶部照條支破。孝宗聖諭雲：「豈惟潘攸不合得，幷能誠亦合住了。」即日御筆批依，仍改正能誠已得真俸之旨，旋又罷醫官局。","sortOrder":19},
  {"id":"s_work_dtbt_50_20","chapterId":"ch_work_dtbt_50","text":"切腳語","sortOrder":20},
  {"id":"s_work_dtbt_50_21","chapterId":"ch_work_dtbt_50","text":"世人語音有以切腳而稱者，亦間見之於書史中，如以蓬為勃籠，槃為勃闌，鐸為突落，叵為不可，團為突欒，鉦為丁寧，頂為滴（寧頁），角為矻落，蒲為勃盧，精為即零，螳為突郎，諸為之乎，旁為步廊，茨為蒺藜，圈為屈攣，錮為骨露，窠為窟駝是也。","sortOrder":21},
  {"id":"s_work_dtbt_50_22","chapterId":"ch_work_dtbt_50","text":"唐世辟寮佐有詞","sortOrder":22},
  {"id":"s_work_dtbt_50_23","chapterId":"ch_work_dtbt_50","text":"唐世節度、觀察諸使，辟置寮佐以至州郡差掾屬，牒語皆用四六，大略如告詞。李商隱樊南甲乙集、顧雲編稿、羅隱湘南雜稿，皆有之。故韓文公送石洪赴河陽幕府序雲：「撰書辭，具馬幣。」李肇國史補，載崖州差故相韋執誼攝軍事衙推，亦有其文，非若今時只以吏牘行遣也。錢武肅在鎮牒鍾廷翰攝安吉主簿雲：「敕淮南、鎮海、鎮東等軍節度使，牒將仕郎試祕書省校書郎鍾廷翰，牒奉處分，前件官儒素修身，早升官緒，寓居霅水，累歷星霜，克循廉謹之規，備顯溫恭之道。今者願求錄用，特議掄材，安吉屬城印曹闕吏，俾期差攝，勉效公方，儻聞佐理之能，豈恡超升之獎？事須差攝安吉縣主簿牒舉者，故牒。貞明二年三月日。」牒後銜雲：「使、尚父、守尚書令、吳越王押。」此牒今藏於王順伯家，其字畫端嚴有法，其文則掌書記所撰，殊為不工，但印記不存矣。謂主簿為印曹，亦佳。","sortOrder":23},
  {"id":"s_work_dtbt_50_24","chapterId":"ch_work_dtbt_50","text":"高子允謁刺","sortOrder":24},
  {"id":"s_work_dtbt_50_25","chapterId":"ch_work_dtbt_50","text":"王順伯藏昔賢墨帖至多，其一曰高子允諸公謁刺，凡十六人，時公美、徐振甫、餘中、龔深父、元耆寧、秦少遊、黃魯直、張文潛、晁無咎、司馬公休、李成季、葉致遠、黃道夫、廖明略、彭器資、陳祥道，皆元祐四年朝士，唯器資為中書舍人，餘皆館職。其刺字或書官職，或書郡里，或稱姓名，或只稱名，既手書之，又斥主人之字，且有同舍、尊兄之目，風流氣味，宛然可端拜，非若後之士大夫一付筆吏也。蔡忠惠公帖亦有其二：一曰，襄奉候子石兄起居，朔旦謹謁；一曰，襄別洪州少卿學士。蓋又在前帖三十年之先也。","sortOrder":25},
  {"id":"s_work_dtbt_50_26","chapterId":"ch_work_dtbt_50","text":"蔡君謨書碑","sortOrder":26},
  {"id":"s_work_dtbt_50_27","chapterId":"ch_work_dtbt_50","text":"歐陽公作蔡君謨墓志雲：「公工於書畫，頗自惜，不妄與人書。仁宗尤愛稱之，御製元舅隴西王碑文，詔公書之。其後命學士撰溫成皇後碑文，又敕公書，則辭不肯，曰：『此待詔職也。』」國史傳所載，蓋用其語。比見蔡與歐陽一帖雲：「曏者得侍陛下清光，時有天旨，令寫御撰碑文、宮寺題榜。至有勛德之家，幹請朝廷出敕令書。襄謂近世書寫碑志，則有資利，若朝廷之命，則有司存焉，待詔其職也。今與待詔爭利其可乎？力辭乃已。」蓋辭其可辭，其不可辭者不辭也。然後知蔡公之旨意如此。雖勛德之家，請於朝出敕令書者，亦辭之，不止一溫成碑而已。其清介有守，後世或未知之，故載於此。","sortOrder":27},
  {"id":"s_work_dtbt_50_28","chapterId":"ch_work_dtbt_50","text":"楊涉父子","sortOrder":28},
  {"id":"s_work_dtbt_50_29","chapterId":"ch_work_dtbt_50","text":"唐楊涉為人和厚恭謹。哀帝時，自吏部侍郎拜相。時朱全忠擅國，涉聞當為相，與家人相泣，謂其子凝式曰：「此吾家之不幸也，必為汝累。」後二年全忠篡逆，涉為押傳國寶使，凝式曰：「大人為唐宰相，而國家至此，不可謂之無過，况手持天子璽綬與人，雖保富貴，奈千載何，盍辭之？」涉大駭，曰：「汝滅吾族！」神色為之不寧者數日。此一楊涉也，方其且相，則對其子有不幸之語，及持國寶與逆賊，則駭其子勸止之請，一何前後之不相侔也？鄙夫患失，又懲白馬之禍，喪其良心，甘入「六臣」之列，其可羞也甚矣！凝式病其父失節，託於心疾，歷五代十二君，佯狂不仕，亦賢乎哉！","sortOrder":29},
  {"id":"s_work_dtbt_50_30","chapterId":"ch_work_dtbt_50","text":"佛胸卍字","sortOrder":30},
  {"id":"s_work_dtbt_50_31","chapterId":"ch_work_dtbt_50","text":"法苑珠林敍佛之初生雲：「開卍字於胸前，躡千輪於足下。」又占相部雲：「如來至真，常於胸前自然卍字，大人相者乃往古世蠲除穢濁不善行故。」予於夷堅丁志中載蔡京胸字，言「京死後四十二年遷葬，皮肉消化已盡，獨心胸上隱起一卍字，高二分許，如鐫刻所就。」正與此同。以大奸誤國之人，而有此祥，誠不可曉也。豈非天崩地坼，造化定數，故產此異物，以為宗社之禍邪！","sortOrder":31},
  {"id":"s_work_dtbt_50_32","chapterId":"ch_work_dtbt_50","text":"蘇渙詩","sortOrder":32},
  {"id":"s_work_dtbt_50_33","chapterId":"ch_work_dtbt_50","text":"杜子美贈蘇渙詩，序雲：「蘇大侍御渙，靜者也，旅寓江側，凡是不交州府之客，人事都絕久矣。肩輿江浦，忽訪老夫，請誦近詩，肯吟數首，才力素壯，詞句動人，涌思雷出，書篋幾杖之外，殷殷留金石聲。賦八韻記異，亦記老夫傾倒於蘇至矣。」詩有「再聞誦新作，突過黃初詩」之語。又有一篇寄裴道州幷呈蘇渙侍御雲：「附書與裴因示蘇，此生已媿須人扶。致君堯舜付公等，早據要路思捐軀。」其褒重之如此。唐藝文志，有渙詩一卷，雲：「渙少喜剽盜，善用白弩，巴蜀商人苦之，稱『白跖』，以比莊蹻。後折節讀書，進士及第。湖南崔瓘辟從事，繼走交、廣，與哥舒晃反，伏誅。」然則非所謂靜隱者也。渙在廣州作變律詩十九首，上廣府帥，其一曰：「養蠶為素絲，葉盡蠶不老。頃筐對空床，此意向誰道。一女不得織，萬夫受其寒。一夫不得意，四海行路難。禍亦不在大，禍亦不在先。世路險孟門，吾徒當勉旃。」其二曰：「毒蜂一巢成，高掛惡木枝。行人百步外，目斷魂為飛。長安大道邊，挾彈誰家兒？手持黃金丸，引滿無所疑。一中紛下來，勢若風雨隨。身如萬箭攢，宛轉送所之。徒有疾惡心，奈何不知幾！」讀此二詩，可以知其人矣。杜贈渙詩，名為記異，語意不與他等，厥有旨哉！","sortOrder":33},
  {"id":"s_work_dtbt_50_34","chapterId":"ch_work_dtbt_50","text":"歲後八日","sortOrder":34},
  {"id":"s_work_dtbt_50_35","chapterId":"ch_work_dtbt_50","text":"東方朔占書，歲後八日，一為鷄，二為犬，三為豕，四為羊，五為牛，六為馬，七為人，八為穀。謂其日晴，則所主之物育，陰則災。杜詩雲：「元日到人日，未有不陰時。」用此也。八日為穀，所係尤重，而人罕知者，故書之。","sortOrder":35},
  {"id":"s_work_dtbt_50_36","chapterId":"ch_work_dtbt_50","text":"門焉閨焉","sortOrder":36},
  {"id":"s_work_dtbt_50_37","chapterId":"ch_work_dtbt_50","text":"左氏傳好用「門焉」字，如「晉侯圍曹，門焉」，「齊侯圍龍，盧蒲就魁門焉」，「吳伐巢，吳子門焉」，「偪陽人啟門，諸侯之士門焉」。及「蔡公孫翩以兩矢門之」，「門於師之梁」，「門於陽州」之類，皆奇葩之語也。然公羊傳雲：「入其大門，則無人門焉者；入其閨，則無人閨焉者；上其堂，則無人焉。」又傑出有味。何休註「堂無人焉」之下曰：「但言焉，絕語辭，堂不設守視人，故不言焉者。」休之學可謂精切，能盡立言之深意。","sortOrder":37},
  {"id":"s_work_dtbt_50_38","chapterId":"ch_work_dtbt_50","text":"郡縣主婿官","sortOrder":38},
  {"id":"s_work_dtbt_50_39","chapterId":"ch_work_dtbt_50","text":"本朝宗室袒免親女出嫁，如婿係白身人，得文解者為將仕郎，否則承節、承信郎，妻雖死，夫為官如故。按唐貞元中，故懷澤縣主婿檢校贊善大夫竇克紹狀言：「臣頃以國親，超授寵祿，及縣主薨逝，臣官遂停。臣陪位出身，未授檢校官，自有本官，伏乞宣付所司，許取前銜婺州司戶參軍隨例調集。」詔：「許赴集，仍委所司比類前任正員官依資註擬。自今已後，郡縣主婿除丁憂外，有曾任正員官停檢校官俸料後者，准此處分。」乃知婿官不停者，恩厚於唐世多矣。紹興中，高士轟尚偽福國長公主，至觀察使。及公主事發誅死，猶得故官，可謂優渥。","sortOrder":39},
  {"id":"s_work_dtbt_50_40","chapterId":"ch_work_dtbt_50","text":"樂府詩引喻","sortOrder":40},
  {"id":"s_work_dtbt_50_41","chapterId":"ch_work_dtbt_50","text":"自齊、梁以來，詩人作樂府子夜四時歌之類，每以前句比興引喻，而後句實言以證之。至唐張祜、李商隱、溫庭筠、陸龜蒙，亦多此體，或四句皆然。今略書十數聯於策。其四句者，如「高山種芙蓉，復經黃檗塢。未得一蓮時，流離嬰辛苦。」「窗外山魈立，知渠腳不多。三更機底下，摸著是誰梭。」「淮上能無雨，回頭總是情。蒲帆渾未織，爭得一歡成。」其兩句者，如「風吹荷葉動，無夜不搖蓮。」「空織無經緯，求匹理自難。」「圍棋燒敗襖，著子故依然。」「理絲入殘機，何悟不成匹。」「攡門不安橫，無復相關意。」「黃檗向春生，苦心日日長。」「明燈照空局，悠然未有期。」「玉作彈棋局，中心最不平。」「翦刀橫眼底，方覺淚難裁。」「中劈庭前棗，教郎見赤心。」「千尋葶藶枝，爭奈長長苦。」「愁見蜘蛛織，尋思直到明。」「雙燈俱暗盡，奈許兩無由。」「三更書石闕，憶子夜啼悲。」「芙蓉腹裏萎，憐汝從心起。」「朝看暮牛跡，知是宿啼痕。」「梳頭入黃泉，分作兩死計。」「石闕生口中，銜悲不能語。」「桑蠶不作繭，晝夜長懸絲。」皆是也。龜蒙又有風人詩四首雲：「十萬全師出，遙知正憶君。一心如瑞麥，長作兩歧分。」「破檗供朝爨，須知是苦辛。曉天窺落宿，誰識獨醒人。」「旦日思雙履，明時願早諧。丹青傳四瀆，難寫是秋懷。」「聞道更新幟，多應廢舊期。征衣無伴搗，獨處自然悲。」皮日休和其三章雲：「刻石書離恨，因成別後悲。莫言春繭薄，猶有萬重思。」「鏤出容刀飾，親逢巧笑難。目中騷客珮，爭奈即闌幹。」「江上秋聲起，從來浪得名。逆風猶掛席，苦不會凡情。」劉采春所唱雲：「不是廚中串，爭知炙裏心。井邊銀釧落，展轉恨還深。」「篝（簳下右換餘)蠟為紅燭，情知不自由。細絲斜結網，爭奈眼相鈎。」尤為明白。七言亦間有之，如「東邊日出西邊雨，道是無情又有情。」「玲瓏骰子安紅豆，入骨相思知也無？」「合歡桃核真堪恨，裏許元來別有人。」是也。近世鄙詞，如一落索數闋，蓋效此格。語意亦新工，恨太俗耳，然非才士不能為。世傳東坡一絕句雲：「蓮子擘開須見薏，楸枰著盡更無棋。破衫却有重縫處，一飯何曾忘却匙。」蓋是文與意並見一句中，又非前比也。集中不載。","sortOrder":41},
  {"id":"s_work_dtbt_51_1","chapterId":"ch_work_dtbt_51","text":"始予作容齋隨筆，首尾十八年，二筆十三年，三筆五年，而四筆之成，不費一歲。身益老而著書益速，蓋有其說。曩自越府歸，謝絕外事，獨弄筆紀述之習，不可掃除。故搜采異聞，但緒夷堅志，於議論雌黃，不復關抱。而稚子櫰，每見夷堅滿紙，輒曰：「隨筆、夷堅，皆大人素所遊戲。今隨筆不加益，不應厚於彼而薄於此也。」日日立案旁，必俟草一則乃退。重逆其意，則裒所憶而書之。櫰嗜讀書，雖就寢猶置一編枕畔，旦則與之俱興。而天嗇其付付，年且弱冠，聰明殊未開，以彼其勤，殆必有日。丈夫愛憐少子，此乎見之。於是占抒為序，幷獎其志雲。慶元三年九月二十四日序。","sortOrder":1},
  {"id":"s_work_dtbt_52_1","chapterId":"ch_work_dtbt_52","text":"卷第一(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_52_2","chapterId":"ch_work_dtbt_52","text":"孔廟位次","sortOrder":2},
  {"id":"s_work_dtbt_52_3","chapterId":"ch_work_dtbt_52","text":"自唐以來，相傳以孔門高弟顏淵至子夏為十哲，故坐祀於廟堂上。其後升顏子配享，則進曾子於堂，居子夏之次以補其闕。然顏子之父路、曾子之父點，乃在廡下從祀之列，子處父上，神靈有知，何以自安？所謂子雖齊聖，不先父食，正謂是也。又孟子配食與顏子並，而其師子思、子思之師曾子亦在下。此兩者於禮、於義，實為未然，特相承既久，莫之敢議耳。","sortOrder":3},
  {"id":"s_work_dtbt_52_4","chapterId":"ch_work_dtbt_52","text":"周三公不特置","sortOrder":4},
  {"id":"s_work_dtbt_52_5","chapterId":"ch_work_dtbt_52","text":"周成王董正治官，立太師、太傅、太保，茲惟三公，而雲：「官不必備，惟其人。」以書傳考之，皆兼領六卿，未嘗特置也。周公既為師，然猶位冢宰，尚書所載召公以太保領冢宰，芮伯為司徒，彤伯為宗伯，畢公以太師領司馬，衞侯為司寇，毛公以太傅領司空是已。其所次第惟以六卿為先後，而師傅之尊乃居太保下也。","sortOrder":5},
  {"id":"s_work_dtbt_52_6","chapterId":"ch_work_dtbt_52","text":"周公作金縢","sortOrder":6},
  {"id":"s_work_dtbt_52_7","chapterId":"ch_work_dtbt_52","text":"尚書孔氏所傳五十九篇皆有序，其出於史官者不言某人作，如虞書五篇，紀一時君臣吁咈都俞及識其政事，如說命、武成、顧命、康王之誥、召誥自「惟二月既望」至「越自乃御事」、洛誥自「戊辰王在新邑」至篇終、蔡仲之命自「惟周公位冢宰」至「邦之蔡」皆然。如指言某人所作，則伊尹作伊訓、太甲、鹹有一德，盤庚三篇，周公作大誥、康誥、酒誥、梓材、多士、無逸、君奭、多方、立政是也。惟金縢之篇，首尾皆敍事，而直以為周公作。按此篇除冊祝三王外，餘皆周史之詞，如「公乃自以為功」、「公歸納冊」、「公將不利於孺子」、「公乃為詩以貽王」、「王亦未敢誚公」、「公命我勿敢言」、「天動威以彰周公之德」、「公勤勞王家」之語，「出郊」、「反風」之異，决非周公所自為，今不復可質究矣。","sortOrder":7},
  {"id":"s_work_dtbt_52_8","chapterId":"ch_work_dtbt_52","text":"雲夢澤","sortOrder":8},
  {"id":"s_work_dtbt_52_9","chapterId":"ch_work_dtbt_52","text":"雲夢，楚澤藪也，列於周禮職方氏。鄭氏曰：「在華容。」漢志有雲夢官。然其實雲也、夢也，各為一處。禹貢所書：「雲土夢作乂。」註雲：「在江南。」惟左傳得其詳，如（雲阝）夫人棄子文於夢中。註雲：「夢，澤名，在江夏安陸縣城東南。」楚子田江南之夢。註雲：「楚之雲、夢，跨江南北。」楚子濟江入於雲中。註：「入雲澤中，所謂江南之夢。」然則，雲在江之北，夢在其南也。上林賦：「楚有七澤，嘗見其一，名曰雲夢，特其小小者耳，方九百里。」此乃司馬長卿夸言。今為縣，隸德安，詢諸彼人，已不能的指疆域。職方氏以「夢」為「瞢」，前漢敍傳：子文投於夢中，音皆同。","sortOrder":9},
  {"id":"s_work_dtbt_52_10","chapterId":"ch_work_dtbt_52","text":"關雎不同","sortOrder":10},
  {"id":"s_work_dtbt_52_11","chapterId":"ch_work_dtbt_52","text":"關雎為國風首，毛氏列之於三百篇之前。大序雲：「後妃之德也。」而魯詩雲：「後夫人鷄鳴佩玉去君所，周康王後不然，故詩人嘆而傷之。」後漢皇後紀序：「康王晏朝，關雎作諷。」蓋用此也。顯宗永平八年詔雲：「昔應門失守，關雎刺世。」註引春秋說題辭曰：「人主不正，應門失守，故歌關雎以感之。」宋均雲：「應門，聽政之處也。言不以政事為務，則有宣淫之心。關雎樂而不淫，思得賢人與之共化，修應門之政者也。」薛氏韓詩章句曰：「詩人言雎鳩貞潔敬匹，以聲相求，隱蔽於無人之處。故人君退朝，入於私宮，後妃御見有度，應門擊柝，鼓人上堂，退反燕處，體安志明。今時大人內傾於色，賢人見其萌，故詠關雎之說淑女正容儀以刺時。」三說不同如此。黍離之詩列於王國風之首，周大夫所作也，而齊詩以為衞宣公之子壽，閔其兄伋之且見害，作憂思之詩，黍離之詩是也。此說尤為可議。","sortOrder":11},
  {"id":"s_work_dtbt_52_12","chapterId":"ch_work_dtbt_52","text":"迷癡厥撥","sortOrder":12},
  {"id":"s_work_dtbt_52_13","chapterId":"ch_work_dtbt_52","text":"柔詞諂笑，專取容悅，世俗謂之「迷癡」，亦曰「迷嬉」。中心有愧見諸顏面者，謂之「緬靦」。舉措脫落，觸事乖忤者，謂之「厥撥」。雖為俚言，然其說皆有所本。列子雲：「墨杘、單至、嘽咺、憋敷心，四人相與遊於世。」又雲：「眠娗、諈諉、勇敢、怯疑，四人亦相與遊。」張湛註雲：「墨音眉，杘敕夷反，方言：江淮之間謂之無賴；眠音緬，娗音殄，方言：欺謾之語也。郭璞雲：謂以言相輕嗤弄也。」所釋雖不同，然大略具是矣。曲禮：「衣毋撥，足毋蹶。」鄭氏註雲：「撥，發揚貌。蹶，行遽貌。」大抵亦指其荒率也。","sortOrder":13},
  {"id":"s_work_dtbt_52_14","chapterId":"ch_work_dtbt_52","text":"三館祕閣","sortOrder":14},
  {"id":"s_work_dtbt_52_15","chapterId":"ch_work_dtbt_52","text":"國朝儒館仍唐製，有四：曰昭文館，曰史館，曰集賢院，曰祕閣。率以上相領昭文大學士，其次監修國史，其次領集賢。若只兩相，則首廳兼國史。唯祕閣最低，故但以兩製判之。四局各置直官，均謂之館職，皆稱學士。其下則為校理、檢討、校勘，地望清切，非名流不得處。范景仁為館閣校勘，當遷校理，宰相龐籍言：「范鎮有異才，恬於進取。」乃除直祕閣。司馬公作詩賀之曰：「延閣屹中天，積書雲漢連。神宗重其選，(謂太宗也。)國士比為仙。玉檻鈎陳上，丹梯北斗邊。帝容瞻日角，宸翰照星躔。職秩曾無貴，光華在得賢。」其重如此。自熙寧以來，或頗用賞勞。元豐官製行，不置昭文、集賢，以史館入著作局，而直祕閣只為貼職。至崇寧、政、宣以處大臣子弟姻戚，其濫及於錢穀文俗吏，士大夫不復貴重。然除此職者必詣館下拜閣，乃具盛筵，邀見在三館者宴集，秋日暴書宴，皆得預席，若餘日則不許至，隨筆有館職名存一則雲。","sortOrder":15},
  {"id":"s_work_dtbt_52_16","chapterId":"ch_work_dtbt_52","text":"亭榭立名","sortOrder":16},
  {"id":"s_work_dtbt_52_17","chapterId":"ch_work_dtbt_52","text":"立亭榭名最易蹈襲，既不可近俗，而務為奇澀亦非是。東坡見一客雲近看晉書，問之曰：「曾尋得好亭子名否？」蓋謂其難也。秦楚材在宣城，於城外並江作亭，目之曰「知有」。用杜詩「已知出郭少塵事，更有澄江消客愁」之句也。王仲衡在會稽，於後山作亭，目之曰「白涼」。亦用杜詩「越女天下白，鑑湖五月涼」之句。二者可謂甚新，然要為未當。廬山一寺中有亭頗幽勝，或標之曰：「不更歸」，取韓詩末句，亦可笑也。","sortOrder":17},
  {"id":"s_work_dtbt_52_18","chapterId":"ch_work_dtbt_52","text":"十十錢","sortOrder":18},
  {"id":"s_work_dtbt_52_19","chapterId":"ch_work_dtbt_52","text":"市肆間交易論錢陌者，雲十十錢。言其足數滿百無蹺減也。其語至俗，然亦有所本。後漢書襄楷傳引宮崇所獻神書，其太平經興帝王篇雲：「開其玉戶，施種於中，比若春種於地也，十十相應和而生。其施不以其時，比若十月種物於地也，十十盡死，固無生者。」其書不傳於今，唐章懷太子註釋之時，尚猶存也。此所謂十十，蓋言十種十生無一失耳，其盡死之義亦然，與錢陌之事殊，然其字則同也。","sortOrder":19},
  {"id":"s_work_dtbt_52_20","chapterId":"ch_work_dtbt_52","text":"犀舟","sortOrder":20},
  {"id":"s_work_dtbt_52_21","chapterId":"ch_work_dtbt_52","text":"張衡應間雲：「犀舟勁楫。」後漢註引前書：「羌戎弓矛之兵，器不犀利。」音義曰：「今俗謂刀兵利為犀。犀，堅也。」「犀舟」，甚新奇，然為文者，未嘗用，亦慮予所見之不博也。","sortOrder":21},
  {"id":"s_work_dtbt_52_22","chapterId":"ch_work_dtbt_52","text":"畢仲遊二書","sortOrder":22},
  {"id":"s_work_dtbt_52_23","chapterId":"ch_work_dtbt_52","text":"元祐初，司馬溫公當國，盡改王荊公所行政事，士大夫言利害者以千百數，聞朝廷更化，莫不歡然相賀，唯畢仲遊一書，究盡本末。其略雲：「昔安石以興作之說動先帝，而患財之不足也，故凡政之可以得民財者無不用。蓋散青苗、置市易、斂役錢、變鹽法者，事也，而欲興作患不足者，情也。苟未能杜其興作之情，而徒欲禁其散斂變置之事，是以百說而百不行。今遂欲廢青苗、罷市易、蠲役錢、去鹽法，凡號為財利而傷民者，一掃而更之，則向來用事於新法者，必不喜矣。不喜之人，必不但曰青苗不可廢，市易不可罷，役錢不可蠲，鹽法不可去，必探不足之情，言不足之事，以動上意，雖致石人而使聽之，猶將動也。如是則廢者可復散，罷者可復置，蠲者可復斂，去者可復存矣。則不足之情可不預治哉！為今之策，當大舉天下之計，深明出入之數，以諸路所積之錢粟，一歸地官，使經費可支二十年之用。數年之間，又將十倍於今日。使天子曉然知天下之餘於財也，則不足之論不得陳於前，然後所謂新法者，始可永罷而不復行矣。昔安石之居位也，中外莫非其人，故其法能行。今欲救前日之敝，而左右侍從職司使者，十有七八皆安石之徒，雖起二三舊臣，用六七君子，然累百之中存其十數，烏在其勢之可為也！勢未可為而欲為之，則青苗雖廢將復散，況未廢乎？市易雖罷且復置，況未罷乎？役錢、鹽法亦莫不然。以此救前日之敝，如人久病而少間，其父兄子弟喜見顏色，而未敢賀者，意其病之在也。」","sortOrder":23},
  {"id":"s_work_dtbt_52_24","chapterId":"ch_work_dtbt_52","text":"先是東坡公在館閣，頗因言語文章，規切時政，仲遊憂其及禍，貽書戒之曰：「孟軻不得已而後辯，孔子欲無言。古人所以精謀極慮，固功業而養壽命者，未嘗不出乎此。君自立朝以來，禍福利害繫身者未嘗言，顧直惜其言爾。夫言語之累，不特出口者為言，其形於詩歌、贊於賦頌、託於碑銘、著於序記者，亦言也。今知畏於口而未畏於文，是其所是，則見是者喜，非其所非，則蒙非者怨。喜者未能濟君之謀，而怨者或已敗君之事矣！天下論君之文，如孫臏之用兵、扁鵲之醫疾，固所指名者矣，雖無是非之言，猶有是非之疑。又況其有耶？官非諫臣，職非御史，而非人所未非，是人所未是，危身觸諱以遊其間，殆由抱石而救溺也。」","sortOrder":24},
  {"id":"s_work_dtbt_52_25","chapterId":"ch_work_dtbt_52","text":"二公得書聳然，竟如其慮。予頃修史時，因得其集，讀二書思欲為之表見，故官雖不顯，亦為之立傳雲。","sortOrder":25},
  {"id":"s_work_dtbt_52_26","chapterId":"ch_work_dtbt_52","text":"列子與佛經相參","sortOrder":26},
  {"id":"s_work_dtbt_52_27","chapterId":"ch_work_dtbt_52","text":"張湛序列子雲：「其書大略明羣有以至虛為宗，萬品以終滅為驗，神惠以凝寂常全，想念以著物自喪，生覺與夢化等情。所明往往與佛經相參。」予讀天瑞篇載林類答子貢之言曰：「死之與生，一往一反。故死於是者，安知不生於彼？故吾知其不相若矣，吾又安知吾今之死不愈昔之生乎？」此一節所謂與佛經相參者也。又雲：「商太宰問孔子：『三王五帝三皇聖者歟？』孔子皆曰：『弗知。』太宰曰：『然則孰者為聖？』孔子曰：『西方之人有聖者焉，不治而不亂，不言而自信，不化而自行，蕩蕩乎民無能名焉，丘疑其為聖。弗知真為聖歟？真不聖歟？』」其後論者以為列子所言，乃佛也，寄於孔子雲。","sortOrder":27},
  {"id":"s_work_dtbt_52_28","chapterId":"ch_work_dtbt_52","text":"韋孟詩乖疎","sortOrder":28},
  {"id":"s_work_dtbt_52_29","chapterId":"ch_work_dtbt_52","text":"漢書韋賢傳載韋孟詩二篇及其孫玄成詩一篇，皆深有三百篇風致，但韋孟諷諫雲：「肅肅我祖，國自豕韋。總齊羣邦，以翼大商。至於有周，歷世會同。王赧聽譖，實絕我邦。我邦既絕，厥政斯逸。賞罰之行，非繇王室。庶尹羣後，靡扶靡衞。五服崩離，宗周以隊。」應劭曰：「王赧聽讒受譖，絕豕韋氏。自是政教逸漏，不由王者。」觀孟之自敍乃祖，而乖疎如是，周至赧王僅存七邑，救亡不暇，豈能絕侯邦乎？周之積微久矣，非因絕豕韋一國，然後五服崩離也。其妄固不待攻，而應劭又從而實之，尤為可笑。左傳書范宣子之言曰：「匄之祖在商為豕韋氏，在周為唐杜氏。」杜預曰：「豕韋國於東郡白馬縣，殷末國於唐，周成王滅之。」此最可證，惜顏師古之不引用也。","sortOrder":29},
  {"id":"s_work_dtbt_52_30","chapterId":"ch_work_dtbt_52","text":"匡衡守正","sortOrder":30},
  {"id":"s_work_dtbt_52_31","chapterId":"ch_work_dtbt_52","text":"漢元帝時，貢禹奏言：天子七廟，親盡之廟宜毀，及郡國廟不應古禮，宜正定。天子下其議，未及施行而禹卒。後乃下詔先罷郡國廟，其親盡寢園，皆無復修。已而上寢疾，夢祖宗譴罷郡國廟。詔問丞相匡衡，議欲復之。衡深言不可。上疾久不平，衡皇恐，禱高祖、孝文、孝武廟曰：「親廟宜一居京師，今皇帝有疾不豫，乃夢祖宗見戒以廟，皇帝悼懼，即詔臣衡復修立，如誠非禮義之中，違祖宗之心，咎盡在臣衡，當受其殃。」又告謝毀廟曰：「遷廟合祭，久長之策，今皇帝乃有疾，願復修立承祀。臣衡等鹹以為禮不得，如不合諸帝後之意，罪盡在臣衡等，當受其咎。今詔中朝臣具復毀廟之文，臣衡以為天子之祀，義有所斷，無所依緣，以作其文。事如失措，罪乃在臣衡。」","sortOrder":31},
  {"id":"s_work_dtbt_52_32","chapterId":"ch_work_dtbt_52","text":"予按衡平生佞諛，專附石顯以取大位，而此一節獨據經守禮，其禱廟之文，殆與金縢之冊祝相似，而不為後世所稱述，漢史又不書於本傳，憎而知其善可也。郊祀志，南山巫祠秦中。秦中者，二世皇帝也。以其彊死，魂魄為厲，故祠之。成帝時，匡衡奏罷之，亦可書。","sortOrder":32},
  {"id":"s_work_dtbt_52_33","chapterId":"ch_work_dtbt_52","text":"西極化人","sortOrder":33},
  {"id":"s_work_dtbt_52_34","chapterId":"ch_work_dtbt_52","text":"列子載周穆王時，西極之國有化人來，王敬之若神。化人謁王同遊，王執化人之袪，騰而上者中天乃止，暨及化人之宮，自以居數十年，不思其國。復謁王同遊，意迷精喪，請化人求還。既寤，所坐猶曏者之處，侍御猶曏者之人。視其前，則酒未清、肴未昲。王問所從來，左右曰：「王默存耳。」穆王自失者三月。復問化人，化人曰：「吾與王神遊也，形奚動哉？」予然後知唐人所著南柯太守、黃粱夢、櫻桃、青衣之類，皆本乎此。","sortOrder":34},
  {"id":"s_work_dtbt_52_35","chapterId":"ch_work_dtbt_52","text":"詔令不可輕出","sortOrder":35},
  {"id":"s_work_dtbt_52_36","chapterId":"ch_work_dtbt_52","text":"人君一話一言不宜輕發，况於詔令形播告者哉！漢光武初即位，既立郭氏為皇後矣，時陰麗華為貴人，帝欲崇以尊位，後固辭，以郭氏有子，終不肯當。建武九年，遂下詔曰：「吾以貴人有母儀之美，宜立為後，而固辭不敢當，列於媵妾。朕嘉其義讓，許封諸弟。」乃追爵其父及弟為侯，皆前世妃嬪所未有。至十七年，竟廢郭後及太子彊，而立貴人為後。蓋九年之詔既行，主意移奪，已見之矣。郭後豈得安其位乎？","sortOrder":36},
  {"id":"s_work_dtbt_52_37","chapterId":"ch_work_dtbt_52","text":"戰國策","sortOrder":37},
  {"id":"s_work_dtbt_52_38","chapterId":"ch_work_dtbt_52","text":"劉向序戰國策，言其書錯亂相揉，莒本字多誤脫為半字，以趙為肖，以齊為立，如此類者多。予按今傳於世者，大抵不可讀，其韓非子、新序、說苑、韓詩外傳、高士傳、史記索隱、太平御覽、北堂書鈔、藝文類聚諸書所引用者，多今本所無。向博極羣書，但擇焉不精，不止於文字脫誤而已。惟太史公史記所采之事九十有三，則明白光豔，悉可稽考，視向為有間矣！","sortOrder":38},
  {"id":"s_work_dtbt_52_39","chapterId":"ch_work_dtbt_52","text":"范曄漢志","sortOrder":39},
  {"id":"s_work_dtbt_52_40","chapterId":"ch_work_dtbt_52","text":"沈約作宋書謝儼傳曰：「范曄所撰十志，一皆託儼。搜撰垂畢，遇曄敗，悉蠟以覆車。宋文帝令丹陽尹徐湛之就儼尋求，已不復得，一代以為恨。其志今闕。」曄本傳載曄在獄中與諸生姪書曰：「既造後漢，欲遍作諸志，前漢所有者悉令備。雖事不必多，且使見文得盡；又欲因事就卷內發論，以正一代得失，意復不果。」此說與儼傳不同，然儼傳所雲乃范紀第十卷公主註中引之，今宋書却無，殊不可曉。劉昭註補志三十卷，至本朝乾興元年，判國子監孫奭始奏以備前史之闕，故淳化五年監中所刊後漢書凡九十卷，惟帝後紀十卷，列傳八十卷，而無志雲。新唐書藝文志：「劉昭補註後漢書五十八卷。」不知昭為何代人。所謂志三十卷，當在其中也。","sortOrder":40},
  {"id":"s_work_dtbt_52_41","chapterId":"ch_work_dtbt_52","text":"繕修犯土","sortOrder":41},
  {"id":"s_work_dtbt_52_42","chapterId":"ch_work_dtbt_52","text":"今世俗營建宅舍，或小遭疾厄，皆雲犯土。故道家有謝土司章醮之文。按後漢書來歷傳所載：「安帝時皇太子驚病不安，避幸乳母野王君王聖舍。太子廚監邴吉以為聖舍新繕修，犯土禁，不可久御。」然則古有其說矣。","sortOrder":42},
  {"id":"s_work_dtbt_52_43","chapterId":"ch_work_dtbt_52","text":"容齋四筆","sortOrder":43},
  {"id":"s_work_dtbt_53_1","chapterId":"ch_work_dtbt_53","text":"卷第二(二十則)","sortOrder":1},
  {"id":"s_work_dtbt_53_2","chapterId":"ch_work_dtbt_53","text":"諸家經學興廢","sortOrder":2},
  {"id":"s_work_dtbt_53_3","chapterId":"ch_work_dtbt_53","text":"稚子問漢儒所傳授諸經，各名其家，而今或存或不存，請書其本末為四筆粍t。乃為采摭班史及陸德明經典釋文幷他書，刪取綱要，詳載於此。","sortOrder":3},
  {"id":"s_work_dtbt_53_4","chapterId":"ch_work_dtbt_53","text":"周易傳自商瞿始，至漢初，田何以之顓門。其後為施、孟喜、梁丘賀之學，又有京房、費直、高相三家。至後漢，高氏已微，晉永嘉之亂，梁丘之易亡。孟、京、費氏人無傳者，唯鄭康成、王弼所註行於世。江左中興，欲置鄭易博士，不果立，而弼猶為世所重。韓康伯等十人並註繫辭，今唯韓傳。","sortOrder":4},
  {"id":"s_work_dtbt_53_5","chapterId":"ch_work_dtbt_53","text":"尚書自漢文帝時伏生得二十九篇，其後為大小夏侯之學。古文者，武帝時出於孔壁，凡五十九篇，詔孔安國作傳，遭巫蠱事，不獲以聞，遂不列於學官，其本殆絕，是以馬、鄭、杜預之徒皆謂之逸書。王肅嘗為註解，至晉元帝時，孔傳始出，而亡舜典一篇，乃取肅所註堯典，分以續之，學徒遂盛。及唐以來，馬、鄭、王註遂廢，今以孔氏為正雲。","sortOrder":5},
  {"id":"s_work_dtbt_53_6","chapterId":"ch_work_dtbt_53","text":"詩自子夏之後，至漢興，分而為四，魯申公曰魯詩，齊轅固生曰齊詩，燕韓嬰曰韓詩，皆列博士。毛詩者出於河間人大毛公，為之故訓，以授小毛公，為獻王博士，以不在漢朝，不列於學，鄭衆、賈逵、馬融皆作詩註，及鄭康成作箋，三家遂廢。齊詩久亡，魯詩不過江東，韓詩雖在，人無傳者，唯毛詩鄭箋獨立國學，今所遵用。","sortOrder":6},
  {"id":"s_work_dtbt_53_7","chapterId":"ch_work_dtbt_53","text":"漢高堂生傳士禮十七篇，即今之儀禮也。古禮經五十六篇，後蒼傳十七篇，曰後氏曲臺記，所餘三十九篇名為逸禮。戴德刪古禮二百四篇為八十五篇，謂之大戴禮，戴聖又刪為四十九篇，謂之小戴禮。馬融、盧植考諸家異同，附戴聖篇章，去其煩重及所缺略而行於世，即今之禮記也。王莽時，劉歆始建立周官經，以為周禮，在三禮中最為晚出。","sortOrder":7},
  {"id":"s_work_dtbt_53_8","chapterId":"ch_work_dtbt_53","text":"左氏為春秋傳，又有公羊、穀梁、鄒氏、夾氏。鄒氏無師，夾氏無書。公羊興於景帝時，穀梁盛於宣帝時，而左氏終西漢不顯。迨章帝乃令賈逵作訓詁，自是左氏大興，二傳漸微矣。","sortOrder":8},
  {"id":"s_work_dtbt_53_9","chapterId":"ch_work_dtbt_53","text":"古文孝經二十二章，世不復行，只用鄭註十八章本。","sortOrder":9},
  {"id":"s_work_dtbt_53_10","chapterId":"ch_work_dtbt_53","text":"論語三家：魯論語者，魯人所傳，即今所行篇次是也；齊論語者，齊人所傳，凡二十二篇；古論語者，出自孔壁，凡二十一篇。各有章句。魏何晏集諸家之說為集解，今盛行於世。","sortOrder":10},
  {"id":"s_work_dtbt_53_11","chapterId":"ch_work_dtbt_53","text":"漢人姓名","sortOrder":11},
  {"id":"s_work_dtbt_53_12","chapterId":"ch_work_dtbt_53","text":"西漢名人如公孫弘、董仲舒、朱買臣、丙吉、王褒、貢禹，皆有異世與之同姓名者。戰國策及呂氏春秋，齊有公孫弘，與秦王、孟嘗君言者。明帝時，又有幽州從事公孫弘，交通楚王英，見於虞延傳。高祖時，又有謁者貢禹。梁元帝時，有武昌太守朱買臣、尚書左僕射王褒。後漢安帝時，有太子廚監邴吉。南齊武帝之子巴東王子響為荊州刺史，要直閣將軍董蠻與同行，蠻曰：「殿下癲如雷，敢相隨耶？」子響曰：「君敢出此語，亦復奇癲。」上聞而不悅曰：「人名『蠻』，復何容得醞藉。」乃改為仲舒。謂曰：「今日仲舒，何如昔日仲舒？」答曰：「昔日仲舒，出自私庭，今日仲舒，降自先帝，以此言之，勝昔遠矣。」然此人後不復見。","sortOrder":12},
  {"id":"s_work_dtbt_53_13","chapterId":"ch_work_dtbt_53","text":"輕浮稱謂","sortOrder":13},
  {"id":"s_work_dtbt_53_14","chapterId":"ch_work_dtbt_53","text":"南齊陸慧曉立身清肅，為諸王長史行事，僚佐以下造詣，必起迎之。或曰：「長史貴重，不宜妄自謙屈。」答曰：「我性惡人無禮，不容不以禮處人。」未嘗卿士大夫，或問其故，慧曉曰：「貴人不可卿，而賤者乃可卿，人生何容立輕重於懷抱！」終身常呼人位。今世俗浮薄少年，或身為卑官，而與尊者言話，稱其儕流，必曰「某丈」。談其所事牧伯監司亦然。至於當他人父兄尊長之前，語及其子孫甥壻，亦雲「某丈」。或妄稱宰相執政貴人之字。皆大不識事分者，習慣以然，元非簡傲也。予常以戒兒輩雲。","sortOrder":14},
  {"id":"s_work_dtbt_53_15","chapterId":"ch_work_dtbt_53","text":"鬼穀子書","sortOrder":15},
  {"id":"s_work_dtbt_53_16","chapterId":"ch_work_dtbt_53","text":"鬼穀子與蘇秦、張儀書曰：「二足下功名赫赫，但春華至秋，不得久茂。今二子好朝露之榮，忽長久之功；輕喬、松之永延，貴一旦之浮爵。夫女愛不極席，男歡不畢輪，痛哉夫君！」戰國策楚江乙謂安陵君曰：「以財交者，財盡而交絕；以色交者，華落而愛渝。是以嬖女不敝席，寵臣不敝軒。」呂不韋說華陽夫人曰：「以色事人者，色衰而愛弛。」詩氓之序曰：「華落色衰，復相棄背。」是諸說大抵意同，皆以色而為喻。士之嗜進而不知自反者，尚監茲哉！","sortOrder":16},
  {"id":"s_work_dtbt_53_17","chapterId":"ch_work_dtbt_53","text":"有美堂詩","sortOrder":17},
  {"id":"s_work_dtbt_53_18","chapterId":"ch_work_dtbt_53","text":"東坡在杭州作有美堂會客詩，頷聯雲：「天外黑風吹海立，浙東飛雨過江來。」讀者疑海不能立，黃魯直曰：蓋是為老杜所誤，因舉三大禮賦朝獻太清宮雲「九天之雲下垂，四海之水皆立」以告之。二者皆句語雄峻，前無古人。坡和陶停雲詩有「雲屯九河，雪立三江」之句，亦用此也。","sortOrder":18},
  {"id":"s_work_dtbt_53_19","chapterId":"ch_work_dtbt_53","text":"張天覺小簡","sortOrder":19},
  {"id":"s_work_dtbt_53_20","chapterId":"ch_work_dtbt_53","text":"張天覺熙寧中為渝州南川宰。章子厚經製夔夷，狎侮州縣吏，無人敢與共語。部使者念獨張可亢之，檄至夔。子厚詢人才，使者以告，即呼入同食，張著道士服，長揖就坐。子厚肆意大言，張隨機折之，落落出其上，子厚大喜，延為上客。歸而薦諸王介甫，遂得召用。政和六年，張在荊南，與子厚之子致平一帖雲：「老夫行年七十有四，日閱佛書四五卷，早晚食米一升、（麥丏）五兩、肉八兩，魚、酒佐之，以此為常，亦不服暖藥，唯以呼吸氣晝夜合天度而已。數數夢見先相公，語論如平生，豈其人在天仙間，而老夫定中神遊或遇之乎？嗟乎，安得奇男子如先相公者，一快吾胸中哉！」此帖藏致平家，其曾孫簡刻諸石。予今年亦七十四歲，姪孫偲於長興得墨本以相示，聊記之雲。","sortOrder":20},
  {"id":"s_work_dtbt_53_21","chapterId":"ch_work_dtbt_53","text":"城狐社鼠","sortOrder":21},
  {"id":"s_work_dtbt_53_22","chapterId":"ch_work_dtbt_53","text":"城狐不灌，社鼠不燻。謂其所棲穴者得所憑依，此古語也，故議論者率指人君左右近習為城狐社鼠。予讀說苑所載孟嘗君之客曰：「狐者人之所攻也，鼠者人之所燻也。臣未嘗見稷狐見攻，社鼠見燻，何則？所託者然也。」稷狐之字，甚奇且新。","sortOrder":22},
  {"id":"s_work_dtbt_53_23","chapterId":"ch_work_dtbt_53","text":"用兵為臣下利","sortOrder":23},
  {"id":"s_work_dtbt_53_24","chapterId":"ch_work_dtbt_53","text":"富公奉使契丹，虜主言欲舉兵。公曰：「北朝與中國通好，則人主專其利，而臣下無所獲。若用兵則利歸臣下，而人主任其禍。故北朝羣臣爭勸舉兵者，此皆其自謀，非國計也。勝負未可知，就使其勝，所亡士馬，羣臣當之歟？抑人主當之歟？」是時，語錄傳於四方，蘇明允讀至此，曰：「此一段議論，古人有之否？」東坡年未十歲，在傍對曰：「記得嚴安上書雲：『今徇南夷，朝夜郎，略薉州，建城邑，深入匈奴，燔其龍城，議者美之，此人臣之利，非天下之長策也。』正是此意。」明允以為然。予又記魏太武時，南邊諸將表稱宋人大嚴，將入寇，請先其未發逆擊之。魏公卿皆以為當。崔伯深曰：「朝廷羣臣及西北守將，從陛下征伐，西平赫連，北破蠕蠕，多獲美女珍寶。南邊諸將聞而慕之，亦欲南鈔以取資財。皆營私計，為國生事，不可從也。」魏主乃止。其論亦然。","sortOrder":24},
  {"id":"s_work_dtbt_53_25","chapterId":"ch_work_dtbt_53","text":"志文不可冗","sortOrder":25},
  {"id":"s_work_dtbt_53_26","chapterId":"ch_work_dtbt_53","text":"東坡為張文定公作墓志銘，有答其子厚之一書雲：「志文路中已作得大半，到此百冗未絕筆，計得十日半月乃成。然書大事略小節，已有六千餘字，若纖悉盡書，萬字不了，古無此例也。知之知之。」蓋當時恕之意但欲務多耳。又一帖雲：「志文謁告數日方寫得了，謹遣持納。衰病眼眩，辭翰皆不佳，不知可用否？」今志文正本凡七千一百字，銘詩百六十字雲。予鄉士作一列大夫小郡守行狀九千言，衢州士人詣闕上書二萬言，使讀之者豈不厭倦，作文者宜戒之。坡帖藏梁氏竹齋，趙晉臣鐫石於湖南憲司楚觀。","sortOrder":26},
  {"id":"s_work_dtbt_53_27","chapterId":"ch_work_dtbt_53","text":"趙殺鳴犢","sortOrder":27},
  {"id":"s_work_dtbt_53_28","chapterId":"ch_work_dtbt_53","text":"漢書劉輔傳：「穀永等上書曰：『趙簡子殺其大夫鳴犢，孔子臨河而還。』」張晏註曰：「簡子欲分晉國，故先殺鳴犢，又聘孔子。孔子聞其死，至河而還也。」顏師古曰：「戰國策說二人姓名雲：鳴犢、鐸犨。而史記及古今人表並以為鳴犢、竇犨。蓋『鐸』、『犢』及『竇』，其聲相近，故有不同耳。今永等指鳴犢一人，不論竇犨也。」韓退之將歸操亦雲：「孔子之趙，聞殺鳴犢作。」予按今本史記孔子世家，乃以為竇鳴犢、舜華。說苑權謀篇雲：「晉有澤鳴、犢犨。」其不同如此。","sortOrder":28},
  {"id":"s_work_dtbt_53_29","chapterId":"ch_work_dtbt_53","text":"五帝官天下","sortOrder":29},
  {"id":"s_work_dtbt_53_30","chapterId":"ch_work_dtbt_53","text":"漢蓋寬饒奏封事，引韓氏易傳言：「五帝官天下，三王家天下，家以傳子，官以傳賢，若四時之運，成功者去。」坐指意欲求禪而死。故或雲自後稱天子為「官家」，蓋出於此。今世無韓氏易，諸家註釋漢書，皆無一語。惟說苑至公篇雲：「秦始皇帝既吞天下，召羣臣議：五帝禪賢，三王世繼，孰是？博士鮑令之對曰：『天下官，則選賢是也；天下家，則世繼是也。故五帝以天下為官，三王以天下為家。』始皇帝嘆曰：『吾德出於五帝，吾將官天下，誰可使代我後者！』」此說可以為證，輒記之以補漢註之缺。蔣濟萬機論亦有官天下、家天下之語。","sortOrder":30},
  {"id":"s_work_dtbt_53_31","chapterId":"ch_work_dtbt_53","text":"黃帝李法","sortOrder":31},
  {"id":"s_work_dtbt_53_32","chapterId":"ch_work_dtbt_53","text":"漢書胡建傳：「黃帝李法。」蘇林曰：「獄官名也。天文志：『左角，李；右角，將。』」顏師古曰：「李者，法官之號也，其書曰李法。」唐世系表：「李氏自皋陶為堯大理，歷虞、夏、商，世世作此官，以官命族為理氏。至紂之時，逃難於伊侯之墟，食木子得全，遂改『理』為李氏。」予按今本漢書天文志騎官：「左角，理。」乃用「理」字，而史記天官書則為「李」，說苑載胡建事亦為「理法」。然則「理」、「李」一也。故左傳數雲「行李往來」。杜預註曰：「行李，使人也。」至鄭子產與晉盟於平丘，則曰：「行理之命。」註亦雲：「行理，使人通聘問者。」其義益明。皋陶作大理，傳子孫不改，迨商之季幾千二百年，世官久任，倉氏、庫氏不足道矣。表系疑不可信。","sortOrder":32},
  {"id":"s_work_dtbt_53_33","chapterId":"ch_work_dtbt_53","text":"抄傳文書之誤","sortOrder":33},
  {"id":"s_work_dtbt_53_34","chapterId":"ch_work_dtbt_53","text":"今代所傳文書，筆吏不謹，至於成行脫漏。予在三館假庾自直類文，先以正本點檢，中有數卷皆以後板為前，予令書庫整頓，然後錄之。他多類此。周益公以蘇魏公集付太平州鏤板，亦先為勘校。其所作東山長老語錄序雲：「側定政宗，無用所以為用；因蹄得兔，忘言而後可言。」以上一句不明白，又與下不對，折簡來問。予憶莊子曰：「地非不廣且大也，人之所用容足爾。然而廁足而墊之致黃泉，知無用而後可以言用矣。」始驗「側定政宗」當是「廁足致泉」，正與下文相應，四字皆誤也。因記曾紘所書陶淵明讀山海經詩雲：「形夭無千歲，猛志固常在。」疑上下文義若不貫，遂取山海經參校，則雲：「刑天，獸名也，口中好銜幹戚而舞。」乃知是「刑天舞幹戚」，故與下句相應，五字皆訛。以語友人岑公休、晁之道，皆撫掌驚嘆，亟取所藏本是正之。此一節甚類蘇集雲。","sortOrder":34},
  {"id":"s_work_dtbt_53_35","chapterId":"ch_work_dtbt_53","text":"二十八宿","sortOrder":35},
  {"id":"s_work_dtbt_53_36","chapterId":"ch_work_dtbt_53","text":"二十八宿，宿音秀。若考其義，則止當讀如本音。嘗記前人有說如此，說苑辯篇曰：「天之五星，運氣於五行，所謂宿者，日月五星之所宿也。」其義昭然。","sortOrder":36},
  {"id":"s_work_dtbt_53_37","chapterId":"ch_work_dtbt_53","text":"大觀元夕詩","sortOrder":37},
  {"id":"s_work_dtbt_53_38","chapterId":"ch_work_dtbt_53","text":"大觀初年，京師以元夕張燈開宴。時再復湟、鄯，徽宗賦詩賜羣臣，其頷聯雲：「午夜笙歌連海嶠，春風燈火過湟中。」席上和者皆莫及。開封尹宋喬年不能詩，密走介求援於其客周子雍，得句雲：「風生閶闔春來早，月到蓬萊夜未中。」為時輩所稱。子雍，汝陰人，曾受學於陳無已，故有句法。則作文為詩者，可無師承乎？","sortOrder":38},
  {"id":"s_work_dtbt_53_39","chapterId":"ch_work_dtbt_53","text":"顏魯公帖","sortOrder":39},
  {"id":"s_work_dtbt_53_40","chapterId":"ch_work_dtbt_53","text":"顏魯公忠義氣節，史策略盡。偶閱臨汝石刻，見一帖雲：「政可守不可不守，吾去歲中言事得罪，又不能逆道苟時，為千古罪人也，雖貶居遠方，終身不恥。汝曹當須謂吾之志不可不守也。」此是獨赴謫地，而與其子孫者，無由考其歲月。千載之下，使人讀之，尚可畏而仰也。","sortOrder":40},
  {"id":"s_work_dtbt_53_41","chapterId":"ch_work_dtbt_53","text":"文潞公奏除改官製","sortOrder":41},
  {"id":"s_work_dtbt_53_42","chapterId":"ch_work_dtbt_53","text":"自熙寧以來，士大夫資歷之法，日趨於壞，歲甚一歲，久而不可復清。近年愈甚，綜核之製，未嘗能守。偶見文潞公在元祐中任平章軍國重事，宣仁面諭，令具自來除授官職次序一本進呈。公遂具除改舊製節目以奏，其一雲：「吏部選兩任親民，有舉主，升通判。通判兩任滿，有舉主，升知州、軍，謂之常調。知州、軍有績效，或有舉薦，名實相副者，特擢升轉運使、副、判官，或提點刑獄、府推、判官，謂之出常調。轉運使有路分輕重遠近之差。河北、陝西、河東三路為重路，歲滿多任三司使、副，或發運使。發運任滿，亦充三司副使。成都路次三路，京東西、淮南又其次，江東西、荊湖、兩浙又次之，二廣、福建、梓、利、夔路為遠小。已上三等路分，轉運任滿，或就移近上次等路分，或歸任省府判官，漸次擢充三路重任。內提點刑獄，則不拘路分輕重除授。」潞公所奏乃是治平以前常行，今一切蕩然矣。京朝官未嘗肯兩任親民。纔為通判，便望州郡。至於監司，既無輕重遠近之間，不復以序升擢雲。","sortOrder":42},
  {"id":"s_work_dtbt_53_43","chapterId":"ch_work_dtbt_53","text":"待製知製誥","sortOrder":43},
  {"id":"s_work_dtbt_53_44","chapterId":"ch_work_dtbt_53","text":"慶曆七年，曾魯公公亮，自修起居註除天章閣待製。時陳恭公獨為相，其弟婦王氏，冀公孫女，曾出也。當月旦出拜，恭公迎語之曰：「六新婦，曾三做從官，想甚喜。」應聲對曰：「三舅荷伯伯提挈極歡喜，只是外婆不樂。」恭公問故，曰：「外婆見三舅來謝，責之曰：汝第五人及第，當過詞掖，想是全廢學，故朝廷如此處汝。」恭公默然自失，後竟改知製誥。蓋恭公不由科第，不諳典故，致受譏於女子。而此女對答之時，元未嘗往外家也，其警慧如此。國家故事，修註官次補必知製誥，惟趙康靖公以歐陽公位在下，而欲先遷，司馬公以力辭，三人皆除待製，其雜壓先後可見雲。","sortOrder":44},
  {"id":"s_work_dtbt_53_45","chapterId":"ch_work_dtbt_53","text":"裴行儉景陽","sortOrder":45},
  {"id":"s_work_dtbt_53_46","chapterId":"ch_work_dtbt_53","text":"裴行儉為定襄道大總管，討突厥。大軍次單於北，暮已立營，塹壕既周，更命徙營高岡。吏白：「士安堵不可擾。」不聽，促徙之。比夜風雨暴至，前占營所，水深丈餘，衆莫不駭嘆。問何以知之，行儉曰：「自今第如我節製，毋問我所以知也。」按戰國策雲：「齊、韓、魏共攻燕，楚王使景陽將而救之。暮舍，使左右司馬各營壁地，已植表，景陽怒曰：『女所營者水皆至滅表，此焉可以舍？』乃令徙。明日大雨，山水大出，所營者水皆滅表，軍吏乃服。」二事正同，而景陽之事不傳。","sortOrder":46},
  {"id":"s_work_dtbt_53_47","chapterId":"ch_work_dtbt_53","text":"北人重甘蔗","sortOrder":47},
  {"id":"s_work_dtbt_53_48","chapterId":"ch_work_dtbt_53","text":"甘蔗只生於南方，北人嗜之，而不可得。魏太武至彭城，遣人於武陵王處求酒及甘蔗。郭汾陽在汾上，代宗賜甘蔗二十條。子虛賦所雲：「諸柘巴且。」諸柘者，甘柘也。蓋相如指言楚雲夢之物。漢郊祀歌「泰尊柘漿」，亦謂取甘蔗汁以為飲。","sortOrder":48},
  {"id":"s_work_dtbt_54_1","chapterId":"ch_work_dtbt_54","text":"卷第三(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_54_2","chapterId":"ch_work_dtbt_54","text":"韓退之張籍書","sortOrder":2},
  {"id":"s_work_dtbt_54_3","chapterId":"ch_work_dtbt_54","text":"韓公集中有答張籍二書，其前篇曰：「吾子所論，排釋、老不若著書。若僕之見，則有異乎此，請待五六十然後為之。吾子又譏吾與人為無實駁雜之說，此吾所以為戲耳。若商論不能下氣，或似有之。博塞之譏，敢不承教！」後篇曰：「二氏行乎中土，蓋六百年，非可以朝令而夕禁，俟五六十為之未失也。謂吾與人商論不能下氣，若好勝者。雖誠有之，抑非好己勝也，好己之道勝也。駁雜之譏，前書盡之。昔者夫子猶有所戲，烏害於道哉？」大略籍所論四事：乞著書、譏駁雜、諫商論好勝及博塞也。今得籍所與書，前篇曰：「漢之衰，浮圖之法入中國，黃、老之術，相沿而熾。盍為一書，以興存聖人之道？執事多尚駁雜無實之說，使人陳之前以為歡，此有累於盛德。又商論之際，或不容人之短，如任私尚勝者，亦有所累也。况為博塞之戲與人競財乎？廢棄日時，不識其然。願絕博塞之好，棄無實之談，宏慮以接士，嗣孟軻、揚雄之作，使聖人之道，復見於唐。」後篇曰：「老、釋惑於生人久矣，執事可以任著書之事。君子汲汲於所欲為，若皆待五十六十而後有所為，則或有遺恨矣。君子發言舉足，不遠於禮，未聞以駁雜無實之說以為戲也。執事每見其說，則拊抃呼笑，是撓氣害性，不得其正矣。」籍之二書，甚勁而直。但稱韓公為執事，不曰先生。考其時，乃雲「執事參於戎府」。按韓公以貞元十二年為汴州推官，時年二十有九，十五年為徐州推官，時年三十有二，年位未盛，籍未以師禮事之雲。","sortOrder":3},
  {"id":"s_work_dtbt_54_4","chapterId":"ch_work_dtbt_54","text":"韓公稱李杜","sortOrder":4},
  {"id":"s_work_dtbt_54_5","chapterId":"ch_work_dtbt_54","text":"新唐書杜甫傳贊曰：「昌黎韓愈於文章重許可，至歌詩，獨推曰：『李杜文章在，光焰萬丈長。』誠可信雲。」予讀韓詩，其稱李、杜者數端，聊疏於此。石鼓歌曰：「少陵無人謫仙死，才薄將奈石鼓何？」酬盧雲夫曰：「高揖羣公謝名譽，遠追甫白感至諴。」薦士曰：「勃興得李杜，萬類困凌暴。」醉留東野曰：「昔年因讀李白杜甫詩，長恨二人不相從。」感春曰：「近憐李杜無檢束，爛漫長醉多文辭。」幷唐志所引，蓋六用之。","sortOrder":5},
  {"id":"s_work_dtbt_54_6","chapterId":"ch_work_dtbt_54","text":"此日足可惜","sortOrder":6},
  {"id":"s_work_dtbt_54_7","chapterId":"ch_work_dtbt_54","text":"韓退之此日足可惜一首贈張籍，凡百四十句，雜用東、冬、江、陽、庚、青六韻。及其亡也，籍作詩祭之，凡百六十六句，用陽、庚二韻，其語鏗鏘震厲，全仿韓體。所謂「乃出二侍女，合彈琵琶箏」者是也。","sortOrder":7},
  {"id":"s_work_dtbt_54_8","chapterId":"ch_work_dtbt_54","text":"粉白黛黑","sortOrder":8},
  {"id":"s_work_dtbt_54_9","chapterId":"ch_work_dtbt_54","text":"韓退之為文章，不肯蹈襲前人一言一句。故其語曰：「惟陳言之務去，戛戛乎其難哉！」獨粉白黛綠四字，似有所因。列子：「周穆王築中天之臺，簡鄭、衞之處子娥媌靡曼者，粉白黛黑以滿之。」戰國策張儀謂楚王曰：「鄭、周之女，粉白黛黑，立於衢間，見者以為神。」屈原大招：「粉白黛黑，施芳澤只。」司馬相如：「靚莊刻飾。」郭璞曰：「粉白黛黑也。」淮南子：「毛嬙、西施，施芳澤，正蛾眉，設笄珥，衣阿錫，粉白黛黑，笑目流眺。」韓公以黑為綠，其旨則同。","sortOrder":9},
  {"id":"s_work_dtbt_54_10","chapterId":"ch_work_dtbt_54","text":"李杜往來詩","sortOrder":10},
  {"id":"s_work_dtbt_54_11","chapterId":"ch_work_dtbt_54","text":"李太白、杜子美在布衣時，同遊梁、宋，為詩酒會心之友。以杜集考之，其稱太白及懷贈之篇甚多。如「李侯金閨彥，脫身事幽討」，「南尋禹穴見李白，道甫問訊今何如」，「李白一（豆斗）詩百篇，自稱臣是酒中仙」，「近來海內為長句，汝與山東李白好」，「昔者與高李，晚登單父臺」，「李侯有佳句，往往似陰鏗」，「憶與高李輩，論交入酒壚」，「白也詩無敵，飄然思不羣」，「昔年有狂客，號爾謫仙人」，「落月滿屋梁，猶疑照顏色」，「三夜頻夢君，情親見君意」，「秋來相顧尚飄蓬，未就丹砂愧葛洪」，「寂寞書齋裏，終朝獨爾思」，「涼風起天末，君子意如何」，「不見李生久，佯狂真可哀」，凡十四五篇。至於太白與子美詩略不見一句。或謂堯祠亭別杜補闕者是已。乃殊不然，杜但為右拾遺，不曾任補闕，兼自諫省出為華州司功，迤邐避難入蜀，未嘗復至東州，所謂「飯顆山頭」之嘲，亦好事者所撰耳。","sortOrder":11},
  {"id":"s_work_dtbt_54_12","chapterId":"ch_work_dtbt_54","text":"李太白怖州佐(「英眄」，館本作「英盼」。)","sortOrder":12},
  {"id":"s_work_dtbt_54_13","chapterId":"ch_work_dtbt_54","text":"李太白上安州裴長史書雲：「白竊慕高義，得趨末塵，何圖謗言忽生，衆口攢毀，將恐投杼下客，震於嚴威。若使事得其實，罪當其身，則將浴蘭沐芳，自屏於烹鮮之地，惟君侯死生之。願君侯惠以大遇，洞開心顏，終乎前恩，再辱英眄，必能使精誠動天，長虹貫日。若赫然作威，加以大怒，即膝行而前，再拜而去耳。」裴君不知何如人，至譽其貴而且賢，名飛天京，天才超然，度越作者，稜威雄雄，下慴羣物。予謂白以白衣入翰林，其蓋世英姿，能使高力士脫靴於殿上，豈拘拘然怖一州佐者邪？蓋時有屈伸，正自不得不爾，大賢不偶，神龍困於螻蟻，可勝嘆哉！白此書自敍其平生雲：「昔與蜀中友人吳指南，同遊於楚，指南死於洞庭之上，白禫服慟哭，炎月伏尸，猛虎前臨，堅守不動，遂權殯於湖側。數年來，觀筋骨尚在，雪泣持刃，躬申洗削，裹骨徒步，負之而趨，寢興攜持，無輟身手，遂丐貸營葬於鄂城。」其存交重義如此。「又與逸人東巖子隱於岷山，巢居數年，不跡城市。養奇禽千計，呼皆就掌取食，了無驚猜。」其養高忘機如此。而史傳不為書之，亦為未盡。","sortOrder":13},
  {"id":"s_work_dtbt_54_14","chapterId":"ch_work_dtbt_54","text":"祝不勝詛","sortOrder":14},
  {"id":"s_work_dtbt_54_15","chapterId":"ch_work_dtbt_54","text":"齊景公有疾，梁丘據請誅祝史。晏子曰：「祝有益也，詛亦有損。聊、攝以東，姑、尤以西，其為人也多矣。雖其善祝，豈能勝億兆人之詛？」晉中行寅將亡，召其太祝欲加罪。曰：「子為我祝，齋戒不敬，使吾國亡。」祝簡對曰：「今舟車飾，賦斂厚，民怨謗詛多矣。苟以為祝有益於國，則詛亦將為損，一人祝之，一國詛之，一祝不勝萬詛，國亡不亦宜乎，祝其何罪？」此二說若出一口，真藥石之言也。","sortOrder":15},
  {"id":"s_work_dtbt_54_16","chapterId":"ch_work_dtbt_54","text":"呂子論學","sortOrder":16},
  {"id":"s_work_dtbt_54_17","chapterId":"ch_work_dtbt_54","text":"呂子曰：「天生人而使其耳可以聞，不學，其聞則不若聾；使其目可以見，不學，其見則不若盲；使其口可以言，不學，其言則不若喑；使其心可以智，不學，其智則不若狂。故凡學，非能益之也，達天性也，能全天之所生，而勿敗之，可謂善學者矣。」此說甚美，而罕為學者所稱，故書以自戒。","sortOrder":17},
  {"id":"s_work_dtbt_54_18","chapterId":"ch_work_dtbt_54","text":"曾太皇太後","sortOrder":18},
  {"id":"s_work_dtbt_54_19","chapterId":"ch_work_dtbt_54","text":"唐德宗即位，訪求其母沈太後，歷順宗，及憲宗時為曾祖母，故稱為曾太皇太後，蓋別於祖母也。舊、新二唐書紀，皆載之。今慈福太皇太後在壽康太上時，已加尊稱，若於主上則為曾祖母，當用唐故事加曾字。向者嘗以告宰相，而省吏以為典故所無，天子逮事三世，安得有前比，亦可謂不知禮矣。又嗣濮王士歆在隆興為從叔祖，在紹熙為曾叔祖，慶元為高叔祖矣，而仍稱皇叔祖如故。士歆視嗣秀王伯圭為從祖，今圭稱皇伯祖，而歆但為皇叔祖，乃是弟爾。禮寺亦以為國朝以來無稱曾高者，彼蓋不知累朝尊屬，元未之有也。","sortOrder":19},
  {"id":"s_work_dtbt_54_20","chapterId":"ch_work_dtbt_54","text":"中天之臺","sortOrder":20},
  {"id":"s_work_dtbt_54_21","chapterId":"ch_work_dtbt_54","text":"中天之臺有二：其一，列子曰：「西極化人見周穆王，王為之改築宮室，土木之功，赭堊之色，無遺巧焉。五府為虛，而臺始成。其高千仞，臨終南之上，名曰中天之臺。」其一，新序曰：「魏王將起中天臺，許綰負操鍤入，曰：『臣能商臺。』王曰：『若何？』曰：『天與地相去萬五千里，今王因而半之，當起七千五百里之臺，高既如是，其趾須方八千里，盡王之地不足以為臺趾。必起此臺，先以兵伐諸侯，盡有其地，又伐四夷，得方八千里，乃足以為臺趾。度八千里之外，當定農畝之地，足以奉給王之臺者。臺具以備，乃可以作。』王默然無以應，乃罷起臺。」","sortOrder":21},
  {"id":"s_work_dtbt_54_22","chapterId":"ch_work_dtbt_54","text":"實年官年","sortOrder":22},
  {"id":"s_work_dtbt_54_23","chapterId":"ch_work_dtbt_54","text":"士大夫敍官閥，有所謂實年、官年兩說，前此未嘗見於官文書。大抵布衣應舉，必減歲數，蓋少壯者欲藉此為求昏地；不幸潦倒場屋，勉從特恩，則年未六十始許入仕，不得不豫為之圖。至公卿任子，欲其早列仕籍，或正在童孺，故率增擡庚甲有至數歲者。然守義之士，猶曰兒曹甫策名委質，而父祖先導之以挾詐欺君，不可也。比者以朝臣屢言，言及七十者不許任監司、郡守，搢紳多不自安，爭引年以決去就。江東提刑李信甫，雖春秋過七十，而官年損其五，堅乞致仕，有旨官年未及，與之外祠。知房州章騆六十八歲，而官年增其三，亦求罷去。諸司以其精力未衰，援實為請，有旨聽終任。知嚴州秦乞祠之疏曰：「實年六十五，而官年已逾七十。」遂得去。齊慶冑寧國乞歸，亦曰：「實年七十，而官年六十七。」於是實年、官年之字，形於製書，播告中外，是君臣上下公相為欺也。掌故之野甚矣，此豈可紀於史錄哉？","sortOrder":23},
  {"id":"s_work_dtbt_54_24","chapterId":"ch_work_dtbt_54","text":"雷公炮炙論","sortOrder":24},
  {"id":"s_work_dtbt_54_25","chapterId":"ch_work_dtbt_54","text":"雷公炮炙論，載一藥而能治重疾者，今醫家罕用之，聊志於此。其說雲：「髮眉墮落，塗半夏而立生。目辟眼（目雖），有五花而自正。腳生肉栨，裩繫菪根。囊皺漩多，夜煎竹木。體寒腹大，全賴鸕鶿。血泛經過，飲調瓜子。咳逆數數，酒服熟雄。遍體（疒軫）風，冷調生側。腸虛泄利，須假草零。久渴心煩，宜投竹瀝。除癥去塊，全仗硝、硇。益食加觴，須煎蘆、朴。強筋健骨，須是蓯、鱓。駐色延年，精蒸神錦。知瘡所在，口點陰膠。產後肌浮，甘皮酒服。腦痛，鼻投硝末。心痛，速覓延胡。」凡十八項。謂眉髮墮落者，煉生半夏莖，取涎塗髮落處，立生。五花者，五加皮也，葉有雄雌，三葉為雄，五葉為雌，須使五葉者作末，酒浸用之，目（目雖）者正。腳有肉栨者，取莨菪根，繫裩帶上，永痊。多小便者，煎萆薢服之，永不夜起。若患腹大如鼓，米飲調鸕鶿末服，立枯如故。血泛行者，搗甜瓜子仁作末去油，飲調服之，立絕。咳逆者，天雄炮過，以酒調一錢，匕服。（疒軫）風者，側子(附子傍生者。)作末，冷酒服。虛泄者，搗五倍子末，熟水下之。癥塊者，以硇砂、硝石二味，乳鉢中研作粉，同煅了，酒服，神效。不飲者幷飲酒少者，煎逆水蘆根幷厚朴二味，湯服之。蓯蓉幷鱓魚作末，以黃精汁圓服之，可力倍常日也。黃精自然汁拌細研神錦，於柳木甑中，蒸七日了，以蜜圓服，顏貌可如幼女之容色。陰膠即是甑中氣垢，點少許於口中，即知臟腑所起，直徹至住處知痛，足可醫也。產後肌浮，酒服甘皮立枯。頭痛者，以硝石作末，內鼻中，立止。心痛者，以延胡索作散，酒服之。","sortOrder":25},
  {"id":"s_work_dtbt_54_26","chapterId":"ch_work_dtbt_54","text":"治藥捷法","sortOrder":26},
  {"id":"s_work_dtbt_54_27","chapterId":"ch_work_dtbt_54","text":"藥有至賤易得，人所常用，而難於修製者，如香附子、菟絲子、艾葉之類。醫家昧其節度，或終日疲勞而不能成。本草雲：「凡菟絲子，暖湯淘汰去沙土，漉乾，暖酒漬，經一宿，漉出，暴微白，搗之，不盡者，更以酒漬，經三五日乃出，更曬微乾，搗之須臾悉盡，極易碎。」蓋以其顆細難施工，其說亦殊勞費。然自有捷法，但撚紙條數枚置其間，則馴帖成粉。香附子洗去皮毛，炒之焦熟，然後舉投水鉢內，候浸漬透徹，漉出，暴日中微燥，乃入搗臼，悉應手糜碎。艾葉柔軟不可著力，若入白茯苓三五片同碾，則即時可作細末。(「馴帖」，館本作「頃刻」。)","sortOrder":27},
  {"id":"s_work_dtbt_54_28","chapterId":"ch_work_dtbt_54","text":"陳翠說燕後","sortOrder":28},
  {"id":"s_work_dtbt_54_29","chapterId":"ch_work_dtbt_54","text":"趙左師觸龍說太後，使長安君出質，用愛憐少子之說以感動之。予嘗論之於隨筆中。其事載於戰國策、史記、資治通鑑，而燕語中又有陳翠一段，甚相似。雲：「陳翠合齊、燕，將令燕王之弟為質於齊，太後大怒曰：『陳公不能為人之國，則亦已矣，焉有離人子母者！』翠遂入見後曰：『人主之愛子也，不如布衣之甚也，非徒不愛子也，又不愛丈夫子獨甚。』太後曰：『何也？』對曰：『太後嫁女諸侯，奉以千金。今王願封公子，羣臣曰，公子無功不當封。今以公子為質，且以為功而封之也。太後弗聽，是以知人主之不愛丈夫子獨甚也。且太後與王幸而在，故公子貴。太後千秋之後，王棄國家，而太子即位，公子賤於布衣。故非及太後與王封公子，則終身不封矣。』太後曰：『老婦不知長者之計。』乃命為行具。」此語與觸龍無異，而史記不書，通鑑不取，學者亦未嘗言。","sortOrder":29},
  {"id":"s_work_dtbt_54_30","chapterId":"ch_work_dtbt_54","text":"燕非強國","sortOrder":30},
  {"id":"s_work_dtbt_54_31","chapterId":"ch_work_dtbt_54","text":"北燕在春秋時最為僻小，能自見於中國者，不過三四，大率製命於齊。七雄之際，為齊所取，後賴五國之力，樂毅為將，然後勝齊，然卒於得七十城不能守也。故蘇秦說趙王曰：「趙北有燕，燕固弱國，不足畏也。」燕王曰：「寡人國小，西迫強秦，南近齊、趙，齊、趙強國也。」又曰：「天下之戰國七，而燕處弱焉，獨戰則不能，有所附則無不重。」昭王謂郭隗曰：「孤極知燕弱小，不足以報齊。」蘇代曰：「一齊之強，燕猶不能支。」奉陽君曰：「燕弱國也，東不如齊，西不如趙。」趙長平之敗，壯者皆死，燕以二千乘攻之，為趙所敗。太子丹謂荊軻曰：「燕小弱，數困於兵，何足以當秦？」楚、漢之初，趙王武臣為燕軍所得，趙廝養卒謂其將曰：「一趙尚易燕，況以兩賢王，滅燕易矣。」彭寵以漁陽叛，即時夷滅。十六國之起，戎狄亂華，稱燕稱趙者多矣，未嘗有只據幽、薊之地者也。獨安祿山以三十年節製之威，又兼領河東，乘天寶政亂，出不意而舉兵，史思明繼之，雖為天下之禍，旋亦殄滅。至於藩鎮擅地，所謂范陽、盧龍，固常受製於天雄、成德也。劉仁恭、守光父子，僭竊一方，唐莊宗遣周德威攻之，克取巡屬十餘州，如拾地芥。石晉割賂契丹，仍其舊國，恃以為強，然晉開運陽城之戰，德光幾不免。周世宗小振之，立下三關。但太平興國，失於輕舉，又不治敗將喪師之罪，致令披猖以迄於今。若以謂幽燕為用武之地，則不然也。","sortOrder":31},
  {"id":"s_work_dtbt_54_32","chapterId":"ch_work_dtbt_54","text":"水旱祈禱","sortOrder":32},
  {"id":"s_work_dtbt_54_33","chapterId":"ch_work_dtbt_54","text":"海內雨暘之數，郡異而縣不同，為守為令，能以民事介心，必自知以時禱祈，不待上命也。而省部循案故例，但視天府為節，下之諸道轉運司，使巡內州縣，各詣名山靈祠，精潔致禱，然固難以一概論。乾道九年秋，贛、吉連雨暴漲。予守贛，方多備土囊，壅諸城門，以杜水入，凡二日乃退。而臺符令禱雨，予格之不下，但據實報之。已而聞吉州於小廳設祈晴道場，大廳祈雨。問其故，郡守曰：「請霽者，本郡以淫潦為災，而請雨者，朝旨也。」其不知變如此，殆為侮惑神天，幽冥之下，將何所據憑哉？俚語笑林謂「兩商人入神廟，其一陸行欲晴，許賽以猪頭，其一水行欲雨，許賽羊頭。神顧小鬼言：『晴乾喫猪頭，雨落喫羊頭，有何不可。』」正謂此耳。坡詩雲：「耕田欲雨刈欲晴，去得順風來者怨。若使人人禱輒遂，造物應須日千變。」此意未易為庸俗道也。","sortOrder":33},
  {"id":"s_work_dtbt_54_34","chapterId":"ch_work_dtbt_54","text":"容齋四筆","sortOrder":34},
  {"id":"s_work_dtbt_55_1","chapterId":"ch_work_dtbt_55","text":"卷第四(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_55_2","chapterId":"ch_work_dtbt_55","text":"今日官冗","sortOrder":2},
  {"id":"s_work_dtbt_55_3","chapterId":"ch_work_dtbt_55","text":"元豐中，曾鞏判三班院，(今侍右也。)上疏言：「國朝景德墾田百七十萬頃，官萬員。皇祐二百二十五萬頃，官二萬員。治平四百三十萬頃，官二萬四千員。田日加辟，官日加多，而後之郊費視前一倍。以三班三年之籍較之，其入籍者幾七百人，而死亡免退不能二百，是年增歲溢，未見其止，則用財之端，入官之門，當令有司講求其故，使天下之入如治平，而財之用官之數同景德，以三十年之通，可以餘十年之蓄矣。」是時，海內全盛，倉庫多有樁積，猶有此懼。慶元二年四月，有朝臣奏對，極言雲：「曩在乾道間，京朝官三四千員，選人七八千員。紹熙二年，四選名籍，尚左，京官四千一百五十九員，尚右，大使臣五千一百七十三員，侍左，選人一萬二千八百六十九員，侍右，小使臣一萬一千三百十五員，合四選之數，共三萬三千五百十六員，冗倍於國朝全盛之際。近者四年之間，京官未至增添，外選人增至一萬三千六百七十員，(比紹熙增八百一員。)大使臣六千五百二十五員，(比紹熙增一千三百四十八員。)小使臣一萬八千七百五員，(比紹熙增七千四百員。)而今年科舉，明年奏薦不在焉。通無慮四萬三千員，比四年之數增萬員矣，可不為之寒心哉！」蓋連有覃霈，慶典屢行，而宗室推恩，不以服派近遠為間斷，特奏名三舉，皆值異恩，雖助教亦出官歸正，人每州以數十百，病在膏肓，正使俞跗、扁鵲，持上池良藥以救之，亦無及已。","sortOrder":3},
  {"id":"s_work_dtbt_55_4","chapterId":"ch_work_dtbt_55","text":"欒城和張安道詩","sortOrder":4},
  {"id":"s_work_dtbt_55_5","chapterId":"ch_work_dtbt_55","text":"張文定公在蜀，一見蘇公父子，即以國士許之。熙寧中，張守陳州南都，辟子由幕府。元豐初，東坡謫齊安，子由貶監筠酒稅，與張別，張悽然不樂，酌酒相命，手寫一詩曰：「可憐萍梗飄蓬客，自嘆匏瓜老病身。從此空齋掛塵榻，不知重掃待何人？」後七年，子由召還，猶復見之於南都。及元符末，自龍川還許昌，因侄叔黨出坡遺墨，再讀張所贈詩，其薨已十年，泣下不能已，乃追和之曰：「少年便識成都尹，中歲仍為幕下賓。待我江西徐孺子，一生知己有斯人。」兩詩皆哀而不怨，使人至今有感於斯文。今世薄夫受人異恩，轉眼若不相識，況於一死一生，拳拳如此，忠厚之至，殆可端拜也。","sortOrder":5},
  {"id":"s_work_dtbt_55_6","chapterId":"ch_work_dtbt_55","text":"和范杜蘇四公","sortOrder":6},
  {"id":"s_work_dtbt_55_7","chapterId":"ch_work_dtbt_55","text":"晉相和凝，以唐長興四年知貢舉，取范質為第十三人。唐故事，知貢舉者，所放進士，以己及第時名次為重，謂之傳衣鉢。蓋凝在梁貞明中居此級，故以處質，且雲：「他日當如我。」後皆至宰相，封魯國公，官至太子太傅，當時以為榮。凝壽止五十八，質止五十四。三朝史質本傳亦書之，而新五代史和凝傳誤為第五，以登科記考之而非也。杜祁公罷相，以太子少師致仕，後以南郊免陪位恩，連進至太子太師，年八十而薨。蘇子容初筮仕為南京判官，杜公方里居，告以平生出處本末，曰：「子異日所至，亦如老夫。」及蘇更踐中外，名德殊與之相似。集中有謝杜公書，正敍此事。其罷相也，亦以太子少師致仕，進太保，年八十二而薨。昔賢謂貴人往往善相人，以所閱多之故也。此二者幷官爵年壽皆前知，異矣。","sortOrder":7},
  {"id":"s_work_dtbt_55_8","chapterId":"ch_work_dtbt_55","text":"外臺祕要","sortOrder":8},
  {"id":"s_work_dtbt_55_9","chapterId":"ch_work_dtbt_55","text":"外臺祕要，載製虎方雲：「到山下先閉氣三十五息，所在山神將虎來到吾前，乃存吾肺中，有白帝出，收取虎兩目，塞吾下部中，乃吐肺氣，上自通冠一山林之上。於是良久，又閉氣三十五息，兩手捻都監目作三步，步皆以右足在前，乃止，祝曰：『李耳、李耳，圖汝非李耳邪。汝盜黃帝之犬，黃帝教我問汝雲何。』畢，便行，一山虎不可得見。若卒逢之者，因正面立，大張左手五指側之，極勢跳，手上下三度，於跳中大喚，咄曰：『虎，北斗君使汝去！』虎即走。」予謂人卒逢虎，魂魄驚怖，竄伏之不暇，豈能雍容步趨，仗咒語七字而脫邪？因讀此方，聊書之以發一笑。此書乃唐王珪之孫燾所作，本傳雲：「燾視母疾，數從高醫遊，遂窮其術，因以所學作書，討繹精明，世寶焉。」蓋不深考也。","sortOrder":9},
  {"id":"s_work_dtbt_55_10","chapterId":"ch_work_dtbt_55","text":"六枳關","sortOrder":10},
  {"id":"s_work_dtbt_55_11","chapterId":"ch_work_dtbt_55","text":"盤洲種枳六本，以為藩籬之限。立小門，名曰六枳關。每為人問其所出，倦於酬應。今取馮衍顯志賦中語書於此。衍雲：「揵六枳而為籬。」按東觀漢記作八枳。逸周書小開篇雲：「嗚呼！汝何敬非時，何擇非德？德枳維大人，大人枳維公，公枳維卿，卿枳維大夫，大夫枳維士。登登皇皇，維在國枳，國枳維都，都枳維邑，邑枳維家，家枳維欲無疆。」言上下相維，遞為藩蔽也。其數有八，與東觀記同。予詳考之，乃九枳也。宋景文公賀宰相啟：「式維公枳。」蓋用此雲。","sortOrder":11},
  {"id":"s_work_dtbt_55_12","chapterId":"ch_work_dtbt_55","text":"王荊公上書幷詩","sortOrder":12},
  {"id":"s_work_dtbt_55_13","chapterId":"ch_work_dtbt_55","text":"王荊公議論高奇，果於自用。嘉祐初，為度支判官，上萬言書，以為「今天下財力日以困窮，風俗日以衰壞。患在不知法度，不法先王之政故也。法先王之政者，法其意而已。法其意，則吾所改易更革，不至乎傾駭天下之耳目，而固已合矣。因天下之力，以生天下之財，取天下之財，以供天下之費。自古治世，未嘗以不足為公患也，患在治財無其道爾。在位之人才既不足，而閭巷草野之間，亦少可用之材，社稷之託，封疆之守，陛下其能久以天幸為常，而無一旦之憂乎？願監苟且因循之敝，明詔大臣，為之以漸，期為合於當世之變。臣之所稱，流俗之所不講，而議者以為迂闊而熟爛者也。」當時富、韓二公在相位，讀之不樂，知其得志必生事。後安石當國，其所註措，大抵皆祖此書。又不忍貧民，而深疾富民，志欲破富以惠貧。嘗賦兼幷詩一篇，曰：「三代子百姓，公私無異財。人主擅操柄，如天持斗魁。賦予皆自我，兼幷乃奸回。奸回法有誅，勢亦無自來。後世始倒持，黔首遂難裁。秦王不知此，更築懷清臺。禮義日已媮，聖經久堙埃。法尚有存者，欲言時所咍。俗吏不知方，掊克乃為才。俗儒不知變，兼幷可無摧。利孔至百出，小人司闔開。有司與之爭，民愈可憐哉！」其語絕不工。迨其得政，設青苗法以奪富民之利，民無貧富，兩稅之外，皆重出息十二。呂惠卿復作手實之法，民遂大病。其禍源於此詩。蘇子由以為昔之詩病未有若此其酷也。痛哉！","sortOrder":13},
  {"id":"s_work_dtbt_55_14","chapterId":"ch_work_dtbt_55","text":"左黃州表","sortOrder":14},
  {"id":"s_work_dtbt_55_15","chapterId":"ch_work_dtbt_55","text":"唐肅宗時，王璵以祠禱見寵，驟得宰相。帝嘗不豫，璵遣女巫乘傳，分禱天下名山大川。巫皆盛服，中人護領，所至幹託州縣，賂遺狼藉。時有一巫美而豔，以惡少年數十自隨，尤憸狡不法。馳入黃州，刺史左震晨至館請事，門鐍不啟，震怒，破鐍入，取巫斬廷下，悉誅所從少年，籍其贓得十餘萬，因遣還中人。璵不能詰，帝亦不加罪。震剛決如此，而史不記其他事。予讀元次山集，有左黃州表一篇雲：「乾元己亥，贊善大夫左振，出為黃州刺史，下車，黃人歌曰：『我欲逃鄉里，我欲去墳墓；左公今既來，誰忍棄之去。』後一歲，又歌曰：『吾鄉有鬼巫，惑人人不知；天子正尊信，左公能殺之。』蓋此巫黃人也。振在州三遷侍御史，判金州刺史，將去，黃人多去思，故為作表。」予謂振(即震也。)為政宜民，見於歌頌，史官當特書之於循吏中，而僅能不沒其實，故為標顯於此。己亥者，乾元二年。璵以元年五月，自太常少卿拜中書相，二年三月罷，本紀及宰相表同。而新史本傳，以為三年自太常卿拜相，明日罷，失之矣。乃承舊史之誤也。","sortOrder":15},
  {"id":"s_work_dtbt_55_16","chapterId":"ch_work_dtbt_55","text":"李郭詔書","sortOrder":16},
  {"id":"s_work_dtbt_55_17","chapterId":"ch_work_dtbt_55","text":"唐代宗即位，郭汾陽為近昵所搖，懼禍之及，表上自靈武、河北至於絳州，兩朝所詒詔書一千餘卷。家傳載其表語，其多如是。又讀韋端符所撰李衞公故物記雲：「三原令座中有客曰李丞者，衞公之冑，藏文帝賜書二十通，多言征討事，厚勞苦，『其兵事節度皆付公，吾不從中治也』。暨公疾，親詔者數四，其一曰：『有晝夜視公病大老嫗令一人來，吾欲熟知公起居狀。』權文公視此詔，常泣曰：『君臣之際乃如是耶！』」新史載其事雲：「靖五代孫彥芳，大和中，為鳳翔司錄參軍，以高祖、太宗賜靖詔書數函上之，天子悉留禁中。又敕摹詔本還賜彥芳。」即二事觀之，唐世之所以眷禮名將相者，綢繆熟復至此。漢、晉以來所不及也。","sortOrder":17},
  {"id":"s_work_dtbt_55_18","chapterId":"ch_work_dtbt_55","text":"兩道出師","sortOrder":18},
  {"id":"s_work_dtbt_55_19","chapterId":"ch_work_dtbt_55","text":"國家用兵行師，異道並出，其勝敗功罪，當隨其實而處之，則賞信罰明，人知勸戒。漢武帝遣衞青、霍去病伐匈奴，去病以功益封，又封部將四人為列侯，而青不得益封，軍吏卒皆無封侯者。宣帝遣田廣明等五將軍擊匈奴，又以常惠護烏孫兵共出，五將皆無功，而廣明及田順以罪誅，獨常惠奉使克獲封侯。宋文帝伐魏，雍州諸將柳元景等，既拔弘農陝城，戍潼關矣，而上以東軍王玄謨敗退，皆召還。其後玄謨貶黜，元景受賞。紹興七年淮西大帥劉少師罷，湖北嶽少保以母憂去。累辭起復之命。朝廷以兵部尚書呂安老、侍郎張淵道分使兩部。已而正除宣撫，遂掌其軍。嶽在九江，憂兵柄一失，不容再得，亟兼程至鄂，有旨復故任，而召淵道為樞密都承旨。安老在廬遭變，言者論罷張魏公，淵道亦繼坐斥。隆興中，北虜再動兵，張公為督帥，遣李顯忠、邵宏淵攻符離，失利而退，一府皆貶秩。是時，汪莊敏以參知政事督視荊、襄，東西不相為謀，乃亦坐譴。古今不侔如此。","sortOrder":19},
  {"id":"s_work_dtbt_55_20","chapterId":"ch_work_dtbt_55","text":"杜韓用歇後語","sortOrder":20},
  {"id":"s_work_dtbt_55_21","chapterId":"ch_work_dtbt_55","text":"杜、韓二公作詩，或用歇後語，如「悽其望呂葛」，「仙鳥仙花吾友於」，「友於皆挺拔」，「再接再礪乃」，「僮僕誠自鄶」，「為爾惜居諸」，「誰謂貽厥無基趾」之類是已。","sortOrder":21},
  {"id":"s_work_dtbt_55_22","chapterId":"ch_work_dtbt_55","text":"唐明皇賜二相物","sortOrder":22},
  {"id":"s_work_dtbt_55_23","chapterId":"ch_work_dtbt_55","text":"唐明皇以李林甫為右相，顓付大政，而左相牛仙客、李適之、陳希烈前後同列，皆拱手備員。林甫死，楊國忠代之，其寵遇愈甚。天寶十三載，上御躍龍殿門，張樂宴羣臣，賜右相絹一千五百匹，綵羅三百匹，綵綾五百匹，而賜左相絹三百，羅、綾各五十而已。其多寡不侔，至於五倍。如希烈庸才，知上恩意，安得不奴事之乎？宜其甘心臣於祿山也。","sortOrder":23},
  {"id":"s_work_dtbt_55_24","chapterId":"ch_work_dtbt_55","text":"一百五日","sortOrder":24},
  {"id":"s_work_dtbt_55_25","chapterId":"ch_work_dtbt_55","text":"今人謂寒食為一百五者，以其自冬至之後至清明，歷節氣六，凡為一百七日，而先兩日為寒食故雲，他節皆不然也。杜老有鄜州一百五日夜對月一篇，江西宗派詩雲「一百五日足風雨，三十六峯勞夢魂」，「一百五日寒食雨，二十四番花信風」之類是也。吾州城北芝山寺，為禁煙遊賞之地，寺僧欲建華嚴閣，請予作勸緣疏，其末一聯雲：「大善知識五十三，永壯人天之仰；寒食清明一百六，鼎來道俗之觀。」或問一百六所出，應之曰：「元微之連昌宮詞：『初過寒食一百六，店舍無煙宮樹綠。』」是以用之。","sortOrder":25},
  {"id":"s_work_dtbt_55_26","chapterId":"ch_work_dtbt_55","text":"老杜寒山詩","sortOrder":26},
  {"id":"s_work_dtbt_55_27","chapterId":"ch_work_dtbt_55","text":"老杜春日憶李白詩雲：「白也詩無敵，飄然思不羣。清新庾開府，俊逸鮑參軍。」嘗有武弁議其失曰：「既是無敵，又却似庾、鮑。」或折之曰：「庾清新而不能俊逸，鮑俊逸而不能清新。太白兼之，所以為無敵也。」今集別本一作無數，殆好事者更之乎？寒山子詩雲：「吾心似秋月，碧潭清皎潔。無物堪比倫，教我如何說？」人亦有言，既似秋月、碧潭，乃以為無物堪比，何也？蓋其意謂若無二物比倫，當如何說耳？讀者當以是求之。","sortOrder":27},
  {"id":"s_work_dtbt_55_28","chapterId":"ch_work_dtbt_55","text":"礜石之毒","sortOrder":28},
  {"id":"s_work_dtbt_55_29","chapterId":"ch_work_dtbt_55","text":"讀黃伯思東觀餘論，內評王大令書一節，曰：「靜息帖雲：『礜石深是可疑事，兄憙患散輒發癰。』散者，寒食散之類。散中蓋用礜石，是性極熱有毒，故雲深可疑也。劉表在荊州，與王粲登障山，見一岡不生百草，粲曰：『此必古冢，其人在世服生礜石，熱蒸出外，故草木焦滅。』鑿看果墓，礜石滿塋。又今洛水冬月不冰，古人謂之溫洛，下亦有礜石。今取此石置甕水中，水亦不冰。又鸛伏卵以助煖氣。其烈酷如此，固不宜餌服。子敬之語實然。」淮南子曰：「人食礜石死，蠶食之而不饑。」予仲兄文安公鎮金陵，因秋暑減食，當塗醫湯三益教以服礜石圓，已而飲啖日進，遂加意服之，越十月而毒作，鼻衄血斗餘，自是數數不止，竟至精液皆竭，迨於捐館。偶見其語，使人追痛，因書之以戒未來者。","sortOrder":29},
  {"id":"s_work_dtbt_55_30","chapterId":"ch_work_dtbt_55","text":"會合聯句","sortOrder":30},
  {"id":"s_work_dtbt_55_31","chapterId":"ch_work_dtbt_55","text":"韻略上聲二腫字險窄。予向作汪莊敏銘詩八十句，唯蕭敏中讀之，曰：「押盡一韻。」今考之，猶有十字越用一董內韻。其詞曰：「維天生材，萬彙傾竦。侯王將相，曾是有種？公家江東，世繹耕壟。桃溪之涘，是播是（禾悤）。孰丰厥培，蓺此圭珙。公羈未奮，逸駕思駷。沈酣春秋，蹈迪周孔。徑策名第，稍辭渫（宂辱）。橫經湘沅，士敬如捧。蓬萊方丈，佩飾有琫。應龍天飛，薈蔚雲滃。千官在序，摩厲從臾。吾惟片言，藉箸泉湧。正冠霜臺，過者卞悚。顏顏殿戺，聲氣不動。顯仁東欑，巫史呼洶。昌言一下，恩浹千冢。獯粥孔熾，邊戒毛氄。媕婀當位，左掣右壅。公雲當今，沸渭混澒。天威震耀，誰不憤踴。遂遷中司，西柄是董。出關啟旆，籌檄倥偬。業業荊襄，將懦曰拱。投袂電赴，如尊乃勇。鄧唐蔡陳，馳捷系踵。佛狸歸骴，民恃不恐。璽書賜朝，百揆參總。亞勳贊冊，國勢尊鞏。督軍載西，寄責冞重。方規許洛，事援秦隴。符離罔功，奇畫膠拲。鈞樞建使，宰席亢寵。還臨西州，夾道歡擁。有銜未鬯，病癖且尰。曾不憖遺，使我心懵。湘湖高丘，草木蔚蓊。維水容裔，維山巃嵸。矢其銘詩，詞費以冗。奈何乎公，萬禩毋聳。」若韓、孟、籍、徹會合聯句三十四韻，除蝝蛹二字韻略不收外，餘皆不出二腫中，雄奇激越，如大川洪河，不見涯涘，非瑣瑣潢汙行潦之水所可同語也。其詩曰：「離別言無期，會合意冞重。病添兒女戀，老喪丈夫勇。劍心知未死，詩思猶孤聳。愁去劇箭飛，讙來若泉湧。析言多新貫，攄抱無昔壅。念難須勤追，悔易勿輕踵。吟巴山犖嶨，說楚波堆壟。馬辭虎豹怒，舟出蛟鼉恐。狂鯨時孤軒，幽狖雜百種。瘴衣常腥膩，蠻器多疏冗。剝苔弔斑林，角飯餌沈塚。忽爾銜遠命，歸歟舞新寵。鬼窟脫幽妖，天居覿清拱。京遊步方振，謫夢意猶恟。詩書誇舊知，酒食接新奉。嘉言寫清越，瘉病失肬腫。夏陰偶高庇，宵魂接虛擁。雪絃寂寂聽，茗盌纖纖捧。馳輝燭浮螢，幽響泄潛蛬。詩老獨何心，江疾有餘尰。我家本瀍穀，有地介皋鞏。休跡憶沈冥，峩冠慚闟（宂辱）。升朝高轡逸，振物羣聽悚。徒言濯幽泌，誰與薙荒茸。朝紳鬱青綠，馬飾曜珪珙。國仇未銷鑠，我志蕩邛隴。君才誠倜儻，時論方洶溶。格言多彪蔚，縣解無梏拲。張生得淵源，寒色拔山冢。堅如撞羣金，眇若抽獨蛹。伊餘何所擬？跛（上敝下黽）詎能踴。塊然墮嶽石，飄爾罥巢氄。龍旆垂天衢，雲韶凝禁甬。君胡眠安然，朝鼓聲洶洶。」其間或有纇句，然衆手立成，理如是也。","sortOrder":31},
  {"id":"s_work_dtbt_56_1","chapterId":"ch_work_dtbt_56","text":"卷第五(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_56_2","chapterId":"ch_work_dtbt_56","text":"土木偶人","sortOrder":2},
  {"id":"s_work_dtbt_56_3","chapterId":"ch_work_dtbt_56","text":"趙德甫作金石錄，其跋漢居攝墳壇二刻石雲：「其一上穀府卿墳壇，其一祝其卿墳壇。曰墳壇者，古未有土木像，故為壇以祀之。兩漢時皆如此。」予案戰國策所載，蘇秦謂孟嘗君曰：「有土偶人與桃梗相語。桃梗曰：『子西岸之土也，埏子以為人，雨下水至，則汝殘矣。』土偶曰：『子東國之桃梗也，刻削子以為人，雨降水至，流子而去矣。』」所謂土木為偶人，非像而何？漢至寓龍、寓車馬，皆謂以木為之，像其真形。謂之兩漢未有，則不可也。","sortOrder":3},
  {"id":"s_work_dtbt_56_4","chapterId":"ch_work_dtbt_56","text":"饒州風俗","sortOrder":4},
  {"id":"s_work_dtbt_56_5","chapterId":"ch_work_dtbt_56","text":"嘉祐中，吳孝宗子經者，作餘幹縣學記，雲：「古者江南不能與中土等，宋受天命，然後七閩二浙與江之西東，冠帶詩、書，翕然大肆，人才之盛，遂甲於天下。江南既為天下甲，而饒人喜事，又甲於江南。蓋饒之為州，壤土肥而養生之物多，其民家富而戶羨，蓄百金者不在富人之列。又當寬平無事之際，而天性好善，為父兄者，以其子與弟不文為咎；為母妻者，以其子與夫不學為辱。其美如此。」予觀今之饒民，所謂家富戶羨，了非昔時，而高甍巨棟連阡亙陌者，又皆數十年來寓公所擅，而好善為學，亦不盡如吳記所言。故錄其語以寄一嘆。","sortOrder":5},
  {"id":"s_work_dtbt_56_6","chapterId":"ch_work_dtbt_56","text":"禽畜菜茄色不同","sortOrder":6},
  {"id":"s_work_dtbt_56_7","chapterId":"ch_work_dtbt_56","text":"禽畜、菜茄之色，所在不同，如江、浙間，猪黑而羊白，至江、廣、吉州以西，二者則反是。蘇、秀間，鵝皆白，或有一斑褐者，則呼為雁鵝，頗異而畜之。若吾鄉，凡鵝皆雁也。小兒至取浙中白者飼養，以為湖沼觀美。浙西常茄皆皮紫，其皮白者為水茄。吾鄉常茄皮白，而水茄則紫。其異如是。","sortOrder":7},
  {"id":"s_work_dtbt_56_8","chapterId":"ch_work_dtbt_56","text":"伏龍肝","sortOrder":8},
  {"id":"s_work_dtbt_56_9","chapterId":"ch_work_dtbt_56","text":"本草伏龍肝，陶隱居雲：「此竈中對釜月下黃土也。以竈有神，故呼為伏龍肝。幷以透隱為名爾。」雷公雲：「凡使勿誤用竈下土，其伏龍肝，是十年已來竈額內火氣積，自結如赤色石，中黃，其形貌八稜。」予嘗見臨安醫官陳輿大夫，言當以砌竈時，納猪肝一具於土中，俟其積久，與土為一，然後用之，則稍與名相應。比讀後漢書陰識傳雲：「其先陰子方，臘日晨炊而竈神形見。」註引雜五行書曰：「宜市買猪肝泥竈，令婦孝。」然則輿之說亦有所本雲。廣濟曆亦有此說，又列作竈忌日，雲：「伏龍在不可移作。」所謂伏龍者，竈之神也。","sortOrder":9},
  {"id":"s_work_dtbt_56_10","chapterId":"ch_work_dtbt_56","text":"勇怯無常","sortOrder":10},
  {"id":"s_work_dtbt_56_11","chapterId":"ch_work_dtbt_56","text":"「民無常勇，亦無常怯，有氣則實，實則勇，無氣則虛，虛則怯，怯勇虛實，其由甚微，不可不知。勇則戰，怯則北，戰而勝者，戰其勇者也，戰而北者，戰其怯者也。怯勇無常，倏忽往來，而莫知其方，惟聖人獨見其所由然。」此呂氏春秋決勝篇之語，予愛而書之。","sortOrder":11},
  {"id":"s_work_dtbt_56_12","chapterId":"ch_work_dtbt_56","text":"趙德甫金石錄","sortOrder":12},
  {"id":"s_work_dtbt_56_13","chapterId":"ch_work_dtbt_56","text":"東武趙明誠德甫，清憲丞相中子也。著金石錄三十篇，上自三代，下訖五季，鼎、鐘、甗、鬲、槃、匜、尊、爵之款識，豐碑大碣顯人晦士之事蹟，見於石刻者，皆是正譌謬，去取褒貶，凡為卷二千。其妻易安李居士，平生與之同志，趙沒後，愍悼舊物之不存，乃作後序，極道遭罹變故本末。今龍舒郡庫刻其書，而此序不見取，比獲見元稿於王順伯，因為撮述大概雲：","sortOrder":13},
  {"id":"s_work_dtbt_56_14","chapterId":"ch_work_dtbt_56","text":"「予以建中辛巳歸趙氏，時丞相作吏部侍郎，家素貧儉，德甫在太學，每朔望謁告出，質衣取半千錢，步入相國寺，市碑文果實歸，相對展玩咀嚼。後二年，從宦，宦便有窮盡天下古文奇字之志，傳寫未見書，買名人書畫、古奇器。有持徐熙牡丹圖求錢二十萬，留信宿，計無所得，捲還之，夫婦相向惋悵者數日。","sortOrder":14},
  {"id":"s_work_dtbt_56_15","chapterId":"ch_work_dtbt_56","text":"「及連守兩郡，竭俸入以事鉛槧，每獲一書，即日勘校裝緝，得名畫彝器，亦摩玩舒卷，摘指疵病，盡一燭為率。故紙札精緻，字畫全整，冠於諸家。每飯罷，坐歸來堂，烹茶，指堆積書史，言某事在某書某卷第幾葉第幾行，以中否勝負，為飲茶先後，中則舉杯大笑，或至茶覆懷中，不得飲而起。凡書史百家字不刓缺、本不誤者，輒市之，儲作副本。","sortOrder":15},
  {"id":"s_work_dtbt_56_16","chapterId":"ch_work_dtbt_56","text":"「靖康丙午，德甫守淄川，聞虜犯京師，盈箱溢篋，戀戀悵悵，知其必不為己物。建炎丁未，奔太夫人喪南來，既長物不能盡載，乃先去書之印本重大者，畫之多幅者，器之無款識者，已又去書之監本者，畫之平常者，器之重大者，所載尚十五車，連艫渡淮、江。其青州故第所鎖十間屋，期以明年具舟載之，又化為煨燼。","sortOrder":16},
  {"id":"s_work_dtbt_56_17","chapterId":"ch_work_dtbt_56","text":"「己酉歲六月，德甫駐家池陽，獨赴行都，自岸上望舟中告別。予意甚惡，呼曰：『如傳聞城中緩急，奈何？』遙應曰：『從衆，必不得已，先棄輜重，次衣衾，次書冊，次卷軸，次古器。獨宗器者可自負抱，與身俱存亡，勿忘之！』徑馳馬去。秋八月，德甫以病不起。時六宮往江西，予遣二吏，部所存書二萬卷，金石刻二千本，先往洪州，至冬，虜陷洪，遂盡委棄。所謂連艫渡江者，又散為雲煙矣！獨餘輕小卷軸，寫本李杜韓柳集、世說、鹽鐵論、石刻數十副軸，鼎鼐十數，及南唐書數篋，偶在臥內，巋然獨存。上江既不可往，乃之台、溫，之衢，之越，之杭，寄物於嵊縣。庚戌春，官軍收叛卒，悉取去，入故李將軍家。巋然者十失五六，猶有五七簏，挈家寓越城，一夕為盜穴壁，負五簏去，盡為吳說運使賤價得之。僅存不成部帙殘書策數種。","sortOrder":17},
  {"id":"s_work_dtbt_56_18","chapterId":"ch_work_dtbt_56","text":"「忽閱此書，如見故人，因憶德甫在東萊靜治堂，裝褾初就，芸簽縹帶，束十卷作一帙，日校二卷，跋一卷，此二千卷，有題跋者五百二卷耳。今手澤如新，墓木已拱！乃知有有必有無，有聚必有散，亦理之常，又胡足道？所以區區記其終始者，亦欲為後世好古博雅者之戒雲。」","sortOrder":18},
  {"id":"s_work_dtbt_56_19","chapterId":"ch_work_dtbt_56","text":"時紹興四年也，易安年五十二矣，自敍如此。予讀其文而悲之，為識於是書。","sortOrder":19},
  {"id":"s_work_dtbt_56_20","chapterId":"ch_work_dtbt_56","text":"韓文公薦士","sortOrder":20},
  {"id":"s_work_dtbt_56_21","chapterId":"ch_work_dtbt_56","text":"唐世科舉之柄，顓付之主司，仍不糊名。又有交朋之厚者為之助，謂之通榜，故其取人也畏於譏議，多公而審。亦有脅於權勢，或撓於親故，或累於子弟，皆常情所不能免者。若賢者臨之則不然，未引試之前，其去取高下，固已定於胸中矣。","sortOrder":21},
  {"id":"s_work_dtbt_56_22","chapterId":"ch_work_dtbt_56","text":"韓文公與祠部陸員外書雲：「執事與司貢士者相知識，彼之所望於執事者，至而無間，彼之職在乎得人，執事之職在乎進賢，如得其人而授之，所謂兩得矣。愈之知者，有侯喜、侯雲長、劉述古、韋羣玉，(摭言作紓。)此四子者，可以當首薦而極論，期於成而後止可也。沈（木巳）、張苰、(科記又作弘。)尉遲汾、李紳、張後餘、李翊，皆出羣之才，與之足以收人望，而得才實，主司廣求焉，則以告之可也。往者陸相公司貢士，愈時幸在得中，所與及第者，皆赫然有聲。原其所以，亦由梁補闕肅、王郎中礎佐之。梁舉八人無有失者，其餘則王皆與謀焉。陸相於王與梁如此不疑也，至今以為美談。」此書在集中不註歲月。案摭言雲：「貞元十八年，權德輿主文，陸傪員外通榜，韓文公薦十人於傪，權公凡三榜，共放六人，餘不出五年內皆捷。」以登科記考之，貞元十八年，德輿以中書舍人知舉，放進士二十三人，尉遲汾、侯雲長、韋紓、沈（木巳）、李翊登第。十九年，以禮部侍郎放二十人，侯喜登第。永貞元年，放二十九人，劉述古登第。通三榜，共七十二人，而韓所薦者預其七。元和元年，崔邠下放李紳，二年，又放張後餘、張弘。皆與摭言合。","sortOrder":22},
  {"id":"s_work_dtbt_56_23","chapterId":"ch_work_dtbt_56","text":"陸傪在貞元間，時名最著，韓公敬重之。其行難一篇為傪作也，曰：「陸先生之賢聞於天下，是是而非非。自越州召拜祠部，京師之人日造焉。先生曰：『今之用人也不詳，位於朝者，吾取某與某而已，在下者多於朝，凡吾與者若幹人。』」又送其刺歙州序曰：「君出刺歙州，朝廷耆舊之賢，都邑遊居之良，齎咨涕洟，鹹以為不當去。」則傪之以人物為己任久矣。其刺歙以十八年二月，權公放榜時，既以去國，而用其言不替，其不負公議而采人望，蓋與陸宣公同。","sortOrder":23},
  {"id":"s_work_dtbt_56_24","chapterId":"ch_work_dtbt_56","text":"韓公與書時，方為四門博士，居百寮底，殊不以其薦為犯分。故公作權公碑雲：「典貢士，薦士於公者，其言可信，不以其人布衣不用；即不可信，雖大官勢人交言，一不以綴意。」又雲：「前後考第進士，及庭所策試士，踴相躡為宰相達官，其餘布處臺閣外府，凡百餘人。」梁肅及傪，皆為後進領袖，一時龍門，惜其位不通顯也，豈非汲引善士為當國者所忌乎？韓公又有答劉正夫書雲：「舉進士者，於先進之門，何所不往？先進之於後輩，苟見其至，寧可以不答其意邪？來者則接之，舉城士大夫，莫不皆然，而愈不幸獨有接後進名。」以是觀之，韓之留意人士可見也。","sortOrder":24},
  {"id":"s_work_dtbt_56_25","chapterId":"ch_work_dtbt_56","text":"王勃文章","sortOrder":25},
  {"id":"s_work_dtbt_56_26","chapterId":"ch_work_dtbt_56","text":"王勃等四子之文，皆精切有本原。其用駢儷作記序碑碣，蓋一時體格如此，而後來頗議之。杜詩雲：「王、楊、盧、駱當時體，輕薄為文哂未休。爾曹身與名俱滅，不廢江河萬古流。」正謂此耳。身名俱滅，以責輕薄子。江河萬古流，指四子也。韓公滕王閣記雲：「江南多遊觀之美，而滕王閣獨為第一。及得三王所為序、賦、記等，壯其文辭。」註謂：「王勃作遊閣序。」又雲：「中丞命為記，竊喜載名其上，詞列三王之次，有榮耀焉。」則韓之所以推勃，亦為不淺矣。勃之文今存者二十七卷雲。","sortOrder":26},
  {"id":"s_work_dtbt_56_27","chapterId":"ch_work_dtbt_56","text":"呂覽引詩書","sortOrder":27},
  {"id":"s_work_dtbt_56_28","chapterId":"ch_work_dtbt_56","text":"呂氏春秋有始覽諭大篇，引夏書曰：「天子之德，廣運乃神，乃武乃文。」又引商書曰：「五世之廟，可以觀怪，萬夫之長，可以生謀。」高誘註皆曰：「逸書也。廟者，鬼神之所在，五世久遠，故於其所觀魅物之怪異也。」予謂呂不韋作書時，秦未有詩、書之禁，何因所引訛謬如此？高誘註文怪異之說，一何不典之甚邪？又孝行覽，亦引商書曰：「刑三百，罪莫重於不孝。」今安得有此文，亦與孝經不合。又引周書曰：「若臨深淵，若履薄冰。」註雲：「周書，周文公所作。」尤妄也。又以「普天之下，莫非王土，率土之濱，莫非王臣」，為舜自作詩，「子惠思我，褰裳涉洧，子不我思，豈無他士？」為子產答叔向之詩。不知是時國風、雅、頌何所定也。甯戚飯牛歌，高誘全引碩鼠三章，又為可笑。","sortOrder":28},
  {"id":"s_work_dtbt_56_29","chapterId":"ch_work_dtbt_56","text":"藍田丞壁記","sortOrder":29},
  {"id":"s_work_dtbt_56_30","chapterId":"ch_work_dtbt_56","text":"韓退之作藍田縣丞廳壁記，柳子厚作武功縣丞廳壁記，二縣皆京兆屬城，在唐為畿甸，事體正同，而韓文雄拔超峻，光前絕後，以柳視之，殆猶碔砆之與美玉也。莆田方崧卿得蜀本，數處與今文小異，其「破崖岸而為文」一句，繼以「丞廳故有記」，蜀本無而字。考其語脈，乃「破崖岸為文丞」是句絕。文丞者，猶言文具備員而已，語尤奇崛，若以丞字屬下句，則既是丞廳記矣，而又雲「丞廳故有記」，雖初學為文者不肯爾也。此篇之外，不復容後人出手。侄孫倬，頃丞宣城，後生頗有意斯道，自作題名記示予。予曉之曰：「他文尚可隨力工拙下筆，至如此記，豈宜犯不韙哉！」倬時已勒石，深悔之。近日亦見有為之者，吾家孫侄多京官調選，再轉必為丞，慮其復有效尤者，故書以戒之。","sortOrder":30},
  {"id":"s_work_dtbt_56_31","chapterId":"ch_work_dtbt_56","text":"錢武肅三改元","sortOrder":31},
  {"id":"s_work_dtbt_56_32","chapterId":"ch_work_dtbt_56","text":"歐陽公五代史敍列國年譜雲：「聞於故老，謂吳越亦嘗稱帝改元，而求其事跡不可得，頗疑吳越後自諱之。及旁採諸國書，與吳越往來者多矣，皆無稱帝之事。獨得其封落星石為寶石山製書，稱寶正六年辛卯耳。」王順伯收碑，有臨安府石屋崇化寺尊勝幢雲：「時天寶四年歲次辛未四月某日，元帥府府庫使王某。」又明慶寺白傘蓋陀羅尼幢雲：「吳越國女弟子吳氏十五娘建。」其發願文序曰：「十五娘生忝霸朝，貴彰國懿。天寶五年太歲壬申月日題。」順伯考其歲年，知非唐天寶，而辛未乃梁開平五年，其五月改乾化，壬申乃二年。梁以丁卯篡唐，武肅是歲猶用唐天祐，次年自建元也。錢唐湖廣潤龍王廟碑雲：「錢鏐貞明二年丙子正月建。」新功臣壇院碑、封睦州牆下神廟敕，皆貞明中登聖寺磨崖，梁龍德元年，歲次辛巳，錢鏐建。又有龍德三年上宮詩，是歲梁亡。九里松觀音尊勝幢：「寶大二年歲次乙酉建。」衢州司馬墓志雲：「寶大二年八月歿。」順伯案，乙酉乃唐莊宗同光三年，其元年當在甲申。蓋自壬申以後用梁紀元，至後唐革命，復自立正朔也。又水月寺幢雲：「寶正元年丙戌十月，具位錢鏐建。」是年為明宗天成。招賢寺幢雲：「丁亥寶正二年。」又小昭慶金牛、碼碯等九幢，皆二年至五年所刻。貢院前橋柱，刻寶正六年歲在辛卯造。然則寶大止二年，而改寶正。寶正盡六年，次年壬辰，有天竺日觀庵經幢，復稱長興三年八月，用唐正朔，其年三月，武肅薨。方寢疾，語其子元瓘曰：「子孫善事中國，勿以易姓廢事大之禮。」於是以遺命去國儀，用藩鎮法，然則有天寶、寶大、寶正三名，歐陽公但知其一耳。通鑑亦然。自是歷晉、漢、周及本朝，不復建元。今猶有清泰、天福、開運、會同、(係契丹年。)乾祐、廣順、顯德石刻，存者三四十種，固未嘗稱帝也。","sortOrder":32},
  {"id":"s_work_dtbt_56_33","chapterId":"ch_work_dtbt_56","text":"黃庭換鵝","sortOrder":33},
  {"id":"s_work_dtbt_56_34","chapterId":"ch_work_dtbt_56","text":"李太白詩雲：「山陰道士如相見，應寫黃庭換白鵝。」蓋用王逸少事也。前賢或議之曰：「逸少寫道德經，道士舉鵝羣以贈之。」元非黃庭，以為太白之誤。予謂太白眼高四海，衝口成章，必不規規然，旋檢閱晉史，看逸少傳，然後落筆，正使誤以道德為黃庭，於理正自無害，議之過矣。東坡雪堂既毀，紹興初，黃州一道士自捐錢粟再營建，士人何頡斯舉作上梁文，其一聯雲：「前身化鶴，曾陪赤壁之遊；故事換鵝，無復黃庭之字。」乃用太白詩為出處，可謂奇語。案張彥遠法書要錄，載褚遂良右軍書目，正書有黃庭經雲。註：六十行。與山陰道士真蹟故在。又武平一徐氏法書記雲：「武後曝太宗時法書六十餘函，有黃庭。」又徐季海古蹟記：「玄宗時，大王正書三卷，以黃庭為第一。」皆不雲有道德經，則知乃晉傳誤也。","sortOrder":34},
  {"id":"s_work_dtbt_56_35","chapterId":"ch_work_dtbt_56","text":"宋桑林","sortOrder":35},
  {"id":"s_work_dtbt_56_36","chapterId":"ch_work_dtbt_56","text":"左傳：「宋公享晉侯於楚丘，請以桑林。」註，桑林者，殷天子之樂名。「舞師題以旌夏。晉侯懼而退，及著雍疾，卜桑林見。荀偃、士匄欲奔請禱焉，荀罃不可。」予案呂氏春秋雲：「武王勝殷，立成湯之後於宋，以奉桑林。」高誘註曰：「桑山之林，湯所禱也。故使奉之。」淮南子雲：「湯旱，以身禱於桑山之林。」許叔重註曰：「桑山之林，能興雲致雨，故禱之。」「桑林」二說不同。杜預註左傳不曾引用，豈非是時未見其書乎？","sortOrder":36},
  {"id":"s_work_dtbt_56_37","chapterId":"ch_work_dtbt_56","text":"馮夷姓字","sortOrder":37},
  {"id":"s_work_dtbt_56_38","chapterId":"ch_work_dtbt_56","text":"張衡思玄賦：「號馮夷俾清津兮，櫂龍舟以濟予。」李善註文選引青令傳曰：「河伯姓馮氏，名夷，浴於河中而溺死，是為河伯。」太公金匱曰：「河伯姓馮名修。」裴氏新語謂為馮夷。莊子曰：「馮夷得之以遊大川。」淮南子曰：「馮夷服夷石而水仙。」後漢張衡傳註，引聖賢冢墓記曰：「馮夷者，弘農華陰潼鄉堤首里人，服八石，得水仙，為河伯。」又龍魚河圖曰：「河伯姓呂名公子，夫人姓馮名夷。」唐碑有河侯新祠頌，秦宗撰，文曰：「河伯姓馮名夷，字公子。」數說不同，然皆不經之傳也。蓋本於屈原遠遊篇，所謂「使湘靈鼓瑟兮，令海若舞馮夷。」前此未有用者。淮南子原道訓又曰：「馮夷、大丙之御也，乘雲車，入雲蜺。」許叔重雲：「皆古之得道能御陰陽者。」此自別一馮夷也。","sortOrder":38},
  {"id":"s_work_dtbt_57_1","chapterId":"ch_work_dtbt_57","text":"卷第六(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_57_2","chapterId":"ch_work_dtbt_57","text":"韓文公逸詩","sortOrder":2},
  {"id":"s_work_dtbt_57_3","chapterId":"ch_work_dtbt_57","text":"唐五竇聯珠集載，竇牟為東都判官，陪韓院長、韋河南同尋劉師，不遇，分韻賦詩。都官員外郎韓愈得尋字，其語雲：「秦客何年駐，仙源此地深。還隨躡鳧騎，來訪馭雲襟。院閉青霞入，松高老鶴尋。猶疑隱形坐，敢起竊桃心。」今諸本韓集皆不載。近者莆田方崧卿考證訪賾甚至，猶取聯珠中竇庠酬退之登嶽陽樓一大篇，顧獨遺此，何也？","sortOrder":3},
  {"id":"s_work_dtbt_57_4","chapterId":"ch_work_dtbt_57","text":"竇叔向詩不存","sortOrder":4},
  {"id":"s_work_dtbt_57_5","chapterId":"ch_work_dtbt_57","text":"竇氏聯珠序雲，五竇之父叔向，當代宗朝，善五言詩，名冠流輩。時屬貞懿皇後山陵，上註意哀挽，即時進三章，內考首出，傳諸人口。有「命婦羞蘋葉，都人插柰花」，「禁兵環素帟，宮女哭寒雲」之句。可謂佳唱，而略無一首存於今。荊公百家詩選亦無之，是可惜也。予嘗得故吳良嗣家所抄唐詩，僅有叔向六篇，皆奇作。念其不傳於世，今悉錄之。夏夜宿表兄話舊雲：「夜合花開香滿庭，夜深微雨醉初醒。遠書珍重何時達，舊事淒涼不可聽。去日兒童皆長大，昔年親友半凋零。明朝又是孤舟別，愁見河橋酒幔青。」秋砧送包大夫雲：「斷續長門夜，清泠逆旅秋。征夫應待信，寒女不勝愁。帶月飛城上，因風散陌頭。離居偏入聽，况復送歸舟。」春日早朝應製雲：「紫殿俯千官，春松應合歡。御爐香焰煖，馳道玉聲寒。乳燕翻珠綴，祥烏集露盤。宮花一萬樹，不敢舉頭看。」過簷石湖雲：「曉發魚門埭，晴看簷石湖。日銜高浪出，天入四空無。咫尺分洲島，纖毫指舳艫。渺然從此去，誰念客帆孤。」貞懿挽歌二首雲：「二陵恭婦道，六寢盛皇情。禮遜生前貴，恩追歿後榮。幼王親捧土，愛女復連塋。東望長如在，誰雲向玉京。」「後庭攀畫柳，上陌咽清笳。命婦羞蘋葉，都人插柰花。壽宮星月異，仙路往來賒。縱有迎神術，終悲隔絳紗。」第三篇亡。叔向字遺直，仕至左拾遺，出為溧水令。唐書亦稱其以詩自名雲。","sortOrder":5},
  {"id":"s_work_dtbt_57_6","chapterId":"ch_work_dtbt_57","text":"用柰花事","sortOrder":6},
  {"id":"s_work_dtbt_57_7","chapterId":"ch_work_dtbt_57","text":"竇叔向所用柰花事，出晉史，雲成帝時，三吳女子相與簪白花，望之如素柰，傳言天公織女死，為之著服。已而杜皇後崩，其言遂驗。紹興五年，寧德皇後訃音從北庭來，知徽州唐煇使休寧尉陳之茂撰疏文，有語雲：「十年罹難，終弗返於蒼梧。萬國銜冤，徒盡簪於白柰。」是時，正從徽廟蒙塵，其對偶精確如此。","sortOrder":7},
  {"id":"s_work_dtbt_57_8","chapterId":"ch_work_dtbt_57","text":"王廖兒良","sortOrder":8},
  {"id":"s_work_dtbt_57_9","chapterId":"ch_work_dtbt_57","text":"賈誼過秦論曰：「六國之士，吳起、孫臏、帶佗、兒良、王廖、田忌、廉頗、趙奢之朋製其兵。」漢書註家皆無所釋，顏師古但音兒為五奚反，廖為聊而已。此八人者，帶佗、兒良、王廖不知其何國人，獨呂氏春秋雲：「老聃貴柔，孔子貴仁，墨翟貴廉，關尹貴清，列子貴虛，陳駢貴齊，楊朱貴己，孫臏貴勢，王廖貴先，兒良貴後。」而註雲：「王廖謀兵事，貴先，建茅也。兒良作兵謀，貴後。」雖僅見二人之名，然亦莫能詳也。廖、良列於孔、老之末，而漢四種兵書，有良權謀一篇。又賈誼首稱甯越、杜赫為之謀。漢書亦不註。呂氏雲孔、墨、甯越，皆布衣之士也。越中牟人也，周威公師之。又稱杜赫以安天下說周昭文君。則越、赫善謀，可以概見。漫書之以補漢書之缺。","sortOrder":9},
  {"id":"s_work_dtbt_57_10","chapterId":"ch_work_dtbt_57","text":"徙木僨表","sortOrder":10},
  {"id":"s_work_dtbt_57_11","chapterId":"ch_work_dtbt_57","text":"商鞅變秦法，恐民不信，乃募民徙三丈之木而予五十金。有一人徙之，輒予金，乃下令。吳起治西河，欲諭其信於民，夜置表於南門之外，令於邑中曰：「有人能僨表者，仕之長大夫。」民相謂曰：「此必不信。」有一人曰：「試往僨表，不得賞而已，何傷？」往僨表，來謁吳起，起仕之長大夫。自是之後，民信起之賞罰。予謂鞅本魏人，其徙木示信，蓋以效起，而起之事不傳。","sortOrder":11},
  {"id":"s_work_dtbt_57_12","chapterId":"ch_work_dtbt_57","text":"建武中元續書","sortOrder":12},
  {"id":"s_work_dtbt_57_13","chapterId":"ch_work_dtbt_57","text":"隨筆所書建武中元一則，文惠公作隸釋，於蜀郡守何君閣道碑一篇中，以為不然。比得蜀士袁夢麒應祥漢製叢錄，亦以紀、志、傳不同為惑，而雲近歲雅州榮經縣治之西，有得蜀郡治道記於崖壁間者，記末雲：「建武中元二年六月就。」於是千載之疑，渙然冰釋。予觀何君閣道正建武中元二年六月就。袁君所言榮經崖壁之記，蓋是此耳。但以出於近歲，恨不得質之文惠，為之惻然。","sortOrder":13},
  {"id":"s_work_dtbt_57_14","chapterId":"ch_work_dtbt_57","text":"草駒聾蟲","sortOrder":14},
  {"id":"s_work_dtbt_57_15","chapterId":"ch_work_dtbt_57","text":"今人謂野牧馬為草馬，淮南子修務訓曰：「馬之為草駒之時，跳躍揚蹄，翹尾而走，人不能製。」註雲：「馬五尺以下為駒，放在草中，故曰草駒。」蓋今之所稱者是也。下文曰：「形之於馬，馬不可化，其可駕御，教之所為也。馬，聾蟲也，而可以通氣志，猶待教而成，又況人乎？」註曰：「蟲，喻無知也。」聾蟲之名甚奇。","sortOrder":15},
  {"id":"s_work_dtbt_57_16","chapterId":"ch_work_dtbt_57","text":"記李履中二事","sortOrder":16},
  {"id":"s_work_dtbt_57_17","chapterId":"ch_work_dtbt_57","text":"崇寧中，蔡京當國，欲洗邢恕誣謗宗廟之罪，既抆拭用之，又欲令立邊功以進身，於是以為涇原經略使，遂謀用車戰法，及造舟五百艘，將直抵興靈，以空夏國。詔以付熙河漕臣李復。復長安人，久居兵間，習熟戎事，力上疏詆切之。予頃書之於國史恕列傳中。比得上饒所刊潏水集，正復所為文，得此兩奏，嘆其能以區區外官而排斥上相之客如此。恨史傳為不詳盡，乃錄於此。其乞罷造戰車疏雲：「奉聖旨，令本司製造戰車三百兩。臣嘗覽載籍，古者師行，固嘗用車，蓋兵不妄動，征戰有禮，不為詭遇，多在平原廣野，故車可以行。今盡在極邊，戎狄乘勢而來，雖鷙鳥飛翥，不如是之迅捷，下寨駐軍，各以保險為利。其往也，車不及期，居而保險，車不能登，歸則虜多襲逐，爭先奔趨，不暇回顧，車安能收？非若古昔於中國為用。臣聞此議，出於許彥圭，彥圭因姚麟而獻說，朝廷遂然之，不知彥圭劇為輕妄。唐之房琯，嘗用車戰，大敗於陳濤斜，十萬義軍，無有脫者。畿邑平地且如此，况今欲用於峻阪溝穀之間乎？又戰車比常車闊六七寸，運不合轍，牽拽不行。昨來兵夫，典賣衣物，自賃牛具，終日方進五七里，遂致兵夫逃亡，棄車於道，大為諸路之患。今乞便行罷造，如別路已有造者，乞更不牽拽前來。」其乞罷造船奏雲：「邢恕乞打造船五百隻，於黃河順流放下，至會州西小河內藏放。有旨專委臣監督，限一年了當契勘。本路只有船匠一人，須乞於荊、江、淮、浙和雇。又丁線物料，亦非本路所出。觀恕奏請，實是兒戲。且造船五百隻，若自今工料並備，亦須數年。自蘭州駕放至會州，約三百里，北岸是敵境，豈可容易？會州之西，小河醎水，其闊不及一丈，深止於一二尺，豈能藏船？黃河過會州入韋精山，石峽險窄，自上垂流直下，高數十尺，船豈可過？至西安州之東，大河分為六七道，水淺灘磧，不勝舟載，一船所載，不過五馬二十人，雖到興州，又何能為？又不知幾月得至？此聲若出，必為夏國侮笑，臣未敢便依旨揮擘畫，恐虛費錢物，終誤大事。」疏既上，徽宗察其言忠，遂罷二役。復字履中，為關內名儒，官至中大夫、集英殿修撰。李昭嘗贈詩雲：「結交賴有紫髥翁，鶴骨嶄嶄爛修目。五言長城屹千丈，萬卷書樓聊一讀。」可知其人矣。","sortOrder":17},
  {"id":"s_work_dtbt_57_18","chapterId":"ch_work_dtbt_57","text":"乾寧覆試進士","sortOrder":18},
  {"id":"s_work_dtbt_57_19","chapterId":"ch_work_dtbt_57","text":"唐昭宗乾寧二年試進士，刑部尚書崔凝下二十五人。放榜後，宣詔翰林學士陸扆、祕書監馮渥入內，各贈衣一副，及氈被，於武德殿前復試，但放十五人。自狀頭張貽範以下重落，其六人許再入舉場，四人所試最下，不許再入，蘇楷其一也。故挾此憾，至於駁昭宗「聖文」之謚。崔凝坐貶合州刺史。是時，國祚如贅疣，悍鎮強藩，請隧問鼎之不暇，顧惓惓若此。其再試也，詩賦各兩篇，內良弓獻問賦，以「太宗問工人木心不正，脈理皆邪，若何道理」十七字皆取五聲字，依輪次以雙周隔句為韻，限三百二十字成。貽範等六人，訖唐末不復綴榜。蓋是時不糊名，一黜之後，主司不敢再收拾也。有黃滔者，是年及第，閩人也，九世孫沃為吉州永豐宰，刊其遺文，初試覆試凡三賦皆在焉。曲直不相入賦，以題中曲直兩字為韻。釋雲：邪正殊途，各有好惡。終篇只押兩韻。良弓獻問賦，取五聲字次第用各隨聲為賦格。於是第一韻尾句雲：「資國祚之崇崇」，上平聲也。第二韻：「垂寶祚於綿綿」，下平聲也。第三韻：「曾非唯唯」，上聲也。第四韻：「露其言而粲粲」，去聲也。而闕入聲一韻。賦韻如是，前所未有。國將亡，必多製，亦雲可笑矣。信州永豐人王正白，時再試中選，郡守為改所居坊名曰「進賢」，且減戶稅，亦後來所無。","sortOrder":19},
  {"id":"s_work_dtbt_57_20","chapterId":"ch_work_dtbt_57","text":"臨海蟹圖","sortOrder":20},
  {"id":"s_work_dtbt_57_21","chapterId":"ch_work_dtbt_57","text":"文登呂亢，多識草木蟲魚。守官台州臨海，命工作蟹圖，凡十有二種。一曰蝤蛑。乃蟹之巨者，兩螯大而有細毛如苔，八足亦皆有微毛。二曰撥棹子。狀如蝤蛑，螯足無毛，後兩小足薄而微闊，類人之所食者，然亦頗異，其大如升，南人皆呼為蟹，八月間盛出，人採之，與人鬥，其螯甚巨，往往能害人。三曰擁劍。狀如蟹而色黃，其一螯偏長三寸餘，有光。四曰彭螖。螯微毛，足無毛，以鹽藏而貨於市，爾雅曰：「彭蠌，小者蟧。」雲小蟹也。蠌音澤，蟧音勞，吳人呼為彭越。搜神記言，此物嘗通人夢，自稱「長卿」，今臨海人多以「長卿」呼之。五曰竭朴。大於彭螖，壳黑斑，有文章，螯正赤，常以大螯障目，小螯取食。六曰沙狗。似彭螖，壤沙為穴，見人則走，屈折易道不可得。七曰望潮。壳白色，居則背坎外向，潮欲來，皆出坎舉螯如望，不失常期。八曰倚望。亦大如彭螖，居常東西顧睨，行不四五，又舉兩螯，以足起望，惟入穴乃止。九曰石蜠。大於常蟹，八足，壳通赤，狀若鵝卵。十曰蜂江。如蟹，兩螯足極小，堅如石，不可食。十一曰蘆虎。似彭蜞，正赤，不可食。十二曰彭蜞。大於螖，小於常蟹。呂君雲：「此皆常所見者，北人罕見，故繪以為圖。又海商言，海中（上句下黽）鼊島之東，一島多蟹，種類甚異。有虎頭者，有翅能飛者，有能捕魚者，有壳大兼尺者，以非親見，故不畫。」李履中得其一本，為作記。予家楚，宦遊二浙、閩、廣，所識蟹屬多矣。亦不悉與前說同。而所謂黃甲，白蟹、蟳、蠘諸種，呂圖不載，豈名謂或殊乎？故紀其詳以示博雅者。","sortOrder":21},
  {"id":"s_work_dtbt_57_22","chapterId":"ch_work_dtbt_57","text":"東坡作碑銘","sortOrder":22},
  {"id":"s_work_dtbt_57_23","chapterId":"ch_work_dtbt_57","text":"東坡祭張文定文雲：「軾於天下，未嘗銘墓，獨銘五人，皆盛德故。」以文集考之，凡七篇。若富韓公、司馬溫公、趙清獻公、范蜀公幷張公，坡所自作。此外趙康靖、滕元發二誌，乃代張公者，故不列於五人之數。眉州小集有元祐中奏稿雲：「臣近准敕差撰故同知樞密院事趙瞻神道碑幷書者，臣平生本不為人撰行狀、埋銘、墓碑，士大夫所共知。只因近日撰司馬光行狀，蓋為光曾為臣亡母程氏撰埋銘，又為范鎮撰墓誌，蓋為鎮與先臣某平生交契至深，不可不撰。及奉詔撰司馬光、富弼等墓碑，不可固辭，然終非本志，况臣老病廢學，文詞鄙陋，不稱人子所欲顯揚其親之意，伏望聖慈別擇能者，特許辭免。」觀此一奏，可印公心。而杭本奏議十五卷中不載。","sortOrder":23},
  {"id":"s_work_dtbt_57_24","chapterId":"ch_work_dtbt_57","text":"洗兒金錢","sortOrder":24},
  {"id":"s_work_dtbt_57_25","chapterId":"ch_work_dtbt_57","text":"車駕都錢塘以來，皇子在邸生男及女，則戚里、三衙、浙漕、京尹，皆有餉獻，隨即致答，自金幣之外，洗兒錢果，動以十數合，極其珍巧，若總而言之，殆不可勝算，莫知其事例之所起。劉原甫在嘉祐中，因論無故疏決雲：「在外羣情，皆雲聖意以皇女生，故施此慶，恐非王者之令典也。又聞多作金銀、犀象、玉石、琥珀、玳瑁、檀香等錢，及鑄金銀為花果，賜予臣下，自宰相、臺諫，皆受此賜。無益之費，無名之賞，殆無甚於此。若欲誇示奢麗，為世俗之觀則可矣，非所以軌物訓儉也。宰相、臺諫，以道德輔主，奈何空受此賜，曾無一言，遂事不諫！臣願深執恭儉，以答上天之貺，不宜行姑息之恩，以損政體。」偉哉劉公之論，其勁切如此。歐陽公銘墓，略而不書。予為國史亦不知載於本傳，比方讀其奏章，故敬紀之。韓偓金鑾密記雲：「天復二年，大駕在岐，皇女生三日，賜洗兒果子、金銀錢、銀葉坐子、金銀鋌子。」予謂唐昭宗於是時尚復講此，而在庭無一言，蓋宮掖相承，欲罷不能也。","sortOrder":25},
  {"id":"s_work_dtbt_57_26","chapterId":"ch_work_dtbt_57","text":"告命失故事","sortOrder":26},
  {"id":"s_work_dtbt_57_27","chapterId":"ch_work_dtbt_57","text":"祖宗時知製誥六員，故朝廷除授，雖京官磨勘，選人改秩，奏薦門客、恩科助教，率皆命詞，然有官列已崇而有司不舉者，多出時相之意。劉原甫掌外製，以任顓落職，不降誥詞，曾奏陳以為非故事，得旨即施行之。已而劉元瑜、王琪降官，直以敕牒。劉又言非朝廷賞罰訓誥毖重之意。今觀劉集，有太平州文學袁嗣立改江州文學製雲：「昔先王簡不帥教而不變者，屏之裔土，終身不齒，若爾之行，豈足顧哉！然猶假以仕版，徙之善郡，不貲之恩也。勉思自新，無重其咎。」未幾，嗣立又徙洪州，製雲：「爾頃冒憲典，遷之尋陽，復以親嫌，於法當避。夫薄志節、寡廉恥者，固不可使處有嫌之地，益徙豫章，思自湔滌。」嗣立之事微矣，乃費兩誥，讀此命書，可知其人。漫書之以發一笑。","sortOrder":27},
  {"id":"s_work_dtbt_57_28","chapterId":"ch_work_dtbt_57","text":"扁字二義","sortOrder":28},
  {"id":"s_work_dtbt_57_29","chapterId":"ch_work_dtbt_57","text":"扁音薄典切，唐韻二義：其一曰扁署門戶，其一曰姓也，此外無他說。案鶡冠子雲：「五家為伍，十伍為里。四里為扁，扁為之長，十扁為鄉。其上為縣為郡。其不奉上令者，以告扁長。」蓋如遂、黨、都、保之稱。諸書皆不載。","sortOrder":29},
  {"id":"s_work_dtbt_57_30","chapterId":"ch_work_dtbt_57","text":"娑羅樹","sortOrder":30},
  {"id":"s_work_dtbt_57_31","chapterId":"ch_work_dtbt_57","text":"世俗多指言月中桂為娑羅樹，不知所起。案酉陽雜俎雲：「巴陵有寺，僧房牀下，忽生一木，隨伐而長，外國僧見曰，此娑羅也。元嘉中，出一花如蓮。唐天寶初，安西進娑羅枝，狀言：『臣所管四鎮拔汗郍國，有娑羅樹，特為奇絕，不比凡草，不止惡禽，近采得樹枝二百莖以進。』」予比得楚州淮陰縣唐開元十一年海州刺史李邕所作娑羅樹碑雲：「非中夏物土所宜有者，婆娑十畝，蔚映千人。惡禽翔而不集，好鳥止而不巢。深識者雖徘徊仰止而莫知冥植，博物者雖沈吟稱引而莫辨嘉名。隨所方面，頗證靈應，東瘁則青郊苦而歲不稔，西茂則白藏泰而秋有成。嘗有三藏義淨，還自西域，齋戒瞻嘆。於是邑宰張松質請邕述文建碑。」觀邕所言，惡禽不集，正與上說同。又有松質一書答邕雲：「此土玉像，爰及石龜，一離淮陰，百有餘載，前後抗表，尚不能稱，賴公威德備聞，所以還歸故里，謹遣僧三人，父老七人，齎狀拜謝。」宣和中，向子諲過淮陰，見此樹，今有二本，方廣丈餘，蓋非故物。蔣穎叔雲：「玉像石龜，不知今安在？」然則娑羅之異，世間無別種也。吳興芮燁國器有從沈文伯乞娑羅樹碑古風一首雲：「楚州淮陰娑羅樹，霜露榮悴今何如？能令草木死不朽，當時為有北海書。荒碑雨侵澀苔蘚，尚想墨本傳東吳。」正賦此也。歐陽公有定力院七葉木詩雲：「伊洛多佳木，娑羅舊得名。常於佛家見，宜在月宮生。釦砌陰鋪靜，虛堂子落聲。」亦此樹耳，所謂七葉者未詳。","sortOrder":31},
  {"id":"s_work_dtbt_58_1","chapterId":"ch_work_dtbt_58","text":"卷第七(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_58_2","chapterId":"ch_work_dtbt_58","text":"天　咫","sortOrder":2},
  {"id":"s_work_dtbt_58_3","chapterId":"ch_work_dtbt_58","text":"黃魯直和王定國詩聞蘇子由病臥績溪雲：「湔祓瘴霧姿，朝趨去天咫。」蜀士任淵註引「天威不違顏咫尺」。予按國語，楚靈築三城，使子晳問范無宇，無宇不可，王曰：「是知天咫，安知民則？」韋昭曰：「咫者少也，言少知天道耳。」酉陽雜俎有天咫篇。黃詩蓋用此。徐師川喜王秀才見過小酌翫月四言曰：「君家近市，所見天咫。庭戶之間，容光能幾？菰蒲之中，江湖之涘。一碧萬頃，長空千里。」正祖述黃所用雲。","sortOrder":3},
  {"id":"s_work_dtbt_58_4","chapterId":"ch_work_dtbt_58","text":"縣尉為少仙","sortOrder":4},
  {"id":"s_work_dtbt_58_5","chapterId":"ch_work_dtbt_58","text":"隨筆載縣尉為少公，予後得晏幾道叔原一帖與通叟少公者，正用此也。杜詩有野望因過常少仙一篇，所謂「落盡高天日，幽人未遣回」者，蜀士註曰：「少仙應是言縣尉也。」縣尉謂之少府，而梅福為尉，有神仙之稱。少仙二字，尤為清雅，與今俗呼為仙尉不侔矣。","sortOrder":5},
  {"id":"s_work_dtbt_58_6","chapterId":"ch_work_dtbt_58","text":"杜詩用受覺二字","sortOrder":6},
  {"id":"s_work_dtbt_58_7","chapterId":"ch_work_dtbt_58","text":"杜詩所用受覺二字皆絕奇，今摭其受字雲：「修竹不受暑」，「勿受外嫌猜」，「莫受二毛侵」，「監河受貸粟」，「輕燕受風斜」，「能事不受相促迫」，「野航恰受兩三人」，「一雙白魚不受釣」，「雄姿未受伏櫪恩」。其覺字雲：「已覺糟牀註」，「身覺省郎在」，「自覺成老醜」，「更覺松竹幽」，「日覺死生忙」，「最覺潤龍鱗」，「喜覺都城動」，「更覺老隨人」，「每覺升元輔」，「覺而行步奔」，「尚覺王孫貴」，「含悽覺汝賢」，「廚煙覺遠庖」，「詩成覺有神」，「已覺披衣慣」，「自覺酒須賒」，「早覺仲容賢」，「城池未覺喧」，「無人覺來往」，「人才覺弟優」，「直覺巫山暮」，「重覺在天邊」，「行遲更覺仙」，「深覺負平生」，「秋覺追隨盡」，「追隨不覺晚」，「熊羆覺自肥」，「自覺坐能堅」，「已覺良宵永」，「更覺綵衣春」，「已覺氣與嵩華敵」，「未覺千金滿高價」，「梅花欲開不自覺」，「胡來不覺潼關隘」，「自得隋珠覺夜明」，「放筯未覺金盤空」，「東歸貪路自覺難」，「更覺良工心獨苦」，「始覺屏障生光輝」，「不覺前賢畏後生」，「吏情更覺滄洲遠」，「我獨覺子神充實」，「習池未覺風流盡」。用之雖多，然每字命意不同，又雜於千五百篇中，學者讀之，唯見其新工也。若陳簡齋亦好用此二字，未免頻復者，蓋只在數百篇內，所以見其多，如「未受風作惡」，「不受珠璣絡」，「不受折簡呼」，「不受人招麾」，「不受安危侵」，「飽受今日閑」，「却扇受景風」，「語聞受遠響」，「坐受世故驅」，「庭柏不受寒」，「可復受憂戚」，「寧受此酸辛」，「滔滔江受風」，「坐受世褊迫」，「清池不受暑」，「平池受細雨」，「窮村受春晚」，「不受急景催」，「肯受元規塵」，「了不受榮悴」，「意閑不受榮與辱」，「獨自人間不受寒」，「枯木無枝不受寒」，「天馬何妨略受鞿」，「來禽花高不受折」，「不受陰晴與寒暑」，「長林巨木受軒輊」。「未覺懶相先」，「未覺壯心休」，「未覺身淹留」，「未覺墉陰遲」，「未覺欠孟嘉」，「未覺有等倫」，「未覺風來遲」，「未覺經旬久」，「欲往還覺非」，「獨覺賦詩難」，「稍覺夜月添」，「菰蒲覺風入」，「未覺此計非」，「高處覺眼新」，「意定覺景多」，「未覺徐娘老」，「未覺有榮辱」，「未覺饑腸虛」，「未覺平生與願違」，「村空更覺水潺湲」，「眼中微覺欠扁舟」，「居夷更覺中原好」，「便覺杯觴耐薄寒」，「牆頭花定覺風闌」，可謂多矣。蓋喜用其字，自不知下筆所著也。","sortOrder":7},
  {"id":"s_work_dtbt_58_8","chapterId":"ch_work_dtbt_58","text":"西太一宮六言","sortOrder":8},
  {"id":"s_work_dtbt_58_9","chapterId":"ch_work_dtbt_58","text":"「楊柳鳴蜩綠暗，荷花落日紅酣。三十六陂春水，白頭想見江南」荊公題西太一宮六言首篇也。今臨川刻本以「楊柳」為「柳葉」，其意欲與荷花為切對，而語句遂不佳。此猶未足問，至改「三十六陂春水」為「三十六宮煙水」，則極可笑。公本意以在京華中，故想見江南景物，何預於宮禁哉？不學者妄意塗竄，殊為害也。彼蓋以太一宮為禁廷離宮爾。","sortOrder":9},
  {"id":"s_work_dtbt_58_10","chapterId":"ch_work_dtbt_58","text":"由與猶同","sortOrder":10},
  {"id":"s_work_dtbt_58_11","chapterId":"ch_work_dtbt_58","text":"新唐書藩鎮傳序雲：「其人自視由羌狄然。」據字義，「由」當為「猶」，故吳縝作唐書音訓有糾謬一篇，正指其失，彼元不深究孟子也。文惠公頃與予作唐書補過，嘗駁其說。予作文每用之，輒為人所疑問，今為詳載於此。如「以齊王，由反手也」，「由弓人而恥為弓」，「王由足用為善」，「是由惡醉而強酒」，「由己溺之，由己飢之」，「由射於百步之外」，「見且由不得亟」，其義皆然，蓋由與猶通用也。","sortOrder":11},
  {"id":"s_work_dtbt_58_12","chapterId":"ch_work_dtbt_58","text":"人焉廋哉","sortOrder":12},
  {"id":"s_work_dtbt_58_13","chapterId":"ch_work_dtbt_58","text":"孔子論人之善惡，始之曰：「視其所以。」繼之以「觀其所由，察其所安。」然後重言之曰：「人焉廋哉，人焉廋哉！」蓋以上之三語詳察之也。而孟氏一斷以眸子，其言曰：「存乎人者，莫良於眸子。眸子不能掩其惡，胸中正，則眸子瞭焉，胸中不正，則眸子眊焉。聽其言也，觀其眸子，人焉廋哉！」說者謂：「人與物接之時，其神在目。故胸中正，則神精而明。不正，則神散而昏。心之所發，幷此而觀，則人之邪正不可匿矣。言猶可以偽為，眸子則有不容偽者。孔聖既已發之於前，孟子知言之要，續為之說，故簡亮如此。」舊見王季明雲，太學士子嘗戲作一論，其略曰：「知人焉廋哉之義，然後知人焉廋哉，人焉廋哉之義。知人焉廋哉，人焉廋哉之義，然後知人焉廋哉之義。孔子所雲人焉廋哉，人焉廋哉者，詳言之也。孟子所雲人焉廋哉者，略言之也。孔子之所謂人焉廋哉，人焉廋哉，即孟子之所謂人焉廋哉也。孟子之所謂人焉廋哉，即孔子之所謂人焉廋哉，人焉廋哉也。」繼又叠三語為一雲：「夫人焉廋哉，人焉廋哉，人焉廋哉，雖曰不同，而其所以為人焉廋哉，人焉廋哉，人焉廋哉，未始不同。」演而成數百字，可資一笑，亦幾於侮聖言矣！","sortOrder":13},
  {"id":"s_work_dtbt_58_14","chapterId":"ch_work_dtbt_58","text":"久而俱化","sortOrder":14},
  {"id":"s_work_dtbt_58_15","chapterId":"ch_work_dtbt_58","text":"天生萬物，久而與之俱化，固其理焉，無間於有情無情，有知無知也。予得雙雁於衢人鄭伯膺，純白色，極馴擾可玩，置之雲壑，不遠飛翔。未幾，殞其一，其一塊獨無儔，因念白鵝正同色，又性亦相類，乃取一隻與同處。始也，兩下不相賓接，見則東西分背，雖一盆飼穀，不肯並啜。如是五日，漸復相就，逾旬之後，怡然同羣，但形體有大小，而色澤飛鳴則一。久之，雁不自知其為雁，鵝不自知其為鵝，宛如同巢而生者，與之俱化，於是驗焉。今人呼鵝為舒雁，或稱家雁，其褐色者為雁鵝，雁之最大者曰天鵝。唐太宗時，吐蕃祿東贊上書，以謂聖功遠被，雖雁飛於天，無是之速，鵝猶雁也，遂鑄金為鵝以獻。蓋二禽一種也。","sortOrder":15},
  {"id":"s_work_dtbt_58_16","chapterId":"ch_work_dtbt_58","text":"黃文江賦","sortOrder":16},
  {"id":"s_work_dtbt_58_17","chapterId":"ch_work_dtbt_58","text":"晚唐士人作律賦，多以古事為題，寓悲傷之旨，如吳融、徐寅諸人是也。黃滔字文江，亦以此擅名，有明皇回駕經馬嵬坡隔句雲：「日慘風悲，到玉顏之死處；花愁露泣，認朱臉之啼痕。」「褒雲萬叠，斷腸新出於啼猿；秦樹千層，比翼不如於飛鳥。」「羽衞參差，擁翠華而不發；天顏愴悢，覺紅袖以難留。」「神仙表態，忽零落以無歸；雨露成波，已沾濡而不及。」「六馬歸秦，却經過於此地；九泉隔越，幾悽惻於平生。」景陽井雲：「理昧納隍，處窮泉而詎得；誠乖馭朽，攀素綆以胡顏！」「青銅有恨，也從零落於秋風；碧浪無情，寧解流傳於夜壑。」「荒涼四面，花朝而不見朱顏；滴瀝千尋，雨夜而空啼碧溜。」「莫可追尋，玉樹之歌聲邈矣；最堪惆悵，金瓶之咽處依然。」館娃宮雲：「花顏縹緲，欺樹裏之春風；銀燄熒煌，却城頭之曉色。」「恨留山鳥，啼百草之春紅；愁寄壟雲，鏁四天之暮碧。」「遺堵塵空，幾踐羣遊之鹿；滄洲月在，寧銷怒觸之濤？」陳皇後因賦復寵雲：「已為無雨之期，空懸夢寐；終自凌雲之製，能致煙霄。」秋色雲：「空三楚之暮天，樓中歷歷；滿六朝之故地，草際悠悠。」白日上升雲：「較美古今，列子之乘風固劣；論功晝夜，姮娥之奔月非優。」凡此數十聯，皆研確有情致，若夫格律之卑，則自當時體如此耳。","sortOrder":17},
  {"id":"s_work_dtbt_58_18","chapterId":"ch_work_dtbt_58","text":"沈季長進言","sortOrder":18},
  {"id":"s_work_dtbt_58_19","chapterId":"ch_work_dtbt_58","text":"沈季長元豐中為崇政殿說書，考開封進士，既罷，入見，神宗曰：「論不以智治國，誰為此者？」對曰：「李定所為。」上曰：「聞定意譏朕。」季長曰：「定事陛下有年，頃者御史言定乃人倫所棄，陛下力排羣議，而定始得為人如初，繼又擢用不次，定雖懷利，尚當知恩，臣以此敢謂無譏陛下意。詩序曰：『言之者無罪，聞之者足以戒。』書曰：『小人怨汝詈汝，則皇自敬德。』陛下自視豈任智者，不知何自嫌疑，乃信此為譏也？」上曰：「卿言甚善，朕今已釋然矣，卿長者，乃喜為人辯謗。」對曰：「臣非為人辯謗，乃為陛下辯譖耳。」他日，上語及前代君臣，因曰：「漢武帝學神仙不死之術，卿曉其意否？此乃貪生以固位耳，故其晚年舉措謬戾，禍貽骨肉，幾覆宗社。且人主固位，其禍猶爾，則為人臣而固位者，其患亦何所不至，故朕每患天下之士能輕爵祿者少。」季長曰：「士而輕爵祿，為士言之，則可，為國言之，則非福也。人主有尊德樂道之志，士皆以不得爵祿為恥，寧有輕爵祿者哉？至於言違諫怫，士有去志，故以爵祿為輕。」上曰：「誠如卿言。」按季長雖嘗至修起居註，其後但終於庶僚，史不立傳。王和甫銘其墓，載此兩論，予在史院時未之見也。其子銖為侍從，恨不獲附見之，故表出於是。","sortOrder":19},
  {"id":"s_work_dtbt_58_20","chapterId":"ch_work_dtbt_58","text":"繁遏渠","sortOrder":20},
  {"id":"s_work_dtbt_58_21","chapterId":"ch_work_dtbt_58","text":"國語魯叔孫穆子曰：「金奏肆夏：繁、遏、渠。天子所以饗元侯也。」韋昭註曰：「繁、遏、渠，肆夏之三也，禮有九夏，皆篇名。」昭雖曉其義，而不詳釋。按周禮春官：「鐘師掌金奏，以鐘鼓奏九夏。」鄭氏註引呂叔玉雲：「肆夏、繁遏、渠，皆周頌也。肆夏，時邁也。繁遏，執競也。渠，思文也。」又曰：「繁，多也。遏，止也。言福祿止於周之多也。故執競曰：『降福穰穰，降福簡簡。』渠，大也。言以後稷配天，王道之大也。故思文曰：『思文後稷，克配彼天。』」予謂此說亦近於鑿。","sortOrder":21},
  {"id":"s_work_dtbt_58_22","chapterId":"ch_work_dtbt_58","text":"替戾岡","sortOrder":22},
  {"id":"s_work_dtbt_58_23","chapterId":"ch_work_dtbt_58","text":"坡公遊鶴林、招隱，有岡字韻詩，凡作七首，最後雲：「背城借一吾何敢，切勿樽前替戾岡。」小兒問三字所出，按晉書佛圖澄傳，澄能聽鈴音以知吉凶，往投石勒。及劉曜攻洛陽，勒將救之，其羣下鹹諫，以為不可。勒以訪澄，澄曰：「相輪鈴音雲：『秀支替戾岡，僕穀劬禿當。』此羯語也。秀支，軍也。替戾岡，出也。僕穀，劉曜胡位也。劬禿當，捉也。此言軍出捉得曜也。」勒遂擒曜。坡公正用此雲。","sortOrder":23},
  {"id":"s_work_dtbt_58_24","chapterId":"ch_work_dtbt_58","text":"文潞公平章重事","sortOrder":24},
  {"id":"s_work_dtbt_58_25","chapterId":"ch_work_dtbt_58","text":"文潞公元豐六年以太師致仕，時七十八歲矣。後二年，哲宗即位，太皇太後垂簾同聽政，用司馬公為門下侍郎，公奏乞召潞公置之百寮之首，以鎮安四海，後遣中使梁惟簡宣諭曰：「彥博名位已重，又得人心，今天子幼沖，恐其有震主之威。且於輔相中無處安排，又已致仕，難為復起。」公當時以新入，不敢復言。元祐元年三月，公拜左僕射，乃再上奏曰：「書曰：『人惟求舊。』蓋以其歷年之多也。彥博沉敏有謀略，知國家治體，能斷大事，自仁宗以來，出將入相，功效顯著，天下所共知，年逾八十，精力尚強。臣初曾奏陳，尋蒙宣諭。切惟彥博一書生爾，年逼桑榆，富貴已極，夫復何求？非有兵權死黨可畏懼也。假使為相，一旦欲罷之，止煩召一學士，授以詞頭，白麻既出，則一匹夫爾，何難製之？有震主之威，防慮大過。若依今官製用之為相，以太師兼侍中，行左僕射，有何不可？倘不欲以劇務煩老臣，則凡常程文書，只委右僕射以下簽書發遣，惟事有難決者，方就彥博咨稟。自古致仕復起，蓋非一人，彥博今年八十一，不過得其數年之力，願急用之，臣但以門下侍郎助彥博，恐亦時有小補。今不以彥博首相，而以臣處之，是猶捨騏驥而策駑駘也，切為朝廷惜之。若以除臣左僕射，難為無故以他人易之，則臣欲露表舉其自代。」奏入，不許。給事中范純仁亦勸乞召致，留為師臣。未幾，右僕射韓縝求去，後始賜司馬公密詔，欲除彥博兼侍中，行右僕射事，其合行恩禮，令相度條具。公以名體未正，不敢居其上，乞以行左僕射，自守右僕射。詔曰：「使彥博居卿上，非予所以待卿之意，卿更思之。」公執奏言：「臣為京官時，彥博已為宰相，今使彥博列位在下，非所以正大倫也。」於是召赴闕。既而御史中丞劉摯、左正言朱光庭、右正言王覿俱上言：「彥博春秋高，不可為三省長官。」司馬公又言：「若令以正太師平章軍國重事，亦足以尊老成矣。」四月，遂下製如公言，詔一月兩赴經筵，六日一入朝，因至都堂與執政商量事，朝廷有大政令，即與輔臣共議。潞公此命，可謂鄭重費力，蓋本不出於主意也。然居位越五年，屢謝病，乃得歸，竟坐此貽紹聖之貶。","sortOrder":25},
  {"id":"s_work_dtbt_58_26","chapterId":"ch_work_dtbt_58","text":"考課之法廢","sortOrder":26},
  {"id":"s_work_dtbt_58_27","chapterId":"ch_work_dtbt_58","text":"唐製，尚書考功掌內外文武官吏之考課，凡應考之官，家具錄當年功過行能，本司及本州長官對衆讀議其優劣，定為九等考第，然後送省。別敕定京官位望高者二人，一校京官考，一校外官考，又定給事中、中書舍人各一人，一監京官考，一監外官考，郎中判京官考，員外郎判外官考。凡考課之法，有四善、二十七最。一最以上有四善，為上上。有三善，或無最而有四善，為上中。有二善，或無最而有三善，為上下。其末至於居官諂詐、貪濁有狀，為下下。外州則司錄、錄事參軍主之，各據之以為黜陟。國朝此法尚存，慶曆、皇祐中，黃亞夫庶佐一府、三州幕，其集所載考詞十四篇，黃司理者曰：「治犴獄，歲再周矣，論其罪棄市者五十四，流若徒三百十有四，杖百八十六，皆得其情，無有寃隱不伸，非才也其孰能？其考可書中。」舞陽尉者曰：「舞陽大約地廣，它盜往往囊槖於其間，居一歲，為竊與強者凡十一，前件官捕得之，其亡者一而已矣，非才焉固不能，可書中。」法曹劉昭遠者曰：「法者，禮之防也。其用之以當人情為得，刻者為之，則拘而少恩。前件官以通經舉進士，始掾於此，若老於為法者，每抱具獄，必傅之經義然後處，故無一不當其情，其考可書中。」它皆類此。不知其製廢於何時。今但付之士按吏據定式書於印紙，比者又令郡守定縣令臧否高下，人亦不知所從出。若使稍復舊貫，似為得宜，雖未必人人盡公得實，然思過半矣。","sortOrder":27},
  {"id":"s_work_dtbt_58_28","chapterId":"ch_work_dtbt_58","text":"小官受俸","sortOrder":28},
  {"id":"s_work_dtbt_58_29","chapterId":"ch_work_dtbt_58","text":"沈存中筆談書國初時州縣之小官俸入至薄，故有「五貫九百六十俸，省錢且作足錢用」之語。黃亞夫皇祐間自序其所為伐檀集雲：「歷佐一府、三州，皆為從事，逾十年，郡之政，巨細無不與，大抵止於簿書獄訟而已，其心之所存，可以效於君、補於國、資於民者，曾未有一事可以自見。然月廩於官，粟麥常兩斛，錢常七千，問其所為，乃一常人皆可不勉而能，茲素餐昭昭矣，遂以『伐檀』名其集，且識其愧。」予謂今之仕宦，雖主簿、尉，蓋或七八倍於此，然常有不足之嘆。若兩斛、七千，祗可祿一書吏小校耳！豈非風俗日趨於浮靡，人用日以汰，物價日以滋，致於不能贍足乎？亞夫之立志如此，真可重也。山穀先生乃其子雲。","sortOrder":29},
  {"id":"s_work_dtbt_59_1","chapterId":"ch_work_dtbt_59","text":"卷第八(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_59_2","chapterId":"ch_work_dtbt_59","text":"庫路真","sortOrder":2},
  {"id":"s_work_dtbt_59_3","chapterId":"ch_work_dtbt_59","text":"新唐書地理志：「襄州，土貢漆器庫路真二品十乘花文五乘。」庫路真者，漆器名也，然其義不可曉。元豐九域志雲「貢漆器二十事」是已。於頔傳，頔為襄陽節度，襄有髹器，天下以為法。至頔驕蹇，故方帥不法者，稱為「襄樣節度」。舊唐書職官志，武德七年，改秦王、齊王下領三衞及庫真、驅咥真，並為統軍。疑是周隋間西邊方言也。記白樂天集曾有一說，而未之見。","sortOrder":3},
  {"id":"s_work_dtbt_59_4","chapterId":"ch_work_dtbt_59","text":"得意失意詩","sortOrder":4},
  {"id":"s_work_dtbt_59_5","chapterId":"ch_work_dtbt_59","text":"舊傳有詩四句誇世人得意者雲：「久旱逢甘雨，他鄉見故知。洞房花燭夜，金榜掛名時。」好事者續以失意四句曰：「寡婦攜兒泣，將軍被敵擒。失恩宮女面，下第舉人心。」此二詩，可喜可悲之狀極矣。","sortOrder":5},
  {"id":"s_work_dtbt_59_6","chapterId":"ch_work_dtbt_59","text":"狄監盧尹","sortOrder":6},
  {"id":"s_work_dtbt_59_7","chapterId":"ch_work_dtbt_59","text":"文潞公留守西京，年七十七，為耆英會，凡十有二人。時富韓公年七十九，最長，至於太中大夫張問，年七十，唯司馬公方六十四歲，用狄監、盧尹故事，亦預於會。或問狄、盧之說，乃見唐白樂天集，今所謂九老圖者。懷州司馬胡杲年八十九，衞尉卿吉皎年八十六，龍武長史鄭據八十四，慈州刺史劉嘉、侍御史盧貞皆八十二，其年皆在元豐諸公之上。永州刺史張渾、刑部尚書白居易皆七十四。時會昌五年。白公序雲：「六賢皆多年壽，予亦次焉。祕書監狄兼謩，河南尹盧貞，以年未七十，雖與會而不及列。」故溫公紀韓公至張昌言，而自不書。今士大夫皆熟知此事，姑志狄、盧二賢，以示兒輩。但唐兩盧貞，而又同會，疑文字或誤雲。","sortOrder":7},
  {"id":"s_work_dtbt_59_8","chapterId":"ch_work_dtbt_59","text":"項韓兵書","sortOrder":8},
  {"id":"s_work_dtbt_59_9","chapterId":"ch_work_dtbt_59","text":"漢成帝時，任宏論次兵書為四種，其權謀中有韓信三篇，形勢中有項王一篇，前後藝文志載之，且雲：「漢興，張良、韓信序次兵法，凡百八十二家，刪取要用，定著三十五家。諸呂用事而盜取之。」項、韓雖不得其死，而遺書可傳於後者，漢世不廢，今不復可見矣。","sortOrder":9},
  {"id":"s_work_dtbt_59_10","chapterId":"ch_work_dtbt_59","text":"承天塔記","sortOrder":10},
  {"id":"s_work_dtbt_59_11","chapterId":"ch_work_dtbt_59","text":"黃魯直初謫戎、涪，既得歸，而湖北轉運判官陳舉，以時相趙清憲與之有小怨，訐其所作荊南承天塔記，以為幸災，遂除名羈管宜州，竟卒於彼。今豫章集不載其文，蓋謂因之兆禍，故不忍著錄。其曾孫續編別集，始得見之。大略雲：「餘得罪竄黔中，道出江陵，寓承天禪院，住持僧智珠方徹舊浮圖於地，而屬曰：『餘成功之後，願乞文記之。』後六年，蒙恩東歸，則七級巋然已立，於是作記。」其後雲：「儒者嘗論一佛寺之費，蓋中民萬家之產，實生民穀帛之蠧，雖餘亦謂之然。然自省事以來，觀天下財力屈竭之端，國家無大軍旅勤民丁賦之政，則蝗旱水溢或疾疫連數十州，此蓋生人之共業，盈虛有數，非人力所能勝者邪！」其語不過如是，初無幸災風刺之意，乃至於遠斥以死，寃哉！","sortOrder":11},
  {"id":"s_work_dtbt_59_12","chapterId":"ch_work_dtbt_59","text":"穆護歌","sortOrder":12},
  {"id":"s_work_dtbt_59_13","chapterId":"ch_work_dtbt_59","text":"郭茂倩編次樂府詩穆護歌一篇，引歷代歌辭曰：「曲犯角。」其語曰：「玉管朝朝弄，清歌日日新。折花當驛路，寄與隴頭人。」黃魯直題牧護歌後雲：「予嘗問人此歌，皆莫能說牧護之義。昔在巴、僰間六年，問諸道人，亦莫能說。他日，船宿雲安野次，會其人祭神罷而飲福，坐客更起舞，而歌木瓠。其詞有雲：『聽說商人木瓠，四海五湖曾去。』中有數十句，皆敍賈人之樂，末雲：『一言為報諸人，倒盡百瓶歸去。』繼有數人起舞，皆陳述己事，而始末略同。問其所以為木瓠，蓋刳曲木狀如瓠，擊之以為歌舞之節耳。乃悟穆護蓋木瓠也。」據此說，則茂倩所序，為不知本原雲。且四句律詩，如何便差排為犯角曲，殊無意義。","sortOrder":13},
  {"id":"s_work_dtbt_59_14","chapterId":"ch_work_dtbt_59","text":"省試取人額","sortOrder":14},
  {"id":"s_work_dtbt_59_15","chapterId":"ch_work_dtbt_59","text":"累舉省試，鎖院至開院，限以一月。如未訖事，則申展亦不過十日，所奏名以十四人取一為定數，不知此製起於何年。黃魯直以元祐三年為貢院參詳官，有書帖一紙雲：「正月乙丑鎖太學，試禮部進士四千七百三十二人。三月戊申具奏進士五百人。」乃是在院四十四日，而九人半取一人，視今日為不侔也。此帖載於別集。","sortOrder":15},
  {"id":"s_work_dtbt_59_16","chapterId":"ch_work_dtbt_59","text":"通印子魚","sortOrder":16},
  {"id":"s_work_dtbt_59_17","chapterId":"ch_work_dtbt_59","text":"魚通印之語，本出於王荊公送張兵部知福州詩「長魚俎上通三印」之句。蓋以福州瀕海多魚，其大如此，初不指言為子魚也。東坡始以「通印子魚」對「披黃雀」，乃借「子」字與「黃」字為假對耳。山穀所雲「子魚通印蠔破山」，蓋承而用之。陳正敏遯齋閒覽雲：「其地有通應廟，廟前港中子魚最佳。王初寮詩『通應子魚鹽透白』，正採其說。」郡人黃處權雲：「興化子魚，去城五十里地名迎仙者為上，所產之處，土人謂之子魚潭而已，初無通應港之名。」有大神祠，賜額曰「顯應」，乃遯齋所指之廟者，亦非「通應」也。潭傍又有小祠一間，庳陋之甚，農家以祀田神，好事欲實遯齋之說，遂粉刷一扁，妄標曰「通應廟」，側題五小字曰「元祐某年立」，此尤可笑。且用神廟封額以名土物，它處未嘗有也。","sortOrder":17},
  {"id":"s_work_dtbt_59_18","chapterId":"ch_work_dtbt_59","text":"壽亭侯印","sortOrder":18},
  {"id":"s_work_dtbt_59_19","chapterId":"ch_work_dtbt_59","text":"荊門玉泉關將軍廟中，有壽亭侯印一鈕，其上大環，徑四寸，下連四環，皆繫於印上。相傳雲：紹興中，洞庭漁者得之，入於潭府，以為關雲長封漢壽亭侯，此其故物也，故以歸之廟中。南雄守黃兌見臨川興聖院僧惠通印圖形，為作記。而復州寶相院又以建炎二年，因伐木，於三門大樹下土中深四尺餘，得此印，其環幷背俱有文雲：「漢建安二十年壽亭侯印。」今留於左藏庫。邵州守黃沃叔啟慶元二年復買一鈕於郡人張氏，其文正同，只欠五繫環耳。予以謂皆非真漢物，且漢壽乃亭名，既以封雲長，不應去漢字，又其大比它漢印幾倍之。聞嘉興王仲言亦有其一。侯印一而已，安得有四？雲長以四年受封，當即刻印，不應在二十年，尤非也。是特後人為之以奉廟祭，其數必多。今流落人間者，尚如此也。予為黃叔啟作辨跋一篇，見贅稿。","sortOrder":19},
  {"id":"s_work_dtbt_59_20","chapterId":"ch_work_dtbt_59","text":"茸附治疽漏","sortOrder":20},
  {"id":"s_work_dtbt_59_21","chapterId":"ch_work_dtbt_59","text":"時康祖病心痔二十年，用聖惠方治腰痛者鹿茸、附子服之，月餘而愈，夷堅己志書其事。予每與醫言，輒雲：「癰疽之發，蘊熱之極也，烏有翻使熱藥之理？」福州醫郭晉卿雲：「脈陷則害漏，陷者冷也，若氣血溫煖，則漏自止，正用得茸、附。」按內經素問生氣通天論曰：「陷脈為痿，留連肉腠。」註雲：「陷脈謂寒氣陷缺其脈也，積寒留舍，經血稽凝，久瘀內攻，結於肉理，故發為瘍瘻，肉腠相連。」此說可謂明白，故復記於此，庶幾或有助於瘍醫雲。","sortOrder":21},
  {"id":"s_work_dtbt_59_22","chapterId":"ch_work_dtbt_59","text":"莆田荔枝","sortOrder":22},
  {"id":"s_work_dtbt_59_23","chapterId":"ch_work_dtbt_59","text":"莆田荔枝，名品皆出天成，雖以其核種之，終與其本不相類。宋香之後無宋香，所存者孫枝爾。陳紫之後無陳紫，過牆則為小陳紫矣。筆談謂焦核荔子，土人能為之，取本木，去其大根，火燔令焦，復植於土，以石壓之，令勿生旁根，其核自小。里人謂不然，此果形狀，變態百出，不可以理求，或似龍牙，或類鳳爪，釵頭紅之可簪，綠珠子之旁綴，是豈人力所能加哉？初，方氏有樹，結實數千顆，欲重其名，以二百顆送蔡忠惠公，紿以常歲所產止此。公為目之曰「方家紅」，著之於譜，印證其妄。自後華實雖極繁茂，逮至成熟，所存者未嘗越二百，遂成語讖。此段已載遯齋閒覽中，郡士黃處權復志其詳如此。","sortOrder":23},
  {"id":"s_work_dtbt_59_24","chapterId":"ch_work_dtbt_59","text":"雙陸不勝","sortOrder":24},
  {"id":"s_work_dtbt_59_25","chapterId":"ch_work_dtbt_59","text":"新唐書狄仁傑傳，武後召問夢雙陸不勝，何也？仁傑與王方慶俱在，二人同辭對曰：「雙陸不勝，無子也。天其意者以儆陛下乎？」於是召還廬陵王。舊史不載，資治通鑑但書鸚鵡折翼一事。而考異雲：「雙陸之說，世傳狄梁公傳有之，以為李邕所作，而其詞多鄙誕，疑非本書，故黜不取。」藝文志有李繁大唐說纂四卷，今罕得其書，予家有之，凡所紀事，率不過數十字，極為簡要，新史大抵采用之。其忠節一門曰：「武後問石泉公王方慶曰：『朕夜夢雙陸不勝，何也？』曰：『蓋謂宮中無子，意者恐有神靈儆夫陛下。』因陳人心在唐之意，後大悟，召廬陵王，復其儲位，俾石泉公為宮相以輔翊之。」然則新史兼采二李之說，而為狄為王莫能辨也。通鑑去之，似為可惜。","sortOrder":25},
  {"id":"s_work_dtbt_59_26","chapterId":"ch_work_dtbt_59","text":"華元入楚師","sortOrder":26},
  {"id":"s_work_dtbt_59_27","chapterId":"ch_work_dtbt_59","text":"左傳，楚莊王圍宋，宋華元夜入楚師，登子反之牀，起之曰：「寡君使元以病告。」子反懼，與之盟，而退三十里。杜註曰：「兵法，因其鄉人而用之，必先知其守將左右謁者、門者之姓名，因而利道之。華元蓋用此術，得以自通。」予按前三年晉、楚邲之戰，隨武子稱楚之善曰：「軍行，右轅，左追蓐，前茅慮無，中權後勁，軍政不戒而備。」大抵言其備豫之固。今使敵人能入上將之幕而登其牀，則刺客奸人，何施不得？雖至於王所可也，豈所謂軍製乎？疑不然也。公羊傳雲：「楚使子反乘堙而闚宋城，宋華元亦乘堙而出見之。」其說比左氏為有理。","sortOrder":27},
  {"id":"s_work_dtbt_59_28","chapterId":"ch_work_dtbt_59","text":"公羊用叠語","sortOrder":28},
  {"id":"s_work_dtbt_59_29","chapterId":"ch_work_dtbt_59","text":"公羊傳書楚子圍宋，宋人及楚人平事，幾四百字。其稱「司馬子反」者八，又再曰「將去而歸爾」，「然後而歸爾」，「然後歸爾」，「臣請歸爾」，「吾亦從子而歸爾」。又三書「軍有七日之糧爾」，凡九用「爾」字，然不覺其煩。","sortOrder":29},
  {"id":"s_work_dtbt_59_30","chapterId":"ch_work_dtbt_59","text":"文書誤一字","sortOrder":30},
  {"id":"s_work_dtbt_59_31","chapterId":"ch_work_dtbt_59","text":"文書一字之誤，有絕係利害者，予親經其三焉，至今思之，猶為汗下。乾道二年冬，蒙恩召還，過三衢，郡守何德輔問奏對用幾劄，因出草稿示之，其一乞蠲減鄱陽歲貢誕節金千兩事，言此貢不知起於何時，或雲藝祖初下江南，郡庫適有金，守臣取以獻長春節，遂為故事。誤書「長春」為「萬春」，乃金主褒節名也。德輔讀之，指以相告，予悚然面發赤，亟改之。三年，以侍講講毛詩，作發題，引孔子於論語中說詩處雲：「不學詩，無以言。」誤書「言」為「立」，已寫進讀正本，經筵吏袁顯忠曰：「恐是言字。」予愧謝之。淳熙十三年在翰苑，作賜安南國曆日詔雲：「茲履夏正，載頒漢朔。」書「夏正」為「周正」，院吏以呈宰執，周益公見而摘其誤，吏還以告，蓋語順意同，一時不自覺也。","sortOrder":31},
  {"id":"s_work_dtbt_59_32","chapterId":"ch_work_dtbt_59","text":"歷代史本末","sortOrder":32},
  {"id":"s_work_dtbt_59_33","chapterId":"ch_work_dtbt_59","text":"古者世有史官，其著見於今，則自堯、舜二典。始，周之諸侯各有國史，孔子因魯史記而作春秋，左氏為之傳，鄭志、宋志、晉齊太史、南史氏之事皆見焉。更纂異同以為國語。漢司馬談自以其先周室之太史，有述作之意，傳其子遷，紬金匱石室之書，罔羅天下放失舊聞，述黃帝以來至於元狩，馳騁古今，上下數千載間，變編年之體為十二本紀、十表、八書、三十世家、七十列傳，凡百三十篇。而十篇有錄無書，元、成之間，褚先生補缺，作武帝紀、三王世家、龜策、日者列傳，張晏以為言辭鄙陋，今雜於書中。而藝文志有馮商續太史公七篇，則泯沒不見。司馬之書既出，後世雖有作者，不能少紊其規製。班彪、固父子，以為漢紹堯運建帝業，而六世史臣，追述功德，私作本紀，編於百王之末，廁於秦、項之列。故采纂前紀，綴輯舊聞，以述漢書，起於高祖，終於王莽之誅，大抵仍司馬氏，第更八書為十志，而無世家，凡百卷。固死，其書未能全，女弟昭續成之，是為前漢書。荀悅漢紀則續所論著者也。後漢之事，初命儒臣著述於東觀，謂之漢紀。其後有袁宏紀，張璠、薛瑩、謝承、華嶠、袁山松、劉義慶、謝沈皆有書。宋范曄刪采為十紀、八十列傳，是為後漢書，而張璠以下諸家盡廢，其志則劉昭所補也。三國雜史至多，有王沈魏書、元行沖魏典、魚豢典略、張勃吳錄、韋昭吳書、孫盛魏春秋、司馬彪九州春秋、丘悅三國典略、員半千三國春秋、虞溥江表傳，今唯以陳壽書為定，是為三國志。晉書則有王隱、虞預、謝靈運、臧榮緒、孫綽、幹寶諸家，唐太宗詔房喬、褚遂良等修定為百三十卷，以四論太宗所作，故總名之曰「御撰」，是為晉書，至今用之。南北兩朝各四代，而僭偽之國十數，其書尤多，如徐爰、孫嚴、王智深、顧野王、魏澹、張大素、李德林之正史，皆不傳。今之存者，沈約宋書、蕭子顯齊書、姚思廉梁陳書、魏收魏書、李百藥北齊書、令狐德棻周書、魏鄭公隋書。其它國則有和包漢趙紀、田融趙石記、范亨燕書、王景暉南燕錄、高閭燕志、劉昞涼書、裴景仁秦記、崔鴻十六國春秋、蕭方武敏之三十國春秋。李太師延壽父子悉取為南史八十卷，北史百卷。今沈約以下八史雖存，而李氏之書獨行，是為南北史。唐自高祖至於武宗，有實錄，後唐修為書，劉昫所上者是已，而猥雜無統。國朝慶曆中，復詔刊修，歷十七年而成，歐陽文忠公主紀、表、志，宋景文公主傳，今行於世。梁、唐、晉、漢、周謂之五代，國初監修國史薛居正提舉上之。其後歐陽芟為新書，故唐、五代史各有舊新之目。凡十七代，本末如此，稚兒數以為問，故詳記之。","sortOrder":33},
  {"id":"s_work_dtbt_59_34","chapterId":"ch_work_dtbt_59","text":"賢者一言解疑譖","sortOrder":34},
  {"id":"s_work_dtbt_59_35","chapterId":"ch_work_dtbt_59","text":"賢者以單詞片言，為人釋謗解患，卓卓可書者，予得兩事焉。秦氏當國時，先忠宣公、鄭亨仲資政、胡明仲侍郎、朱新仲舍人，皆在謫籍，分置廣東。方務德為經略帥，待之盡禮。秦對一客言曰：「方滋在廣部，凡得罪於朝廷者，必加意護結，得非欲為異日地乎？」客曰：「非公相有雲，不敢輒言。方滋之為人，天性長者，凡於人唯以周旋為志，非獨於遷客然也。」秦悟曰：「方務德却是個周旋底人。」其疑遂釋。當時使一憸巧者承其問，微肆一語，方必得罪，而諸公不得安跡矣。言之者可謂大君子，當求之古人中。嚴陵王大卞赴曲江守，過南安，謁張先生子韶，從容言：「大卞頃在檢院，以羅彥濟中丞章去國，其後彥濟自吏書出守嚴，遂遷避於蘭溪。彥濟到郡，遺書相邀曰：『與君有同年之契，何為爾？』不得已，復還。既見，密語雲：『前此臺評，乃朱新仲所作，託造物之意以相授，一時失於審思，至今為悔。』此事既往，今適守韶，而朱在彼，邂逅有弗愜，為之奈何？」張揣其必將修怨，即雲：「國先為君子為小人，皆在此舉。」王悚然曰：「謹受教。」至則降意彌縫，終二年，不見分毫形跡，蓋本自相善也。予曩侍張公坐，聞其言，故追紀之。","sortOrder":35},
  {"id":"s_work_dtbt_60_1","chapterId":"ch_work_dtbt_60","text":"卷第九(十六則)","sortOrder":1},
  {"id":"s_work_dtbt_60_2","chapterId":"ch_work_dtbt_60","text":"蔣魏公逸史","sortOrder":2},
  {"id":"s_work_dtbt_60_3","chapterId":"ch_work_dtbt_60","text":"蔣魏公逸史二十卷，穎叔所著也，多紀當時典章文物。雲舊有數百冊，兵火間盡失之，其曾孫芾始攟摭遺稿，而成此書，將以奏御，以其副上之太史，且板行之，傳之天下後世，既而不果。蔣公在熙寧、元祐、崇寧時，名為博聞強識，然閱其論述，頗有可議，恨不及丞相在日與之言。其一雲：「行、守、試，視其官品之高下，除者必帶本官，呂晦叔除守司空而不帶金紫光祿大夫者，此翰林之失也，既不帶官，不當著『守』字，故晦叔辨之，遂去『守』字，為正司空，議者謂超過特進、東宮三太、儀同矣。」予謂行、守、試必帶正官，固也。然自改官製以後，既為司空，自不應復帶階官。呂從金紫遷，只是超特進一級耳，東宮三太，何嘗以為宰相官？儀同又係使相也，呂亦無自辨之說。其二雲：「文潞公既為真太師矣，其罷也，乃加『守』字，潞公怏怏，諸公欲為去之，議者謂非典故，潞公之意，止欲以真太師致仕耳，諸公曰：『如此可乎？』曰：『不可，為真太師則在宰相之上。』竟不去『守』字，但出劄子，令權去之。」案潞公本以開府儀同三司守太師，河東節度使致仕，入為平章軍國重事，故繫銜只雲太師。及再致仕，悉還舊稱，當時有旨於製詞內除去「守」字，以嘗正任太師也。所謂劄子權去，恐或不然。其三雲：「舊製，執政雙轉，謂自工部侍郎轉刑部，刑部轉兵部，兵部轉工部尚書。惟宰相對轉，工部侍郎直轉工書，比執政三遷也。」予考舊製，執政轉官，與學士等。六侍郎則升兩曹，以工、禮、刑、戶、兵、吏為敍，至兵侍者，轉右丞，至吏侍者，轉左丞，皆轉工書，然後細遷。今言兵侍即轉工書，非也。宰相為侍郎者，升三曹，為尚書者，雙轉。如工侍轉戶侍，禮侍轉兵侍，若係戶侍，當改二丞，而宰相故事不立丞，故直遷尚書。今言工侍對轉工書，非也。其四雲：「楊察為翰林學士，一夜當三製，劉沆以參知政事，富弼以宣徽使，皆除宰相。宣徽在參政下，則富當在劉下，乃誤以居上，人皆不覺其失，惟學士李淑知之，揚言其事，遂貼麻改之。」予考國史，至和元年八月，劉沆以參知政事拜集賢相。二年六月，以忠武軍節度使知永興軍文彥博為昭文相，位第一，劉沆遷史館相，位第二，宣徽南院使判幷州富弼為集賢相，位第三，其夕三製是已。而劉先一年已在相位，初無失誤貼改之說。其五雲：「有四儀同：一曰開府儀同三司，二曰儀同三司，三曰左儀同三司，四曰右儀同三司。」案自漢鄧騭始為儀同三司，魏、晉以降，但有開府儀同三司之目，周、隋又增上字為一階，又改儀同三司為儀同大將軍，又有開府、上開府，儀同、上儀同，班列益卑，未嘗有左右之稱也。後進不當輒議前輩，因孫偃有問，書以示之。","sortOrder":3},
  {"id":"s_work_dtbt_60_4","chapterId":"ch_work_dtbt_60","text":"沈慶之曹景宗詩","sortOrder":4},
  {"id":"s_work_dtbt_60_5","chapterId":"ch_work_dtbt_60","text":"宋孝武嘗令羣臣賦詩，沈慶之手不知書，每恨眼不識字，上逼令作詩，慶之曰：「臣不知書，請口授師伯。」上即令顏師伯執筆，慶之口授之曰：「微生遇多幸，得逢時運昌。朽老筋力盡，徒步還南岡。辭榮此聖世，何愧張子房？」上甚悅，衆坐並稱其辭意之美。梁曹景宗破魏軍還，振旅凱入，武帝宴飲聯句，令沈約賦韻，景宗不得韻，意色不平，啟求賦詩，帝曰：「卿伎能甚多，人才英拔，何必止在一詩？」景宗已醉，求作不已。時韻已盡，唯餘競、病二字，景宗便操筆，其辭曰：「去時兒女悲，歸來笳鼓競。借問行路人，何如霍去病？」帝嘆不已，約及朝賢，驚嗟竟日。予謂沈、曹二公，未必能辦此，疑好事者為之，然正可為一佳對，曰：「辭榮聖世，何愧子房？借問路人，何如去病？」若全用後兩句，亦自的切。","sortOrder":5},
  {"id":"s_work_dtbt_60_6","chapterId":"ch_work_dtbt_60","text":"藍尾酒","sortOrder":6},
  {"id":"s_work_dtbt_60_7","chapterId":"ch_work_dtbt_60","text":"白樂天元日對酒詩雲：「三杯藍尾酒，一楪膠牙餳。」又雲：「老過占他藍尾酒，病餘收得到頭身。」「歲盞後推藍尾酒，春盤先勸膠牙餳。」荊楚歲時記雲：「膠牙者，取其堅固如膠也。」而藍尾之義，殊不可曉。河東記載申屠澄與路傍茅舍中老父、嫗及處女環火而坐，嫗自外挈酒壺至曰：「以君冒寒，且進一杯。」澄因揖，遜曰：「始自主人翁，即巡澄，當婪尾。」蓋以藍為婪，當婪尾者，謂最在後飲也。葉少蘊石林燕語雲：「唐人言藍尾多不同，藍字多作啉，出於侯白酒律，謂酒巡匝，末坐者連飲三杯，為藍尾，蓋末坐遠，酒行到常遲，故連飲以慰之，以啉為貪婪之意。或謂啉為燷，如鐵入火，貴其出色，此尤無稽。則唐人自不能曉此義。」葉之說如此。予謂不然，白公三杯之句，只為酒之巡數耳，安有連飲者哉？侯白滑稽之語，見於啟顏錄。唐藝文志，白有啟顏錄十卷、雜語五卷，不聞有酒律之書也。蘇鶚演義亦引其說。","sortOrder":7},
  {"id":"s_work_dtbt_60_8","chapterId":"ch_work_dtbt_60","text":"歐陽公辭官","sortOrder":8},
  {"id":"s_work_dtbt_60_9","chapterId":"ch_work_dtbt_60","text":"歐陽公自亳州除兵部尚書知青州，辭免至四，雲：「恩典超優，遷轉頗數。臣近自去春由吏部侍郎轉左丞，未逾兩月，又超轉三資，除刑部尚書。今纔逾歲，又超轉兩資。尚書六曹，一歲之間，超轉其五。」累降詔不從其請。此是熙寧元年未改官製時，今人多不能曉。蓋昔者左右丞在尚書下，所謂左丞超三資除刑書者，謂歷工、禮乃至刑也。下雲又超兩資者，謂歷戶部乃至兵也。其上唯有吏部，故言尚書六曹，超轉其五雲。","sortOrder":9},
  {"id":"s_work_dtbt_60_10","chapterId":"ch_work_dtbt_60","text":"南北語音不同","sortOrder":10},
  {"id":"s_work_dtbt_60_11","chapterId":"ch_work_dtbt_60","text":"南北語音之異，至於不能相通，故器物花木之屬，雖人所常用，固有不識者。如毛、鄭釋詩，以梅為枏，竹為王芻，蔞為翹翹之草是矣。顏師古註漢書亦然。淮南王安諫武帝伐越書曰：「輿轎而隃領。」服虔曰：「轎音橋，謂隘道輿車也。」臣瓚曰：「今竹輿車也，江表作竹輿以行。」項昭曰：「陵絕水曰轎，音旗廟反。」師古曰：「服音、瓚說是也，項氏謬矣。此直言以轎過領耳，何雲陵絕水乎？旗廟之音，無所依據。」又武帝紀：「戈船將軍。」張晏曰：「越人於水中負人船，又有蛟龍之害，故置戈於船下，因以為名。」瓚曰：「伍子胥書有戈船，以載幹戈，因謂之戈船也。」師古曰：「以樓船之例言之，則非為載幹戈也。此蓋船下安戈戟以禦蛟鼉水蟲之害。張說近之。」二說皆為三劉所破，雲：「今南方竹輿，正作旗廟音，項亦未為全非。顏乃西北人，隨其方言，遂音橋。」又雲：「船下安戈戟，既難厝置，又不可以行。且今造舟船甚多，未嘗有置戈者，顏北人，不知行船。瓚說是也。」予謂項音轎字是也，而雲陵絕水則謬，故劉公以為未可全非。張晏雲「越人於水中負船」，尤可笑。","sortOrder":11},
  {"id":"s_work_dtbt_60_12","chapterId":"ch_work_dtbt_60","text":"南舟北帳","sortOrder":12},
  {"id":"s_work_dtbt_60_13","chapterId":"ch_work_dtbt_60","text":"頃在豫章，遇一遼州僧於上藍，與之閒談，曰：「南人不信北方有千人之帳，北人不信南人有萬斛之舟，蓋土俗然也。」法苑珠林雲：「山中人不信有魚大如木，海上人不信有木大如魚。胡人見錦，不信有蟲食樹吐絲所成。吳人身在江南，不信有千人氊帳，及來河北，不信有二萬碩船。」遼僧之談合於此。","sortOrder":13},
  {"id":"s_work_dtbt_60_14","chapterId":"ch_work_dtbt_60","text":"魏冉罪大","sortOrder":14},
  {"id":"s_work_dtbt_60_15","chapterId":"ch_work_dtbt_60","text":"自漢以來，議者謂秦之亡，由商鞅、李斯。鞅更變法令，使民不見德，斯焚燒詩書，欲人不知古，其事固然。予觀秦所以得罪於天下後世，皆自挾詐失信故耳。其始也，以商於六百里啖楚絕齊，繼約楚懷王入武關，辱為藩臣，竟留之至死。及其喪歸，楚人皆憐之，如悲親戚。諸侯由是不直秦，未及百年，「三戶亡秦」之語遂驗。而為此謀者，張儀、魏冉也。儀之惡不待言，而冉之計頗隱，故不為士君子所誅。當秦武王薨，諸弟爭立，唯冉力能立昭王。冉者，昭王母宣太後之弟也。昭王少，太後自治事，任冉為政，威震秦國，才六年而詐留楚王，又怒其立太子，復取十六城。是時，王不過十餘歲，為此者必冉也。後冉為范雎所間而廢逐。司馬公以為冉援立昭王，除其災害，使諸侯稽首而事秦，秦益強大者，冉之功也。蓋公不細考之雲。又嘗請趙王會澠池，處心積慮，亦與詐楚同，賴藺相如折之，是以無所成，不然，與楚等耳！冉區區匹夫之見，徒能為秦一時之功，而貽秦不義不信之名萬世不滅者，冉之罪誠大矣！","sortOrder":15},
  {"id":"s_work_dtbt_60_16","chapterId":"ch_work_dtbt_60","text":"辯秦少遊義倡","sortOrder":16},
  {"id":"s_work_dtbt_60_17","chapterId":"ch_work_dtbt_60","text":"夷堅己志載潭州義倡事，謂秦少遊南遷過潭，與之往來，後倡竟為秦死，常州教授鍾將之得其說於李結次山，為作傳。予反復思之，定無此事，當時失於審訂，然悔之不及矣。秦將赴杭倅時，有妾邊朝華，既而以妨其學道，割愛去之，未幾罹黨禍，豈復眷戀一倡女哉？予記國史所書溫益知潭州，當紹聖中，逐臣在其巡內，若范忠宣、劉仲馮、韓川原伯、呂希純子進、呂陶元鈞，皆為所侵困。鄒公南遷過潭，暮投宿村寺，益即時遣州都監將數卒夜出城，逼使登舟，竟凌風絕江去，幾於覆舟。以是觀之，豈肯容少遊款昵累日？此不待辯而明，己志之失著矣！","sortOrder":17},
  {"id":"s_work_dtbt_60_18","chapterId":"ch_work_dtbt_60","text":"姓源韻譜","sortOrder":18},
  {"id":"s_work_dtbt_60_19","chapterId":"ch_work_dtbt_60","text":"姓氏之書，大抵多謬誤。如唐貞觀氏族志，今已亡其本。元和姓纂，誕妄最多。國朝所修姓源韻譜，尤為可笑。姑以洪氏一項考之，雲：「五代時有洪昌、洪杲，皆為參知政事。」予按二人乃五代南漢僭主劉龑之子，及晟嗣位，用為知政事，其兄弟本連「弘」字，以本朝國諱，故五代史追改之，元非姓洪氏也。此與洪慶善序丹陽弘氏雲：「有弘憲者，元和四年嘗跋輞川圖。」不知弘憲乃李吉甫之字耳。其誤正同，三筆已載此說。","sortOrder":19},
  {"id":"s_work_dtbt_60_20","chapterId":"ch_work_dtbt_60","text":"譽人過實","sortOrder":20},
  {"id":"s_work_dtbt_60_21","chapterId":"ch_work_dtbt_60","text":"稱譽人過實，最為作文章者之疵病，班孟堅尚不能免。如薦謝夷吾一書，予蓋論之於三筆矣。柳子厚復杜溫夫書雲：「三辱生書，書皆逾千言，抵吾必曰周、孔，周、孔安可當也？儗人必於其倫。生來柳州，見一刺史即周、孔之，今而去我，道連而謁於潮，又得二周、孔。去之京師，京師顯人，為文詞立聲名以千數，又宜得周、孔千百。何吾生胸中擾擾焉多周、孔哉？」是時，劉夢得在連，韓退之在潮，故子厚雲然。此文人人能誦，然今之好為諛者，固自若也。予表出之，以為子孫戒。張說賀魏元忠衣紫曰：「公居伊、周之任。」即為二張所讒，幾於隕命。此但形於語言之間耳。","sortOrder":21},
  {"id":"s_work_dtbt_60_22","chapterId":"ch_work_dtbt_60","text":"作文句法","sortOrder":22},
  {"id":"s_work_dtbt_60_23","chapterId":"ch_work_dtbt_60","text":"作文旨意句法，固有規仿前人，而音節鏘亮不嫌於同者。如前漢書贊雲：「豎牛奔仲叔孫卒，郈伯毀季昭公逐，費忌納女楚建走，宰嚭譖胥夫差喪，李園進妹春申斃，上官訴屈懷王執，趙高敗斯二世縊，伊戾坎盟宋痤死，江充造蠱太子殺，息夫作奸東平誅。」新唐書效之雲：「三宰嘯凶牝奪辰，林甫將蕃黃屋奔，鬼質敗謀興元蹙，崔、柳倒持李宗覆。」劉夢得因論儆舟篇雲：「越子膝行吳君忽，晉宣尸居魏臣怠，白公厲劍子西哂，李園養士春申易。」亦效班史語也。然其模範，本自荀子成相篇。","sortOrder":23},
  {"id":"s_work_dtbt_60_24","chapterId":"ch_work_dtbt_60","text":"書簡循習","sortOrder":24},
  {"id":"s_work_dtbt_60_25","chapterId":"ch_work_dtbt_60","text":"近代士人，相承於書尺語言，浸涉奇獧，雖有賢識，不能自改。如小簡問委，自言所在，必求新異之名。予守贛時，屬縣興國宰詒書雲：「瀲水有驅策，乞疏下。」瀲水者，彼邑一水耳，郡中未嘗知此，不足以為工，當言下邑、屬邑足矣。為縣丞者，無不采藍田壁記語雲，「負丞某處」，「哦松無補」，「涉筆承乏」，皆厭爛陳言。至稱丞曰「藍田」，殊為可笑。初赴州郡，與人書，必言「前政頹靡，倉庫匱乏，未知所以善後」，沿習一律。正使真如所陳，讀者亦不之信。予到當塗日，謝執政書雲：「郡雖小而事簡，庫錢倉粟，自可枝梧，得坐嘯道院，誠為至幸。」周益公答雲：「從前得外郡太守書，未有不以窘冗為詞，獨創見來緘如此。」蓋覺其與它異也。此兩者皆狃熟成俗，故紀述以戒子弟輩。","sortOrder":25},
  {"id":"s_work_dtbt_60_26","chapterId":"ch_work_dtbt_60","text":"健訟之誤","sortOrder":26},
  {"id":"s_work_dtbt_60_27","chapterId":"ch_work_dtbt_60","text":"破句讀書之誤，根著於人，殆不可復正。在易彖之下，先釋卦義，然後承以本名者凡八卦。蒙卦曰「蒙，山下有險，險而止，蒙」，以「止」字為句絕，乃及於「蒙」，始係以「蒙亨，以亨行」。訟卦曰「訟，上剛下險，險而健，訟」，以「健」字為句絕，乃及於「訟」，始係以「訟有孚」。豫卦「剛應而志行，順以動，豫」，隨卦「剛來而下柔，動而說，隨」，蠱卦「剛上而柔下，巽而止，蠱」，恆卦「巽而動，剛柔皆應，恆」，解卦「解，險以動，動而免乎險，解」，井卦「巽乎水而上水，井」，皆是卦名之上為句絕。而童蒙入學之初，其師點句，輒混於上，遂以「健訟」相連，此下「說隨」二字，尚為有說，若「止蒙」、「動豫」之類，將如之何？凡謂頑民好訟者，曰「嚚訟」，曰「終訟」，可也，黃魯直江西道院賦雲「細民險而健，以終訟為能。筠獨不嚚於訟」，是已。同人卦：「柔得中而應乎乾曰同人，同人曰，同人於野，亨。」據其文義，正與諸卦同，但多下一「曰」字，王弼以為「乾之所行，故特曰『同人曰』」，程伊川以為衍三字，恐不然也。","sortOrder":27},
  {"id":"s_work_dtbt_60_28","chapterId":"ch_work_dtbt_60","text":"用史語之失","sortOrder":28},
  {"id":"s_work_dtbt_60_29","chapterId":"ch_work_dtbt_60","text":"今之牽引史語者，亦未免有失。張釋之言便宜事，文帝曰：「卑之，毋甚高論，令今可行也。」遂言秦、漢之間事，帝稱善。顏師古雲：「令其議論依附時事。」予謂不欲使為甚高難行之論，故令少卑之爾。而今之語者，直以言議不足采為「無甚高論」。又文帝問上林令禽獸簿，不能對，虎圈嗇夫從旁代對，帝曰：「吏不當如此邪？」薛廣德諫元帝御樓船，曰：「宜從橋。」且有血汚車輪之訐。張猛曰：「乘船危，就橋安。」上曰：「曉人不當如是邪？」師古謂「諫爭之言，當如猛之詳婉也。」按兩帝之語皆是褒嘉之詞，猶雲「獨不當如是乎？」今乃指人引喻非理或直述其私曰「曉人不當如是」。又韓公送諸葛覺往隨州讀書詩雲：「鄴侯家多書，插架三萬軸。一一懸牙籤，新若手未觸。為人強記覽，過眼不再讀。偉哉羣聖文，磊落載其腹。」鄴侯蓋謂李繁，時為隨州刺史，藏書既多，且記性警敏，故籤軸嚴整如是。今人或指言雖名為收書而未嘗過目者，輒曰：「新若手未觸。」亦非也。","sortOrder":29},
  {"id":"s_work_dtbt_60_30","chapterId":"ch_work_dtbt_60","text":"文字書簡謹日","sortOrder":30},
  {"id":"s_work_dtbt_60_31","chapterId":"ch_work_dtbt_60","text":"作文字紀月日，當以實言，若拘拘然必以節序，則為牽強，乃似麻沙書坊桃源居士輩所跋耳。至於往還書問，不可不繫日，而性率者，一切不書。予有婿生子，遣報雲：「今日巳時得一子。」更不知為何日。或又失之好奇。外姻孫鼎臣，每致書，必題其後曰：「某節」，至雲「小暑前一日」、「驚蟄前兩日」之類。文惠公常笑雲：「看孫鼎臣書，須著置曆日於案上。」蓋自元正、人日、三元、上巳、中秋、端午、七夕、重九、除夕外，雖寒食、冬至，亦當謹識之，况於小小氣候？後生宜戒。","sortOrder":31},
  {"id":"s_work_dtbt_60_32","chapterId":"ch_work_dtbt_60","text":"更衣","sortOrder":32},
  {"id":"s_work_dtbt_60_33","chapterId":"ch_work_dtbt_60","text":"雅志堂後小室，名之曰「更衣」，以為姻賓憩息地。稚子數請所出，因錄班史語示之。灌夫傳：「坐乃起更衣。」顏註：「更，改也。凡久坐者皆起更衣，以其寒暖或變也。」「田延年起，至更衣。」顏註：「古者延賓必有更衣之處，」衞皇後傳：「帝起更衣，子夫侍，尚衣。」","sortOrder":33},
  {"id":"s_work_dtbt_61_1","chapterId":"ch_work_dtbt_61","text":"卷第十(十七則)","sortOrder":1},
  {"id":"s_work_dtbt_61_2","chapterId":"ch_work_dtbt_61","text":"過所","sortOrder":2},
  {"id":"s_work_dtbt_61_3","chapterId":"ch_work_dtbt_61","text":"刑統衞禁律雲：「不應度關而給過所，若冒名請過所而度者。」又雲：「以過所與人。」又關津疏議：「關謂判過所之處，津直度人，不判過所。」釋名曰：「過所，至關津以示之。」或曰：「傳，傳轉也，轉移所在，識以為信。」漢文帝十二年，「除關無用傳。」張晏曰：「傳，信也，若今過所也。」「兩行書繒帛，分持其一，出入關，合之乃得過，謂之傳也。」魏志，倉慈為敦煌太守，西域雜胡欲詣洛者，為封過所。廷尉决事曰：「廣平趙禮詣雒治病，門人賫過所詣洛陽，責禮冒名渡津，受一歲半刑。」徐鉉稽神錄：「道士張謹好符法，客遊華陰，得二奴，曰德兒、歸寶，謹願可憑信。張東行，凡書囊、符法、過所、衣服，皆付歸寶負之，將及關，二奴忽不見，所賫之物，皆失之矣。時秦隴用兵，關禁嚴急，客行無驗，皆見刑戮，既不敢東度，復還，主人乃見二兒，因擲過所還之。」然過所二字，讀者多不曉，蓋若今時公憑引據之類，故裒其事於此。","sortOrder":3},
  {"id":"s_work_dtbt_61_4","chapterId":"ch_work_dtbt_61","text":"露布","sortOrder":4},
  {"id":"s_work_dtbt_61_5","chapterId":"ch_work_dtbt_61","text":"用兵獲勝，則上其功狀於朝，謂之露布。今博學宏詞科以為一題，雖自魏、晉以來有之，然竟不知所出，唯劉勰文心雕龍雲：「露布者，蓋露板不封，布諸觀聽也。」唐莊宗為晉王時，擒滅劉守光，命掌書記王緘草露布，緘不知故事，書之於布，遣人曳之，為議者所笑。然亦有所從來，魏高祖南伐，長史韓顯宗與齊戍將力戰，斬其裨將。高祖曰：「卿何為不作露布？」對曰：「頃聞將軍王肅獲賊二三人，驢馬數匹，皆為露布，私每哂之。近雖得摧醜虜，擒斬不多，脫復高曳長縑，虛張功捷，尤而效之，其罪彌甚，臣所以斂毫卷帛，解上而已。」以是而言，則用絹高懸久矣。","sortOrder":5},
  {"id":"s_work_dtbt_61_6","chapterId":"ch_work_dtbt_61","text":"東坡題潭帖","sortOrder":6},
  {"id":"s_work_dtbt_61_7","chapterId":"ch_work_dtbt_61","text":"潭州石刻法帖十卷，蓋錢希白所鐫，最為善本。吾鄉程欽之待製，以元符三年帥桂林，東坡自儋耳移合浦，得觀其藏帖，每冊各題其末。第二卷雲：「唐太宗作詩至多，亦有徐、庾風氣，而世不傳，獨於初學記時時見之。」第四卷雲：「吳道子始見張僧繇畫，曰：『浪得名耳！』已而坐臥其下，三日不能去。庾征西初不服逸少，有家鷄野鶩之論，後乃以為伯英再生。今觀其書，乃不逮子敬遠甚，正可比羊欣耳。」第六卷雲：「『宰相安和，殷生無恙。』宰相當是簡文帝，殷生則淵源也邪？」第八卷雲：「希白作字，自有江左風味，故長沙法帖比淳化待詔所摹為勝，世俗不察，爭訪閣下本，誤矣。此逸少一卷，尤妙。庚辰七夕，合浦官舍借觀。」第九卷雲：「謝安問獻之：『君書何如尊公？』答曰：『故自不同。』安曰：『外人不爾。』曰：『人那得知！』」已上所書，今麻沙所刊大全集志林中或有之。案庾亮及弟翼俱為征西將軍，坡所引者翼也。坡又有詩曰：「暮年却得庾安西，自厭家鷄題六紙。」蓋指翼前所歷官雲。此帖今藏予家。","sortOrder":7},
  {"id":"s_work_dtbt_61_8","chapterId":"ch_work_dtbt_61","text":"山公啟事","sortOrder":8},
  {"id":"s_work_dtbt_61_9","chapterId":"ch_work_dtbt_61","text":"晉書山濤傳：「濤再居選職，十有餘年，每一官缺，輒啟擬數人，詔旨有所向，然後顯奏，隨帝意所欲為先。故帝之所用，或非舉首，衆情不察，以濤輕重任意。或譖之於帝，濤行之自若。一年之後，衆情乃寢。濤所奏甄拔人物，各為題目，時稱山公啟事。」此語今多引用，然不得其式，法帖中乃有之，雲：「侍中、尚書僕射、奉車都尉、新沓伯臣濤言，臣近啟崔諒、史曜、陳準可補吏部郎，詔書可爾。此三人皆衆所稱，諒尤質正少華，可以崇教，雖大化未可倉卒，風尚所勸，為益者多，臣以為宜先用諒。謹隨事以聞。」觀此一帖，可以概見。然所啟三人，後亦無聞，既雲皆衆所稱，當不碌碌也。舊潭帖為識者稱許，以為賢於他本，然於此奏「未可倉卒」之下，乃雲「風筆惻然」，全無意義。今所錄者，臨江本也。","sortOrder":9},
  {"id":"s_work_dtbt_61_10","chapterId":"ch_work_dtbt_61","text":"親王回庶官書","sortOrder":10},
  {"id":"s_work_dtbt_61_11","chapterId":"ch_work_dtbt_61","text":"隨筆中載親王與侍從往還禮數，又得錢丕行年雜紀雲：「昇王受恩命，丕是時為將作少監，亦投賀狀，王降回書簽子啟頭。繼為皇太子，三司判官並通榜子，詣內東門參賀。通入後，中貴出傳令旨傳語。及受冊寶訖，百官班賀，又赴東宮賀，宰相親王階下班定，太子降階，宰相前拜，致詞訖，又拜。太子皆答拜，亦致詞敍謝。」一時之儀如此。","sortOrder":11},
  {"id":"s_work_dtbt_61_12","chapterId":"ch_work_dtbt_61","text":"責降考試官","sortOrder":12},
  {"id":"s_work_dtbt_61_13","chapterId":"ch_work_dtbt_61","text":"天禧二年九月，敕差屯田員外郎判度支計院任布、著作郎直史館徐奭、太子中允直集賢院麻溫其，並充開封府發解官。十月，差兵部員外郎直集賢院楊侃、太子中允直集賢院丁度，並國子監發解官。十一月，解一百四人，解元郭稹。十六日，宣翰林學士錢惟演、盛度，樞密直學士王晦叔，龍圖閣待製李虛己、李行簡，覆考開封舉人，為落解舉人有訟不平者。及奏名，郭稹依舊，其餘覆落，並却考上人數甚多。十二月，發解官並降差遣，任布鄧州，徐奭洪州，楊侃江州，丁度齊州，並監稅。此事見於錢丕雜紀。用五侍從覆考解試，前後未之有也。","sortOrder":13},
  {"id":"s_work_dtbt_61_14","chapterId":"ch_work_dtbt_61","text":"青蓮居士","sortOrder":14},
  {"id":"s_work_dtbt_61_15","chapterId":"ch_work_dtbt_61","text":"李太白贈玉泉仙人掌茶詩序雲：「荊州玉泉寺近清溪諸山，往往有乳窟。其水邊處處有茗草羅生，枝葉如碧玉，唯玉泉真公常採而飲之。餘遊金陵，見宗僧中孚，示予茶數十片，其狀如手，名為『仙人掌茶』，蓋新出乎玉泉之山，曠古未覿，因持以見遺，兼贈詩，要予答之，遂有此作。後之高僧大隱，知仙人掌茶發乎中孚禪子及青蓮居士李白也。」太白之稱，但有「謫仙人」爾，「青蓮居士」，獨於此見之，文人未嘗引用，而仙人掌茶，今池州九華山中亦頗有之，其狀略如蕨拳也。","sortOrder":15},
  {"id":"s_work_dtbt_61_16","chapterId":"ch_work_dtbt_61","text":"閩俗詭祕殺人","sortOrder":16},
  {"id":"s_work_dtbt_61_17","chapterId":"ch_work_dtbt_61","text":"奸凶之民，恃富逞力，處心積慮，果於殺人。然揆之以法，蓋有敕律所不曾登載，善治惡者，當原情定罪，必致其誅可也。閩中習俗尤甚，每執縛其仇，窮肆殘虐。或以酒調鋸屑逼之使飲，欲其黏著肺腑，不能傳化，馴致痰渴之疾。或炒沙鎔蠟灌註耳中，令其聾聵。或以濕薦束體，布裹卵石痛加毆箠，而外無痕傷。或按擦肩背，使皮膚寬皺，乃施針刺入肩井，不可復出。或以小釣鈎藏於鰍魚之腹，強使吞之，攻鑽五臟，久而必死。凡此術者，類非一端，既痕腫不露於外，檢驗不得而見情犯，巨蠧功意兩惡而法所不言。顏度魯子為轉運使，嘗揭榜禁約。予守建寧，亦窮治一兩事，吳、楚間士大夫宦遊於彼者，不可不察也。","sortOrder":17},
  {"id":"s_work_dtbt_61_18","chapterId":"ch_work_dtbt_61","text":"富公遷官","sortOrder":18},
  {"id":"s_work_dtbt_61_19","chapterId":"ch_work_dtbt_61","text":"富韓公慶曆二年以右正言知製誥報聘契丹，還，除吏部郎中、樞密直學士，不受。尋除翰林學士，又不受。三年，除右諫議大夫、樞密副使，力辭。乃改資政殿學士，而諫議如初，公受之。又五月，復為副樞。蓋昔時除目纔下，即時命詞給告，及其改命，但不拜執政，而猶得所進官。用今日官製言之，是承議郎、(舊為正言。)中書舍人(舊知製誥。)而為太中大夫、(舊為諫議。)資政殿學士也。","sortOrder":19},
  {"id":"s_work_dtbt_61_20","chapterId":"ch_work_dtbt_61","text":"唐藩鎮行墨敕","sortOrder":20},
  {"id":"s_work_dtbt_61_21","chapterId":"ch_work_dtbt_61","text":"池州銅陵縣孚貺侯廟，有唐中和二年二月一碑，其詞雲：「敕宣、歙、池等州都團練、觀察使牒。當道先準詔旨，許行墨敕授管內諸州有功刺史、大將等，憲官具件如後：晉朝故晉陽太守兼揚州長史張寬牒。奉處分，當道先準詔旨，許行墨敕，獎勸功勳，雖幽顯不同，而褒升一致。神久標奇絕，早揖英風，靈跡屢彰，神逵不昧。夫寵贈之典，非列藩宜為，神功既昭，乃軍都顒請，是行權製，用副人心。謹議褒贈遊擊將軍宣州都督。」後雲：「使、檢校工部尚書兼御史大夫裴押。」邑人以為裴休，秋浦志亦然，予考之，非也。張魏公宣撫川、陝，便宜封爵諸神，實本諸此。","sortOrder":21},
  {"id":"s_work_dtbt_61_22","chapterId":"ch_work_dtbt_61","text":"吏部循資格","sortOrder":22},
  {"id":"s_work_dtbt_61_23","chapterId":"ch_work_dtbt_61","text":"唐開元十八年四月，以侍中裴光庭兼吏部尚書。先是，選司註官，惟視其人之能否，或不次超遷，或老於下位，有出身二十餘年不得祿者。又州縣亦無等級，或自大入小，或初近後遠，皆無定製。光庭始奏用循資格，各以罷官若幹選而集，官高者選少，卑者選多，無問能否，選滿則註，限年躡級，毋得逾越，非負譴者皆有升無降。其庸愚沉滯者皆喜，謂之「聖書」，而材俊之士，無不怨嘆，宋璟爭之，不能得。二十一年，光庭薨，博士孫琬議光庭用循資格，失勸獎之道，請謚曰「克」。是年六月製，自今選人有才業操行，委吏部臨時擢用。雖有此製，而有司以循資格便於己，猶踵行之。蓋今日吏部四選，乃其法也。予案元魏肅宗神龜二年，官員既少，應選者多，尚書李韶銓註不行，大致怨嗟。崔亮代之，奏為格製，不問士之賢愚，專以停解月日為斷，沉滯者皆稱其能。亮甥劉景安與書曰：「商、周以鄉塾貢士，兩漢由州郡薦材，魏、晉中正，雖未盡美，應什收六七。而朝廷貢材，止求其文，不取其理，察孝廉唯論章句，不及治道，立中正不考材行，空辨姓氏。舅屬當銓衡，宜須改張易調，反為停年格以限之，天下士子，誰復修厲名行哉？」洛陽令薛琡上書言：「黎元命繫長吏，若選曹惟取年勞，不簡能否，義均行雁，次若貫魚，執簿呼名，一人足矣，數人而用，何謂銓衡？乞令王公貴人薦賢以補郡縣。」詔公卿議之。其後甄琛等繼亮，利其便己，踵而行之。魏之選舉失人，自亮始也。至孝靜帝元象二年，以高澄攝吏部尚書，始改亮年勞之製，銓擢賢能，當是自此一變。光庭又祖亮故智雲。然後人罕有談亮、澄事者。","sortOrder":23},
  {"id":"s_work_dtbt_61_24","chapterId":"ch_work_dtbt_61","text":"五行納音","sortOrder":24},
  {"id":"s_work_dtbt_61_25","chapterId":"ch_work_dtbt_61","text":"六十甲子納音之說，術家多不能曉。原其所以得名，皆從五音所生，有條不紊，端如貫珠。蓋甲子為首，而五音始於宮，宮土生金，故甲子為金，而乙丑以陰從陽。商金生水，故丙子為水，而丁丑從之。角木生火，故戊子為火。徵火生土，故庚子為土。羽水生木，故壬子為木。而己丑、辛丑、癸丑各從之。至於甲寅，則納音起於商，商金生水，故甲寅為水。角木生火，故丙寅為火。徵火生土，故戊寅為土。羽水生木，故庚寅為木。宮土生金，故壬寅為金。而五卯各從之。至甲辰，則納音起於角，角木生火，故甲辰為火。徵火生土，故丙辰為土。羽水生木，故戊辰為木。宮土生金，故庚辰為金。商金生水，故壬辰為水。而五巳各從之。宮、商、角既然，惟徵、羽不得居首。於是甲午復如甲子，甲申如甲寅，甲戌如甲辰，而五未、五酉、五亥，亦各從其類。","sortOrder":25},
  {"id":"s_work_dtbt_61_26","chapterId":"ch_work_dtbt_61","text":"五行化真","sortOrder":26},
  {"id":"s_work_dtbt_61_27","chapterId":"ch_work_dtbt_61","text":"五行運化，如甲、己化真土之類，若推求其義，無從可得，蓋祗以五虎元所生命之。如「甲、己之年丙作首」，謂丙寅月建也，丙屬火，火生土，故甲、己化真土。「乙、庚之歲戊為頭」，謂戊寅月建也，戊屬土，土生金，故乙、庚化真金。「丙、辛寄向庚寅去」，庚屬金，金生水，故丙、辛化真水。「丁、壬壬位順行流」，壬屬水，水生木，故丁、壬化真木。「戊、癸但向甲寅求」，甲屬木，木生火，故戊、癸化真火。此二說皆得之莆田鄭景實。頃在館中，見魏幾道談五行納音，亦然。","sortOrder":27},
  {"id":"s_work_dtbt_61_28","chapterId":"ch_work_dtbt_61","text":"錢忠懿判語","sortOrder":28},
  {"id":"s_work_dtbt_61_29","chapterId":"ch_work_dtbt_61","text":"王順伯家有錢忠懿一判語，其狀雲：「臣贊寧，右臣伏奉宣旨撰文疏，今進呈，乞給下，取設齋日五更前上塔，臣自宣却欲重建，乞於仁政殿前夜間化却，不然便向塔前化，並取聖旨。判曰：便要吾人宣讀後，於真身塔前焚化。二十七日。」而在前花押。予謂錢氏固嘗三改元，但或言其稱帝，則否也。此狀內「進呈」、「聖旨」等語，蓋類西河之人疑子夏於夫子，故自貽僭帝之議，想它所施行皆然矣。","sortOrder":29},
  {"id":"s_work_dtbt_61_30","chapterId":"ch_work_dtbt_61","text":"王逸少為藝所累","sortOrder":30},
  {"id":"s_work_dtbt_61_31","chapterId":"ch_work_dtbt_61","text":"王逸少在東晉時，蓋溫太真、蔡謨、謝安石一等人也，直以抗懷物外，不為人役，故功名成就，無一可言，而其操履識見，議論閎卓，當世亦少其比。公卿愛其才器，頻召不就。殷淵源輔政，勸使應命，遺之書曰：「足下出處，正與隆替對，豈可以一世之存亡，必從足下從容之適？」逸少報曰：「吾素自無廊廟，王丞相欲內吾，誓不許之，手跡猶存，由來尚矣，不於足下參政而方進退。自兒娶女嫁，便懷尚子平之志，數與親知言之，非一日也。」及殷侯將北伐，以為必敗，貽書止之。殷敗後，復圖再舉，又遺書曰：「以區區江左，所營綜如此，天下寒心久矣。自寇亂以來，處內外之任者，疲竭根本，各從所志，竟無一功可論，一事可紀。任其事者，豈得辭四海之責哉！若猶以前事為未工，故復求之於分外，宇宙雖廣，何所自容！」又與會稽王箋曰：「今雖有可欣之會，內求諸己，而所憂乃重於所欣，以區區吳、越，經緯天下十分之九，不亡何待！願令諸軍皆還保淮，須根立勢舉，謀之未晚。」其識慮精深，如是其至，恨不見於用耳。而為書名所蓋，後世但以翰墨稱之。晉書本贊，標為唐太宗御撰，專頌其研精篆素，盡善盡美，至有「心慕手追」之語，略無一詞論其平生，則一藝之工，為累大矣。獻之立志，亦似其父。謝安欲使題太極殿榜，以為萬代寶，而難言之，試及韋仲將凌雲榜事，即正色曰：「使其若此，有以知魏德之不長。」遂不之逼。觀此一節，可以知其為人，而亦以書名之故，沒其盛德。二王尚爾，况於他人乎！","sortOrder":31},
  {"id":"s_work_dtbt_61_32","chapterId":"ch_work_dtbt_61","text":"鄂州南樓磨崖","sortOrder":32},
  {"id":"s_work_dtbt_61_33","chapterId":"ch_work_dtbt_61","text":"慶元元年，鄂州修南樓，剝土有大石露於外，奇崛可觀。郡守吳琚見而愛之，命洗剔出圭角，即而諦視，乃磨崖二碑。其一刻兩字，上曰「柳」，徑二尺四寸，筆勢清勁，下若翻書「天」字，唯存人腳，不可復辨，或以為符，或以為花押，邦人至褾飾置神堂，香火供事。或雲道州學側虞帝廟內亦有之，雲柳君名應辰，是唐末五代時湖北人也。其一高丈一尺，闊如其高而加五寸，刻大字八十五，凡為九行，其文曰：「乾正元年，荊襄寇亂，大吳將軍出陳武昌，詔太守楊公出鎮。」後雲：「荊、江、京、漢推忠、輔國、侍衞將軍吳居中記。」案楊行密之子溥嗣吳王位，是歲，唐明宗天成二年，溥以十一月僭帝，改元乾貞，宋莒公紀年通譜書為「乾正」，雲避仁宗嫌名，通鑑亦同。而此直以為「乾正」，一時所立，不應有誤也。","sortOrder":33},
  {"id":"s_work_dtbt_61_34","chapterId":"ch_work_dtbt_61","text":"賞魚袋出處","sortOrder":34},
  {"id":"s_work_dtbt_61_35","chapterId":"ch_work_dtbt_61","text":"隨筆書衡山唐碑別駕賞魚袋，雲「名不可曉」，今按唐職林魚帶門敍金玉銀鐵帶，及金銀魚袋雲：「開元敕，非灼然有戰功者，餘不得輒賞魚袋。」斯明文也。","sortOrder":35},
  {"id":"s_work_dtbt_62_1","chapterId":"ch_work_dtbt_62","text":"卷第十一(十八則)","sortOrder":1},
  {"id":"s_work_dtbt_62_2","chapterId":"ch_work_dtbt_62","text":"京丞相轉官","sortOrder":2},
  {"id":"s_work_dtbt_62_3","chapterId":"ch_work_dtbt_62","text":"慶元二年朝廷奉上三宮徽稱冊寶，繼又進敕令、玉牒、實錄，大臣遷秩，於再於三，蓋自崇寧至於紹熙，未之有也。於是京右丞相以十月受冊寶賞，由正議轉宣奉。十二月用敕局賞，當得兩官，以一回授、一轉光祿。三年二月，用提舉玉牒實錄院及禮儀使賞，有旨三項各轉兩官，辭之至四五。詔減為四官，其半回授，其二遂轉金紫。四月之間，陟五華資，仍回授三帙。在法宰執轉官與除拜同，故得給使恩。百二十年而入流者二十有四。邁記淳熙十四年，王左相進玉牒，幷充國史禮儀使；梁右相進四朝史傳、國朝會要，幷充玉牒禮儀使。詔各與轉兩官。所謂各者，指二相也。時梁公誤認為三者各兩官，已係特進，謂如此則序進太師矣。中批只共為兩官，復辭之，詔許回授，又辭，但令加恩，亦辭。適已罷相在經筵，訖於分毫不受，唯王公獨加恩。今日之事全相類，而又已有去冬二賞矣。有司不諳練故實，徑準昔年中旨行出，聞京公殊不自安，然無說可免，惜乎東閤賢賓客不告以十年內親的故事，以成其美。邁頃居翰苑，答王、梁諸詔，嘗上章開析論列，是以竊識其詳。","sortOrder":3},
  {"id":"s_work_dtbt_62_4","chapterId":"ch_work_dtbt_62","text":"熙寧司農牟利","sortOrder":4},
  {"id":"s_work_dtbt_62_5","chapterId":"ch_work_dtbt_62","text":"熙寧、元豐中，聚斂之臣，專務以利為國，司農遂粥天下祠廟。官既得錢，聽民為賈區，廟中慢侮穢踐，無所不至。南京有閼伯、微子兩廟，一歲所得不過七八千，張文定公判應天府，上言曰：「宋王業所基也，而以火王。閼伯封於商丘，以主大火，微子為宋始封，此二祠者獨不可免乎！乞以公使庫錢代其歲入。」神宗震怒，批出曰：「慢神辱國，無甚於斯！」於是天下祠廟皆得不粥。又有議前代帝王陵寢，許民請射耕墾，司農可之，唐之諸陵，因此悉見芟刈。昭陵喬木，翦伐無遺。御史中丞鄧潤甫言：「熙寧著令，本禁樵采，遇郊祀則敕吏致祭，德意可謂遠矣。小人掊克，不顧大體，使其所得不貲，猶為不可，况至為淺鮮者哉！願絀創議之人，而一切如故。」於是未耕之地僅得免。二者可謂前古未有，一日萬幾，蓋無由盡知之也。","sortOrder":5},
  {"id":"s_work_dtbt_62_6","chapterId":"ch_work_dtbt_62","text":"文與可樂府","sortOrder":6},
  {"id":"s_work_dtbt_62_7","chapterId":"ch_work_dtbt_62","text":"今人但能知文與可之竹石，惟東坡公稱其詩騷，又表出「美人却扇坐，羞落庭下花」之句。予常恨不見其全，比得蜀本石室先生丹淵集，蓋其遺文也。於樂府雜詠，有秦王卷衣篇曰：「鹹陽秦王家，宮闕明曉霞。丹文映碧鏤，光采相鈎加。銅螭逐銀猊，壓屋驚蟠拏。洞戶鎖日月，其中光景賒。春風動珠箔，鸞額金窠斜。美人却扇坐，羞落庭下花。閒弄玉指環，輕冰扼紅牙。君王顧之笑，為駐七寶車。自卷金縷衣，龍鸞蔚紛葩。持以贈所愛，結歡期無涯。」其語意冞入騷人閫域。又有王昭君三絕句雲：「絕豔生殊域，芳年入內庭。誰知金屋寵，只是信丹青。」「幾歲後宮塵，今朝絕國春。君王重恩信，不欲遣他人。」「極目胡沙滿，傷心漢月圓。一生埋沒恨，長入四條絃。」令人讀之，縹縹然感慨無已也！","sortOrder":7},
  {"id":"s_work_dtbt_62_8","chapterId":"ch_work_dtbt_62","text":"譏議遷史","sortOrder":8},
  {"id":"s_work_dtbt_62_9","chapterId":"ch_work_dtbt_62","text":"大儒立言著論，要當使後人無復擬議，乃為至當，如王氏中說謂：「陳壽有志於史，依大議而削異端，使壽不美於史，遷、固之罪也。」又曰：「史之失自遷、固始也，記繁而志寡。」王氏之意，直以壽之書過於漢、史矣，豈其然乎？元經續詩、書，猶有存者，不知能出遷、固之右乎？蘇子由作古史，謂：「太史公易編年之法，為本紀、世家、列傳，後世莫能易之，然其人淺近而不學，疏略而輕信，故因遷之舊，別為古史。」今其書固在，果能盡矯前人之失乎？指司馬子長為淺近不學，貶之已甚，後之學者不敢謂然。","sortOrder":9},
  {"id":"s_work_dtbt_62_10","chapterId":"ch_work_dtbt_62","text":"常何","sortOrder":10},
  {"id":"s_work_dtbt_62_11","chapterId":"ch_work_dtbt_62","text":"唐太宗貞觀五年，以旱，詔文武官極言得失。時馬周客遊長安，舍於中郎將常何之家。何武人，不學，不知所言，周代之陳便宜二十餘條。上怪其能，以問何。對曰：「此非臣所能，家客馬周為臣具草耳。」上即召周與語，甚悅，以何為知人，賜絹三百匹。常何後亦不顯，莫知其所以進。予案李密傳，密從翟讓與張須陁戰，率驍勇常何等二十人為遊騎，遂殺須陁，常何之名蓋見於此。唐史亦採於劉仁軌行年河洛記也。","sortOrder":11},
  {"id":"s_work_dtbt_62_12","chapterId":"ch_work_dtbt_62","text":"李密詩","sortOrder":12},
  {"id":"s_work_dtbt_62_13","chapterId":"ch_work_dtbt_62","text":"李密在隋大業中，從楊玄感起兵被獲，以計得脫。變姓名為劉智遠，教授諸生自給，鬱鬱不得志，哀吟泣下。唐史所書如此。劉仁軌行年河洛記，專載密事，雲：「密往來諸賊帥之間，說以舉大計，莫肯從者，因作詩言志，曰：『金風蕩初節，玉露垂晚林。此夕窮途士，鬱陶傷寸心。平野葭葦合，荒村葵藿深。眺聽良多感，徙倚獨沾襟。沾襟何所為？悵然懷古意。秦、洛既未平，漢道將何冀？樊噲市井屠，蕭何刀筆吏。一朝逢時會，千載傳名謚。寄言世上雄，虛生真可愧！』諸將見詩漸敬之。」予意此篇，正其哀吟中所作也。","sortOrder":13},
  {"id":"s_work_dtbt_62_14","chapterId":"ch_work_dtbt_62","text":"寺監主簿","sortOrder":14},
  {"id":"s_work_dtbt_62_15","chapterId":"ch_work_dtbt_62","text":"自元豐官製行，九寺、五監各置主簿，專以掌鈎考簿書為職，它不得預。紹聖初，韓粹彥為光祿主簿，自言今輒預寺事，非先帝意也，請如元豐詔書。從之。如玉牒修書，主簿不預，見於王定國舊錄，予猶及見。紹興中，太府寺公狀文移，惟卿丞繫銜，後來掌故之吏，昧於典章，遂一切與丞等。今百官庶府，背戾官製，非特此一事也。","sortOrder":15},
  {"id":"s_work_dtbt_62_16","chapterId":"ch_work_dtbt_62","text":"溫大雅兄弟名字","sortOrder":16},
  {"id":"s_work_dtbt_62_17","chapterId":"ch_work_dtbt_62","text":"新唐書，溫大雅字彥弘，弟彥博字大臨、大有字彥將，舊史不載彥博字，它皆同。三溫，兄弟也，而兩人以大為名，彥為字，一以彥為名，大為字。宰相世系表則雲彥將字大有。而博、雅與傳同，讀者往往致疑。歐陽公集古錄引顏思魯製中書舍人彥將行，證表為是，然則惟彥博異耳，故或以為誤。予少時因文惠公得歐率更所書虞恭公志銘，乃彥博也，其名字實然。後見大唐創業起居註，大雅所撰，其中雲：「煬帝遣使夜至太原，溫彥將宿於城西門樓上，首先見之。報兄彥弘，馳以啟帝，帝方臥，聞而驚起，執彥弘手而笑。」據此，則三溫之名皆從彥，而此書首題乃雲大雅奉敕撰。不應於其間敢自稱字。已而詳考之，高宗太子弘為武後所酖，追尊為孝敬皇帝，廟曰義宗，列於太廟，故諱其名。如弘文館改為昭文，弘農縣改為恆農，徐弘敏改為有功，韋弘機但為機，李含光本姓弘，易為李，曲阿弘氏易為洪，則大雅之名，後人追改之也。顏魯公作顏勤禮碑，敍顏、溫二家之盛，曰：思魯、大雅，愍楚、彥博，遊秦、彥將。以雅為名，亦由避諱耳。錢聞詩在太學，以此為策問，而言歐陽作傳，戾於聞見，彼蓋不察宋子京之作雲。","sortOrder":17},
  {"id":"s_work_dtbt_62_18","chapterId":"ch_work_dtbt_62","text":"冊府元龜","sortOrder":18},
  {"id":"s_work_dtbt_62_19","chapterId":"ch_work_dtbt_62","text":"真宗初，命儒臣編修君臣事跡，後謂輔臣曰：「昨見宴享門中錄唐中宗宴飲，韋庶人等預會和詩，與臣寮馬上口摘含桃事，皆非禮也。已令削之。」又曰：「所編事跡，蓋欲垂為典法，異端小說，鹹所不取，可謂盡善。」而編修官上言：「近代臣僚自述揚歷之事，如李德裕文武兩朝獻替記、李石開成承詔錄、韓偓金鑾密記之類，又有子孫追述先德敍家世，如李繁鄴侯傳、柳氏序訓、魏公家傳之類，或隱己之惡，或攘人之善，並多溢美，故匪信書。幷僭偽諸國，各有著撰，如偽吳錄、孟知祥實錄之類，自矜本國，事或近誣。其上件書，並欲不取。餘有三十國春秋、河洛記、壺關錄之類，多是正史已有；秦記、燕書之類，出自偽邦；殷芸小說、談藪之類，俱是詼諧小事；河南志、邠志、平剡錄之類，多是故吏賓從述本府戎帥征伐之功，傷於煩碎；西京雜記、明皇雜錄，事多語怪；奉天錄尤是虛詞。盡議採收，恐成蕪穢。」並從之。及書成，賜名冊府元龜，首尾十年，皆王欽若提總，凡一千卷，其所遺棄既多，故亦不能暴白。如資治通鑑則不然，以唐朝一代言之：敍王世充、李密事，用河洛記；魏鄭公諫爭，用諫錄；李絳議奏，用李司空論事；睢陽事，用張中丞傳；淮西事，用涼公平蔡錄；李泌事，用鄴侯家傳；李德裕太原、澤潞、回鶻事，用兩朝獻替記；大中吐蕃尚婢婢等事，用林恩後史補；韓偓鳳翔謀畫，用金鑾密記；平龐勛，用彭門紀亂；討裘甫，用平剡錄；記畢師鐸、呂用之事，用廣陵妖亂志。皆本末粲然，然則雜史、瑣說、家傳，豈可盡廢也！","sortOrder":19},
  {"id":"s_work_dtbt_62_20","chapterId":"ch_work_dtbt_62","text":"漢高帝祖稱豐公","sortOrder":20},
  {"id":"s_work_dtbt_62_21","chapterId":"ch_work_dtbt_62","text":"前漢書高祖紀贊雲：「劉氏自秦獲於魏。秦滅魏，遷大梁，都於豐。故周市說雍齒曰：『豐，故梁徙也。』是以頌高祖雲：『漢帝本系，出自唐帝。降及於周，在秦作劉。涉魏而東，遂為豐公。』豐公，蓋太上皇父。」案上六句皆韻語，不知何人作此頌，諸家註釋，大抵闕如。予自少時讀班史，今六七十年，何啻百遍，用朱點句，亦須十本，初不記憶高帝之祖稱豐公，比再閱之，恍然若昧平生，聊表見於此。舊書不厭百回讀，信哉！","sortOrder":21},
  {"id":"s_work_dtbt_62_22","chapterId":"ch_work_dtbt_62","text":"樞密行香","sortOrder":22},
  {"id":"s_work_dtbt_62_23","chapterId":"ch_work_dtbt_62","text":"唐世樞密使專以內侍為之，與它使均稱內諸司，五代以來始參用士大夫，遂同執政。案實錄所載景德二年三月元德皇後忌，中書、樞密院文武百官，並赴相國寺行香。初樞密院言：「舊例國忌行香，惟樞密使、副依內諸司例不赴，恐有虧恭恪。今欲每遇大忌日，與中書門下同赴行香。」從之。樞密使副、翰林、樞密直學士並赴，自茲始也。然則樞密之同內諸司久矣。隆興以來，定朝臣四參之儀，自宰臣至於郎官、御史，皆班列殿庭拜舞，惟樞密立殿上不預，亦此意雲。","sortOrder":23},
  {"id":"s_work_dtbt_62_24","chapterId":"ch_work_dtbt_62","text":"船名三翼","sortOrder":24},
  {"id":"s_work_dtbt_62_25","chapterId":"ch_work_dtbt_62","text":"文選張景陽七命曰：「浮三翼，戲中沚。」其事出越絕書，李善註頗言其略，蓋戰船也。其書雲：「闔閭見子胥，問船運之備。對曰：『船名大翼、小翼、突胃、樓船、橋船。大翼者當陵軍之車，小翼者當陵軍之輕車。』」又水戰兵法內經曰：「大翼一艘，廣一丈五尺三寸，長十丈；中翼一艘，廣一丈三尺五寸，長九丈；小翼一艘，廣一丈二尺，長五丈六尺。」大抵皆巨戰船，而昔之詩人，乃以為輕舟。梁元帝雲「日華三翼舸」，又雲「三翼自相追」，張正見雲「三翼木蘭船」，元微之雲「光陰三翼過」。其它亦鮮用之者。","sortOrder":25},
  {"id":"s_work_dtbt_62_26","chapterId":"ch_work_dtbt_62","text":"東坡誨葛延之","sortOrder":26},
  {"id":"s_work_dtbt_62_27","chapterId":"ch_work_dtbt_62","text":"江陰葛延之，元符間，自鄉縣不遠萬里省蘇公於儋耳，公留之一月。葛請作文之法，誨之曰：「儋州雖數百家之聚，而州人之所須，取之市而足，然不可徒得也，必有一物以攝之，然後為己用。所謂一物者，錢是也。作文亦然，天下之事散在經、子、史中，不可徒使，必得一物以攝之，然後為己用。所謂一物者，意是也。不得錢不可以取物，不得意不可以用事，此作文之要也。」葛拜其言，而書諸紳。嘗以親製龜冠為獻，公受之，而贈以詩曰：「南海神龜三千歲，兆葉朋從生慶喜。智能周物不周身，未死人鑽七十二。誰能用爾作小冠，岣嶁耳孫創其製。今君此去寧復來，欲慰相思時整視。」今集中無此詩。葛常之，延之三從弟也，嘗見其親筆。","sortOrder":27},
  {"id":"s_work_dtbt_62_28","chapterId":"ch_work_dtbt_62","text":"用書雲之誤","sortOrder":28},
  {"id":"s_work_dtbt_62_29","chapterId":"ch_work_dtbt_62","text":"今人以冬至日為書雲，至用之於表啟中，雖前輩或不細考，然皆非也。左氏傳：「僖公五年正月辛亥朔，日南至，公既視朔，遂登觀臺以望，而書，禮也。凡分、至、啟、閉，必書雲物，為備故也。」杜預註雲：「周正月，今十一月。分，春秋分也；至，冬夏至也；啟者，立春、立夏；閉者，立秋、立冬；雲物者，氣色災變也。」蓋四時凡八節，其禮並同。漢明帝永平二年春正月辛未，宗祀光武畢，登靈臺觀雲物，尤可為證。而但讀左傳前兩三句，故遂顓以指冬至雲。今太史局官，每至此八日，則為一狀，若立春則曰風從艮位上來，春分則曰風從震位上來，它皆仿此，只是定本，元非摭實。起居註隨即修入，顯為文具，蓋古之書雲意也。","sortOrder":29},
  {"id":"s_work_dtbt_62_30","chapterId":"ch_work_dtbt_62","text":"張鷟譏武後濫官","sortOrder":30},
  {"id":"s_work_dtbt_62_31","chapterId":"ch_work_dtbt_62","text":"武後革命，濫授人官，故張鷟為諺以譏之曰：「補闕連車載，拾遺平斗量，杷推侍御史，椀脫校書郎。」唐新、舊史亦載其語，但泛言之。案天授二年二月，以十道使所舉人石艾縣令王山輝等六十一人，並授拾遺、補闕；懷州錄事參軍霍獻可等二十四人，並授侍御史；幷州錄事參軍徐昕等二十四人，授著作郎；內黃縣尉崔宣道等二十三人，授衞佐校書。凡百三十二人，同日而命，試官自此始也。其濫如此！劉子玄傳：「武後詔九品以上陳得失，子玄言：『君不虛授，臣不虛受。今羣臣無功，遭遇輒遷，至都下有車載、斗量、杷推、椀脫之諺。』」正為此設，然只是自外官便除此四職，非所謂輒遷，子玄之言失之矣。","sortOrder":31},
  {"id":"s_work_dtbt_62_32","chapterId":"ch_work_dtbt_62","text":"唐王府官猥下","sortOrder":32},
  {"id":"s_work_dtbt_62_33","chapterId":"ch_work_dtbt_62","text":"唐自高宗以後，諸王府官益輕，惟開元二十三年，加榮王以下官爵，悉拜王府官屬。浸又減省，僅有一傅一友一長史，亦但備員，至與其府王不相見。寶曆中，瓊王府長史裴簡求具狀言：「諸王府本在宣平坊，多年摧毀，後付莊宅使收管，遂為公局。每聖恩除授，無處禮上。王官為衆所輕，府既不存，官同虛設，伏乞賜官宅一區。」乃詔賜延康坊宅。予因閱九經字樣一書，開成中唐玄度所纂，其官階雲朝議郎知沔王友，充翰林待詔。沔王名恂，憲宗之子，而以書吏為友，其餘可知。案文、武、宣、昭四宗，皆自藩王登大位，剛明果斷，為史所稱，蓋出於天性，然非資於師友成就也。","sortOrder":33},
  {"id":"s_work_dtbt_62_34","chapterId":"ch_work_dtbt_62","text":"御史風聞","sortOrder":34},
  {"id":"s_work_dtbt_62_35","chapterId":"ch_work_dtbt_62","text":"御史許風聞論事，相承有此言，而不究所從來，以予考之，蓋自晉、宋以下如此。齊沈約為御史中丞，奏彈王源曰：「風聞東海王源。」蘇冕會要雲：「故事，御史臺無受詞訟之例，有詞狀在門，御史採狀有可彈者，即略其姓名，皆雲風聞訪知。其後疾惡公方者少，遞相推倚，通狀人頗壅滯。開元十四年，始定受事御史，人知一日劾狀，遂題告事人名，乖自古風聞之義。」然則向之所行，今日之短卷是也。二字本見尉佗傳。","sortOrder":35},
  {"id":"s_work_dtbt_62_36","chapterId":"ch_work_dtbt_62","text":"唐御史遷轉定限","sortOrder":36},
  {"id":"s_work_dtbt_62_37","chapterId":"ch_work_dtbt_62","text":"唐元和中，御史中丞王播奏：「監察御史，舊例在任二十五月轉，準具員不加，今請仍舊；其殿中侍御史，舊十二月轉，具員加至十八月，今請減至十五月；侍御史，舊十月轉，加至十三月，今請減至十二月。」從之。案唐世臺官，雖職在抨彈，然進退從違，皆出宰相，不若今之雄緊，觀其遷敍定限可知矣。國朝未改官製之前，任監察滿四年而轉殿中，又四年轉侍御史，又四年解臺職，始轉司封員外郎。元豐五年以後，升沉迥別矣。","sortOrder":37},
  {"id":"s_work_dtbt_63_1","chapterId":"ch_work_dtbt_63","text":"卷第十二(十三則)","sortOrder":1},
  {"id":"s_work_dtbt_63_2","chapterId":"ch_work_dtbt_63","text":"小學不講","sortOrder":2},
  {"id":"s_work_dtbt_63_3","chapterId":"ch_work_dtbt_63","text":"古人八歲入小學，教之六書，周官保氏之職，實掌斯事，厥後浸廢。蕭何著法，太史試學童，諷書九千字，乃得為吏。以六體試之。吏人上書，字或不正，輒有舉劾。劉子政父子校中祕書，自史籀以下凡十家，序為小學，次於六藝之末。許叔重收集篆、籀、古文諸家之學，就隸為訓註，謂之說文。蔡伯喈以經義分散、傳記交亂、訛偽相蒙，乃請刊定五經，備體刻石，立於太學門外，謂之石經。後有呂忱，又集說文之所漏略，著字林五篇以補之。唐製，國子監置書學博士，立說文、石經、字林之學，舉其文義，歲登下之。而考功、禮部課試貢舉，許以所習為通，人苟趨便，不求當否。大曆十年，司業張參纂成五經文字，以類相從。至開成中，翰林待詔唐玄度又加九經字樣，補參之所不載。晉開運末，祭酒田敏合二者為一編，並以考正俗體訛謬。今之世不復詳考，雖士大夫作字，亦不能悉如古法矣。韓子曰：「凡為文辭，宜略識字。」又雲：「阿買不識字，頗知書八分。」安有不識字而能書，蓋所謂識字者，如上所雲也。予采張氏、田氏之書，擇今人所共昧者，漫載於此，以訓子孫。本字從木，一在其下，今為大十者非。休字象人息於木陰，加點者非。美從羊從大，今從犬從火者非。（勹內車）字古者以車戰，故軍從勹下車，後相承作軍，義無所取。看字從手，凡視物不審，則以手遮目看之，作（上乎下目）者非。揚州取輕揚之義，從木者非。梁從木，作梁者非。乾有幹、虔二音，為字一體，今俗分別作乹字音虔，而乾音幹者非。尊從酋下寸，作（上酋中一下寸）者非。奠從酋從丌，作（上酋中一下八）者非。夷從弓從大，作夷者訛。耆從旨，作老下目者訛。漆、泰、黍、黎，下並從水，相承省作氺，今從小，從(小者訛。決、沖、況、涼、盜並從水，作冫者訛。饑、飢二字，上穀不熟，下餓也，今多誤用。至於果、芻、韭之加草，岡加山，攜之作携，鉏作鋤，惡作（上覀下心），霸作覇，筍作筍，（左上彡下止右頁）作髭，須加髟或從水，祕從禾，（上竹下閒）作蕳，寶從爾，趨從多，衡合從角從大而從魚，啟從又及弋，肈從文，徹從去，麤作（鹿上丶作勹），蟲作虫，墮許規反，俗作隳，又以為惰，幡作（巾畨），怪為恠，關為（闗之灬為大），炙從夕，閒從日，功從刀，玆合從二玄而作茲，升作（廾左上右下加丶），輩從北，妒從（後去一），姦為（左上女下女右幹），纛從毒，吝作（上乂下厷），冤上加點，鄰作隣，牟從午，互作（牙之撇作捺），元從點，舌從千，蓋作蓋，京作亰，皎從日，次從冫，鼓從皮，濳、（左言右上兟下曰）、（左亻右上兟下曰）從替，出作二山，覺從與，遊、於以方為才，皁為皂，曷為（是曰下匂），匹為疋，收作（丬又），敍作叙，臥從臣從人，而以人為卜，改從戊己之己而以為衛，凡作（上丶下幾），允作（允之上丶作丿去下丿），館作舘，覽作（上左臣右丿二下見），祭合從月從又而作（癸下作示），瞻作（瞻之言作上工下口），緥從衣，淫從（上个下正），徧作遍，徼作僥，漾作（漾之永作水），琴瑟之絃從系，輕作（軯之平下加一），如是者皆非也。","sortOrder":3},
  {"id":"s_work_dtbt_63_4","chapterId":"ch_work_dtbt_63","text":"主臣","sortOrder":4},
  {"id":"s_work_dtbt_63_5","chapterId":"ch_work_dtbt_63","text":"漢文帝問陳平決獄、錢穀，平謝曰：「主臣！」史記、漢書皆同。張晏曰：「若今人謝曰『惶恐』也。」文穎曰：「惶恐之辭，猶今言死罪也。」晉灼曰：「主，擊也。臣，服也。言其擊服，惶恐之辭。」馬融龍虎賦曰：「勇怯見之，莫不主臣。」正用此意。文選載梁任昉奏彈曹景宗，先敍其罪，然後繼之曰「景宗即主臣」，仍繼之曰「謹案某官臣景宗」，又彈劉整亦曰「整即主臣」。齊沈約彈王源文亦然。李善捨漢、史所書，而引王隱晉書庾純自劾以謂然，以主為句，則臣當下讀，殊為非是。不知所謂某人即主，有何義哉？","sortOrder":5},
  {"id":"s_work_dtbt_63_6","chapterId":"ch_work_dtbt_63","text":"景華御苑","sortOrder":6},
  {"id":"s_work_dtbt_63_7","chapterId":"ch_work_dtbt_63","text":"崔德符坐元符上書邪黨，困於崇寧。後監洛南稻田務，嘗送客於會節園，是時冬暮，梅花已開。明年春，監修大內，閹官容佐取以為景華御苑，德符不知也。至春晚，復騎瘦馬與老兵遊園內，坐梅下賦詩。其詞曰：「去年白玉花，結子深枝間。小憩藉清影，低顰啄微酸。","sortOrder":7},
  {"id":"s_work_dtbt_63_8","chapterId":"ch_work_dtbt_63","text":"故人不可見，春事今已闌。繞樹尋履跡，空餘土花斑。」次日，佐入園，見地上馬糞，知為德符。是時，府官事佐如不及，而德符未嘗謁之。佐即具奏，劾以擅入御苑作踐。有旨勒停。家素貧，傳食於諸賢之舍，久乃歸陽翟。德符沒於靖康，官卑不應立傳，予詳考本末為特書之，頗憶此段事，擬載於傳中，以悼君子之不幸。且知馬永卿懶真錄中有之，而求不可得，漫紀於此。","sortOrder":8},
  {"id":"s_work_dtbt_63_9","chapterId":"ch_work_dtbt_63","text":"州升府而不為鎮","sortOrder":9},
  {"id":"s_work_dtbt_63_10","chapterId":"ch_work_dtbt_63","text":"州郡之名，莫重於府，雖節鎮不及焉，固未有稱府而不為節度者。比年以來，升蜀州為崇慶府，劍州為隆慶府，恭州為重慶府，嘉州為嘉定府，秀州為嘉興府，英州為英德府。蜀、劍既有崇慶、普安軍之額，而恭、嘉以下獨未然，故幕職官仍雲某府軍事判官、推官，大與府不相稱，皆有司之失也。信陽軍一小壘耳，而司戶參軍銜內帶兼節推，尤為可笑。頃在中都時，每為天官主者言之，雲亦不必白朝廷，只本案檢舉改正申知足矣。乃曰：「久例如此。」竟相承到今。文安公嘗為左選侍郎，是時，未知此也。","sortOrder":10},
  {"id":"s_work_dtbt_63_11","chapterId":"ch_work_dtbt_63","text":"漢唐三君知子","sortOrder":11},
  {"id":"s_work_dtbt_63_12","chapterId":"ch_work_dtbt_63","text":"英明之君，見其子有材者，必愛而稱之。漢高祖謂趙王如意類己，欲以易孝惠，以大臣諫而止。宣帝以淮陽王欽壯大，好經書、法律，聰達有材，數嗟嘆曰：「真我子也！」常有意欲立為嗣，而用太子起於微細，且早失母，故弗忍。唐太宗以吳王恪英果類我，欲以代雉奴。其後如意為呂母所戕，恪為長孫無忌所害，欽陷張博之事，殆於不免。此三王行事無由表見。然孝惠之仁弱，幾遭呂氏之覆宗；孝元之優柔不斷，權移於閽寺，漢業遂衰；高宗之庸懦，受製凶後，為李氏禍尤慘。其不能繼述固已灼然。高祖、宣帝、太宗蓋本三子之材而言之，非專指其容貌也，可謂知子矣。彼明崇儼謂英王哲(即中宗也。)貌類太宗，張說謂太宗畫像雅類忠王，(即肅宗也。)此惟取其形似也。若以材言之，中宗之視太宗，天壤相隔矣！漢成帝所幸妾曹宮產子，曰：「我兒額上有壯髮，類孝元皇帝。」使其真是孝元，亦何足道？而况於嬰孺之狀邪！","sortOrder":12},
  {"id":"s_work_dtbt_63_13","chapterId":"ch_work_dtbt_63","text":"當官營繕","sortOrder":13},
  {"id":"s_work_dtbt_63_14","chapterId":"ch_work_dtbt_63","text":"元豐元年，范純粹自中書檢正官謫知徐州滕縣，一新公堂吏舍，凡百一十有六間，而寢室未治，非嫌於奉己也，曰吾力有所未暇而已。是時，新法正行，御士大夫如束濕，雖任二千石之重，而一錢粒粟，不敢輒用，否則必著冊書。東坡公嘆其廉，適為徐守，故為作記。其略曰：「至於宮室，蓋有所從受，而傳之無窮，非獨以自養也。今日不治，後日之費必倍。而比年以來，所在務為儉陋，尤諱土木營造之功，欹仄腐壞，轉以相付，不敢擅易一椽，此何義也！」是記之出，新進趨時之士，媢疾以惡之。恭覽國史，開寶二年二月詔曰：「一日必葺，昔賢之能事。如聞諸道藩鎮、郡邑公宇及倉庫，凡有隳壞，弗即繕修，因循歲時，以至頹毀，及僝工充役，則倍增勞費。自今節度、觀察、防禦、團練使、刺史、知州、通判等罷任，其治所廨舍，有無隳壞及所增修，著以為籍，迭相符授。幕職州縣官受代，則對書於考課之曆，損壞不全者，殿一選，修葺、建置而不煩民者，加一選。」太祖創業方十年，而聖意下逮，克勤小物，一至於此！後之當官者不復留意。以興仆植僵為務，則暗於事體、不好稱人之善者，往往翻指為妄作名色，盜隱官錢，至於使之束手諱避，忽視傾陋，逮於不可奈何而後已。殊不思貪墨之吏，欲為奸者，無施不可，何必假於營造一節乎？","sortOrder":14},
  {"id":"s_work_dtbt_63_15","chapterId":"ch_work_dtbt_63","text":"治曆明時","sortOrder":15},
  {"id":"s_work_dtbt_63_16","chapterId":"ch_work_dtbt_63","text":"易革之彖曰：「天地革而四時成。湯、武革命，順乎天而應乎人。」魏、晉而降，凡及禪代者，必據以為說。案漢轅固與黃生爭論湯、武於景帝前，但評受命之是非，不引易為證。卦之象曰：「君子以治曆明時。」其義了不相涉。偃孫頗留意曆學，雲按唐一行大衍曆日度議曰：「顓帝曆上元甲寅正月甲寅晨初合朔立春，七曜皆直艮維之首，湯作殷曆，更以十一月合朔冬至為上元，周人因之。」此謂治曆也。至於三統之建，夏以寅為歲首，得人統；殷以丑，為得地統；周武王改從子，為得天統。此謂明時也。其革命之說，劉歆作三統曆及譜，引革彖「湯、武革命」，又曰「治曆明時，所以和人道也」，如是而已。其前又引逸書曰：「先其革命。」顏師古曰：「言王者統業，先立算數，以命百事也。」推此而伸之，所雲革命，蓋謂是耳，非論其取天下也。况大衍之用四十有九，一行以之起曆，而革卦之序，在周易正當四十九，然則專為曆甚明。考其上句，尤極顯白，然諸儒贊易，皆不及此，王弼亦無一言。","sortOrder":16},
  {"id":"s_work_dtbt_63_17","chapterId":"ch_work_dtbt_63","text":"仕宦捷疾","sortOrder":17},
  {"id":"s_work_dtbt_63_18","chapterId":"ch_work_dtbt_63","text":"唐傅遊藝以期年之中，歷衣青、綠、朱、紫，時人謂之「四時仕宦」，言其速也。國朝惟綠、緋、紫三等。而紫袍者，除武臣外，文官之製其別有六：庶僚黑角帶，佩金魚；未至侍從，而特賜帶者，為荔枝五子，不佩魚；中書舍人、諫議、待製、權侍郎，紅鞓黑犀帶，佩魚；權尚書、御史中丞、資政、端明殿閣學士、直學士、正侍郎、給事中，金御仙花帶，不佩魚，謂之橫金；翰林學士以上正尚書，御仙帶，佩魚，謂之重金；執政官宰相，方團毬文帶，俗謂之笏頭者是也。其敍如此。若猛進躐得者則不然。紹興中，宋樸自侍御史遷中丞，施鉅自中書檢正、鄭仲熊自右正言，並遷權侍郎，三人皆受告日易服，以正謝日拜執政。樸、鉅以緋，仲熊以綠，服紫之次日，而賜毬文帶。蓋侍從以下，俟正謝乃易帶，而執政命才下，即遣中使賫賜，遂服之而赴都堂供職，可謂捷疾矣。若李綱則又異於是，宣和七年十二月二十九日，自太常少卿除兵部侍郎，未謝間，靖康元年正月四日，胡騎將至京城，綱以邊事求見。宰執奏事未退，綱語知閤門事朱孝莊曰：「有急切公事，欲與宰執廷辯。」孝莊曰：「舊例，未有宰執未退而從官求對者。」綱曰：「此何時，而用例邪！」孝莊即具奏。詔引綱立於執政之末。時宰執議欲奉鑾輿出狩襄、鄧，綱請固守，上曰：「誰可將者？」綱曰：「願以死報；第人微官卑，恐不足以鎮服士卒。」白時中乞以為禮部尚書，綱曰：「亦只是侍從。」即命除尚書右丞。綱曰：「臣未正謝，猶衣綠，非所以示中外。」即面賜袍帶幷笏，綱服之以謝，且言：「方時艱難，臣不敢辭。」此為不經緋紫而極其服章，未之有也。","sortOrder":18},
  {"id":"s_work_dtbt_63_19","chapterId":"ch_work_dtbt_63","text":"詞臣益輕","sortOrder":19},
  {"id":"s_work_dtbt_63_20","chapterId":"ch_work_dtbt_63","text":"治平以前，謂翰林學士及知製誥為兩製，自翰林罷補外者，得端明殿學士，謂之換職。熙寧之後，乃始為龍圖，紹興以來愈不及矣。修起居註者序遷知製誥，其次及辭不為者，乃為待製，趙康靖、馮文簡、曾魯公、司馬公、呂正獻公是也。學士闕，則次補，或為宰相所不樂者，猶得侍讀學士，劉原甫是也。在職未久而外除者，為樞密直學士，韓魏公是也；亦為龍圖直學士，歐陽公是也。後來褒擢者，僅得待製，王時亨是也。餘以善去者，集英修撰而止耳。","sortOrder":20},
  {"id":"s_work_dtbt_63_21","chapterId":"ch_work_dtbt_63","text":"夏英公好處","sortOrder":21},
  {"id":"s_work_dtbt_63_22","chapterId":"ch_work_dtbt_63","text":"夏英公既失時譽，且以慶曆聖德頌之故，不正之名愈彰，然固自有好處。夏羌之叛，英公為四路經略安撫招討使，韓魏公副之。賊犯山外，韓公令大將任福自懷遠城趨得勝寨，出賊後，如未可戰，即據險置伏，要其歸，戒之至再。又移檄申約，苟違節度，雖有功亦斬。福竟為賊誘，沒於好水川，朝論歸咎於韓。英公使人收散兵，得韓檄於福衣帶間，言罪不在韓，故但奪一官。英公此事賢矣，而後來士大夫未必知也，予是以表出之。","sortOrder":22},
  {"id":"s_work_dtbt_63_23","chapterId":"ch_work_dtbt_63","text":"祖宗用人","sortOrder":23},
  {"id":"s_work_dtbt_63_24","chapterId":"ch_work_dtbt_63","text":"祖宗用人，進退遲速，不執一端，苟其材可任，則超資越級，曾不少靳，非拘拘於愛惜名器也。宋琪自員外郎以正月擢拜諫議大夫，三月參知政事。太宗將用李昉，時昉官工部尚書，七月特遷琪刑書，遂並命為相。而琪居昉上，自外郎歲中至此。石熙載以太平興國四年正月，自右補闕(今朝奉郎。)為兵部員外郎、(今朝請郎。)樞密直學士，才七日，簽書院事，四月拜給事中，(今通議大夫。)為副樞，十月遷刑部侍郎，(今正議。)六年遷戶部尚書，(今銀青光祿。)為使，八年罷為右僕射，(今特進。)從初至此五歲，用今時階秩言之，乃是朝奉郎而為特進也。當日職名，唯有密直多從庶僚得之，旋即大用。張齊賢、王沔皆自補闕、直史館，遷郎中，充學士，越半歲並遷諫議、簽樞。溫仲舒、寇準皆自正言、(今承議郎。)直館，遷郎中，充職二年，並為樞密副使。向敏中自工部郎中以本官充職，越三月同知密院。錢若水自同州推官入直史館，逾年擢知製誥，二年除翰林學士，遂以諫議同知密院，首尾五年。","sortOrder":24},
  {"id":"s_work_dtbt_63_25","chapterId":"ch_work_dtbt_63","text":"至道九老","sortOrder":25},
  {"id":"s_work_dtbt_63_26","chapterId":"ch_work_dtbt_63","text":"李文正公昉罷相後，只居京師，以司空致仕。至道元年，年七十一矣，思白樂天洛中九老之會。適交遊中有此數，曰太子中允張好問，年八十五；太常少卿李運，年八十；故相吏部尚書宋琪、廬州節度副使武允成，皆七十九；吳僧贊寧，年七十八；郢州刺史魏丕，年七十六；左諫議大夫楊徽之，年七十五；水部郎中朱昂與昉，皆七十一。欲繼其事為宴集，會蜀寇起而罷。其中兩宰相乃著一僧，唐世及元豐耆英所無也。次年，李公即世，此事竟不成。耋老康寧，相與燕嬉於升平之世，而雅懷弗遂，造物豈亦吝此耶！","sortOrder":26},
  {"id":"s_work_dtbt_63_27","chapterId":"ch_work_dtbt_63","text":"李文正兩罷相","sortOrder":27},
  {"id":"s_work_dtbt_63_28","chapterId":"ch_work_dtbt_63","text":"宰相拜罷，恩典重輕，詞臣受旨者，得以高下其手。李文正公昉，太平興國八年，以工部尚書為集賢、史館相。端拱元年，為布衣翟馬周所訟。太宗召學士賈黃中草製，罷為右僕射，令詔書切責。黃中言：「僕射百寮師長，今自工書拜，乃為殊遷，非黜責之義。若以均勞逸為辭，斯為得體。」上然之，其詞略雲：「端揆崇資，非賢不授。昉素高聞望，久展謨猷，謙和秉君子之風，純懿擅吉人之美。輟從三事，總彼六卿，用資鎮俗之清規，式表尊賢之茂典。」其美如此。淳化二年，復歸舊廳。四年又罷，優加左僕射，學士張洎言：「近者霖霔百餘日，昉職在燮和陰陽，不能决意引退。僕射之重，右減於左，位望不侔，因而授之，何以示勸？」上批洎奏尾，止令罷守本官。洎遂草製峻詆，腦詞雲：「燮和陰陽，輔相天地，此宰相之任也。苟或依違在位，啟沃無聞，雖居廊廟之崇，莫著彌綸之效。宜敷朝旨，用罷鼎司。昉自處機衡，曾無規畫。擁化源而滋久，孤物望以何深！俾長中臺，尚為優渥。可依前尚書右僕射，罷知政事。」歷考前後製麻，只言可某官，其雲罷知政事者，洎創增之也。國史昉傳雲：昉厚善洎，及昉罷，洎草製乃如此。紹興二十九年，沈該罷製，學士周麟之於結句後，添入可罷尚書左僕射同平章事，蓋用此雲。","sortOrder":28},
  {"id":"s_work_dtbt_64_1","chapterId":"ch_work_dtbt_64","text":"卷第十三(二十四則)","sortOrder":1},
  {"id":"s_work_dtbt_64_2","chapterId":"ch_work_dtbt_64","text":"科舉之弊不可革","sortOrder":2},
  {"id":"s_work_dtbt_64_3","chapterId":"ch_work_dtbt_64","text":"法禁益煩，奸偽滋熾，唯科場最然，其尤者莫如銓試。代筆有禁也，禁之愈急，則代之者獲賂謝愈多。其不幸而敗者百無一二，正使得之，元未嘗致法。吏部長貳簾試之製，非不善也，而文具兒戲，抑又甚焉。議論奉公之臣，朝夕建明，然此風如决流偃草，未嘗少革。或以謂失於任法而不任人之故。殊不思所任之人，渠肯一意向方，見惡輒取，於事無益，而禍謗先集於厥身矣！開寶中，太子賓客邊光範掌選，太廟齋郎李宗訥赴吏部銓，光範見其年少，意未能屬辭，語之曰：「苟援筆成六韻，雖不試書判，可入等矣。」宗訥曰：「非唯學詩，亦嘗留心詞賦。」即試詩賦二首，數刻而就。甚嘉賞之，翌日擬授祕書省正字。今之世，寧復有是哉！","sortOrder":3},
  {"id":"s_work_dtbt_64_4","chapterId":"ch_work_dtbt_64","text":"宰執子弟廷試","sortOrder":4},
  {"id":"s_work_dtbt_64_5","chapterId":"ch_work_dtbt_64","text":"太宗朝，呂文穆公蒙正之弟蒙亨舉進士，禮部高等薦名。既廷試，與李文正公昉之子宗諤，並以父兄在中書罷之。國史許仲宣傳雲，仲宣子待問，雍熙二年舉進士，與李宗諤、呂蒙亨、王扶幷預廷試。宗諤即宰相昉之子，蒙亨參知政事蒙正之弟，扶鹽鐵使明之子。上曰：「斯並勢家，與孤寒競進，縱以藝升，人亦謂朕有私也。」皆下第，正此事也。仲宣時為度支使。仁宗朝，韓忠憲公億為參知政事，子維以進士奏名禮部，不肯試大廷，受蔭入官。唐質肅公介參政，子義問鎖廳試禮部，用舉者召試祕閣，介引嫌罷之。舊製，嚴於宰執子弟如此，與夫秦益公柄國，而子熺、孫塤皆於省殿試輒冠多士者異矣！","sortOrder":5},
  {"id":"s_work_dtbt_64_6","chapterId":"ch_work_dtbt_64","text":"國初救弊","sortOrder":6},
  {"id":"s_work_dtbt_64_7","chapterId":"ch_work_dtbt_64","text":"國朝削併僭偽，救民水火之中，然亦有因仍舊弊，未暇更張者，故須賴於賢士大夫昌言之。江左初平，太宗選張齊賢為江南西路轉運使，諭以民間不便事，令一一條奏。先是諸州罪人多錮送闕下，緣路非理而死者，常十五六。齊賢至蘄州，見南劍州吏送罪人者，索得州帖視之。二人皆逢販私鹽者，為荷鹽籠得鹽二斤，又六人皆嘗見販鹽而不告者，並黥决傳送，而五人已死於路。江州司理院自正月至二月，經過寄禁罪人，計三百二十四人。建州民二人，本田家客戶，嘗於主家塘內，以錐刺得魚一斤半，並杖脊、黥面，送闕下。齊賢上言：「乞俟至京，擇官慮問，如顯有負屈者，本州官吏量加懲罰。自今只令發遣正身。」及虔州，送三囚，嘗市得牛肉，幷家屬十二人悉詣闕，而殺牛賊不獲，齊賢憫之，即遣其妻子還。自是江南送罪人者減大半。是皆相循習所致也，齊賢改為，其利民如此。齊賢以太平興國二年方登科，六年為使者，八年還朝，由密學拜執政，可謂迅用也。","sortOrder":7},
  {"id":"s_work_dtbt_64_8","chapterId":"ch_work_dtbt_64","text":"房玄齡名字","sortOrder":8},
  {"id":"s_work_dtbt_64_9","chapterId":"ch_work_dtbt_64","text":"舊唐書目錄書房元齡，而本傳雲房喬字玄齡，新唐書列傳房玄齡字喬，而宰相世系表玄齡字喬松，三者不同。趙明誠金石錄得其神道碑，褚遂良書，名字與新史傳同。予記先公自燕還，有房碑一冊，於志寧撰，乃玄齡字喬松，本欽宗在東宮時所藏，其後猶有一印，曰「伯志西齋」。今亦不存矣。","sortOrder":9},
  {"id":"s_work_dtbt_64_10","chapterId":"ch_work_dtbt_64","text":"二朱詩詞","sortOrder":10},
  {"id":"s_work_dtbt_64_11","chapterId":"ch_work_dtbt_64","text":"朱載上，舒州桐城人，為黃州教授，有詩雲：「官閒無一事，胡蝶飛上階。」東坡公見之，稱賞再三，遂為知己。中書舍人新仲翌，其次子也，有家學，十八歲時，戲作小詞，所謂「流水泠泠，斷橋斜路梅枝亞」者。朱希真見而書諸扇，今人遂以為希真所作。又有摺摺扇詞雲：「宮紗蜂趕梅，寶扇鸞開翅。數摺聚清風，一捻生秋意。搖搖雲母輕，裊裊瓊枝細。莫解玉連環，怕作飛花墜。」公親書稿固存，亦因張安國書扇，而載於於湖集中。其詠五月菊詞雲：「玉臺金盞對炎光。全似去年香。有意莊嚴端午，不應忘却重陽。菖蒲九節，金英滿把，同泛瑤觴。舊日東籬陶令，北窗正傲羲皇。」淵明於五六月高臥北窗之下，清風颯至，自謂羲皇上人。用此事於五月菊，詩家嘆其精切雲。","sortOrder":11},
  {"id":"s_work_dtbt_64_12","chapterId":"ch_work_dtbt_64","text":"金剛經四句偈","sortOrder":12},
  {"id":"s_work_dtbt_64_13","chapterId":"ch_work_dtbt_64","text":"今世所行金剛經，用姚秦鳩摩羅什所譯，其四句偈曰：「一切有為法，如夢幻泡影，如露亦如電，應作如是觀。」又曰：「若以色見我，以音聲求我，是人行邪道，不能見如來。」予博觀它本，頗有不同。元魏天竺三藏菩提流支譯雲：「一切有為法，如星翳燈幻，露泡夢電雲，應作如是觀。」而「不能見如來」之下更有四句雲：「彼如來妙體，即法身諸佛，法體不可見，彼識不能知。」陳天竺三藏真諦譯雲：「如如不動，恆有正說，應觀有為法，如暗翳燈幻，露泡夢電雲。若以色見我，以音聲求我，是人行邪道，不應得見我。由法應見佛，調御法為身，此法非識境，法如深難見。」唐三藏玄奘譯雲：「諸和合所為，如星翳燈幻，露泡夢電雲，應作如是觀。諸以色見我，以音聲尋我，彼生履邪斷，不能當見我。應觀佛法性，即導師法身，法性非所識，故彼不能了。」唐沙門義淨譯前四句，與魏菩提本同，而後雲：「若以色見我，以音聲求我，是人起邪觀，不能當見我。」後四句與玄奘本同。予案今人稱六如，東坡以名堂者，謂夢幻泡影露電也。而此四譯，乃知有九如。大般若經，第八會世尊頌，第九會能斷金剛分二頌，亦與玄奘所譯同。","sortOrder":13},
  {"id":"s_work_dtbt_64_14","chapterId":"ch_work_dtbt_64","text":"四蓮華之名","sortOrder":14},
  {"id":"s_work_dtbt_64_15","chapterId":"ch_work_dtbt_64","text":"嗢鉢摩華，青蓮華也；鉢特摩華，亦雲波頭摩，赤蓮華也；拘毋陁華，亦雲俱物頭，亦雲俱牟陁，紅蓮也；奔荼利華，亦雲芬陁利，白蓮也。堵羅綿，柳絮之類，即兜羅綿也。","sortOrder":15},
  {"id":"s_work_dtbt_64_16","chapterId":"ch_work_dtbt_64","text":"黑法白法","sortOrder":16},
  {"id":"s_work_dtbt_64_17","chapterId":"ch_work_dtbt_64","text":"安立黑法，感黑異熟，所謂地獄傍生鬼界。安立白法，感白異熟，所謂人天。安立黑白法，感黑白異熟，所謂一分傍生鬼界及一分人。安立非黑非白法，感非黑非白異熟，所謂預留果，或一來果，或不還果。","sortOrder":17},
  {"id":"s_work_dtbt_64_18","chapterId":"ch_work_dtbt_64","text":"多心經偈","sortOrder":18},
  {"id":"s_work_dtbt_64_19","chapterId":"ch_work_dtbt_64","text":"多心經偈曰：「揭帝揭帝，波羅揭帝，波羅僧揭諦，菩提薩摩訶。」又有大明呪經，鳩羅什所譯，曰：「竭帝竭帝，波羅竭帝，波羅僧竭帝，菩提僧莎呵。」","sortOrder":19},
  {"id":"s_work_dtbt_64_20","chapterId":"ch_work_dtbt_64","text":"天宮寶樹","sortOrder":20},
  {"id":"s_work_dtbt_64_21","chapterId":"ch_work_dtbt_64","text":"「行行相值，莖莖相望。枝枝相准，葉葉相向。華華相順，實實相當。」此無量壽經所言，天宮寶樹，非塵世所有也。","sortOrder":21},
  {"id":"s_work_dtbt_64_22","chapterId":"ch_work_dtbt_64","text":"白分黑分","sortOrder":22},
  {"id":"s_work_dtbt_64_23","chapterId":"ch_work_dtbt_64","text":"月盈至滿，謂之白分；月虧至晦，謂之黑分。白前黑後合為一月。又曰，日隨月後行，至十五日覆月都盡，是名黑半；日在月前行，至十五日具足圓滿，是名白半。(「都盡」一作「都虧」。)","sortOrder":23},
  {"id":"s_work_dtbt_64_24","chapterId":"ch_work_dtbt_64","text":"月雙閏雙","sortOrder":24},
  {"id":"s_work_dtbt_64_25","chapterId":"ch_work_dtbt_64","text":"十五夜為半月，兩半月為一月，三月為一時，兩時為一行，兩行為一年，二年半為一雙。此由閏，故以閏月兼本月，此謂月雙，非閏雙也，以五年再閏為閏雙。","sortOrder":25},
  {"id":"s_work_dtbt_64_26","chapterId":"ch_work_dtbt_64","text":"踰繕那一由旬","sortOrder":26},
  {"id":"s_work_dtbt_64_27","chapterId":"ch_work_dtbt_64","text":"數量之稱，謂踰繕那，四十里也。毗曇論四肘為一弓，五百弓為一拘盧舍，八拘盧舍為一由旬，一弓長八尺，五百弓長四百丈，一拘盧舍有二里，十六里為一由旬。","sortOrder":27},
  {"id":"s_work_dtbt_64_28","chapterId":"ch_work_dtbt_64","text":"七極微塵","sortOrder":28},
  {"id":"s_work_dtbt_64_29","chapterId":"ch_work_dtbt_64","text":"七極微塵成一阿耨池上塵，七阿耨塵為銅上塵，七銅上塵為水上塵，七水上塵為兔毫上塵，七兔毫上塵為一羊毛上塵，七羊毛上塵為一牛毛上塵，七牛毛上塵成一嚮遊塵，七嚮遊塵成一蟣，七蟣成一蝨，七蝨成一穔麥，七穔麥為一指，二十四指為一肘，四肘為一弓。","sortOrder":29},
  {"id":"s_work_dtbt_64_30","chapterId":"ch_work_dtbt_64","text":"宰相贈本生父母官","sortOrder":30},
  {"id":"s_work_dtbt_64_31","chapterId":"ch_work_dtbt_64","text":"封贈先世，自晉、宋以來有之，迨唐始備，然率不過一代，其恩延及祖廟者絕鮮，亦未嘗至極品。郭汾陽二十四考中書令，而其父贈止太保；權德輿位宰相，其祖贈止郎中。唐末五季，宰輔貴臣，始追榮三代，國朝因之。李文正公昉本工部郎中超之子，出繼從叔紹。昉再入相，表其事求贈所生父、祖官封，詔贈祖溫太子太保，祖母權氏莒國太夫人，父超太子太師，母謝氏鄭國太夫人。可謂異數，後不聞繼之者。","sortOrder":31},
  {"id":"s_work_dtbt_64_32","chapterId":"ch_work_dtbt_64","text":"執政贈三代不同","sortOrder":32},
  {"id":"s_work_dtbt_64_33","chapterId":"ch_work_dtbt_64","text":"文臣封贈三代，自初除執政外，凡轉廳皆不再該，唯知樞密院及拜相乃復得之。然舊法又不如是。歐陽公作程文簡公琳父神道碑，歷敍恩典曰：「琳參知政事，贈為太子少師。在政事遷左丞，(係轉一官。)又贈太子太師。罷為資政殿學士，又贈太師、中書令。為宣徽北院使，又贈兼尚書令。」則是轉官與罷政亦褒贈，而自宮師得太師中令，更為超越。它或不然。","sortOrder":33},
  {"id":"s_work_dtbt_64_34","chapterId":"ch_work_dtbt_64","text":"唐孫處約事","sortOrder":34},
  {"id":"s_work_dtbt_64_35","chapterId":"ch_work_dtbt_64","text":"新唐書來濟傳雲：「初，濟與高智周、郝處俊、孫處約客宣城石仲覽家，仲覽衍於財，有器識，待四人甚厚。私相與言志。處俊曰：『願宰天下。』濟及智周亦然。處約曰：『宰相或不可冀，願為通事舍人足矣。』後濟領吏部，處約始以瀛州書佐入調，濟遽註曰：『如志。』遂以為通事舍人。後皆至公輔。」高智周傳雲：「智周始與郝處俊、來濟、孫處約共依江都石仲覽。仲覽傾產結四人歡，因請各語所期。處俊曰：『丈夫惟無仕，仕至宰相乃可。』智周、濟如之。處約曰：『得為舍人，在殿中周旋吐納可也。』後濟居吏部，處約以瀛州參軍入調，濟曰：『如志。』擬通事舍人。畢，降階勞問平生。」案兩傳相去才一卷，不應重複如此，可謂冗長。本出韓琬所撰御史臺記，而所載自不實。處約傳：「貞觀中，為齊王祐記室。祐多過失，數上書切諫。王誅，太宗得其書，擢中書舍人。」是歲十七年癸卯。來濟次年亦為中書舍人，永徽三年拜相，六年檢校吏部尚書，是歲丁巳，去癸卯首尾十五歲。若如兩傳所書，大為不合，韓琬之說誠謬，史氏又失於不考。仲覽鄉里，一以為宣城，一以為江都，豈宣城人而家於廣陵也？","sortOrder":35},
  {"id":"s_work_dtbt_64_36","chapterId":"ch_work_dtbt_64","text":"夏侯勝京房兩傳","sortOrder":36},
  {"id":"s_work_dtbt_64_37","chapterId":"ch_work_dtbt_64","text":"漢書儒林傳，欲詳記經學師承，故序列唯謹，然夏侯勝、京房，又自有傳。儒林雲：「勝其先夏侯都尉，以尚書傳族子始昌。始昌傳勝，勝又事同郡簡卿。傳兄子建，建又事歐陽高。」而本傳又雲：「從始昌受尚書。後事簡卿，又從歐陽氏。從子建，師事勝及歐陽高。」儒林言：「房受易梁人焦延壽。以明災異得幸，為石顯所譖，誅。」凡百餘字，而本傳又雲：「治易，事梁人焦延壽。其說長於災變，房用之尤精。為石顯告非謗政治，誅。」此兩者近於重複也。若其它張禹、彭宣、王駿、倪寬、龔勝、鮑宣、周堪、孔光、李尋、韋賢、玄成、薛廣德、師丹、王吉、蔡誼、董仲舒、眭孟、貢禹、疏廣、馬宮、翟方進諸人，但志姓名及所師耳。","sortOrder":37},
  {"id":"s_work_dtbt_64_38","chapterId":"ch_work_dtbt_64","text":"漢人坐語言獲罪","sortOrder":38},
  {"id":"s_work_dtbt_64_39","chapterId":"ch_work_dtbt_64","text":"漢昭帝時，有大石自立，僵柳復起。眭孟上書，言：「有從匹夫為天子，宜求索賢人，禪以帝位而退，自封百里。」霍光惡之，論以祅言惑衆伏誅。案孟之妄發，其死宜矣。宣帝信任宦官，蓋寬饒奏封事，言：「五帝官天下，三王家天下。家以傳子，官以傳賢。」執金吾議以指意欲求禪，亦坐死。考其所引，亦不為無罪。楊惲之報孫會宗書，初無甚怨怒之語，其詩曰：「田彼南山，蕪穢不治，種一頃豆，落而為萁。」張晏釋以為言朝廷荒亂，百官諂諛。可謂穿鑿。而廷尉當以大逆無道，刑及妻子。予熟味其詞，獨有所謂「君父至尊親，送其終也，有時而既」。蓋宣帝惡其君喪送終之喻耳。嚴助論汲黯輔少主守成，武帝不怒，實係於一時禍福雲。賈誼、劉向談說痛切無忌諱，文、成二帝未嘗問焉，隨筆紀之矣。","sortOrder":39},
  {"id":"s_work_dtbt_64_40","chapterId":"ch_work_dtbt_64","text":"樞密書史","sortOrder":40},
  {"id":"s_work_dtbt_64_41","chapterId":"ch_work_dtbt_64","text":"景德四年，命宰臣王旦監修兩朝正史；知樞密院王欽若、陳堯叟，參知政事趙安仁並修國史。後來執政入樞府，皆不得提舉修書，非故事也。","sortOrder":41},
  {"id":"s_work_dtbt_64_42","chapterId":"ch_work_dtbt_64","text":"知州轉運使為通判","sortOrder":42},
  {"id":"s_work_dtbt_64_43","chapterId":"ch_work_dtbt_64","text":"今世士大夫既貴不可復賤。淳化中，北戎入寇，以殿前都虞候曹璨知定州，時趙安易官宗正少卿，以知州遂就徙通判。同時有羅延吉者，既知彭、祁、絳三州，而除通判廣州；滕中正知興元府而通判河南。袁郭知楚、鄆二州，會秦王廷美遷置房州，詔崇儀副使閻彥進知州，而以郭通判州事。范正辭既知戎、淄二州，而通判棣、深。又陳若拙歷知單州、殿中侍御史、西川轉運使，召歸，會李至守洛都，表為通判；久之，柴禹錫鎮涇州，復表為通判。連下遷而皆非貶降，近不復有矣。","sortOrder":43},
  {"id":"s_work_dtbt_64_44","chapterId":"ch_work_dtbt_64","text":"范正辭治饒州","sortOrder":44},
  {"id":"s_work_dtbt_64_45","chapterId":"ch_work_dtbt_64","text":"范正辭太平興國中，以饒州多滯訟，選知州事。至則宿繫皆決遣之，胥史坐淹獄停職者六十三人。會詔令料州兵送京，有王興者，懷土憚行，以刃故傷其足，正辭斬之。興妻上訴，太宗召見正辭，庭辯其事。正辭曰：「東南諸郡，饒實繁盛，人心易動，興敢扇搖。苟失控馭，則臣無待罪之地矣。」上壯其敢斷，特遷官，充江南轉運副使。饒州民甘紹者，為羣盜所掠，州捕繫十四人，獄具將死。正辭案部至，引問之，囚皆泣下。察其非實，命徙他所訊鞫。既而民有告盜所在者，正辭潛召監軍掩捕之。盜覺遁去，正辭即單騎出郭二十里追及之。賊控絃持來逼，正辭大呼，以鞭擊之，中賊雙目，仆之。餘賊渡江散走。被傷者尚有餘息，旁得所棄贓，按其奸狀伏法，十四人皆得釋。此吾鄉里事，而郡人多不聞之。","sortOrder":45},
  {"id":"s_work_dtbt_64_46","chapterId":"ch_work_dtbt_64","text":"榮王藏書","sortOrder":46},
  {"id":"s_work_dtbt_64_47","chapterId":"ch_work_dtbt_64","text":"濮安懿王之子宗綽，蓄書七萬卷。始與英宗偕學於邸，每得異書，必轉以相付。宗綽家本有「嶽陽」記者，皆所賜也，此國史本傳所載。宣和中，其子淮安郡王仲糜進目錄三卷，忠宣公在燕得其中袟，雲：「除監本外，寫本、印本書籍計二萬二千八百三十六卷。」觀一袟之目如是，所謂七萬卷者為不誣矣。三館祕府所未有也，盛哉！","sortOrder":47},
  {"id":"s_work_dtbt_64_48","chapterId":"ch_work_dtbt_64","text":"秦杜八六子","sortOrder":48},
  {"id":"s_work_dtbt_64_49","chapterId":"ch_work_dtbt_64","text":"秦少遊八六子詞雲：「片片飛花弄晚，濛濛殘雨籠晴。正銷凝，黃鸝又啼數聲。」語句清峭，為名流推激。予家舊有建本蘭畹曲集，載杜牧之一詞，但記其末句雲：「正銷魂，梧桐又移翠陰。」秦公蓋效之，似差不及也。","sortOrder":49},
  {"id":"s_work_dtbt_65_1","chapterId":"ch_work_dtbt_65","text":"卷第十四(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_65_2","chapterId":"ch_work_dtbt_65","text":"祖宗親小事","sortOrder":2},
  {"id":"s_work_dtbt_65_3","chapterId":"ch_work_dtbt_65","text":"太宗朝，呂端自諫議大夫、開封判官左遷衞尉少卿。時羣官有負宿譴者，率置散秩，會置考課院，每引對，多泣涕，以不免飢寒為請。至端，即前奏曰：「臣罪大而幸深，苟得潁州副使，臣之願也。」上曰：「朕自知卿。」無何，復舊官。逾月，拜參知政事。上留意金穀之務，一日盡召三司吏李溥等對於崇政殿，詢以計司利害。溥等願給筆札，於是二十七人共上七十一事。詔以四十四事付有司奉行，十九事下鹽鐵使陳恕等，議其可否，遣知雜御史監議，賜溥等白金緡錢，悉補侍禁、殿直，領其職。謂宰相曰：「溥等條奏事，亦頗有所長。朕嘗語恕等，若文章稽古，此輩固不可望卿，錢穀利病，彼自幼至長寢處其中，必周知根本。卿但假以顏色，引令剖陳，必有所益。」恕不肯降意詢問，旋以職事曠廢，上召而責之，始頓首謝。王賓以供奉官充亳州監軍，妻極妬悍。時監軍不許挈家至任所，妻擅至亳州，賓具以白上。上召見其妻詰責，俾衞士交捽之，杖一百，配為忠靖卒妻，一夕死。陳州民張矩，殺里中王裕家兩人，知州田錫未嘗慮問，又詣闕訴寃。遣二朝士鞫之，皆雲：「非矩所殺。」裕家寃甚，其子福應募為軍，因得見，曰：「臣非欲隸軍，蓋家寃求訴耳！」太宗怒，付御史府治之，置矩於法，二朝士皆坐貶，錫洎通判郭渭，謫為海、郢州團練副使。饒州卒妻訴理夫死，至召知州范正辭庭辯。且夫引見散秩庶僚，而容其各各有請；三司胥吏而引對正殿，命以官爵，聽其所陳；一州都監而得自上奏，至召其妻責辱之；一卒應募，而得入見，遂伸家寃，為貶責吏。萬幾如是，安得不理？今之言典故者，蓋未能盡雲。","sortOrder":3},
  {"id":"s_work_dtbt_65_4","chapterId":"ch_work_dtbt_65","text":"王居正封駁","sortOrder":4},
  {"id":"s_work_dtbt_65_5","chapterId":"ch_work_dtbt_65","text":"紹興五、六年間，王居正為給事中，時王繼先方以醫進，中旨以其壻添監浙江稅務，錄黃過門下，居正封還。高宗批三省將上，及二相進呈，聖訓雲：「卿等亦嘗用醫者否？」對曰：「皆用之。」曰：「所酬如何？」曰：「或與酒，或與錢，或與縑帛，隨大小效驗以答其勞。」上曰：「然則朕宮中用醫，反不得酬謝邪？文字未欲再付出，可以喻居正使之書讀。」丞相退，即語居正曰：「聖意如此，是事亦甚小，給事不必固執。」居正唯唯，遂請對，上語如前，而玉色頗厲。居正對曰：「臣庶之家，待此輩與朝廷有異，量功隨力，各致陳謝之禮。若朝廷則不然，繼先之徒，以技術庸流，享官榮，受祿俸，果為何事哉？一或失職，重則有刑，輕則斥逐。使其應奉有效，僅能塞責而已，想金帛之賜，固自不少。至於無故增創員闕，誠為未善，臣不願陛下輒起此門。」上悟曰：「卿言是也。」即日下其奏，前降指揮更不施行。居正之直諒有守，高宗之聽言納諫，史錄中恐不備載，故敬書之。邁頃聞之於張九成。","sortOrder":5},
  {"id":"s_work_dtbt_65_6","chapterId":"ch_work_dtbt_65","text":"王元之論官冗","sortOrder":6},
  {"id":"s_work_dtbt_65_7","chapterId":"ch_work_dtbt_65","text":"省官之說，昔人論之多矣，唯王元之兩疏，最為切當。其一雲：「臣舊知蘇州長洲縣，自錢氏納土以來，朝廷命官，七年無縣尉，使主簿兼領之，未嘗闕事。三年增置尉，未嘗立一功。以臣詳之，天下大率如是。誠能省官三千員，減俸數千萬，以供邊備，寬民賦，亦大利也。」其二雲：「開寶中，設官至少，臣占籍濟上，未及第時，止有刺史一人，李謙溥是也，司戶一人，孫賁是也。近及一年，朝廷別不除吏。自後有團練推官一人，畢士安是也。太平興國中，臣及第歸鄉，有刺史、通判、副使、判官、推官、監軍，監酒榷稅算又增四員，曹官之外更益司理。問其租稅，減於曩日也，問其人民，逃於昔時也，一州既爾，天下可知。冗兵耗於上，冗吏耗於下，此所以盡取山澤之利而不能足也。」觀此二說，以今言之，何止於可為長太息哉！","sortOrder":7},
  {"id":"s_work_dtbt_65_8","chapterId":"ch_work_dtbt_65","text":"梁狀元八十二歲","sortOrder":8},
  {"id":"s_work_dtbt_65_9","chapterId":"ch_work_dtbt_65","text":"陳正敏遁齋閒覽：「梁灝八十二歲，雍熙二年狀元及第。其謝啟雲：『白首窮經，少伏生之八歲；青雲得路，多太公之二年。』後終祕書監，卒年九十餘。」此語既著，士大夫亦以為口實。予以國史考之，梁公字太素，雍熙二年，廷試甲科，景德元年，以翰林學士知開封府，暴疾卒，年四十二。子固亦進士甲科，至直史館，卒年三十三。史臣謂：「梁方當委遇，中途夭謝。」又雲：「梁之秀穎，中道而摧。」明白如此，遁齋之妄不待攻也。","sortOrder":9},
  {"id":"s_work_dtbt_65_10","chapterId":"ch_work_dtbt_65","text":"太宗恤民","sortOrder":10},
  {"id":"s_work_dtbt_65_11","chapterId":"ch_work_dtbt_65","text":"曾致堯為兩浙轉運使，嘗上言：「去歲所部秋租，惟湖州一郡督納及期，而蘇、常、潤三州，悉有逋負，請各按賞罰。」太宗以江、淮頻年水災，蘇、常特甚。致堯所言，刻薄不可行，因詔戒之，使倍加安撫，勿得騷擾。是事必已編入三朝寶訓中，此國史本傳所載也。","sortOrder":11},
  {"id":"s_work_dtbt_65_12","chapterId":"ch_work_dtbt_65","text":"潘遊洪沈","sortOrder":12},
  {"id":"s_work_dtbt_65_13","chapterId":"ch_work_dtbt_65","text":"紹興十三年，敕令所進書刪定官五員，皆自選人改秩。潘良能季成、遊操存誠、沈介德和伯、兄景伯，皆拜祕書省正字，張表臣正民以無出身，除司農丞，四正字同日赴館供職。少監秦伯陽於會食之次，謂坐客言，一旦增四同舍，而姓皆從水傍，熺有一句，願諸君為對之，以成三館異日佳話，即雲：「潘遊洪沈泛瀛洲。」坐客合詞賞嘆，竟無有能對者。予因記筆談所載，元厚之絳少時，曾夢人告之曰：「異日當為翰林學士，須兄弟數人同在禁林。」厚之自思，素無兄弟，疑為不然。及熙寧中除學士，同時相先後入院者，韓維持國、陳繹和叔、鄧綰文約、楊繪元素，名皆從糸，始悟兄弟之說。欲用「絳繹繪維綰綸綍」為對，然未暇考之史錄，歲月果同否也。","sortOrder":13},
  {"id":"s_work_dtbt_65_14","chapterId":"ch_work_dtbt_65","text":"舞鷗遊蜻","sortOrder":14},
  {"id":"s_work_dtbt_65_15","chapterId":"ch_work_dtbt_65","text":"戰國時，諸子百家之書，所載絕有同者。列子黃帝篇雲：「海上之人有好漚(音鷗。)鳥者，每旦之海上從漚鳥遊，漚鳥之至者百數而不止。其父曰：『吾聞漚鳥皆從汝遊，汝取來吾玩之。』明日之海上，漚鳥舞而不下也。」呂覽精喻篇雲：「海上人有好蜻(蜻蜓也。)者，每朝居海上從蜻遊，蜻之至者百數而不止，前後左右盡蜻也，終日玩之而不去。其父告之曰：『聞蜻皆從汝居，取而來，吾將玩之。』明日之海上，蜻無至者矣。」此二說如出一手也。","sortOrder":15},
  {"id":"s_work_dtbt_65_16","chapterId":"ch_work_dtbt_65","text":"郎中用資序","sortOrder":16},
  {"id":"s_work_dtbt_65_17","chapterId":"ch_work_dtbt_65","text":"國朝官製既行，除用職事官，不問資序高下，但隨階品，而加行、守、試以賦祿，郎中、員外郎亦自為兩等，頗因履歷而授之。後來相承，必欲已關升知州資序者為郎中，於是拜員外郎者具改官後實歷歲月申吏部，不以若幹任，但通理細滿八考則升知州，乃正作郎中，別命詞給告。頃嘗有旨，初除郎官者，雖資歷已高，且為員外，候吏部再申，然後升作郎中。近歲掌故失之，故李大性自浙東提刑除吏部，時佐自大理正除刑部，徐門元自大府丞除都官，嶽震自將作少監除度支，其告內即雲郎中，與元指揮戾矣。","sortOrder":17},
  {"id":"s_work_dtbt_65_18","chapterId":"ch_work_dtbt_65","text":"臺諫分職","sortOrder":18},
  {"id":"s_work_dtbt_65_19","chapterId":"ch_work_dtbt_65","text":"臺、諫不相見，已書於續筆中，其分職不同，各自有故實。元豐中，趙彥若為諫議大夫，論大臣不以道德承聖化，而專任小數，與羣有司較計短長，失具瞻體。因言門下侍郎章子厚、左丞王安禮，不宜處位。神宗以彥若侵御史論事，左轉祕書監。蓋許其論議，而責其彈擊為非也。元祐初，孫覺為諫議大夫，是時諫官、御史論事有分限，毋得越職。覺請申唐六典及天禧詔書，凡發令造事之未便，皆得奏陳。然國史所載，御史掌糾察官邪，肅正綱紀；諫官掌規諫諷諭，凡朝政闕失，大臣至百官，任非其人，三省至百司，事有失當，皆得諫正。則蓋許之矣。唐人朝製，大率重諫官而薄御史。中丞溫造道遇左補闕李虞，恚不避，捕從者笞辱。左拾遺舒元褒等建言：「故事，供奉官惟宰相外無屈避，造棄蔑典禮，辱天子侍臣。遺、補雖卑，侍臣也；中丞雖高，法吏也。侍臣見陵，法吏自恣，請得論罪。」乃詔臺官、供奉官共道路，聽先後行，相值則揖。然則居此二雄職者，在唐日了不相謀雲。","sortOrder":19},
  {"id":"s_work_dtbt_65_20","chapterId":"ch_work_dtbt_65","text":"貞元朝士","sortOrder":20},
  {"id":"s_work_dtbt_65_21","chapterId":"ch_work_dtbt_65","text":"劉禹錫聽舊宮人穆氏唱歌一詩雲：「曾陪織女度天河，記得雲間第一歌。休唱貞元供奉曲，當時朝士已無多。」劉在貞元任郎官、御史，後二紀方再入朝，故有是語。汪藻始采用之，其宣州謝上表雲：「新建武之官儀，不圖重見；數貞元之朝士，今已無多。」汪在宣和間為館職符寶郎，是時，紹興十三、四年中，其用事可謂精切。邁嘗四用之，謝侍講修史表雲：「下建武之詔書，正爾恢張於治具；數貞元之朝士，獨憐流落之孤蹤。」以德壽慶典，曾任兩省官者遷秩，蒙轉通奉大夫，謝表雲：「供奉當時，敢齒貞元之朝士；頌歌大業，願賡至德之中興。」充永思陵橋道頓遞使，轉宣奉大夫，謝表雲：「武德文階，愧三品維新之澤；貞元朝士，動一時既往之悲。」主上即位，明堂禮成，謝加恩雲：「考皇祐明堂之故，操以舉行；念貞元朝士之存，今其餘幾。」亦各隨事引用。近者單夔以知紹興府進文華閣直學士，謝表雲：「數甘泉法從之舊，真貞元朝士之餘。」夔當淳熙中雖為侍郎，然一朝名臣尚多，又距今才十餘歲，似為未穩貼也。","sortOrder":21},
  {"id":"s_work_dtbt_65_22","chapterId":"ch_work_dtbt_65","text":"表章用兩臣字對","sortOrder":22},
  {"id":"s_work_dtbt_65_23","chapterId":"ch_work_dtbt_65","text":"表章自敍以兩「臣」字對說，由東坡至汪浮溪多用之。然須要審度君臣之間情義厚薄，及姓名眷顧於君前如何，乃為合宜。坡湖州謝表雲：「知臣愚不適時，難以追陪新進；察臣老不生事，或能牧養小民。」登州表雲：「於其黨而觀過，謂臣或出於愛君；就所短以求長，知臣稍習於治郡。」侍讀謝表雲：「謂臣雖無大過人之才，知臣粗有不欺君之實，欲使朝夕與於討論。」潁州表雲：「意其忠義許國，故暫召還；察其老病畏人，復許補外。」汪謝徽州雲：「謂臣不改歲寒，故起之散地；察臣素推月旦，故付以本州。」為陸藻謝給事中雲：「知臣椎鈍無他，故長奉賢王之學；憫臣踐揚滋久，故亟升法從之班。」為汪樞密謝子自虜中歸不令入城降詔獎諭表雲：「知臣齒髮已凋，常恐鄧攸之無後；憐臣肺肝可見，有如去病之辭家。」凡此所言，皆可自表於君前者。劉夢得代竇羣容州表，有「察臣前任事實，恕臣本性樸愚」之句，坡公蓋本諸此。近年後生假倩作文，不識事體，至有碌碌常流，乍得一壘，亦輒雲知臣察臣之類，真可笑也。","sortOrder":23},
  {"id":"s_work_dtbt_65_24","chapterId":"ch_work_dtbt_65","text":"劉夢得謝上表","sortOrder":24},
  {"id":"s_work_dtbt_65_25","chapterId":"ch_work_dtbt_65","text":"郡守謝上表，首必雲：「伏奉告命授臣某州，已於某月某日到任上訖。」然後入詞。獨劉夢得數表不然，和州者曰：「伏奉去年六月二十五日製書，授臣使持節和州諸軍事，守和州刺史。臣自理巴、賨，不聞善最，恩私忽降，慶抃失容。臣某(中謝。)伏惟皇帝陛下丕承寶祚，光闡鴻猷，有漢武天人之姿，稟周成叡哲之德。發言合古，舉意通神，委用得人，動植鹹悅，理平之速，從古無倫。微臣何幸，獲睹昌運。臣業在辭學，早歲策名。德宗尚文，擢為御史。出入中外，歷事五朝，累承恩光，三換符竹。分憂之寄，祿秩非輕，而素蓄所長，效用無日。臣聞一物失所，前王軫懷，今逢聖朝，豈患無位。臣即以今月二十六日到所任上訖。伏以地在江、淮，俗參吳、楚，災旱之後，綏撫誠難。謹當奉宣皇風，慰彼黎庶，久於其道，冀使知方。伏乞聖慈俯賜昭鑒。」首尾敍述皆與他人表不同。其夔州、汝州、同州、蘇州，諸篇一體。邁長子木莘常稱誦之。及為太平州，遂擬其體，代作一表。其詞雲：「臣邁言：伏奉今年九月十七日製書，授臣知太平州者。一麾出守，方切兢危，三命滋共，弗容控避。仰皇天之大造，扣丹地以何言！(中謝。)恭惟皇帝陛下叡知有臨，神武不殺，慕舜之孝，見堯於牆，德冠古今而獨尊，仁並清寧而遍覆。明見萬里，將大混於車書；子來庶民，更精求於嶽牧。臣家本儒素，時無令名，濫竽宏博之科，稅駕清華之地，瀛山抱槧，郎省握蘭。在紹興之季年，汚記註於右史。龍飛應運，鳳歷紀祥，不遺細微，兼取愚鈍，遂以詞賦之職，獲侍清閒之歡。雖宿命應仙，許暫來於天上，而塵心未斷，旋即墮於人間。一去十八年之中，三叨二千石之寄，末繇金華郡，還紬石室書，從珍臺閒館之遊，勸廣廈細旃之講。真拜學士，號名私人，受九重知己之殊，極三入承明之幸，使與大議，不專斯文。而臣弱羽不足以當雄風，蹇步不足以勝重任。上恩惜其終棄，左符寵其餘生。李廣數奇，徒羨侯於校尉；汲黯妄發，敢嘆薄於淮陽。臣即以今月二十八日到任上訖。伏以郡在江東，昔稱道院；地鄰淮右，今謂壯藩。謹當宣布恩威，奉行寬大，求民之瘼，問俗所宜。緩帶輕裘，雖弗賢長城於李勣；清心省事，敢不避正堂於蓋公。庶幾固結本根，少復報酬知遇。」全規模其步驟，然視昔所作，猶覺語煩。","sortOrder":25},
  {"id":"s_work_dtbt_65_26","chapterId":"ch_work_dtbt_65","text":"陳簡齋葆真詩","sortOrder":26},
  {"id":"s_work_dtbt_65_27","chapterId":"ch_work_dtbt_65","text":"自崇寧以來，時相不許士大夫讀史作詩，何清源至於修入令式，本意但欲崇尚經學，痛沮詩賦耳，於是庠序之間以詩為諱。政和後稍復為之，而陳去非遂以墨梅絕句擢置館閣。嘗以夏日偕五同舍集葆真宮池上避暑，取「綠陰生晝靜」分韻賦詩，陳得「靜」字。其詞曰：「清池不受暑，幽討起予病。長安車轍邊，有此萬荷柄。是身唯可懶，共寄無盡興。魚遊水底涼，鳥語林間靜。談餘日亭午，樹影一時正。清風不負客，意重百金贈。聊將兩鬢蓬，起照千丈鏡。微波喜搖人，小立待其定。梁王今何許，柳色幾衰盛。人生行樂耳，詩律已其剩。邂逅一尊酒，它年五君詠。重期踏月來，夜半嘯煙艇。」詩成出示坐上，皆詫為擅場。朱新仲時親見之，雲京師無人不傳寫也。","sortOrder":27},
  {"id":"s_work_dtbt_65_28","chapterId":"ch_work_dtbt_65","text":"仙傳圖志荒唐","sortOrder":28},
  {"id":"s_work_dtbt_65_29","chapterId":"ch_work_dtbt_65","text":"昔人所作神仙傳之類，大抵荒唐謬悠，殊不能略考引史策。如衞叔卿事雲：「漢儀鳳二年，孝武皇帝閒居殿上而見之。」月支使者事雲：「延和三年，武帝幸安定，而月支國遣使獻香。」案儀鳳乃唐高宗紀年名，延和乃魏太武、唐睿宗紀年名，而誕妄若是。自餘山經地志，往往皆然。近世士大夫采一方傳記及故老談說，競為圖志，用心甚專，用力甚博，亦不能免牴牾。高夔守襄陽，命僚屬作一書，其敍歷代沿革雲：「在周為楚、鄧、鄾諸國。」據左傳，鄾乃鄧邑，後巴人伐楚圍鄾，蓋楚滅鄧，故亦來屬，元非列國也。又引左傳蔓成然事，以蔓為國。據成然乃楚大夫，靈王奪其邑，無所謂「蔓國」也。","sortOrder":29},
  {"id":"s_work_dtbt_66_1","chapterId":"ch_work_dtbt_66","text":"卷第十五(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_66_2","chapterId":"ch_work_dtbt_66","text":"徽廟朝宰輔","sortOrder":2},
  {"id":"s_work_dtbt_66_3","chapterId":"ch_work_dtbt_66","text":"蔡京擅國命，首尾二十餘年，一時士大夫未有不因之以至大用者，其後頗採公議，與為異同。若宰相則趙清憲挺之、張無盡商英、鄭華原居中、劉文憲正夫，所行所言，世多知之。其居執政位者，如張康國賓老、溫益禹弼、劉逵公路、侯蒙元功者，皆有可錄。康國定元祐黨籍，看詳講議司編彙奏牘，皆深預密議，及後知樞密院，始浸為崖異。徽宗察京專愎，陰令狙伺其奸，蓋嘗許以相。是時，西北邊帥，多取部內好官自辟置，以力不以才。康國曰：「並塞當擇人以紓憂，顧奈何欲私所善乎？」乃隨闕選用，定為格。京使御史中丞吳執中擊之，康國先知之，具以奏。益鎮潭州，凡元祐逐臣在湖南者，悉遭侵困，因愛莫助之圖遂為京用。至中書侍郎，乃時有立異。京一日除監司郡守十人，將進畫，益判其後曰：「收。」京使益所厚中書舍人鄭居中問之，益曰：「君在西掖，每見所論事，舍人得舉職，侍郎顧不許邪？今丞相所擬十人，共皆姻黨耳，欲不逆其意，得乎？」逵以附京至中書侍郎。京去相，逵首勸上碎元祐黨碑，寬上書邪籍之禁，凡京所行悖理殃民事，稍稍釐正之。蒙在政地，上從容問蔡京何如人，對曰：「使京能正其心術，雖古賢相何以加？」上頷首，且使密伺京所為，京聞而銜之。凡此數端，皆見於國史本傳。","sortOrder":3},
  {"id":"s_work_dtbt_66_4","chapterId":"ch_work_dtbt_66","text":"教官掌牋奏","sortOrder":4},
  {"id":"s_work_dtbt_66_5","chapterId":"ch_work_dtbt_66","text":"所在州郡，相承以表奏書啟委教授，因而餉以錢酒。予官福州，但為撰公家謝表及祈謝晴雨文，至私禮牋啟小簡皆不作。然遇聖節樂語嘗為之，因又作他用者三兩篇，每以自愧。鄒忠公為潁昌教授，府守范忠宣公屬撰興龍節致語，辭不為。范公曰：「翰林學士亦作此。」忠公曰：「翰林學士則可，祭酒、司業則不可。」范公敬謝之。前輩風節，可畏可仰如此。","sortOrder":5},
  {"id":"s_work_dtbt_66_6","chapterId":"ch_work_dtbt_66","text":"經句全文對","sortOrder":6},
  {"id":"s_work_dtbt_66_7","chapterId":"ch_work_dtbt_66","text":"予初登詞科，再至臨安，寓於三橋西沈亮功主簿之館，沈以予買飯於外，謂為不便，自取家饌日相供。同年湯丞相來訪，扣旅食大概，具為言之。湯公笑曰：「主人亦賢矣！」因戲出一語曰：「哀王孫而進食，豈望報乎？」良久，予應之曰：「為長者而折枝，非不能也。」公大激賞而去。汪聖錫為祕書少監，每食罷會茶，一同舍輒就枕不至。及起，亦戲之曰：「宰予晝寢，於予與何誅。」衆未有言，汪曰：「有一對，雖於今事不切，然漤是一箇出處。」雲：「子貢方人，夫我則不暇。」同舍皆合詞稱美。","sortOrder":7},
  {"id":"s_work_dtbt_66_8","chapterId":"ch_work_dtbt_66","text":"北郊議論","sortOrder":8},
  {"id":"s_work_dtbt_66_9","chapterId":"ch_work_dtbt_66","text":"三代之禮，冬至祀天於南郊，夏至祭地於北郊。王莽於元始中改為合祭，自是以來，不可復變。元豐中，下詔欲復北郊，至六年，唯以冬至祀天，而地祇不及事。元祐七年，又使博議，而許將、顧臨、范純禮、王欽臣、孔武仲、杜純各為一說。逮蘇軾之論出，於是髃議盡廢。當時諸人之說有六：一曰，今之寒暑與古無異，宣王六月出師，則夏至之日，何為不可祭；二曰，夏至不能行禮，則遣官攝行，亦有故事；三曰，省去繁文末節，則一歲可以再郊；四曰，三年一祀天，又一年一祭地；五曰，當郊之歲，以十月神州之祭，易夏至之方澤，可以免方暑舉事之患；六曰，當郊之歲，以夏至祀地祇於方澤，上不親郊，而通爟火於禁中望祀。軾皆辟之，以謂無一可行之理，其文載於奏議，凡三千言。元符中，又詔議合祭，論者不一，唯太常少卿宇文昌齡之議，最為簡要。曰：「天地之勢，以高卑則異位，以禮製則異宜，以樂則異數。至於衣服之章，器用之具，日至之時，皆有辨而不亂。夫祀者，自有以感於無，自實以通於虛，必以類應類，以氣合氣，然後可以得而親，可以冀其格。今祭地於圜丘，以氣則非所合，以類則非所應，而求高厚之來享，不亦難乎？」後竟用其議。此兩說之至當如此。","sortOrder":9},
  {"id":"s_work_dtbt_66_10","chapterId":"ch_work_dtbt_66","text":"討論濫賞詞","sortOrder":10},
  {"id":"s_work_dtbt_66_11","chapterId":"ch_work_dtbt_66","text":"東坡公行香子小詞雲：「清夜無塵，月色如銀。酒斟時，須滿十分。浮名浮利，休苦勞神。嘆隙中駒，石中火，夢中身。雖抱文章，開口誰親？且陶陶，樂盡天真。不如歸去，作箇閒人。對一張琴，一壺酒，一溪雲。」紹興初，范覺民為相，以自崇寧以來，創立法度，例有泛賞，如學校，茶鹽，錢幣，保伍，農田，居養，安濟，寺觀，開封、大理獄空，四方邊事，御前、內外諸司，編敕會要、學製、禮製、道史等書局，掖庭編澤，行幸，曲恩，諸色營繕，河埽功役，採石、木栰、花石等綱，祥瑞，禮樂，兩城所公田，伎術，伶優，三山，永橋，明堂，西內，八寶，玄圭，種種濫賞，不可勝述。其曰應奉有勞、獻頌可採、職事修舉、特授特轉者，又皆無名直與，及白身補官，選人改官，職名礙格，非隨龍而依隨龍人，非戰功而依戰功人等，每事各為一項，建議討論。又行下吏部，若該載未盡名色，並合取朝廷指揮，臨時參酌。追奪事件，遂為畫一規式，有至奪十五官者。雖公論當然，而失職者胥動造謗，浮議蜂起。無名子因改坡語雲：「清要無因，舉選艱辛。繫書錢，須要十分。浮名浮利，虛苦勞神。嘆旅中愁，心中悶，部中身。雖抱文章，苦苦推尋。更休說，誰假誰真。不如歸去，作個齊民。免一回來，一回討，一回論。」至大字書寫貼於內前牆上，邏者得之以聞。是時，偽齊劉豫方盜據河南，朝論慮或搖人心，亟罷討論之舉。范公用是為臺諫所攻，今章且叟奏稿中正載彈疏，竟去相位雲。","sortOrder":11},
  {"id":"s_work_dtbt_66_12","chapterId":"ch_work_dtbt_66","text":"尺　八","sortOrder":12},
  {"id":"s_work_dtbt_66_13","chapterId":"ch_work_dtbt_66","text":"唐盧肇為歙州刺史，會客於江亭，請目前取一事為酒令，尾有樂器之名。肇令曰：「遙望漁舟，不闊尺八。」有姚巖傑者，飲酒一器，墚欄嘔噦，須臾即席，還令曰：「墚欄一吐，已覺空喉。」此語載於摭言。又逸史雲：「開元末，一狂僧往終南回向寺，一老僧令於空房內取尺八來，乃玉笛也。謂曰：『汝主在寺，以愛吹尺八，謫在人間，此常吹者也。汝當回，可將此付汝主。』僧進於玄宗，特取吹之，宛是先所御者。」孫夷中仙隱傳：「房介然善吹竹笛，名曰尺八。將死，預將管打破，告諸人曰：『可以同將就壙。』」亦謂此雲。尺八之為樂名，今不復有。呂才傳雲：「貞觀時，祖孝孫增損樂律，太宗詔侍臣舉善音者。王珪、魏徵盛稱才製尺八，凡十二枚，長短不同，與律諧契。太宗即召才參論樂事。」尺八之所出，見於此，無由曉其形製也。爾雅釋樂亦不載。","sortOrder":13},
  {"id":"s_work_dtbt_66_14","chapterId":"ch_work_dtbt_66","text":"三給事相攻","sortOrder":14},
  {"id":"s_work_dtbt_66_15","chapterId":"ch_work_dtbt_66","text":"元祐中，王欽臣仲至，自權工部侍郎除給事中，為給事姚勔所駁而止。大觀中，陳亨伯自左司員外郎擢給事中，為權官蔡薿所沮而出。政和末，伯祖仲達在東省，以疾暫謁告兩日，張天覺復官之命，過門下第四廳，給事方會論為畏繳駁之故，所以託病，遂罷知滁州。","sortOrder":15},
  {"id":"s_work_dtbt_66_16","chapterId":"ch_work_dtbt_66","text":"朱藏一詩","sortOrder":16},
  {"id":"s_work_dtbt_66_17","chapterId":"ch_work_dtbt_66","text":"政和末，老蔡以太師魯國公總治三省，年已過七十，與少宰王黼爭權相傾。朱藏一在館閣，和同舍秋夜省宿詩雲：「老火未甘退，稚金方力征。炎涼分勝負，頃刻變陰晴。」兩人門下士互興譖言，以為嘲謗。其後黼獨相，館職多遷擢，朱居官如故，而和人菊花詩雲：「紛紛桃李春，過眼成枯萎。晚榮方耐久，造物豈吾欺？」或又譖於黼以為怨憤。是時，士論指三館為鬧藍。","sortOrder":17},
  {"id":"s_work_dtbt_66_18","chapterId":"ch_work_dtbt_66","text":"蔡京輕用官職","sortOrder":18},
  {"id":"s_work_dtbt_66_19","chapterId":"ch_work_dtbt_66","text":"蔡京三入相時，除用士大夫，視官職如糞土，蓋欲以天爵市私恩。政和六年十月，不因赦令，侍從以上先緣左降同日遷職者二十人。通奉大夫張商英為觀文殿學士，中大夫王襄為延康殿學士，顯謨閣待製李圖南為述古殿學士，寶文閣待製蔡薿、顯謨閣待製葉夢得並為龍圖閣直學士，寶文閣待製張近、通奉大夫錢即、右文殿修撰王漢之並為顯謨閣直學士，中大夫葉祖洽為徽猷閣直學士，朝散大夫曾孝蘊為天章閣待製，朝散郎俞（上卥下木）、朝議大夫曾孝序、中奉大夫范致明、右文殿修撰蔡肇、大中大夫孫鼛、朝議大夫王覺、右文殿修撰陳暘幷為顯謨閣待製，朝請郎蔡懋、中奉大夫龐恭孫、朝請郎洪彥昇並為徽猷閣待製。至十一月冬祀畢，大赦天下，仍復推恩。","sortOrder":19},
  {"id":"s_work_dtbt_66_20","chapterId":"ch_work_dtbt_66","text":"節度使改東宮環衛官","sortOrder":20},
  {"id":"s_work_dtbt_66_21","chapterId":"ch_work_dtbt_66","text":"太祖有天下，將收藩鎮威柄，故漸行改革。至於位至侍中、中書令、使相者，其高僅得東宮官，次但居環韂。鳳翔王晏為太子太師，安遠武行德為太子太傅，護國郭從義為左金吾上將軍，鳳翔王彥超為右金吾上將軍，定國白重贊為左千牛上將軍，保太楊廷璋為右千牛上將軍，靜難劉重進為羽林統軍。若符彥卿者，以太師中書令、天雄節度使直罷歸洛，八年不問，亦不別除官。其廟謨雄斷如是。靖康初，以戚里冒政、宣恩典，多建節鉞，乃稽用此製。錢景臻以少傅安武節度，劉宗元以開府儀同三司、鎮安節度，並為左金吾上將軍。范訥以平涼，劉敷以保信，劉敏以保成，張楙以嚮德，王舜臣以嶽陽，朱孝孫以應道，錢忱以瀘川節度，並為右金吾上將軍。自後不復舉行矣。","sortOrder":21},
  {"id":"s_work_dtbt_66_22","chapterId":"ch_work_dtbt_66","text":"宰相任怨","sortOrder":22},
  {"id":"s_work_dtbt_66_23","chapterId":"ch_work_dtbt_66","text":"宰相欲收士譽，使恩歸己，故只以除用為意，而不任職及顯有過舉者，亦不肯任怨，稍行黜徙。文惠公在相位，嘗奏言：「今之監司、郡守，其無大過者，臺諫固不論擊。但其間實有疲愞庸老之人，依阿留之，轉為民害。臣欲皆與祠祿，理作自陳，監司或就移小郡，庶幾人有家食之資，國無曠官之失。」孝宗欣然聽許。於是湖南轉運判官任詔，改知復州，廣東提舉鹽事劉景，改知南雄州。時太常丞闕，監左藏庫許子紹欲得之，公以大超越，諭使小緩。子紹宛轉愈力，乃白其事，出通判靜江府。議者私謂若如此則是廟堂而兼臺諫之職。殊不思進賢退不肖，真宰相之事耳。欲擬宮觀三四人，未暇而去位，子紹之出，遂織入言章中。近者京丞相以國子錄吳仁傑居職未久，便欲求遷，奏罷歸吏部註簽判，亦此意也。","sortOrder":23},
  {"id":"s_work_dtbt_66_24","chapterId":"ch_work_dtbt_66","text":"四李杜","sortOrder":24},
  {"id":"s_work_dtbt_66_25","chapterId":"ch_work_dtbt_66","text":"漢太尉李固、杜喬，皆以為相守正，為梁冀所殺。故掾楊生上書，乞李、杜二公骸骨，使得歸葬。梁冀之誅，權勢專歸宦官，傾動中外，白馬令李雲露布上書，有帝欲不諦之語。桓帝得奏震怒，逮雲下北寺獄。弘農五官掾杜觽，傷雲以忠諫獲罪，上書願與雲同日死。帝愈怒，下廷尉，皆死獄中。其後襄楷上言，亦稱為李、杜。靈帝再治軭黨，范滂受誅，母就與之訣，曰：「汝今與李、杜齊名，死亦何恨！」謂李膺、杜密也。李太白、杜子美同時著名，故韓退之詩雲：「李杜文章在，光燄萬丈長。」凡四李、杜雲。","sortOrder":25},
  {"id":"s_work_dtbt_66_26","chapterId":"ch_work_dtbt_66","text":"渾脫隊","sortOrder":26},
  {"id":"s_work_dtbt_66_27","chapterId":"ch_work_dtbt_66","text":"唐中宗時，清源尉呂元泰上書言時政曰：「比見坊邑相率為渾脫隊，駿馬胡服，名曰『蘇幕遮』，旗鼓相當，騰逐喧譟。以禮義之朝，法胡虜之俗，非先王之禮樂，而示則於四方。書曰：『謀時寒若。』何必臝形體、歡衢路，鼓舞跳躍而索寒焉！」書聞不報。此蓋幷論潑寒胡之戲。唐史附於宋務光傳末，元泰竟亦不顯。近世風俗相尚，不以公私宴集，皆為耍曲耍舞，如勃海樂之類，殆猶此也。","sortOrder":27},
  {"id":"s_work_dtbt_66_28","chapterId":"ch_work_dtbt_66","text":"歲陽歲名","sortOrder":28},
  {"id":"s_work_dtbt_66_29","chapterId":"ch_work_dtbt_66","text":"歲陽、歲名之說，始於爾雅。太歲在甲曰閼逢，在乙曰旃蒙，在丙曰柔兆，在丁曰彊圉，在戊曰著雍，在己曰屠維，在庚曰上章，在辛曰重光，在壬曰玄黓，在癸曰昭陽，謂之歲陽。在寅曰攝提格，在卯曰單閼，在辰曰執徐，在巳曰大荒落，在午曰敦牂，在未曰協洽，在申曰涒灘，在酉曰作噩，在戌曰閹茂，在亥曰大淵獻，在子曰困敦，在丑曰赤奮若，謂之歲名。自後唯太史公曆書用之，而或有不同。如閼逢為焉逢，旃蒙為端蒙，柔兆為遊兆，彊圉為彊梧，著雍為徒雍，屠維為祝儣，上章為商橫，重光為昭陽，玄黓為橫艾，昭陽為尚章，大荒落為大芒落，協洽為汁洽，涒灘為汭漢，作噩為作鄂，閹茂為淹茂，大淵獻、困敦更互，赤奮若乃為赤奪，若此蓋年祀久遠，傳寫或訛，不必深辨。但漢武帝太初元年太歲丁丑，而以為甲寅，其失多矣。爾雅又有月陽、月名。月在甲曰畢，在乙曰橘，在丙曰修，在丁曰圉，在戊曰厲，在己曰則，在庚曰窒，在辛曰塞，在壬曰終，在癸曰極。正月為陬，二月為如，三月為寎，四月為餘，五月為嚱，六月為且，七月為相，八月為壯，九月為玄，十月為陽，十一月為辜，十二月為涂。考之典籍，唯曆書謂太初十月為畢聚。離騷雲：「攝提貞於孟陬。」左氏傳：「十月曰良月。」國語：「至於玄月。」它未嘗稱引。郭景純註釋雲：「自歲陽至月名，皆所未詳通者，故闕而不論。」蓋不可強為之說。非若律書所言二十八舍、十母、十二子，猶得穿鑿傅致也。資治通鑑專取歲陽、歲名以冠年，不可曉解，殊不若甲子至癸亥為明白爾。韓退之詩「歲在淵獻牽牛中」，王介甫字說言「彊圉」，自餘亦無說。左傳所書「歲在星紀，而淫於玄枵」，「歲在降婁，降婁中而旦」，「歲在娵訾之口」，「歲五及鶉火」，「歲在顓帝之虛」，「歲在豕韋」，「歲在大梁」，皆用歲星次舍言之。司馬倬跋溫公潛虛，其末雲：「乾道二年，歲在柔兆閹茂、玄黓執徐月、極大淵獻日。」謂丙戌年、壬辰月、癸亥日，以歲名施於月日，尤為不然。漢章不自為文，殆是僚寀強解事者所作也。","sortOrder":29},
  {"id":"s_work_dtbt_66_30","chapterId":"ch_work_dtbt_66","text":"官稱別名","sortOrder":30},
  {"id":"s_work_dtbt_66_31","chapterId":"ch_work_dtbt_66","text":"唐人好以它名標榜官稱，今漫疏於此，以示子姪之未能盡知者。太尉為掌武，司徒為五教，司空為空土，侍中為大貂，散騎常侍為小貂，御史大夫為亞台、為亞相、為司憲，中丞為獨坐、為中憲，侍御史為端公、南黙、橫榻、雜端，又曰脆梨，殿中為副端，又曰開口椒，監察為合口椒，諫議為大坡、大諫，補闕(今司諫。)為中諫，又曰補袞，拾遺(今正言。)為小諫，又曰遺公，給事郎為夕郎、夕拜，知製誥為三字，起居郎為左螭，舍人為右螭，又並為修註，吏部尚書為大天，禮部為大儀，兵部為大戎，刑部為大秋，工部為大起，吏部郎為小選、為省眼，考功、度支為振行，禮部為小儀、為南省舍人，今曰南宮，刑部為小秋，祠部為（氵水）(柄。)廳，比部為比盤，又曰崑龏皆頭，屯田為田曹，水部為水曹，諸部郎通曰哀烏、依烏，太常卿為樂卿，少卿為少常、奉常，光祿為飽卿，鴻臚為客卿、睡卿，司農為走卿，大理為棘卿，評事為廷平，將作監為大匠，少監為少匠，祕書監為大蓬，少監為少蓬，左右司為都公，太子庶子為宮相，宰相呼為堂老，兩省相呼為閣老，尚書丞郎為曹長，御史、拾遺為院長。下至縣令曰明府，丞曰贊府、贊公，尉曰少府、少公、少仙，此已見前筆。容齋四筆","sortOrder":31},
  {"id":"s_work_dtbt_67_1","chapterId":"ch_work_dtbt_67","text":"卷第十六(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_67_2","chapterId":"ch_work_dtbt_67","text":"漢重蘇子卿","sortOrder":2},
  {"id":"s_work_dtbt_67_3","chapterId":"ch_work_dtbt_67","text":"漢世待士大夫少恩，而獨於蘇子卿加優寵，蓋以其奉使持節，褒勸忠義也。上官安謀反，武子元與之有謀，坐死。武素與上官桀、桑弘羊有舊，數為燕王所訟，子又在謀中，廷尉奏請逮捕武，霍光寢其奏。宣帝立，錄髃臣定策功，賜爵關內侯者八人，劉德、蘇武食邑。張晏曰：「舊關內侯無邑，以武守節外國，德宗室俊彥，故特令食邑。」帝閔武年老，子坐事死，問左右：「武在匈奴久，豈有子乎？」武曰：「前發匈奴時，胡婦實產一子通國，有聲問來，願因使者贖之。」上許焉。通國至，上以為郎，又以武弟子為右曹，以武著節老臣，令朝朔望，稱祭酒，甚優寵之。皇後父、帝舅、丞相、御史、將軍皆敬重武。後圖畫中興輔佐有功德知名者於麒麟閣，凡十一人，而武得預。武終於典屬國，蓋以武老不任公卿之故。先公縶留絕漠十五年，能致顯仁皇太後音書，蒙高宗皇帝有「蘇武不能過」之語。而厄於權臣，歸國僅升一職，立朝不滿三旬，訖於竄謫南荒惡地，長子停官。追誦漢史，可為痛哭者已！又案武本傳雲：「奉使初還，拜為典屬國，秩中二千石。昭帝時，免武官。後以故二千石與計謀立宣帝，賜爵。張安世薦之，即時召待詔，數進見，復為典屬國。」然則豫定策時，但以故二千石耳。而霍光傳連名奏昌邑王時，直稱典屬國，宣紀封侯亦然，恐誤也。","sortOrder":3},
  {"id":"s_work_dtbt_67_4","chapterId":"ch_work_dtbt_67","text":"昔賢為卒伍","sortOrder":4},
  {"id":"s_work_dtbt_67_5","chapterId":"ch_work_dtbt_67","text":"三代而上，文武不分，春秋列國軍將皆命卿，處則執政，出則將兵，載於詩、書、左傳，可考也。然此特謂將帥耳，乃若卒伍之賤，雖賢士亦為之，不以為異。魯哀公時，吳伐魯，次於泗上。微虎欲宵攻王舍，私屬徒七百人，三踴於幕庭，卒三百人，有若與焉。杜預雲：「卒，終也，謂於七百人中，終得三百人任行也。」或謂季孫曰：「不足以害吳，而多殺國士，不如已也。」乃止之。此蓋後世斫營刼寨之類，而有若亦為之。齊伐魯，冉求帥左師，樊遲為右，季孫曰：「須也弱。」有子曰：「就用命焉。」謂雖年少，能用命也。冉有用矛於齊師，故能入其軍。杜預雲：「言能以義勇也。」皆孔門高弟，而親卒伍之事，後世豈復有之？","sortOrder":5},
  {"id":"s_work_dtbt_67_6","chapterId":"ch_work_dtbt_67","text":"兵家貴於備豫","sortOrder":6},
  {"id":"s_work_dtbt_67_7","chapterId":"ch_work_dtbt_67","text":"晉盜盧循據廣州，以其黨徐道覆為始興相，循寇建康，以為前鋒。初，道覆遣人伐船材於南康山，至始興賤賣之，居人爭市之，船材大積，而人不疑。至是悉取以裝艦，旬日而辦。蕭衍鎮雍州，以齊室必亂，密修武備，多伐材竹，沈之檀溪，積茅如岡阜，皆不之用。中兵參軍呂僧珍覺其意，亦私具櫓數百張。衍既起兵，出竹木裝艦，葺之以茅，事皆立辦。諸將爭櫓，僧珍出先所具者，每船付二張，爭者乃息。魏太武南伐盱眙，太守沈璞以郡當衝要，乃繕城浚隍，積財穀，儲矢石，為城守之備。魏攻之，三旬不拔，燒攻具退走。古人如此者甚多，道覆雖失所從，為畔渙之歸，然其事固可稱也。","sortOrder":7},
  {"id":"s_work_dtbt_67_8","chapterId":"ch_work_dtbt_67","text":"渠陽蠻俗","sortOrder":8},
  {"id":"s_work_dtbt_67_9","chapterId":"ch_work_dtbt_67","text":"靖州之地，自熙寧九年收復唐溪洞誠州，元豐四年，仍建為誠州，元祐二年，廢為渠陽軍，又廢為寨，五年復之，崇寧二年，改為靖州。始時渠陽縣為治所，後改屬沅州而治永平，其風俗敻與中州異。蠻酋自稱曰官，謂其所部之長曰都幙，邦人稱之曰土官。酋官入郭，則加冠巾，餘皆椎髻，能者則以白練布纏之，曾殺人者謂之能。婦人徒跣，不識鞋履，以銀、錫或竹為釵，其長尺有咫。通以班紬布為之裳。紀歲不以建寅為首，隨所處無常月。要約以木鐵為契。病不謁醫，但殺牛祭鬼，率以刀斷其咽，視死所向以卜，多至十百頭。凡昏姻，兄死弟繼，姑舅之昏，他人取之，必賄男家，否則爭，甚則仇殺。男丁受田於酋長，不輸租而服其役，有罪則聽其所裁，謂之草斷。凡貸易之逋，甲不能償，則掠乙以取直，謂之準（上敫下手）。長少相犯，則少者出物，謂之出面。言語相誣，則虛者出物，謂之裹口。田丁之居，峭巖重阜，大率無十家之聚。遇仇殺則立柵布棘以受之。各有門款，門款者，猶言伍籍也，借牛綵於鄰洞者，謂之拽門款。方爭時，以首博首，獲級一二則潰去，明日復來，必相當乃止。欲解仇，則備財物以和，謂之陪頭暖心。戰之日，觀者立其傍和勸之，官雖居其中，不敢犯也。敗則走，謂之上坡。志在於掠，而不在於殺，則震以金鼓，而挺其一隅，縱之逸，謂之（走併）。敗者屈而歸之，掠其財而還其地，謂之入地。兵器有甲冑、標牌、弓弩，而刀之鐵尤良。弩則傅矢於絃而偏架之，謂之偏架弩，以利侔中土神臂弓，雖暑濕亦可用。凡仇殺，雖微隙必發，雖昔釁必報，父子兄弟之親不避也。子弟為士人者，隸於學，仇殺則歸，罷則復來。荊湖南、北路，如武岡、桂陽之屬瑤民，大略如此。","sortOrder":9},
  {"id":"s_work_dtbt_67_10","chapterId":"ch_work_dtbt_67","text":"寄資官","sortOrder":10},
  {"id":"s_work_dtbt_67_11","chapterId":"ch_work_dtbt_67","text":"內侍之職，至於幹辦後苑，則為出常調，流輩稱之曰苑使。又進而幹辦龍圖諸閣，曰閣長。其上曰門司，曰御藥，曰御帶。又其上為省官，謂押班及都知也。在法，內侍轉至東頭供奉官則止，若幹辦御藥院，不許寄資，當遷官則轉歸吏部。司馬公論高居簡雲：「舊製，御藥院官至內殿崇班以上，即須出外，今獨留四人，中外以此竊議。」言之詳矣。後乃不然，逮其遷帶御器械可帶階官，然後盡還所寄之資。至於宣政、宣慶諸使，遙郡防、團、觀察，其高者為延福宮、景福殿承宣使。頃在樞密行府，有院吏兵房副承旨董球，於紹興三十二年正月尚未有正官，至四月，予接伴人使回，球通刺字來謁，已轉出為武顯大夫。問其何以遽得至此？曰：「副承旨比附武顯郎，後用賞故爾。」蓋亦寄資也。","sortOrder":11},
  {"id":"s_work_dtbt_67_12","chapterId":"ch_work_dtbt_67","text":"親王帶將仕郎","sortOrder":12},
  {"id":"s_work_dtbt_67_13","chapterId":"ch_work_dtbt_67","text":"薛氏五代史，梁太祖開平元年五月，皇第五男友雍封賀王。及友珪篡位，以將仕郎試祕書省校書郎賀王友雍為銀青光祿大夫、檢校工部尚書兼御史大夫。以親王而階將仕郎，仍試銜初品，雖典章掃地之時，恐不應爾也。","sortOrder":13},
  {"id":"s_work_dtbt_67_14","chapterId":"ch_work_dtbt_67","text":"郡縣用陰陽字","sortOrder":14},
  {"id":"s_work_dtbt_67_15","chapterId":"ch_work_dtbt_67","text":"山南為陽，水北為陽，穀梁傳之語也，若山北水南則為陰，故郡縣及地名多用之，今略敍於此。山之南者，如嵩陽、華陽、恆陽、衡陽、鎮陽、嶽陽、嶧陽、夏陽、城陽、陵陽、岐陽、首陽、營陽、鹹陽、櫟陽、宜陽、山陽、(屬河內郡，太行在北。)廣陽、辟陽、河陽、魯陽、黎陽、樅陽、零陽、巫陽、東陽、韶陽、郴陽、揭陽、弋陽、(屬汝南郡，弋山在西北。)當陽、青陽、黔陽、壽陽、麻陽、雲陽、美陽、復陽、(南陽復山之陽。)上曲陽、(屬常山。)下曲陽、(屬鉅鹿。)稒陽、屬五原。原陽。屬雲中。水之北者，馮翊之池陽、頻陽、郃陽、沈陽、扶風之杜陽，河東之大陽、(大河之陽。)平陽，(平河之陽。)太原之晉陽、汾陽，及河陽，洛陽，滎陽，偪陽，渭陽，淮陽，汶陽，濟陽，襄陽，滏陽，漁陽，遼陽，泗陽，伊陽，永陽，滁陽，潮陽，澧陽，灌陽，汧陽，洮陽，沭陽，東郡之濮陽、東武陽，潁川之潁陽、崑陽、舞陽，汝南之汝陽、鮦陽、紬陽、灈陽、滇陽、新陽、安陽、博陽、成陽，南陽之育陽、湼陽、堵陽、蔡陽、筑陽、棘陽、比陽、朝陽、湖陽、紅陽，江夏之西陽，廬江之尋陽，九江之曲陽，濟陰之句陽，(音鉤，句瀆之丘。)沛郡之穀陽、扶陽、漂陽，魏郡之繁陽，鉅鹿之堂陽，清河之清陽，涿郡之高陽、饒陽、范陽，勃海之浮陽，濟南之般陽、朝陽，泰山之東平陽、東武陽、寧陽，北海之膠陽，東海之開陽、曲陽、都陽，臨淮之射陽、蘭陽，丹陽之丹陽、陵陽、溧陽，豫章之鄱陽、鄡陽，桂陽之耒陽、桂陽、湞陽，武陵之無陽、辰陽、酉陽、零陽，零陵之洮陽，漢中之旬陽、沔陽、安陽，犍為之江陽、武陽、漢陽，金城之枝陽，天水之略陽、阿陽，安定之涇陽、彭陽，北地之泥陽，上郡之定陽，雁門之沃陽、劇陽，上穀之沮陽，漁陽之要陽，遼西之海陽，右北平之夕陽、聚陽，蒼梧之封陽，趙國之易陽，膠東之觀陽，長沙之益陽，已上皆見漢書地理志。其水之下，必曰在某水之陽。合山水之稱陽者，百有五六十，至陰字則甚少，蓋面勢在背，自難立國邑耳。山之北者，唯華陰、山陰、龜陰、蒙陰、鶉陰、雕陰、襄陰，水之南者，汾陰、蕩陰、潁陰、汝陰、舞陰、濟陰、漢陰、晉陰、蒲陰、湘陰、漯陰、河陰、湖陰、江陰、淮陰、圜陰，僅三十而已。若樂陽、南陽、合陽、被陽、富陽、(屬泰山者。)昌陽、建陽、(屬東海者。)武陽之類，尚多有之，莫能知其為山為水也。","sortOrder":15},
  {"id":"s_work_dtbt_67_16","chapterId":"ch_work_dtbt_67","text":"杜畿李泌董晉","sortOrder":16},
  {"id":"s_work_dtbt_67_17","chapterId":"ch_work_dtbt_67","text":"漢建安中，河東太守王邑被召，郡掾衞固、范先請留之。固等外以請邑為名，而內實與幷州高幹通謀。曹操選杜畿為太守，固等使兵絕陝津，數月不得渡。畿曰：「河東有三萬戶，非皆欲為亂也。吾單車直往，出其不意，固為人多計而無斷，必偽受吾。吾得居郡一月，以計縻之足矣。」遂詭道從郖津度，固遂奉之。畿謂固、先曰：「衞、范，河東之望也，吾仰成而已。」比數十日，諸將斬固等首。","sortOrder":17},
  {"id":"s_work_dtbt_67_18","chapterId":"ch_work_dtbt_67","text":"唐貞元初，陝虢兵馬使達奚抱暉殺節度使張勸，代總軍務，邀求旌節。德宗遣李泌往，欲以神策軍送之，泌請以單騎入，上加泌觀察使。泌出潼關，鄜坊步騎三千布於關外，曰：「奉密詔送公。」泌寫宣以却之，疾驅而前。抱暉不使將佐出迎，去城十五里方出謁。泌稱其攝事保城壁之功，入城視事。明日，召抱暉至宅，語之曰：「吾非愛汝而不誅，恐自今有危疑之地，朝廷所命將帥，皆不能入，故丐汝餘生。」抱暉遂亡命。","sortOrder":18},
  {"id":"s_work_dtbt_67_19","chapterId":"ch_work_dtbt_67","text":"宣武節度使李萬榮疾病，其子迺為兵馬使，欲為亂，都虞候鄧惟恭執送京師。詔以東都留守董晉為節度使。惟恭權軍事，自謂當代萬榮，不遣人迎晉。晉既受詔，即與僕從十餘人赴鎮，不用兵衞。至鄭州，或勸晉且留觀變。有自汴州出者，言不可入，晉不對，遂行。惟恭以晉來之速，不及謀，去城十餘里，乃帥諸將出迎。晉入，仍委以軍政。久之，惟恭內不自安，潛謀作亂，事覺，晉悉捕斬其黨，械惟恭送京師。","sortOrder":19},
  {"id":"s_work_dtbt_67_20","chapterId":"ch_work_dtbt_67","text":"觀此三者，其危至矣！杜畿、李泌、董晉，皆以單車入逆城，從容妥定，其智勇過人如此。唐史猶譏晉為懦弛苟安，殆不然也。是時，朝議以晉柔仁多可，恐不能集事，用汝州刺史陸長源為行軍司馬以佐之。長源性剛刻，多更張舊事，晉初皆許之，案成則命且罷，由是軍中得安。初，劉玄佐、李萬榮、鄧惟恭時，士卒驕不能禦，乃置腹心之士，幕於公庭廡下，挾弓執劍以備之，時勞賜酒肉。晉至之明日，悉罷之。謂之懦弛，實為失當。晉在汴三年而薨，長源代之，即為軍士所殺。向使晉聽用其言，汴亂久矣。又李泌傳但雲拜陝虢觀察使，開車道至三門，及殺淮西亡兵。於赴鎮事略不書，亦失之也。","sortOrder":20},
  {"id":"s_work_dtbt_67_21","chapterId":"ch_work_dtbt_67","text":"嚴有翼詆坡公","sortOrder":21},
  {"id":"s_work_dtbt_67_22","chapterId":"ch_work_dtbt_67","text":"嚴有翼所著藝苑雌黃，該洽有識，蓋近世博雅之士也。然其立說頗務譏詆東坡公，予嘗因論玉川子月蝕詩，誚其輕發矣。又有八端，皆近於蚍蜉撼大木，招後人攻擊。如正誤篇中，摭其用五十本鰃為「種薤五十本」，發丘中郎將為「校尉解摸金」，扁鵲見長桑君，使飲上池之水，為「倉公飲上池」，鄭餘慶烝胡蘆為盧懷慎雲，如此甚多。坡詩所謂抉雲漢，分天章，萬斛泉源不擇地而出。若用鰃為薤，用校尉為中郎，用扁鵲為倉公，用餘慶為懷慎，不失為名語，於理何害？公豈一一如學究書生，案圖索駿，規行矩步者哉！四凶篇中，謂坡稱太史公多見先秦古書，四族之誅，皆非殊死，為無所考據。盧橘篇中，謂坡詠枇杷雲「盧橘是鄉人」，為何所據而言。昌陽篇中昌蒲贊，以為信陶隱居之言，以為昌陽，不曾詳讀本草，妄為此說。苦荼篇中，謂「周詩記苦荼」為誤用爾雅。如皋篇中，謂「不向如皋閒射雉」與左傳杜註不合，其誤與江總「暫往如皋路」之句同。荔枝篇中，謂四月食荔枝詩，愛其體物之工，而坡未嘗到閩中，不識真荔枝，是特火山耳。此數者或是或非，固未為深失，然皆不必爾也。最後一篇遂名曰辨坡，謂雪詩雲，「飛花又舞謫仙簷」，李太白本言送酒，即無雪事。「水底笙歌蛙兩部」，無笙歌字。殊不知坡藉花詠雪，以鼓吹為笙歌，正是妙處。「坐看青丘吞澤芥」，「青丘已吞雲夢芥」，用芥字和韻，及以澤芥對溪蘋，可謂工新。乃以為出處曾不蔕芥，非草芥之芥。「知白守黑名曰穀」正是老子所言，又以為老子只雲為天下穀，非名曰穀也。如此論文章，其意見亦淺矣。","sortOrder":22},
  {"id":"s_work_dtbt_67_23","chapterId":"ch_work_dtbt_67","text":"曹馬能收人心","sortOrder":23},
  {"id":"s_work_dtbt_67_24","chapterId":"ch_work_dtbt_67","text":"曹操自擊烏桓，諸將皆諫，既破敵而還，科問前諫者，衆莫知其故，人人皆懼。操皆厚賞之，曰：「孤前行，乘危以僥倖，雖得之，天所佐也，顧不可以為常。諸君之諫，萬安之計，是以相賞，後勿難言之。」魏伐吳，三征各獻計，詔問尚書傅嘏，嘏曰：「希賞徼功，先戰而後求勝，非全軍之長策也。」司馬師不從，三道擊吳，軍大敗。朝議欲貶出諸將，師曰：「我不聽公休，以至於此，此我過也，諸將何罪？」悉宥之。弟昭時為監軍，唯削昭爵。雍州刺史陳泰求敕幷州，幷力討胡，師從之。未集，而二郡胡以遠役遂驚反，師又謝朝士曰：「此我過也，非陳雍州之責。」是以人皆愧悅。討諸葛誕於壽春，王基始至，圍城未合，司馬昭敕基斂軍堅壁。基累求進討，詔引諸軍轉據北山。基守便宜，上疏言：「若遷移依險，人心搖蕩，於勢大損。」書奏報聽。及壽春平，昭遺基書曰：「初，議者雲雲，求移者甚衆，時未臨履，亦謂宜然。將軍深算利害，獨秉固心，上違詔命，下拒衆議，終於製敵禽賊，雖古人所述，不過是也。」然東關之敗，昭問於衆曰：「誰任其咎？」司馬王儀曰：「責在元帥。」昭怒曰：「司馬欲委罪於孤耶？」引出斬之。此為謬矣！操及師、昭之奸逆，固不待言。然用兵之際，以善推人，以惡自與，幷謀兼智，其誰不歡然盡心悉力以為之用？袁紹不用田豐之計，敗於官渡，宜罪己，謝之不暇，乃曰：「吾不用豐言，卒為所笑。」竟殺之。其失國喪師，非不幸也。","sortOrder":24},
  {"id":"s_work_dtbt_67_25","chapterId":"ch_work_dtbt_67","text":"取蜀將帥不利","sortOrder":25},
  {"id":"s_work_dtbt_67_26","chapterId":"ch_work_dtbt_67","text":"自巴蜀通中國之後，凡割據擅命者，不過一傳再傳。而從東方舉兵臨之者，雖多以得鉨，將帥輒不利，至於死貶。漢伐公孫述，大將岑彭、來歙遭刺客之禍，吳漢幾不免。魏伐劉禪，大將鄧艾、鍾會皆至族誅。唐莊宗伐王衍，招討使魏王繼岌、大將郭崇韜、康延孝皆死。國朝伐孟昶，大將王全斌、崔彥進皆不賞而受黜，十年乃復故官。","sortOrder":26},
  {"id":"s_work_dtbt_67_27","chapterId":"ch_work_dtbt_67","text":"李嶠楊再思","sortOrder":27},
  {"id":"s_work_dtbt_67_28","chapterId":"ch_work_dtbt_67","text":"李嶠、楊再思相唐中宗，皆以諛悅保位，為世所詆，然亦有可稱。武後時，嶠為給事中，來俊臣陷狄仁傑等獄，將抵死，敕嶠與大理少卿張德裕、侍御史劉憲覆驗。德裕等內知其噃，不敢異，嶠曰：「知其枉不申，是謂見義不為者。」卒與二人列其枉。忤後旨，出為潤州司馬，然仁傑數人竟賴此獲脫。嶠此舉可謂至難，而資治通鑑不載。神龍初，要官闕，執政以次用其親。韋巨源秉筆，當除十人，再思得其一，試問餘授，皆諸宰相近屬。再思喟然曰：「吾等誠負天下！」巨源曰：「時當爾耳。」再思此言，自狀其短，觀過知仁，亦足稱也。","sortOrder":28},
  {"id":"s_work_dtbt_68_1","chapterId":"ch_work_dtbt_68","text":"卷第一(十九則)","sortOrder":1},
  {"id":"s_work_dtbt_68_2","chapterId":"ch_work_dtbt_68","text":"天慶諸節","sortOrder":2},
  {"id":"s_work_dtbt_68_3","chapterId":"ch_work_dtbt_68","text":"大中祥符之世，諛佞之臣，造為司命天尊下降及天書等事，於是降聖、天慶、天祺、天貺諸節並興。始時京師宮觀每節齋醮七日，旋減為三日、一日，後不復講。百官朝謁之禮亦罷。今中都未嘗舉行，亦無休假，獨外郡必詣天慶觀朝拜，遂休務，至有前後各一日。此為敬事司命過於上帝矣，其當寢明甚，惜無人能建白者。","sortOrder":3},
  {"id":"s_work_dtbt_68_4","chapterId":"ch_work_dtbt_68","text":"虢州兩刺史","sortOrder":4},
  {"id":"s_work_dtbt_68_5","chapterId":"ch_work_dtbt_68","text":"唐韓休為虢州刺史，虢於東、西京為近州，乘輿所至，常稅廐芻。休請均賦它郡，中書令張說曰：「免虢而與它州，此守臣為私惠耳！」休復執論，吏白恐忤宰相意，休曰：「刺史幸知民之弊而不救，豈為政哉？雖得罪所甘心焉。」訖如休請。盧（木巳）為虢州刺史，奏言虢有官豕三千，為民患。德宗曰：「徙之沙苑。」（木巳）曰：「同州亦陛下百姓，臣謂食之便。」帝曰：「守虢而憂它州，宰相材也。」詔以豕賜貧民，遂有意柄任矣。俄召入，逾年拜相。案兩人皆以虢州守臣言公家事，而休見疑於名相，（木巳）受知於猜主，遇合有命，信哉！","sortOrder":5},
  {"id":"s_work_dtbt_68_6","chapterId":"ch_work_dtbt_68","text":"狐假虎威","sortOrder":6},
  {"id":"s_work_dtbt_68_7","chapterId":"ch_work_dtbt_68","text":"諺有「狐假虎威」之語，稚子來扣其義，因示以戰國策、新序所載。戰國策雲：「楚宣王問羣臣曰：『吾聞北方之畏昭奚恤也，果誠何如？』羣臣莫對。江乙對曰：『虎求百獸而食之，得狐，狐曰：「子無敢食我矣，天帝使我長百獸，今子食我，是逆天帝命也。子以我為不信，吾為子先行，子隨我後，觀百獸之見我而敢不走乎？」虎以為然，故遂與之行。獸見之皆走，虎不知獸畏己而走也，以為畏狐也。今王之地方五千里，帶甲百萬，而專屬之昭奚恤，故北方之畏奚恤也，其實畏王之甲兵也，猶百獸之畏虎也。』」新序並同。而其後雲：「故人臣而見畏者，是見君之威也，君不用，則威亡矣。」俗諺蓋本諸此。","sortOrder":7},
  {"id":"s_work_dtbt_68_8","chapterId":"ch_work_dtbt_68","text":"徐章二先生教人","sortOrder":8},
  {"id":"s_work_dtbt_68_9","chapterId":"ch_work_dtbt_68","text":"徐仲車先生為楚州教授，每升堂，訓諸生曰：「諸君欲為君子，而勞己之力，費己之財，如此而不為，猶之可也；不勞己之力，不費己之財，何不為君子？鄉人賤之，父母惡之，如此而不為可也；鄉人榮之，父母欲之，何不為君子？」又曰：「言其所善，行其所善，思其所善，如此而不為君子者，未之有也。言其不善，行其不善，思其不善，如此而不為小人者，未之有也。」成都沖退處士章縱隱者，其學長於易太玄，為范子功解述大旨，再復攡詞曰：「『人之所好而不足者，善也；所醜而有餘者，惡也。君子能強其所不足，而拂其所有餘，則太玄之道幾矣。』此子雲仁義之心，予之於太玄，述斯而已。或者苦其思，艱其言，迂溺其所以為數，而忘其仁義之大，是惡足以語道哉！」二先生之教人，簡易明白，學者或未知之，故表出於此。","sortOrder":9},
  {"id":"s_work_dtbt_68_10","chapterId":"ch_work_dtbt_68","text":"張呂二公文論","sortOrder":10},
  {"id":"s_work_dtbt_68_11","chapterId":"ch_work_dtbt_68","text":"張文潛誨人作文，以理為主，嘗著論雲：「自六經以下，至於諸子百氏、騷人、辯士論述，大抵皆將以為寓理之具也。故學文之端，急於明理，如知文而不務理，求文之工，世未嘗有是也。夫決水於江、河、淮、海也，順道而行，滔滔汩汩，日夜不止，衝砥柱，絕呂梁，放於江湖而納之海，其舒為淪漣，鼓為濤波，激之為風颷，怒之為雷霆，蛟龍魚（上敝下黽），噴薄出沒，是水之奇變也。水之初，豈若是哉！順道而决之，因其所遇而變生焉。溝瀆東决而西竭，下滿而上虛，日夜激之，欲見其奇，彼其所至者，蛙蛭之玩耳！江、河、淮、海之水，理達之文也，不求奇而奇至矣。激溝瀆而求水之奇，此無見於理，而欲以言語句讀為奇，反復咀嚼，卒亦無有，此最文之陋也。」一時學者仰以為至言。予作史，採其語著於本傳中。又呂南公雲：「士必不得已於言，則文不可以不工。蓋意有餘而文不足，則如吃人之辯訟，心未始不虛，理未始不直，然而或屈者，無助於辭而已矣。觀書契以來，特立之士未有不善於文者。士無志於立言則已，必有志焉，則文何可以卑淺而為之。故毅然盡心，思欲與古人並。」此南公與人書如此，予亦載之傳中。","sortOrder":11},
  {"id":"s_work_dtbt_68_12","chapterId":"ch_work_dtbt_68","text":"郎官非時得對","sortOrder":12},
  {"id":"s_work_dtbt_68_13","chapterId":"ch_work_dtbt_68","text":"唐肅宗在靈武，關東獻俘百，將即死，有嘆者。司膳員外郎李勉過而問之，曰：「被脅而官，非敢反。」勉入見帝曰：「寇亂之汙半天下，其欲澡心自歸無繇，如盡殺之，是驅以助賊也。」帝馳騎全宥。以一郎吏之微，而非時得入對，雖唐製不可詳知，想兵戈艱難時，暫如是耳！","sortOrder":13},
  {"id":"s_work_dtbt_68_14","chapterId":"ch_work_dtbt_68","text":"王安石棄地","sortOrder":14},
  {"id":"s_work_dtbt_68_15","chapterId":"ch_work_dtbt_68","text":"熙寧七年，遼主洪基遣泛使蕭禧來言河東地界未决。八年再來，必欲以代州天池分水嶺為界。詔詢於故相文彥博、富弼、韓琦、曾公亮以可與及不可許之狀，皆以為不可。王安石當國，言曰：「將欲取之，必固與之。」於是詔不論有無照驗，擗撥與之。往時界於黃嵬山麓，我可以下瞰其應、朔、武三州，既以嶺與之，虜遂反瞰忻、代，凡東西失地七百里。案慶曆中，虜求關南十縣，朝廷方以西夏為慮，猶不過增歲幣以塞其欲，至於土地，尺寸弗與。熙寧之兵力勝於曩時，而用蕭禧堅坐都亭之故，輕棄疆埸設險要害之處。安石果於大言，其實無詞以却之也。孫權謂：「魯肅勸吾借劉玄德地雲：『帝王之起，皆有驅除，關羽不足忌。』此子敬內不能辨，外為大言耳！」安石之語亦然。","sortOrder":15},
  {"id":"s_work_dtbt_68_16","chapterId":"ch_work_dtbt_68","text":"雙生以前為兄","sortOrder":16},
  {"id":"s_work_dtbt_68_17","chapterId":"ch_work_dtbt_68","text":"續筆已書公羊傳註雙生子事，茲讀西京雜記，得一說甚詳。雲：「霍將軍妻一產二子，疑所為兄弟。或曰：『前生為兄，後生為弟，今雖俱日，亦宜以先生為兄。』或曰：『居上者宜為兄，居下者宜為弟，居下者前生，今宜以前生為弟。』光曰：『昔殷王祖甲一產二子，以卯日生嚚，以巳日生良。則以嚚為兄，以良為弟，若以在上者為兄，嚚亦當為弟矣。』許莊公一產二女，曰妖曰茂，楚大夫唐勒一產二子，一男一女，男曰正夫，女曰瓊華，皆以先生為長。近代鄭昌時、文長倩幷生二男，滕公一生二女，李黎生一男一女，幷以前生為長。霍氏亦以前生為兄焉。」此最可證。","sortOrder":17},
  {"id":"s_work_dtbt_68_18","chapterId":"ch_work_dtbt_68","text":"風俗通","sortOrder":18},
  {"id":"s_work_dtbt_68_19","chapterId":"ch_work_dtbt_68","text":"應劭風俗通雖東漢末所作，然所載亦難盡信。其敍希姓者曰：「合浦太守虎旗、上郡太守邸杜、河內太守遇冲、北平太守賤瓊、東平太守到質、沐寵、北平太守卑躬、雁門太守宿詳、五原太守督（王賈）、汝南太守謁渙、九江太守荊修、東海太守鄐熙、弘農太守移良、南郡太守為崑、酒泉太守頻暢、北海太守處興、巴郡太守鹿旗、涿郡太守作顯、廬江太守貴遷、交趾太守賴先、外黃令集一、洛陽令諸於、單父令即賣、烏傷令昔登、山陽令職洪、高唐令用虯。」此二十君子，皆是郡守、縣令，惟移良之名曾見於史，恐未必然也。","sortOrder":19},
  {"id":"s_work_dtbt_68_20","chapterId":"ch_work_dtbt_68","text":"俗語有出","sortOrder":20},
  {"id":"s_work_dtbt_68_21","chapterId":"ch_work_dtbt_68","text":"今人意錢賭博，皆以四數之，謂之「攤」。案廣韻攤字下雲：「攤蒱，四數也。」竹工謂屋椽上織箔曰篖笪，廣韻篖字下雲：「筕篖，竹也笪。」采帛鋪謂翦截之餘曰帵子，帵，一懽切。註，裁餘也。挑剔燈火之杖曰（木忝），他念切。註，火杖也。李濟翁資暇集雲：「意錢當曰攤鋪，疾道之，訛其音為蒲。」此說不然。","sortOrder":21},
  {"id":"s_work_dtbt_68_22","chapterId":"ch_work_dtbt_68","text":"昏主棄功臣","sortOrder":22},
  {"id":"s_work_dtbt_68_23","chapterId":"ch_work_dtbt_68","text":"燕昭王伐齊，取其七十城，所存者惟莒、即墨，田單一旦悉復之，使齊復為齊。而襄王聽幸臣九子之譖，單幾不免。秦苻堅舉百萬之師伐晉，賴謝安却之，而孝武帝聽王國寶之讒，安不能立於朝廷之上。桓溫伐慕容暐，暐兵屢挫，議欲奔北，慕容垂一戰，使燕復存，乃用慕容評之毀，垂竄身苻氏，國隨以亡。朱泚據京師，德宗播遷奉天，李懷光繼叛，李晟孤軍堅壁，竟平大難，而德宗用張延賞之譖，訖罷其兵，且百端疑忌，至於鞅鞅以死。自古昏主不明，輕棄功臣如此，真可嘆也！","sortOrder":23},
  {"id":"s_work_dtbt_68_24","chapterId":"ch_work_dtbt_68","text":"問故居","sortOrder":24},
  {"id":"s_work_dtbt_68_25","chapterId":"ch_work_dtbt_68","text":"陶淵明問來使詩雲：「爾從山中來，早晚發天目。我屋南窗下，今生幾叢菊？薔薇葉已抽，秋蘭氣當馥。歸去來山中，山中酒應熟。」諸集中皆不載，惟晁文元家本有之，蓋天目疑非陶居處。然李太白雲：「陶令歸去來，田家酒應熟。」乃用此爾。王摩詰詩曰：「君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未？」杜公送韋郎歸成都雲：「為問南溪竹，抽梢合過牆。」憶弟雲：「故園花自發，春日鳥還飛。」王介甫雲：「道人北山來，問松我東岡。舉手指屋脊，雲今如許長。」古今詩人懷想故居，形之篇詠，必以松竹梅菊為比、興，諸子句皆是也。至於杜公將別巫峽贈南卿兄瀼西果園詩雲：「苔竹素所好，萍蓬無定居。遠遊長兒子，幾地別林廬。雜蕊紅相對，他時錦不如。具舟將出峽，巡圃念攜鋤。」每讀至此，未嘗不為之凄然。寄題草堂雲：「尚念四小松，蔓草易拘纏。霜骨不甚長，永為鄰里憐。」又一篇雲：「四松初移時，大抵三尺強。別來忽三載，離立如人長。」尤可見一時之懷抱也。","sortOrder":25},
  {"id":"s_work_dtbt_68_26","chapterId":"ch_work_dtbt_68","text":"唐宰相不歷守令","sortOrder":26},
  {"id":"s_work_dtbt_68_27","chapterId":"ch_work_dtbt_68","text":"唐楊綰、崔祐甫、杜黃裳、李藩、裴垍皆稱英宰，然考其履歷，皆未嘗為刺史、守令。綰初補太子正字，擢右拾遺，起居、中書舍人，禮、吏部侍郎，國子祭酒，太常卿，拜相；祐甫初調壽安尉，歷藩府判官，入為起居、中書舍人，拜相；黃裳初佐朔方府，入為侍御史，太子賓客，太常卿，拜相；藩佐東都、徐州府，入為祕書郎，郎中，給事中，拜相；垍由美原尉四遷考功員外郎，中書舍人，戶部侍郎，拜相。五賢行業，史策書之已詳，茲不復論。然則後之用人，必言踐揚中外，諳熟民情，始堪大用，殆為隘矣。","sortOrder":27},
  {"id":"s_work_dtbt_68_28","chapterId":"ch_work_dtbt_68","text":"張釋之柳渾","sortOrder":28},
  {"id":"s_work_dtbt_68_29","chapterId":"ch_work_dtbt_68","text":"漢張釋之為廷尉，文帝出行，有人驚乘輿馬，使騎捕之，屬廷尉。釋之奏當此人犯蹕，罰金。上怒，釋之曰：「方其時，上使使誅之則已。」顏師古謂：「言初執獲此人，天子即令誅之，其事即畢。」唐柳渾為相，玉工為德宗作帶，誤毀一銙，工私市它玉足之。帝識不類，怒其欺，詔京兆論死，渾曰：「陛下遽殺之則已，若委有司，須詳讞乃可。於法，罪當杖，請論如律。」由是工不死。予謂張、柳之論，可謂善矣，然張雲「上使使誅之則已」，柳雲「陛下遽殺之則已」，無乃啟人主徑殺人之端乎！斯一節未為至當也。","sortOrder":29},
  {"id":"s_work_dtbt_68_30","chapterId":"ch_work_dtbt_68","text":"人臣震主","sortOrder":30},
  {"id":"s_work_dtbt_68_31","chapterId":"ch_work_dtbt_68","text":"人臣立社稷大功，負海宇重望，久在君側，為所敬畏，其究必至於招疑毀。漢高祖有天下，韓信之力為多，終以挾不賞之功，戴震主之威，至於誅滅。霍光擁昭立宣，勢侔人主，宣帝謁見高廟，光從驂乘，上內嚴憚之，若有芒刺在背。其家既覆，俗傳之曰：「威震主者不畜，霍氏之禍，萌於驂乘。」周亞夫平定七國，景帝怒其固爭栗太子，由此疏之，後目送其出，曰：「此鞅鞅，非少主臣也。」訖以無罪殺之。謝安却苻堅百萬之衆，晉室復存，功名既盛，險詖求進之徒，多毀短之，孝武稍以疏忌，又信會稽王道子之奸扇，至使避位出外，終以至亡。齊文宣之篡魏，皆高德政之力，德政為相，數強諫，帝不悅。謂左右曰：「高德政恆以精神凌逼人。」遂殺之，幷其妻子。隋文帝將篡周，欲引高熲入府，熲忻然曰：「願受驅馳，縱公事不成，亦不辭滅族。」及帝受禪，用為相二十年，朝臣莫與為比。熲自以為任寄隆重，每懷至公，無自疑意。積為獨孤皇後、漢王諒等所譖，帝欲成其罪，既罷之後，至雲：「自其解落，瞑然忘之，如本無高熲。不可以身要君，自雲第一也。」迨於煬帝，竟以冤誅。郭子儀再造王室，以身為天下安危，權任既重，功名復大，德宗即位，自外召還朝，所領副元帥諸使悉罷之。李晟以孤軍復京城，不見信於庸主，使之晝夜泣，目為之腫，卒奪其兵，百端疑忌，幾於不免。李德裕功烈光明，佐武宗中興，威名獨重，宣宗立，奉冊太極殿，帝退謂左右曰：「向行事近我者，非太尉邪？每顧我，毛髮為之森豎。」明日罷之，終於貶死海外。若郭崇韜、安重誨皆然也。","sortOrder":31},
  {"id":"s_work_dtbt_68_32","chapterId":"ch_work_dtbt_68","text":"五經秀才","sortOrder":32},
  {"id":"s_work_dtbt_68_33","chapterId":"ch_work_dtbt_68","text":"唐楊綰為相，以進士不鄉舉，但試辭賦浮文，非取士之實，請置五經秀才科。李栖筠、賈至以綰所言為是，然亦不聞施行也。","sortOrder":33},
  {"id":"s_work_dtbt_68_34","chapterId":"ch_work_dtbt_68","text":"陶潛去彭澤","sortOrder":34},
  {"id":"s_work_dtbt_68_35","chapterId":"ch_work_dtbt_68","text":"晉書及南史陶潛傳，皆雲：「潛為彭澤令，素簡貴，不私事上官。郡遣督郵至，縣吏白：『應束帶見之。』潛嘆曰：『吾不能為五斗米折腰，拳拳事鄉里小人。』即日解印綬去，賦歸去來以遂其志。」案陶集載此辭，自有序，曰：「餘家貧，耕植不足以自給。彭澤去家百里，故便求之。及少日，眷然有歸歟之情。何則？質性自然，非矯勵所得，饑凍雖切，違己交病。悵然慷慨，深愧平生之志，猶望一稔，當斂裳宵逝。尋程氏妹喪於武昌，情在駿奔，自免去職，在官八十餘日。」觀其語意，乃以妹喪而去，不緣督郵。所謂矯勵違己之說，疑必有所屬，不欲盡言之耳！詞中正喜還家之樂，略不及武昌，自可見也。","sortOrder":35},
  {"id":"s_work_dtbt_68_36","chapterId":"ch_work_dtbt_68","text":"羌戎畏服老將","sortOrder":36},
  {"id":"s_work_dtbt_68_37","chapterId":"ch_work_dtbt_68","text":"漢先零羌犯塞，趙充國往擊之。羌豪相數責曰：「語汝亡反，今天子遣趙將軍來，年八九十矣，善為兵。今請欲一鬥而死，可得邪！」充國時年七十六，訖平之。唐代宗時，回紇、吐蕃合兵入寇，郭子儀單騎見回紇，復與之和。諸酋長皆大喜曰：「嚮以二巫師從軍，巫言：『此行甚安穩，不與唐戰，見一大人而還。』今果然矣。」郭公是時年七十，乃知羌、戎畏服老將如此。班超久在西域，思歸，故其言雲：「蠻夷之俗，畏壯侮老。」蓋有為而雲。","sortOrder":37},
  {"id":"s_work_dtbt_68_38","chapterId":"ch_work_dtbt_68","text":"古人字只一言","sortOrder":38},
  {"id":"s_work_dtbt_68_39","chapterId":"ch_work_dtbt_68","text":"檀弓雲：「幼名冠字，五十以伯仲，周道也。」古之人命字，一而已矣。初曰子，已而為仲為伯，又為叔為季，其老而尊者為甫，蓋無以兩言相連取義。若屈原離騷經：「名餘曰正則兮，字餘曰靈均。」案史記原字平，所謂「靈均」者，釋「平」之義，以緣飾詞章耳。下至西漢，與周相接，故一切皆然。除子房、子卿、子孟、子政、子孺、子長、子雲、子兄、子真、子公、子陽、子賓、子幼之外，若仲孺、仲卿、仲子、長卿、少卿、孺卿、君卿、客卿、遊卿、翁卿、聖卿、長君、少君、穉君、遊君、次君、贛君、近君、曼君、王孫、翁孫、次公、少公、孟公、遊公、仲公、長公、君公、少叔、翁叔、長叔、中叔、子叔、長倩、曼倩、次倩、穉季、長孺、仲孺、幼孺、少孺、次孺、翁孺、君孺、長翁、弱翁、仲翁、少翁、君房、君賓、君倩、君敖、君蘭、君長、君仲、君孟、少季、少子、少路、少遊、穉賓、穉圭、穉遊、稚君、巨先、巨君、長賓、長房、翁思、翁子、翁仲之類，其義只從一訓，極為雅馴。至於婦人，曰少夫、君俠、政君、君力、君弟、君之、阿君。單書一字者，若陳勝字涉，項籍字羽，彭越字仲，張歐、吳廣、枚乘字叔，楚元王字交，朱雲字遊，爰盎字絲，張釋之字季，鄭當時字莊，劉德字路，眭弘字孟。迨東漢以下，則不盡然。","sortOrder":39},
  {"id":"s_work_dtbt_68_40","chapterId":"ch_work_dtbt_68","text":"容齋五筆","sortOrder":40},
  {"id":"s_work_dtbt_69_1","chapterId":"ch_work_dtbt_69","text":"卷第二(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_69_2","chapterId":"ch_work_dtbt_69","text":"二叔不鹹","sortOrder":2},
  {"id":"s_work_dtbt_69_3","chapterId":"ch_work_dtbt_69","text":"左氏傳載富辰之言曰：「昔周公弔二叔之不鹹，故封建親戚，以藩屏周。」士大夫多以二叔為管、蔡。案蔡仲之命雲：「羣叔流言，乃致辟管叔於商，囚蔡叔，降霍叔為庶人。」蓋三叔也。杜預註以為周公傷夏、殷之叔世，疏其親戚，以至滅亡，故廣封其兄弟。是以方敍說管、蔡、郕、霍十六國，其義昭然。所言親戚者，指兄弟耳。","sortOrder":3},
  {"id":"s_work_dtbt_69_4","chapterId":"ch_work_dtbt_69","text":"官階服章","sortOrder":4},
  {"id":"s_work_dtbt_69_5","chapterId":"ch_work_dtbt_69","text":"唐憲宗時，因數赦，官多泛階；又帝親郊，陪祠者授三品、五品，不計考；使府軍吏以軍功借賜朱紫，率十八；近臣謝、郎官出使，多所賜與。每朝會，朱紫滿庭，而少衣綠者，品服太濫，人不以為貴，帝亦惡之，詔太子少師鄭餘慶條奏懲革。淳熙十六年，紹熙五年，連有覃霈，轉官賜服者衆。紹熙元年，予自當塗徙會稽，過闕，遇起居舍人莫仲謙於漏舍，仲謙雲：「比赴景靈行香，見朝士百數，無一綠袍者。」又朝議、中奉皆直轉行，故五品官不勝計，頗類元和也。","sortOrder":5},
  {"id":"s_work_dtbt_69_6","chapterId":"ch_work_dtbt_69","text":"月非望而食","sortOrder":6},
  {"id":"s_work_dtbt_69_7","chapterId":"ch_work_dtbt_69","text":"曆家論日月食，自漢太初以來，始定日食，不在朔則在晦，否則二日，然甚少。月食則有十四、十五、十六之差，蓋置望參錯也。天體有二交道，曰交初，曰交中。交初者，星家以為羅睺。交中者，計都也。隱暗不可見，於是為入交法以求之，然不過能求朔望耳。若餘日入交，則書所不載，由漢及唐二十八家，暨本朝十一曆，皆然。姑以慶元丁巳歲五次月食考之，二月望為入交中，七月為交初，唯十月二十日、二十一日連兩夜，乃以二更盡月食之既，纔兩刻復明，十一月十八夜復如之。案此三食皆是交中。十月二十夜月在張五度，而計都在翼二度，次夜月在張十七度，計都未定，相距才四度耳。十一月十八夜，月在星五度，計都在張十九度，相距二十度。十二月十七夜五更，月在星二度，入交陽末，卯初四刻交甚，食六分半，八刻退交。十八夜四更，月在張六度，入交中陰初，至寅四刻交甚，食九分，卯五刻退交。其驗如此。予竊又有疑焉，太陰一月一周天，必兩值交道，今年遂至八食，一一如星官、曆翁之說，仍不拘月望，則玉川子之詩不勝作矣，當更求其旨趣雲。頃見太史局官劉孝榮言：「月本無光，受日為明，望夜正與日對，故一輪光滿。或月行有遲疾先後，日光所不照處，則為食。朔旦之日，日月同宮，如月在日上，掩太陽而過，則日光為所遮，故為日食。非此二日，則無薄蝕之理。」其說亦通。","sortOrder":7},
  {"id":"s_work_dtbt_69_8","chapterId":"ch_work_dtbt_69","text":"慶善橋","sortOrder":8},
  {"id":"s_work_dtbt_69_9","chapterId":"ch_work_dtbt_69","text":"饒州學非范文正公所建，予既書之矣。城內慶善橋之說，亦然。比因郡人修橋，拆去舊石，見其上鐫雲：「康定庚辰」。案范公以景祐乙亥為待製，丙子知開封府，黜知饒州，後徙潤、越，至庚辰歲乃復職，帥長安，既去此久矣。","sortOrder":9},
  {"id":"s_work_dtbt_69_10","chapterId":"ch_work_dtbt_69","text":"西漢以來加官","sortOrder":10},
  {"id":"s_work_dtbt_69_11","chapterId":"ch_work_dtbt_69","text":"漢書百官表雲侍中、左右曹、諸吏、散騎、中常侍，皆加官。所加或將軍、列侯、卿、大夫、將、都尉。給事中亦加官。所加或大夫、博士、議郎。其侍中、中常侍得入禁中，諸曹受尚書事，諸吏得舉法，散騎並乘輿車。並，步浪反。案漢世除授此等稱謂，殆若今之兼職者，不甚為顯秩，然魏相以御史大夫兼給事中。它如劉向以宗正，散騎、給事中；蘇武以右曹，典屬國；揚雄為諸吏，光祿大夫是也。至於金日磾以降虜為侍中，其子賞、建，諸孫常、敞、岑、明、涉、湯、融、欽，皆以左曹、諸吏、侍中，故班史贊之雲：「七世內侍，何其盛也！」蓋如今時閣門宣贊、祗候之類。但漢家多用士人，武帝所任莊助、朱買臣、吾丘壽王、東方朔諸人，皆天下選，此其所以為人貴重。東漢大略亦然。晉、宋以來，又有給事黃門侍郎、散騎常侍、通直散騎常侍、散騎侍郎等，皆為兼官，但視本秩之高下。已而復以將軍為寵，齊高帝以太子詹事何戢領選，以戢資重，欲加常侍，褚淵曰：「臣與王儉既已左珥，若復加戢，則八座遂有三貂。若帖以驍、遊，亦為不少。」乃以為吏部尚書，加驍騎將軍。唐有檢校官、文武散階、憲銜，乃此製也。國朝自真宗始創學士、直學士、待製、直閣職名，尤為仕宦所慕。今自觀文殿大學士至直祕閣，幾四十種，不刊之典，明白易曉，非若前代之冗泛雲。","sortOrder":11},
  {"id":"s_work_dtbt_69_12","chapterId":"ch_work_dtbt_69","text":"呂望非熊","sortOrder":12},
  {"id":"s_work_dtbt_69_13","chapterId":"ch_work_dtbt_69","text":"自李瀚蒙求有「呂望非熊」之句，後來據以為用。然以史策考之，六韜第一篇文韜曰：「文王將田，史編布卜曰：『田於渭陽，將大得焉。非龍非彲，(螭。)非虎非羆，兆得公侯，天遺汝師。』文王曰：『兆致是乎？』史編曰：『編之太祖史疇，為禹占得皋陶兆。』」史記雲：「呂尚窮困年老，以漁釣幹西伯，西伯將出獵，卜之，曰：『所獲非龍非彲，非虎非羆，所獲霸王之輔。』」後漢崔駰達旨，雲「漁父見兆於元龜」，註文乃引史記「非龍非彲，非熊非羆」為證。今之史記，蓋不然也。「非熊」出處，惟此而已。","sortOrder":13},
  {"id":"s_work_dtbt_69_14","chapterId":"ch_work_dtbt_69","text":"唐曹因墓銘","sortOrder":14},
  {"id":"s_work_dtbt_69_15","chapterId":"ch_work_dtbt_69","text":"慶元三年，信州上饒尉陳莊發土得唐碑，乃婦人為夫所作。其文曰：「君姓曹，名因，字鄙夫，世為鄱陽人。祖、父皆仕於唐高祖之朝，惟公三舉不第，居家以禮義自守。及卒於長安之道，朝廷公卿、鄉鄰耆舊，無不太息。惟予獨不然。謂其母曰：『家有南畝，足以養其親；室有遺文，足以訓其子。肖形天地間，範圍陰陽內，死生聚散，特世態耳，何憂喜之有哉！』予姓周氏，公之妻室也。歸公八載，恩義有奪，故贈之銘曰：『其生也天，其死也天，苟達此理，哀復何言！』」予案唐世上饒本隸饒州，其後分為信，故曹君為鄱陽人。婦人能文達理如此，惜其不傳，故書之，以裨圖志之缺。","sortOrder":15},
  {"id":"s_work_dtbt_69_16","chapterId":"ch_work_dtbt_69","text":"唐史省文之失","sortOrder":16},
  {"id":"s_work_dtbt_69_17","chapterId":"ch_work_dtbt_69","text":"楊虞卿兄弟，怙李宗閔勢，為人所奔向。當時為之語曰：「欲入舉場，先問蘇、張，蘇、張尚可，三楊殺我。」而新唐書減去「先」字。李德裕賜河北三鎮詔曰：「勿為子孫之謀，欲存輔車之勢。」新書減去「欲」字。遂使兩者意義為不鏗鏘激越，此務省文之失也。","sortOrder":17},
  {"id":"s_work_dtbt_69_18","chapterId":"ch_work_dtbt_69","text":"李德裕論命令","sortOrder":18},
  {"id":"s_work_dtbt_69_19","chapterId":"ch_work_dtbt_69","text":"李德裕相武宗，言從計行。韋弘質建言宰相不可兼治錢穀，德裕奏言：「管仲明於治國，其語曰：『國之重器，莫重於令。令重君尊，君尊國安，治人之本，莫要於令。故曰虧令者死，益令者死，不行令者死，留令者死，不從令者死，五者無赦。』又曰：『令在上，而論可否在下，是主威下繫於人也。』大和後，風俗寖敝，令出於上，非之在下，此敝不止，無以治國。臣謂製置職業，人主之柄，非小人所得幹，弘質賤臣，豈得以非所宜言，妄觸天聽，是輕宰相也。」德裕大意，欲朝廷尊，臣下肅，而政出宰相，故感憤切言之。予謂德裕當國，它相取充位而已。若如所言，則一命一令之出，臣下皆不得有言，諫官、御史、給事、舍人之職廢矣。弘質位給事中，亦非賤臣。宜其一朝去位，遂罹抵巇，皆自取之也。","sortOrder":19},
  {"id":"s_work_dtbt_69_20","chapterId":"ch_work_dtbt_69","text":"漢武唐德宗","sortOrder":20},
  {"id":"s_work_dtbt_69_21","chapterId":"ch_work_dtbt_69","text":"漢張湯事武帝，舞文巧詆以輔法，所治夷滅者多，旋以罪受誅。上惜湯，稍進其子安世，擢為尚書令。安世宿衞忠正，肅敬不怠，勤勞國家，卒為重臣，其可大用不疑。而武帝之意，乃以父湯故耳。唐盧杞相德宗，奸邪險賊，為天下禍。以公議不容，譴逐致死。帝念之不忘，擢敍其子元輔，至兵部侍郎。元輔端靜介正，能紹其祖奕之忠規，陟之臺省要官，宜也。而德宗之意，乃以父杞故爾。且武帝之世，羣臣不幸而誅者，如莊助、朱買臣、吾丘壽王諸人，及考終名臣，如汲黯、鄭莊、董仲舒、卜式，未嘗恤其孤。德宗輔相之賢，如崔祐甫、李泌、陸贄，皆身沒則已。而獨於湯、杞二人惓惓如此，是可嘆也！","sortOrder":21},
  {"id":"s_work_dtbt_69_22","chapterId":"ch_work_dtbt_69","text":"諸公論唐肅宗","sortOrder":22},
  {"id":"s_work_dtbt_69_23","chapterId":"ch_work_dtbt_69","text":"唐肅宗於幹戈之際，奪父位而代之。然尚有可諉者，曰：「欲收復兩京，非居尊位，不足以製命諸將耳。」至於上皇還居興慶，惡其與外人交通，劫徙之西內，不復定省，竟以怏怏而終，其不孝之惡，上通於天。是時，元次山作中興頌，所書天子幸蜀，太子即位於靈武，直指其事。殆與洪範雲「武王勝殷殺受」之辭同。其詞曰：「事有至難，宗廟再安，二聖重歡。」既言重歡，則知其不歡多矣。杜子美杜鵑詩：「我看禽鳥情，猶解事杜鵑。」傷之至矣。顏魯公請立放生池表雲：「一日三朝，大明天子之孝；問安視膳，不改家人之禮。」東坡以為彼知肅宗有愧於是也。黃魯直題磨崖碑，尤為深切。「撫軍監國太子事，何乃趣取大物為？事有至難天幸耳，上皇局脊還京師。南內淒涼幾苟活，高將軍去事尤危。臣結舂陵二三策，臣甫杜鵑再拜詩。安知忠臣痛至骨，世上但賞瓊琚詞！」所以揭表肅宗之罪，極矣。","sortOrder":23},
  {"id":"s_work_dtbt_69_24","chapterId":"ch_work_dtbt_69","text":"孫馬兩公所言","sortOrder":24},
  {"id":"s_work_dtbt_69_25","chapterId":"ch_work_dtbt_69","text":"盧照鄰有疾，問孫思邈曰：「高醫愈疾奈何？」答曰：「天有四時五行，寒暑迭居，和為雨，怒為風，凝為雪霜，張為虹蜺，天常數也。人之四支五藏，一覺一寐，吐納往來，流為榮衞，章為氣色，發為音聲，人常數也。陽用其形，陰用其精，天人所同也。失則烝生熱，否生寒，結為瘤贅，陷為癰疽，奔則喘乏，竭則焦槁，發乎面，動乎形。天地亦然，五緯縮贏，孛彗飛流，其危胗也。寒暑不時，其烝否也。石立土踴，是其瘤贅。山崩土陷，是其癰疽。奔風暴雨，其喘乏。川瀆竭涸，其焦槁。高醫導以藥石，救以砭劑，聖人和以至德，輔以人事，故體有可愈之疾，天有可振之災。」睿宗召司馬子微問其術，對曰：「為道日損，損之又損，以至於無為。夫心目所知見，每損之尚不能已，况攻異端，而增智慮哉！」帝曰：「治身則爾，治國若何？」曰：「國猶身也，故遊心於淡，合氣於漠，與物自然，而無私焉，而天下治。」孫公、司馬所言，皆至道妙理之所寓，治心養性，宜無出此者矣。","sortOrder":25},
  {"id":"s_work_dtbt_69_26","chapterId":"ch_work_dtbt_69","text":"元微之詩","sortOrder":26},
  {"id":"s_work_dtbt_69_27","chapterId":"ch_work_dtbt_69","text":"唐書藝文志元稹長慶集一百卷，小集十卷，而傳於今者，惟閩、蜀刻本，為六十卷。三館所藏，獨有小集。文惠公鎮越，以其舊治，而文集蓋缺，乃求而刻之。外春遊一篇雲：「酒戶年年減，山行漸漸難。欲終心懶慢，轉恐興闌散。鏡水波猶冷，稽峯雪尚殘。不能辜物色，乍可怯春寒。遠目傷千里，新年思萬端。無人知此意，閑凭小闌幹。」白樂天書之，題雲「元相公春遊」。錢思公藏其真跡，穆父守越時，摹刻於蓬萊閣下，今不復存。集中逸此詩，文惠為列之於集外。李端民平叔嘗和其韻寄公雲：「東閣經年別，窮愁客路難。望塵驚嶽峙，懷舊各雲散。茵醉恩逾厚，檣歌興未殘。馮唐嗟已老，范叔敢言寒。玉燭調魁柄，陽春在筆端。應憐掃門役，白首滯江幹。」樂天所書，予少時得其石刻，後亦失之。","sortOrder":27},
  {"id":"s_work_dtbt_69_28","chapterId":"ch_work_dtbt_69","text":"諫繚綾戲龍羅","sortOrder":28},
  {"id":"s_work_dtbt_69_29","chapterId":"ch_work_dtbt_69","text":"李德裕為浙西觀察使，穆宗詔索盤縧繚綾千匹，德裕奏言：「立鵝、天馬、盤縧、掬豹，文彩怪麗，惟乘輿當御，今廣用千匹，臣所未諭。」優詔為停。崇寧間，中使持御劄至成都，令轉運司織戲龍羅二千，繡旗五百，副使何常奏：「旗者，軍國之用，敢不奉詔。戲龍羅唯供御服，日衣一匹，歲不過三百有奇，今乃數倍，無益也。」詔獎其言，為減四之三。以二事觀之，人臣進言於君，切而不訐，蓋無有不聽者。何常所論，甚與德裕相類雲。","sortOrder":29},
  {"id":"s_work_dtbt_69_30","chapterId":"ch_work_dtbt_69","text":"詳正學士","sortOrder":30},
  {"id":"s_work_dtbt_69_31","chapterId":"ch_work_dtbt_69","text":"唐太宗時，命祕書監魏徵寫四部羣書，將藏內府，置讎正二十員。後又詔虞世南、顏師古踵領之，功不就。顯慶中罷讎正官，使散官隨番刊正。後詔東臺侍郎趙仁本等，充使檢校，置詳正學士以代散官，此名甚雅，不知何時罷去。然祕省自有校書郎、正字，使正名責實足矣。紹興中以貴臣提舉秘書省，而置編定書籍官二員，亦其類也。","sortOrder":31},
  {"id":"s_work_dtbt_69_32","chapterId":"ch_work_dtbt_69","text":"容齋五筆","sortOrder":32},
  {"id":"s_work_dtbt_70_1","chapterId":"ch_work_dtbt_70","text":"卷第三(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_70_2","chapterId":"ch_work_dtbt_70","text":"人生五計","sortOrder":2},
  {"id":"s_work_dtbt_70_3","chapterId":"ch_work_dtbt_70","text":"朱新仲舍人常雲：「人生天地間，壽夭不齊，姑以七十為率：十歲為童兒，父母膝下，視寒暖燥濕之節，調乳哺衣食之宜，以須成立，其名曰生計；二十為丈夫，骨強志健，問津名利之場，秣馬厲兵，以取我勝，如驥子伏櫪，意在千里，其名曰身計；三十至四十，日夜註思，擇利而行，位欲高，財欲厚，門欲大，子息欲盛，其名曰家計；五十之年，心怠力疲，俯仰世間，智術用盡，西山之日漸逼，過隙之駒不留，當隨緣任運，息念休心，善刀而藏，如蠶作繭，其名曰老計；六十以往，甲子一周，夕陽銜山，倏爾就木，內觀一心，要使絲毫無慊，其名曰死計。」朱公每以語人以身計則喜，以家計則大喜，以老計則不答，以死計則大笑，且曰：「子之計拙也。」朱既不勝笑者之衆，則亦自疑其計之拙，曰：「豈皆惡老而諱死邪？」因為南華長老作大死庵記，遂識其語。予之年齡逾七望八，當以書諸紳雲。","sortOrder":3},
  {"id":"s_work_dtbt_70_4","chapterId":"ch_work_dtbt_70","text":"瀛莫間二禽","sortOrder":4},
  {"id":"s_work_dtbt_70_5","chapterId":"ch_work_dtbt_70","text":"瀛、莫二州之境，塘濼之上有禽二種。其一類鵠，色正蒼而喙長，凝立水際不動，魚過其下則取之，終日無魚，亦不易地。名曰信天緣。其一類鶩，奔走水上，不閒腐草泥沙，唼唼然必盡索乃已，無一息少休。名曰漫畫。信天緣若無能者，乃與漫畫均度一日無飢色，而反加壯大。二禽皆稟性所賦，其不同如此。","sortOrder":5},
  {"id":"s_work_dtbt_70_6","chapterId":"ch_work_dtbt_70","text":"士大夫避父祖諱","sortOrder":6},
  {"id":"s_work_dtbt_70_7","chapterId":"ch_work_dtbt_70","text":"國朝士大夫，除官避父祖名諱，蓋有不同。不諱嫌名，二名不偏諱，在禮固然，亦有出於一時恩旨免避，或旋為改更者。建隆創業之初，侍衞帥慕容彥釗、樞密使吳廷祚皆拜使相，而彥釗父名章，廷祚父名璋，製麻中為改同中書門下平章事為同二品。紹興中，沈守約、湯進之二丞相，父皆名舉，於是改提舉書局為提領。自餘未有不避者。呂希純除著作郎，以父名公著而辭。然富韓公之父單名言，而公以右正言知製誥，韓保樞之子忠憲公億，孫絳、縝，皆歷位樞密，未嘗避。豈別有說乎？","sortOrder":7},
  {"id":"s_work_dtbt_70_8","chapterId":"ch_work_dtbt_70","text":"元正父子忠死","sortOrder":8},
  {"id":"s_work_dtbt_70_9","chapterId":"ch_work_dtbt_70","text":"唐安祿山表權皋入幕府，皋度祿山且叛，以其猜虐不可諫，欲行，慮禍及親，因獻俘京師，在道詐死，既唅斂而逸去。皋母謂實死，慟哭感行路，故祿山不之虞，歸其母。皋潛奉侍晝夜南奔。既渡江而祿山反。天下聞其名，爭取以為屬。甄濟居青巖山，諸府五辟，詔十至，堅臥不起。安祿山入朝，求濟於玄宗，授范陽掌書記，濟不得已而起。察祿山有反謀，不可諫，因謁歸，陽歐血不支，舁歸舊廬。祿山反，使封刀召之。曰：「即不起，斷其首。」濟引頸待之。使以實病告，慶緒復使強輿至東都。會廣平王平東都，詣軍門上謁，肅宗使汚賊官羅拜，以愧其心。唐書列二人於卓行傳，褒之至矣。有元正者，在河南幕府，史思明陷河、洛，輦父匿山中。賊以名召之，正度事急，謂弟曰：「賊祿不可養親，彼利吾名，難免矣。然不汚身而死，吾猶生也。」賊既得，誘以高位，瞋目固拒，兄弟皆遇害。父聞，仰藥死。事平，詔錄伏節十一姓，而正為冠。皋、濟之終，與正皆贈祕書少監。予謂皋、濟得生，而正一門皆幷命，故當時以為伏節之冠。而唐史不列之忠義、卓行中，但附見於其祖萬頃文藝之末，資治通鑑亦不載其事，使正之名寂寥不章顯，為可恨也！白樂天作張諴碑雲：「以左武衞參軍分司東都，屬安祿山陷覆洛京，以偽職淫刑，脅劫士庶，公與同官盧巽潛遁於陸渾山，食木實，飲泉水者二年，訖不為逆命所汚。肅宗詔河南搜訪不仕賊庭、隱藏山穀者，得六人以應詔，公與巽在焉。繇是名節聞於朝，優詔褒美，特授密縣主簿。」","sortOrder":9},
  {"id":"s_work_dtbt_70_10","chapterId":"ch_work_dtbt_70","text":"蕭穎士風節","sortOrder":10},
  {"id":"s_work_dtbt_70_11","chapterId":"ch_work_dtbt_70","text":"蕭穎士為唐名人，後之學者但稱其才華而已，至以笞楚童奴為之過。予反復考之，蓋有風節識量之士也。為集賢校理，宰相李林甫欲見之，穎士不詣，林甫怒其不下己。後召詣史館，又不屈，愈見疾，至免官更調河南參軍。安祿山寵恣，穎士陰語柳幷曰：「胡人負寵而驕，亂不久矣。東京其先陷乎！」即託疾去。祿山反，往見河南採訪使郭納，言禦守計，納不用。嘆曰：「肉食者以兒戲禦劇賊，難矣哉！」聞封常清陳兵東京，往觀之，不宿而還，身走山南，節度使源洧欲退保江陵，穎士說曰：「襄陽乃天下喉襟，一日不守，則大事去矣。公何遽輕土地，取天下笑乎？」洧乃按甲不出。洧卒，往客金陵，永王璘召之，不見。劉展反，圍雍丘，副大使李承式遣兵往救，大宴賓客，陳女樂。穎士曰：「天子暴露，豈臣下盡歡時邪！夫投兵不測，乃使觀聽華麗，誰致其死哉？」弗納。穎士之言論操持如此，今所稱之者淺矣。李太白，天下士也，特以墮永王亂中，為終身累。穎士，永王召而不見，則過之焉。","sortOrder":11},
  {"id":"s_work_dtbt_70_12","chapterId":"ch_work_dtbt_70","text":"石尤風","sortOrder":12},
  {"id":"s_work_dtbt_70_13","chapterId":"ch_work_dtbt_70","text":"石尤風，不知其義，意其為打頭逆風也。唐人詩好用之。陳子昂入峽苦風雲：「故鄉今日友，歡會坐應同。寧知巴峽路，辛苦石尤風。」戴叔倫送裴明州雲：「瀟水連湘水，千波萬浪中。知君未得去，慚愧石尤風。」司空文明留盧秦卿雲：「知有前期在，難分此夜中。無將故人酒，不及石尤風。」計南朝篇詠，必多用之，未暇憶也。","sortOrder":13},
  {"id":"s_work_dtbt_70_14","chapterId":"ch_work_dtbt_70","text":"江楓雨菊","sortOrder":14},
  {"id":"s_work_dtbt_70_15","chapterId":"ch_work_dtbt_70","text":"作詩要有來處，則為淵原宗派。然字字執泥，又為拘澀。予於此學，無自得之見，少年時，尤失之琱琢。記一聯，初雲：「雨深荒病菊，江冷落愁楓。」後以其太險，改為：「雨深人病菊，江冷客愁楓。」比前句微有蘊藉。蓋取崔信明「楓落吳江冷」、杜老「雨荒深院菊」、「南菊再逢人臥病」、嚴武「江頭赤葉楓愁客」，合而用之。乃如補衲衣裳，殊為可笑。聊書之以示兒輩雲。","sortOrder":15},
  {"id":"s_work_dtbt_70_16","chapterId":"ch_work_dtbt_70","text":"開元宮嬪","sortOrder":16},
  {"id":"s_work_dtbt_70_17","chapterId":"ch_work_dtbt_70","text":"自漢以來，帝王妃妾之多，唯漢靈帝、吳歸命侯、晉武帝、宋蒼梧王、齊東昏、陳後主。晉武至於萬人。唐世明皇為盛，白樂天長恨歌雲「後宮佳麗三千人」，杜子美劍器行雲「先帝侍女八千人」，蓋言其多也。新唐史所敍，謂開元、天寶中，宮嬪大率至四萬。嘻，其甚矣！隋大業離宮遍天下，所在皆置宮女。故裴寂為晉陽宮監，以私侍高祖。及高祖義師經過處，悉罷之。其多可想。","sortOrder":17},
  {"id":"s_work_dtbt_70_18","chapterId":"ch_work_dtbt_70","text":"相里造","sortOrder":18},
  {"id":"s_work_dtbt_70_19","chapterId":"ch_work_dtbt_70","text":"唐內侍監魚朝恩，怙貴誕肆，凡詔會羣臣計事，折愧坐人，出其上。雖宰相元載辯強，亦拱默。唯禮部郎中相里造、殿中侍御史李衎，酬詰往返，未始降屈。朝恩不懌，黜衎以動造，又謀將易執政，以震朝廷，乃會百官都堂，且言：「今水旱不時，屯軍饋運困竭，天子臥不安席，宰相何以輔之？不退避賢路，尚何賴乎？」宰相俯首，坐皆失色。造徙坐從之，因曰：「陰陽不和，五穀踴貴，皆軍容事，宰相何與哉？且軍帑不散，故天降之沴。今京師無事，六軍可相維鎮，又屯十萬，饋糧所以不足，百司無稍食，軍容為之。宰相行文書而已，何所歸罪？」朝恩拂衣去，曰：「南衙朋黨且害我。」此段載於唐史宦者傳中，不能記相里造之本末。予謂造當閹寺威權震主，生殺在手之時，以區區一郎吏，而抗身與為敵，後來名人議論，及敍列忠言鯁詞，未見有稱述之者，通鑑亦不書，聊紀於此，以章潛德。同時劉給事爭幸河中，亦然。","sortOrder":19},
  {"id":"s_work_dtbt_70_20","chapterId":"ch_work_dtbt_70","text":"先公詩詞","sortOrder":20},
  {"id":"s_work_dtbt_70_21","chapterId":"ch_work_dtbt_70","text":"先忠宣公好讀書，北困松漠十五年，南謫嶺表九年，重之以風淫末疾，而翻閱書策，早暮不置，尤熟於杜詩。初歸國到闕，命邁作謝賜物一劄子，竄定兩句雲：「已為死別，偶遂生還。」謂邁曰：「此雖不必泥出處，然有所本更佳。東坡海外表雲：『子孫慟哭於江邊，已為死別。』杜老羌村詩雲：『世亂遭飄蕩，生還偶然遂。』正用其語。」在鄉邦日，招兩使者會集，出所將宣和殿書畫舊物示之。提刑洪慶善作詩曰：「願公十襲勿浪出，六丁取將飛辟歷！」辟歷二字如古文，不從雨。公和之曰：「萬里懷歸為公出，往事宣和空歷歷！」邁請其意，曰：亦出杜詩「歷歷開元事，分明在目前」也。紹興丁巳，所在始歌江梅引詞，不知為誰人所作，己未、庚申年，北庭亦傳之。至於壬戌，公在燕，赴張總侍御家宴，侍妾歌之，感其「念此情，家萬里」之句，愴然曰：「此詞殆為我作！」既歸不寐，遂用韻賦四闋。時在囚拘中，無書可檢，但有初學記、韓杜蘇白樂天集，所引用句語，一一有來處。北方不識梅花，士人罕有知梅事者，故皆註所出。","sortOrder":21},
  {"id":"s_work_dtbt_70_22","chapterId":"ch_work_dtbt_70","text":"其一，憶江梅雲：「天涯除館憶江梅。幾枝開。使南來。還帶餘杭春信到燕臺。准擬寒英聊慰遠，隔山水，應銷落，赴愬誰？　空恁遐想笑摘蕊。斷回腸，思故里。漫彈綠綺。引三弄，不覺魂飛。更聽胡笳哀怨淚沾衣。亂插繁華須異日，待孤諷，怕東風，一夜吹。」元註引杜公：「忽憶兩京梅發時。」「胡笳在樓上，哀怨不堪聽。」「安得健步移遠梅，亂插繁華向晴昊！」樂天憶杭州梅花：「三年閑悶在餘杭，曾為梅花醉幾場。」車駕時在臨安。柳子厚：「欲為萬里贈，杳杳山水隔。寒英坐銷落，何用慰遠客？」江總：「桃李佳人欲相照，摘蕊牽花來並笑。」高適：「遙憐故人思故鄉，梅花滿枝空斷腸！」盧仝：「含愁更奏綠綺琴，相思一夜梅花發。」劉方平：「晚歲芳梅樹，繁華四面同。東風吹漸落，一夜幾枝空。」東坡：「忽見早梅花，不飲但孤諷。」「一夜東風吹石裂，半隨飛雪度關山。」","sortOrder":22},
  {"id":"s_work_dtbt_70_23","chapterId":"ch_work_dtbt_70","text":"其二，訪寒梅雲：「春還消息訪寒梅。賞初開。夢吟來。映雪銜霜清絕繞風臺。可怕長洲桃李妒，度香遠，驚愁眼，欲媚誰？　曾動詩興笑冷蕊。效少陵，慚下里。萬株連綺。嘆金穀，人墜鶯飛。引領羅浮翠羽幻青衣。月下花神言極麗，且同醉，休先愁，玉笛吹。」註引李太白：「聞道春還未相識，走傍寒梅訪消息。」「綠珠樓下梅花滿，今日曾無一枝在。」江總：「金穀萬株連綺甍，梅花隱處藏嬌鶯。」何遜：「銜霜當路發，映雪擬寒開。枝橫却月觀，花繞凌風臺。」杜公：「東閤官梅動詩興，還如何遜在揚州。」「未將梅蕊驚愁眼，要取椒花媚遠天。」「巡簷索共梅花笑，冷蕊疏枝半不禁。」樂天：「賞自初開直至落。」「莫怕長洲桃李妒，明年好為使君開。」王昌齡夢中作梅花詩。梁簡文賦「香隨風而遠度」，及趙師雄羅浮見美人在梅花下有翠羽啾嘈相顧詩雲：「學妝欲待問花神。」崔櫓：「初開已入雕梁畫，未落先愁玉笛吹。」","sortOrder":23},
  {"id":"s_work_dtbt_70_24","chapterId":"ch_work_dtbt_70","text":"其三，憐落梅雲：「重閨佳麗最憐梅。牖春開，學妝來。爭粉翻光何遽落梳臺。笑坐雕鞍歌古曲，催玉柱，金巵滿，勸阿誰？　貪為結子藏暗蕊。斂蛾眉，隔千里。舊時羅綺。已零散，沈謝雙飛。不見嬌姿真悔著單衣。若作和羹休訝晚，墮煙雨，任春風，片片吹。」註引梁簡文賦：「重閨佳麗，貌婉心嫻，憐早花之驚節，訝春光之遣寒。」「顧影丹墀，弄此嬌姿，洞開春牖，四卷羅帷。春風吹梅畏落盡，賤妾為此斂蛾眉。」又：「爭樓上之落粉，奪機中之織素。」梁王詩：「翻光同雪舞。」鮑泉：「縈窗落梳臺。」江總：「滿酌金巵催玉柱，落梅樹下宜歌舞。」太白：「千金駿馬邀少妾，笑坐雕鞍歌落梅。」古曲有落梅花。又：「片片吹落春風香。」謝莊賦：「隔千里兮共明月。」庾信：「早知覓不見，真悔著衣單！」東坡：「抱叢暗蕊初含子，玉妃謫墮煙雨村。」王建：「自是桃花貪結子。」","sortOrder":24},
  {"id":"s_work_dtbt_70_25","chapterId":"ch_work_dtbt_70","text":"第四篇失其稿。每首有一笑字，北人謂之「四笑江梅引」，爭傳寫焉。","sortOrder":25},
  {"id":"s_work_dtbt_70_26","chapterId":"ch_work_dtbt_70","text":"州縣名同","sortOrder":26},
  {"id":"s_work_dtbt_70_27","chapterId":"ch_work_dtbt_70","text":"晉、宋以來，置立州郡，惟以多為貴。先是中原陷胡、羯，本土遺民，或僑寓南方，故即其所聚為立郡。而方伯所治之州，亦仍舊名。如南徐、南兗、南豫、南雍州、南蘭陵、南東海、南瑯邪、南東莞、南魯郡，其類不一。魏、周在北，亦如此。隋、唐不復然。國朝之製，州名或同，則增一字以別之。若河北有雄州、恩州，故廣東者增南字；蜀有劍州，故福建者，亦增南字。以至西和、西安州亦然。其聲音頗同，患於舛誤，則俗間稱呼，自加上下東西為別。故稱嶽為上嶽，鄂為下鄂。清州與青類，稱為北清；郢州與潁類，稱為西郢；融州與容類，稱為西融者是也。若縣邑則不問，今河南、靜江府、鞏州皆有永寧縣，饒、邛、衡州皆有安仁縣，蔡、英之真陽，廬、汝之梁，光、台之仙居，臨安、建昌之新城，越、筠之新昌，婺、蜀之永康，處、吉之龍泉，嚴、池之建德，渭、秀之華亭，信、吉之永豐，郴、興國之永興，衢、嘉之龍遊，施、臨江之清江，洪、萬之武寧，福、循之長樂，郴、連之桂陽，福、桂之永福是也。","sortOrder":27},
  {"id":"s_work_dtbt_70_28","chapterId":"ch_work_dtbt_70","text":"三衙軍製","sortOrder":28},
  {"id":"s_work_dtbt_70_29","chapterId":"ch_work_dtbt_70","text":"乾道四年正月，邁為中書舍人，因入對，論三衙軍製名稱不正：「以祖宗之製論之，軍職之大者，凡八等。除都指揮使或不常置外，曰殿前副都指揮使、馬軍副都指揮使、步軍副都指揮使，曰殿前都虞候、馬軍都虞候、步軍都虞候，曰捧日天武四廂都指揮使、龍神衞四廂都指揮使，秩秩有序，若登梯然，不可一級輒廢。一或有闕，即以功次遞遷。降此而下，則分營、分廂，各置都副指揮使，如捧日左廂第一軍、天武右廂第二軍之類。邊境有事，命將討捕，則旋立總管、鈐轄、都監之名，使各將其所部以出。事已，則復初。累聖相承，皆用此術，以製軍詰禁。自南渡以後，觸事草創，於是三帥之資淺者，始有主管某司公事之稱。而都虞候以下，不復設置，乃以宿衞虎士而與在外諸軍同其名，以統製、統領為之長。又使遙帶外路總管、鈐轄。考之舊製則非法，稽之事體則非是。以陛下聖明，能知人善任，使所謂爪牙之士，豈無十數人以待用者？若法祖宗之製，正三衙之名，改諸軍為諸廂，改統製以下為都虞候、指揮使，使宿衞之職預有差等，士卒之心明有所係，異時拜將，必無一軍皆驚之舉。於以銷壓未萌，循名責實，則環衞將軍雖不置可也。乞下樞密院討論故實，圖議其當，恐或可以少贊布昭聖武之意。」讀劄子畢，孝宗甚喜，即批付樞密院。是時，知院虞允文使四川，同知劉珙不樂曰：「舍人要如何行？」對之以「但隨所見敷陳，若施行與否，自係廟堂處分」。竟寢不行。後閱華陽集，王珪撰高瓊神道碑雲：「王為殿前都指揮使，管軍員闕，兼領二司，王乃言曰：『臣老矣，如有負薪之憂，誰為可任者？先朝自殿前而下，各置副都指揮使，及都虞候，常有十人，職近事親，易以第進，又使士卒預識其威名，緩急臨戎，上下得以附習，此軍製之大要也。』有旨從之。」據瓊所言如此，正合前說。","sortOrder":29},
  {"id":"s_work_dtbt_70_30","chapterId":"ch_work_dtbt_70","text":"歐陽公勛封贈典","sortOrder":30},
  {"id":"s_work_dtbt_70_31","chapterId":"ch_work_dtbt_70","text":"吉州新刊歐陽公文集，於年譜下盡載官爵、製詞，無一遺落。考之今製，多有不合。雖非事之所以損益，謾書於策，且記典章隨時之異雲。公自太子中允初加勛，便得騎都尉，越過驍、武、飛、雲四級。自龍圖閣直學士初封爵，便得信都縣子，越過男一等。翰林學士加恩而得五百戶，初加實封，便得二百戶。及罷政，為觀文學士，遇郊而加食邑五百戶，實封二百戶。薨之後，以子登朝，遇大禮，自太子太師合贈司空，而躐贈太尉，蓋超空、徒、保、傅四官。再贈即為太師，仍封國公。今殊不然，除勛官既罷外，侍從初封，亦從縣男為始，每加不過三百戶。(待製侍郎只二百。)初得實封財百戶。執政去位，但與侍從同，均為虛邑三百而已。身後加贈，只單轉一官，兩子升朝，乃進二官，雖三四人亦不增，未有宮師直贈太尉者。(今太傅也。)又公任知製誥、知潁州轉官而與直龍圖閣、知亳州王洙同一詞。唐書成，進秩，五人同製。公與宋景文公、范文忠公、王忠簡公皆帶從官職，而宋次道乃集賢校理耳。","sortOrder":31},
  {"id":"s_work_dtbt_70_32","chapterId":"ch_work_dtbt_70","text":"嘉祐四真","sortOrder":32},
  {"id":"s_work_dtbt_70_33","chapterId":"ch_work_dtbt_70","text":"嘉祐中富韓公為宰相，歐陽公在翰林，包孝肅公為御史中丞，胡翼之侍講在太學，皆極天下之望。一時士大夫相語曰：「富公真宰相，歐陽永叔真翰林學士，包老真中丞，胡公真先生。」遂有四真之目。歐陽公之子發、棐等，敍公事跡，載此語，可謂公言。","sortOrder":33},
  {"id":"s_work_dtbt_70_34","chapterId":"ch_work_dtbt_70","text":"五方老人祝聖壽","sortOrder":34},
  {"id":"s_work_dtbt_70_35","chapterId":"ch_work_dtbt_70","text":"聖節所用祝頌樂語，外方州縣各當筵致語一篇，又有王母像者。若教坊，唯祝聖而已。歐陽公集，乃載五方老人祝壽文五首，其東方曰：「但某太山老叟、東海真仙，溜穿石而曾究始終，松避雨而備知歲月。羲氏定三百六日，嘗守寅賓之官；夷吾紀七十二君，盡睹登封之事。遇安期而遺棗，笑方朔之偷桃。風入律而來自巖前，斗指春而光臨洞口。昔漢武帝嘗懷三島之勝遊，有羨門生欲謁巨公於昭代，今則紫庭降聖，華渚開祥，遠離朝日之方，來展望雲之懇。千八百國，鹹歸至治之風；億萬斯年，共禱無疆之壽。」其頌只四句，西中南北方皆然。集中不雲何處所作，今無復用之。","sortOrder":35},
  {"id":"s_work_dtbt_70_36","chapterId":"ch_work_dtbt_70","text":"容齋五筆","sortOrder":36},
  {"id":"s_work_dtbt_71_1","chapterId":"ch_work_dtbt_71","text":"卷第四(九則)","sortOrder":1},
  {"id":"s_work_dtbt_71_2","chapterId":"ch_work_dtbt_71","text":"作詩旨意","sortOrder":2},
  {"id":"s_work_dtbt_71_3","chapterId":"ch_work_dtbt_71","text":"詩三百篇中，其譽婦人者至多。如敍宗姻之貴者，若「平王之孫，齊侯之子」，「汾王之甥，蹶父之子」，「齊侯之子，衞侯之妻，東宮之妹，邢侯之姨，譚公維私」。夸服飾之盛者，若「副笄六珈」，「如山如河」，「玉之瑱也，象之揥也」。贊容色之美者，若「唐棣之華」，「華如桃李」，「鬒髮如雲」，「手如柔荑，膚如凝脂，領如蝤蠐，齒如瓠犀，螓首蛾眉。巧笑倩兮，美目盼兮」，「顏如舜華」，「洵美且都」。語嫁聘之侈者，若「百兩彭彭，八鸞鏘鏘，不顯其光。諸娣從之，祁祁如雲，爛其盈門」。其詞可謂盡善矣。魏、晉、六朝，流連光景，不可勝述。唐人播之歌詩，固亦極摯。若「態濃意遠淑且真，肌理細膩骨肉勻。繡羅衣裳照暮春，蹙金孔雀銀麒麟」，「翠微（勹內盍）葉垂鬢唇，珠壓腰衱穩稱身」，「深宮高樓入紫清，金作蛟龍盤繡楹。佳人當窗弄白日，絃將手語彈鳴箏」，「回眸一笑百媚生，六宮粉黛無顏色」，「後宮佳麗三千人，三千寵愛在一身」，「金屋妝成嬌侍夜，玉樓宴罷醉和春」，「樓上樓前盡珠翠，眩轉熒煌照天地」。此皆李、杜、元、白之麗句也。予獨愛朱慶餘閨意一絕句上張籍水部者，曰：「洞房昨夜停紅燭，待曉堂前拜舅姑。妝罷低聲問夫婿，畫眉深淺入時無？」細味此章，元不談量女之容貌，而其華豔韶好，體態溫柔，風流醞藉，非第一人不足當也。歐陽公所謂：「狀難寫之景，如在目前，含不盡之意，見於言外，然後為工。」斯之謂也。慶餘名可久，以字行。登寶曆進士第，而官不達。著錄於藝文志者，只一卷，予家有之，他不逮此。張籍酬其篇雲：「越女新妝出鏡心，自知明豔更沉吟。齊紈未是人間貴，一曲菱歌直萬金。」其愛之重之，可見矣。然比之慶餘，殊為不及。","sortOrder":3},
  {"id":"s_work_dtbt_71_4","chapterId":"ch_work_dtbt_71","text":"平王之孫","sortOrder":4},
  {"id":"s_work_dtbt_71_5","chapterId":"ch_work_dtbt_71","text":"周南、召南之詩，合為二十有五篇。自漢以來為之說者，必系之文、武、成、康，故不無牴牾。如何彼襛矣，乃美王姬之詩，其辭有：「平王之孫，齊侯之子」兩句，翻覆再言之。毛公箋雲：「武王女，文王孫，適齊侯之子。」鄭氏不立說。考其意，蓋以平王為平正之王，齊侯為齊一之侯，若所謂武王載旆，成王之孚，成王不敢康，非指武與成者。然證諸春秋經，魯莊公元年，當周莊王之四年，齊襄公之五年，書曰：「單伯送王姬。」繼之以「築王姬之館於外」，又繼之以「王姬歸於齊」。杜預註雲：「王將嫁女於齊，命魯為主。莊公在諒闇，慮齊侯當親迎，不忍便以禮接於廟，故築舍於外。」末書「歸於齊」者，終此一事也。十一年又書「王姬歸於齊」，傳言「齊侯來逆共姬」，乃桓公也。莊王為平王之孫，則所嫁王姬當是姊妹，齊侯之子，即襄公、桓公也。二者必居一於此矣。明白如是，而以為武王女，文王孫，於義何取？","sortOrder":5},
  {"id":"s_work_dtbt_71_6","chapterId":"ch_work_dtbt_71","text":"毛詩語助","sortOrder":6},
  {"id":"s_work_dtbt_71_7","chapterId":"ch_work_dtbt_71","text":"毛詩所用語助之字，以為句絕者，若之、乎、焉、也、者、雲、矣、爾、兮、哉，至今作文者皆然。他如只、且、忌、止、思、而、何、斯、旃、其之類，後所罕用。「只」字，如「母也天只，不諒人只」。「且」字，如「椒聊且，遠條且」，「狂童之狂也且」，「既亟只且」。「忌」字，如「叔善射忌，又良御忌」。「止」字，如「齊子歸止」，「曷又懷止」，「女心傷止」。「思」字，如「不可求思」，「爾羊來思」，「今我來思」。「而」字，如「俟我於著乎而，充耳以素乎而」。「何」字，如「如此良人何」，「如此粲者何」。「斯」字，如「恩斯勤斯，鬻子之閔斯」，「彼何人斯」。「旃」字，如「舍旃舍旃」。「其」字，音基。如「夜如何其」，「子曰何其」。皆是也。「忌」唯見於鄭詩，「而」唯見於齊詩。楚詞大招一篇全用「只」字。太玄經：「其人有輯杭，可與過其。」至於「些」字，獨招魂用之耳！","sortOrder":7},
  {"id":"s_work_dtbt_71_8","chapterId":"ch_work_dtbt_71","text":"東坡文章不可學","sortOrder":8},
  {"id":"s_work_dtbt_71_9","chapterId":"ch_work_dtbt_71","text":"東坡作蓋公堂記雲：「始吾居鄉，有病寒而欬者，問諸醫，醫以為蠱，不治且殺人。取其百金而治之，飲以蠱藥，攻伐其腎腸，燒灼其體膚，禁切其飲食之美者。期月而百疾作，內熱惡寒而欬不已，纍然真蠱者也。又求於醫，醫以為熱，授之以寒藥，旦朝吐之，莫夜下之，於是始不能食。懼而反之，則鍾乳、烏喙，雜然並進，而漂疽、癰疥、眩瞀之狀，無所不至。三易醫而病愈甚。里老父教之曰：『是醫之罪，藥之過也。子何疾之有？人之生也，以氣為主，食為輔。今子終日藥不釋口，臭味亂於外，而百毒戰於內，勞其主，隔其輔，是以病也。子退而休之，謝醫却藥，而進所嗜，氣全而食美矣。則夫藥之良者，可以一飲而效。』從之，期月而病良已。昔之為國者亦然。吾觀夫秦自孝公以來，至於始皇，立法更製，以鐫磨鍛鍊其民，可謂極矣。蕭何、曹參親見其斵喪之禍，而收其民於百戰之餘，知其厭苦、憔悴、無聊，而不可與有為也，是以一切與之休息，而天下安。」是時，熙寧中，公在密州，為此說者，以諷王安石新法也。其議論病之三易，與秦、漢之所以興亡治亂，不過三百言而盡之。","sortOrder":9},
  {"id":"s_work_dtbt_71_10","chapterId":"ch_work_dtbt_71","text":"張文潛作藥戒，僅千言，雲：「張子病痞，積於中者，伏而不能下，自外至者，捍而不能納，從醫而問之。曰：『非下之不可。』歸而飲其藥，既飲而暴下。不終日，而向之伏者散而無餘，向之捍者柔而不支。焦膈導達，呼吸開利，快然若未始有疾者。不數日，痞復作，投以故藥，其快然也亦如初。自是逾月而痞五作五下，每下輒愈。然張子之氣，一語而三引，體不勞而汗，股不步而慄，膚革無所耗於外，而其中薾然，莫知其所來。聞楚之南，有良醫焉，往而問之。醫嘆曰：『子無嘆是薾然者也。天下之理，其甚快於予心者，其末必有傷，求無傷於終者，則初無望於快吾心。痞橫乎胸中，其累大矣。擊而去之，不須臾而除甚大之累，和平之物不能為也。必將擊搏震撓而後可，其功未成而和氣已病。則子之痞，凡一快者，子之和一傷矣。不終月而快者五，則和平之氣，不既索乎？且將去子之痞，而無害於和乎！子歸，燕居三月，而後予之藥可為也。』張子歸三月而復請之。醫曰：『子之氣少全矣！』取藥而授之。曰：『服之三月而疾少平，又三月而少康，終年而復常。且飲藥不得亟進。』張子歸而行其說。其初使人懣然遲之，蓋三投其藥而三反之也。然日不見其所攻，久較則月異而時不同，蓋終歲而疾平。張子謁醫謝，而問其故。醫曰：『是治國之說也。獨不見秦之治民乎？敕之以命，捍而不聽令；勤之以事，放而不畏法。令之不聽，治之不變，則秦之民嘗痞矣。商君見其痞也，厲以刑法，威以斬伐，痛剗而力鋤之。流蕩四達，無敢或拒，痞嘗一快矣。至於二世，凡幾痞而幾快矣。積快而不已，而秦之四支，枵然徒有其物而已。民心日離，而君孤立於上，故匹夫大呼，不終日而百疾皆起，欲運其手足肩膂，而漠然不我應。故秦之亡者，是好為快者之過也。昔者先王之民，初亦嘗痞矣。先王不敢求快於吾心，陰解其亂，而除去其滯，使之悠然自趨於平安而不自知。於是政成教達，悠久而無後患。則餘之藥終年而愈疾者，蓋無足怪也。』」予觀文潛之說，盡祖蘇公之緒論，而千言之煩，不若三百言之簡也。故詳書之，俾作文立說者知所矜式。竊料蘇公之記，文潛必未之見，是以著此篇；若既見之，當不復屋下架屋也。","sortOrder":10},
  {"id":"s_work_dtbt_71_11","chapterId":"ch_work_dtbt_71","text":"韓文稱名","sortOrder":11},
  {"id":"s_work_dtbt_71_12","chapterId":"ch_work_dtbt_71","text":"歐陽公作文，多自稱予，雖說君上處亦然，三筆嘗論之矣。歐公取法於韓公，而韓不然。滕王閣記、袁公先廟為尊者所作，謙而稱名，宜也。至於徐泗掌書記壁記、科斗書後記、李虛中墓志之類，皆曰愈，可見其謙以下人。後之為文者所應取法也。","sortOrder":12},
  {"id":"s_work_dtbt_71_13","chapterId":"ch_work_dtbt_71","text":"棘寺棘卿","sortOrder":13},
  {"id":"s_work_dtbt_71_14","chapterId":"ch_work_dtbt_71","text":"今人稱大理為棘寺，卿為棘卿，丞為棘丞，此出周禮秋官：「朝士掌建邦外朝之法。左九棘，孤、卿、大夫位焉。右九棘，公、侯、伯、子、男位焉。」鄭氏註雲：「植棘以為位者，取其赤心而外刺也。棘於棗同。」棘之字，兩朿相並，棗之字，兩朿相承。此所言者，今之棗也。然孤、卿、大夫皆同之，則難以獨指大理。王製雲：「正以獄成，告於大司寇，大司寇聽之棘木之下。」料後人藉此而言。鄭註亦只引前說，此但謂其入朝立治之處，若以指刑部尚書亦可也。易坎卦「係用徽纆，寘於叢棘」，以居險阻囚執為詞，其義自別。","sortOrder":14},
  {"id":"s_work_dtbt_71_15","chapterId":"ch_work_dtbt_71","text":"晉代遺文","sortOrder":15},
  {"id":"s_work_dtbt_71_16","chapterId":"ch_work_dtbt_71","text":"故簏中得舊書一帙，題為晉代名臣文集。凡十四家，所載多不能全，真太山一毫芒耳。有張敏者，太原人，仕歷平南參軍、太子舍人、濟北長史。其一篇曰頭責子羽文，極為尖新。古來文士皆無此作，恐藝文類聚、文苑英華或有之，惜其泯沒不傳，謾采之以遺博雅君子。其序雲：「太原溫長仁、潁川荀景伯、范陽張茂先、士卿劉文生、南陽鄒潤甫、河南鄭思淵。餘友有秦生者，雖有姊夫之尊，少而狎之，同時昵好。張、荀之徒，數年之中，繼踵登朝，而此賢身處陋巷，屢沽而無善價，抗志自若，終不衰墮。為之慨然！又怪諸賢既已在位，曾無伐木嚶鳴之聲，又違王、貢彈冠之義，故因秦生容貌之盛，為頭責之文以戲之。幷以嘲六子焉。雖似諧謔，實有興也。」文曰：「維泰始元年，頭責子羽曰：『吾託為子頭，萬有餘日矣。大塊稟我以精，造我以形。我為子蒔髮膚，置鼻耳，安眉額，插牙齒。眸子橋光，雙權隆起。每至出入人間，遨遊市里，行者辟易，坐者竦跽。或稱君侯，或言將軍，捧手傾側，佇立踦（足區）。如此者，故我形之足偉也。子冠冕弗戴，金銀弗佩，艾以當笄，幍以代帶，百味弗嘗，食粟茹菜，歲暮年過，曾不自悔。子厭我形容，我賤子意態。若此者，必子行己累也。子遇我如讎，我視子如仇。居常不樂，兩者俱憂。何其鄙哉！子欲為仁賢耶？則當如咎陶、後稷、巫鹹、伊陟，保乂王家，永見封殖。子欲為名高耶？則當如許由、子臧、卞隨、務光，洗耳逃祿，千載流芳。子欲為遊說耶？則當如陳軫、蒯通、陸生、鄧公，轉禍為福，含辭從容。子欲為進趨耶？則當如賈生之求試，終軍之請使，砥礪鋒穎，以幹王事。子欲為恬淡耶？則當如老聃之守一，莊周之自逸，漠然離俗，志凌雲日。子欲為隱遁耶？則當如榮期之帶索，漁父之瀺灂，棲遲神嶽，垂餌巨壑。此一介之人，所以顯身成名者也。今子上不睎道德，中不效儒、墨，塊然窮賤，守此愚惑。察子之情，觀子之志，退不為處士，進無望三事。而徒玩日勞形，習為常人之所喜，不亦過乎？』子羽愀然深念而對曰：『凡所教勅，謹聞命矣。受性拘係，不聞禮義，誤以天幸，為子所寄。今子欲使吾為忠耶？當如包胥、屈平；欲使吾為信耶？則當殺身以成名；欲使吾為節耶？則當赴水火以全貞。此四者，人之所忌，故吾不敢造意。』頭曰：『子所謂天刑地網，剛德之尤。不登山抱木，則褰裳赴流。吾欲告爾以養性，誨爾以優遊。而與蟣蝨同情，不聽我謀。悲哉！俱御人體，而獨為子頭！且儗人其倫，喻子儕偶，曾不如太原溫顒，潁川荀禹，范陽張華，士卿劉許，南陽鄒湛，河南鄭詡。此數子者，或蹇吃無宮商，或尪陋希言語；或淹伊多姿態，或讙譁少智諝；或口如含膠飴，或頭如巾虀杵。而猶以文采可觀，意思詳序，攀龍附鳳，並登天府。夫（舌氐）痔得車，沉淵竊珠，豈若夫子，徒令唇舌腐爛，手足沾濡哉？居有事之世，而恥為權謀，譬猶鑿地抱甕，難以求富。嗟乎子羽！何異牢檻之熊，深阱之虎，石間餓蟹，竈中之鼠！事雖多，而見工甚少，宜其卷局煎蹙，至老無所睎也。支離其形者，猶能不困，命也夫，與子同處！』」其文九百餘言，頗有東方朔客難、劉孝標絕交論之體。集仙傳所載神女成公智瓊傳，見於太平廣記，蓋敏之作也。鄒湛姓名，因羊叔子而傳，而字曰潤甫，則見於此。","sortOrder":16},
  {"id":"s_work_dtbt_71_17","chapterId":"ch_work_dtbt_71","text":"漢武帝田蚡公孫弘","sortOrder":17},
  {"id":"s_work_dtbt_71_18","chapterId":"ch_work_dtbt_71","text":"尚論古人者，如漢史所書，於武帝則譏其好大喜功，窮奢極侈，置生民於塗炭；於田蚡則詆其負貴驕溢，以肺腑為相，殺竇嬰、灌夫；於公孫弘則雲：「性意忌，外寛內深，飾詐釣名，不為賢大夫所稱述。」然以予考之，三君臣者，實有大功於名教。自秦始皇焚書坑儒，六學散缺，高帝初興，未遑庠序之事，孝惠、高後時，公卿皆武力功臣，孝文好刑名，孝景不任儒。至於武帝，田蚡為丞相，黜黃、老刑名百家之言，延文學儒者以百數。帝詳延天下多聞之士，鹹登諸朝，令禮官勸學，講議洽聞，舉遺興禮，以為天下先。而公孫弘以治春秋為丞相，天下學士靡然鄉風。弘為學官，悼道之鬱滯，始請為博士官置弟子，郡國有秀才異等，輒以名聞。請著為令。而詩、書、易、禮之學，彬彬並興，使唐、虞三代以來稽古禮文之事，得以不廢。今之所以識聖人至道之要者，實本於此。史稱其「罷黜百家，表章六經，號令文章，煥焉可述」。蓋已不能盡其美。然則武帝奢暴，固貽患於一時；蚡、弘之為人，得罪於公論，而所以扶持聖教者，乃萬世之功也。平帝元始詔書，尚能稱弘之率下篤俗，但不及此雲。","sortOrder":18},
  {"id":"s_work_dtbt_71_19","chapterId":"ch_work_dtbt_71","text":"近世文物之殊","sortOrder":19},
  {"id":"s_work_dtbt_71_20","chapterId":"ch_work_dtbt_71","text":"國家南渡以來，典章文物，多不與承平類。姑以予所親見者言之，蓋月異而歲不同，今聊紀從官立班隨駕、省試官入院、政府呼召、百官騶從、朝報簡削數項，以示子侄。","sortOrder":20},
  {"id":"s_work_dtbt_71_21","chapterId":"ch_work_dtbt_71","text":"侍從常朝，紹興中分立於垂拱殿隔門上，南北相向，以俟追班。乾道中猶然。暨淳熙，則引於殿門上，東西對立。車駕出，常朝文臣自宰相至二史，武臣自宗王、使相至觀察使，以雜壓次序行焉。孝宗在普安邸，官檢校少保節度使，每出必處正尚書之後。而乾道以來，兩班分而為二，唯使相不然。故開府儀同三司皆與執政官聯行，而居其上。","sortOrder":21},
  {"id":"s_work_dtbt_71_22","chapterId":"ch_work_dtbt_71","text":"紹興十二年壬戌，予寓南山淨慈，待詞科試，見省試官聯騎，公服戴帽，不加披衫。每一員以親事官一人執敕黃行前。是時，知舉、參詳、點檢官，合三十一員，最後一中官宣押者，入下天竺貢院。及三十年庚辰，予以吏部郎充參詳官，既入內受敕，則各各乘馬，不同時而赴院。至淳熙十四年丁未，忝司貢舉，則了與昔異。三三兩兩，自為遲速，其乘轎者十人而九矣。","sortOrder":22},
  {"id":"s_work_dtbt_71_23","chapterId":"ch_work_dtbt_71","text":"宰府呼召之禮，始時庶僚皆然，已而卿、監、郎官及史局、玉牒所緣提舉官屬之故，一切得免。逮乾道以後，宰相益自卑，於是館職亦免。迄於淳熙，則凡職事官悉罷此製。","sortOrder":23},
  {"id":"s_work_dtbt_71_24","chapterId":"ch_work_dtbt_71","text":"朝士騶從至少，各得雇募若幹，取步軍司名籍，而幫錢米於左藏，率就雇遊手、冗卒，兩分可供一名。如假借於近郡者，給其半。初猶破省，馬幷一馭者，後不復有焉。若乘轎，僅能充負荷而已。今日以益增，雖下列亦占十餘輩。","sortOrder":24},
  {"id":"s_work_dtbt_71_25","chapterId":"ch_work_dtbt_71","text":"進奏院報狀，必載外郡謝上或監司到任表，與夫慶賀表章一篇。凡朝廷除郡守，先則除目，但雲：「某人差知某州，替某人。」及錄黃下吏部，則前銜後擬雲：「某官姓名，宜差知(或權知、權發遣。)某州、軍州兼管內勸農營田事，替某人。到任成資闕，(或雲年滿。)仍借紫借緋，候回日却依舊服色。」外官求休致，則雲：「某州申某官姓名，為病乞致仕。」或兩人三人後，雲：「某時已降敕，命各守本官致仕。」今不復行，但小報批下。或禁小報，則無由可知。此必一宰相以死為諱者，故去之。外官表章聞，有一二欲士大夫見之者，須以屬東省乃可。郡守更不報細銜。禮文簡脫，一至於此。","sortOrder":25},
  {"id":"s_work_dtbt_71_26","chapterId":"ch_work_dtbt_71","text":"容齋五筆","sortOrder":26},
  {"id":"s_work_dtbt_72_1","chapterId":"ch_work_dtbt_72","text":"卷第五(十五則)","sortOrder":1},
  {"id":"s_work_dtbt_72_2","chapterId":"ch_work_dtbt_72","text":"庾公之斯","sortOrder":2},
  {"id":"s_work_dtbt_72_3","chapterId":"ch_work_dtbt_72","text":"孟子：「逄蒙學射於羿，盡羿之道，思天下惟羿為愈己，於是殺羿。孟子曰：『是亦羿有罪焉？』公明儀曰：『宜若無罪焉。』曰：『薄乎雲爾，惡得無罪？』」此一段既畢，而繼之曰：「鄭人使子濯孺子侵衞，衞使庾公之斯追之。子濯孺子曰：『今日我疾作，不可以執弓，吾死矣夫！』問其僕曰：『追我者誰也？』其僕曰：『庾公之斯也。』曰：『吾生矣。』其僕曰：『庾公之斯，衞之善射者也。夫子曰吾生，何謂也？』曰：『庾公之斯學射於尹公之他，尹公之他學射於我。夫尹公之他，端人也，其取友必端矣。』庾公之斯至，曰：『夫子何為不執弓？』曰：『今日我疾作，不可以執弓。』曰：『小人學射於尹公之他，尹公之他學射於夫子，我不忍以夫子之道反害夫子。雖然今日之事，君事也，我不敢廢。』抽矢，扣輪，去其金，發乘矢而後反。」孟子書子濯、庾公一段，幾二百字，其旨以謂使羿如子濯，得尹公而教之，則必無逄蒙之禍。然前段結尾，自常為文者處之，必雲如子濯孺子施教於尹公之他則可，不然，後段之末，必當雲：以是事觀之，羿之不善取友，至於殺身，其失如此，然後文體相屬。茲判為兩節，若不關聯，而宮商相宣，律呂明煥，立言之妙，是豈步趨模倣所能髣髴哉？人為兒童時，便讀此章，未必深識其趣，故因表出而極論之。左氏傳書衞獻公奔齊雲：「尹公他學射於庾公差，庾公差學射於公孫丁。他與差為孫林父追公，公孫丁御公。庾公差曰：『射為背師，不射為戮，射為禮乎。』射兩軥而還。尹公他曰：『子為師，我則遠矣。』乃反之。公孫丁授公轡而射之，貫他臂。」即孟子所引者，而名字先後美惡皆不同。","sortOrder":3},
  {"id":"s_work_dtbt_72_4","chapterId":"ch_work_dtbt_72","text":"萬事不可過","sortOrder":4},
  {"id":"s_work_dtbt_72_5","chapterId":"ch_work_dtbt_72","text":"天下萬事不可過，豈特此也？雖造化陰陽亦然。雨澤所以膏潤四海，然過則為霖淫；陽舒所以發育萬物，然過則為燠亢。賞以勸善，過則為僭；刑以懲惡，過則為濫。仁之過，則為兼愛無父；義之過，則為為我無君。執禮之過，反鄰於諂；尚信之過，至於證父。是皆偏而不舉之弊，所謂過猶不及者。揚子法言雲：「周公以來，未有漢公之懿也，勤勞則過於阿衡。」蓋諂王莽也。後之議者，謂阿衡之事不可過也，過則反，乃誚莽耳。其旨意固然。","sortOrder":5},
  {"id":"s_work_dtbt_72_6","chapterId":"ch_work_dtbt_72","text":"致仕官上壽","sortOrder":6},
  {"id":"s_work_dtbt_72_7","chapterId":"ch_work_dtbt_72","text":"國朝大臣及侍從致仕後，多居京師。熙寧中，范蜀公自翰林學士，以本官戶部侍郎致仕，同天節乞隨班上壽，許之。遂著為令。元祐初，韓康公以故相判大名府，還都，拜司空致仕，值太皇太後受冊禮畢，乞隨班稱賀，降詔免赴。皆故事也。","sortOrder":7},
  {"id":"s_work_dtbt_72_8","chapterId":"ch_work_dtbt_72","text":"桃花笑春風","sortOrder":8},
  {"id":"s_work_dtbt_72_9","chapterId":"ch_work_dtbt_72","text":"王荊公集古胡笳詞一章雲：「欲問平安無使來，桃花依舊笑春風。」後章雲：「春風似舊花仍笑，人生豈得長年少？」二者貼合，如出一手，每嘆其精工。其上句蓋用崔護詩，後一句久不見其所出。近讀范文正公靈巖寺一篇雲：「春風似舊花猶笑。」以「仍」為「猶」，乃此也。李義山又有絕句雲：「無賴夭桃面，平明露井東。春風為開了，却擬笑春風。」語意兩極其妙。","sortOrder":9},
  {"id":"s_work_dtbt_72_10","chapterId":"ch_work_dtbt_72","text":"嚴先生祠堂記","sortOrder":10},
  {"id":"s_work_dtbt_72_11","chapterId":"ch_work_dtbt_72","text":"范文正公守桐廬，始於釣臺建嚴先生祠堂，自為記，用屯之初九，蠱之上九，極論漢光武之大，先生之高，財二百字。其歌詞雲：「雲山蒼蒼，江水泱泱。先生之德，山高水長。」既成，以示南豐李泰伯。泰伯讀之，三嘆味不已，起而言曰：「公之文一出，必將名世，某妄意輒易一字，以成盛美。」公瞿然握手扣之，答曰：「雲山江水之語，於義甚大，於詞甚溥，而德字承之，乃似趢趚，擬換作風字，如何？」公凝坐頷首，殆欲下拜。張伯玉守河陽，作六經閣記，先託遊士及在職者各為之，凡七八本，既畢，並會於府，伯玉一一閱之，取紙書十四字，遍示客曰：「六經閣，諸子、史、集在焉，不書，尊經也。」時曾子固亦預坐，驚起摘伏。邁頃聞此二事於張子韶，不能追憶經閣所在及其文竟就於誰手，後之君子，當有知之者矣。","sortOrder":11},
  {"id":"s_work_dtbt_72_12","chapterId":"ch_work_dtbt_72","text":"大言誤國","sortOrder":12},
  {"id":"s_work_dtbt_72_13","chapterId":"ch_work_dtbt_72","text":"隗囂謀畔漢，馬援勸止之甚力，而其將王元曰：「今天水全富，士馬最強，案秦舊跡，表裏河山。元請以一丸泥為大王東封函穀關。」囂反遂决，至於父子不得其死。元竟降漢。隋文帝伐陳，大軍臨江，都官尚書孔範言於後主曰：「長江天塹，古以為限隔南北，今日虜軍豈能飛度邪？臣每患官卑，虜若渡江，臣定作太尉公矣。」或妄言北軍馬死，範曰：「此是我馬，何為而死？」帝笑以為然，故不為深備。已而國亡，身竄遠裔。唐元宗有克復中原之志，及下南閩，意以謂諸國可指麾而定，而事力窮薄，且無良將。魏岑因侍宴言：「臣少遊元城，好其風物，陛下平中原，臣獨乞任魏州。」元宗許之。岑趨墀下拜謝，人皆以為佞。孟蜀通奏使王昭遠，居常好大言，有雜耕渭上之志，聞王師入討，對賓客挼手言：「此送死來爾！乘此逐北，遂定中原，不煩再舉也。」不兩月蜀亡，昭遠為俘。此四臣之佞，本為爵祿及一時容悅而已，亦可悲哉！","sortOrder":13},
  {"id":"s_work_dtbt_72_14","chapterId":"ch_work_dtbt_72","text":"宗室覃恩免解","sortOrder":14},
  {"id":"s_work_dtbt_72_15","chapterId":"ch_work_dtbt_72","text":"淳熙十三年，光堯太上皇帝以聖壽八十，肆赦推恩，宇宙之內，蒙被甚廣。太學諸生，至於武學，皆得免文解一次，凡該此恩者，千二三百人。而宗子在學者不預，諸人相率詣宰府，且遍謁侍從、臺諫，各納一劄子，敍述大旨，其要以為：「德壽霈典，普天同慶，而玉牒支派，辱居膠庠，顧不獲與布衣書生等。竊譬之世俗尊長生日，召會族姻，而本家子孫，不享杯酒臠炙，外議謂何？今厖鴻之澤如此，而宗學乃不許廁名，於義於禮，恐為未愜。」是時，諸公莫肯出手為言，邁以待製侍講內宿，適蒙宣引，因出其紙以奏，仍為敷陳此輩所雲尊長生日會客，而本家子弟不得坐，譬諭可謂明白。孝宗亦笑曰：「甚是切當有理。」時所攜只是白劄子，蒙徑付出施行，遂一例免舉。其人名字，今不復能記憶矣。","sortOrder":15},
  {"id":"s_work_dtbt_72_16","chapterId":"ch_work_dtbt_72","text":"唐書載韓柳文","sortOrder":16},
  {"id":"s_work_dtbt_72_17","chapterId":"ch_work_dtbt_72","text":"宋景文修唐書，韓文公傳全載其進學解、諫佛骨表、潮州謝上表、祝鱷魚文，皆不甚潤色，而但換進學解數字，頗不如本意。元雲「招諸生立館下」，改「招」字為「召」，既言先生入學，則諸生在前，招而誨之足矣，何召之為？「障百川而東之」，改「障」字為「停」，本言川流橫潰，故障之使東，若以為停，於義甚淺。改「跋前疐後」為「躓後」，韓公本用狼跋詩語，非躓也。其他以「爬羅剔抉」為「杷羅」，「焚膏油」為「燒」，以「取敗幾時」為「其敗」。吳元濟傳書平淮西碑文千六百六十字，固有他本不同，然才減節輒不穩當。「明年平夏」一句，悉芟之。「平蜀西川」，減「西川」字。「非郊廟祠祀，其無用樂」，減「祠」、「其」兩字。「皇帝以命臣愈，臣愈再拜稽首」，減下「臣」字。殊害理。「汝其以節都統討軍」，以「討」為「諸」，尤不然。討者，如左傳討軍實之義，若雲「諸軍」，何人不能下此語。柳子厚傳載其文章四篇，與蕭俛、許孟容書、貞符、懲咎賦也。孟容書意象步武，全與漢楊惲答孫會宗書相似，貞符倣班孟堅典引，而其四者次序或失之。至雲：「宗元不得召，內閔悼，作賦自儆。」然其語曰：「逾再歲之寒暑。」則責居日月未為久，難以言不得召也。資治通鑑但載梓人及郭橐駝傳，以為其文之有理者。其識見取舍，非宋景文可比雲。","sortOrder":17},
  {"id":"s_work_dtbt_72_18","chapterId":"ch_work_dtbt_72","text":"冥靈社首鳳","sortOrder":18},
  {"id":"s_work_dtbt_72_19","chapterId":"ch_work_dtbt_72","text":"光堯上仙，於梓宮發引前夕，合用警場導引鼓吹詞。邁在翰苑製撰，其六州歌頭內一句雲：「春秋不說楚冥靈。」常時進入文字，立待報者，則貼黃批急速，未嘗停滯。是時，首尾越三日，又入奏，趣請付出。太常吏欲習熟歌唱，守院門伺候。適有表弟沈日新在軍將橋客邸，一士人乃上庠舊識，忽問楚冥靈出處，沈亦不能知，來扣予，因以莊子語告之，急走報，此士大喜。初，孝宗以付巨璫霍汝弼，使釋其意。此士，霍客也，故宛轉費日如此。又面奉旨令代作輓詩五章，其四雲：「鼎湖龍去遠，社首鳳來遲。」當時不敢宣泄，而帶御器械謝純孝密以為問，乃為舉王子年拾遺記，蓋周成王事也。禁苑文書，周悉乃爾。","sortOrder":19},
  {"id":"s_work_dtbt_72_20","chapterId":"ch_work_dtbt_72","text":"左傳州郡","sortOrder":20},
  {"id":"s_work_dtbt_72_21","chapterId":"ch_work_dtbt_72","text":"左傳魯哀公二年，晉趙鞅與鄭戰，誓衆曰：「克敵者，上大夫受縣，下大夫受郡，士田十萬。」註雲：「周書作雒篇：千里百縣，縣有四郡。」然則郡乃隸縣，而歷代地理、郡國志未之或書。又傳所載地名，從州者凡五。「魯宣公會齊於平州，以定其位。」註雲：「齊地在泰山牟縣西。」見於正經。它如「允姓之戎，居於瓜州。」註：「今燉煌也。」「楚莊王滅陳，復封之，鄉取一人焉以歸，謂之夏州。」「齊子尾使閭丘嬰伐我陽州。」註：「魯地。」後四十年，又書「魯侵齊，門於陽州。」註：「攻其門也。」「苫越生子，將待事而名之，陽州之役獲焉，名之曰陽州。」是齊、魯皆有此地也。衞莊公登城以望，見戎州，曰：「我姬姓也，何戎之有焉？」以上唯瓜州之名至今。","sortOrder":21},
  {"id":"s_work_dtbt_72_22","chapterId":"ch_work_dtbt_72","text":"貧富習常","sortOrder":22},
  {"id":"s_work_dtbt_72_23","chapterId":"ch_work_dtbt_72","text":"少時見前輩一說雲：「富人有子不自乳，而使人棄其子而乳之；貧人有子不得自乳，而棄之以乳他人之子。富人懶行，而使人肩輿；貧人不得自行，而又肩輿人。是皆習以為常而不察之也。天下事，習以為常而不察者，推此亦多矣，而人不以為異，悲夫！」甚愛其論。後乃得之於晁以道客語中，故謹書之，益廣其傳。","sortOrder":23},
  {"id":"s_work_dtbt_72_24","chapterId":"ch_work_dtbt_72","text":"唐用宰相","sortOrder":24},
  {"id":"s_work_dtbt_72_25","chapterId":"ch_work_dtbt_72","text":"唐世用宰相不以序，其得之若甚易，然固有出入大僚，歷諸曹尚書、御史大夫，領方鎮，入為僕射、東宮師傅，而不得相者，若顏真卿、王起、楊於陵、馬總、盧鈞、韓皋、柳公綽公權、盧知猷是也。如人主所欲用，不過侍郎、給事中，下至郎中、博士者，才居位即禮絕百僚，諫官、御史聽命之不暇，顧何敢輒抨彈其失，與國朝異矣。其先在職者，仍許引其同列，若姚元崇之引宋璟，蕭嵩之引韓休，李林甫引牛仙客、陳希烈，楊國忠引韋見素，盧（木巳）引關播，李泌引董晉、竇參，李吉甫引裴垍，李德裕引李回，皆然。","sortOrder":25},
  {"id":"s_work_dtbt_72_26","chapterId":"ch_work_dtbt_72","text":"史記簡妙處","sortOrder":26},
  {"id":"s_work_dtbt_72_27","chapterId":"ch_work_dtbt_72","text":"太史公書不待稱說，若雲褒贊其高古簡妙處，殆是摹寫星日之光輝，多見其不知量也。然予每展讀至魏世家、蘇秦平原君魯仲連傳，未嘗不驚呼擊節，不自知其所以然。魏公子無忌與王論韓事曰：「韓必德魏愛魏重魏畏魏，韓必不敢反魏。」十餘語之間五用魏字。蘇秦說趙肅侯曰：「擇交而得則民安，擇交而不得則民終身不安。齊、秦為兩敵而民不得安，倚秦攻齊而民不得安，倚齊攻秦而民不得安。」平原君使楚，客毛遂願行，君曰：「先生處勝之門下幾年於此矣？」曰：「三年於此矣。」君曰：「先生處勝之門下三年於此矣，左右未有所稱誦，勝未有所聞，是先生無所有也。先生不能，先生留。」遂力請行，面折楚王，再言：「吾君在前，叱者何也？」至左手持盤血，而右手招十九人於堂下，其英姿雄風，千載而下，尚可想見，使人畏而仰之，卒定從而歸。至於趙，平原君曰：「勝不敢復相士。勝相士多者千人，寡者百數，今乃於毛先生而失之。毛先生一至楚，而使趙重於九鼎、大呂。毛先生以三寸之舌，強於百萬之師。勝不敢復相士。」秦圍趙，魯仲連見平原君曰：「事將奈何？」君曰：「勝也何敢言事！魏客新垣衍令趙帝秦，今其人在是。勝也何敢言事！」仲連曰：「吾始以君為天下之賢公子也，吾今然後知君非天下之賢公子也。客安在？」平原往見衍曰：「東國有魯仲連先生者，勝請為紹介，交之於將軍。」衍曰：「吾聞魯仲連先生，齊國之高士也。衍人臣也，使事有職，吾不願見魯仲連先生。」及見衍，衍曰：「吾視居此圍城之中者，皆有求於平原君者也；今吾觀先生之玉貌，非有求於平原君者也。」又曰：「始以先生為庸人，吾乃今日知先生為天下之士也。」是三者重沓熟復，如駿馬下駐千丈坡，其文勢正爾。風行於上而水波，真天下之至文也。","sortOrder":27},
  {"id":"s_work_dtbt_72_28","chapterId":"ch_work_dtbt_72","text":"玉津園喜晴詩","sortOrder":28},
  {"id":"s_work_dtbt_72_29","chapterId":"ch_work_dtbt_72","text":"淳熙十二年三月二十六日，車駕宿戒幸玉津園，命下，大雨，有旨許從駕官帶雨具，將曉有晴意，已而天宇豁然。至晚歸，邁進一詩歌詠其實雲：「五更猶自雨如麻，無限都人仰翠華。翻手作雲方悵望，舉頭見日共驚嗟。天公的有施生妙，帝力堪同造物誇。上苑春光無盡藏，何須羯鼓更催花。」四月四日，扈從詣景靈宮朝獻，蒙於幕次賜和篇，聖製雲：「比幸玉津園，縱觀春事，適霽色可喜，卿有詩來上，因俯同其韻：春郊柔綠遍桑麻，小駐芳園覽物華。應信吾心非暇逸，頓回晴意絕咨嗟。每思富庶將同樂，敢務遊畋漫自誇？不似華清當日事，五家車騎爛如花。」後二日，兵部尚書宇文价內引，上舉似此詩曰：「洪待製用雨如麻字，偶思得桑麻可押，又其末句用羯鼓催花事，故以華清車騎答之。」价拱手稱贊。明日以相告雲。","sortOrder":29},
  {"id":"s_work_dtbt_72_30","chapterId":"ch_work_dtbt_72","text":"虢巨賀蘭","sortOrder":30},
  {"id":"s_work_dtbt_72_31","chapterId":"ch_work_dtbt_72","text":"天下國家不幸而有四郊之警，為人臣者當隨其事力，悉心盡忠，以致尺寸之效。苟為叨竊祿位，視如秦、越，一切惟己私之是徇，雖千百載後，睹其事者猶使人怒髮衝冠也。唐天寶祿山之亂，可謂極矣。虢王巨為河南節度使，賀蘭進明繼之，擁數道之兵，臨要害之地，尊為征鎮，有民有財，而汗漫忌疾，非徒無益，而反敗之。巨在彭城，張巡在雍丘，以將士有功，遣使詣巨請空名告身及賜物，巨惟與折衝、果毅告身三十通，不與賜物，巡竟不能立，徙於睢陽。先是太守許遠積糧六萬石，巨以其半給濮陽、濟陰，遠固爭不得。二郡得糧，遂以城叛，而睢陽食盡。顏魯公起兵平原，合衆十萬，既成魏郡堂邑之功矣。是時，進明為北海太守，亦起兵，公以書召之幷力，進明度河，公每事咨之，軍權始移，遂取捨任意，以得招討。後詣行在，因譖房琯，自嶺南而易河南。張巡受圍困棘，遣南霽雲告急於其所治臨淮，相去三百里，棄而不救。平原、睢陽失守，實二人之故。一時議者，皆不以為言，使之連據高位，顯為佚罰。曾不十年，巨斥刺遂州，為段子璋所殺，進明坐第五琦黨，自御史大夫竄謫以死。天網恢恢，茲焉不漏。","sortOrder":31},
  {"id":"s_work_dtbt_72_32","chapterId":"ch_work_dtbt_72","text":"容齋五筆","sortOrder":32},
  {"id":"s_work_dtbt_73_1","chapterId":"ch_work_dtbt_73","text":"卷第六(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_73_2","chapterId":"ch_work_dtbt_73","text":"鄱陽七談","sortOrder":2},
  {"id":"s_work_dtbt_73_3","chapterId":"ch_work_dtbt_73","text":"鄱陽素無圖經地志，元祐六年，餘幹進士都頡，始作七談一篇，敍土風人物，雲：「張仁有篇，徐濯有說，顧雍有論，王德璉有記，而未有形於詩賦之流者，因作七談。」其起事則命以「建端先生」，其止語則以「畢意子」。其一章，言澹浦、彭蠡山川之險勝，番君之靈傑。其二章，言演湖蒲魚之利，膏腴七萬頃，柔桑蠶繭之盛。其三章，言林麓木植之饒，水草蔬果之衍，魚（上敝下黽）禽畜之富。其四章，言銅冶鑄錢，陶埴為器。其五章，言宮寺遊觀，王遙仙壇，吳氏潤泉，叔倫戴隄。其六章，言鄱江之水。其七章，言堯山之民，有陶唐之遺風。凡三千餘字，自謂八日而成，比之太沖十稔、平子十年為無慊。予偶於故簏中得之，惜其不傳於世，故表著於此。其所引張、徐、王、顧所著，今不復存，更為可恨也！","sortOrder":3},
  {"id":"s_work_dtbt_73_4","chapterId":"ch_work_dtbt_73","text":"經解之名","sortOrder":4},
  {"id":"s_work_dtbt_73_5","chapterId":"ch_work_dtbt_73","text":"晉、唐至今，諸儒訓釋六經，否則自立佳名，蓋各以百數，其書曰傳、曰解、曰章句而已。若戰國迨漢，則其名簡雅。一曰故，故者，通其指義也。書有夏侯解故，詩有魯故、後氏故、韓故也。毛詩故訓傳，顏師古謂流俗改故訓傳為詁，字失真耳。小學有杜林蒼頡故。二曰微，謂釋其微指。如春秋有左氏微、鐸氏微、張氏微、虞卿微傳。三曰通，如洼丹易通論名為洼君通，班固白虎通，應劭風俗通，唐劉知幾史通，韓滉春秋通。凡此諸書，唯白虎通、風俗通僅存耳。又如鄭康成作毛詩箋，申明傳義，他書無用此字者。論語之學，但曰齊論、魯論、張侯論，後來皆不然也。","sortOrder":5},
  {"id":"s_work_dtbt_73_6","chapterId":"ch_work_dtbt_73","text":"卜筮不敬","sortOrder":6},
  {"id":"s_work_dtbt_73_7","chapterId":"ch_work_dtbt_73","text":"古者龜為卜，筴為筮，皆興神物以前民用。其用之至嚴，其奉之至敬，其求之至悉，其應之至精。齋戒乃請，問不相襲，故史祝所言，其驗若答。周史筮陳敬仲，知其八世之後莫之與京，將必代齊有國。史蘇占晉伯姬之嫁，而及於為嬴敗姬，惠、懷之亂。至邃至賾，通於神明。後世浸以不然，今而愈甚。至以飲食峱雜之際，呼日者隅坐，使之占卜，往往不加冠裳，一問四五，而責其術之不信，豈有是理哉！善乎班孟堅之論曰：「君子將有為也，將有行也，問焉而以言，其受命也如響。及至衰世，懈於齋戒，而屢煩卜筮，神明不應。故筮瀆不告，易以為忌，龜厭不告，詩以為刺。」謂周易之蒙卦曰：「初筮告，再三瀆，瀆則不告。」詩小旻之章雲：「我龜既厭，不我告猶。」言卜問煩數，狎嫚於龜，龜靈厭之，不告以道也。漢世尚爾，况在於今，未嘗頃刻盡敬，而一歸咎於淫巫瞽史，其可乎哉！","sortOrder":7},
  {"id":"s_work_dtbt_73_8","chapterId":"ch_work_dtbt_73","text":"糖霜譜","sortOrder":8},
  {"id":"s_work_dtbt_73_9","chapterId":"ch_work_dtbt_73","text":"糖霜之名，唐以前無所見，自古食蔗者始為蔗漿，宋玉招魂所謂「胹鱉炮羔有柘漿」是也。其後為蔗餳，孫亮使黃門就中藏吏取交州獻甘蔗餳是也。後又為石蜜，南中八郡志雲：「笮甘蔗汁，曝成飴，謂之石蜜。」本草亦雲，「煉糖和乳為石蜜」是也。後又為蔗酒，唐赤土國用甘蔗作酒，雜以紫瓜根是也。唐太宗遣使至摩揭陀國，取熬糖法，即詔揚州上諸蔗，榨瀋如其劑，色味愈於西域遠甚，然只是今之沙糖。蔗之技盡於此，不言作霜，然則糖霜非古也。歷世詩人模奇寫異，亦無一章一句言之，唯東坡公過金山寺，作詩送遂寧僧圓寶雲：「涪江與中泠，共此一味水。冰盤薦琥珀，何似糖霜美。」黃魯直在戎州，作頌答梓州雍熙長老寄糖霜雲：「遠寄蔗霜知有味，勝於崔子水晶鹽。正宗掃地從誰說，我舌猶能及鼻尖。」則遂寧糖霜見於文字者，實始二公。甘蔗所在皆植，獨福唐、四明、番禺、廣漢、遂寧有糖冰，而遂寧為冠。四郡所產甚微，而顆碎色淺味薄，纔比遂之最下者，亦皆起於近世。唐大曆中，有鄒和尚者，始來小溪之繖山，教民黃氏以造霜之法。繖山在縣北二十里，山前後為蔗田者十之四，糖霜戶十之三。蔗有四色，曰杜蔗，曰西蔗，曰墜蔗，本草所謂荻蔗也，曰紅蔗，本草崑崙蔗也。紅蔗止堪生噉，墜蔗可作沙糖，西蔗可作霜，色淺，土人不甚貴，杜蔗紫嫩，味極厚，專用作霜。凡蔗最困地力，今年為蔗田者，明年改種五穀以息之。霜戶器用，曰蔗削，曰蔗鐮，曰蔗凳，曰蔗碾，曰榨斗，曰榨床，曰漆甕，各有製度。凡霜，一甕中品色亦自不同，堆疊如假山者為上，團枝次之，甕鑑次之，小顆塊次之，沙腳為下；紫為上，深琥珀次之，淺黃又次之，淺白為下。宣和初，王黼創應奉司，遂寧常貢外，歲別進數千斤。是時，所產益奇，牆壁或方寸，應奉司罷，乃不再見。當時因之大擾，敗本業者居半，久而未復。遂寧王灼作糖霜譜七篇，具載其說，予采取之以廣聞見。","sortOrder":9},
  {"id":"s_work_dtbt_73_10","chapterId":"ch_work_dtbt_73","text":"李彥仙守陝","sortOrder":10},
  {"id":"s_work_dtbt_73_11","chapterId":"ch_work_dtbt_73","text":"靖康夷虜之禍，忠義之士，死於守城，而得書史傳者，如汾州之張克戩、隆德之張確、懷之霍安國、代之史抗、建寧寨之楊震、振武之朱昭是已。唯建炎以來，士之得其死者蓋不少。茲讀王灼所作李彥仙傳，雖嘗具表上進，然慮實錄、正史未曾采用，謹識於此。","sortOrder":11},
  {"id":"s_work_dtbt_73_12","chapterId":"ch_work_dtbt_73","text":"彥仙字少嚴，本名孝忠，其先寧州人也，後徙於鞏。幼有大志，喜談兵，習騎射，所歷山川形勢必識之。尚氣，謹然諾，非豪俠不交。金人南侵，郡縣募勤王軍，彥仙散家貲，得三千人，入援京師。虜圍太原，李綱為宣撫使，彥仙上書切詆，有司逮捕急，乃易今名，棄官亡命。頃之，復從种師中，師中敗死，仙走陝州。守將李彌大問北事，條對詳復，使扼殽、澠間。金人再圍汴，陝西范致虛總六路兵進援，仙請曰：「殽、澠險隘，難於立軍，前却即衆潰矣。宜分道並進，伺空以出。且留半軍於陝，為善後計。」致虛曰：「如子言乃逗撓也。」仙曰：「兵輕而分，正可速達。」不從，爭益牢，致虛怒，罷其職。既而敗績，卒無功。建炎元年四月，金人屠陝州，經製使王（王燮）度不能支，引部曲去，官吏逃逸。仙為石壕尉，獨如平時，歸者繈屬，即徙老穉入土花砦、三觜、石柱、大通諸山，拔武銳者分主之，自營三觜。諭衆曰：「虜實易與，今得地利，若輩堅守足矣。」少日虜復據陝，分軍來攻，有健酋升前阜嫚罵，仙單騎衝擊，挾之以歸，始料衆，正部伍。虜數萬圍三觜，仙邀戰，伏精兵後崦，掩殺萬計，奪馬三百，虜解去。京、洛間多爭附者，勢益雄張，未閱月，破虜五十餘壁。初，虜再入陝，官其土人，俾招復業者，人給符別之。仙陰縱麾下往，約日內應。二年三月，引兵直州南，城中火起，虜方備南壁，而水軍自新店，夜順流薄城東北蒙泉坡龍堂溝以入，表裏夾攻，僵尸相藉，遂復陝。始，河東之人倡義拒虜，仙約胡夜叉者為助，假以沿河提舉，意不滿，叛趨南原。仙誘致殺之，奪五千衆。邵隆、邵雲本其黨，欲為復仇，仙因客鐫說，遂來歸。乘勝渡河，柵中條諸山，蒲、解至太原皆響動，乃分遣隆、雲等取安邑、虞鄉、芮城、正平、解，皆下之，蒲幾拔，會援至不克。以功遷閤門宣贊舍人，就畀陝，兼安撫司公事，悉裒所俘酋長護送行在。上咨嘆，賜袍帶、槍劍，許直達奏事，便宜處决。時關以東獨陝在，益增陴、疏塹、蒐軍、繕鎧，廣屯田，訓農耕作。家素留鞏，盡取至官，曰：「吾父母妻子同城存亡矣！」聞者感悅，各有固志。十二月，金酋烏魯撤拔圍陝，仙背城鏖鬥七日，虜傷甚跳奔。三年，婁宿孛堇自絳移屯蒲、解，諜知之，設伏於諸穀，鼓噪橫突，俘馘十八，婁宿僅以身免。製置使王庶檄使輕軍掎角，次虞鄉，虜以萬甲逆石鍾穀口，終日戰，斬級二千，遷武功大夫、寧州觀察使、河解同耀製置使。時河東土豪密附，期王師來為應。仙益治軍，欲請於朝，乞詔陝西諸路各助步騎二萬。會張浚經略處置川、陝，弗之許。十二月，婁宿衆十萬復圍陝，仙夜使人隧地，焚其攻具，營部囂亂，縱兵乘之，虜稍退。四年正月，益生兵傅壘，晝夜進攻，鵝車、天橋、火車、衝車叢進，仙隨機拒敵，又為金汁礮，火藥所及，糜爛無遺，而圍不解。日憑堞須外援，浚為遣軍，虜先阻雍，不得進，則令涇原曲端出鄜坊繞虜後。端素嫉仙聲績逾己，幸其敗，詭託不行。丁巳，城陷，仙挾親軍巷戰，矢集身如蝟，左臂中刃，不殊，戰逾力，遂死之，幷其家遇害。先是，虜嘗許以河南元帥，及圍合，復言如前約，當退師。仙叱曰：「吾寧鬼於宋，安用汝富貴為！」虜惜其才，必欲降之，城將破，先令軍中，生致者予萬金。仙平時弊衣同士卒，及是雜羣伍中死，虜不能察。其為人，面少和色，有犯令，雖親屬不貸。諸將敗事，或有他過，其外屯者，輒封箠，遣帳下往，皆裸就笞，不敢出一詞。當是時，同、華、長安盡為敵藪，陝斗絕一隅，初無朝家素定約束，中立孤軍日與虜確，但誦忠義，感勵其衆。每拜君賜暨取敵金資，悉均之，毛銖不入己。以是精兵三萬，大小二百戰，皆樂為用。軍事獨裁决，至郡政必問法所底，闔境稱治。浚承製贈彰武軍節度使，建廟商州。","sortOrder":12},
  {"id":"s_work_dtbt_73_13","chapterId":"ch_work_dtbt_73","text":"邵雲者，龍門人。城破被執，婁宿欲命以千戶長，肆詈不屈，乃釘之木架上，置解州東門外。惡少撫其背湼文，戲曰：「可鞘吾佩刀。」雲怒，偃架扑之。後五日磔解之，至抉眼摘肝，詈不絕，喉斷乃已。初行刑，將剸刃，雲叱之，失刀而斃，其忠勇蓋如此。","sortOrder":13},
  {"id":"s_work_dtbt_73_14","chapterId":"ch_work_dtbt_73","text":"奸雄疾勝己者","sortOrder":14},
  {"id":"s_work_dtbt_73_15","chapterId":"ch_work_dtbt_73","text":"自古奸雄得志，包藏禍心，窺伺神器，其勢必嫉士大夫之勝己者，故常持「寧我負人，無人負我」之說。若蔡伯喈之值董卓，孔文舉、禰正平、楊德祖之值曹操，嵇叔夜、阮嗣宗之值司馬昭、師，溫太真之值王處仲，謝安石、孟嘉之值桓溫，皆可謂不幸矣。伯喈僅僅脫卓手，終以之隕命。正平轉死於黃祖，文舉覆宗，德祖被戮。叔夜罹東市之害。嗣宗沉湎佯狂，至為勸進表以逃大咎。太真以智挫錢鳳而免，其危若蹈虎尾。唯謝公以高名達識，表裏至誠，故溫敬之重之，不敢萌相窺之意。然尚有「為性命忍須臾」，及「晉祚存亡在此一行」之虞。孟嘉為人夷曠沖默，名冠州里，稱盛德人。仕於溫府，歷征西參軍、從事、中郎、長史，在朝隤然仗正，必不效郗超輩輕與溫合。然自度終不得善其去，故放志酒中，如龍山落帽，豈為不自覺哉！溫至雲：「人不可以無勢，我乃能駕馭卿。」老賊於是見其肺肝矣！嘉雖得全於酒，幸以考終，然財享年五十一，蓋酒為之累也。陶淵明實其外孫，傷其「道悠運促」，悲夫！","sortOrder":15},
  {"id":"s_work_dtbt_73_16","chapterId":"ch_work_dtbt_73","text":"俗語放錢","sortOrder":16},
  {"id":"s_work_dtbt_73_17","chapterId":"ch_work_dtbt_73","text":"今人出本錢以規利入，俗語謂之放債，又名生放，予考之亦有所來。漢書穀永傳雲：「至為人起責，分利受謝。」顏師古註曰：「言富賈有錢，假託其名，代之為主，放與他人，以取利息而共分之。」此放字所起也。","sortOrder":17},
  {"id":"s_work_dtbt_73_18","chapterId":"ch_work_dtbt_73","text":"漢書多敍穀永","sortOrder":18},
  {"id":"s_work_dtbt_73_19","chapterId":"ch_work_dtbt_73","text":"予亡弟景何，少時讀書甚精勤，晝夜不釋卷，不幸有心疾，以至夭逝。嘗見梁弘夫誦漢書，即雲：「唯穀永一人，無處不有。」弘夫驗之於史，乃服其說。今五十餘年矣，漫摭永諸所論建，以渫予在原之思。薛宣為少府，御史大夫缺，永言宣簡在兩府。諫大夫劉輔繫獄，永同中朝臣上書救之。光祿大夫鄭寛中卒，永乞以師傅恩加其禮謚。陳湯下獄，永上疏訟其功。鴻嘉河决，永言當觀水勢，然後順天心而圖之。成帝好鬼神方術，永言皆妄人惑衆，挾左道以欺罔世主，宜距絕此類。梁王為有司奏禽獸行，永上疏諫止勿治。淳於長初封，下朝臣議，永言長當封。段會宗復為西域都護，永憐其老復遠出，手書戒之。建昭雨雪，燕多死，永請皇後就宮，令衆妾人人更進。建始星孛營室，永言為後宮懷妊之象，彗星加之，將有絕繼嗣者。永始日食，永以易占對，言酒亡節之所致。次年又食，永言民愁怨之所致。星隕如雨，永言王者失道，下將叛去，故星叛天而隕，以見其象。樓護傳言：「穀子雲之筆札。」敍傳述其論許、班事。許皇後傳雲：「上採永所言以答書。」其載於史者詳複如此。本傳雲：「永善言災異，前後所上四十餘事。」蓋謂是雲。","sortOrder":19},
  {"id":"s_work_dtbt_73_20","chapterId":"ch_work_dtbt_73","text":"玉堂殿閣","sortOrder":20},
  {"id":"s_work_dtbt_73_21","chapterId":"ch_work_dtbt_73","text":"漢穀永對成帝問曰：「抑損椒房、玉堂之盛寵。」顏師古註：「椒房，皇後所居。玉堂，嬖幸之舍也。」按漢書李尋傳：「久汚玉堂之署。」註：「玉堂殿在未央宮。」翼奉疏曰：「孝文帝時，未央宮又無高門、武臺、麒麟、鳳凰、白虎、玉堂、金華之殿。」三輔黃圖曰：「未央宮有殿閣三十二，椒房、玉堂在其中。」漢宮閣記雲：「未央宮有玉堂、宣室閣。」又引漢書「建章宮南有玉堂，璧門三層，臺高二十丈，玉堂內殿十二門階，階皆玉為之。又有玉堂、神明堂二十六殿。」然今漢書郊祀志但雲「建章宮南有玉堂璧門」，而無它語。晉灼註揚雄解嘲「上玉堂」之句，曰「黃圖有大玉堂、小玉堂殿」，而今黃圖無此文。國朝太宗淳化中，賜翰林「玉堂之署」四字，其後以最下一字犯廟諱，故元符中只雲「玉堂」。紹興末，學士周麟之又乞高宗御書「玉堂」二字，揭於直廬，麟之跋語，自有所疑。已而議者皆謂玉堂乃殿名，不得以為臣下直舍，當如承明故事，請曰「玉堂之廬」可也。今翰林但扁摛文堂三字，示不敢居。然則其為禁內宮殿明白，有殿、有閣、有臺。穀永以配椒房言之，意當日亦嘗為燕遊之地，師古直以為嬖幸之舍，與前註自相舛異，大誤矣！","sortOrder":21},
  {"id":"s_work_dtbt_73_22","chapterId":"ch_work_dtbt_73","text":"漢武帝喜殺人者","sortOrder":22},
  {"id":"s_work_dtbt_73_23","chapterId":"ch_work_dtbt_73","text":"漢武帝天資剛嚴，聞臣下有殺人者，不唯不加之罪，更喜而褒稱之。李廣以故將軍屏居藍田，夜出至亭，為霸陵醉尉所辱。居無何，拜右北平太守，請尉與俱，至軍而斬之，上書自陳謝罪。上報曰：「將軍者，國之爪牙也。怒形則千里竦，威振則萬物伏。夫報忿除害，朕之所圖於將軍也。若乃免冠徒跣，稽顙請罪，豈朕之指哉！」胡建守軍正丞，(謂未得真官，兼守之也。)時監軍御史穿北軍壘垣以為賈區，建欲誅之。當選士馬日，御史與護軍諸校列坐堂皇上，建趨至拜謁，因令走卒曳御史下，斬之。遂上奏曰：「案軍法：『正亡屬將軍，將軍有罪以聞，二千石以下行法焉。』丞於用法疑，臣謹以斬。」謂丞屬軍正，斬御史於法有疑也。製曰：「三王或誓於軍中，欲民先成其慮也。或誓於軍門之外，欲民先意以待事也。或將交刃而誓，致民志也。建又何疑焉。」建繇是顯名。觀此二詔，豈不開妄殺之路乎？","sortOrder":23},
  {"id":"s_work_dtbt_73_24","chapterId":"ch_work_dtbt_73","text":"知人之難","sortOrder":24},
  {"id":"s_work_dtbt_73_25","chapterId":"ch_work_dtbt_73","text":"霍光事武帝，但為奉車都尉，出則奉車，入侍左右，雖以小心謹飭親信，初未嘗少見於事也。一旦位諸百寮之上，使之受遺當國。金日磾以胡父不降，沒入官養馬，上因遊宴見馬，於造次頃刻間，異其為人，即日親近，其後遂為光副。兩人皆能稱上所委。然一日用四人，若上官桀、桑弘羊亦同時輔政，幾於欲害霍光，苟非昭帝之明，社稷危矣！則其知人之哲，得失相半，為未能盡，此雖帝堯之聖而以為難也。","sortOrder":25},
  {"id":"s_work_dtbt_73_26","chapterId":"ch_work_dtbt_73","text":"館職遷除","sortOrder":26},
  {"id":"s_work_dtbt_73_27","chapterId":"ch_work_dtbt_73","text":"建炎南渡，稍置館職，紹興初，始定製，除監、少丞外，以著作郎、佐郎、祕書郎二員，校書、正字通十二員為額，倣唐瀛州十八學士之數。其遷出它司，非郎官即御史。唯林之奇以疾，王十朋以論事，皆徙越府大宗正丞。自乾道以後，有旨，須曾任為縣，始得除臺、察，曾任郡守，始得為郎。三館之士固無有歷此者，於是朝廷欲越次擢用者，乃以為將作、軍器少監，旋進為監，既班在郎上，則無所不可為。欲徑隮清要者，則由著遷祕郎而拜左右二史，不然，不過兼權省郎，年歲間求一郡而去，而御史之除，皆歸六院矣。爾後頗靳其選，俟再遷寺監丞簿，然後命之。向時郡守召用，雖自軍壘亦除郎，今資淺望輕者，但得丞及司直，或又再命，始入省雲。","sortOrder":27},
  {"id":"s_work_dtbt_73_28","chapterId":"ch_work_dtbt_73","text":"容齋五筆","sortOrder":28},
  {"id":"s_work_dtbt_74_1","chapterId":"ch_work_dtbt_74","text":"卷第七(十四則)","sortOrder":1},
  {"id":"s_work_dtbt_74_2","chapterId":"ch_work_dtbt_74","text":"盛衰不可常","sortOrder":2},
  {"id":"s_work_dtbt_74_3","chapterId":"ch_work_dtbt_74","text":"東坡謂廢興成毀不可得而知。予每讀書史，追悼古昔，未嘗不掩卷而嘆。伶子於敍趙飛燕傳，極道其姊弟一時之盛，而終之以荒田野草之悲，言盛之不可留，衰之不可推，正此意也。國初時，工部尚書楊玢長安舊居，多為鄰里侵占，子弟欲以狀訴其事，玢批紙尾，有「試上含元基上望，秋風秋草正離離」之句。方去唐未百年，而故宮殿已如此，殆於宗周黍離之詠矣。慈恩寺塔有荊叔所題一絕句，字極小而端勁，最為感人。其詞曰：「漢國河山在，秦陵草木深。暮雲千里色，無處不傷心。」旨意高遠，不知為何人，必唐世詩流所作也。李嶠汾陰行雲：「富貴榮華能幾時，山川滿目淚沾衣。不見只今汾水上，唯有年年秋雁飛。」明皇聞之，至於泣下。杜甫觀畫馬圖雲：「憶昔巡幸新豐宮，翠華拂天來向東。騰驤磊落三萬匹，皆與此圖筋骨同。君不見金粟堆前松柏裏，龍媒去盡鳥呼風。」公孫大娘弟子舞劍器行雲：「先帝侍女八千人，公孫劍器初第一。五十年間似反掌，風塵澒洞昏王室。梨園弟子散如煙，女樂餘姿映寒日。」元微之連昌宮詞雲：「兩京定後六七年，却尋家舍行宮前。莊園燒盡有枯井，行宮門闥樹宛然。」又雲：「舞榭欹傾基尚存，文窗窈窕紗猶綠。」「上皇偏愛臨砌花，依然御榻臨階斜。」「寢殿相連端正樓，太真梳洗樓上頭。晨光未出簾影黑，至今反掛珊瑚鈎。指似傍人因慟哭，却出宮門淚相續。」凡此諸篇，不可勝紀。飛燕別傳以為伶玄所作，又有玄自敍及桓譚跋語。予竊有疑焉，不唯其書太媟，至雲揚雄獨知之，雄貪名矯激，謝不與交；為河東都尉，捽辱决曹班躅，躅從兄子彪續司馬史記，絀子於無所敍錄，皆恐不然。而自雲：「成、哀之世，為淮南相。」案是時淮南國絕久矣，可昭其妄也。因序次諸詩，聊載於此。","sortOrder":3},
  {"id":"s_work_dtbt_74_4","chapterId":"ch_work_dtbt_74","text":"唐賦造語相似","sortOrder":4},
  {"id":"s_work_dtbt_74_5","chapterId":"ch_work_dtbt_74","text":"唐人作賦，多以造語為奇。杜牧阿房宮賦雲：「明星熒熒，開妝鏡也。綠雲擾擾，梳曉鬟也。渭流漲膩，棄脂水也。煙斜霧橫，焚椒蘭也。雷霆乍驚，宮車過也。轆轆遠聽，杳不知其所之也。」其比興引喻，如是其侈。然楊敬之華山賦又在其前，敍述尤壯，曰：「見若咫尺，田千畝矣。見若環堵，城千雉矣。見若杯水，池百里矣。見若蟻垤，臺九層矣。醯鷄往來，周東西矣。蠛蠓紛紛，秦速亡矣。蜂窠聯聯，起阿房矣。俄而復然，立建章矣。小星奕奕，焚鹹陽矣。纍纍繭栗，祖龍藏矣。」後又有李庾者，賦西都雲：「秦址薪矣，漢址蕪矣。西去一舍，鞠為墟矣。代遠時移，作新都矣。」其文與意皆不逮楊、杜遠甚。高彥休闕史雲敬之「賦五千字，唱在人口」。賦內之句，如上數語，杜司徒佑、李太尉德裕常所誦念。牧之乃佑孫，則阿房賦實模仿楊作也。彥休者，昭宗時人。","sortOrder":5},
  {"id":"s_work_dtbt_74_6","chapterId":"ch_work_dtbt_74","text":"張蘊古大寶箴","sortOrder":6},
  {"id":"s_work_dtbt_74_7","chapterId":"ch_work_dtbt_74","text":"唐太宗初即位，直中書省張蘊古上大寶箴，凡六百餘言，遂擢大理丞。新唐史附其姓名於文藝謝偃傳末，又不載此文，但雲「諷帝以民畏而未懷，其辭挺切」而已。資治通鑑僅載其略曰：「聖人受命，拯溺亨屯。」「故以一人治天下，不以天下奉一人。」「壯九重於內，所居不過容膝，彼昏不知，瑤其臺而瓊其室；羅八珍於前，所食不過適口，惟狂罔念，丘其糟而池其酒。」「勿沒沒而暗，勿察察而明，雖冕旒蔽目而視於未形，雖黈纊塞耳而聽於無聲。」然此外尚多規正之語，如曰：「惟辟作福，為君實難。主普天之下，處王公之上，任土貢其有求，具寮陳其所倡。是故恐懼之心日弛，邪僻之情轉放。豈知事起乎所忽，禍生乎無妄。」「大明無私照，至公無私親。」「禮以禁其奢，樂以防其佚。」「勿謂無知，居高聽卑；勿謂何害，積小就大。樂不可極，樂極生哀；欲不可縱，縱欲成災。」「勿內荒於色，勿外荒於禽。勿貴難得貨，勿聽亡國音。內荒伐人性，外荒蕩人心。難得之貨侈，亡國之音淫。勿謂我尊，而慢賢侮士；勿謂我智，而拒諫矜己。」「安彼反側，如春陽秋露，巍巍蕩蕩，恢漢高大度；撫茲庶事，如履薄臨深，戰戰慄慄，用周文小心。」「一彼此於胸臆，捐好惡於心想。」「如衡如石，不定物以限，物之懸者，輕重自見；如水如鏡，不示物以情，物之鑒者，妍媸自生。勿渾渾而濁，勿皎皎而清；勿沒沒而暗，勿察察而明。」「吾王撥亂，戡以智力，民懼其威，未懷其德；我皇撫運，扇以淳風，民懷其始，未保其終。」「使人以心，應言以行。」「天下為公，一人有慶。」其文大抵不凡，既不為史所書，故學者亦罕傳誦。蘊古為丞四年，以無罪受戮，太宗尋悔之，乃有覆奏之旨，傳亦不書，而以為坐事誅，皆失之矣。舊唐書全載此箴，仍專立傳，不知宋景文何為削之也？","sortOrder":7},
  {"id":"s_work_dtbt_74_8","chapterId":"ch_work_dtbt_74","text":"國初文籍","sortOrder":8},
  {"id":"s_work_dtbt_74_9","chapterId":"ch_work_dtbt_74","text":"國初承五季亂離之後，所在書籍印板至少，宜其焚煬蕩析，了無孑遺。然太平興國中編次御覽，引用一千六百九十種，其綱目幷載於首卷，而雜書、古詩賦又不及具錄，以今考之，無傳者十之七八矣，則是承平百七十年，翻不若極亂之世。姚鉉以大中祥符四年，集唐文粹，其序有雲：「况今歷代墳籍，略無亡逸。」觀鉉所類文集，蓋亦多不存，誠為可嘆！","sortOrder":9},
  {"id":"s_work_dtbt_74_10","chapterId":"ch_work_dtbt_74","text":"敍西漢郊祀天地","sortOrder":10},
  {"id":"s_work_dtbt_74_11","chapterId":"ch_work_dtbt_74","text":"郊祀合祭、分祭之論，國朝元豐、元祐、紹聖中三議之矣，莫辯於東坡之立說，然其大旨駁當時議臣，謂周、漢以來，皆嘗合祭，及謂夏至之日行禮為不便。予固讚美之於四筆矣。但熟考漢史，猶為未盡。自高皇帝增秦四畤為五，以事天地。武帝以來，至於元、成，皆郊見甘泉。武帝因幸汾陰，始立後土祠於脽上，率歲歲間舉之，或隔一歲，常以正月郊泰畤，三月祠後土。成帝建始元年，初立南北郊，亦用正月、三月辛日，而罷甘泉、汾陰之祭。元豐、祐、紹三議，皆未嘗及此。蓋盛夏入廟出郊，在漢禮元不然也。是時，坡公以非議者所起，故不暇更為之說，似不必深攻合祭為王莽所行，庶幾往復考賾，不至矛盾，當復俟知禮者折衷之焉。","sortOrder":11},
  {"id":"s_work_dtbt_74_12","chapterId":"ch_work_dtbt_74","text":"騫鶱二字義訓","sortOrder":12},
  {"id":"s_work_dtbt_74_13","chapterId":"ch_work_dtbt_74","text":"騫鶱二字，音義訓釋不同。以字書正之，騫，去乾切，註雲：「馬腹縶，又虧也。」今列於禮部韻略下平聲二仙中。鶱，虛言切，註雲：「飛貌。」今列於上平聲二十二元中。文人相承，以騫虧之騫為軒昂掀舉之義，非也。其字之下從馬，馬豈能掀舉哉？閔損字子騫，雖古聖賢命名製字，未必有所拘泥，若如虧少之義，則渙然矣。其下從鳥，則於掀飛之訓為得。此字殆廢於今，故東坡、山穀亦皆押騫字入元韻，如「時來或作鵬騫」，「傳非其人恐飛騫」之類，特不暇毛舉深考耳，唯韓公和侯協律詠筍一聯雲：「得時方張王，挾勢欲騰鶱。」乃為得之。此固小學瑣瑣，尤可以見公之不苟於下筆也。","sortOrder":13},
  {"id":"s_work_dtbt_74_14","chapterId":"ch_work_dtbt_74","text":"書麴信陵事","sortOrder":14},
  {"id":"s_work_dtbt_74_15","chapterId":"ch_work_dtbt_74","text":"夜讀白樂天秦中吟十詩，其立碑篇雲：「我聞望江縣，麴令撫惸嫠。(麴，名信陵。)在官有仁政，名不聞京師。身歿欲歸葬，百姓遮路歧。攀轅不得去，留葬此江湄。至今道其名，男女涕皆垂。無人立碑碣，唯有邑人知。」予因憶少年寓無錫時，從錢伸仲大夫借書，正得信陵遺集，財有詩三十三首，祈雨文三首。信陵以貞元元年鮑防下及第，為四人，以六年作望江令。讀其投石祝江文雲：「必也私欲之求，行於邑里，慘黷之政，施於黎元，令長之罪也。神得而誅之，豈可移於人以害其歲？」詳味此言，其為政無愧於神天可見矣。至大中十一年，寄客鄉貢進士姚輦，以其文示縣令蕭縝，縝輟俸買石刊之。樂天十詩，作於貞元元和之際，距其亡十五年耳，而名已不傳。新唐藝文志但記詩一卷，略無它說。非樂天之詩，幾於與草木俱腐。乾道二年，歷陽陸同為望江令，得其詩於汝陰，王廉清為刊板而致之郡庫，但無祈雨文也。","sortOrder":15},
  {"id":"s_work_dtbt_74_16","chapterId":"ch_work_dtbt_74","text":"貢禹朱暉晚達","sortOrder":16},
  {"id":"s_work_dtbt_74_17","chapterId":"ch_work_dtbt_74","text":"貢禹壯年仕不遇，棄官而歸。至元帝初，乃召用，由諫大夫遷光祿，奏言：「臣犬馬之齒八十一，凡有一子，年十二。」則禹入朝時，蓋年八十，其生子時固已七十歲矣，竟再遷至御史大夫，列於三公。杜子美雲：「長安卿相多少年，富貴應須致身早。」是不然也。朱暉在章帝朝，自臨淮太守屏居，後召拜僕射，復為太守，上疏乞留中，詔許之。因議事不合，自繫獄，不肯復署議，曰：「行年八十，得在機密，當以死報。」遂閉口不復言。帝意解，遷為尚書令。至和帝時，復諫征匈奴，計其年當九十矣。其忠正非禹比也。","sortOrder":17},
  {"id":"s_work_dtbt_74_18","chapterId":"ch_work_dtbt_74","text":"琵琶行海棠詩","sortOrder":18},
  {"id":"s_work_dtbt_74_19","chapterId":"ch_work_dtbt_74","text":"白樂天琵琶行一篇，讀者但羨其風致，敬其詞章，至形於樂府，詠歌之不足，遂以謂真為長安故倡所作。予竊疑之。唐世法網雖於此為寛，然樂天嘗居禁密，且謫官未久，必不肯乘夜入獨處婦人船中，相從飲酒，至於極彈絲之樂，中夕方去，豈不虞商人者它日議其後乎？樂天之意，直欲攄寫天涯淪落之恨爾。東坡謫黃州，賦定惠院海棠詩，有「陋邦何處得此花，無乃好事移西蜀」、「天涯流落俱可念，為飲一尊歌此曲」之句，其意亦爾也。或謂殊無一話一言與之相似，是不然。此真能用樂天之意者，何必效常人章摹句寫而後已哉？","sortOrder":19},
  {"id":"s_work_dtbt_74_20","chapterId":"ch_work_dtbt_74","text":"東坡不隨人後","sortOrder":20},
  {"id":"s_work_dtbt_74_21","chapterId":"ch_work_dtbt_74","text":"自屈原詞賦假為漁父、日者問答之後，後人作者悉相規倣。司馬相如子虛、上林賦以子虛、烏有先生、亡是公，揚子雲長楊賦以翰林主人、子墨客卿，班孟堅兩都賦以西都賓、東都主人，張平子兩都賦以憑虛公子、安處先生，左太沖三都賦以西蜀公子、東吳王孫、魏國先生，皆改名換字，蹈襲一律，無復超然新意稍出於法度規矩者。晉人成公綏嘯賦，無所賓主，必假逸羣公子，乃能遣詞。枚乘七發，本只以楚太子、吳客為言，而曹子建七啟，遂有玄微子、鏡機子。張景陽七命，有沖漠公子、殉華大夫之名。言話非不工也，而此習根著未之或改。若東坡公作後杞菊賦，破題直雲：「吁嗟先生，誰使汝坐堂上稱太守？」殆如飛龍摶鵬，鶱翔扶搖於煙霄九萬里之外，不可搏詰，豈區區巢林翾羽者所能窺探其涯涘哉？於詩亦然，樂天雲：「醉貌如霜葉，雖紅不是春。」坡則曰：「兒童誤喜朱顏在，一笑那知是酒紅。」杜老雲：「休將短髮還吹帽，笑倩傍人為正冠。」坡則曰：「酒力漸消風力軟，颼颼，破帽多情却戀頭。」鄭穀十日菊雲：「自緣今日人心別，未必秋香一夜衰。」坡則曰：「相逢不用忙歸去，明日黃花蝶也愁。」又曰：「萬事到頭都是夢，休休，明日黃花蝶也愁。」正採舊公案，而機杼一新，前無古人，於是為至。與夫用「見他桃李樹，思憶後園春」之意，以為「長因送人處，憶得別家時」，為一僧所嗤者有間矣。","sortOrder":21},
  {"id":"s_work_dtbt_74_22","chapterId":"ch_work_dtbt_74","text":"元白習製科","sortOrder":22},
  {"id":"s_work_dtbt_74_23","chapterId":"ch_work_dtbt_74","text":"白樂天、元微之同習製科，中第之後，白公寄微之詩曰：「皆當少壯日，同惜盛明時。光景嗟虛擲，雲霄竊暗窺。攻文朝矻矻，講學夜孜孜。策目穿如札，毫鋒銳若錐。」註雲：「時與微之結集策略之目，其數至百十，各有纖鋒細管筆，攜以就試，相顧輒笑，目為毫錐。」乃知士子待敵，編綴應用，自唐以來則然，毫錐筆之名起於此也。","sortOrder":23},
  {"id":"s_work_dtbt_74_24","chapterId":"ch_work_dtbt_74","text":"門生門下見門生","sortOrder":24},
  {"id":"s_work_dtbt_74_25","chapterId":"ch_work_dtbt_74","text":"後唐裴尚書年老致政。清泰初，其門生馬裔孫知舉，放榜後引新進士謁謝於裴，裴歡宴永日，書一絕雲：「宦途最重是文衡，天與愚夫作盛名。三主禮闈今八十，門生門下見門生。」時人榮之。事見蘇耆開譚錄。予以五代登科記考之，裴在同光中三知舉，四年放進士八人，裔孫預焉。後十年，裔孫為翰林學士，以清泰三年放進士十三人，茲所書是已。裔孫尋拜相，新史亦載此一句雲。白樂天詩，有與諸同年賀座主高侍郎新拜太常同宴蕭尚書亭子一篇。註雲：「座主於蕭尚書下及第。」予考登科記，樂天以貞元十六年庚辰中書舍人高郢下第四人登科，郢以寶應二年癸卯禮部侍郎蕭昕下第九人登科，迨郢拜太常時，幾四十年矣。昕自癸卯放進士之後，二十四年丁卯，又以禮部尚書再知貢舉，可謂壽俊。觀白公所賦，益可見唐世舉子之尊尚主司也。","sortOrder":25},
  {"id":"s_work_dtbt_74_26","chapterId":"ch_work_dtbt_74","text":"韓蘇杜公敍馬","sortOrder":26},
  {"id":"s_work_dtbt_74_27","chapterId":"ch_work_dtbt_74","text":"韓公人物畫記，其敍馬處雲：「馬大者九匹，於馬之中又有上者下者焉，行者，牽者，奔者，涉者，陸者，翹者，顧者，鳴者，寢者，訛者，立者，齕者，飲者，溲者，陟者，降者，痒磨樹者，噓者，嗅者，喜而相戲者，怒相踶齧者，秣者，騎者，驟者，走者，載服物者，載狐兔者，凡馬之事二十有七焉。馬大小八十有三，而莫有同者焉。」秦少遊謂其敍事該而不煩，故仿之而作羅漢記。坡公賦韓幹十四馬詩雲：「二馬並驅攢八蹄，二馬宛頸鬃尾齊。一馬任前雙舉後，一馬却避長鳴嘶。老髯奚官騎且顧，前身作馬通馬語。後有八匹飲且行，微流赴吻若有聲。前者既濟出林鶴，後者欲涉鶴俯啄。最後一匹馬中龍，不嘶不動尾搖風。韓生畫馬真是馬，蘇子作詩如見畫。世無伯樂亦無韓，此詩此畫誰當看？」詩之與記，其體雖異，其為布置鋪寫則同。誦坡公之語，蓋不待見畫也。予雲林繪監中有臨本，略無小異。杜老觀曹將軍畫馬圖雲：「昔日太宗拳毛騧，近時郭家師子花。今之新圖有二馬，復令識者久嘆嗟。其餘七匹亦殊絕，迥若寒空動煙雪。霜蹄蹴踏長楸間，馬官廝養森成列。可憐九馬爭神駿，顧視清高氣深穩。」其語視東坡，似若不及，至於「斯須九重真龍出，一洗萬古凡馬空」，不妨獨步也。杜又有畫馬讚雲：「韓幹畫馬，毫端有神。驊騮老大，騕褭清新」及「四蹄雷雹，一日天池。瞻彼駿骨，實惟龍媒」之句。坡公九馬讚言：「薛紹彭家藏曹將軍九馬圖，杜子美所為作詩者也。」其詞雲：「牧者萬歲，繪者惟霸。甫為作誦，偉哉九馬。」讀此詩文數篇，真能使人方寸超然，意氣橫出，可謂「妙絕動宮牆」矣。","sortOrder":27},
  {"id":"s_work_dtbt_74_28","chapterId":"ch_work_dtbt_74","text":"風災霜旱","sortOrder":28},
  {"id":"s_work_dtbt_74_29","chapterId":"ch_work_dtbt_74","text":"慶元四年，饒州盛夏中，時雨頻降，六七月之間未嘗請禱，農家水車龍具，倚之於壁，父老以為所未見，指期西成有秋，當倍常歲，而低下之田，遂以潦告。餘幹、安仁乃於八月罹地火之厄。地火者，蓋苗根及心，（上薛下虫）蟲生之，莖幹焦枯，如火烈烈，正古之所謂蟊賊也。九月十四日，嚴霜連降，晚稻未實者，皆為所薄，不能復生，諸縣多然。有常產者，訴於郡縣，郡守孜孜愛民，有意蠲租，然僚吏多雲：「在法無此兩項。」又雲：「九月正是霜降節，不足為異。」案白樂天諷諫杜陵叟一篇曰：「九月霜降秋早寒，禾穗未熟皆青乾。長吏明知不申破，急斂暴征求考課。」此明證也。予因記元祐五年蘇公守杭日，與宰相呂汲公書，論浙西災傷曰：「賢哲一聞此言，理無不行，但恐世俗諂薄成風，揣所樂聞與所忌諱，爭言無災，或有災而不甚損。八月之末，秀州數千人訴風災，吏以為法有訴水旱而無訴風災，閉拒不納，老幼相騰踐，死者十一人。由此言之，吏不喜言災者，蓋十人而九，不可不察也。」蘇公及此，可謂仁人之言。豈非昔人立法之初，如所謂風災、所謂早霜之類，非如水旱之田可以稽考，懼貪民乘時，或成冒濫，故不輕啟其端。今日之計，固難添創條式。但凡有災傷，出於水旱之外者，專委良守令推而行之，則實惠及民，可以救其流亡之禍，仁政之上也。","sortOrder":29},
  {"id":"s_work_dtbt_74_30","chapterId":"ch_work_dtbt_74","text":"容齋五筆","sortOrder":30},
  {"id":"s_work_dtbt_75_1","chapterId":"ch_work_dtbt_75","text":"卷第八(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_75_2","chapterId":"ch_work_dtbt_75","text":"白蘇詩紀年歲","sortOrder":2},
  {"id":"s_work_dtbt_75_3","chapterId":"ch_work_dtbt_75","text":"白樂天為人誠實洞達，故作詩述懷，好紀年歲。因閱其集，輒抒錄之：「此生知負少年心，不展愁眉欲三十」，「莫言三十是年少，百歲三分已一分」，「何況纔中年，又過三十二」，「不覺明鏡中，忽年三十四」，「我年三十六，冉冉昏復旦」，「非老亦非少，年過三紀餘」，「行年欲四十，有女曰金鑾」，「我今欲四十，秋懷亦可知」，「行年三十九，歲暮日斜時」，「忽因時節驚年歲，四十如今欠一年」，「四十為野夫，田中學鋤穀」，「四十官七品，拙宦非由它」，「毛鬢早改變，四十白髮生」，「况我今四十，本來形貌羸」，「衰病四十身，嬌癡三歲女」，「自問今年幾，春秋四十初」，「四十未為老，憂傷早衰惡」，「莫學二郎吟太苦，纔年四十鬢如霜」，「下有獨立人，年來四十一」，「若為重入華陽院，病鬢愁心四十三」，「已年四十四，又為五品官」，「面瘦頭斑四十四，遠謫江州為郡吏」，「行年四十五，兩鬢半蒼蒼」，「四十六時三月盡，送春爭得不殷勤」，「我今四十六，衰顇臥江城」，「鬢髮蒼浪牙齒疏，不覺身年四十七」，「明朝四十九，應轉悟前非」，「四十九年身老日，一百五夜月明天」，「衰鬢蹉跎將五十，關河迢遞過三千」，「青山舉眼三千里，白髮平頭五十人」，「宦途氣味已諳盡，五十不休何日休」，「五十江城守，停杯忽自思」，「莫學爾兄年五十，蹉跎始得掌絲綸」，「五十未全老，尚可且歡娛」，「長慶二年秋，我年五十一」，「二月五日花如雪，五十二人頭似霜」，「老校於君合先退，明年半百又加三」，「前歲花前五十二，今年花前五十五」，「倘年七十猶強健，尚得閑行十五春」，「去時十一二，今年五十六」，「我年五十七，榮名得幾許」，「我年五十七，歸去誠已遲」，「身為三品官，年已五十八」，「五十八翁方有後，靜思堪喜亦堪嗟」，「半百過九年，豔陽殘一日」，「火銷燈盡天明後，便是平頭六十人」，「六十河南尹，前途足可知」，「不准擬身年六十，上山仍未要人扶」，「不准擬身年六十，遊春猶自有心情」，「我今悟已晚，六十方退閑」，「今歲日餘二十六，來歲年登六十二」，「心情多少在，六十二三人」，「六十三翁頭雪白，假如醒黠欲何為」，「行年六十四，安得不衰羸」，「我今六十五，走若下坡輪」，「年開第七秩，屈指幾多人」，「五十八歸來，今年六十六」，「無憂亦無喜，六十六年春」，「共把十千沽一斗，相看七十欠三年」，「七十欠四歲，此生那足論」，「六十八衰翁，乘衰百疾攻」，「又問年幾何，七十行欠二」，「更過今年年七十，假如無病亦宜休」，「今日行年將七十，猶須慚愧病來遲」，「且喜同年滿七十，莫嫌衰病莫嫌貧」，「舊語相傳聊自慰，世間七十老人稀」，「皤然七十翁，亦足稱壽考」，「昨日復今辰，悠悠七十春」，「人生七十希，我年幸過之」，「白鬚如雪五朝臣，又入新正第七旬(時年七十一。)」，「行開第八秩，可謂盡天年」，「吾今已年七十一，眼昏鬚白頭風眩」，「七十人難到，過三更較稀」，「七十三人難再到，今春來是別花來」，「七十三翁旦暮身，誓開險路作通津」，「風光拋得也，七十四年春」，「壽及七十五，俸沾五十千」，其多如此。蘇公素重樂天，故間亦效之，如「龍鍾三十九，勞生已強半，歲莫日斜時，還為昔人嘆」，正引用其語。又「四十豈不知頭顱，畏人不出何其愚」，「我今四十二，衰髮不滿梳」，「憶在錢塘正如此，回頭四十二年非」，「行年四十九，還此北窗宿」，「吾年四十九，賴此一笑喜」，「嗟我與君皆丙子，四十九年窮不死」，「五十之年初過二，衰顏記我今如此」，「白髮蒼顏五十三，家人強遣試春衫」，「先生年來六十化，道眼已入不二門」，「紛紛華髮不足道，當返六十過去魂」，「我年六十一，頹景薄西山」，「結髮事文史，俯仰六十逾」，「與君皆丙子，各已三萬日」。玩味莊誦，便如閱年譜也。","sortOrder":3},
  {"id":"s_work_dtbt_75_4","chapterId":"ch_work_dtbt_75","text":"天將富此翁","sortOrder":4},
  {"id":"s_work_dtbt_75_5","chapterId":"ch_work_dtbt_75","text":"唐劉仁軌任給事中，為宰相李義府所惡，出為青州刺史。及代還，欲斥以罪，又坐漕船覆沒免官。其後百濟叛，詔以白衣檢校帶方州刺史。仁軌謂人曰：「天將富貴此翁邪！」果削平遼海。白樂天有自題酒庫一篇，雲：「身更求何事，天將富此翁。此翁何處富，酒庫不曾空。」註雲：「劉仁軌詩：『天將富此翁。』以一醉為富也。」然則唐史以此為仁軌之語，而不言其詩，為未審耳。","sortOrder":5},
  {"id":"s_work_dtbt_75_6","chapterId":"ch_work_dtbt_75","text":"白公說俸祿","sortOrder":6},
  {"id":"s_work_dtbt_75_7","chapterId":"ch_work_dtbt_75","text":"白樂天仕宦，從壯至老，凡俸祿多寡之數，悉載於詩，雖波及它人亦然。其立身廉清，家無餘積，可以概見矣。因讀其集，輒敍而列之。其為校書郎，曰：「俸錢萬六千，月給亦有餘。」為左拾遺，曰：「月慚諫紙二千張，歲愧俸錢三十萬。」兼京兆戶曹，曰：「俸錢四五萬，月可奉晨昏。廩祿二百石，歲可盈倉囷。」貶江州司馬，曰：「散員足庇身，薄俸可資家。」壁記曰：「歲廩數百石，月俸六七萬。」罷杭州刺史，曰：「三年請祿俸，頗有餘衣食。」「移家入新宅，罷郡有餘資。」為蘇州刺史，曰：「十萬戶州尤覺貴，二千石祿敢言貧。」為賓客分司，曰：「俸錢八九萬，給受無虛月。」「嵩洛供雲水，朝廷乞俸錢。」「老宜官冷靜，貧賴俸優饒。」「官優有祿料，職散無羈縻。」「官銜依口得，俸祿逐身來。」為河南尹，曰：「厚俸如何用，閑居不可忘。」不赴同州，曰：「誠貪俸錢厚，其如身力衰！」為太子少傅，曰：「月俸百千官二品，朝廷雇我作閑人。」「又問俸厚薄，百千隨月至。」「七年為少傅，品高俸不薄。」其致仕，曰：「全家遁此曾無悶，半俸資身亦有餘。」「俸隨日計錢盈貫，祿逐年支粟滿囷。」「壽及七十五，俸占五十千。」其泛敍曰：「歷官凡五六，祿俸及妻孥。」「料錢隨官用，生計逐年營。」「形骸僶俛班行內，骨肉勾留俸祿中。」其它人者，如陝州王司馬曰：「公事閑忙同少尹，俸錢多少敵尚書。」劉夢得罷賓客，除祕監，祿俸略同，曰：「日望揮金賀新命，俸錢依舊又如何！」嘆洛陽、長水二縣令曰：「朱紱洛陽官位屈，青袍長水俸錢貧。」其將下世，有達哉樂天行，曰：「先賣南坊十畝園，次賣東郭五頃田。然後兼賣所居宅，髣髴獲緡二三千。但恐此錢用不盡，即先朝露歸夜泉。」後之君子試一味其言，雖日飲貪泉，亦知斟酌矣。觀其生涯如是，東坡雲：「公廩有餘粟，府有餘帛。」殆亦不然。","sortOrder":7},
  {"id":"s_work_dtbt_75_8","chapterId":"ch_work_dtbt_75","text":"白居易出位","sortOrder":8},
  {"id":"s_work_dtbt_75_9","chapterId":"ch_work_dtbt_75","text":"白居易為左贊善大夫，盜殺武元衡，京都震擾。居易首上疏，請亟捕賊，刷朝廷恥，以必得為期。宰相嫌其出位，不悅，因是貶江州司馬。此唐書本傳語也。案是時宰相張弘靖、韋貫之，弘靖不足道，貫之於是為失矣。白集載與楊虞卿書雲：「左降詔下，明日而東，思欲一陳於左右。去年六月，盜殺右丞相於通衢中，迸血體，磔髮肉，所不忍道。合朝震慄不知所雲，僕以書籍以來，未有此事。苟有所見，雖畎畝皂隸之臣，不當默默，况在班列，而能勝其痛憤耶？故武丞相之氣平明絕，僕之書奏日午入。兩日之內，滿城知之，其不與者，或語以偽言，或陷以非語，皆曰：『丞、郎、給、舍、諫官、御史，尚未論請，而贊善大夫何反憂國之甚也？』僕聞此語，退而思之，贊善大夫誠賤冗耳，朝廷有非常事，即日獨進封章，謂之忠，謂之憤，亦無愧矣！謂之妄，謂之狂，又敢逃乎？以此獲辜，顧何如耳，況又不以此為罪名乎！」白之自述如此。然則一時指為出位者，不但宰相而已也。史又曰：「居易母墜井死，而賦新井篇，以是左降。」前書所謂不以此為罪名者，是已。","sortOrder":9},
  {"id":"s_work_dtbt_75_10","chapterId":"ch_work_dtbt_75","text":"醉翁亭記酒經","sortOrder":10},
  {"id":"s_work_dtbt_75_11","chapterId":"ch_work_dtbt_75","text":"歐陽公醉翁亭記、東坡公酒經，皆以也字為絕句。歐陽二十一也字，坡用十六也字，歐記人人能讀，至於酒經，知之者蓋無幾。坡公嘗雲：「歐陽作此記，其詞玩易，蓋戲雲耳，不自以為奇特也。而妄庸者作歐語雲：『平生為此文最得意。』又雲：『吾不能為退之畫記，退之不能為吾醉翁亭記。』此又大妄也。」坡酒經每一也字上必押韻，暗寓於賦，而讀之者不覺，其激昂淵妙，殊非世間筆墨所能形容，今盡載於此，以示後生輩。其詞雲：「南方之氓，以糯與粳，雜以卉藥而為餅，嗅之香，嚼之辣，揣之枵然而輕，此餅之良者也。吾始取麵而起肥之，和之以薑液，烝之使十裂，繩穿而風戾之，愈久而益悍，此（麥曲）之精者也。米五岗為率，而五分之，為三岗者一，為五升者四，三岗者以釀，五升者以投，三投而止，尚有五升之贏也。始釀，以四兩之餅，而每投以二兩之（麥曲），皆澤以少水，足以散解而勻停也。釀者必甕按而井泓之，三日而井溢，此吾酒之萌也。酒之始萌也，甚烈而微苦，蓋三投而後平也。凡餅烈而（麥曲）和，投者必屢嘗而增損之，以舌為權衡也。既溢之三日乃投，九日三投，通十有五日而後定也。既定乃註以岗水，凡水必熟而冷者也。凡釀與投，必寒之而後下，此炎州之令也。既水五日乃篘，得二岗有半，此吾酒之正也。先篘半日，取所謂贏者為粥，米一而水三之，揉以餅（麥曲），凡四兩，二物幷也。投之糟中，熟撋而再釀之，五日壓得岗有半，此吾酒之少勁者也。勁、正合為四岗，又五日而飲，則和而力、嚴而不猛也。篘絕不旋踵而粥投之，少留則糟枯中風而酒病也。釀久者酒醇而豐，速者反是，故吾酒三十日而成也。」此文如太牢八珍，咀嚼不嫌於致力，則真味愈雋永，然未易為俊快者言也。","sortOrder":11},
  {"id":"s_work_dtbt_75_12","chapterId":"ch_work_dtbt_75","text":"白公感石","sortOrder":12},
  {"id":"s_work_dtbt_75_13","chapterId":"ch_work_dtbt_75","text":"白樂天有奉和牛思黯以李蘇州所寄太湖石奇狀絕倫因作詩兼呈劉夢得，其末雲：「共嗟無此分，虛管太湖來。」註：「與夢得俱典姑蘇，而不獲此石。」又有感石上舊字雲：「太湖石上鐫三字，十五年前陳結之。」案陳結之並無所經見，全不可曉。後觀其對酒有懷寄李郎中一絕句，曰：「往年江外拋桃葉，去歲樓中別柳枝。寂寞春來一杯酒，此情唯有李君知。」註曰：「桃葉，結之也；柳枝，樊素也。」然後結之之義始明。樂天以病而去柳枝，故作詩雲：「兩枝楊柳小樓中，嫋娜多年伴醉翁。明日放歸歸去後，世間應不要春風。」因劉夢得有戲之之句，又答之雲：「誰能更學孩童戲，尋逐春風捉柳花。」然其鍾情處竟不能忘，如雲「病共樂天相伴住，春隨樊子一時歸」，「金羈駱馬近貰却，羅袖柳枝尋放還」，「觴詠罷來賓閣閉，笙歌散後妓房空」皆是也，讀之使人悽然。","sortOrder":13},
  {"id":"s_work_dtbt_75_14","chapterId":"ch_work_dtbt_75","text":"禮部韻略非理","sortOrder":14},
  {"id":"s_work_dtbt_75_15","chapterId":"ch_work_dtbt_75","text":"禮部韻略所分字，有絕不近人情者，如東之與冬，清之與青，至於隔韻不通用。而為四聲切韻之學者，必強立說，然終為非是。如撰字至列於上去三韻中，仍義訓不一。頃紹興三十年，省闈舉子兼經出易簡天下之理得賦。予為參詳官，有點檢試卷官蜀士杜莘雲：「簡字韻甚窄，若撰字必在所用，然唯撰述之撰乃可爾，如『雜物撰德』，『體天地之撰』，『異夫三子者之撰』，『欠伸，撰杖屨』之類，皆不可用。」予以白知舉，請揭榜示衆。何通遠諫議，初亦難之，予曰：「倘舉場皆落韻，如何出手？」乃自書一榜。榜纔出，八廂邏卒，以為逐舉未嘗有此例，即錄以報主者。士人滿簾前上請，予為逐一剖析，然後退。又靜之與靚，其義一也，而以靜為上聲，靚為去聲。案漢書賈誼服賦「澹虖若深淵之靚」，顏師古註「靚與靜同」。史記正作靜。揚雄甘泉賦「暗暗靚深」，註雲「靚即靜字耳」。今析入兩音，殊為非理。予名雲竹莊之堂曰「賞靜」，取杜詩「賞靜憐雲竹」之句也。守僧居之，頻年三易，有道人指曰：「靜字左傍乃爭字，以故不定疊。」於是撤去元扁，而改為「靚」雲。","sortOrder":15},
  {"id":"s_work_dtbt_75_16","chapterId":"ch_work_dtbt_75","text":"唐臣乞贈祖","sortOrder":16},
  {"id":"s_work_dtbt_75_17","chapterId":"ch_work_dtbt_75","text":"唐世贈典唯一品乃及祖，餘官只贈父耳。而長慶中流澤頗異，白樂天製集有戶部尚書楊於陵，回贈其祖為吏部郎中，祖母崔氏為郡夫人。馬總准製贈亡父，亦請回其祖及祖母。散騎常侍張惟素亦然。非常製也。是時，崔植為相，亦有陳情表雲：「亡父嬰甫，是臣本生；亡伯祐甫，臣今承後。嗣襲雖移，孝心則在。自去年以來，累有慶澤，凡在朝列，再蒙追榮，或有陳乞，皆許回授。臣猥當寵擢，而顯揚之命，獨未及於先人。今請以在身官秩，幷前後合敍勳封，特乞回充追贈。」則知其時一切之製如此。伯兄文惠執政，乞以己合轉官回贈高祖，既已得旨，而為後省封還。固近無此比，且失於考引唐時故事也。","sortOrder":17},
  {"id":"s_work_dtbt_75_18","chapterId":"ch_work_dtbt_75","text":"承習用經語誤","sortOrder":18},
  {"id":"s_work_dtbt_75_19","chapterId":"ch_work_dtbt_75","text":"經傳中事實多有轉相祖述而用，初不考其訓故者，如：邶穀風之詩，為淫新昏棄舊室而作，其詞曰：「宴爾新昏，以我御窮。」宴，安也，言安愛爾之新昏，但以我御窮苦之時，至於富貴則棄我。今人乃以初娶為宴爾，非惟於詩意不合，且又再娶事，豈堪用也。抑之詩曰：「訏謨定命，遠猶辰告。」毛公曰：「訏，大也；謨，謀也；猶，道也；辰，時也。」猶與猷同。鄭箋曰：「猶，圖也，言大謀定命。為天下遠圖庶事，而以歲時告施之，如正月始和布政也。」案此特謂上告下之義，今詞臣乃用於製詔，以屬臣下，而臣下於表章中亦用之，不知其與「入告爾後」之告不侔也。生民之詩曰：「誕彌厥月。」毛公曰：「誕，大也；彌，終也。」鄭箋言：「後稷之在其母，終人道十月而生。」案訓彌為終，其義亦未易曉。至「俾爾彌爾性，似先公酋矣。」既釋彌為終，又曰酋終也，頗涉煩複。生民凡有八誕字「誕寘之隘巷」，「誕寘之平林」，「誕寘之寒冰」，「誕實匍匐」，「誕後稷之穡」，「誕降嘉種」，「誕我祀如何」，若悉以誕為大，於義亦不通。它如「誕先登於岸」之類，新安朱氏以為發語之辭，是已。莆田鄭氏雲：「彌只訓滿，謂滿此月耳。」今稱聖節曰降誕，曰誕節，人相稱曰誕日、誕辰、慶誕，皆為不然。但承習膠固，無由可革，雖東坡公亦雲「仰止誕彌之慶」，未能免俗。書之於此，使子弟後生輩知之。左傳：「王使宰孔賜齊侯胙，齊侯將下拜，孔曰：『天子使孔曰，以伯舅耋老，無下拜。』對曰：『天威不違顏咫尺，敢不下拜。』下拜登受。」謂拜於堂下，而受胙於堂上。今人簡牘謝饋者，輒曰「謹已下拜」，猶未為甚失，若「天威不違顏咫尺」，則上四字為天子設，下三字為人臣設，故註言：「天鑒察不遠，威嚴常在顏面之前。」今士大夫往往於表奏中言違顏，或曰咫顏、咫尺之顏，全與本指爽戾。如用龍顏、聖顏、天顏之類，自無害也。","sortOrder":19},
  {"id":"s_work_dtbt_75_20","chapterId":"ch_work_dtbt_75","text":"長慶表章","sortOrder":20},
  {"id":"s_work_dtbt_75_21","chapterId":"ch_work_dtbt_75","text":"唐自大曆以河北三鎮為悍藩所據，至元和中，田弘正以魏歸國，長慶初王承元、劉總去鎮、幽，於是河北略定。而穆宗以昏君，崔植、杜元穎、王播以庸相，不能建久長之策，輕徙田弘正，以啟王庭湊之亂，繆用張弘靖，以啟朱克融之亂。朝廷以諸道十五萬衆，裴度元臣宿望，烏重嗣、李光顏當時名將，屯守逾年，竟無成功，財竭力盡，遂以節鉞授二賊，再失河朔，訖於唐亡。觀一時事勢，何止可為痛哭！而宰相請上尊號表雲：「陛下自即大位，及此二年，無巾車汗馬之勞，而坐平鎮、冀；無亡弓遺鏃之費，而立定幽燕。以謂威靈四及，請為『神武』。」君臣上下，其亦雲無羞恥矣。此表乃白居易所作。又翰林學士元稹求為宰相，恐裴度復有功大用，妨己進取，多從中沮壞之。度上表極陳其狀，帝不得已解稹翰林，恩遇如故。稹怨度，欲解其兵柄，勸上罷兵。未幾拜相，居易代作謝表，其略雲：「臣遭遇聖明，不因人進，擢居禁內，訪以密謀。恩獎太深，讒謗並至。雖內省行事，無所愧心，然上黷宸聰，合當死責。」其文過飾非如此。居易二表，誠為有玷盛德。","sortOrder":21},
  {"id":"s_work_dtbt_75_22","chapterId":"ch_work_dtbt_75","text":"元白製科","sortOrder":22},
  {"id":"s_work_dtbt_75_23","chapterId":"ch_work_dtbt_75","text":"元、白習製科，其書後分為四卷，命曰策林。其策頭、策項各二道，策尾三道，此外曰美謙遜、塞人望、教必成、不勞而理、風化澆朴、復雍熙、感人心之類，凡七十五門，言所應對者百不用其一二，備載於文集雲。","sortOrder":23},
  {"id":"s_work_dtbt_75_24","chapterId":"ch_work_dtbt_75","text":"八種經典","sortOrder":24},
  {"id":"s_work_dtbt_75_25","chapterId":"ch_work_dtbt_75","text":"開士悟入諸佛知見，以了義度無邊，以圓教垂無窮，莫尊於妙法蓮華經，凡六萬九千五百五字。證無生忍，造不二門，住不可思議解脫，莫極於維摩經，凡二萬七千九十二字。攝四生九類，入無餘湼槃，實無得度者，莫先於金剛般若波羅密經，凡五千二百八十七字。壞罪集福，淨一切惡道，莫急於佛頂尊勝陀羅尼經，凡三千二十字。應念順願，願生極樂土，莫疾於阿彌陀經，凡一千八百字。用正見，觀真相，莫出於觀音普賢菩薩法行經，凡六千九百九十字。詮自性，認本覺，莫深於實相法密經，凡三千一百五字。空法塵，依佛智，莫過於般若波羅密多心經，凡二百五十八字。是八種經典十二部，合一十一萬六千八百五十七字。三乘之要旨，萬佛之祕藏，盡矣。唐長慶三年，蘇州重玄寺法華院石壁所刻金字經，白樂天為作碑文，其敍如此。予竊愛其簡明潔亮，故備錄之。","sortOrder":25},
  {"id":"s_work_dtbt_75_26","chapterId":"ch_work_dtbt_75","text":"容齋五筆","sortOrder":26},
  {"id":"s_work_dtbt_76_1","chapterId":"ch_work_dtbt_76","text":"卷第九(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_76_2","chapterId":"ch_work_dtbt_76","text":"畏人索報書","sortOrder":2},
  {"id":"s_work_dtbt_76_3","chapterId":"ch_work_dtbt_76","text":"士大夫得交朋書問，有懶傲不肯即答者。記白樂天老慵一絕句曰：「豈是交親向我疏，老慵自愛閉門居。近來漸喜知聞斷，免惱嵇康索報書。」案嵇康與山濤絕交書雲：「素不便書，又不喜作書，而人間多事，堆案盈幾，不相酬答，則犯教傷義，欲自勉強，則不能久。」樂天所雲正此也。乃知畏於答書，其來久矣。","sortOrder":3},
  {"id":"s_work_dtbt_76_4","chapterId":"ch_work_dtbt_76","text":"不能忘情吟","sortOrder":4},
  {"id":"s_work_dtbt_76_5","chapterId":"ch_work_dtbt_76","text":"予既書白公鍾情蠻、素於前卷，今復見其不能忘情吟一篇，尤為之感嘆，輒載其文，因以自警。其序雲：「樂天既老，又病風。乃錄家事，會經費，去長物。妓有樊素者，年二十餘，綽綽有歌舞態，善唱楊柳枝，人多以曲名名之，由是名聞洛下，籍在經費中，將放之。馬有駱者，籍在長物中，將鬻之。馬出門，驤首反顧。素聞馬嘶，慘然立且拜，婉孌有辭，辭畢涕下。予亦愍然不能對，且命反袂，飲之酒，自飲一杯，快吟數十聲，聲成文，文無定句。予非聖達，不能忘情，又不至於不及情者，事來攪情，情動不可柅，因自哂，題其篇曰不能忘情吟。」吟曰：「鬻駱馬兮，放楊柳枝。掩翠黛兮，頓金羈。馬不能言兮，長鳴而却顧。楊柳枝再拜長跪而致辭。辭曰：『素事主十年，凡三千有六百日。巾櫛之間，無違無失。今素貌雖陋，未至衰摧。駱力猶壯，又無虺隤。即駱之力，尚可以代主一步，素之歌，亦可以送主一杯。一旦雙去，有去無回。故素將去，其辭也苦，駱將去，其鳴也哀。此人之情也，馬之情也。豈主君獨無情哉？』予俯而嘆，仰而咍，且曰駱駱爾勿嘶，素素爾勿啼，駱反廐，素反閨。吾疾雖作年雖頹，幸未及項籍之將死，亦何必一日之內棄騅兮而別虞兮。乃目素兮，素兮為我歌楊柳枝，我姑酌彼金罍，我與爾歸醉鄉去來。」觀公之文，固以遣情釋意耳，素竟去也。此文在一集最後卷，故讀之者未必記憶。東坡猶以為柳枝不忍去，因劉夢得「春盡絮飛」之句方知之。於是美朝雲之獨留，為之作詩，有「不似楊枝別樂天，恰如通德伴伶玄」之語。然不及二年而病亡，為可嘆也。","sortOrder":5},
  {"id":"s_work_dtbt_76_6","chapterId":"ch_work_dtbt_76","text":"擒鬼章祝文","sortOrder":6},
  {"id":"s_work_dtbt_76_7","chapterId":"ch_work_dtbt_76","text":"東坡在翰林作擒鬼章奏告永裕陵祝文雲：「大獮獲禽，必有指蹤之自。豐年多廩，孰知耘耔之勞？昔漢武命將出師，而呼韓來庭，效於甘露；憲宗厲精講武，而河湟恢復，見於大中。」其意蓋以神宗有平唃氏之志，至於元祐，乃克有成，故告陵歸功，謂武帝、憲宗亦經營於初，而績效在於二宣之世，其用事精切如此。今蘇氏眉山功德寺所刻大小二本，及季真給事在臨安所刻，幷江州本、麻沙書坊大全集，皆只自「耘耔」句下，便接「憬彼西戎，古稱右臂」。正是好處，却芟去之，豈不可惜？唯成都石本法帖真跡，獨得其全。坡集奏議中登州上殿三劄，皆非是。司馬季思知泉州，刻溫公集，有作中丞日彈王安石章，尤可笑。溫公以治平四年解中丞，還翰林，而此章乃熙寧三年者。二集皆出本家子孫，而為妄人所誤，季真、季思不能察耳。坡內製有溫公安葬祭文，雲：「元豐之末，天步為艱。社稷之衞，中外所屬。惟是一老，屏予一人。名高當世，行滿天下。措國於太山之安，下令於流水之源。歲月未周，綱紀略定。天若相之，又復奪之。殄瘁之哀，古今所共。知之者神考，用之者聖母。馴致其道，太平可期。長為宗臣，以表後世。往奠其葬，庶知予懷！」而石本頗不同，其詞雲：「元豐之末，天步惟艱。社稷之衞，存者有幾？惟是一老，屏予一人。措國於太山之安，下令於流水之源。歲未及期，綱紀略定。道之將行，非天而誰？天既予之，又復奪之。惟聖與賢，莫如天何！然其所立，天亦不能亡也。知之者神考，用之者聖母。馴致其道，終於太平。永為宗臣，與國無極。於其葬也，告諸其柩。」今莫能考其所以異也。","sortOrder":7},
  {"id":"s_work_dtbt_76_8","chapterId":"ch_work_dtbt_76","text":"歐公送慧勤詩","sortOrder":8},
  {"id":"s_work_dtbt_76_9","chapterId":"ch_work_dtbt_76","text":"國朝承平之時，四方之人，以趨京邑為喜。蓋士大夫則用功名進取係心，商賈則貪舟車南北之利，後生嬉戲則以紛華盛麗而悅。夷考其實，非南方比也。讀歐陽公送僧慧勤歸餘杭之詩可知矣。曰：「越俗僭宮室，傾貲事雕牆。佛屋尤其侈，耽耽擬侯王。文彩瑩丹漆，四壁金焜煌。上懸百寶蓋，宴坐以方牀。胡為棄不居，棲身客京坊？辛勤營一室，有類燕巢梁。南方精飲食，菌筍比羔羊。飯以玉粒粳，調之甘露漿。一饌費千金，百品羅成行。晨興未飯僧，日昃不敢嘗。乃茲隨北客，枯粟充飢腸。東南地秀絕，山水澄清光。餘杭幾萬家，日夕焚清香。煙霏四面起，雲霧雜芬芳。豈如車馬塵，鬢髮染成霜？三者孰苦樂？子奚勤四方！」觀此詩中所謂吳越宮室、飲食、山水三者之勝，昔日固如是矣。公又有山中之樂三章送之歸。勤後識東坡，為作詩集序者。","sortOrder":9},
  {"id":"s_work_dtbt_76_10","chapterId":"ch_work_dtbt_76","text":"委蛇字之變","sortOrder":10},
  {"id":"s_work_dtbt_76_11","chapterId":"ch_work_dtbt_76","text":"歐公樂郊詩雲：「有山在其東，有水出逶夷。」近歲丁朝佐辨正謂其字參古今之變，必有所據。予因其說而悉索之，此二字凡十二變。一曰委蛇，本於詩羔羊：「退食自公，委蛇委蛇。」毛公註：「行可從跡也。」鄭箋：「委曲自得之貌。委，於危反。蛇音移。」左傳引此句，杜註雲：「順貌。」莊子載齊桓公澤中所見，其名亦同。二曰委佗，詩君子偕老：「委委佗佗。」毛註：「委委者，行可委曲從跡也。佗者，德平易也。」三曰逶迱，韓詩釋上文雲：「公正貌。」說文：「逶迤，斜去貌。」四曰倭遲，詩：「四牡騑騑，周道倭遲。」註：「歷遠之貌。」五曰逶夷，韓詩之文也。六曰威夷，潘嶽詩：「迴溪縈曲阻，峻阪路威夷。」孫綽天台山賦：「既克隮於九折，路威夷而修通。」李善註引韓詩「周道威夷」。薛君曰：「威夷，險也。」七曰委移，離騷經：「載雲旗之委蛇。」一本作「逶迤」，一本作「委移」。註：「雲旗委移，長也。」八曰逶移，劉向九嘆：「遵江曲之逶移。」九曰逶蛇，後漢費鳳碑：「君有逶蛇之節。」十曰蜲蛇，張衡西京賦：「女、娥坐而長歌，聲清暢而蜲蛇。」李善註：「蜲蛇，聲餘詰曲也。」十一曰（辶爲）迆，漢逄盛碑：「當遂（辶爲）迆，立號建基。」十二曰威遲，劉夢得詩：「柳動御溝清，威遲堤上行。」韓公南海廟碑：「蜿蜿蛇蛇」，亦然也。則歐公正用韓詩，朝佐不暇尋繹之爾。","sortOrder":11},
  {"id":"s_work_dtbt_76_12","chapterId":"ch_work_dtbt_76","text":"東不可名園","sortOrder":12},
  {"id":"s_work_dtbt_76_13","chapterId":"ch_work_dtbt_76","text":"今人亭館園池，多即其方隅以命名。如東園、東亭、西池、南館、北榭之類，固為簡雅，然有當避就處。歐陽公作真州東園記，最顯。案漢書百官表：「將作少府，掌治宮室。屬官有東園主章。」註雲：「章謂大材也。主章掌大材，以供東園大匠。」紹興三十年，予為省試參詳官，主司委出詞科題，同院或欲以「東園主章」為箴，予曰：「君但知漢表耳！霍光傳：『光之喪，賜東園溫明。』服虔曰：『東園處此器，以鏡置其中，以懸尸上。』師古曰：『東園，署名也，屬少府。其署主作此器。』董賢傳：『東園祕器以賜賢。』註引漢舊儀東園祕器作棺。若是豈佳處乎？」同院驚謝而退。然則以東名園，是為不可。予有兩園，適居東西，故扁西為西園，而以東為東圃，蓋避此也。","sortOrder":13},
  {"id":"s_work_dtbt_76_14","chapterId":"ch_work_dtbt_76","text":"一二三與壹貳叁同","sortOrder":14},
  {"id":"s_work_dtbt_76_15","chapterId":"ch_work_dtbt_76","text":"古書及漢人用字，如一之與壹，二之與貳，三之與叁，其義皆同。鳲鳩序：「刺不壹也。」又雲：「用心之不壹也。」而正文「其儀一兮」。表記：「節以壹惠。」註：「言聲譽雖有衆多者，節以其行一大善者為謚耳。」漢華山碑：「五載壹巡狩。」祠孔廟碑：「恢崇壹變。」祝睦碑：「非禮，壹不得犯。」而後碑雲：「非禮之常，一不得當。」則與壹通用也。孟子：「市價不貳。」趙岐註雲：「無二賈者也。」本文用大貳字，註用小二字，則二與貳通用也。易繫辭：「參天兩地。」釋文雲：「參，七南反。又如字，音三。」周禮：「設其參。」註：「參，謂卿三人。」則三與參通用也。九之與久，十之與拾，百之與伯亦然。予頃在英州，訪鄰人利秀才。利新作茅齋，頗淨潔，從予乞名。其前有兩高松，因為誦藍田壁記，命之曰「二松」。其季請曰：「是使大貳字否？」坐者皆哂。蓋其人不知書，信口輒言，以貽譏笑。若以古字論之，亦未為失也。文惠公名流杯亭曰「一詠」，而采借隸法，扁為「壹詠」，讀者多以為疑，顧第弗深考耳。","sortOrder":15},
  {"id":"s_work_dtbt_76_16","chapterId":"ch_work_dtbt_76","text":"何恙不已","sortOrder":16},
  {"id":"s_work_dtbt_76_17","chapterId":"ch_work_dtbt_76","text":"公孫弘為丞相，以病歸印，上報曰：「君不幸罹霜露之疾，何恙不已？」顏師古註：「恙，憂也。何憂於疾不止也。」禮部韻略訓恙字，亦曰憂也。初無訓病之義。蓋既雲罹疾矣，不應復雲病，師古之說甚為明白。而世俗相承，至問人病為貴恙，謂輕者為微恙，心疾為心恙，風疾為風恙，根著已深，無由可改。","sortOrder":17},
  {"id":"s_work_dtbt_76_18","chapterId":"ch_work_dtbt_76","text":"兩漢用人人元元字","sortOrder":18},
  {"id":"s_work_dtbt_76_19","chapterId":"ch_work_dtbt_76","text":"前漢書好用人人字，如文帝紀「人人自以為得之者以萬數」，又曰「人人自安難動搖」，元帝紀「人人自以得上意」，食貨志「人人自愛而重犯法」，韓信傳「人人自以為得大將」，曹參傳「齊故諸儒以百數，言人人殊」，張良傳「人人自堅」，叔孫通傳「吏人人奉職」，賈誼傳「人人各如其意所出」，揚雄傳「人人自以為咎繇」，鮑宣傳「人人牽引所私」，韓延壽傳「人人問以謠俗」、「人人為飲」，張騫傳「人人有言輕重」，李尋傳「人人自賢」，王莽傳「人人延問」，嚴安傳「人人自以為更生」，王吉傳「人人自製」是也。後漢書亦間有之，如崔駰傳「人人有以自優」，五行志「人人莫不畏憲」，吳漢傳「諸將人人多請之」，申屠剛傳「人人懷憂」，王允傳「人人自危」，荀彧傳「人人自安」，呂強傳「諸常侍人人求退」是也。又元元二字，考之六經無所見，而兩漢書多用之。如前漢文帝紀「全天下元元之民」，武紀「燭幽隱，勸元元」、「所以化元元」，宣紀「不忘元元」，元紀「元元失望」、「元元何辜」、「元元大困」、「元元之民，勞於耕耘」、「元元騷動」、「元元安所歸命」，成紀「元元冤失職者衆」，哀紀「元元不贍」，刑法志「罹元元之不逮」，嚴安傳「元元黎民，得免於戰國」，嚴助傳「使元元之民，安生樂業」，賈捐之傳「保全元元」，東方朔傳「元元之民，各得其所」，魏相傳「尉安元元」、「唯陛下留神元元」，鮑宣傳「為天牧養元元」，蕭育傳「安元元而已」，匡衡薛宣傳「哀閔元元」，王嘉傳「憂閔元元」，穀永傳「以慰元元之心」，匈奴傳「元元萬民」是也。後漢光武紀「下為元元所歸」、「賊害元元」、「元元愁恨」、「惠茲元元」，章紀「誠欲元元去末歸本」、「元元未諭」、「深元元之愛」，和紀「愛養元元」、「下濟元元」，順紀「元元被害」，質紀「元元嬰此困毒」，桓紀「害及元元」，鄧後紀、劉毅傳「垂恩元元」，王昌傳「元元創痍」，耿弇傳「元元叩心」，郎顗傳「弘濟元元」、「貸贍元元」，曹褒傳「仁濟元元」，范升傳「元元焉所呼天」、「免元元之急」，鍾離意傳「憂念元元」，何敞傳「元元怨恨」、「安濟元元」，楊終傳「以濟元元」，虞詡傳「遭元元無妄之災」，皇甫規傳「平志畢力，以慶元元」是也。予謂元元者，民也。而上文又言元元之民、元元黎民、元元萬民，近於複重矣。故顏註：「或雲，元元，善意也。」","sortOrder":19},
  {"id":"s_work_dtbt_76_20","chapterId":"ch_work_dtbt_76","text":"韓公潮州表","sortOrder":20},
  {"id":"s_work_dtbt_76_21","chapterId":"ch_work_dtbt_76","text":"韓文公諫佛骨表，其詞切直，至雲：「凡有殃咎，宜加臣身，上天監臨，臣不怨悔。」坐此貶潮州刺史。而謝表雲：「臣於當時之文，未有過人者。至論陛下功德，與詩、書相表裏，作為歌詩，薦之郊廟，雖使古人復生，臣亦未肯多遜。而負罪嬰釁，自拘海島，懷痛窮天，死不閉目，伏惟天地父母，哀而憐之。」考韓所言，其意乃望召還。憲宗雖有武功，亦未至編之詩、書而無愧，至於「紀泰山之封，鏤白玉之牒，東巡奏功，明示得意」等語，摧挫獻佞，大與諫表不侔，當時李漢輩編定文集，惜不能為之除去。東坡自黃州量移汝州，上表雲：「伏讀訓詞，有『人材實難，不忍終棄』之語，臣昔在常州，有田粗給饘粥，欲望許令常州居住。輒敍徐州守河及獲妖賊事，庶因功過相除，得從所便。」讀者謂與韓公相類，是不然。二表均為歸命君上，然其情則不同。坡自列往事，皆其實跡，而所乞不過見地耳，且略無一佞詞，真為可服。","sortOrder":21},
  {"id":"s_work_dtbt_76_22","chapterId":"ch_work_dtbt_76","text":"燕賞逢知己","sortOrder":22},
  {"id":"s_work_dtbt_76_23","chapterId":"ch_work_dtbt_76","text":"白樂天為河南尹日，有答舒員外雲：「員外遊香山寺，數日不歸，兼辱尺書，大誇勝事，時正值坐衙慮囚之際，走筆題長句以贈之，曰：『黃菊繁時好客到，碧雲合處佳人來。(謂遣英、蒨二妓與舒君同遊也。)酡顏一笑夭桃綻，清冷秋聲寒玉哀。軒騎逶迤棹容與，留連三日不能回。白頭老尹府中坐，早衙纔退暮衙催。』」謝希深、歐陽公官洛陽，同遊嵩山歸，暮抵龍門香山，雪作，留守錢文僖公遣吏以廚傳歌妓至，且勞之曰：「山行良勞，當少留龍門賞雪，府事簡，無遽歸也。」王定國訪東坡公於彭城，一日，棹小舟與顏長道攜盼、英、卿三子遊泗水，南下百步洪，吹笛飲酒，乘月而來。坡時以事不得往，夜著羽衣，佇立黃樓上，相視而笑，以為李太白死，世間無此樂三百餘年矣。定國既去，逾月，復與參寥師泛舟洪下，追憶曩遊，作詩曰：「輕舟弄水買一笑，醉中蕩槳肩相摩。歸來笛聲滿山穀，明月正照金叵羅。」味此三遊之勝，今之燕賓者寧復有之？蓋亦值知己也。","sortOrder":23},
  {"id":"s_work_dtbt_76_24","chapterId":"ch_work_dtbt_76","text":"端午貼子詞","sortOrder":24},
  {"id":"s_work_dtbt_76_25","chapterId":"ch_work_dtbt_76","text":"唐世五月五日揚州於江心鑄鏡以進，故國朝翰苑撰端午貼子詞，多用其事，然遣詞命意，工拙不同。王禹玉雲：「紫閤曈曨隱曉霞，瑤墀九御薦菖華。何時又進江心鑑，試與君王却衆邪。」李邦直雲：「艾葉成人後，榴花結子初。江心新得鏡，龍瑞護仙居。」趙彥若雲：「揚子江中方鑄鏡，未央宮裏更飛符。菱花欲共朱靈合，驅盡神奸又得無？」又「揚子江中百煉金，寶奩疑是月華沉。爭如聖後無私鑑，明照人間萬善心。」又「江心百煉青銅鏡，架上雙紉翠縷衣。」李士美雲：「何須百煉鑑，自勝五兵符。」傅墨卿雲：「百煉鑑從江上鑄，五時花向帳前施。」許冲元雲：「江中今日成龍鑑，苑外多年廢鷺陂。合照乾坤共作鏡，放生河海盡為池。」蘇子由雲：「揚子江中寫鏡龍，波如細縠不搖風。宮中驚捧秋天月，長照人間助至公。」大概如此。唯東坡不然，曰：「講餘交翟轉回廊，始覺深宮夏日長。揚子江心空百煉，只將無逸監興亡。」其輝光氣燄，可畏而仰也。若白樂天諷諫百煉鏡篇雲：「江心波上舟中鑄，五月五日日午時。」「背有九五飛天龍，人人呼為天子鏡。」又雲：「太宗常以人為鏡，監古監今不監容。」「乃知天子別有鏡，不是揚州百煉銅。」用意正與坡合。予亦嘗有一聯雲：「願儲醫國三年艾，不博江心百煉銅。」然去之遠矣。端午故事，莫如楚人競渡之的，蓋以其非吉祥，不可施諸祝頌，故必用鏡事雲。","sortOrder":25},
  {"id":"s_work_dtbt_76_26","chapterId":"ch_work_dtbt_76","text":"容齋五筆","sortOrder":26},
  {"id":"s_work_dtbt_77_1","chapterId":"ch_work_dtbt_77","text":"卷第十(十二則)","sortOrder":1},
  {"id":"s_work_dtbt_77_2","chapterId":"ch_work_dtbt_77","text":"哀公問社","sortOrder":2},
  {"id":"s_work_dtbt_77_3","chapterId":"ch_work_dtbt_77","text":"哀公問社於宰我，宰我對曰：「夏後以松，殷人以柏，周人以栗。」曰：「使民戰栗。」子聞之曰：「成事不說，遂事不諫，既往不咎。」古人立社，但各因其土地所宜木為之，初非求異而取義於彼也。哀公本不必致問，既聞用栗之言，遂起「使民戰栗」之語。其意謂古者弗用命戮於社，所以威民。然其實則非也。孔子責宰我不能因事獻可替否，既非成事，尚為可說，又非遂事，尚為可諫，且非既往，何咎之雲。或謂「使民戰栗」一句，亦出於宰我，記之者欲與前言有別，故加「曰」字以起之，亦是一說。然戰栗之對，使出於我，則導君於猛，顯為非宜。出於哀公，則便即時正救，以杜其始。兩者皆失之，無所逃於聖人之責也。哀公欲以越伐魯而去三家，不克成，卒為所逐，以至失邦，其源蓋在於此。何休註公羊傳雲：「松，猶容也，想見其容貌而事之，主人正之意也。柏，猶迫也，親而不遠，主地正之意也。栗猶戰栗，謹敬貌，主天正之意也。」然則戰栗之說，亦有所本。公羊雲：「虞主用桑，練主用栗。」則三代所奉社，其亦以松、柏、栗為神之主乎？非植此木也。程伊川之說有之。","sortOrder":3},
  {"id":"s_work_dtbt_77_4","chapterId":"ch_work_dtbt_77","text":"絕句詩不貫穿","sortOrder":4},
  {"id":"s_work_dtbt_77_5","chapterId":"ch_work_dtbt_77","text":"「夜涼吹笛千山月，路暗迷人百種花。棋罷不知人換世，酒闌無奈客思家。」此歐陽公絕妙之語。然以四句各一事，似不相貫穿，故名之曰夢中作。永嘉士人薛韶喜論詩，嘗立一說雲：老杜近體律詩，精深妥帖，雖多至百韻，亦首尾相應，如常山之蛇，無間斷齟齬處。而絕句乃或不然，五言如「遲日江山麗，春風花草香。泥融飛燕子，沙暖睡鴛鴦」，「急雨捎溪足，斜暉轉樹腰。隔巢黃鳥並，翻藻白魚跳」，「江動月移石，溪虛雲傍花。鳥棲知故道，帆過宿誰家」，「鑿井交棕葉，開渠斷竹根。扁舟輕褭纜，小徑曲通村」，「日出籬東水，雲生舍北泥。竹高鳴翡翠，沙僻舞鵾鷄」，「釣艇收緡盡，昏鴉接翅稀。月生初學扇，雲細不成衣」，「舍下筍穿壁，庭中藤刺簷。地晴絲冉冉，江白草纖纖」，七言如「糝徑楊花鋪白氈，點溪荷葉疊青錢。筍根雉子無人見，沙上鳧雛傍母眠」，「兩個黃鸝鳴翠柳，一行白鷺上青天。窗含西嶺千秋雪，門泊東吳萬里船」之類是也。予因其說，以唐人萬絕句考之，但有司空圖雜題雲「驛步堤縈閣，軍城鼓振橋。鷗和湖雁下，雪隔嶺梅飄」，「舴艋猿偷上，蜻蜓燕競飛。樵香燒桂子，苔濕掛莎衣」。","sortOrder":5},
  {"id":"s_work_dtbt_77_6","chapterId":"ch_work_dtbt_77","text":"農父田翁詩","sortOrder":6},
  {"id":"s_work_dtbt_77_7","chapterId":"ch_work_dtbt_77","text":"張碧農父詩雲：「運鋤耕斸侵晨起，隴畔豐盈滿家喜。到頭禾黍屬他人，不知何處拋妻子！」杜荀鶴田翁詩雲：「白髮星星筋骨衰，種田猶自伴孫兒。官苗若不平平納，任是豐年也受飢！」讀之使人愴然，以今觀之，何啻倍蓰也！","sortOrder":7},
  {"id":"s_work_dtbt_77_8","chapterId":"ch_work_dtbt_77","text":"衛宣公二子","sortOrder":8},
  {"id":"s_work_dtbt_77_9","chapterId":"ch_work_dtbt_77","text":"衞宣公二子之事，詩與左傳所書，始末甚詳，乘舟之詩，為伋、壽而作也。左傳雲：「宣公烝於庶母夷薑，生伋子。為之娶於齊而美，公取之，生壽及朔。宣薑與公子朔譖伋子。宣薑者，宣公所納伋之妻，翻譖其過。公使諸齊，使盜待諸莘，將殺之。壽子告之，使行，不可。壽子載其旌以先，盜殺之，遂兄弟幷命。」案宣公以魯隱四年十二月立，至桓十二年十一月卒，凡十有九年。姑以即位之始，便成烝亂，而伋子即以次年生，勢須十五歲然後娶。既娶而奪之，又生壽、朔，朔已能同母譖兄，壽又能代為使者以越境，非十歲以下兒所能辦也。然則十九年之間，如何消破？此最為難曉也。","sortOrder":9},
  {"id":"s_work_dtbt_77_10","chapterId":"ch_work_dtbt_77","text":"謂端為匹","sortOrder":10},
  {"id":"s_work_dtbt_77_11","chapterId":"ch_work_dtbt_77","text":"今人謂縑帛一匹為壹端，或總言端匹。案左傳「幣錦二兩」註雲：「二丈為一端，二端為一兩，所謂匹也，二兩，二匹也。」然則以端為匹非矣。湘山野錄載夏英公鎮襄陽，遇大禮赦恩，賜致仕官束帛，以絹十匹與胡旦，旦笑曰：「奉還五匹，請檢韓詩外傳，及諸儒韓康伯等所解『束帛戔戔』之義，自可見證。」英公檢之，果見三代束帛、束脩之製。若束帛則卷其帛為二端，五匹遂見十端，正合此說也。然周易正義及王弼註、韓詩外傳皆無其語。文瑩多妄誕，不足取信。按春秋公羊傳「乘馬束帛」註雲：「束帛謂玄三纁二，玄三法天，纁二法地。」若文瑩以此為證，猶之可也。","sortOrder":11},
  {"id":"s_work_dtbt_77_12","chapterId":"ch_work_dtbt_77","text":"唐人草堂詩句","sortOrder":12},
  {"id":"s_work_dtbt_77_13","chapterId":"ch_work_dtbt_77","text":"予於東圃作草堂，欲採唐人詩句書之壁而未暇也，姑錄之於此。杜公雲：「西郊向草堂」，「昔我去草堂」，「草堂少花今欲栽」，「草堂塹西無樹林」。白公有別草堂三絕句，又雲：「身出草堂心不出。」劉夢得傷愚溪雲：「草堂無主燕飛回。」元微之和裴校書雲：「清江見底草堂在。」錢起有暮春歸故山草堂詩，又雲：「暗歸草堂靜，半入花源去。」朱慶餘：「稱著朱衣入草堂。」李涉：「草堂曾與雪為鄰。」顧況：「不作草堂招遠客。」郎士元：「草堂竹徑在何處？」張籍：「草堂雪夜攜琴宿。」又雲：「西峯月猶在，遙憶草堂前。」武元衡：「多君能寂寞，共作草堂遊。」陸龜蒙：「草堂祗待新秋景。」又雲：「草堂盡日留僧坐。」司空圖：「草堂舊隱猶招我。」韋莊：「今來空訝草堂新。」子蘭：「策杖吟詩上草堂。」皎然有題湖上草堂雲：「山居不買剡中山，湖上千峯處處閑。芳草白雲留我住，世人何事得相關？」","sortOrder":13},
  {"id":"s_work_dtbt_77_14","chapterId":"ch_work_dtbt_77","text":"公穀解經書日","sortOrder":14},
  {"id":"s_work_dtbt_77_15","chapterId":"ch_work_dtbt_77","text":"孔子作春秋，以一字為褒貶，大抵志在尊王，至於紀年敍事，只因舊史。杜預見汲冢書魏國史記，謂「其著書文意大似春秋經，推此足以見古者國史策書之常也。」所謂書日不書日，在輕重事體本無所系，而公羊、穀梁二傳，每事斷之以日，故窒而不通。左氏惟有公子益師卒，「公不與小斂，故不書日」一說，其它亦鮮。今表二傳之語，以示兒曹。公羊雲：「益師卒，何以不日？遠也。」「葬者不及時而日，渴葬也。不及時而不日，慢葬也。過時而日，隱之也。過時而不日，謂之不能葬也。當時而不日，正也。當時而日，危不得葬也。」「庚寅，入邴。其日何？難也。」「取邑不日。」「桓之盟不日，信之也。」「甲寅，齊人伐衞。伐不日，此何以日？至之日也。」「壬申，公朝於王所。其日何？錄乎內也。」「辛巳，晉敗秦於殽。詐戰不日，此何以日？盡也。」「甲戌，敗狄於鹹。其日何？大之也。」「子卒。何以不日？隱之也。」「即位不日。」穀梁最多：「卑者之盟，不日。」「大夫日卒，正也。」「諸侯日卒，正也。」「日入，惡入者也。」「外盟不日。」「取邑不日。」「大閱崇武，故謹而日之。」「前定之盟，不日。」「公敗齊師。不日，疑戰也。」「公敗宋師。其日，成敗之也。」「齊人滅遂。其不日，微國也。」「公會齊侯，盟於柯，桓盟雖內與，不日，信也。」「媵陳人之婦。其不日，數渝，惡之也。」「癸亥，葬紀叔姬，不日卒，而日葬，閔紀之亡也。」「子卒日，正也。不日，故也。有所見則日。」「戊辰，盟於葵丘。桓盟不日，此何以日？美之也。」「辛卯，沙鹿崩。其日，重變也。」「戊申，隕石於宋。是月，六鷁退飛。石無知，故日之。鷁微有知之物，故月之。」「乙亥，齊侯小白卒。此不正，其日之，何也？」「壬申，公朝於王所。其日，以其再致天子，故謹而日之。日繫於月，月繫於時。其不月，失其所繫也。」「丁未，商臣弒其君髠。日髠之卒，所以謹商臣之弒也。」「乙巳，及晉處父盟。不言公，諱也。何以知其與公盟？以其日也。」「甲戌，取須句。取邑不日，此其日，何也？不正其再取，故謹而日之也。」「辛丑，葬襄王。日之，甚矣，其不葬之辭也。」「乙卯，晉、楚戰於邲。日，其事敗也。」「癸卯，晉滅潞。滅國有三術：中國謹日，卑國月，夷狄不日。其日，潞子賢也。」「甲戌，楚子卒。夷狄卒而不日。日，少進也。」「癸酉，戰於鞌。其日，或曰日其戰也，或曰日其悉也。」「梁山崩。不日。何也？高者有崩道也。」「鼷鼠食郊牛角。不言日，急辭也。」「庚申，莒潰。惡之，故謹而日之也。」「秋，公至自會。不日，至自伐鄭也。」「丙戌，鄭伯卒於操。其日，未逾竟也。」「乙亥，臧孫紇出奔邾。其日，正紇之出也。」「蔡世子弒其君。其不日，子奪父政，是謂夷之。」「冬十月，葬蔡景公。不日卒而月葬，不葬者也。」「四月，楚公子比弒其君。弒君者日，不日，比不弒也。」「甲戌，同盟於平丘。其日，善是盟也。」「內之大事日。即位，君之大事也。其不日，何也？以年决者，不以日决也。定之即位，何以日也？著之也。」它釋時月者亦然，通經之士，可以默喻矣。沙鹿、梁山為兩說，尤不然。蘇子由春秋論雲：「公羊、穀梁之傳，日月土地，皆所以為訓。夫日月之不知，土地之不詳，何足以為喜怒？」其意蓋亦如此。","sortOrder":15},
  {"id":"s_work_dtbt_77_16","chapterId":"ch_work_dtbt_77","text":"柳應辰押字","sortOrder":16},
  {"id":"s_work_dtbt_77_17","chapterId":"ch_work_dtbt_77","text":"予頃因見鄂州南樓土中磨崖碑，其一刻「柳」字，下一字不可識，後訪得其人名應辰，而雲是唐末五代時湖北人也，既載之四筆中，今始究其實，柳之名是已。蓋以國朝寶元元年呂溱榜登甲科，今浯溪石上有大押字，題雲：「押字起於心，心之所記，人不能知。大宋熙寧七年甲寅歲刻，尚書都官員外郎武陵柳應辰，時為永州通判。」仍有詩雲：「浯溪石在大江邊，心記閑將此地鐫。自有後人來屈指，四千六百甲寅年。」有閬中陳思者跋雲：「右柳都官欲以怪取名，所至留押字盈丈，莫知其何為。押字古人書名之草者，施於文記間，以自別識耳。今應辰鐫刻廣博如許，已怪矣。好事者從而為之說，謂能祛逐不祥，真大可笑。」予得此帖，乃恨前疑之非。石傍又有蔣世基述夢記雲：「至和三年八月，知永州職方員外郎柳拱辰受代歸闕，祁陽縣令齊術送行至白水，夢一儒衣冠者曰：『我元結也，今柳公遊浯溪，無詩而去，子盍求之。』覺而心異之，遂獻一詩。柳依韻而和，其語不工。」拱辰以天聖八年王拱辰榜登科，殆應辰兄也，輒幷記之。","sortOrder":17},
  {"id":"s_work_dtbt_77_18","chapterId":"ch_work_dtbt_77","text":"唐堯無後","sortOrder":18},
  {"id":"s_work_dtbt_77_19","chapterId":"ch_work_dtbt_77","text":"堯、舜之子，不肖等耳。舜之後雖不有天下，而傳至於陳及田齊，幾二千載。惟堯之後，當舜在位時即絕，故禹之戒舜曰：「毋若丹朱傲，用殄厥世。」又作戒曰：「惟彼陶唐，有此冀方。今失厥道，亂其紀綱，乃底滅亡。」原丹朱之惡，固在所絕。方舜、禹之世，顧不能別訪賢冑為之立繼乎？左傳載子產之辭曰：「唐人是因，以服事夏、商，其季世曰唐叔虞。(謂唐人之季，非周武王子封於晉者。)成王滅唐而封太叔。」又蔡墨曰：「陶唐氏既衰，其後有劉累氏，曰御龍。」范宣子曰：「匄之祖，自虞以上為陶唐氏，在夏御龍氏。」然則封國雖絕，尚有子孫。武王滅商，封帝堯之後於薊，而未嘗一見於簡策。史趙言楚之滅陳曰：「盛德必百世祀，虞之世數，未也。」臧文仲聞蓼與六二國亡，曰：「皋陶庭堅不祀，忽諸！」堯之盛德，豈出舜、皋之下，而爵邑不能及孫，何也？","sortOrder":19},
  {"id":"s_work_dtbt_77_20","chapterId":"ch_work_dtbt_77","text":"斯須之敬","sortOrder":20},
  {"id":"s_work_dtbt_77_21","chapterId":"ch_work_dtbt_77","text":"今公私宴會，稱與主人對席者曰席面。古者謂之賓、謂之客是已。儀禮燕禮篇：「射人請賓，公曰：『命某為賓。』賓少進，禮辭。又命之，賓許諾。」左傳季氏飲大夫酒，臧紇為客。宋公兼享晉、楚之大夫，趙孟為客。杜預雲：「客，一坐所尊也。」乾道二年十一月，薛季益以權工部侍郎受命使金國，侍從共餞之於吏部尚書廳，陳應求主席，自六部長貳之外，兩省官皆預，凡會者十二人。薛在部位最下，應求揖之為客，辭不就，曰：「常時固自有次第，奈何今日不然？」諸公言：「此席正為侍郎設，何辭之為？」薛終不可。予時為右史，最居末坐。給事中王日嚴目予曰：「景盧能倉卒間應對，願出一轉語折衷之。」予笑謂薛曰：「孟子不雲乎？『庸敬在兄，斯須之敬在鄉人。』侍郎姑處斯須之敬可也。明日以往，不妨復如常時。」薛無以對，諸公皆稱善，遂就席。","sortOrder":21},
  {"id":"s_work_dtbt_77_22","chapterId":"ch_work_dtbt_77","text":"丙午丁未","sortOrder":22},
  {"id":"s_work_dtbt_77_23","chapterId":"ch_work_dtbt_77","text":"丙午、丁未之歲，中國遇此輒有變故，非禍生於內，則夷狄外侮。三代遠矣，姑摭漢以來言之。高祖以丙午崩，權歸呂氏，幾覆劉宗。武帝元光元年為丁未，長星見，蚩尤旗亘天，其春，戾太子生，始命將出征匈奴，自是之後，師行三十年，屠夷死滅，不可勝數，及於巫蠱之禍，太子子父皆敗。昭帝元平元年丁未，帝崩，昌邑立而復廢，一歲再易主。成帝永始二年、三年，為丙午、丁未，王氏方盛，封莽為新都侯，立趙飛燕為皇後，由是國統三絕，漢業遂頹，雖光武建武之時，海內無事，然勾引南匈奴，稔成劉淵亂華之釁，正是歲也。殤帝、安帝之立，值此二年，東漢政亂，實基於此。桓帝終於永康丁未，孝靈繼之，漢室滅矣。魏文帝以黃初丙午終，明帝嗣位，司馬氏奪國，兆於此時。晉武太康六年、七年，惠帝正在東宮，五胡毒亂，此其源也。東晉訖隋，南北分裂，九縣飈回，在所不論。唐太宗貞觀之季，武氏已在後宮，中宗神龍、景龍，其事可見。代宗大曆元、二，大盜初平，而置其餘孽於河北，強藩悍鎮，卒以亡唐。寶曆丙午，敬宗遇弒。大和丁未，是為文宗甘露之悲，至於不可救藥。僖宗光啟之際，天下固已大亂，而中官劫幸興元，襄王熅僭立。石晉開運，遺禍至今。皇朝景德，方脫契丹之擾，而明年祥符，神仙宮觀之役崇熾，海內虛耗。治平丁未，王安石入朝，愲亂宗社。靖康丙午，都城受圍，逮於丁未，汴失守矣。淳熙丁未，高宗上仙。總而言之，大抵丁未之災，又慘於丙午，昭昭天象，見於運行，非人力之所能為也。","sortOrder":23},
  {"id":"s_work_dtbt_77_24","chapterId":"ch_work_dtbt_77","text":"祖宗命相","sortOrder":24},
  {"id":"s_work_dtbt_77_25","chapterId":"ch_work_dtbt_77","text":"祖宗進用宰相，惟意所屬，初不以內外高卑為主。若召故相，則率置諸見當國者之上，太平興國中，薛文惠公居正薨，盧多遜、沈倫在相位，而趙韓王普以太子太保散秩而拜昭文。鹹平四年，李文靖公沆為集賢，而召故相呂文穆公蒙正為昭文。景德元年，文靖薨，王文正公旦、文穆公欽若為參政，不次補，而畢文簡公士安由侍讀學士、寇忠愍公準由三司使，並命為史館集賢，畢公雖歷參政，不及一月。至和二年，陳恭公執中罷，劉沆在位，而外召文、富二公，文公復為昭文，富為集賢，而沆遷史館。熙寧三年，韓獻肅公絳、王荊公安石同拜，韓在上而先罷，荊公越四年亦罷。韓復為館相，明年荊公再入，遂拜昭文，居韓之上。元祐元年，召文潞公於洛，司馬公自門下侍郎，拜左僕射，固辭，乞令彥博以太師兼侍中行左僕射，而己為右以佐之。宣仁不許，曰：「彥博豈可居卿上？」欲命兼侍中行右僕射，會臺諫有言，彥博不可居三省長官，於是但平章軍國重事。崇寧以後，蔡京凡四入，輒為首臺。此非可論典故也。隆興元年冬，湯岐公思退為右僕射，張魏公浚為樞密使，孝宗欲命張為左，請於德壽，高宗曰：「湯思退元是左相，張浚元是右相，只仍其舊可也。」於是出命。","sortOrder":25},
];

